-- Golden Oremar application schema baseline.
-- Generated by scripts/schema/build-baseline.mjs from the live catalogue (export date in commit).
-- Recreates public, private, api_internal and api_public_bridge exactly; no rows.
-- Needs what a Supabase project already has: auth, storage, vault, cron, net,
-- the extensions schema (pgcrypto, pg_trgm, uuid-ossp) and the API roles.
-- Do not edit by hand: regenerate, then prove it with compare-catalog.mjs.

set check_function_bodies = off;
set client_min_messages = warning;
set search_path = "$user", public, extensions;

-- Schemas
create schema if not exists public;
comment on schema public is 'standard public schema';
create schema if not exists private;
create schema if not exists api_internal;
create schema if not exists api_public_bridge;

-- Sequences
create sequence if not exists public.order_number_seq as bigint increment by 1 minvalue 1 start with 1001 cache 1;
create sequence if not exists private.store_number_seq as bigint increment by 1 minvalue 1 start with 1 cache 1;

