CREATE OR REPLACE FUNCTION public.get_event_refund_context_for_service_v1(p_requester_id uuid, p_reservation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  f private.event_reservation_finance%rowtype;
  r public.event_reservations%rowtype;
  i private.payment_intents%rowtype;
  requester_can_execute boolean:=false;
  transaction_id text;
begin
  if auth.role()<>'service_role' then raise exception 'service_role_required' using errcode='42501'; end if;
  if p_requester_id is null or p_reservation_id is null then raise exception 'refund_context_required' using errcode='22023'; end if;
  requester_can_execute:=private.user_has_permission_v1(p_requester_id,'refund.execute');
  select * into r from public.event_reservations where id=p_reservation_id;
  select * into f from private.event_reservation_finance where reservation_id=p_reservation_id;
  if r.id is null or f.reservation_id is null then raise exception 'event_refund_context_not_found' using errcode='P0002'; end if;
  if r.user_id<>p_requester_id and not requester_can_execute then raise exception 'refund_not_allowed' using errcode='42501'; end if;
  if f.payment_status='refunded' then return jsonb_build_object('reservationId',r.id,'userId',r.user_id,'status','refunded','amountMinor',f.total_minor,'currency',f.currency,'attemptCount',f.refund_attempt_count); end if;
  if f.payment_status<>'refund_required' or f.provider<>'iyzico' or f.provider_reference is null then raise exception 'event_refund_not_required' using errcode='55000'; end if;
  select * into i from private.payment_intents where subject_type='event_reservation' and subject_id=r.id and status='captured' and provider='iyzico' order by created_at desc limit 1;
  if i.id is null then raise exception 'refund_payment_intent_not_found' using errcode='P0002'; end if;
  select nullif(x->>'paymentTransactionId','') into transaction_id from jsonb_array_elements(case when jsonb_typeof(i.provider_result->'itemTransactions')='array' then i.provider_result->'itemTransactions' else '[]'::jsonb end) x where nullif(x->>'paymentTransactionId','') is not null limit 1;
  if transaction_id is null then raise exception 'refund_transaction_id_missing' using errcode='55000'; end if;
  return jsonb_build_object('reservationId',r.id,'userId',r.user_id,'eventId',r.event_id,'intentId',i.id,'provider','iyzico','providerReference',f.provider_reference,'paymentTransactionId',transaction_id,'amountMinor',f.total_minor,'currency',f.currency,'attemptCount',f.refund_attempt_count,'lastError',f.last_refund_error,'lastAttemptAt',f.last_refund_attempt_at,'requesterCanExecuteRefund',requester_can_execute,'requesterIsSuperAdmin',private.user_has_permission_v1(p_requester_id,'role.manage'));
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_event_reservation_payment_state_for_service_v1(p_user_id uuid, p_reservation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.event_reservations%rowtype; f private.event_reservation_finance%rowtype; e public.events%rowtype;
begin
 if auth.role()<>'service_role' then raise exception 'service_role_required' using errcode='42501'; end if;
 if p_user_id is null or p_reservation_id is null then raise exception 'payment_context_required' using errcode='22023'; end if;
 select * into r from public.event_reservations where id=p_reservation_id and user_id=p_user_id;
 if r.id is null then raise exception 'event_reservation_not_found' using errcode='P0002'; end if;
 select * into e from public.events where id=r.event_id;
 select * into f from private.event_reservation_finance where reservation_id=r.id;
 return jsonb_build_object(
  'reservationId',r.id,'reservationCode',r.reservation_code,'reservationStatus',case when r.status='pending_payment' and f.payment_status='pending' and f.payment_expires_at<=timezone('utc',now()) then 'cancelled' else r.status end,
  'eventId',r.event_id,'eventTitle',e.title,
  'payment',case when f.reservation_id is null then jsonb_build_object('status','not_required','requiresPayment',false,'amountMinor',0,'currency',e.currency,'expiresAt',null)
    else jsonb_build_object('status',case when f.payment_status='pending' and f.payment_expires_at<=timezone('utc',now()) then 'expired' else f.payment_status end,'requiresPayment',f.payment_status='pending' and f.payment_expires_at>timezone('utc',now()),'amountMinor',f.total_minor,'currency',f.currency,'expiresAt',f.payment_expires_at) end
 );
end;$function$;

CREATE OR REPLACE FUNCTION public.get_hosted_payment_intent_for_service_v1(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare intent private.payment_intents%rowtype; context jsonb;
begin
 if auth.role()<>'service_role' then raise exception 'service_role_required' using errcode='42501'; end if;
 if p_token is null or char_length(btrim(p_token)) not between 8 and 500 then raise exception 'invalid_checkout_token' using errcode='22023'; end if;
 select * into intent from private.payment_intents where provider_session_token=btrim(p_token) order by created_at desc limit 1;
 if intent.id is null or intent.payment_flow<>'checkout_form' then raise exception 'hosted_payment_intent_not_found' using errcode='P0002'; end if;
 context:=private.get_payment_intent_for_service_v1(intent.id);
 return context||jsonb_build_object('providerSessionToken',intent.provider_session_token,'providerSnapshot',intent.provider_result,'clientIp',intent.client_ip::text);
end;$function$;

