CREATE OR REPLACE FUNCTION public.preview_my_checkout_v1(p_country_code text DEFAULT 'TR'::text, p_coupon_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare base jsonb; readiness jsonb;
begin
  base:=private.preview_my_checkout_v1(p_country_code,p_coupon_code);
  readiness:=private.commercial_checkout_legal_readiness_v1();
  base:=base||jsonb_build_object('legalReadiness',readiness);
  if coalesce((base->>'canCheckout')::boolean,false) and not coalesce((readiness->>'ready')::boolean,false) then
    base:=jsonb_set(base,'{canCheckout}','false'::jsonb,true);
    base:=jsonb_set(base,'{blockingReason}',to_jsonb('business_legal_identity_incomplete'::text),true);
  end if;
  return base;
end;
$function$;

CREATE OR REPLACE FUNCTION private.accept_current_terms_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
