CREATE OR REPLACE FUNCTION private.admin_archive_platform_user_v1(p_user_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  normalized_reason text := btrim(coalesce(p_reason, ''));
  caller_is_super_admin boolean;
  target_is_super_admin boolean;
begin
  if caller_id is null or not coalesce(private.has_permission('user.erase'),false) then
    raise exception 'admin_required' using errcode = '42501';
  end if;
  if p_user_id is null or char_length(normalized_reason) not between 8 and 500 then
    raise exception 'archive_reason_required' using errcode = '22023';
  end if;
  if p_user_id = caller_id then
    raise exception 'cannot_archive_current_user' using errcode = '42501';
  end if;

  caller_is_super_admin := coalesce(private.has_permission('role.manage'), false);
  select exists (
    select 1
    from private.user_roles role
    where role.user_id = p_user_id
      and role.role = 'super_admin'
      and (role.expires_at is null or role.expires_at > timezone('utc', now()))
  ) into target_is_super_admin;
  if target_is_super_admin and not caller_is_super_admin then
    raise exception 'super_admin_required' using errcode = '42501';
  end if;

  update public.profiles
  set status = 'deleted',
      deleted_at = timezone('utc', now()),
      marketing_consent = false,
      marketing_consent_at = null
  where id = p_user_id;

  if not found then
    raise exception 'user_not_found' using errcode = 'P0002';
  end if;

  delete from private.user_roles
  where user_id = p_user_id
    and role <> 'customer';

  update public.producers
  set status = 'suspended'
  where owner_user_id = p_user_id
    and status = 'active'
    and deleted_at is null;

  return jsonb_build_object(
    'id', p_user_id,
    'status', 'deleted',
    'reason', normalized_reason,
    'archivedAt', timezone('utc', now())
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_broadcast_notification_v1(p_target_scope text, p_user_id uuid, p_title text, p_message text, p_type text, p_action_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  scope text := lower(btrim(coalesce(p_target_scope,'')));
  normalized_title text := btrim(coalesce(p_title,''));
  normalized_message text := btrim(coalesce(p_message,''));
  normalized_type text := lower(btrim(coalesce(p_type,'system')));
  broadcast_id uuid := gen_random_uuid();
  inserted_count integer := 0;
begin
  if caller_id is null or not private.has_permission('notification.send') then
    raise exception 'admin_required' using errcode='42501';
  end if;
  if scope not in ('all','producer','specific') then
    raise exception 'invalid_notification_target_scope' using errcode='22023';
  end if;
  if scope='specific' and p_user_id is null then
    raise exception 'notification_target_user_required' using errcode='22023';
  end if;
  if char_length(normalized_title) not between 2 and 160 or char_length(normalized_message) not between 2 and 5000 then
    raise exception 'invalid_notification_content' using errcode='22023';
  end if;
  if normalized_type not in ('order','payment','shipment','return','campaign','system','producer') then
    raise exception 'invalid_notification_type' using errcode='22023';
  end if;
  if char_length(coalesce(p_action_url,'')) > 2048 then
    raise exception 'invalid_action_url' using errcode='22023';
  end if;

  insert into public.notifications(user_id,type,title,message,action_url,metadata)
  select audience.user_id, normalized_type, normalized_title, normalized_message,
         nullif(btrim(coalesce(p_action_url,'')),''),
         jsonb_build_object('createdBy',caller_id,'broadcastId',broadcast_id,'targetScope',scope)
  from (
    select p.id as user_id
    from public.profiles p
    where scope='all' and p.status='active' and p.deleted_at is null
    union
    select producer.owner_user_id
    from public.producers producer
    join public.profiles profile on profile.id=producer.owner_user_id
    where scope='producer' and producer.deleted_at is null and producer.status='active'
      and profile.status='active' and profile.deleted_at is null
    union
    select p.id
    from public.profiles p
    where scope='specific' and p.id=p_user_id and p.status='active' and p.deleted_at is null
  ) audience;

  get diagnostics inserted_count = row_count;
  if inserted_count = 0 then
    raise exception 'notification_audience_empty' using errcode='P0002';
  end if;

  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
  values('notification_broadcast',broadcast_id,'notification.broadcast_created',jsonb_build_object(
    'broadcast_id',broadcast_id,'target_scope',scope,'recipient_count',inserted_count,'type',normalized_type,'actor_user_id',caller_id
  ));

  return jsonb_build_object('broadcastId',broadcast_id,'recipientCount',inserted_count,'type',normalized_type,'targetScope',scope);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_create_platform_notification_v1(p_user_id uuid, p_title text, p_message text, p_type text, p_action_url text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  normalized_title text := btrim(coalesce(p_title, ''));
  normalized_message text := btrim(coalesce(p_message, ''));
  normalized_type text := lower(btrim(coalesce(p_type, 'system')));
  notification_id uuid;
begin
  if caller_id is null or not coalesce(private.has_permission('notification.send'),false) then
    raise exception 'admin_required' using errcode = '42501';
  end if;
  if p_user_id is null or not exists (select 1 from public.profiles profile where profile.id = p_user_id) then
    raise exception 'user_not_found' using errcode = 'P0002';
  end if;
  if char_length(normalized_title) not between 2 and 160
    or char_length(normalized_message) not between 2 and 5000 then
    raise exception 'invalid_notification_content' using errcode = '22023';
  end if;
  if normalized_type not in ('order', 'payment', 'shipment', 'return', 'campaign', 'system', 'producer') then
    raise exception 'invalid_notification_type' using errcode = '22023';
  end if;
  if char_length(coalesce(p_action_url, '')) > 2048 then
    raise exception 'invalid_action_url' using errcode = '22023';
  end if;

  insert into public.notifications(user_id, type, title, message, action_url, metadata)
  values (
    p_user_id,
    normalized_type,
    normalized_title,
    normalized_message,
    nullif(btrim(coalesce(p_action_url, '')), ''),
    jsonb_build_object('createdBy', caller_id)
  )
  returning id into notification_id;

  return notification_id;
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_enforce_platform_user_v1(p_user_id uuid, p_action text, p_reason text, p_block_known_ips boolean DEFAULT false, p_block_known_devices boolean DEFAULT false, p_fraud_flag boolean DEFAULT false, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); action_value text:=lower(btrim(coalesce(p_action,''))); reason_value text:=btrim(coalesce(p_reason,'')); caller_super boolean; target_super boolean; target_admin boolean; target public.profiles%rowtype; producer public.producers%rowtype; rule_count integer:=0; ctx record;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if; if action_value='block' and not private.has_permission('user.suspend') then raise exception 'permission_required:user.suspend' using errcode='42501'; elsif action_value='unblock' and not private.has_permission('user.restore') then raise exception 'permission_required:user.restore' using errcode='42501'; elsif action_value='close' and not private.has_permission('user.erase') then raise exception 'permission_required:user.erase' using errcode='42501'; end if;
  if action_value not in ('block','unblock','close') then raise exception 'invalid_enforcement_action' using errcode='22023'; end if;
  if char_length(reason_value) not between 8 and 1000 then raise exception 'enforcement_reason_required' using errcode='22023'; end if;
  if p_user_id=caller_id and action_value in ('block','close') then raise exception 'cannot_enforce_current_user' using errcode='42501'; end if;
  caller_super:=coalesce(private.has_permission('security.manage'),false);
  select exists(select 1 from private.user_roles where user_id=p_user_id and role='super_admin' and (expires_at is null or expires_at>timezone('utc',now()))),exists(select 1 from private.user_roles where user_id=p_user_id and role='admin' and (expires_at is null or expires_at>timezone('utc',now()))) into target_super,target_admin;
  if (target_super or target_admin or action_value='close' or p_block_known_ips or p_block_known_devices or p_fraud_flag) and not caller_super then raise exception 'super_admin_required' using errcode='42501'; end if;
  select * into target from public.profiles where id=p_user_id for update;
  if target.id is null then raise exception 'user_not_found' using errcode='P0002'; end if;
  if p_expires_at is not null and p_expires_at<=timezone('utc',now()) then raise exception 'invalid_block_expiry' using errcode='22023'; end if;

  if action_value='block' then
    update public.profiles set status='blocked',deleted_at=null where id=p_user_id;
    update public.producers set status=case when status='closed' then status else 'suspended' end,
      trust_badge_status=case when trust_badge_status='active' then 'revoked' else trust_badge_status end,
      trust_badge_revoked_at=case when trust_badge_status='active' then timezone('utc',now()) else trust_badge_revoked_at end,
      trust_badge_reason=case when trust_badge_status='active' then 'Hesap güvenlik nedeniyle engellendi: '||reason_value else trust_badge_reason end,
      updated_at=timezone('utc',now()) where owner_user_id=p_user_id and deleted_at is null returning * into producer;
    update private.device_push_tokens set disabled_at=coalesce(disabled_at,timezone('utc',now())),updated_at=timezone('utc',now()) where user_id=p_user_id;
    insert into private.security_block_rules(subject_type,user_id,source_user_id,reason,fraud_flag,expires_at,created_by) values('user',p_user_id,p_user_id,reason_value,p_fraud_flag,p_expires_at,caller_id);
    rule_count:=rule_count+1;
    if p_block_known_ips then
      for ctx in select distinct ip_address from private.user_security_contexts where user_id=p_user_id and ip_address is not null loop
        if not exists(select 1 from private.security_block_rules r where r.subject_type='ip' and r.ip_network=host(ctx.ip_address)::cidr and r.active=true and (r.expires_at is null or r.expires_at>timezone('utc',now()))) then
          insert into private.security_block_rules(subject_type,ip_network,source_user_id,reason,fraud_flag,expires_at,created_by) values('ip',host(ctx.ip_address)::cidr,p_user_id,reason_value,p_fraud_flag,p_expires_at,caller_id); rule_count:=rule_count+1;
        end if;
      end loop;
    end if;
    if p_block_known_devices then
      for ctx in select distinct device_id from private.user_security_contexts where user_id=p_user_id and device_id is not null loop
        if not exists(select 1 from private.security_block_rules r where r.subject_type='device' and r.device_id=ctx.device_id and r.active=true and (r.expires_at is null or r.expires_at>timezone('utc',now()))) then
          insert into private.security_block_rules(subject_type,device_id,source_user_id,reason,fraud_flag,expires_at,created_by) values('device',ctx.device_id,p_user_id,reason_value,p_fraud_flag,p_expires_at,caller_id); rule_count:=rule_count+1;
        end if;
      end loop;
    end if;
    insert into private.account_enforcement_events(user_id,actor_user_id,action,reason,metadata) values(p_user_id,caller_id,'blocked',reason_value,jsonb_build_object('blockKnownIps',p_block_known_ips,'blockKnownDevices',p_block_known_devices,'fraudFlag',p_fraud_flag,'ruleCount',rule_count,'expiresAt',p_expires_at));
    if p_fraud_flag then insert into private.account_enforcement_events(user_id,actor_user_id,action,reason,metadata) values(p_user_id,caller_id,'fraud_flagged',reason_value,jsonb_build_object('ruleCount',rule_count)); end if;
  elsif action_value='unblock' then
    update public.profiles set status='active',deleted_at=null where id=p_user_id;
    update private.security_block_rules set active=false,revoked_by=caller_id,revoked_at=timezone('utc',now()) where source_user_id=p_user_id and active=true;
    insert into private.account_enforcement_events(user_id,actor_user_id,action,reason,metadata) values(p_user_id,caller_id,'unblocked',reason_value,jsonb_build_object('producerRequiresSeparateReactivation',true));
  else
    if target_super then raise exception 'super_admin_account_cannot_be_closed_here' using errcode='42501'; end if;
    update public.profiles set status='deleted',deleted_at=timezone('utc',now()),marketing_consent=false,marketing_consent_at=null where id=p_user_id;
    update public.producers set status='closed',trust_badge_status=case when trust_badge_status='active' then 'revoked' else trust_badge_status end,trust_badge_revoked_at=case when trust_badge_status='active' then timezone('utc',now()) else trust_badge_revoked_at end,trust_badge_reason='Hesap kalıcı olarak kapatıldı: '||reason_value,updated_at=timezone('utc',now()) where owner_user_id=p_user_id and deleted_at is null returning * into producer;
    if producer.id is not null then
      update public.products set status='archived',is_active=false,updated_at=timezone('utc',now()) where producer_id=producer.id and deleted_at is null and status<>'archived';
      update public.product_change_requests set status='withdrawn',updated_at=timezone('utc',now()) where producer_id=producer.id and status='pending';
    end if;
    delete from private.user_roles where user_id=p_user_id and role<>'customer';
    update private.device_push_tokens set disabled_at=coalesce(disabled_at,timezone('utc',now())),updated_at=timezone('utc',now()) where user_id=p_user_id;
    insert into private.security_block_rules(subject_type,user_id,source_user_id,reason,fraud_flag,created_by) values('user',p_user_id,p_user_id,reason_value,p_fraud_flag,caller_id);
    if p_block_known_ips then for ctx in select distinct ip_address from private.user_security_contexts where user_id=p_user_id and ip_address is not null loop insert into private.security_block_rules(subject_type,ip_network,source_user_id,reason,fraud_flag,created_by) values('ip',host(ctx.ip_address)::cidr,p_user_id,reason_value,p_fraud_flag,caller_id); end loop; end if;
    if p_block_known_devices then for ctx in select distinct device_id from private.user_security_contexts where user_id=p_user_id and device_id is not null loop insert into private.security_block_rules(subject_type,device_id,source_user_id,reason,fraud_flag,created_by) values('device',ctx.device_id,p_user_id,reason_value,p_fraud_flag,caller_id); end loop; end if;
    insert into private.account_enforcement_events(user_id,actor_user_id,action,reason,metadata) values(p_user_id,caller_id,'closed',reason_value,jsonb_build_object('fraudFlag',p_fraud_flag,'blockKnownIps',p_block_known_ips,'blockKnownDevices',p_block_known_devices));
  end if;
  return jsonb_build_object('id',p_user_id,'action',action_value,'status',(select status from public.profiles where id=p_user_id),'producerStatus',(select status from public.producers where owner_user_id=p_user_id and deleted_at is null limit 1),'securityRuleCount',(select count(*) from private.security_block_rules where source_user_id=p_user_id and active=true),'fraudFlag',exists(select 1 from private.security_block_rules where source_user_id=p_user_id and active=true and fraud_flag=true));
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_finance_report_v2(p_from date, p_to date, p_currency text DEFAULT 'TRY'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare currency_value text:=upper(btrim(coalesce(p_currency,''))); result jsonb;
begin
 if auth.uid() is null or not coalesce(private.has_permission('finance.read'),false) then raise exception 'admin_required' using errcode='42501'; end if;
 if p_from is null or p_to is null or p_to<p_from or p_to-p_from>366 then raise exception 'invalid_finance_date_range' using errcode='22023'; end if;
 if currency_value!~'^[A-Z]{3}$' then raise exception 'invalid_currency' using errcode='22023'; end if;
 with date_series as(select day::date report_date from generate_series(p_from::timestamp,p_to::timestamp,interval '1 day') day),
 daily_orders as(select timezone('utc',coalesce(o.placed_at,o.created_at))::date report_date,count(*)::integer order_count,sum(o.total_minor)::bigint gross_sales_minor from public.orders o where timezone('utc',coalesce(o.placed_at,o.created_at))::date between p_from and p_to and o.currency=currency_value and o.payment_status in('paid','partially_refunded','refunded') and o.status<>'cancelled' group by 1),
 daily_refunds as(select timezone('utc',r.created_at)::date report_date,sum(r.amount_minor)::bigint refund_minor from public.refunds r where timezone('utc',r.created_at)::date between p_from and p_to and r.currency=currency_value and r.status='succeeded' group by 1),
 daily as(select d.report_date,coalesce(o.order_count,0) order_count,coalesce(o.gross_sales_minor,0) gross_sales_minor,coalesce(r.refund_minor,0) refund_minor,coalesce(o.gross_sales_minor,0)-coalesce(r.refund_minor,0) net_sales_minor from date_series d left join daily_orders o using(report_date) left join daily_refunds r using(report_date)),
 ledger as(select l.producer_id,count(distinct l.order_id)::integer order_count,sum(l.producer_gross_minor)::bigint producer_gross_minor,sum(l.platform_fee_minor)::bigint commission_minor,sum(l.producer_net_minor)::bigint producer_net_minor from private.producer_ledger_entries l where timezone('utc',l.created_at)::date between p_from and p_to and l.currency=currency_value group by l.producer_id),
 vendor_income as(select l.producer_id,p.display_name vendor_name,l.order_count,l.producer_gross_minor gross_sales_minor,l.commission_minor,l.producer_net_minor estimated_payout_minor from ledger l join public.producers p on p.id=l.producer_id),
 payouts as(select coalesce(sum(amount_minor) filter(where status='paid'),0)::bigint paid_payout_minor,coalesce(sum(amount_minor) filter(where status in('scheduled','processing')),0)::bigint pending_payout_minor from private.producer_payouts where currency=currency_value and timezone('utc',coalesce(processed_at,scheduled_at,created_at))::date between p_from and p_to),
 payments as(select coalesce(sum(amount_minor) filter(where status in('captured','partially_refunded','refunded')),0)::bigint captured_minor from public.payment_records where currency=currency_value and timezone('utc',coalesce(captured_at,created_at))::date between p_from and p_to),
 expenses as(select coalesce(sum(amount_minor),0)::bigint expense_minor from private.platform_expenses where currency=currency_value and status='posted' and spent_on between p_from and p_to),
 scalars as(select coalesce((select sum(commission_minor) from ledger),0)::bigint commission_minor,coalesce((select sum(producer_net_minor) from ledger),0)::bigint producer_net_minor,coalesce((select sum(producer_gross_minor) from ledger),0)::bigint producer_gross_minor,(select paid_payout_minor from payouts)::bigint paid_payout_minor,(select pending_payout_minor from payouts)::bigint pending_payout_minor,(select captured_minor from payments)::bigint captured_minor,(select expense_minor from expenses)::bigint expense_minor,coalesce((select sum(refund_minor) from daily),0)::bigint refund_minor,coalesce((select sum(gross_sales_minor) from daily),0)::bigint gross_sales_minor)
 select jsonb_build_object('currency',currency_value,'from',p_from,'to',p_to,'totals',jsonb_build_object('order_count',coalesce((select sum(order_count) from daily),0),'gross_sales_minor',(select gross_sales_minor from scalars),'refund_minor',(select refund_minor from scalars),'net_sales_minor',(select gross_sales_minor-refund_minor from scalars),'commission_minor',(select commission_minor from scalars),'estimated_payout_minor',(select producer_net_minor from scalars),'producer_gross_minor',(select producer_gross_minor from scalars),'paid_payout_minor',(select paid_payout_minor from scalars),'pending_payout_minor',(select pending_payout_minor from scalars),'captured_payment_minor',(select captured_minor from scalars),'reconciliation_delta_minor',(select captured_minor-gross_sales_minor from scalars),'expense_minor',(select expense_minor from scalars),'platform_profit_minor',(select commission_minor-expense_minor from scalars),'cash_out_minor',(select refund_minor+paid_payout_minor+expense_minor from scalars),'cash_delta_minor',(select captured_minor-refund_minor-paid_payout_minor-expense_minor from scalars)),'daily_sales',coalesce((select jsonb_agg(jsonb_build_object('date',report_date,'order_count',order_count,'gross_sales_minor',gross_sales_minor,'refund_minor',refund_minor,'net_sales_minor',net_sales_minor) order by report_date) from daily),'[]'::jsonb),'vendor_income',coalesce((select jsonb_agg(jsonb_build_object('producer_id',producer_id,'vendor_name',vendor_name,'order_count',order_count,'gross_sales_minor',gross_sales_minor,'commission_minor',commission_minor,'estimated_payout_minor',estimated_payout_minor) order by gross_sales_minor desc,vendor_name) from vendor_income),'[]'::jsonb),'available_currencies',coalesce((select jsonb_agg(currency order by currency) from(select distinct currency from public.orders union select distinct currency from private.producer_ledger_entries union select distinct currency from private.producer_payouts union select distinct currency from private.platform_expenses) c),'[]'::jsonb)) into result;
 return result;
end;$function$;

CREATE OR REPLACE FUNCTION private.admin_finance_report_v3(p_from date, p_to date, p_currency text DEFAULT 'TRY'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare payload jsonb; pending_minor bigint; currency_value text:=upper(btrim(coalesce(p_currency,'')));
begin
  payload:=private.admin_finance_report_v2(p_from,p_to,currency_value);
  select coalesce(sum(amount_minor),0)::bigint into pending_minor
  from private.producer_payouts
  where currency=currency_value and status in('requested','scheduled','processing')
    and timezone('utc',coalesce(processed_at,requested_at,scheduled_at,created_at))::date between p_from and p_to;
  return jsonb_set(payload,'{totals,pending_payout_minor}',to_jsonb(pending_minor),true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_get_brand_configuration_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare settings public.brand_settings%rowtype;
begin
  if auth.uid() is null or not private.has_permission('system.read') then
    raise exception 'admin_required' using errcode='42501';
  end if;
  select * into settings from public.brand_settings where slug='golden-oremar';
  if not found then raise exception 'brand_configuration_not_found' using errcode='P0002'; end if;
  return jsonb_build_object(
    'slug',settings.slug,
    'brandName',settings.brand_name,
    'maintenanceMode',settings.maintenance_mode,
    'supportEmail',settings.support_email,
    'supportPhone',settings.support_phone,
    'publicConfig',settings.public_config,
    'updatedAt',settings.updated_at
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_get_message_moderation_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s private.message_moderation_settings%rowtype;
begin
  if auth.uid() is null or not private.has_permission('security.read') then raise exception 'super_admin_required' using errcode='42501'; end if;
  select * into s from private.message_moderation_settings where singleton=true;
  if not found then raise exception 'message_moderation_configuration_missing' using errcode='P0002'; end if;
  return jsonb_build_object(
    'enabled',s.enabled,
    'blockEmail',s.block_email,
    'blockPhone',s.block_phone,
    'blockMessagingApps',s.block_messaging_apps,
    'blockExternalLinks',s.block_external_links,
    'blockSocialHandles',s.block_social_handles,
    'blockBankDetails',s.block_bank_details,
    'blockExternalPayments',s.block_external_payments,
    'blockQrCodes',s.block_qr_codes,
    'customBlockedPhrases',to_jsonb(s.custom_blocked_phrases),
    'applyToSupport',s.apply_to_support,
    'allowAttachments',s.allow_attachments,
    'allowImages',s.allow_images,
    'allowPdf',s.allow_pdf,
    'maxAttachments',s.max_attachments,
    'maxAttachmentMb',s.max_attachment_mb,
    'updatedAt',s.updated_at
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_get_producer_application_sensitive_v3(p_application_id uuid, p_purpose text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); result jsonb;
begin
 if caller_id is null or not coalesce(private.has_permission('seller.sensitive_read'),false) then raise exception 'permission_required:seller.sensitive_read' using errcode='42501'; end if;
 if p_application_id is null then raise exception 'producer_application_required' using errcode='22023'; end if;
 if char_length(btrim(coalesce(p_purpose,''))) not between 10 and 200 then raise exception 'sensitive_access_purpose_required' using errcode='22023'; end if;
 select jsonb_build_object('application_id',a.id,'legal_name',k.legal_name,'national_id',private.decrypt_producer_kyc(k.national_id_ciphertext),'tax_number',private.decrypt_producer_kyc(k.tax_number_ciphertext),'tax_office',k.tax_office,'mersis_number',private.decrypt_producer_kyc(k.mersis_number_ciphertext),'tax_exemption_number',private.decrypt_producer_kyc(k.tax_exemption_number_ciphertext),'food_registration_number',private.decrypt_producer_kyc(k.food_registration_number_ciphertext),'organic_certificate_number',private.decrypt_producer_kyc(k.organic_certificate_number_ciphertext),'iban',private.decrypt_producer_kyc(k.iban_ciphertext),'bank_account_holder',k.bank_account_holder,'phone',k.phone,'contact_email',k.contact_email,'address',k.address,'consent_version',k.consent_version,'consented_at',k.consented_at) into result from public.producer_applications a join private.producer_application_kyc k on k.application_id=a.id where a.id=p_application_id;
 if result is null then raise exception 'producer_application_not_found' using errcode='P0002'; end if;
 insert into private.sensitive_access_log(actor_user_id,resource_type,resource_id,purpose) values(caller_id,'producer_application_kyc',p_application_id,btrim(p_purpose));
 return result;
end;$function$;

CREATE OR REPLACE FUNCTION private.admin_get_product_certifications_v1(p_product_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
  if auth.uid() is null or not coalesce(private.has_permission('product.read'),false) then raise exception 'admin_required' using errcode='42501'; end if;
  if not exists(select 1 from public.products p where p.id=p_product_id and p.deleted_at is null) then raise exception 'product_not_found' using errcode='P0002'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',c.id,'certificateType',c.certificate_type,'issuer',c.issuer,'certificateNumber',c.certificate_number,
    'issuedAt',c.issued_at,'expiresAt',c.expires_at,'status',c.status,
    'documentPath',d.storage_path,'reviewedAt',d.reviewed_at,'reviewNote',d.review_note
  ) order by c.created_at desc),'[]'::jsonb) into result
  from public.product_certifications c
  left join private.product_certification_documents d on d.certification_id=c.id
  where c.product_id=p_product_id;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_get_return_detail_v1(p_return_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  request_row public.return_requests%rowtype;
  result jsonb;
begin
  if not coalesce(private.has_permission('refund.read'),false) then
    raise exception 'admin_required' using errcode='42501';
  end if;

  select * into request_row
  from public.return_requests request
  where request.id=p_return_id;

  if request_row.id is null then
    raise exception 'return_not_found' using errcode='P0002';
  end if;

  select jsonb_build_object(
    'id',request_row.id,
    'returnNumber',request_row.return_number,
    'orderId',request_row.order_id,
    'orderNumber',customer_order.order_number,
    'customer',jsonb_build_object(
      'userId',request_row.user_id,
      'displayName',profile.display_name,
      'phone',profile.phone
    ),
    'reasonCode',request_row.reason_code,
    'customerMessage',request_row.customer_message,
    'status',request_row.status,
    'resolution',request_row.resolution,
    'resolutionNote',request_row.resolution_note,
    'reviewReason',request_row.review_reason,
    'restockApproved',request_row.restock_approved,
    'requestedAt',request_row.requested_at,
    'reviewedAt',request_row.reviewed_at,
    'receivedAt',request_row.received_at,
    'closedAt',request_row.closed_at,
    'items',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',return_item.id,
        'orderItemId',return_item.order_item_id,
        'productName',order_item.product_name,
        'variantName',order_item.variant_name,
        'quantity',return_item.quantity,
        'purchasedQuantity',order_item.quantity,
        'condition',return_item.condition,
        'evidencePaths',to_jsonb(return_item.evidence_paths),
        'refundAmountMinor',return_item.refund_amount_minor,
        'currency',customer_order.currency
      ) order by return_item.created_at)
      from public.return_items return_item
      join public.order_items order_item on order_item.id=return_item.order_item_id
      where return_item.return_id=request_row.id
    ),'[]'::jsonb),
    'refunds',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',refund.id,
        'amountMinor',refund.amount_minor,
        'currency',refund.currency,
        'status',refund.status,
        'reason',refund.reason,
        'processedAt',refund.processed_at
      ) order by refund.created_at desc)
      from public.refunds refund
      where refund.return_id=request_row.id
    ),'[]'::jsonb)
  ) into result
  from public.orders customer_order
  left join public.profiles profile on profile.id=request_row.user_id
  where customer_order.id=request_row.order_id;

  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_list_accounting_periods_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if auth.uid() is null or not coalesce(private.has_permission('finance.read'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
 return coalesce((select jsonb_agg(jsonb_build_object('id',id,'from',period_from,'to',period_to,'currency',currency,'status',status,'closedAt',closed_at,'archivedAt',archived_at,'cleanupCompletedAt',cleanup_completed_at,'snapshot',snapshot) order by period_to desc,currency) from private.accounting_periods),'[]'::jsonb);
end;$function$;

CREATE OR REPLACE FUNCTION private.admin_list_categories_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null or not private.has_permission('content.read') then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', category.id,
      'parent_id', category.parent_id,
      'slug', category.slug,
      'name', category.name,
      'description', category.description,
      'icon', category.icon,
      'image_path', category.image_path,
      'sort_order', category.sort_order,
      'is_active', category.is_active,
      'product_count', (select count(*) from public.products p where p.category_id=category.id and p.deleted_at is null),
      'published_product_count', (
        select count(*)
        from public.products p
        join public.producers producer on producer.id=p.producer_id
        where p.category_id=category.id and p.status='published' and p.is_active=true and p.deleted_at is null
          and producer.status='active' and producer.is_verified=true and producer.deleted_at is null
      )
    ) order by category.sort_order, category.name)
    from public.categories category
  ), '[]'::jsonb);
