CREATE OR REPLACE FUNCTION private.admin_list_coupons_v1()
 RETURNS TABLE(id uuid, campaign_id uuid, campaign_title text, display_hint text, status text, starts_at timestamp with time zone, ends_at timestamp with time zone, usage_limit integer, per_user_limit integer, reserved_count bigint, consumed_count bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null or not coalesce(private.has_permission('campaign.read'),false) then
    raise exception 'admin_required' using errcode='42501';
  end if;
  return query
  select coupon.id,coupon.campaign_id,campaign.title,coupon.display_hint,coupon.status,
         coupon.starts_at,coupon.ends_at,coupon.usage_limit,coupon.per_user_limit,
         count(redemption.id) filter (where redemption.status='reserved')::bigint,
         count(redemption.id) filter (where redemption.status='consumed')::bigint
  from public.coupons coupon
  join public.campaigns campaign on campaign.id=coupon.campaign_id
  left join private.promotion_redemptions redemption on redemption.coupon_id=coupon.id
  group by coupon.id,campaign.title
  order by coupon.created_at desc;
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_list_events_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null or not private.has_permission('event.read') then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'events', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', event.id,
        'legacy_id', event.legacy_id,
        'slug', event.slug,
        'title', event.title,
        'description', event.description,
        'image_path', event.image_path,
        'location_name', event.location_name,
        'location_details', event.location_details,
        'starts_at', event.starts_at,
        'ends_at', event.ends_at,
        'capacity', event.capacity,
        'reservation_deadline', event.reservation_deadline,
        'status', event.status,
        'created_at', event.created_at,
        'updated_at', event.updated_at,
        'reservation_count', (select count(*) from public.event_reservations r where r.event_id=event.id and r.status <> 'cancelled'),
        'reserved_guests', (select coalesce(sum(r.guest_count),0) from public.event_reservations r where r.event_id=event.id and r.status <> 'cancelled')
      ) order by event.starts_at desc)
      from public.events event
    ), '[]'::jsonb),
    'reservations', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', reservation.id,
        'event_id', reservation.event_id,
        'event_title', event.title,
        'event_starts_at', event.starts_at,
        'reservation_code', reservation.reservation_code,
        'user_id', reservation.user_id,
        'guest_name', reservation.guest_name,
        'guest_email', reservation.guest_email,
        'guest_phone', reservation.guest_phone,
        'guest_count', reservation.guest_count,
        'notes', reservation.notes,
        'status', reservation.status,
        'created_at', reservation.created_at,
        'updated_at', reservation.updated_at
      ) order by reservation.created_at desc)
      from public.event_reservations reservation
      join public.events event on event.id=reservation.event_id
    ), '[]'::jsonb)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_list_inventory_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null or not private.has_permission('inventory.read') then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'variant_id', variant.id,
      'sku', variant.sku,
      'variant_name', variant.name,
      'product_id', product.id,
      'product_name', product.name,
      'product_status', product.status,
      'stock_mode', product.stock_mode,
      'currency', product.currency,
      'price_minor', variant.price_minor,
      'producer_id', producer.id,
      'producer_name', producer.display_name,
      'producer_status', producer.status,
      'producer_verified', producer.is_verified,
      'available_quantity', coalesce(inventory.available_quantity, 0),
      'reserved_quantity', coalesce(inventory.reserved_quantity, 0),
      'sellable_quantity', greatest(0, coalesce(inventory.available_quantity, 0) - coalesce(inventory.reserved_quantity, 0)),
      'reorder_level', coalesce(inventory.reorder_level, 0),
      'version', coalesce(inventory.version, 0),
      'updated_at', coalesce(inventory.updated_at, variant.updated_at),
      'is_active', variant.is_active
    ) order by greatest(0, coalesce(inventory.available_quantity, 0) - coalesce(inventory.reserved_quantity, 0)) asc, product.name, variant.name)
    from public.product_variants variant
    join public.products product on product.id = variant.product_id and product.deleted_at is null
    join public.producers producer on producer.id = product.producer_id and producer.deleted_at is null
    left join public.product_inventory inventory on inventory.variant_id = variant.id
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_list_pending_product_changes_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null or not coalesce(private.has_permission('product.read'),false) then raise exception 'admin_required' using errcode='42501'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id',cr.id,'product_id',cr.product_id,'product_name',p.name,'product_slug',p.slug,'producer_id',cr.producer_id,'producer_name',producer.display_name,
    'producer_badge_active',private.is_producer_trust_badge_active_v1(cr.producer_id),'category_scope_ready',category.slug=any(producer.approved_category_slugs),
    'origin_matches_producer',lower(btrim(coalesce(cr.proposed_payload->>'origin',p.origin,'')))=lower(btrim(coalesce(producer.production_location,''))),
    'proposed_payload',cr.proposed_payload,'created_at',cr.created_at,'updated_at',cr.updated_at
  ) order by cr.created_at asc) from public.product_change_requests cr
  join public.products p on p.id=cr.product_id and p.deleted_at is null
  join public.producers producer on producer.id=cr.producer_id and producer.deleted_at is null
  join public.categories category on category.id=p.category_id
  where cr.status='pending'),'[]'::jsonb);
