CREATE OR REPLACE FUNCTION private.admin_list_platform_expenses_v1(p_from date, p_to date, p_currency text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare currency_value text:=upper(btrim(coalesce(p_currency,'')));
begin
 if auth.uid() is null or not coalesce(private.has_permission('finance.read'),false) then raise exception 'admin_required' using errcode='42501'; end if;
 if p_from is null or p_to is null or p_to<p_from or p_to-p_from>366 then raise exception 'invalid_finance_date_range' using errcode='22023'; end if;
 if currency_value!~'^[A-Z]{3}$' then raise exception 'invalid_currency' using errcode='22023'; end if;
 return coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'spentOn',e.spent_on,'category',e.category,'description',e.description,'amountMinor',e.amount_minor,'currency',e.currency,'status',e.status,'externalReference',e.external_reference,'receiptPath',e.receipt_path,'voidReason',e.void_reason,'createdAt',e.created_at) order by e.spent_on desc,e.created_at desc) from private.platform_expenses e where e.spent_on between p_from and p_to and e.currency=currency_value),'[]'::jsonb);
end;$function$;

CREATE OR REPLACE FUNCTION private.admin_list_platform_users_v3()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  reveal_sensitive boolean;
begin
  if caller_id is null or not coalesce(private.has_permission('user.read'),false) then
    raise exception 'admin_required' using errcode='42501';
  end if;
  reveal_sensitive:=coalesce(private.has_permission('security.read'),false);

  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id',p.id,
      'displayName',nullif(btrim(p.display_name),''),
      'email',u.email,
      'roles',role_state.roles,
      'primaryRole',role_state.primary_role,
      'status',case when p.status='active' then 'active' when p.status='deleted' then 'deleted' else 'blocked' end,
      'profileStatus',p.status,
      'joinDate',p.created_at,
      'producerId',producer.id,
      'producerStatus',producer.status,
      'producerCommissionBasisPoints',case when reveal_sensitive then producer.commission_basis_points else null end,
      'lastSeenAt',p.last_seen_at,
      'lastKnownIp',case when reveal_sensitive then latest.ip_address::text else null end,
      'knownDeviceCount',(select count(distinct c.device_id) from private.user_security_contexts c where c.user_id=p.id and c.device_id is not null),
      'activeSecurityRuleCount',(select count(*) from private.security_block_rules r where r.source_user_id=p.id and r.active=true and (r.expires_at is null or r.expires_at>timezone('utc',now()))),
      'fraudFlag',exists(select 1 from private.security_block_rules r where r.source_user_id=p.id and r.active=true and r.fraud_flag=true and (r.expires_at is null or r.expires_at>timezone('utc',now()))),
      'lastEnforcementReason',(select e.reason from private.account_enforcement_events e where e.user_id=p.id order by e.created_at desc limit 1),
      'lastEnforcementAt',(select e.created_at from private.account_enforcement_events e where e.user_id=p.id order by e.created_at desc limit 1)
    ) order by p.created_at desc)
    from public.profiles p
    join auth.users u on u.id=p.id
    left join lateral(
      select
        array_agg(r.role order by case r.role when 'super_admin' then 1 when 'admin' then 2 when 'operations' then 3 when 'moderator' then 4 when 'content_editor' then 5 when 'support' then 6 when 'producer' then 7 when 'customer' then 8 else 99 end) as roles,
        (array_agg(r.role order by case r.role when 'super_admin' then 1 when 'admin' then 2 when 'operations' then 3 when 'moderator' then 4 when 'content_editor' then 5 when 'support' then 6 when 'producer' then 7 when 'customer' then 8 else 99 end))[1] as primary_role
      from private.user_roles r
      where r.user_id=p.id and (r.expires_at is null or r.expires_at>timezone('utc',now()))
    ) role_state on true
    left join lateral(
      select pr.id,pr.status,pr.commission_basis_points
      from public.producers pr
      where pr.owner_user_id=p.id and pr.deleted_at is null
      order by pr.created_at desc limit 1
    ) producer on true
    left join lateral(
      select c.ip_address
      from private.user_security_contexts c
      where c.user_id=p.id and c.ip_address is not null
      order by c.last_seen_at desc limit 1
    ) latest on true
  ),'[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_list_producer_applications_v3()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare base jsonb; result jsonb;
begin
  base:=public.admin_list_producer_applications_v2();
  select coalesce(jsonb_agg(item||jsonb_build_object(
    'planned_products',application.planned_products,
    'sourcing_models',application.sourcing_models,
    'activity_types',application.activity_types,
    'organic_claim_status',application.organic_claim_status,
    'organic_certifier_name',application.organic_certifier_name,
    'organic_certificate_expires_on',application.organic_certificate_expires_on,
    'village_product_commitment',application.village_product_commitment,
    'traceability_commitment',application.traceability_commitment,
    'product_truth_commitment',application.product_truth_commitment,
    'production_practice_notes',application.production_practice_notes,
    'production_country_code',application.production_country_code,
    'production_province',application.production_province,
    'production_district',application.production_district,
    'production_village',application.production_village,
    'production_village_is_custom',application.production_village_is_custom
  )),'[]'::jsonb) into result
  from jsonb_array_elements(base) item
  join public.producer_applications application on application.id=(item->>'id')::uuid;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_list_producer_balances_v1(p_currency text DEFAULT 'TRY'::text)
 RETURNS TABLE(producer_id uuid, display_name text, commission_basis_points integer, currency text, pending_minor bigint, available_to_payout_minor bigint, paid_payout_minor bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  currency_code text:=upper(btrim(coalesce(p_currency,'TRY')));
begin
  if auth.uid() is null or not coalesce(private.has_permission('finance.read'),false) then raise exception 'admin_required' using errcode='42501'; end if;
  if currency_code !~ '^[A-Z]{3}$' then raise exception 'invalid_currency' using errcode='22023'; end if;
  return query
  select producer.id,producer.display_name,producer.commission_basis_points,currency_code,
         ((private.get_producer_balance_v1(producer.id,currency_code))->>'pendingMinor')::bigint,
         ((private.get_producer_balance_v1(producer.id,currency_code))->>'availableToPayoutMinor')::bigint,
         ((private.get_producer_balance_v1(producer.id,currency_code))->>'paidPayoutMinor')::bigint
  from public.producers producer
  where producer.deleted_at is null
  order by producer.display_name;
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_list_producer_event_submissions_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null or not coalesce(private.has_permission('event.moderate'),false) then
    raise exception 'super_admin_required' using errcode='42501';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id',s.id,'producerId',s.producer_id,'producerName',p.display_name,'producerLocation',p.production_location,
      'producerCommissionBasisPoints',p.commission_basis_points,'producerBadgeActive',private.is_producer_trust_badge_active_v1(p.id),
      'title',s.title,'description',s.description,'imagePath',s.image_path,'locationName',s.location_name,'locationDetails',s.location_details,
      'startsAt',s.starts_at,'endsAt',s.ends_at,'capacity',s.capacity,'reservationDeadline',s.reservation_deadline,
      'ticketPriceMinor',s.ticket_price_minor,'currency',s.currency,'requestedCommissionBasisPoints',s.requested_commission_basis_points,
      'approvedCommissionBasisPoints',s.approved_commission_basis_points,'status',s.status,'reviewReason',s.review_reason,
      'eventId',s.event_id,'createdAt',s.created_at,'updatedAt',s.updated_at
    ) order by case s.status when 'pending' then 0 when 'needs_changes' then 1 else 2 end,s.created_at asc)
    from private.producer_event_submissions s
    join public.producers p on p.id=s.producer_id
  ),'[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_list_producers_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null or not private.has_permission('seller.read') then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  return coalesce((
    select jsonb_agg(
      jsonb_build_object(
        'id', producer.id,
        'owner_user_id', producer.owner_user_id,
        'application_id', producer.application_id,
        'slug', producer.slug,
        'display_name', producer.display_name,
        'description', producer.description,
        'production_location', producer.production_location,
        'production_country_code', producer.production_country_code,
        'production_province', producer.production_province,
        'production_district', producer.production_district,
        'production_village', producer.production_village,
        'production_village_is_custom', producer.production_village_is_custom,
        'logo_path', producer.logo_path,
        'status', producer.status,
        'is_verified', producer.is_verified,
        'verified_at', producer.verified_at,
        'verification_due_at', producer.verification_due_at,
        'origin_verified', producer.origin_verified,
        'origin_verified_at', producer.origin_verified_at,
        'origin_verification_basis', producer.origin_verification_basis,
        'commission_basis_points', producer.commission_basis_points,
        'rating_average', producer.rating_average,
        'rating_count', producer.rating_count,
        'email', account.email,
        'phone', profile.phone,
        'created_at', producer.created_at,
        'product_count', (
          select count(*)
          from public.products product
          where product.producer_id = producer.id
            and product.deleted_at is null
        ),
        'order_count', (
          select count(distinct item.order_id)
          from public.order_items item
          where item.producer_id = producer.id
        ),
        'follower_count', (
          select count(*)
          from private.producer_follows follow_row
          where follow_row.producer_id = producer.id
        )
      )
      order by producer.created_at desc
    )
    from public.producers producer
    join public.profiles profile on profile.id = producer.owner_user_id
    join auth.users account on account.id = producer.owner_user_id
    where producer.deleted_at is null
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_list_producers_v2()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare base jsonb; result jsonb; reveal_commission boolean;
begin
  if auth.uid() is null or not coalesce(private.has_permission('seller.read'),false) then raise exception 'admin_required' using errcode='42501'; end if;
  reveal_commission:=coalesce(private.has_permission('finance.read'),false);
  base:=private.admin_list_producers_v1();
  select coalesce(jsonb_agg((item-'commission_basis_points')||jsonb_build_object(
    'commission_basis_points',case when reveal_commission then p.commission_basis_points else null end,
    'activity_types',p.activity_types,
    'approved_category_slugs',p.approved_category_slugs,
    'trust_badge_status',p.trust_badge_status,
    'trust_badge_active',private.is_producer_trust_badge_active_v1(p.id),
    'trust_badge_granted_at',p.trust_badge_granted_at,
    'trust_badge_review_due_at',p.trust_badge_review_due_at,
    'trust_badge_revoked_at',p.trust_badge_revoked_at,
    'trust_badge_reason',p.trust_badge_reason
  ) order by ordinality),'[]'::jsonb) into result
  from jsonb_array_elements(base) with ordinality rows(item,ordinality)
  join public.producers p on p.id=(item->>'id')::uuid;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_list_product_editorial_reviews_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
  if auth.uid() is null or not coalesce(private.has_permission('product.read'),false) then raise exception 'admin_required' using errcode='42501'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'productId',p.id,'productName',p.name,'productSlug',p.slug,'producerId',pr.id,'producerName',pr.display_name,'payload',d.payload,'submittedAt',d.submitted_at,'updatedAt',d.updated_at) order by d.updated_at desc),'[]'::jsonb) into result
  from private.product_editorial_drafts d join public.products p on p.id=d.product_id join public.producers pr on pr.id=d.producer_id where d.status='review' and p.deleted_at is null and pr.deleted_at is null;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_list_products_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null or not private.has_permission('product.read') then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', p.id,
      'producer_id', p.producer_id,
      'producer_name', producer.display_name,
      'producer_verified', producer.is_verified,
      'producer_origin_verified', producer.origin_verified,
      'category_id', p.category_id,
      'category_name', category.name,
      'slug', p.slug,
      'name', p.name,
      'short_description', p.short_description,
      'description', p.description,
      'origin', p.origin,
      'unit_label', p.unit_label,
      'base_price_minor', p.base_price_minor,
      'compare_at_price_minor', p.compare_at_price_minor,
      'currency', p.currency,
      'status', p.status,
      'stock_mode', p.stock_mode,
      'is_featured', p.is_featured,
      'is_active', p.is_active,
      'export_status', p.export_status,
      'country_of_origin_code', p.country_of_origin_code,
      'requires_cold_chain', p.requires_cold_chain,
      'is_perishable', p.is_perishable,
      'shelf_life_days', p.shelf_life_days,
      'published_at', p.published_at,
      'created_at', p.created_at,
      'updated_at', p.updated_at,
      'variant_count', metrics.variant_count,
      'active_variant_count', metrics.active_variant_count,
      'missing_weight_variant_count', metrics.missing_weight_variant_count,
      'primary_image_count', metrics.primary_image_count,
      'available_quantity', metrics.available_quantity,
      'review_count', metrics.review_count,
      'rating_average', metrics.rating_average,
      'shipping_weight_ready', metrics.active_variant_count > 0 and metrics.missing_weight_variant_count = 0,
      'origin_code_ready', p.country_of_origin_code ~ '^[A-Z]{2}$',
      'shelf_life_ready', (not p.is_perishable) or p.shelf_life_days is not null,
      'export_ready',
        p.export_status = 'eligible'
        and p.country_of_origin_code ~ '^[A-Z]{2}$'
        and metrics.active_variant_count > 0
        and metrics.missing_weight_variant_count = 0
        and ((not p.is_perishable) or p.shelf_life_days is not null),
      'catalog_issue_count',
        (case when producer.id is null or producer.status <> 'active' or producer.is_verified is not true then 1 else 0 end)
        + (case when category.id is null or category.is_active is not true then 1 else 0 end)
        + (case when metrics.active_variant_count = 0 then 1 else 0 end)
        + (case when metrics.priced_variant_count = 0 then 1 else 0 end)
        + (case when metrics.primary_image_count <> 1 then 1 else 0 end)
        + (case when p.export_status = 'eligible' and p.country_of_origin_code !~ '^[A-Z]{2}$' then 1 else 0 end)
        + (case when p.export_status = 'eligible' and metrics.missing_weight_variant_count > 0 then 1 else 0 end)
        + (case when p.is_perishable and p.shelf_life_days is null then 1 else 0 end)
    ) order by p.updated_at desc)
    from public.products p
    left join public.producers producer on producer.id = p.producer_id
    left join public.categories category on category.id = p.category_id
    cross join lateral (
      select
        (select count(*)::integer from public.product_variants v where v.product_id = p.id and v.deleted_at is null) as variant_count,
        (select count(*)::integer from public.product_variants v where v.product_id = p.id and v.deleted_at is null and v.is_active) as active_variant_count,
        (select count(*)::integer from public.product_variants v where v.product_id = p.id and v.deleted_at is null and v.is_active and v.price_minor > 0) as priced_variant_count,
        (select count(*)::integer from public.product_variants v where v.product_id = p.id and v.deleted_at is null and v.is_active and (v.weight_grams is null or v.weight_grams <= 0)) as missing_weight_variant_count,
        (select count(*)::integer from public.product_images image where image.product_id = p.id and image.is_primary) as primary_image_count,
        coalesce((
          select sum(greatest(0, i.available_quantity - i.reserved_quantity))::bigint
          from public.product_inventory i
          join public.product_variants v on v.id = i.variant_id
          where v.product_id = p.id and v.deleted_at is null
        ), 0) as available_quantity,
        (select count(*)::integer from public.reviews r where r.product_id = p.id and r.status = 'published') as review_count,
        coalesce((select avg(r.rating)::numeric(4,2) from public.reviews r where r.product_id = p.id and r.status = 'published'), 0) as rating_average
    ) metrics
    where p.deleted_at is null
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_list_products_v2()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  base jsonb;
  result jsonb;
begin
  if auth.uid() is null or not coalesce(private.has_permission('product.read'),false) then
    raise exception 'admin_required' using errcode='42501';
  end if;
  base:=private.admin_list_products_v1();
  select coalesce(jsonb_agg(
    (item - 'primary_image_count')
    || jsonb_build_object(
      'database_primary_image_count',coalesce((item->>'primary_image_count')::integer,0),
      'primary_image_count',asset_metrics.stored_primary_image_count,
      'stored_image_count',asset_metrics.stored_image_count,
      'stored_primary_image_count',asset_metrics.stored_primary_image_count,
      'image_asset_ready',asset_metrics.stored_primary_image_count=1,
      'catalog_issue_count',coalesce((item->>'catalog_issue_count')::integer,0)
        + case
            when coalesce((item->>'primary_image_count')::integer,0)=1 and asset_metrics.stored_primary_image_count<>1 then 1
            else 0
          end
    )
    order by ordinality
  ),'[]'::jsonb)
  into result
  from jsonb_array_elements(coalesce(base,'[]'::jsonb)) with ordinality as rows(item,ordinality)
  cross join lateral (
    select
      count(*) filter(where private.verified_public_storage_path_v1('catalog-public',image.storage_path) is not null)::integer as stored_image_count,
      count(*) filter(where image.is_primary=true and private.verified_public_storage_path_v1('catalog-public',image.storage_path) is not null)::integer as stored_primary_image_count
    from public.product_images image
    where image.product_id=(item->>'id')::uuid
  ) asset_metrics;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_list_products_v3()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare base jsonb; result jsonb;
begin
  if auth.uid() is null or not coalesce(private.has_permission('product.read'),false) then raise exception 'admin_required' using errcode='42501'; end if;
  base:=private.admin_list_products_v2();
  select coalesce(jsonb_agg(item||jsonb_build_object(
    'producer_badge_active',private.is_producer_trust_badge_active_v1(product.producer_id),
    'producer_badge_status',producer.trust_badge_status,
    'category_scope_ready',category.slug=any(producer.approved_category_slugs),
    'origin_matches_producer',lower(btrim(coalesce(product.origin,'')))=lower(btrim(coalesce(producer.production_location,''))),
    'primary_image_path',(select private.verified_public_storage_path_v1('catalog-public',i.storage_path) from public.product_images i where i.product_id=product.id and i.is_primary=true order by i.created_at limit 1),
    'duplicate_name_count',(select count(*) from public.products p2 where p2.id<>product.id and p2.deleted_at is null and lower(btrim(p2.name))=lower(btrim(product.name))),
    'duplicate_primary_image_count',(select count(*) from public.product_images i2 join public.product_images i1 on i1.product_id=product.id and i1.is_primary=true where i2.product_id<>product.id and i2.is_primary=true and i2.storage_path=i1.storage_path),
    'pending_change_count',(select count(*) from public.product_change_requests cr where cr.product_id=product.id and cr.status='pending'),
    'moderation_risk_count',(case when not private.is_producer_trust_badge_active_v1(product.producer_id) then 1 else 0 end)+(case when not (category.slug=any(producer.approved_category_slugs)) then 1 else 0 end)+(case when lower(btrim(coalesce(product.origin,'')))<>lower(btrim(coalesce(producer.production_location,''))) then 1 else 0 end)+(case when exists(select 1 from public.product_images i2 join public.product_images i1 on i1.product_id=product.id and i1.is_primary=true where i2.product_id<>product.id and i2.is_primary=true and i2.storage_path=i1.storage_path) then 1 else 0 end)+(case when coalesce((item->>'catalog_issue_count')::integer,0)>0 then 1 else 0 end)
  ) order by ordinality),'[]'::jsonb) into result
  from jsonb_array_elements(base) with ordinality rows(item,ordinality)
  join public.products product on product.id=(item->>'id')::uuid
  join public.producers producer on producer.id=product.producer_id
  join public.categories category on category.id=product.category_id;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_list_returns_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null or not private.has_permission('refund.read') then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', request.id,
      'return_number', request.return_number,
      'order_id', request.order_id,
      'order_number', customer_order.order_number,
      'customer_name', coalesce(nullif(profile.display_name,''), 'Müşteri'),
      'customer_phone', profile.phone,
      'status', request.status,
      'reason_code', request.reason_code,
      'customer_message', request.customer_message,
      'resolution', request.resolution,
      'resolution_note', request.resolution_note,
      'review_reason', request.review_reason,
      'restock_approved', request.restock_approved,
      'requested_at', request.requested_at,
      'reviewed_at', request.reviewed_at,
      'received_at', request.received_at,
      'closed_at', request.closed_at,
      'currency', customer_order.currency,
      'order_total_minor', customer_order.total_minor,
      'item_count', (select count(*) from public.return_items item where item.return_id = request.id),
      'requested_quantity', coalesce((select sum(item.quantity) from public.return_items item where item.return_id = request.id),0),
      'requested_refund_minor', coalesce((select sum(item.refund_amount_minor) from public.return_items item where item.return_id = request.id),0),
      'succeeded_refund_minor', coalesce((select sum(refund.amount_minor) from public.refunds refund where refund.return_id = request.id and refund.status='succeeded'),0)
    ) order by request.requested_at desc)
    from public.return_requests request
    join public.orders customer_order on customer_order.id=request.order_id
    left join public.profiles profile on profile.id=request.user_id
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_list_reviews_core_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
  if auth.uid() is null or not private.has_permission('review.read') then raise exception 'permission_required:review.read' using errcode='42501'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',review.id,'user_name',coalesce(nullif(profile.display_name,''),'Kullanıcı'),'product_name',product.name,'rating',review.rating,'title',review.title,'comment',review.body,'status',review.status,'is_verified_purchase',review.is_verified_purchase,'created_at',review.created_at,'updated_at',review.updated_at) order by review.created_at desc),'[]'::jsonb)
  into result from public.reviews review join public.profiles profile on profile.id=review.user_id join public.products product on product.id=review.product_id;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_list_system_errors_v1(p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if auth.uid() is null or not coalesce(private.has_permission('system.read'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
 if p_from is null or p_to is null or p_to<p_from or p_to-p_from>90 then raise exception 'invalid_error_date_range' using errcode='22023'; end if;
 return coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'day',e.event_day,'fingerprint',e.fingerprint,'severity',e.severity,'source',e.source,'message',e.message,'stack',e.sample_stack,'route',e.route,'count',e.occurrence_count,'firstSeenAt',e.first_seen_at,'lastSeenAt',e.last_seen_at) order by e.last_seen_at desc) from private.system_error_daily e where e.event_day between p_from and p_to),'[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_moderate_review_v1(p_review_id uuid, p_status text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); next_status text:=lower(btrim(coalesce(p_status,''))); reason_value text:=nullif(btrim(coalesce(p_reason,'')),''); review_row public.reviews%rowtype; before_value jsonb;
begin
  if caller_id is null or not private.has_permission('review.moderate') then raise exception 'permission_required:review.moderate' using errcode='42501'; end if;
  if next_status not in ('published','rejected','hidden') then raise exception 'invalid_review_moderation_status' using errcode='22023'; end if;
  if next_status='published' and not private.has_permission('review.publish') then raise exception 'permission_required:review.publish' using errcode='42501'; end if;
  if next_status='rejected' and not private.has_permission('review.reject') then raise exception 'permission_required:review.reject' using errcode='42501'; end if;
  if next_status='hidden' and not private.has_permission('review.remove') then raise exception 'permission_required:review.remove' using errcode='42501'; end if;
  if next_status in ('rejected','hidden') and char_length(coalesce(reason_value,''))<5 then raise exception 'review_moderation_reason_required' using errcode='22023'; end if;
  if reason_value is not null and char_length(reason_value)>2000 then raise exception 'review_moderation_reason_too_long' using errcode='22023'; end if;
  select * into review_row from public.reviews where id=p_review_id for update;
  if review_row.id is null then raise exception 'review_not_found' using errcode='P0002'; end if;
  if review_row.status='withdrawn' then raise exception 'withdrawn_review_cannot_be_moderated' using errcode='55000'; end if;
  before_value:=jsonb_build_object('status',review_row.status,'moderatedBy',review_row.moderated_by,'moderatedAt',review_row.moderated_at);
  update public.reviews set status=next_status,moderated_by=caller_id,moderated_at=timezone('utc',now()),moderation_reason=reason_value,updated_at=timezone('utc',now()) where id=review_row.id returning * into review_row;
  insert into public.notifications(user_id,type,title,message,action_url,metadata) values(review_row.user_id,'review',case when next_status='published' then 'Yorumunuz yayınlandı' else 'Yorumunuz incelendi' end,case when next_status='published' then 'Doğrulanmış alışveriş yorumunuz yayınlandı.' else 'Yorumunuzun moderasyon durumu güncellendi.' end,'/account/reviews',jsonb_build_object('reviewId',review_row.id,'status',next_status));
  perform private.write_admin_audit_v2('review.moderated','review',review_row.id::text,before_value,jsonb_build_object('status',review_row.status,'moderatedBy',review_row.moderated_by,'moderatedAt',review_row.moderated_at),jsonb_build_object('reason',reason_value));
  return jsonb_build_object('id',review_row.id,'status',review_row.status,'moderatedAt',review_row.moderated_at,'reason',review_row.moderation_reason);
end; $function$;

CREATE OR REPLACE FUNCTION private.admin_notification_audience_count_v1(p_target_scope text, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  scope text := lower(btrim(coalesce(p_target_scope,'')));
  result integer;
begin
  if auth.uid() is null or not private.has_permission('notification.read') then
    raise exception 'admin_required' using errcode='42501';
  end if;
  if scope not in ('all','producer','specific') then
    raise exception 'invalid_notification_target_scope' using errcode='22023';
  end if;
  if scope='specific' and p_user_id is null then
    raise exception 'notification_target_user_required' using errcode='22023';
  end if;

  if scope='all' then
    select count(*)::integer into result from public.profiles p where p.status='active' and p.deleted_at is null;
  elsif scope='producer' then
    select count(distinct producer.owner_user_id)::integer into result
    from public.producers producer
    join public.profiles profile on profile.id=producer.owner_user_id
    where producer.deleted_at is null and producer.status='active' and profile.status='active' and profile.deleted_at is null;
  else
    select count(*)::integer into result from public.profiles p where p.id=p_user_id and p.status='active' and p.deleted_at is null;
  end if;
  return coalesce(result,0);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_operations_overview_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  result jsonb;
begin
  if not coalesce(private.has_permission('analytics.read'),false) then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'generated_at', timezone('utc', now()),
    'counts', jsonb_build_object(
      'active_users', (select count(*) from public.profiles p where p.status = 'active' and p.deleted_at is null),
      'verified_producers', (select count(*) from public.producers p where p.status = 'active' and p.is_verified = true and p.deleted_at is null),
      'published_products', (select count(*) from public.products p where p.status = 'published' and p.is_active = true and p.deleted_at is null),
      'open_orders', (select count(*) from public.orders o where o.status in ('pending_payment','confirmed','preparing','partially_shipped','shipped','delivered')),
      'producer_applications', (select count(*) from public.producer_applications a where a.status in ('submitted','under_review','needs_information')),
      'product_reviews', (select count(*) from public.products p where p.status = 'review' and p.deleted_at is null),
      'product_change_requests', (select count(*) from public.product_change_requests r where r.status = 'pending'),
      'return_requests', (select count(*) from public.return_requests r where r.status in ('requested','under_review','approved','in_transit','received')),
      'review_moderation', (select count(*) from public.reviews r where r.status = 'pending'),
      'support_conversations', (select count(*) from public.conversations c where c.conversation_type = 'support' and c.status <> 'closed'),
      'account_closures', (select count(*) from private.account_closure_requests r where r.status in ('requested','processing','ready_for_auth_deletion')),
      'producer_payouts', (select count(*) from private.producer_payouts p where p.status in ('scheduled','processing'))
    ),
    'finance_by_currency', coalesce((
      select jsonb_agg(jsonb_build_object(
        'currency', x.currency,
        'captured_minor', x.captured_minor,
        'refunded_minor', x.refunded_minor,
        'net_collected_minor', x.captured_minor - x.refunded_minor
      ) order by x.currency)
      from (
        select currency,
          sum(captured_minor)::bigint as captured_minor,
          sum(refunded_minor)::bigint as refunded_minor
        from (
          select pr.currency, sum(pr.amount_minor)::bigint as captured_minor, 0::bigint as refunded_minor
          from public.payment_records pr
          where pr.status in ('captured','partially_refunded','refunded')
          group by pr.currency
          union all
          select rf.currency, 0::bigint, sum(rf.amount_minor)::bigint
          from public.refunds rf
          where rf.status = 'succeeded'
          group by rf.currency
        ) totals
        group by currency
      ) x
    ), '[]'::jsonb),
    'recent_orders', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', q.id,
        'order_number', q.order_number,
        'status', q.status,
        'payment_status', q.payment_status,
        'fulfillment_status', q.fulfillment_status,
        'currency', q.currency,
        'total_minor', q.total_minor,
        'placed_at', q.placed_at,
        'created_at', q.created_at
      ) order by q.created_at desc)
      from (
        select o.id,o.order_number,o.status,o.payment_status,o.fulfillment_status,o.currency,o.total_minor,o.placed_at,o.created_at
        from public.orders o
        order by o.created_at desc
        limit 10
      ) q
    ), '[]'::jsonb),
    'queues', jsonb_build_object(
      'producer_applications', coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'public_name',a.public_name,'status',a.status,'submitted_at',a.submitted_at,'village',a.production_village,'district',a.production_district,'province',a.production_province) order by coalesce(a.submitted_at,a.created_at)) from (select * from public.producer_applications where status in ('submitted','under_review','needs_information') order by coalesce(submitted_at,created_at) asc limit 10) a), '[]'::jsonb),
      'products', coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'producer_id',p.producer_id,'status',p.status,'updated_at',p.updated_at) order by p.updated_at) from (select * from public.products where status='review' and deleted_at is null order by updated_at asc limit 10) p), '[]'::jsonb),
      'returns', coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'return_number',r.return_number,'order_id',r.order_id,'status',r.status,'reason_code',r.reason_code,'requested_at',r.requested_at) order by r.requested_at) from (select * from public.return_requests where status in ('requested','under_review','approved','in_transit','received') order by requested_at asc limit 10) r), '[]'::jsonb),
      'reviews', coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'product_id',r.product_id,'rating',r.rating,'title',r.title,'created_at',r.created_at) order by r.created_at) from (select * from public.reviews where status='pending' order by created_at asc limit 10) r), '[]'::jsonb)
    )
  ) into result;

  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_operations_overview_v2()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare result jsonb; begin if not coalesce(private.has_permission('analytics.read'),false) then raise exception 'admin_required' using errcode='42501'; end if; select jsonb_build_object('generated_at',timezone('utc',now()),'counts',jsonb_build_object('members_total',(select count(*) from public.profiles p where p.deleted_at is null),'members_active',(select count(*) from public.profiles p where p.status='active' and p.deleted_at is null),'customers_active',(select count(*) from public.profiles p where p.status='active' and p.deleted_at is null and not exists(select 1 from private.user_roles ur where ur.user_id=p.id and ur.role in('producer','support','content_editor','operations','admin','super_admin') and (ur.expires_at is null or ur.expires_at>timezone('utc',now())))),'staff_users',(select count(distinct ur.user_id) from private.user_roles ur join public.profiles p on p.id=ur.user_id where ur.role in('support','content_editor','operations','admin','super_admin') and (ur.expires_at is null or ur.expires_at>timezone('utc',now())) and p.status='active' and p.deleted_at is null),'producer_role_users',(select count(distinct ur.user_id) from private.user_roles ur join public.profiles p on p.id=ur.user_id where ur.role='producer' and (ur.expires_at is null or ur.expires_at>timezone('utc',now())) and p.status='active' and p.deleted_at is null),'categories_total',(select count(*) from public.categories),'categories_active',(select count(*) from public.categories where is_active=true),'products_total',(select count(*) from public.products where deleted_at is null),'products_published',(select count(*) from public.products where status='published' and is_active=true and deleted_at is null),'producers_total',(select count(*) from public.producers where deleted_at is null),'verified_producers',(select count(*) from public.producers where status='active' and is_verified=true and deleted_at is null),'orders_total',(select count(*) from public.orders),'open_orders',(select count(*) from public.orders where status in('pending_payment','confirmed','preparing','partially_shipped','shipped','delivered')),'producer_applications',(select count(*) from public.producer_applications where status in('submitted','under_review','needs_information')),'product_reviews',(select count(*) from public.products where status='review' and deleted_at is null),'product_change_requests',(select count(*) from public.product_change_requests where status='pending'),'return_requests',(select count(*) from public.return_requests where status in('requested','under_review','approved','in_transit','received')),'review_moderation',(select count(*) from public.reviews where status='pending'),'support_conversations',(select count(*) from public.conversations where conversation_type='support' and status<>'closed'),'account_closures',(select count(*) from private.account_closure_requests where status in('requested','processing','ready_for_auth_deletion')),'producer_payouts',(select count(*) from private.producer_payouts where status in('scheduled','processing')),'settlements_waiting',(select count(distinct le.order_id) from private.producer_ledger_entries le join public.orders o on o.id=le.order_id where le.entry_type='sale' and le.availability_status='pending' and o.status='completed' and o.payment_status='paid'),'catalog_objects',(select count(*) from private.media_objects_all where bucket_id='catalog-public'),'content_objects',(select count(*) from private.media_objects_all where bucket_id='content-public'),'certificate_objects',(select count(*) from private.media_objects_all where bucket_id='product-certificates')),'finance_by_currency',coalesce((select jsonb_agg(jsonb_build_object('currency',c.currency,'captured_minor',coalesce(py.captured_minor,0),'refunded_minor',coalesce(rf.refunded_minor,0),'net_collected_minor',coalesce(py.captured_minor,0)-coalesce(rf.refunded_minor,0),'protected_pool_minor',coalesce(pl.protected_pool_minor,0),'approved_seller_minor',coalesce(pl.approved_seller_minor,0),'seller_pending_ledger_minor',coalesce(le.pending_minor,0),'seller_available_ledger_minor',coalesce(le.available_minor,0),'seller_paid_out_minor',coalesce(po.paid_minor,0)) order by c.currency) from (select currency from public.payment_records union select currency from public.refunds union select currency from private.producer_ledger_entries union select currency from private.producer_payouts)c left join(select currency,sum(amount_minor)::bigint captured_minor from public.payment_records where status in('captured','partially_refunded','refunded') group by currency)py using(currency) left join(select currency,sum(amount_minor)::bigint refunded_minor from public.refunds where status='succeeded' group by currency)rf using(currency) left join(select pr.currency,coalesce(sum(ps.submerchant_price_minor) filter(where ps.approval_status='pending'),0)::bigint protected_pool_minor,coalesce(sum(ps.submerchant_price_minor) filter(where ps.approval_status='approved'),0)::bigint approved_seller_minor from private.payment_item_splits ps join public.payment_records pr on pr.id=ps.payment_id where ps.order_id is not null group by pr.currency)pl using(currency) left join(select currency,coalesce(sum(producer_net_minor) filter(where availability_status='pending'),0)::bigint pending_minor,coalesce(sum(producer_net_minor) filter(where availability_status='available'),0)::bigint available_minor from private.producer_ledger_entries where entry_type='sale' group by currency)le using(currency) left join(select currency,coalesce(sum(amount_minor),0)::bigint paid_minor from private.producer_payouts where status='paid' group by currency)po using(currency)),'[]'::jsonb),'recent_orders',coalesce((select jsonb_agg(jsonb_build_object('id',q.id,'order_number',q.order_number,'status',q.status,'payment_status',q.payment_status,'fulfillment_status',q.fulfillment_status,'currency',q.currency,'total_minor',q.total_minor,'placed_at',q.placed_at,'created_at',q.created_at) order by q.created_at desc) from(select id,order_number,status,payment_status,fulfillment_status,currency,total_minor,placed_at,created_at from public.orders where accounting_archived_at is null order by created_at desc limit 10)q),'[]'::jsonb),'queues',jsonb_build_object('producer_applications',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'public_name',a.public_name,'status',a.status,'submitted_at',a.submitted_at,'village',a.production_village,'district',a.production_district,'province',a.production_province) order by coalesce(a.submitted_at,a.created_at)) from(select * from public.producer_applications where status in('submitted','under_review','needs_information') order by coalesce(submitted_at,created_at) asc limit 10)a),'[]'::jsonb),'products',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'producer_id',p.producer_id,'status',p.status,'updated_at',p.updated_at) order by p.updated_at) from(select * from public.products where status='review' and deleted_at is null order by updated_at asc limit 10)p),'[]'::jsonb),'returns',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'return_number',r.return_number,'order_id',r.order_id,'status',r.status,'reason_code',r.reason_code,'requested_at',r.requested_at) order by r.requested_at) from(select * from public.return_requests where status in('requested','under_review','approved','in_transit','received') order by requested_at asc limit 10)r),'[]'::jsonb),'reviews',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'product_id',r.product_id,'rating',r.rating,'title',r.title,'created_at',r.created_at) order by r.created_at) from(select * from public.reviews where status='pending' order by created_at asc limit 10)r),'[]'::jsonb))) into result; return result; end;$function$;

CREATE OR REPLACE FUNCTION private.admin_operations_overview_v3()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare payload jsonb; payout_count bigint;
begin
  payload:=private.admin_operations_overview_v2();
  select count(*) into payout_count from private.producer_payouts where status in('requested','scheduled','processing');
  return jsonb_set(payload,'{counts,producer_payouts}',to_jsonb(payout_count),true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_record_manual_payment_v1(p_order_id uuid, p_provider_reference text, p_payment_method_type text, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  target_order public.orders%rowtype;
begin
  if caller_id is null or not coalesce(private.has_permission('finance.manage'),false) then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  select * into target_order from public.orders where id=p_order_id;
  if target_order.id is null then raise exception 'order_not_found' using errcode='P0002'; end if;

  if lower(btrim(coalesce(p_payment_method_type,''))) not in ('bank_transfer','cash_on_delivery','other') then
    raise exception 'manual_payment_method_not_allowed' using errcode='22023';
  end if;
  if lower(btrim(coalesce(p_status,''))) not in ('authorized','captured','failed','cancelled') then
    raise exception 'invalid_manual_payment_status' using errcode='22023';
  end if;

  return private.apply_verified_payment_v1(
    target_order.id,
    'manual',
    p_provider_reference,
    p_payment_method_type,
    target_order.total_minor,
    target_order.currency,
    p_status,
    caller_id
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_record_manual_refund_v1(p_return_id uuid, p_payment_id uuid, p_provider_reference text, p_amount_minor bigint, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  payment public.payment_records%rowtype;
begin
  if caller_id is null or not private.has_permission('refund.execute') then raise exception 'permission_required:refund.execute' using errcode='42501'; end if;
  select * into payment from public.payment_records where id=p_payment_id;
  if payment.id is null then raise exception 'payment_not_found' using errcode='P0002'; end if;
  return private.apply_verified_refund_v1(p_return_id,p_payment_id,'manual',p_provider_reference,p_amount_minor,payment.currency,p_status,caller_id);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_record_product_organic_certificate_v1(p_product_id uuid, p_issuer text, p_certificate_number text, p_issued_at date, p_expires_at date, p_document_path text, p_review_confirmed boolean, p_review_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  issuer_value text:=btrim(coalesce(p_issuer,''));
  number_value text:=btrim(coalesce(p_certificate_number,''));
  document_value text:=private.verified_product_certificate_path_v1(p_document_path);
  note_value text:=nullif(btrim(coalesce(p_review_note,'')),'');
  certification_id uuid;
begin
  if caller_id is null or not coalesce(private.has_permission('product.moderate'),false) then raise exception 'admin_required' using errcode='42501'; end if;
  if not coalesce(p_review_confirmed,false) then raise exception 'certificate_manual_review_required' using errcode='22023'; end if;
  if not exists(select 1 from public.products p join public.producers pr on pr.id=p.producer_id where p.id=p_product_id and p.deleted_at is null and pr.status='active' and pr.is_verified=true and pr.deleted_at is null) then raise exception 'verified_product_required' using errcode='55000'; end if;
  if char_length(issuer_value) not between 2 and 180 or char_length(number_value) not between 2 and 120 then raise exception 'invalid_certificate_identity' using errcode='22023'; end if;
  if p_issued_at is null or p_expires_at is null or p_issued_at>current_date or p_expires_at<current_date or p_expires_at<p_issued_at then raise exception 'invalid_certificate_dates' using errcode='22023'; end if;
  if document_value is null then raise exception 'stored_certificate_document_required' using errcode='55000'; end if;
  if document_value not like 'admin/'||caller_id::text||'/%' then raise exception 'admin_owned_certificate_document_required' using errcode='42501'; end if;
  if note_value is not null and char_length(note_value)>2000 then raise exception 'certificate_review_note_too_long' using errcode='22023'; end if;
  update public.product_certifications set status='revoked' where product_id=p_product_id and status='valid' and lower(certificate_type) in ('organic','organic_certificate','certified_organic');
  insert into public.product_certifications(product_id,certificate_type,issuer,certificate_number,issued_at,expires_at,verification_url,status)
  values(p_product_id,'organic',issuer_value,number_value,p_issued_at,p_expires_at,null,'valid') returning id into certification_id;
  insert into private.product_certification_documents(certification_id,storage_path,submitted_by,reviewed_by,review_note)
  values(certification_id,document_value,caller_id,caller_id,note_value);
  return jsonb_build_object('id',certification_id,'productId',p_product_id,'status','valid','certificateType','organic','expiresAt',p_expires_at);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_review_producer_application_v3(p_application_id uuid, p_status text, p_reason text, p_commission_basis_points integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); application public.producer_applications%rowtype; result jsonb; producer_id uuid; product_item jsonb; review_due timestamptz;
begin
  if caller_id is null or not coalesce(private.has_permission('seller.review'),false) then raise exception 'permission_required:seller.review' using errcode='42501'; end if;
  if p_status='approved' and not private.has_permission('seller.approve') then raise exception 'permission_required:seller.approve' using errcode='42501'; elsif p_status='rejected' and not private.has_permission('seller.reject') then raise exception 'permission_required:seller.reject' using errcode='42501'; elsif p_status='needs_information' and not private.has_permission('seller.request_information') then raise exception 'permission_required:seller.request_information' using errcode='42501'; end if;
  select * into application from public.producer_applications where id=p_application_id;
  if application.id is null then raise exception 'producer_application_not_found' using errcode='P0002'; end if;
  if p_status='approved' then
    if cardinality(application.activity_types)=0 then raise exception 'producer_activity_required' using errcode='55000'; end if;
    if cardinality(application.product_categories)=0 then raise exception 'producer_category_scope_required' using errcode='55000'; end if;
    if cardinality(application.sourcing_models)=0 or not (application.sourcing_models <@ array['own_production','family_production','cooperative_production']::text[]) then raise exception 'producer_intermediary_source_not_allowed' using errcode='55000'; end if;
    if exists(select 1 from unnest(application.product_categories) slug where not exists(select 1 from public.categories c where c.slug=slug and c.is_active=true)) then raise exception 'invalid_producer_category_scope' using errcode='55000'; end if;
    for product_item in select value from jsonb_array_elements(application.planned_products) loop
      if not (coalesce(product_item->>'category','')=any(application.product_categories)) then raise exception 'planned_product_outside_category_scope' using errcode='55000'; end if;
    end loop;
  end if;
  if p_status='approved' and application.organic_claim_status='certified' then
    if application.organic_certificate_expires_on is null or application.organic_certificate_expires_on<current_date then raise exception 'organic_certificate_expired' using errcode='55000'; end if;
    if not exists(select 1 from private.producer_documents d where d.application_id=p_application_id and d.document_type='organic_certificate' and d.verification_status='verified') then raise exception 'organic_certificate_document_not_verified' using errcode='55000'; end if;
  end if;
  result:=public.admin_review_producer_application_v2(p_application_id,p_status,p_reason,p_commission_basis_points);
  if p_status='approved' then
    producer_id:=(result->>'producer_id')::uuid;
    if producer_id is not null then
      update public.producers producer set
        status='pending',storefront_status='draft',storefront_published_at=null,storefront_published_by=null,
        production_country_code=application.production_country_code,production_province=application.production_province,
        production_district=application.production_district,production_village=application.production_village,production_village_is_custom=application.production_village_is_custom,
        production_latitude=application.production_latitude,production_longitude=application.production_longitude,origin_verified=true,origin_verified_at=timezone('utc',now()),
        origin_verification_basis='application_review',activity_types=application.activity_types,approved_category_slugs=application.product_categories,
        trust_badge_status='active',trust_badge_granted_at=timezone('utc',now()),trust_badge_review_due_at=coalesce(producer.verification_due_at,timezone('utc',now())+interval '365 days'),
        trust_badge_revoked_at=null,trust_badge_reason='KYC, üretim menşei, faaliyet alanı ve kategori kapsamı yönetim tarafından onaylandı.',updated_at=timezone('utc',now())
      where producer.id=producer_id returning trust_badge_review_due_at into review_due;
      insert into private.producer_trust_badge_events(producer_id,actor_user_id,action,reason,review_due_at)
      values(producer_id,caller_id,'granted','KYC, üretim menşei, faaliyet alanı ve kategori kapsamı yönetim tarafından onaylandı.',review_due);
      update public.notifications n set title='Satıcı başvurunuz onaylandı',message='Doğrulamanız tamamlandı. Mağaza adınızı, profil ve kapak görsellerinizi, iletişim, adres ve işletme bilgilerinizi tamamlayıp mağazanızı yayınladıktan sonra ürün ekleyebilirsiniz.',action_url='/?tab=account'
      where n.id=(select n2.id from public.notifications n2 where n2.user_id=application.applicant_user_id and n2.metadata->>'application_id'=application.id::text and n2.metadata->>'status'='approved' order by n2.created_at desc limit 1);
      insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
      values('storefront',producer_id,'storefront.setup_required',jsonb_build_object('producerId',producer_id,'applicationId',application.id,'ownerUserId',application.applicant_user_id));
    end if;
  end if;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_review_producer_event_submission_v1(p_submission_id uuid, p_decision text, p_reason text DEFAULT NULL::text, p_commission_basis_points integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  decision_value text:=lower(btrim(coalesce(p_decision,'')));
  reason_value text:=nullif(btrim(coalesce(p_reason,'')),'');
  submission private.producer_event_submissions%rowtype;
  producer public.producers%rowtype;
  event_row public.events%rowtype;
  commission_value integer;
  slug_value text;
begin
  if caller_id is null or not private.has_permission('event.moderate') then raise exception 'permission_required:event.moderate' using errcode='42501'; end if; if p_commission_basis_points is not null and not private.has_permission('finance.manage') then raise exception 'permission_required:finance.manage' using errcode='42501'; end if;
  if decision_value not in ('approve','reject','needs_changes') then raise exception 'invalid_event_review_decision' using errcode='22023'; end if;
  if decision_value<>'approve' and char_length(coalesce(reason_value,''))<8 then raise exception 'event_review_reason_required' using errcode='22023'; end if;
  if reason_value is not null and char_length(reason_value)>2000 then raise exception 'event_review_reason_too_long' using errcode='22023'; end if;
  select * into submission from private.producer_event_submissions where id=p_submission_id for update;
  if submission.id is null or submission.status not in ('pending','needs_changes') then raise exception 'event_submission_not_reviewable' using errcode='55000'; end if;
  select * into producer from public.producers where id=submission.producer_id and deleted_at is null;
  if producer.id is null then raise exception 'producer_not_found' using errcode='P0002'; end if;
  commission_value:=coalesce(p_commission_basis_points,submission.requested_commission_basis_points,producer.commission_basis_points);
  if commission_value not between 0 and 10000 then raise exception 'invalid_event_commission' using errcode='22023'; end if;
  if decision_value='approve' then
    if not private.is_producer_trust_badge_active_v1(producer.id) then raise exception 'producer_trust_badge_required' using errcode='55000'; end if;
    if producer.status<>'active' or producer.is_verified is not true or producer.origin_verified is not true then raise exception 'producer_not_event_eligible' using errcode='55000'; end if;
    if submission.starts_at<=timezone('utc',now()) then raise exception 'event_start_must_be_future' using errcode='55000'; end if;
    if submission.image_path is not null and private.verified_public_storage_path_v1('event-public',submission.image_path) is null then raise exception 'stored_event_image_required' using errcode='55000'; end if;
    slug_value:=private.slugify_tr_v1(submission.title);
    if exists(select 1 from public.events where slug=slug_value) then slug_value:=slug_value||'-'||substr(gen_random_uuid()::text,1,8); end if;
    insert into public.events(slug,title,description,image_path,location_name,location_details,starts_at,ends_at,capacity,reservation_deadline,status,producer_id,event_submission_id,ticket_price_minor,currency,platform_commission_basis_points,sale_mode)
    values(slug_value,submission.title,submission.description,submission.image_path,submission.location_name,submission.location_details,submission.starts_at,submission.ends_at,submission.capacity,submission.reservation_deadline,'published',producer.id,submission.id,submission.ticket_price_minor,submission.currency,commission_value,case when submission.ticket_price_minor>0 then 'ticketed' else 'reservation' end)
    returning * into event_row;
    update private.producer_event_submissions set status='approved',approved_commission_basis_points=commission_value,review_reason=reason_value,reviewed_by=caller_id,reviewed_at=timezone('utc',now()),event_id=event_row.id,updated_at=timezone('utc',now()) where id=submission.id;
  else
    update private.producer_event_submissions set status=case when decision_value='reject' then 'rejected' else 'needs_changes' end,review_reason=reason_value,reviewed_by=caller_id,reviewed_at=timezone('utc',now()),updated_at=timezone('utc',now()) where id=submission.id;
  end if;
  insert into public.notifications(user_id,type,title,message,action_url,metadata)
  values(
    producer.owner_user_id,'producer',
    case when decision_value='approve' then 'Etkinliğiniz onaylandı ve yayınlandı' when decision_value='needs_changes' then 'Etkinlik başvurunuz için düzeltme gerekiyor' else 'Etkinlik başvurunuz reddedildi' end,
    case when decision_value='approve' then submission.title||' etkinliği Golden Oremar etkinliklerinde yayınlandı.' else submission.title||' etkinliği için yönetim notu: '||reason_value||case when decision_value='needs_changes' then ' Düzeltip yeniden gönderebilirsiniz.' else '' end end,
    '/?tab=account',jsonb_build_object('eventSubmissionId',submission.id,'decision',decision_value,'reason',reason_value,'eventId',event_row.id)
  );
  return jsonb_build_object('id',submission.id,'decision',decision_value,'status',case when decision_value='approve' then 'approved' when decision_value='reject' then 'rejected' else 'needs_changes' end,'eventId',event_row.id,'commissionBasisPoints',commission_value,'reason',reason_value);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_review_producer_location_change_v1(p_request_id uuid, p_approve boolean, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.producer_location_change_requests%rowtype; admin_id uuid:=auth.uid();
begin
  if not coalesce(private.has_permission('seller.review'),false) then raise exception 'admin_required' using errcode='42501'; end if;
  select * into r from public.producer_location_change_requests where id=p_request_id and status='pending' for update;
  if r.id is null then raise exception 'location_change_request_not_pending' using errcode='P0002'; end if;
  if not coalesce(p_approve,false) and char_length(btrim(coalesce(p_reason,''))) < 5 then raise exception 'review_reason_required' using errcode='22023'; end if;
  if coalesce(p_approve,false) then
    update public.producers set
      production_country_code=r.country_code, production_province=r.province, production_district=r.district,
      production_village=r.village, production_village_is_custom=r.village_is_custom,
      production_latitude=r.latitude, production_longitude=r.longitude,
      production_location=r.village||', '||r.district||', '||r.province||', '||r.country_code,
      latitude=r.latitude, longitude=r.longitude, updated_at=timezone('utc',now())
    where id=r.producer_id;
  end if;
  update public.producer_location_change_requests set status=case when coalesce(p_approve,false) then 'approved' else 'rejected' end,
    reviewed_by=admin_id, reviewed_at=timezone('utc',now()), review_reason=nullif(btrim(coalesce(p_reason,'')),''), updated_at=timezone('utc',now())
  where id=r.id;
  return jsonb_build_object('request_id',r.id,'status',case when coalesce(p_approve,false) then 'approved' else 'rejected' end);
end; $function$;

CREATE OR REPLACE FUNCTION private.admin_review_product_batch_v1(p_batch_id uuid, p_status text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := (select auth.uid());
  batch_row public.product_batches%rowtype;
  normalized_reason text := btrim(coalesce(p_reason, ''));
begin
  if caller_id is null or not coalesce(private.has_permission('product.moderate'),false) then raise exception 'admin_required' using errcode = '42501'; end if;
  if p_status not in ('released','rejected','recalled') then raise exception 'invalid_batch_review_status' using errcode = '22023'; end if;
  select batch.* into batch_row from public.product_batches batch where batch.id = p_batch_id for update;
  if batch_row.id is null then raise exception 'batch_not_found' using errcode = 'P0002'; end if;
  if p_status = 'released' then
    if batch_row.status <> 'review' then raise exception 'batch_not_ready_for_release' using errcode = '55000'; end if;
    if not exists (
      select 1 from public.products product
      join public.producers producer on producer.id = product.producer_id
      where product.id = batch_row.product_id
        and product.status = 'published' and product.is_active = true and product.deleted_at is null
        and producer.id = batch_row.producer_id and producer.status = 'active' and producer.is_verified = true and producer.deleted_at is null
    ) then raise exception 'batch_product_or_producer_not_public' using errcode = '55000'; end if;
    update public.product_batches
    set status = 'released', review_reason = null, reviewed_by = caller_id,
        reviewed_at = timezone('utc', now()), released_at = timezone('utc', now()), recalled_at = null
    where id = batch_row.id;
    insert into public.product_batch_events(batch_id, event_type, event_at, public_note, visibility, actor_user_id)
    values (batch_row.id, 'released', timezone('utc', now()), 'Parti bilgileri Golden Oremar doğrulama sürecinden geçti ve yayımlandı.', 'public', caller_id);
  elsif p_status = 'rejected' then
    if batch_row.status <> 'review' then raise exception 'batch_not_under_review' using errcode = '55000'; end if;
    if char_length(normalized_reason) not between 10 and 1000 then raise exception 'batch_review_reason_required' using errcode = '22023'; end if;
    update public.product_batches
    set status = 'rejected', review_reason = normalized_reason, reviewed_by = caller_id, reviewed_at = timezone('utc', now())
    where id = batch_row.id;
  else
    if batch_row.status <> 'released' then raise exception 'only_released_batch_can_be_recalled' using errcode = '55000'; end if;
    if char_length(normalized_reason) not between 10 and 1000 then raise exception 'batch_recall_reason_required' using errcode = '22023'; end if;
    update public.product_batches
    set status = 'recalled', review_reason = normalized_reason, reviewed_by = caller_id,
        reviewed_at = timezone('utc', now()), recalled_at = timezone('utc', now())
    where id = batch_row.id;
    insert into public.product_batch_events(batch_id, event_type, event_at, public_note, visibility, actor_user_id)
    values (batch_row.id, 'recalled', timezone('utc', now()), normalized_reason, 'public', caller_id);
  end if;
  insert into private.outbox_events(aggregate_type, aggregate_id, event_type, payload)
  values ('product_batch', batch_row.id, 'product_batch.' || p_status, jsonb_build_object('batch_id', batch_row.id, 'status', p_status, 'reviewed_by', caller_id));
  return jsonb_build_object('batch_id', batch_row.id, 'status', p_status, 'trace_code', batch_row.trace_code);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_review_product_change_v1(p_change_request_id uuid, p_approve boolean, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  request_row public.product_change_requests%rowtype;
  product_row public.products%rowtype;
  producer_owner uuid;
  reason_value text:=nullif(btrim(coalesce(p_reason,'')),'');
  apply_result jsonb;
begin
  if caller_id is null or not coalesce(private.has_permission('product.moderate'),false) then raise exception 'admin_required' using errcode='42501'; end if;
  select * into request_row from public.product_change_requests where id=p_change_request_id for update;
  if request_row.id is null or request_row.status<>'pending' then raise exception 'pending_product_change_not_found' using errcode='P0002'; end if;
  if not coalesce(p_approve,false) and char_length(coalesce(reason_value,''))<8 then raise exception 'product_change_rejection_reason_required' using errcode='22023'; end if;
  if reason_value is not null and char_length(reason_value)>2000 then raise exception 'product_change_reason_too_long' using errcode='22023'; end if;

  perform private.validate_product_change_payload_v1(request_row.product_id,request_row.producer_id,request_row.requested_by,request_row.proposed_payload);
  select * into product_row from public.products where id=request_row.product_id for update;
  if product_row.status<>'published' then raise exception 'product_no_longer_published' using errcode='55000'; end if;

  if coalesce(p_approve,false) then
    apply_result:=private.management_upsert_product_core_v1(product_row.id::text,request_row.proposed_payload);
    update public.product_change_requests set status='approved',review_reason=reason_value,reviewed_by=caller_id,reviewed_at=timezone('utc',now()),updated_at=timezone('utc',now()) where id=request_row.id;
  else
    update public.product_change_requests set status='rejected',review_reason=reason_value,reviewed_by=caller_id,reviewed_at=timezone('utc',now()),updated_at=timezone('utc',now()) where id=request_row.id;
  end if;

  insert into private.product_moderation_events(product_id,change_request_id,producer_id,actor_user_id,decision,reason)
  values(product_row.id,request_row.id,request_row.producer_id,caller_id,case when coalesce(p_approve,false) then 'change_approved' else 'change_rejected' end,reason_value);

  select owner_user_id into producer_owner from public.producers where id=request_row.producer_id;
  if producer_owner is not null then
    insert into public.notifications(user_id,type,title,message,action_url,metadata)
    values(
      producer_owner,
      'producer',
      case when coalesce(p_approve,false) then 'Ürün değişikliğiniz onaylandı' else 'Ürün değişikliğiniz için düzeltme gerekiyor' end,
      case when coalesce(p_approve,false)
        then product_row.name||' ürünü için gönderdiğiniz değişiklikler onaylandı ve yayındaki ürüne uygulandı.'
        else product_row.name||' ürünü için gönderdiğiniz değişiklik onaylanmadı. Ret nedeni: '||reason_value||' Düzelterek yeniden gönderebilirsiniz.'
      end,
      '/producer/products',
      jsonb_build_object('productId',product_row.id,'changeRequestId',request_row.id,'approved',coalesce(p_approve,false),'reason',reason_value,'canResubmit',not coalesce(p_approve,false))
    );
  end if;

  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
  values('product_change_request',request_row.id,case when coalesce(p_approve,false) then 'product_change.approved' else 'product_change.rejected' end,
    jsonb_build_object('change_request_id',request_row.id,'product_id',product_row.id,'reviewed_by',caller_id,'reason',reason_value));
  return jsonb_build_object('changeRequestId',request_row.id,'productId',product_row.id,'status',case when coalesce(p_approve,false) then 'approved' else 'rejected' end,'reason',reason_value,'result',apply_result);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_review_product_change_v2(p_change_request_id uuid, p_approve boolean, p_reason text, p_ownership_checked boolean, p_image_checked boolean, p_scope_checked boolean, p_origin_checked boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare cr public.product_change_requests%rowtype; producer public.producers%rowtype; product public.products%rowtype; proposed_category text;
begin
  if auth.uid() is null or not coalesce(private.has_permission('product.moderate'),false) then raise exception 'admin_required' using errcode='42501'; end if;
  select * into cr from public.product_change_requests where id=p_change_request_id and status='pending';
  if cr.id is null then raise exception 'pending_product_change_not_found' using errcode='P0002'; end if;
  select * into product from public.products where id=cr.product_id and deleted_at is null;
  select * into producer from public.producers where id=cr.producer_id and deleted_at is null;
  if coalesce(p_approve,false) then
    if p_ownership_checked is not true or p_image_checked is not true or p_scope_checked is not true or p_origin_checked is not true then raise exception 'product_moderation_checklist_required' using errcode='22023'; end if;
    if not private.is_producer_trust_badge_active_v1(cr.producer_id) then raise exception 'producer_trust_badge_required' using errcode='55000'; end if;
    if cr.proposed_payload ? 'category' or cr.proposed_payload ? 'categoryId' then
      select c.slug into proposed_category from public.categories c where c.is_active=true and (c.slug=coalesce(nullif(cr.proposed_payload->>'category',''),cr.proposed_payload->>'categoryId') or c.id::text=coalesce(nullif(cr.proposed_payload->>'categoryId',''),cr.proposed_payload->>'category')) limit 1;
    else
      select c.slug into proposed_category from public.categories c where c.id=product.category_id;
    end if;
    if proposed_category is null or not (proposed_category=any(producer.approved_category_slugs)) then raise exception 'product_category_outside_producer_scope' using errcode='55000'; end if;
    if lower(btrim(coalesce(cr.proposed_payload->>'origin',producer.production_location,'')))<>lower(btrim(coalesce(producer.production_location,''))) then raise exception 'product_origin_mismatch' using errcode='55000'; end if;
  end if;
  return private.admin_review_product_change_v1(p_change_request_id,p_approve,p_reason);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_review_product_change_v3(p_change_request_id uuid, p_approve boolean, p_reason text, p_ownership_checked boolean, p_image_checked boolean, p_scope_checked boolean, p_origin_checked boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); product_id uuid; result jsonb; editorial_result jsonb;
begin
  if caller_id is null or not coalesce(private.has_permission('product.moderate'),false) then raise exception 'permission_required:product.moderate' using errcode='42501'; end if;
  if coalesce(p_approve,false) then
    if not private.has_permission('product.approve') then raise exception 'permission_required:product.approve' using errcode='42501'; end if;
    if not private.has_permission('product.publish') then raise exception 'permission_required:product.publish' using errcode='42501'; end if;
  elsif not private.has_permission('product.reject') then raise exception 'permission_required:product.reject' using errcode='42501'; end if;
  select cr.product_id into product_id from public.product_change_requests cr where cr.id=p_change_request_id and cr.status='pending';
  if product_id is null then raise exception 'pending_product_change_not_found' using errcode='P0002'; end if;
  if coalesce(p_approve,false) and not exists(select 1 from private.product_editorial_drafts d where d.product_id=product_id and d.locale='tr' and d.status='review') then raise exception 'product_editorial_review_required' using errcode='55000'; end if;
  if coalesce(p_approve,false) and not exists(select 1 from public.content_entries e where e.related_product_id=product_id and e.content_type='product_health' and e.locale='tr' and e.status='published' and e.deleted_at is null) then raise exception 'published_product_health_required' using errcode='55000'; end if;
  result:=private.admin_review_product_change_v2(p_change_request_id,p_approve,p_reason,p_ownership_checked,p_image_checked,p_scope_checked,p_origin_checked);
  editorial_result:=private.review_product_editorial_with_product_v1(product_id,p_approve,p_reason,caller_id);
  return result||jsonb_build_object('editorialReview',editorial_result);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_review_product_v1(p_product_id uuid, p_approve boolean, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  product_row public.products%rowtype;
  producer_row public.producers%rowtype;
  reason_value text:=nullif(btrim(coalesce(p_reason,'')),'');
  result jsonb;
begin
  if caller_id is null or not coalesce(private.has_permission('product.moderate'),false) then raise exception 'admin_required' using errcode='42501'; end if;
  select * into product_row from public.products where id=p_product_id for update;
  if product_row.id is null or product_row.status not in ('review','rejected') then raise exception 'product_not_reviewable' using errcode='55000'; end if;
  select * into producer_row from public.producers where id=product_row.producer_id and deleted_at is null;
  if producer_row.id is null or producer_row.status<>'active' or not producer_row.is_verified then raise exception 'verified_active_producer_required' using errcode='55000'; end if;

  if coalesce(p_approve,false) then
    if product_row.status<>'review' then raise exception 'rejected_product_must_be_resubmitted' using errcode='55000'; end if;
    if char_length(btrim(product_row.name))<2 or char_length(btrim(product_row.description))<20 or char_length(btrim(product_row.story))<20 or char_length(btrim(coalesce(product_row.origin,'')))<2 then
      raise exception 'product_content_incomplete' using errcode='55000';
    end if;
    if not exists(select 1 from public.product_variants variant where variant.product_id=product_row.id and variant.is_active=true and variant.price_minor>0) then raise exception 'active_priced_variant_required' using errcode='55000'; end if;
    if not exists(select 1 from public.product_images image where image.product_id=product_row.id and image.is_primary=true) then raise exception 'primary_product_image_required' using errcode='55000'; end if;
    result:=private.management_upsert_product_core_v1(product_row.id::text,jsonb_build_object('is_approved',true));
  else
    if char_length(coalesce(reason_value,''))<8 then raise exception 'product_rejection_reason_required' using errcode='22023'; end if;
    if char_length(reason_value)>2000 then raise exception 'product_rejection_reason_too_long' using errcode='22023'; end if;
    result:=private.management_upsert_product_core_v1(product_row.id::text,jsonb_build_object('is_rejected',true,'rejection_reason',reason_value));
  end if;

  insert into public.notifications(user_id,type,title,message,action_url,metadata)
  values(producer_row.owner_user_id,'producer',case when coalesce(p_approve,false) then 'Ürününüz yayınlandı' else 'Ürün incelemeniz sonuçlandı' end,
    case when coalesce(p_approve,false) then product_row.name||' Golden Oremar kataloğunda yayınlandı.' else product_row.name||' için düzeltme gerekiyor.' end,
    '/producer/products',jsonb_build_object('productId',product_row.id,'approved',coalesce(p_approve,false),'reason',reason_value));
  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
  values('product',product_row.id,case when coalesce(p_approve,false) then 'product.published' else 'product.rejected' end,
    jsonb_build_object('product_id',product_row.id,'producer_id',product_row.producer_id,'reviewed_by',caller_id,'reason',reason_value));
  return result||jsonb_build_object('reviewed',true,'approved',coalesce(p_approve,false));
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_review_product_v2(p_product_id uuid, p_approve boolean, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  product_row public.products%rowtype;
  producer_row public.producers%rowtype;
  reason_value text:=nullif(btrim(coalesce(p_reason,'')),'');
  result jsonb;
begin
  if caller_id is null or not coalesce(private.has_permission('product.moderate'),false) then raise exception 'admin_required' using errcode='42501'; end if;
  if p_product_id is null then raise exception 'product_required' using errcode='22023'; end if;
  select * into product_row from public.products where id=p_product_id for update;
  if product_row.id is null or product_row.status not in ('review','rejected') then raise exception 'product_not_reviewable' using errcode='55000'; end if;
  select * into producer_row from public.producers where id=product_row.producer_id and deleted_at is null;
  if producer_row.id is null or producer_row.status<>'active' or not producer_row.is_verified then raise exception 'verified_active_producer_required' using errcode='55000'; end if;

  if coalesce(p_approve,false) then
    if product_row.status<>'review' then raise exception 'rejected_product_must_be_resubmitted' using errcode='55000'; end if;
    if char_length(btrim(product_row.name))<2 or char_length(btrim(product_row.description))<20 or char_length(btrim(product_row.story))<20 or char_length(btrim(coalesce(product_row.origin,'')))<2 then raise exception 'product_content_incomplete' using errcode='55000'; end if;
    if not exists(select 1 from public.product_variants variant where variant.product_id=product_row.id and variant.is_active=true and variant.price_minor>0) then raise exception 'active_priced_variant_required' using errcode='55000'; end if;
    if not private.product_media_integrity_ok_v1(product_row.id) then raise exception 'product_media_integrity_failed' using errcode='55000'; end if;
    result:=private.management_upsert_product_core_v1(product_row.id::text,jsonb_build_object('is_approved',true,'is_active',true));
    update public.products set specifications=specifications-'rejectionReason',updated_at=timezone('utc',now()) where id=product_row.id;
  else
    if char_length(coalesce(reason_value,''))<8 then raise exception 'product_rejection_reason_required' using errcode='22023'; end if;
    if char_length(reason_value)>2000 then raise exception 'product_rejection_reason_too_long' using errcode='22023'; end if;
    result:=private.management_upsert_product_core_v1(product_row.id::text,jsonb_build_object('is_rejected',true,'rejection_reason',reason_value));
  end if;

  insert into private.product_moderation_events(product_id,producer_id,actor_user_id,decision,reason)
  values(product_row.id,product_row.producer_id,caller_id,case when coalesce(p_approve,false) then 'approved' else 'rejected' end,reason_value);

  if producer_row.store_kind='producer' and producer_row.owner_user_id is not null then
    insert into public.notifications(user_id,type,title,message,action_url,metadata)
    values(
      producer_row.owner_user_id,'producer',
      case when coalesce(p_approve,false) then 'Ürününüz onaylandı ve yayınlandı' else 'Ürününüz için düzeltme gerekiyor' end,
      case when coalesce(p_approve,false)
        then product_row.name||' ürünü Super Admin onayından geçti ve Golden Oremar mağazanızda yayınlandı.'
        else product_row.name||' ürünü henüz yayınlanmadı. Ret nedeni: '||reason_value||' Ürünü düzeltip yeniden incelemeye gönderebilirsiniz.' end,
      '/producer/products',
      jsonb_build_object('productId',product_row.id,'approved',coalesce(p_approve,false),'reason',reason_value,'canResubmit',not coalesce(p_approve,false))
    );
  end if;

  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
  values('product',product_row.id,case when coalesce(p_approve,false) then 'product.published' else 'product.rejected' end,
    jsonb_build_object('product_id',product_row.id,'producer_id',product_row.producer_id,'reviewed_by',caller_id,'reason',reason_value));
  return result||jsonb_build_object('reviewed',true,'approved',coalesce(p_approve,false),'reason',reason_value);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_review_product_v3(p_product_id uuid, p_approve boolean, p_reason text, p_ownership_checked boolean, p_image_checked boolean, p_scope_checked boolean, p_origin_checked boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  product_row public.products%rowtype;
  producer public.producers%rowtype;
  category_slug text;
  clean_reason text := nullif(btrim(coalesce(p_reason, '')), '');
begin
  if auth.uid() is null
     or not coalesce(private.has_permission('product.moderate'), false) then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  select *
  into product_row
  from public.products
  where id = p_product_id
    and deleted_at is null
  for update;

  if product_row.id is null
     or product_row.status not in ('review', 'rejected') then
    raise exception 'product_not_reviewable' using errcode = '55000';
  end if;

  select *
  into producer
  from public.producers
  where id = product_row.producer_id
    and deleted_at is null;

  if producer.id is null then
    raise exception 'product_producer_not_found' using errcode = '55000';
  end if;

  select c.slug
  into category_slug
  from public.categories c
  where c.id = product_row.category_id
    and c.is_active = true;

  if coalesce(p_approve, false) then
    if p_ownership_checked is not true
       or p_image_checked is not true
       or p_scope_checked is not true
       or p_origin_checked is not true then
      raise exception 'product_moderation_checklist_required' using errcode = '22023';
    end if;

    if not private.is_producer_trust_badge_active_v1(product_row.producer_id) then
      raise exception 'producer_trust_badge_required' using errcode = '55000';
    end if;

    -- Every approved product still requires a real active category. Only the
    -- independent-producer program is constrained by approved_category_slugs.
    if category_slug is null then
      raise exception 'product_category_inactive_or_missing' using errcode = '55000';
    end if;

    if coalesce(producer.store_kind, '') <> 'official'
       and not (category_slug = any(producer.approved_category_slugs)) then
      raise exception 'product_category_outside_producer_scope' using errcode = '55000';
    end if;

    if lower(btrim(coalesce(product_row.origin, '')))
       <> lower(btrim(coalesce(producer.production_location, ''))) then
      raise exception 'product_origin_mismatch' using errcode = '55000';
    end if;
  end if;

  return private.admin_review_product_v2(
    p_product_id,
    p_approve,
    clean_reason
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_review_product_v4(p_product_id uuid, p_approve boolean, p_reason text, p_ownership_checked boolean, p_image_checked boolean, p_scope_checked boolean, p_origin_checked boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); result jsonb; editorial_result jsonb;
begin
  if caller_id is null or not coalesce(private.has_permission('product.moderate'),false) then raise exception 'permission_required:product.moderate' using errcode='42501'; end if;
  if coalesce(p_approve,false) then
    if not private.has_permission('product.approve') then raise exception 'permission_required:product.approve' using errcode='42501'; end if;
    if not private.has_permission('product.publish') then raise exception 'permission_required:product.publish' using errcode='42501'; end if;
  elsif not private.has_permission('product.reject') then raise exception 'permission_required:product.reject' using errcode='42501'; end if;
  if coalesce(p_approve,false) and not exists(select 1 from private.product_editorial_drafts d where d.product_id=p_product_id and d.locale='tr' and d.status='review') then raise exception 'product_editorial_review_required' using errcode='55000'; end if;
  if coalesce(p_approve,false) and not exists(select 1 from public.content_entries e where e.related_product_id=p_product_id and e.content_type='product_health' and e.locale='tr' and e.status='published' and e.deleted_at is null) then raise exception 'published_product_health_required' using errcode='55000'; end if;
  result:=private.admin_review_product_v3(p_product_id,p_approve,p_reason,p_ownership_checked,p_image_checked,p_scope_checked,p_origin_checked);
  editorial_result:=private.review_product_editorial_with_product_v1(p_product_id,p_approve,p_reason,caller_id);
  return result||jsonb_build_object('editorialReview',editorial_result);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_revoke_product_certification_v1(p_certification_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare reason_value text:=btrim(coalesce(p_reason,'')); product_id uuid;
begin
  if auth.uid() is null or not coalesce(private.has_permission('product.moderate'),false) then raise exception 'admin_required' using errcode='42501'; end if;
  if char_length(reason_value) not between 8 and 2000 then raise exception 'certificate_revocation_reason_required' using errcode='22023'; end if;
  update public.product_certifications set status='revoked' where id=p_certification_id and status='valid' returning product_certifications.product_id into product_id;
  if product_id is null then raise exception 'valid_certificate_not_found' using errcode='P0002'; end if;
  update private.product_certification_documents set review_note=reason_value,reviewed_by=auth.uid(),reviewed_at=timezone('utc',now()) where certification_id=p_certification_id;
  return jsonb_build_object('id',p_certification_id,'productId',product_id,'status','revoked');
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_schedule_producer_payout_v1(p_producer_id uuid, p_currency text, p_amount_minor bigint, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  producer_row public.producers%rowtype;
  currency_code text:=upper(btrim(coalesce(p_currency,'')));
  balance jsonb;
  available bigint;
  payout_row private.producer_payouts%rowtype;
begin
  if caller_id is null or not private.has_permission('payout.review') then raise exception 'permission_required:payout.review' using errcode='42501'; end if;
  if currency_code !~ '^[A-Z]{3}$' or p_amount_minor is null or p_amount_minor<=0 then raise exception 'invalid_payout_request' using errcode='22023'; end if;
  if char_length(coalesce(p_note,''))>1000 then raise exception 'payout_note_too_long' using errcode='22023'; end if;
  select * into producer_row from public.producers where id=p_producer_id and deleted_at is null for update;
  if producer_row.id is null then raise exception 'producer_not_found' using errcode='P0002'; end if;
  balance:=private.get_producer_balance_v1(producer_row.id,currency_code);
  available:=(balance->>'availableToPayoutMinor')::bigint;
  if p_amount_minor>available then raise exception 'payout_exceeds_available_balance' using errcode='22023'; end if;
  insert into private.producer_payouts(producer_id,currency,amount_minor,status,note,created_by)
  values(producer_row.id,currency_code,p_amount_minor,'scheduled',nullif(btrim(coalesce(p_note,'')),''),caller_id)
  returning * into payout_row;
  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
  values('producer_payout',payout_row.id,'producer_payout.scheduled',jsonb_build_object('payout_id',payout_row.id,'producer_id',producer_row.id,'currency',currency_code,'amount_minor',p_amount_minor,'actor_user_id',caller_id));
  return jsonb_build_object('id',payout_row.id,'producerId',producer_row.id,'currency',currency_code,'amountMinor',p_amount_minor,'status',payout_row.status);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_session_status_impl_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid(); roles jsonb; baseline_allowed boolean; has_legacy_admin_marker boolean;
  staff_mfa_required boolean; mfa_factor_enrolled boolean; aal text; mfa_state text; mfa_satisfied boolean;
begin
  if caller_id is null then return jsonb_build_object('is_admin',false,'roles','[]'::jsonb,'capabilityBased',true,'staffMfaRequired',false,'mfaFactorEnrolled',false,'mfaSatisfied',true,'mfaEnforcementActive',false,'staffMfaState',null,'staffMfaTransitionPending',false,'authenticatorAssuranceLevel','aal1'); end if;
  perform private.record_current_security_context_v1(caller_id);
  baseline_allowed:=coalesce(private.user_has_permission_v1(caller_id,'admin.access'),false);
  staff_mfa_required:=private.user_requires_staff_mfa_v1(caller_id);
  mfa_factor_enrolled:=private.user_has_verified_totp_factor_v1(caller_id);
  aal:=private.current_authenticator_assurance_level_v1(); mfa_state:=private.staff_mfa_state_v1(caller_id);
  mfa_satisfied:=not staff_mfa_required or (mfa_state='enforced' and mfa_factor_enrolled and aal='aal2');
  select coalesce(jsonb_agg(r.role order by case r.role when 'super_admin' then 1 when 'admin' then 2 when 'operations' then 3 when 'moderator' then 4 when 'content_editor' then 5 when 'support' then 6 else 99 end,r.role),'[]'::jsonb) into roles
  from private.user_roles r where r.user_id=caller_id and r.role in('support','content_editor','operations','moderator','admin','super_admin') and (r.expires_at is null or r.expires_at>timezone('utc',now()));
  has_legacy_admin_marker:=roles?'admin' or roles?'super_admin'; if baseline_allowed and not has_legacy_admin_marker then roles:=roles||jsonb_build_array('admin'); end if;
  return jsonb_build_object('is_admin',baseline_allowed,'roles',case when baseline_allowed then roles else '[]'::jsonb end,'capabilityBased',true,'legacyAdminShellMarker',baseline_allowed and not has_legacy_admin_marker,
    'staffMfaRequired',staff_mfa_required,'mfaFactorEnrolled',mfa_factor_enrolled,'mfaSatisfied',mfa_satisfied,'mfaEnforcementActive',staff_mfa_required,
    'staffMfaState',mfa_state,'staffMfaTransitionPending',staff_mfa_required and coalesce(mfa_state,'enrollment_required')='enrollment_required','authenticatorAssuranceLevel',aal);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_set_content_report_status_v1(p_report_id uuid, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare status_value text:=lower(btrim(coalesce(p_status,''))); report_row private.user_content_reports%rowtype;
begin
  if auth.uid() is null or not coalesce(private.has_permission('report.moderate'),false) then raise exception 'admin_required' using errcode='42501'; end if;
  if status_value not in ('reviewing','actioned','dismissed') then raise exception 'invalid_report_status' using errcode='22023'; end if;
  update private.user_content_reports set status=status_value,updated_at=timezone('utc',now()) where id=p_report_id returning * into report_row;
  if report_row.id is null then raise exception 'content_report_not_found' using errcode='P0002'; end if;
  return jsonb_build_object('id',report_row.id,'status',report_row.status,'updatedAt',report_row.updated_at);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_set_platform_user_role_v2(p_user_id uuid, p_role text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  normalized_role text:=lower(btrim(coalesce(p_role,'')));
  normalized_reason text:=btrim(coalesce(p_reason,''));
  target_is_admin boolean;
  target_is_super_admin boolean;
  active_super_admin_count integer;
  previous_roles text[];
  next_roles text[];
begin
  if caller_id is null or not private.has_permission('role.manage') then
    raise exception 'permission_required:role.manage' using errcode='42501';
  end if;
  if p_user_id is null or normalized_role not in ('customer','producer','support','content_editor','operations','moderator','admin','super_admin') then
    raise exception 'invalid_user_role' using errcode='22023';
  end if;
  if char_length(normalized_reason) not between 8 and 500 then raise exception 'role_reason_required' using errcode='22023'; end if;
  if not exists(select 1 from public.profiles p where p.id=p_user_id and p.status<>'deleted') then raise exception 'user_not_found' using errcode='P0002'; end if;
  if p_user_id=caller_id then raise exception 'cannot_change_current_user_role' using errcode='42501'; end if;

  select
    private.user_has_permission_v1(p_user_id,'admin.access') and exists(select 1 from private.user_roles r where r.user_id=p_user_id and r.role='admin' and (r.expires_at is null or r.expires_at>timezone('utc',now()))),
    private.user_has_permission_v1(p_user_id,'role.manage') and exists(select 1 from private.user_roles r where r.user_id=p_user_id and r.role='super_admin' and (r.expires_at is null or r.expires_at>timezone('utc',now())))
  into target_is_admin,target_is_super_admin;

  if target_is_super_admin and normalized_role<>'super_admin' then
    select count(*) into active_super_admin_count
    from private.user_roles r
    join public.profiles p on p.id=r.user_id
    where r.role='super_admin'
      and (r.expires_at is null or r.expires_at>timezone('utc',now()))
      and p.status='active' and p.deleted_at is null
      and not coalesce((private.platform_access_block_v1(r.user_id)->>'blocked')::boolean,false);
    if active_super_admin_count<=1 then raise exception 'last_super_admin_cannot_be_demoted' using errcode='42501'; end if;
  end if;

  if normalized_role='producer' and not exists(select 1 from public.producers pr where pr.owner_user_id=p_user_id and pr.deleted_at is null and pr.status in ('active','suspended')) then
    raise exception 'producer_profile_required' using errcode='22023';
  end if;

  select coalesce(array_agg(r.role order by r.role),'{}'::text[]) into previous_roles
  from private.user_roles r where r.user_id=p_user_id and (r.expires_at is null or r.expires_at>timezone('utc',now()));

  delete from private.user_roles
  where user_id=p_user_id and role in ('customer','producer','support','content_editor','operations','moderator','admin','super_admin');

  insert into private.user_roles(user_id,role,granted_by) values(p_user_id,'customer',caller_id)
  on conflict(user_id,role) do update set granted_by=excluded.granted_by,granted_at=timezone('utc',now()),expires_at=null;
  if normalized_role<>'customer' then
    insert into private.user_roles(user_id,role,granted_by) values(p_user_id,normalized_role,caller_id)
    on conflict(user_id,role) do update set granted_by=excluded.granted_by,granted_at=timezone('utc',now()),expires_at=null;
  end if;
  next_roles:=case when normalized_role='customer' then array['customer']::text[] else array[normalized_role,'customer']::text[] end;

  perform private.write_admin_audit_v2(
    'user.role_changed','user',p_user_id::text,
    jsonb_build_object('roles',previous_roles),
    jsonb_build_object('roles',next_roles),
    jsonb_build_object('reason',normalized_reason)
  );

  insert into public.notifications(user_id,type,title,message,action_url,metadata)
  values(p_user_id,'system','Hesap rolünüz güncellendi','Hesap yetkiniz yönetim incelemesinin ardından güncellendi.','/?tab=account',jsonb_build_object('role',normalized_role,'reason',normalized_reason,'actorUserId',caller_id));
  return jsonb_build_object('id',p_user_id,'role',normalized_role,'roles',to_jsonb(next_roles));
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_set_platform_user_status_v1(p_user_id uuid, p_status text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  normalized_status text := lower(btrim(coalesce(p_status, '')));
  normalized_reason text := btrim(coalesce(p_reason, ''));
  target_is_super_admin boolean;
  caller_is_super_admin boolean;
  updated_profile public.profiles%rowtype;
begin
  if caller_id is null or not coalesce(private.has_permission('user.manage'),false) then
    raise exception 'admin_required' using errcode = '42501';
  end if;
  if p_user_id is null or normalized_status not in ('active', 'blocked') then
    raise exception 'invalid_user_status' using errcode = '22023';
  end if;
  if char_length(normalized_reason) not between 8 and 500 then
    raise exception 'status_reason_required' using errcode = '22023';
  end if;
  if p_user_id = caller_id and normalized_status = 'blocked' then
    raise exception 'cannot_block_current_user' using errcode = '42501';
  end if;
  select exists (
    select 1 from private.user_roles role
    where role.user_id = p_user_id and role.role = 'super_admin'
      and (role.expires_at is null or role.expires_at > timezone('utc', now()))
  ) into target_is_super_admin;
  caller_is_super_admin := coalesce(private.has_permission('role.manage'), false);
  if target_is_super_admin and not caller_is_super_admin then
    raise exception 'super_admin_required' using errcode = '42501';
  end if;
  update public.profiles set status = normalized_status, deleted_at = null where id = p_user_id
  returning * into updated_profile;
  if not found then raise exception 'user_not_found' using errcode = 'P0002'; end if;
  insert into public.notifications(user_id, type, title, message, action_url, metadata)
  values (
    p_user_id, 'system',
    case when normalized_status = 'active' then 'Hesabınız yeniden etkinleştirildi' else 'Hesabınıza erişim kısıtlandı' end,
    case when normalized_status = 'active'
      then 'Hesabınız yönetim incelemesinin ardından yeniden etkinleştirildi.'
      else 'Hesabınız yönetim incelemesi nedeniyle geçici olarak kısıtlandı. Destek ekibiyle iletişime geçebilirsiniz.'
    end,
    '/account', jsonb_build_object('reason', normalized_reason, 'actorUserId', caller_id)
  );
  return jsonb_build_object('id', updated_profile.id, 'status', case when updated_profile.status = 'active' then 'active' else 'blocked' end, 'updatedAt', updated_profile.updated_at);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_set_producer_commission_v1(p_producer_id uuid, p_commission_basis_points integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare caller_id uuid:=auth.uid(); producer_row public.producers%rowtype; begin
 if caller_id is null or not coalesce(private.has_permission('finance.manage'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
 if p_commission_basis_points is null or p_commission_basis_points not between 0 and 10000 then raise exception 'invalid_producer_commission' using errcode='22023'; end if;
 update public.producers set commission_basis_points=p_commission_basis_points,updated_at=timezone('utc',now()) where id=p_producer_id and deleted_at is null returning * into producer_row;
 if producer_row.id is null then raise exception 'producer_not_found' using errcode='P0002'; end if;
 insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload) values('producer',producer_row.id,'producer.commission_updated',jsonb_build_object('producer_id',producer_row.id,'commission_basis_points',p_commission_basis_points,'actor_user_id',caller_id));
 return jsonb_build_object('producerId',producer_row.id,'commissionBasisPoints',producer_row.commission_basis_points);
end;$function$;

CREATE OR REPLACE FUNCTION private.admin_set_producer_document_status(p_document_id uuid, p_status text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid := (select auth.uid());
begin
  if caller_id is null or not coalesce(private.has_permission('seller.review'),false) then raise exception 'admin_required' using errcode = '42501'; end if;
  if p_status not in ('pending', 'verified', 'rejected') then raise exception 'invalid_producer_document_status' using errcode = '22023'; end if;
  update private.producer_documents
  set verification_status = p_status,
      verified_by = case when p_status in ('verified', 'rejected') then caller_id else null end,
      verified_at = case when p_status in ('verified', 'rejected') then timezone('utc', now()) else null end
  where id = p_document_id;
  if not found then raise exception 'producer_document_not_found' using errcode = 'P0002'; end if;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_set_producer_origin_verified_v1(p_producer_id uuid, p_verified boolean, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare producer public.producers%rowtype; clean_reason text:=btrim(coalesce(p_reason,'')); caller_id uuid:=auth.uid();
begin
  if caller_id is null or not coalesce(private.has_permission('seller.review'),false) then raise exception 'admin_required' using errcode='42501'; end if;
  if p_verified is null then raise exception 'verification_state_required' using errcode='22023'; end if;
  if char_length(clean_reason) not between 10 and 1000 then raise exception 'origin_verification_reason_required' using errcode='22023'; end if;
  select * into producer from public.producers where id=p_producer_id and deleted_at is null for update;
  if producer.id is null then raise exception 'producer_profile_not_found' using errcode='P0002'; end if;
  if p_verified and not producer.is_verified then raise exception 'producer_identity_not_verified' using errcode='42501'; end if;
  if p_verified and char_length(btrim(coalesce(producer.production_location,'')))<2 and (producer.production_village is null or producer.production_district is null or producer.production_province is null) then raise exception 'producer_origin_information_required' using errcode='22023'; end if;
  update public.producers set origin_verified=p_verified,origin_verified_at=case when p_verified then timezone('utc',now()) else null end,
    origin_verification_basis=case when p_verified then 'admin_manual_verification' else null end,
    trust_badge_status=case when not p_verified and trust_badge_status='active' then 'revoked' else trust_badge_status end,
    trust_badge_revoked_at=case when not p_verified and trust_badge_status='active' then timezone('utc',now()) else trust_badge_revoked_at end,
    trust_badge_reason=case when not p_verified and trust_badge_status='active' then 'Menşe doğrulaması kaldırıldı: '||clean_reason else trust_badge_reason end,
    updated_at=timezone('utc',now()) where id=p_producer_id;
  if not p_verified and producer.trust_badge_status='active' then
    insert into private.producer_trust_badge_events(producer_id,actor_user_id,action,reason,review_due_at)
    values(producer.id,caller_id,'auto_revoked','Menşe doğrulaması kaldırıldı: '||clean_reason,producer.trust_badge_review_due_at);
  end if;
  return jsonb_build_object('producer_id',p_producer_id,'origin_verified',p_verified,'reason',clean_reason);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_set_producer_phone_verified(p_application_id uuid, p_verified boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid := (select auth.uid());
begin
  if caller_id is null or not coalesce(private.has_permission('seller.review'),false) then raise exception 'admin_required' using errcode = '42501'; end if;
  update private.producer_application_kyc kyc
  set phone_verified_at = case when p_verified then timezone('utc', now()) else null end,
      phone_verified_by = case when p_verified then caller_id else null end
  where kyc.application_id = p_application_id;
  if not found then raise exception 'producer_application_not_found' using errcode = 'P0002'; end if;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_set_producer_status_v1(p_producer_id uuid, p_status text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare producer public.producers%rowtype; clean_reason text:=btrim(coalesce(p_reason,'')); caller_id uuid:=auth.uid();
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if; if p_status='suspended' and not private.has_permission('seller.suspend') then raise exception 'permission_required:seller.suspend' using errcode='42501'; end if; if p_status='active' and not private.has_permission('seller.restore') then raise exception 'permission_required:seller.restore' using errcode='42501'; end if;
  if p_status not in ('active','suspended') then raise exception 'invalid_producer_status' using errcode='22023'; end if;
  if p_status='suspended' and char_length(clean_reason)<10 then raise exception 'producer_status_reason_required' using errcode='22023'; end if;
  select * into producer from public.producers where id=p_producer_id and deleted_at is null for update;
  if producer.id is null then raise exception 'producer_profile_not_found' using errcode='P0002'; end if;
  if p_status='active' and not producer.is_verified then raise exception 'producer_not_verified' using errcode='42501'; end if;
  update public.producers set status=p_status,
    trust_badge_status=case when p_status='suspended' and trust_badge_status='active' then 'revoked' else trust_badge_status end,
    trust_badge_revoked_at=case when p_status='suspended' and trust_badge_status='active' then timezone('utc',now()) else trust_badge_revoked_at end,
    trust_badge_reason=case when p_status='suspended' and trust_badge_status='active' then 'Satıcı hesabı askıya alındı: '||clean_reason else trust_badge_reason end,
    updated_at=timezone('utc',now()) where id=producer.id;
  if p_status='suspended' and producer.trust_badge_status='active' then
    insert into private.producer_trust_badge_events(producer_id,actor_user_id,action,reason,review_due_at)
    values(producer.id,caller_id,'auto_revoked','Satıcı hesabı askıya alındı: '||clean_reason,producer.trust_badge_review_due_at);
  end if;
  insert into public.notifications(user_id,type,title,message,action_url,metadata)
  values(producer.owner_user_id,'producer',case when p_status='active' then 'Mağazanız yeniden etkinleştirildi' else 'Mağazanız geçici olarak askıya alındı' end,
    case when p_status='active' then 'Golden Oremar mağazanız yeniden satışa açıldı. Doğrulama rozeti gerekiyorsa yeniden inceleme yapılır.' else clean_reason end,
    '/?tab=account',jsonb_build_object('producer_id',producer.id,'status',p_status,'reason',nullif(clean_reason,'')));
  return jsonb_build_object('id',producer.id,'status',p_status);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_set_producer_trust_badge_v1(p_producer_id uuid, p_active boolean, p_reason text, p_review_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  producer public.producers%rowtype;
  clean_reason text:=btrim(coalesce(p_reason,''));
  review_due timestamptz;
begin
  if caller_id is null or not coalesce(private.has_permission('seller.review'),false) then raise exception 'admin_required' using errcode='42501'; end if;
  if p_active is null then raise exception 'trust_badge_state_required' using errcode='22023'; end if;
  if char_length(clean_reason) not between 10 and 1000 then raise exception 'trust_badge_reason_required' using errcode='22023'; end if;
  select * into producer from public.producers where id=p_producer_id and deleted_at is null for update;
  if producer.id is null then raise exception 'producer_profile_not_found' using errcode='P0002'; end if;

  if p_active then
    if producer.status<>'active' or not producer.is_verified or not producer.origin_verified then
      raise exception 'producer_not_trust_badge_eligible' using errcode='55000';
    end if;
    review_due:=coalesce(p_review_due_at,producer.verification_due_at,timezone('utc',now())+interval '365 days');
    if review_due<=timezone('utc',now()) then raise exception 'trust_badge_review_due_must_be_future' using errcode='22023'; end if;
    update public.producers set
      trust_badge_status='active',trust_badge_granted_at=timezone('utc',now()),trust_badge_review_due_at=review_due,
      trust_badge_revoked_at=null,trust_badge_reason=clean_reason,updated_at=timezone('utc',now())
    where id=producer.id;
    insert into private.producer_trust_badge_events(producer_id,actor_user_id,action,reason,review_due_at)
    values(producer.id,caller_id,'granted',clean_reason,review_due);
  else
    update public.producers set
      trust_badge_status='revoked',trust_badge_revoked_at=timezone('utc',now()),trust_badge_reason=clean_reason,updated_at=timezone('utc',now())
    where id=producer.id;
    insert into private.producer_trust_badge_events(producer_id,actor_user_id,action,reason,review_due_at)
    values(producer.id,caller_id,'revoked',clean_reason,producer.trust_badge_review_due_at);
  end if;

  insert into public.notifications(user_id,type,title,message,action_url,metadata)
  values(producer.owner_user_id,'producer',
    case when p_active then 'Doğrulanmış Üretici rozeti verildi' else 'Doğrulanmış Üretici rozeti kaldırıldı' end,
    case when p_active then 'Golden Oremar doğrulama rozetiniz aktif edildi.' else clean_reason end,
    '/?tab=account',jsonb_build_object('producer_id',producer.id,'trust_badge_active',p_active,'review_due_at',review_due,'reason',clean_reason));

  return jsonb_build_object('producer_id',producer.id,'active',p_active,'status',case when p_active then 'active' else 'revoked' end,'review_due_at',review_due,'reason',clean_reason);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_set_return_status_v1(p_order_id uuid, p_status text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  normalized_input text := lower(btrim(coalesce(p_status, '')));
  normalized_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  next_status text;
  target_return public.return_requests%rowtype;
begin
  if caller_id is null or not coalesce(private.has_permission('refund.approve'),false) then
    raise exception 'admin_required' using errcode = '42501';
  end if;
  next_status := case normalized_input
    when 'requested' then 'under_review' when 'approved' then 'approved' when 'rejected' then 'rejected'
    when 'completed' then 'closed' when 'under_review' then 'under_review' when 'in_transit' then 'in_transit'
    when 'received' then 'received' when 'closed' then 'closed' else null
  end;
  if next_status is null then raise exception 'invalid_return_status' using errcode = '22023'; end if;
  if next_status = 'rejected' and char_length(coalesce(normalized_reason, '')) < 8 then
    raise exception 'rejection_reason_required' using errcode = '22023';
  end if;
  select * into target_return from public.return_requests request where request.order_id = p_order_id
  order by request.created_at desc limit 1 for update;
  if not found then raise exception 'return_request_not_found' using errcode = 'P0002'; end if;
  if not (
    (target_return.status = 'requested' and next_status in ('under_review', 'approved', 'rejected'))
    or (target_return.status = 'under_review' and next_status in ('approved', 'rejected'))
    or (target_return.status = 'approved' and next_status in ('in_transit', 'received', 'closed'))
    or (target_return.status = 'in_transit' and next_status in ('received', 'closed'))
    or (target_return.status = 'received' and next_status = 'closed')
  ) then
    raise exception 'invalid_return_status_transition:%:%', target_return.status, next_status using errcode = '22023';
  end if;
  update public.return_requests
  set status = next_status,
      review_reason = coalesce(normalized_reason, review_reason),
      reviewed_by = caller_id, reviewed_at = timezone('utc', now()),
      resolution = case when next_status = 'rejected' then 'none' when next_status = 'closed' then coalesce(resolution, 'none') else resolution end
  where id = target_return.id returning * into target_return;
  if next_status = 'closed' then
    update public.order_items item
    set fulfillment_status = case when exists (select 1 from public.return_items returned where returned.return_id = target_return.id and returned.order_item_id = item.id) then 'returned' else item.fulfillment_status end
    where item.order_id = target_return.order_id;
  end if;
  insert into public.notifications(user_id, type, title, message, action_url, metadata)
  values (target_return.user_id, 'return', 'İade talebiniz güncellendi',
    target_return.return_number || ' numaralı iade talebinizin yeni durumu: ' || next_status || '.',
    '/account/orders', jsonb_build_object('returnId', target_return.id, 'orderId', target_return.order_id, 'status', next_status));
  insert into private.outbox_events(aggregate_type, aggregate_id, event_type, payload)
  values ('return_request', target_return.id, 'return.status_changed', jsonb_build_object('return_id', target_return.id, 'status', next_status, 'actor_user_id', caller_id));
  return jsonb_build_object('id', target_return.id, 'orderId', target_return.order_id, 'status', target_return.status, 'returnNumber', target_return.return_number);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_set_store_follow_simulation_v1(p_producer_id uuid, p_simulated_followers integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  allocated_other integer := 0;
begin
  if auth.uid() is null or not private.has_permission('system.configure') then
    raise exception 'super_admin_required' using errcode='42501';
  end if;
  if p_producer_id is null or p_simulated_followers is null or p_simulated_followers not between 0 and 10000 then
    raise exception 'invalid_simulation_allocation' using errcode='22023';
  end if;
  if not exists(
    select 1 from public.producers p
    where p.id=p_producer_id and p.status='active' and p.is_verified=true and p.deleted_at is null
  ) then
    raise exception 'producer_not_available' using errcode='P0002';
  end if;

  perform pg_advisory_xact_lock(hashtext('golden_oremar_store_follow_simulation_v1'));

  select coalesce(sum(a.simulated_followers),0)::integer
    into allocated_other
  from private.store_follow_simulation_allocations a
  where a.producer_id<>p_producer_id;

  if allocated_other+p_simulated_followers>10000 then
    raise exception 'simulation_pool_capacity_exceeded' using errcode='22023';
  end if;

  if p_simulated_followers=0 then
    delete from private.store_follow_simulation_allocations where producer_id=p_producer_id;
  else
    insert into private.store_follow_simulation_allocations(producer_id,simulated_followers,updated_by,updated_at)
    values(p_producer_id,p_simulated_followers,auth.uid(),timezone('utc',now()))
    on conflict(producer_id) do update set
      simulated_followers=excluded.simulated_followers,
      updated_by=excluded.updated_by,
      updated_at=excluded.updated_at;
  end if;

  insert into private.admin_audit_logs(actor_user_id,action,target_type,target_id,details,created_at)
  values(auth.uid(),'store_follow_simulation_set','producer',p_producer_id::text,jsonb_build_object(
    'simulatedFollowers',p_simulated_followers,
    'publicMetricsIsolation',true,
    'poolCapacity',10000
  ),timezone('utc',now()));

  return private.get_store_follow_simulation_v1();
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_update_account_closure_v1(p_request_id uuid, p_status text, p_admin_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  next_status text:=lower(btrim(coalesce(p_status,'')));
  note_value text:=nullif(btrim(coalesce(p_admin_note,'')),'');
  request_row private.account_closure_requests%rowtype;
begin
  if caller_id is null or not coalesce(private.has_permission('user.manage'),false) then raise exception 'admin_required' using errcode='42501'; end if;
  if next_status not in ('processing','ready_for_auth_deletion','completed','rejected') then raise exception 'invalid_account_closure_status' using errcode='22023'; end if;
  if note_value is not null and char_length(note_value)>4000 then raise exception 'account_closure_admin_note_too_long' using errcode='22023'; end if;
  select * into request_row from private.account_closure_requests where id=p_request_id for update;
  if request_row.id is null then raise exception 'account_closure_not_found' using errcode='P0002'; end if;
  if not (
    (request_row.status='requested' and next_status in ('processing','rejected'))
    or (request_row.status='processing' and next_status in ('ready_for_auth_deletion','rejected'))
    or (request_row.status='ready_for_auth_deletion' and next_status='completed')
  ) then raise exception 'invalid_account_closure_transition:%:%',request_row.status,next_status using errcode='22023'; end if;
  if next_status='ready_for_auth_deletion' then
    update public.profiles
    set status='deleted',display_name='Silinmiş Kullanıcı',phone=null,avatar_path=null,marketing_consent=false,marketing_consent_at=null,deleted_at=timezone('utc',now()),updated_at=timezone('utc',now())
    where id=request_row.user_id;
    update public.addresses set deleted_at=coalesce(deleted_at,timezone('utc',now())),is_default=false,updated_at=timezone('utc',now()) where user_id=request_row.user_id and deleted_at is null;
    delete from public.favorites where user_id=request_row.user_id;
    update public.carts set status='abandoned',updated_at=timezone('utc',now()) where user_id=request_row.user_id and status='active';
    delete from private.device_push_tokens where user_id=request_row.user_id;
    update private.user_notification_preferences set push_enabled=false,campaign_push=false,updated_at=timezone('utc',now()) where user_id=request_row.user_id;
    insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
    values('account_closure',request_row.id,'account_closure.auth_deletion_required',jsonb_build_object('request_id',request_row.id,'user_id',request_row.user_id));
  end if;
  update private.account_closure_requests
  set status=next_status,admin_note=note_value,updated_at=timezone('utc',now()),processed_by=caller_id,
      processed_at=case when next_status in ('completed','rejected') then timezone('utc',now()) else processed_at end
  where id=request_row.id returning * into request_row;
  return jsonb_build_object('id',request_row.id,'userId',request_row.user_id,'status',request_row.status,'updatedAt',request_row.updated_at,'processedAt',request_row.processed_at);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_update_brand_configuration_v1(p_section text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  normalized_section text := lower(btrim(coalesce(p_section, '')));
  next_config jsonb;
  next_contact jsonb;
  next_general jsonb;
  next_value jsonb;
  next_brand_name text;
  next_maintenance boolean;
  next_email text;
  next_phone text;
  result_row public.brand_settings%rowtype;
begin
  if caller_id is null or not coalesce(private.has_permission('system.configure'),false) then
    raise exception 'admin_required' using errcode = '42501';
  end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'invalid_configuration_payload' using errcode = '22023';
  end if;
  if pg_column_size(p_payload) > 524288 then
    raise exception 'configuration_payload_too_large' using errcode = '22023';
  end if;
  select settings.public_config into next_config from public.brand_settings settings where settings.slug = 'golden-oremar' for update;
  if not found then raise exception 'brand_configuration_not_found' using errcode = 'P0002'; end if;
  if normalized_section = 'general' then
    if exists (select 1 from jsonb_object_keys(p_payload) key where key not in ('siteName', 'logoUrl', 'theme', 'maintenanceMode')) then
      raise exception 'unsupported_general_setting' using errcode = '22023';
    end if;
    next_brand_name := nullif(btrim(p_payload ->> 'siteName'), '');
    if next_brand_name is not null and char_length(next_brand_name) not between 2 and 80 then
      raise exception 'invalid_site_name' using errcode = '22023';
    end if;
    if p_payload ? 'theme' and coalesce(p_payload ->> 'theme', '') not in ('light', 'dark') then
      raise exception 'invalid_theme' using errcode = '22023';
    end if;
    if p_payload ? 'logoUrl' and char_length(coalesce(p_payload ->> 'logoUrl', '')) > 2048 then
      raise exception 'invalid_logo_url' using errcode = '22023';
    end if;
    if p_payload ? 'maintenanceMode' and jsonb_typeof(p_payload -> 'maintenanceMode') <> 'boolean' then
      raise exception 'invalid_maintenance_mode' using errcode = '22023';
    end if;
    next_general := coalesce(next_config -> 'appSettings', '{}'::jsonb) || jsonb_strip_nulls(
      jsonb_build_object('theme', case when p_payload ? 'theme' then p_payload ->> 'theme' else null end,
        'logoUrl', case when p_payload ? 'logoUrl' then p_payload ->> 'logoUrl' else null end)
    );
    next_config := jsonb_set(next_config, '{appSettings}', next_general, true);
    next_maintenance := case when p_payload ? 'maintenanceMode' then (p_payload ->> 'maintenanceMode')::boolean else null end;
    update public.brand_settings
    set brand_name = coalesce(next_brand_name, brand_name), maintenance_mode = coalesce(next_maintenance, maintenance_mode), public_config = next_config
    where slug = 'golden-oremar' returning * into result_row;
  elsif normalized_section = 'contactinfo' then
    if exists (select 1 from jsonb_object_keys(p_payload) key where key not in ('address', 'phone', 'whatsapp', 'email', 'mapUrl', 'social')) then
      raise exception 'unsupported_contact_setting' using errcode = '22023';
    end if;
    if p_payload ? 'social' and jsonb_typeof(p_payload -> 'social') <> 'object' then
      raise exception 'invalid_social_links' using errcode = '22023';
    end if;
    if char_length(coalesce(p_payload ->> 'address', '')) > 500
      or char_length(coalesce(p_payload ->> 'phone', '')) > 40
      or char_length(coalesce(p_payload ->> 'whatsapp', '')) > 40
      or char_length(coalesce(p_payload ->> 'email', '')) > 320
      or char_length(coalesce(p_payload ->> 'mapUrl', '')) > 2048 then
      raise exception 'invalid_contact_field_length' using errcode = '22023';
    end if;
    next_email := lower(btrim(coalesce(p_payload ->> 'email', '')));
    if next_email <> '' and next_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
      raise exception 'invalid_support_email' using errcode = '22023';
    end if;
    next_phone := btrim(coalesce(p_payload ->> 'phone', ''));
    next_contact := jsonb_build_object('address', btrim(coalesce(p_payload ->> 'address', '')), 'phone', next_phone,
      'whatsapp', btrim(coalesce(p_payload ->> 'whatsapp', '')), 'email', next_email,
      'mapUrl', btrim(coalesce(p_payload ->> 'mapUrl', '')), 'social', coalesce(p_payload -> 'social', '{}'::jsonb));
    next_config := jsonb_set(next_config, '{contactInfo}', next_contact, true);
    update public.brand_settings set support_email = nullif(next_email, ''), support_phone = nullif(next_phone, ''), public_config = next_config
    where slug = 'golden-oremar' returning * into result_row;
  elsif normalized_section = 'herocategories' then
    next_value := p_payload -> 'items';
    if jsonb_typeof(next_value) <> 'array' or jsonb_array_length(next_value) not between 1 and 12 then
      raise exception 'invalid_hero_categories' using errcode = '22023';
    end if;
    if exists (select 1 from jsonb_array_elements(next_value) item
      where jsonb_typeof(item) <> 'object'
        or char_length(btrim(coalesce(item ->> 'id', ''))) not between 1 and 80
        or char_length(btrim(coalesce(item ->> 'title', ''))) not between 1 and 120
        or char_length(btrim(coalesce(item ->> 'targetCategory', ''))) not between 1 and 120
        or char_length(coalesce(item ->> 'subtitle', '')) > 180
        or char_length(coalesce(item ->> 'image', '')) > 2048
        or char_length(coalesce(item ->> 'icon', '')) > 80) then
      raise exception 'invalid_hero_category_item' using errcode = '22023';
    end if;
    next_config := jsonb_set(next_config, '{heroCategories}', next_value, true);
    update public.brand_settings set public_config = next_config where slug = 'golden-oremar' returning * into result_row;
  elsif normalized_section = 'homesections' then
    next_value := p_payload -> 'items';
    if jsonb_typeof(next_value) <> 'array' or jsonb_array_length(next_value) not between 1 and 20 then
      raise exception 'invalid_home_sections' using errcode = '22023';
    end if;
    if exists (select 1 from jsonb_array_elements(next_value) item
      where jsonb_typeof(item) <> 'object'
        or char_length(btrim(coalesce(item ->> 'id', ''))) not between 1 and 80
        or char_length(btrim(coalesce(item ->> 'title', ''))) not between 1 and 160
        or not (item ? 'active') or jsonb_typeof(item -> 'active') <> 'boolean') then
      raise exception 'invalid_home_section_item' using errcode = '22023';
    end if;
    next_config := jsonb_set(next_config, '{homeSections}', next_value, true);
    update public.brand_settings set public_config = next_config where slug = 'golden-oremar' returning * into result_row;
  elsif normalized_section = 'staticcontent' then
    next_value := p_payload -> 'content';
    if jsonb_typeof(next_value) <> 'object' then raise exception 'invalid_static_content' using errcode = '22023'; end if;
    if exists (select 1 from jsonb_object_keys(next_value) key where key not in ('about', 'returns', 'privacy', 'faq', 'interface')) then
      raise exception 'unsupported_static_content_section' using errcode = '22023';
    end if;
    if not (next_value ?& array['about', 'returns', 'privacy', 'faq', 'interface'])
      or jsonb_typeof(next_value -> 'about') <> 'object'
      or jsonb_typeof(next_value -> 'returns') <> 'object'
      or jsonb_typeof(next_value -> 'privacy') <> 'object'
      or jsonb_typeof(next_value -> 'faq') <> 'array'
      or jsonb_typeof(next_value -> 'interface') <> 'object'
      or jsonb_array_length(next_value -> 'faq') > 50 then
      raise exception 'incomplete_static_content' using errcode = '22023';
    end if;
    if char_length(coalesce(next_value #>> '{about,content}', '')) > 100000
      or char_length(coalesce(next_value #>> '{returns,content}', '')) > 100000
      or char_length(coalesce(next_value #>> '{privacy,content}', '')) > 100000 then
      raise exception 'static_content_section_too_large' using errcode = '22023';
    end if;
    next_config := jsonb_set(next_config, '{staticContent}', next_value, true);
    update public.brand_settings set public_config = next_config where slug = 'golden-oremar' returning * into result_row;
  else
    raise exception 'unsupported_configuration_section' using errcode = '22023';
  end if;
  return jsonb_build_object('slug', result_row.slug, 'brandName', result_row.brand_name, 'maintenanceMode', result_row.maintenance_mode,
    'supportEmail', result_row.support_email, 'supportPhone', result_row.support_phone, 'publicConfig', result_row.public_config, 'updatedAt', result_row.updated_at);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_update_event_spotlight_v1(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  settings public.brand_settings%rowtype;
  normalized jsonb;
  featured_ref text;
  max_items integer;
  placement text;
begin
  if caller_id is null or not private.has_permission('event.manage') then
    raise exception 'super_admin_required' using errcode='42501';
  end if;
  if p_payload is null or jsonb_typeof(p_payload)<>'object' then raise exception 'invalid_event_spotlight_payload' using errcode='22023'; end if;
  if exists(select 1 from jsonb_object_keys(p_payload) key where key not in ('enabled','title','subtitle','maxItems','featuredEventReference','showCountdown','showCapacity','showShare','showAllLink','placement')) then
    raise exception 'unsupported_event_spotlight_setting' using errcode='22023';
  end if;
  if jsonb_typeof(p_payload->'enabled')<>'boolean' or jsonb_typeof(p_payload->'showCountdown')<>'boolean' or jsonb_typeof(p_payload->'showCapacity')<>'boolean' or jsonb_typeof(p_payload->'showShare')<>'boolean' or jsonb_typeof(p_payload->'showAllLink')<>'boolean' then
    raise exception 'invalid_event_spotlight_boolean' using errcode='22023';
  end if;
  if char_length(btrim(coalesce(p_payload->>'title',''))) not between 2 and 120 or char_length(btrim(coalesce(p_payload->>'subtitle',''))) > 300 then raise exception 'invalid_event_spotlight_copy' using errcode='22023'; end if;
  begin max_items:=(p_payload->>'maxItems')::integer; exception when others then raise exception 'invalid_event_spotlight_max_items' using errcode='22023'; end;
  if max_items not between 1 and 6 then raise exception 'invalid_event_spotlight_max_items' using errcode='22023'; end if;
  placement:=btrim(coalesce(p_payload->>'placement',''));
  if placement not in ('after_hero','after_categories','before_products') then raise exception 'invalid_event_spotlight_placement' using errcode='22023'; end if;
  featured_ref:=nullif(btrim(coalesce(p_payload->>'featuredEventReference','')),'');
  if featured_ref is not null then
    if char_length(featured_ref)>220 then raise exception 'invalid_featured_event_reference' using errcode='22023'; end if;
    if not exists(select 1 from public.events e where e.id::text=featured_ref or e.slug=featured_ref or e.legacy_id=featured_ref) then raise exception 'featured_event_not_found' using errcode='22023'; end if;
  end if;
  normalized:=jsonb_build_object(
    'enabled',(p_payload->>'enabled')::boolean,
    'title',btrim(p_payload->>'title'),
    'subtitle',btrim(coalesce(p_payload->>'subtitle','')),
    'maxItems',max_items,
    'featuredEventReference',featured_ref,
    'showCountdown',(p_payload->>'showCountdown')::boolean,
    'showCapacity',(p_payload->>'showCapacity')::boolean,
    'showShare',(p_payload->>'showShare')::boolean,
    'showAllLink',(p_payload->>'showAllLink')::boolean,
    'placement',placement
  );
  update public.brand_settings
  set public_config=jsonb_set(public_config,'{eventSpotlight}',normalized,true),updated_at=timezone('utc',now())
  where slug='golden-oremar'
  returning * into settings;
  if not found then raise exception 'brand_configuration_not_found' using errcode='P0002'; end if;
  return normalized||jsonb_build_object('updatedAt',settings.updated_at);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_update_home_interface_v1(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  entry_row public.content_entries%rowtype;
  current_payload jsonb;
  next_payload jsonb;
  hero_title text;
  hero_subtitle text;
  hero_button text;
  categories_title text;
  footer_text text;
begin
  if auth.uid() is null or not private.has_permission('content.update') then
    raise exception 'super_admin_required' using errcode='42501';
  end if;
  if p_payload is null or jsonb_typeof(p_payload)<>'object' then raise exception 'invalid_home_interface_payload' using errcode='22023'; end if;
  if exists(select 1 from jsonb_object_keys(p_payload) key where key not in ('heroTitle','heroSubtitle','heroButtonText','categoriesTitle','footerText')) then
    raise exception 'unsupported_home_interface_field' using errcode='22023';
  end if;

  select * into entry_row
  from public.content_entries
  where legacy_source='repository-static-content-v1' and legacy_id='interface' and locale='tr' and deleted_at is null
  order by updated_at desc
  limit 1
  for update;
  if not found then raise exception 'home_interface_not_found' using errcode='P0002'; end if;

  begin current_payload:=entry_row.body_markdown::jsonb; exception when others then raise exception 'invalid_home_interface_storage' using errcode='22023'; end;
  if jsonb_typeof(current_payload)<>'object' then raise exception 'invalid_home_interface_storage' using errcode='22023'; end if;

  hero_title:=btrim(coalesce(p_payload->>'heroTitle',current_payload->>'heroTitle',''));
  hero_subtitle:=btrim(coalesce(p_payload->>'heroSubtitle',current_payload->>'heroSubtitle',''));
  hero_button:=btrim(coalesce(p_payload->>'heroButtonText',current_payload->>'heroButtonText',''));
  categories_title:=btrim(coalesce(p_payload->>'categoriesTitle',current_payload->>'categoriesTitle',''));
  footer_text:=btrim(coalesce(p_payload->>'footerText',current_payload->>'footerText',''));

  if char_length(hero_title) not between 2 and 180 then raise exception 'invalid_home_hero_title' using errcode='22023'; end if;
  if char_length(hero_subtitle) not between 2 and 500 then raise exception 'invalid_home_hero_subtitle' using errcode='22023'; end if;
  if char_length(hero_button) not between 2 and 80 then raise exception 'invalid_home_hero_button' using errcode='22023'; end if;
  if char_length(categories_title) not between 2 and 160 then raise exception 'invalid_home_categories_title' using errcode='22023'; end if;
  if char_length(footer_text)>500 then raise exception 'invalid_home_footer_text' using errcode='22023'; end if;

  next_payload:=current_payload||jsonb_build_object(
    'heroTitle',hero_title,
    'heroSubtitle',hero_subtitle,
    'heroButtonText',hero_button,
    'categoriesTitle',categories_title,
    'footerText',footer_text
  );
  update public.content_entries set body_markdown=next_payload::text,updated_at=timezone('utc',now()) where id=entry_row.id returning * into entry_row;
  return next_payload||jsonb_build_object('updatedAt',entry_row.updated_at);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_update_message_moderation_v1(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  s private.message_moderation_settings%rowtype;
  phrases text[];
  key text;
begin
  if auth.uid() is null or not private.has_permission('security.manage') then raise exception 'super_admin_required' using errcode='42501'; end if;
  if p_payload is null or jsonb_typeof(p_payload)<>'object' then raise exception 'invalid_message_moderation_payload' using errcode='22023'; end if;

  for key in select jsonb_object_keys(p_payload) loop
    if key not in ('enabled','blockEmail','blockPhone','blockMessagingApps','blockExternalLinks','blockSocialHandles','blockBankDetails','blockExternalPayments','blockQrCodes','customBlockedPhrases','applyToSupport','allowAttachments','allowImages','allowPdf','maxAttachments','maxAttachmentMb') then raise exception 'unsupported_message_moderation_setting' using errcode='22023'; end if;
  end loop;

  if p_payload ? 'customBlockedPhrases' then
    if jsonb_typeof(p_payload->'customBlockedPhrases')<>'array' or jsonb_array_length(p_payload->'customBlockedPhrases')>100 then raise exception 'invalid_custom_blocked_phrases' using errcode='22023'; end if;
    select coalesce(array_agg(lower(btrim(value))), '{}'::text[])
      into phrases
      from jsonb_array_elements_text(p_payload->'customBlockedPhrases') t(value)
      where char_length(btrim(value)) between 2 and 80;
    if coalesce(array_length(phrases,1),0)<>jsonb_array_length(p_payload->'customBlockedPhrases') then raise exception 'invalid_custom_blocked_phrase' using errcode='22023'; end if;
  end if;

  if p_payload ? 'maxAttachments' and ((p_payload->>'maxAttachments')::int not between 0 and 5) then raise exception 'invalid_message_attachment_limit' using errcode='22023'; end if;
  if p_payload ? 'maxAttachmentMb' and ((p_payload->>'maxAttachmentMb')::int not between 1 and 20) then raise exception 'invalid_message_attachment_size' using errcode='22023'; end if;

  update private.message_moderation_settings set
    enabled=coalesce((p_payload->>'enabled')::boolean,enabled),
    block_email=coalesce((p_payload->>'blockEmail')::boolean,block_email),
    block_phone=coalesce((p_payload->>'blockPhone')::boolean,block_phone),
    block_messaging_apps=coalesce((p_payload->>'blockMessagingApps')::boolean,block_messaging_apps),
    block_external_links=coalesce((p_payload->>'blockExternalLinks')::boolean,block_external_links),
    block_social_handles=coalesce((p_payload->>'blockSocialHandles')::boolean,block_social_handles),
    block_bank_details=coalesce((p_payload->>'blockBankDetails')::boolean,block_bank_details),
    block_external_payments=coalesce((p_payload->>'blockExternalPayments')::boolean,block_external_payments),
    block_qr_codes=coalesce((p_payload->>'blockQrCodes')::boolean,block_qr_codes),
    custom_blocked_phrases=case when p_payload ? 'customBlockedPhrases' then phrases else custom_blocked_phrases end,
    apply_to_support=coalesce((p_payload->>'applyToSupport')::boolean,apply_to_support),
    allow_attachments=coalesce((p_payload->>'allowAttachments')::boolean,allow_attachments),
    allow_images=coalesce((p_payload->>'allowImages')::boolean,allow_images),
    allow_pdf=coalesce((p_payload->>'allowPdf')::boolean,allow_pdf),
    max_attachments=coalesce((p_payload->>'maxAttachments')::smallint,max_attachments),
    max_attachment_mb=coalesce((p_payload->>'maxAttachmentMb')::smallint,max_attachment_mb),
    updated_by=auth.uid(),
    updated_at=timezone('utc',now())
  where singleton=true
  returning * into s;

  return private.admin_get_message_moderation_v1();
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_update_producer_payout_v1(p_payout_id uuid, p_status text, p_provider text DEFAULT NULL::text, p_provider_reference text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  payout_row private.producer_payouts%rowtype;
  next_status text:=lower(btrim(coalesce(p_status,'')));
  producer_owner uuid;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if next_status='paid' and not private.has_permission('payout.release') then raise exception 'permission_required:payout.release' using errcode='42501'; end if;
  if next_status<>'paid' and not private.has_permission('payout.review') then raise exception 'permission_required:payout.review' using errcode='42501'; end if;
  if next_status not in ('processing','paid','failed','cancelled') then raise exception 'invalid_payout_status' using errcode='22023'; end if;
  if char_length(coalesce(p_provider,''))>80 or char_length(coalesce(p_provider_reference,''))>180 or char_length(coalesce(p_note,''))>1000 then raise exception 'invalid_payout_field' using errcode='22023'; end if;
  select * into payout_row from private.producer_payouts where id=p_payout_id for update;
  if payout_row.id is null then raise exception 'payout_not_found' using errcode='P0002'; end if;
  if not (
    (payout_row.status='scheduled' and next_status in ('processing','paid','failed','cancelled'))
    or (payout_row.status='processing' and next_status in ('paid','failed','cancelled'))
  ) then raise exception 'invalid_payout_transition:%:%',payout_row.status,next_status using errcode='22023'; end if;
  if next_status='paid' and (char_length(btrim(coalesce(p_provider,'')))<2 or char_length(btrim(coalesce(p_provider_reference,'')))<4) then raise exception 'payout_payment_reference_required' using errcode='22023'; end if;
  update private.producer_payouts
  set status=next_status,
      provider=coalesce(nullif(btrim(coalesce(p_provider,'')),''),provider),
      provider_reference=coalesce(nullif(btrim(coalesce(p_provider_reference,'')),''),provider_reference),
      note=coalesce(nullif(btrim(coalesce(p_note,'')),''),note),
      processed_by=caller_id,
      processed_at=case when next_status in ('paid','failed','cancelled') then timezone('utc',now()) else processed_at end,
      updated_at=timezone('utc',now())
  where id=payout_row.id returning * into payout_row;
  select owner_user_id into producer_owner from public.producers where id=payout_row.producer_id;
  if next_status='paid' and producer_owner is not null then
    insert into public.notifications(user_id,type,title,message,action_url,metadata)
    values(producer_owner,'producer','Üretici ödemeniz gönderildi','Golden Oremar üretici ödemeniz işlendi.','/producer/finance',jsonb_build_object('payoutId',payout_row.id,'amountMinor',payout_row.amount_minor,'currency',payout_row.currency));
  end if;
  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
  values('producer_payout',payout_row.id,'producer_payout.'||next_status,jsonb_build_object('payout_id',payout_row.id,'producer_id',payout_row.producer_id,'status',next_status,'actor_user_id',caller_id));
  return jsonb_build_object('id',payout_row.id,'producerId',payout_row.producer_id,'currency',payout_row.currency,'amountMinor',payout_row.amount_minor,'status',payout_row.status,'provider',payout_row.provider,'providerReference',payout_row.provider_reference);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_update_product_export_profile_v1(p_product_id uuid, p_export_status text, p_country_of_origin_code text, p_customs_hs_code text, p_customs_description text, p_is_perishable boolean, p_requires_cold_chain boolean, p_shelf_life_days integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  product_row public.products%rowtype;
  export_status_value text:=lower(btrim(coalesce(p_export_status,'')));
  origin_code text:=upper(nullif(btrim(coalesce(p_country_of_origin_code,'')),''));
  hs_code text:=nullif(regexp_replace(btrim(coalesce(p_customs_hs_code,'')),'\s+','','g'),'');
  customs_text text:=nullif(btrim(coalesce(p_customs_description,'')),'');
begin
  if caller_id is null or not coalesce(private.has_permission('product.update'),false) then raise exception 'admin_required' using errcode='42501'; end if;
  if export_status_value not in ('not_configured','domestic_only','manual_review','eligible') then raise exception 'invalid_export_status' using errcode='22023'; end if;
  if origin_code is not null and origin_code !~ '^[A-Z]{2}$' then raise exception 'invalid_origin_country' using errcode='22023'; end if;
  if hs_code is not null and (char_length(hs_code) not between 4 and 16 or hs_code !~ '^[0-9.]+$') then raise exception 'invalid_hs_code' using errcode='22023'; end if;
  if customs_text is not null and char_length(customs_text)>500 then raise exception 'customs_description_too_long' using errcode='22023'; end if;
  if p_shelf_life_days is not null and p_shelf_life_days not between 1 and 3650 then raise exception 'invalid_shelf_life_days' using errcode='22023'; end if;
  if export_status_value='eligible' and (origin_code is null or hs_code is null or customs_text is null) then raise exception 'eligible_export_profile_requires_customs_data' using errcode='22023'; end if;
  update public.products
  set export_status=export_status_value,country_of_origin_code=origin_code,customs_hs_code=hs_code,customs_description=customs_text,
      is_perishable=coalesce(p_is_perishable,false),requires_cold_chain=coalesce(p_requires_cold_chain,false),shelf_life_days=p_shelf_life_days,updated_at=timezone('utc',now())
  where id=p_product_id and deleted_at is null returning * into product_row;
  if product_row.id is null then raise exception 'product_not_found' using errcode='P0002'; end if;
  return jsonb_build_object('productId',product_row.id,'exportStatus',product_row.export_status,'countryOfOriginCode',product_row.country_of_origin_code,'customsHsCode',product_row.customs_hs_code,'isPerishable',product_row.is_perishable,'requiresColdChain',product_row.requires_cold_chain,'shelfLifeDays',product_row.shelf_life_days);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_update_return_v2(p_return_id uuid, p_status text, p_reason text DEFAULT NULL::text, p_resolution text DEFAULT NULL::text, p_restock_approved boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  target_return public.return_requests%rowtype;
  next_status text:=lower(btrim(coalesce(p_status,'')));
  normalized_reason text:=nullif(btrim(coalesce(p_reason,'')),'');
  normalized_resolution text:=nullif(lower(btrim(coalesce(p_resolution,''))),'');
begin
  if caller_id is null or not private.has_permission('refund.approve') then raise exception 'permission_required:refund.approve' using errcode='42501'; end if;
  if next_status not in ('under_review','approved','rejected','in_transit','received','closed') then raise exception 'invalid_return_status' using errcode='22023'; end if;
  if normalized_resolution is not null and normalized_resolution not in ('refund','replacement','partial_refund','store_credit','none') then raise exception 'invalid_return_resolution' using errcode='22023'; end if;
  if normalized_reason is not null and char_length(normalized_reason)>3000 then raise exception 'return_reason_too_long' using errcode='22023'; end if;
  select * into target_return from public.return_requests request where request.id=p_return_id for update;
  if target_return.id is null then raise exception 'return_request_not_found' using errcode='P0002'; end if;
  if not (
    (target_return.status='requested' and next_status in ('under_review','approved','rejected')) or
    (target_return.status='under_review' and next_status in ('approved','rejected')) or
    (target_return.status='approved' and next_status in ('in_transit','received','closed')) or
    (target_return.status='in_transit' and next_status in ('received','closed')) or
    (target_return.status='received' and next_status='closed')
  ) then raise exception 'invalid_return_status_transition:%:%',target_return.status,next_status using errcode='22023'; end if;
  if next_status='rejected' and char_length(coalesce(normalized_reason,''))<8 then raise exception 'rejection_reason_required' using errcode='22023'; end if;
  if next_status in ('approved','received','closed') and normalized_resolution is null then normalized_resolution:=target_return.resolution; end if;
  if next_status='approved' and normalized_resolution is null then raise exception 'return_resolution_required' using errcode='22023'; end if;
  if next_status='received' and p_restock_approved is null then raise exception 'restock_decision_required' using errcode='22023'; end if;
  update public.return_requests
  set status=next_status,
      review_reason=case when next_status='rejected' then normalized_reason else review_reason end,
      reviewed_by=caller_id, reviewed_at=timezone('utc',now()),
      resolution=coalesce(normalized_resolution,resolution),
      resolution_note=coalesce(normalized_reason,resolution_note),
      restock_approved=case when next_status='received' then p_restock_approved else restock_approved end,
      received_at=case when next_status='received' then timezone('utc',now()) else received_at end,
      closed_at=case when next_status='closed' then timezone('utc',now()) else closed_at end
  where id=target_return.id returning * into target_return;
  if next_status='received' and coalesce(p_restock_approved,false) then perform private.restock_return_inventory_v1(target_return.id,caller_id); end if;
  if next_status='closed' then
    update public.order_items item
    set fulfillment_status='returned'
    where exists(select 1 from public.return_items returned where returned.return_id=target_return.id and returned.order_item_id=item.id and returned.quantity>=item.quantity);
  end if;
  insert into public.notifications(user_id,type,title,message,action_url,metadata)
  values(target_return.user_id,'return','İade talebiniz güncellendi',target_return.return_number||' numaralı iade talebinizin yeni durumu: '||next_status||'.','/account/orders',jsonb_build_object('returnId',target_return.id,'orderId',target_return.order_id,'status',next_status,'resolution',target_return.resolution));
  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
  values('return_request',target_return.id,'return.status_changed',jsonb_build_object('return_id',target_return.id,'status',next_status,'resolution',target_return.resolution,'actor_user_id',caller_id));
  return jsonb_build_object('id',target_return.id,'orderId',target_return.order_id,'status',target_return.status,'returnNumber',target_return.return_number,'resolution',target_return.resolution,'restockApproved',target_return.restock_approved);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_upsert_campaign_v2(p_id uuid, p_slug text, p_title text, p_description text, p_banner_path text, p_discount_type text, p_discount_value integer, p_currency text, p_minimum_order_minor bigint, p_usage_limit integer, p_per_user_limit integer, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_status text, p_target_scope text, p_target_ids uuid[], p_activation_mode text, p_priority integer, p_max_discount_minor bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  campaign_id uuid;
  normalized_activation text:=lower(btrim(coalesce(p_activation_mode,'automatic')));
begin
  if auth.uid() is null or not coalesce(private.has_permission('campaign.manage'),false) then raise exception 'admin_required' using errcode='42501'; end if;
  if normalized_activation not in ('automatic','coupon') then raise exception 'invalid_campaign_activation_mode' using errcode='22023'; end if;
  if p_priority is null or p_priority not between -1000 and 1000 then raise exception 'invalid_campaign_priority' using errcode='22023'; end if;
  if p_max_discount_minor is not null and p_max_discount_minor<=0 then raise exception 'invalid_campaign_max_discount' using errcode='22023'; end if;
  campaign_id:=public.admin_upsert_campaign(
    p_id,p_slug,p_title,p_description,p_banner_path,p_discount_type,p_discount_value,p_currency,
    p_minimum_order_minor,p_usage_limit,p_per_user_limit,p_starts_at,p_ends_at,p_status,p_target_scope,p_target_ids
  );
  update public.campaigns
  set activation_mode=normalized_activation, priority=p_priority, max_discount_minor=p_max_discount_minor, updated_at=timezone('utc',now())
  where id=campaign_id;
  return jsonb_build_object('id',campaign_id,'activationMode',normalized_activation,'priority',p_priority,'maxDiscountMinor',p_max_discount_minor);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_upsert_coupon_v1(p_id uuid, p_campaign_id uuid, p_code text, p_status text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_usage_limit integer, p_per_user_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  target_campaign public.campaigns%rowtype;
  normalized_status text := lower(btrim(coalesce(p_status,'active')));
  normalized_code text;
  code_hash_value text;
  display_hint_value text;
  coupon_row public.coupons%rowtype;
begin
  if caller_id is null or not coalesce(private.has_permission('campaign.manage'),false) then
    raise exception 'admin_required' using errcode='42501';
  end if;
  select campaign.* into target_campaign from public.campaigns campaign where campaign.id=p_campaign_id;
  if target_campaign.id is null then raise exception 'campaign_not_found' using errcode='P0002'; end if;
  if target_campaign.activation_mode<>'coupon' then raise exception 'campaign_not_coupon_activated' using errcode='22023'; end if;
  if normalized_status not in ('active','disabled','expired') then raise exception 'invalid_coupon_status' using errcode='22023'; end if;
  if p_starts_at is not null and p_ends_at is not null and p_ends_at<=p_starts_at then raise exception 'invalid_coupon_dates' using errcode='22023'; end if;
  if p_usage_limit is not null and p_usage_limit<=0 then raise exception 'invalid_coupon_usage_limit' using errcode='22023'; end if;
  if p_per_user_limit is null or p_per_user_limit<=0 then raise exception 'invalid_coupon_per_user_limit' using errcode='22023'; end if;
  if p_id is null or nullif(btrim(coalesce(p_code,'')),'') is not null then
    normalized_code:=private.normalize_coupon_code_v1(p_code);
    code_hash_value:=private.hash_coupon_code_v1(normalized_code);
    display_hint_value:=case
      when char_length(normalized_code)<=6 then left(normalized_code,2)||'••'||right(normalized_code,2)
      else left(normalized_code,3)||'••••'||right(normalized_code,2)
    end;
  end if;
  if p_id is null then
    if code_hash_value is null then raise exception 'coupon_code_required' using errcode='22023'; end if;
    insert into public.coupons(campaign_id,code_hash,display_hint,status,starts_at,ends_at,usage_limit,per_user_limit)
    values (p_campaign_id,code_hash_value,display_hint_value,normalized_status,p_starts_at,p_ends_at,p_usage_limit,p_per_user_limit)
    returning * into coupon_row;
  else
    update public.coupons coupon
    set campaign_id=p_campaign_id, code_hash=coalesce(code_hash_value,coupon.code_hash), display_hint=coalesce(display_hint_value,coupon.display_hint),
        status=normalized_status, starts_at=p_starts_at, ends_at=p_ends_at, usage_limit=p_usage_limit, per_user_limit=p_per_user_limit
    where coupon.id=p_id returning * into coupon_row;
    if coupon_row.id is null then raise exception 'coupon_not_found' using errcode='P0002'; end if;
  end if;
  insert into private.audit_log(actor_user_id,action,record_type,record_id,metadata)
  values(caller_id,case when p_id is null then 'coupon.created' else 'coupon.updated' end,'coupon',coupon_row.id,jsonb_build_object('campaign_id',coupon_row.campaign_id,'status',coupon_row.status,'display_hint',coupon_row.display_hint));
  return jsonb_build_object('id',coupon_row.id,'campaignId',coupon_row.campaign_id,'displayHint',coupon_row.display_hint,'status',coupon_row.status,'startsAt',coupon_row.starts_at,'endsAt',coupon_row.ends_at,'usageLimit',coupon_row.usage_limit,'perUserLimit',coupon_row.per_user_limit);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_upsert_product_export_rule_v1(p_product_id uuid, p_category_id uuid, p_country_code text, p_decision text, p_public_note text, p_internal_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  country_code text:=upper(btrim(coalesce(p_country_code,'')));
  decision_value text:=lower(btrim(coalesce(p_decision,'')));
  rule_row private.product_export_country_rules%rowtype;
begin
  if caller_id is null or not coalesce(private.has_permission('product.update'),false) then raise exception 'admin_required' using errcode='42501'; end if;
  if ((p_product_id is not null)::integer+(p_category_id is not null)::integer)<>1 then raise exception 'exactly_one_export_rule_target_required' using errcode='22023'; end if;
  if country_code !~ '^[A-Z]{2}$' then raise exception 'invalid_country_code' using errcode='22023'; end if;
  if decision_value not in ('allowed','manual_review','restricted','prohibited') then raise exception 'invalid_export_decision' using errcode='22023'; end if;
  if char_length(coalesce(p_public_note,''))>500 or char_length(coalesce(p_internal_note,''))>2000 then raise exception 'export_rule_note_too_long' using errcode='22023'; end if;
  if p_product_id is not null then
    insert into private.product_export_country_rules(product_id,country_code,decision,public_note,internal_note,created_by,updated_by)
    values(p_product_id,country_code,decision_value,coalesce(p_public_note,''),coalesce(p_internal_note,''),caller_id,caller_id)
    on conflict (product_id,country_code) where product_id is not null do update
    set decision=excluded.decision,public_note=excluded.public_note,internal_note=excluded.internal_note,updated_by=caller_id,updated_at=timezone('utc',now())
    returning * into rule_row;
  else
    insert into private.product_export_country_rules(category_id,country_code,decision,public_note,internal_note,created_by,updated_by)
    values(p_category_id,country_code,decision_value,coalesce(p_public_note,''),coalesce(p_internal_note,''),caller_id,caller_id)
    on conflict (category_id,country_code) where category_id is not null do update
    set decision=excluded.decision,public_note=excluded.public_note,internal_note=excluded.internal_note,updated_by=caller_id,updated_at=timezone('utc',now())
    returning * into rule_row;
  end if;
  return jsonb_build_object('id',rule_row.id,'productId',rule_row.product_id,'categoryId',rule_row.category_id,'countryCode',rule_row.country_code,'decision',rule_row.decision,'publicNote',rule_row.public_note);
end;
$function$;

CREATE OR REPLACE FUNCTION private.apply_verified_payment_v1(p_order_id uuid, p_provider text, p_provider_reference text, p_payment_method_type text, p_amount_minor bigint, p_currency text, p_status text, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_order public.orders%rowtype;
  normalized_provider text := lower(btrim(coalesce(p_provider,'')));
  normalized_reference text := btrim(coalesce(p_provider_reference,''));
  normalized_method text := lower(btrim(coalesce(p_payment_method_type,'')));
  normalized_currency text := upper(btrim(coalesce(p_currency,'')));
  normalized_status text := lower(btrim(coalesce(p_status,'')));
  existing_payment public.payment_records%rowtype;
  payment_id uuid;
  new_payment_status text;
  should_confirm boolean := false;
  event_id text;
begin
  if p_order_id is null then raise exception 'order_required' using errcode='22023'; end if;
  if char_length(normalized_provider) not between 2 and 80 then raise exception 'invalid_payment_provider' using errcode='22023'; end if;
  if char_length(normalized_reference) not between 4 and 220 then raise exception 'invalid_payment_reference' using errcode='22023'; end if;
  if normalized_method not in ('card','bank_transfer','cash_on_delivery','wallet','other') then raise exception 'invalid_payment_method' using errcode='22023'; end if;
  if normalized_currency !~ '^[A-Z]{3}$' then raise exception 'invalid_payment_currency' using errcode='22023'; end if;
  if normalized_status not in ('authorized','captured','failed','cancelled') then raise exception 'invalid_payment_status' using errcode='22023'; end if;

  select o.* into target_order from public.orders o where o.id=p_order_id for update;
  if target_order.id is null then raise exception 'order_not_found' using errcode='P0002'; end if;
  if target_order.status in ('cancelled','refunded') then raise exception 'terminal_order_payment_not_allowed' using errcode='55000'; end if;
  if normalized_currency<>target_order.currency then raise exception 'payment_currency_mismatch' using errcode='22023'; end if;
  if p_amount_minor<>target_order.total_minor then raise exception 'payment_amount_mismatch' using errcode='22023'; end if;

  select payment.* into existing_payment
  from public.payment_records payment
  where payment.provider=normalized_provider and payment.provider_reference=normalized_reference
  for update;

  if existing_payment.id is not null then
    if existing_payment.order_id<>target_order.id
      or existing_payment.amount_minor<>p_amount_minor
      or existing_payment.currency<>normalized_currency
      or existing_payment.payment_method_type<>normalized_method then
      raise exception 'payment_reference_reused' using errcode='23505';
    end if;
    if existing_payment.status=normalized_status then
      return jsonb_build_object('paymentId',existing_payment.id,'orderId',target_order.id,'paymentStatus',target_order.payment_status,'orderStatus',target_order.status,'unchanged',true);
    end if;
    if not (
      (existing_payment.status in ('created','pending') and normalized_status in ('authorized','captured','failed','cancelled'))
      or (existing_payment.status='authorized' and normalized_status in ('captured','failed','cancelled'))
    ) then
      raise exception 'invalid_payment_transition:%:%',existing_payment.status,normalized_status using errcode='22023';
    end if;
    update public.payment_records
    set status=normalized_status,
        authorized_at=case when normalized_status in ('authorized','captured') then coalesce(authorized_at,timezone('utc',now())) else authorized_at end,
        captured_at=case when normalized_status='captured' then coalesce(captured_at,timezone('utc',now())) else captured_at end,
        failure_code=case when normalized_status='failed' then 'provider_failure' else null end,
        failure_message=case when normalized_status='failed' then 'Payment rejected by verified payment workflow.' else null end,
        updated_at=timezone('utc',now())
    where id=existing_payment.id returning id into payment_id;
  else
    insert into public.payment_records(order_id,user_id,provider,provider_reference,payment_method_type,amount_minor,currency,status,authorized_at,captured_at,failure_code,failure_message)
    values(target_order.id,target_order.user_id,normalized_provider,normalized_reference,normalized_method,p_amount_minor,normalized_currency,normalized_status,
      case when normalized_status in ('authorized','captured') then timezone('utc',now()) end,
      case when normalized_status='captured' then timezone('utc',now()) end,
      case when normalized_status='failed' then 'provider_failure' end,
      case when normalized_status='failed' then 'Payment rejected by verified payment workflow.' end)
    returning id into payment_id;
  end if;

  new_payment_status:=case normalized_status when 'authorized' then 'authorized' when 'captured' then 'paid' when 'failed' then 'failed' when 'cancelled' then 'unpaid' end;
  should_confirm:=normalized_status='captured' and target_order.status='pending_payment';

  if should_confirm then
    perform private.consume_order_inventory_v1(target_order.id,p_actor_user_id);
    update public.orders set payment_status='paid',status='confirmed',reservation_expires_at=null,updated_at=timezone('utc',now()) where id=target_order.id;
    insert into public.order_status_history(order_id,from_status,to_status,note,visible_to_customer,actor_user_id)
    values(target_order.id,target_order.status,'confirmed','Ödeme tahsil edildi ve sipariş onaylandı.',true,p_actor_user_id);
    insert into public.notifications(user_id,type,title,message,action_url,metadata)
    values(target_order.user_id,'order','Siparişiniz onaylandı',target_order.order_number||' numaralı siparişinizin ödemesi tahsil edildi ve sipariş onaylandı.','/account/orders',jsonb_build_object('orderId',target_order.id,'paymentId',payment_id,'status','confirmed'));
  else
    update public.orders set payment_status=new_payment_status,updated_at=timezone('utc',now()) where id=target_order.id;
  end if;

  event_id:=left(normalized_reference||':'||normalized_status,500);
  insert into private.payment_events(provider,provider_event_id,payment_id,event_type,payload,signature_verified,processing_status,processed_at)
  values(normalized_provider,event_id,payment_id,'payment.'||normalized_status,
    jsonb_build_object('order_id',target_order.id,'provider',normalized_provider,'provider_reference',normalized_reference,'amount_minor',p_amount_minor,'currency',normalized_currency,'status',normalized_status,'actor_user_id',p_actor_user_id),
    normalized_provider<>'manual','processed',timezone('utc',now()))
  on conflict(provider,provider_event_id) do nothing;

  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
  values('payment',payment_id,'payment.'||normalized_status,jsonb_build_object('payment_id',payment_id,'order_id',target_order.id,'status',normalized_status));

  return jsonb_build_object('paymentId',payment_id,'orderId',target_order.id,'paymentStatus',new_payment_status,'orderStatus',case when should_confirm then 'confirmed' else target_order.status end);
end;
$function$;

CREATE OR REPLACE FUNCTION private.apply_verified_refund_v1(p_return_id uuid, p_payment_id uuid, p_provider text, p_provider_reference text, p_amount_minor bigint, p_currency text, p_status text, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_return public.return_requests%rowtype;
  target_payment public.payment_records%rowtype;
  target_order public.orders%rowtype;
  normalized_provider text:=lower(btrim(coalesce(p_provider,'')));
  normalized_reference text:=btrim(coalesce(p_provider_reference,''));
  normalized_currency text:=upper(btrim(coalesce(p_currency,'')));
  normalized_status text:=lower(btrim(coalesce(p_status,'')));
  refund_row public.refunds%rowtype;
  succeeded_total bigint;
  payment_refunded_total bigint;
  new_payment_status text;
begin
  if p_amount_minor is null or p_amount_minor<=0 then raise exception 'invalid_refund_amount' using errcode='22023'; end if;
  if char_length(normalized_provider) not between 2 and 80 or char_length(normalized_reference) not between 4 and 180 then raise exception 'invalid_refund_reference' using errcode='22023'; end if;
  if normalized_currency !~ '^[A-Z]{3}$' then raise exception 'invalid_refund_currency' using errcode='22023'; end if;
  if normalized_status not in ('pending','processing','succeeded','failed','cancelled') then raise exception 'invalid_refund_status' using errcode='22023'; end if;

  select * into target_return from public.return_requests where id=p_return_id for update;
  if target_return.id is null then raise exception 'return_request_not_found' using errcode='P0002'; end if;
  if target_return.status not in ('approved','in_transit','received','refunded','closed') then raise exception 'return_not_ready_for_refund' using errcode='55000'; end if;
  if target_return.resolution not in ('refund','partial_refund') then raise exception 'return_resolution_not_refundable' using errcode='55000'; end if;

  select * into target_payment from public.payment_records payment where payment.id=p_payment_id and payment.order_id=target_return.order_id for update;
  if target_payment.id is null then raise exception 'payment_not_found_for_return' using errcode='P0002'; end if;
  if target_payment.status not in ('captured','partially_refunded','refunded') then raise exception 'payment_not_refundable' using errcode='55000'; end if;
  if target_payment.currency<>normalized_currency then raise exception 'refund_currency_mismatch' using errcode='22023'; end if;

  select * into target_order from public.orders where id=target_return.order_id for update;

  select coalesce(sum(refund.amount_minor),0)::bigint into payment_refunded_total
  from public.refunds refund
  where refund.payment_id=target_payment.id and refund.status='succeeded'
    and not (refund.provider=normalized_provider and refund.provider_reference=normalized_reference);
  if payment_refunded_total+p_amount_minor>target_payment.amount_minor then raise exception 'refund_exceeds_payment' using errcode='22023'; end if;

  select * into refund_row from public.refunds refund
  where refund.provider=normalized_provider and refund.provider_reference=normalized_reference for update;

  if refund_row.id is null then
    insert into public.refunds(order_id,return_id,payment_id,amount_minor,currency,reason,provider,provider_reference,status,processed_at)
    values(target_return.order_id,target_return.id,target_payment.id,p_amount_minor,normalized_currency,coalesce(target_return.resolution_note,target_return.customer_message),normalized_provider,normalized_reference,normalized_status,case when normalized_status in ('succeeded','failed','cancelled') then timezone('utc',now()) end)
    returning * into refund_row;
  else
    if refund_row.order_id<>target_return.order_id or refund_row.payment_id is distinct from target_payment.id or refund_row.amount_minor<>p_amount_minor or refund_row.currency<>normalized_currency then raise exception 'refund_reference_reused' using errcode='23505'; end if;
    if refund_row.status<>normalized_status then
      if not ((refund_row.status='pending' and normalized_status in ('processing','succeeded','failed','cancelled')) or (refund_row.status='processing' and normalized_status in ('succeeded','failed','cancelled'))) then raise exception 'invalid_refund_transition:%:%',refund_row.status,normalized_status using errcode='22023'; end if;
      update public.refunds set status=normalized_status,processed_at=case when normalized_status in ('succeeded','failed','cancelled') then timezone('utc',now()) else processed_at end,updated_at=timezone('utc',now()) where id=refund_row.id returning * into refund_row;
    end if;
  end if;

  if normalized_status='succeeded' then
    select coalesce(sum(refund.amount_minor),0)::bigint into succeeded_total from public.refunds refund where refund.order_id=target_order.id and refund.status='succeeded';
    new_payment_status:=case when succeeded_total>=target_order.total_minor then 'refunded' else 'partially_refunded' end;
    update public.orders set payment_status=new_payment_status,status=case when succeeded_total>=target_order.total_minor then 'refunded' else status end,updated_at=timezone('utc',now()) where id=target_order.id;
    update public.payment_records set status=case when payment_refunded_total+p_amount_minor>=amount_minor then 'refunded' else 'partially_refunded' end,updated_at=timezone('utc',now()) where id=target_payment.id;
    update public.return_requests set status='refunded',reviewed_at=timezone('utc',now()) where id=target_return.id and status<>'closed';
    insert into public.notifications(user_id,type,title,message,action_url,metadata)
    values(target_return.user_id,'return','Ödeme iadeniz işlendi',target_return.return_number||' numaralı iade talebiniz için ödeme iadesi işlendi.','/account/orders',jsonb_build_object('returnId',target_return.id,'refundId',refund_row.id,'amountMinor',p_amount_minor,'currency',normalized_currency));
  end if;

  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
  values('refund',refund_row.id,'refund.'||normalized_status,jsonb_build_object('refund_id',refund_row.id,'return_id',target_return.id,'order_id',target_order.id,'status',normalized_status,'amount_minor',p_amount_minor,'currency',normalized_currency));

  return jsonb_build_object('refundId',refund_row.id,'returnId',target_return.id,'orderId',target_order.id,'status',refund_row.status,'amountMinor',refund_row.amount_minor,'currency',refund_row.currency);
end;
$function$;

CREATE OR REPLACE FUNCTION private.assert_platform_access_v1(p_user_id uuid DEFAULT auth.uid())
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare block jsonb:=private.platform_access_block_v1(p_user_id);
begin
  if coalesce((block->>'blocked')::boolean,false) then raise exception 'platform_access_blocked:%',coalesce(block->>'code','blocked') using errcode='42501'; end if;
end;
$function$;

CREATE OR REPLACE FUNCTION private.assert_published_product_media_integrity_v1(p_product_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if exists(
    select 1 from public.products p
    where p.id=p_product_id
      and p.status='published'
      and p.deleted_at is null
  ) and not private.product_media_integrity_ok_v1(p_product_id) then
    raise exception 'published_product_requires_verified_media' using errcode='23514';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION private.assign_store_number_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op='INSERT' then
    new.store_number:='GO-STORE-'||lpad(nextval('private.store_number_seq'::regclass)::text,8,'0');
  elsif new.store_number is distinct from old.store_number then
    raise exception 'store_number_immutable' using errcode='42501';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.audit_role_permission_change_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is not null then
    insert into private.admin_audit_logs(actor_user_id,action,target_type,target_id,details,correlation_id,before_state,after_state)
    values(
      auth.uid(),
      'authorization.role_permission_changed',
      'role_permission',
      coalesce(new.role,old.role)||':'||coalesce(new.permission_key,old.permission_key),
      jsonb_build_object('operation',tg_op),
      gen_random_uuid(),
      case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) else null end,
      case when tg_op in ('UPDATE','INSERT') then to_jsonb(new) else null end
    );
  end if;
  return coalesce(new,old);
end;
$function$;

CREATE OR REPLACE FUNCTION private.audit_row_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  old_row jsonb;
  new_row jsonb;
  row_id text;
  jwt_claims jsonb;
begin
  old_row := case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) else null end;
  new_row := case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) else null end;
  row_id := coalesce(new_row ->> 'id', old_row ->> 'id', new_row ->> 'user_id', old_row ->> 'user_id');
  jwt_claims := coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb, '{}'::jsonb);

  insert into private.audit_log(
    table_schema,
    table_name,
    record_id,
    action,
    actor_user_id,
    actor_role,
    old_data,
    new_data,
    request_id
  ) values (
    tg_table_schema,
    tg_table_name,
    row_id,
    tg_op,
    auth.uid(),
    coalesce(jwt_claims ->> 'role', current_user),
    old_row,
    new_row,
    coalesce(nullif(current_setting('request.headers', true), '')::jsonb, '{}'::jsonb) ->> 'x-request-id'
  );

  return case when tg_op = 'DELETE' then old else new end;
end;
$function$;

CREATE OR REPLACE FUNCTION private.audit_staff_mfa_challenge_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid;
begin
  select f.user_id into uid from auth.mfa_factors f where f.id=coalesce(new.factor_id,old.factor_id) and f.factor_type::text='totp';
  if uid is null or not private.user_requires_staff_mfa_v1(uid) then return coalesce(new,old); end if;
  if tg_op='INSERT' then
    insert into private.admin_audit_logs(actor_user_id,action,target_type,target_id,details)
    values(uid,'mfa.challenge_started','mfa_challenge',new.id::text,jsonb_build_object('factorId',new.factor_id::text));
  elsif tg_op='UPDATE' and old.verified_at is null and new.verified_at is not null then
    insert into private.admin_audit_logs(actor_user_id,action,target_type,target_id,details)
    values(uid,'mfa.challenge_succeeded','mfa_challenge',new.id::text,jsonb_build_object('factorId',new.factor_id::text));
  end if;
  return coalesce(new,old);
end;
$function$;

CREATE OR REPLACE FUNCTION private.audit_staff_mfa_factor_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=coalesce(new.user_id,old.user_id); changed_to_verified boolean:=false; prior_state text; recovery_until timestamptz;
begin
  if coalesce(new.factor_type,old.factor_type)::text<>'totp' then return coalesce(new,old); end if;
  if not private.user_requires_staff_mfa_v1(uid) and not exists(select 1 from private.staff_mfa_security_state s where s.user_id=uid) then return coalesce(new,old); end if;
  if tg_op='INSERT' then
    insert into private.admin_audit_logs(actor_user_id,action,target_type,target_id,details) values(uid,'mfa.enrollment_started','mfa_factor',new.id::text,jsonb_build_object('factorType','totp','status',new.status::text));
  elsif tg_op='UPDATE' then
    changed_to_verified:=old.status::text<>'verified' and new.status::text='verified';
    if changed_to_verified then
      select s.state into prior_state from private.staff_mfa_security_state s where s.user_id=uid for update;
      insert into private.staff_mfa_security_state(user_id,state,enforced_at,transition_completed_at,recovery_authorized_until,recovery_reason,recovery_completed_at,updated_at)
      values(uid,'enforced',timezone('utc',now()),timezone('utc',now()),null,null,timezone('utc',now()),timezone('utc',now()))
      on conflict(user_id) do update set state='enforced',enforced_at=coalesce(private.staff_mfa_security_state.enforced_at,excluded.enforced_at),transition_completed_at=coalesce(private.staff_mfa_security_state.transition_completed_at,excluded.transition_completed_at),recovery_authorized_until=null,recovery_reason=null,recovery_completed_at=case when private.staff_mfa_security_state.recovery_started_at is not null then timezone('utc',now()) else private.staff_mfa_security_state.recovery_completed_at end,updated_at=timezone('utc',now());
      insert into private.admin_audit_logs(actor_user_id,action,target_type,target_id,details) values(uid,'mfa.factor_verified','mfa_factor',new.id::text,jsonb_build_object('factorType','totp','status','verified'));
      if coalesce(prior_state,'enrollment_required')<>'enforced' then insert into private.admin_audit_logs(actor_user_id,action,target_type,target_id,details) values(uid,'mfa.transition_completed','account_security',uid::text,jsonb_build_object('state','enforced')); end if;
    end if;
  elsif tg_op='DELETE' and old.status::text='verified' then
    select s.recovery_authorized_until into recovery_until from private.staff_mfa_security_state s where s.user_id=uid;
    insert into private.admin_audit_logs(actor_user_id,action,target_type,target_id,details) values(uid,'mfa.factor_removed','mfa_factor',old.id::text,jsonb_build_object('factorType','totp','status','verified','breakGlass',recovery_until is not null and recovery_until>timezone('utc',now())));
    if recovery_until is not null and recovery_until>timezone('utc',now()) and not exists(select 1 from auth.mfa_factors f where f.user_id=uid and f.id<>old.id and f.factor_type::text='totp' and f.status::text='verified') then
      update private.staff_mfa_security_state set state='enforced',recovery_authorized_until=null,recovery_completed_at=timezone('utc',now()),updated_at=timezone('utc',now()) where user_id=uid;
      insert into private.admin_audit_logs(actor_user_id,action,target_type,target_id,details) values(null,'mfa.break_glass_factor_reset','account_security',uid::text,jsonb_build_object('state','enforced','requiresNewTotp',true));
    end if;
  end if;
  return coalesce(new,old);
end;
$function$;

CREATE OR REPLACE FUNCTION private.authorization_context_core_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  uid uuid:=auth.uid(); profile public.profiles%rowtype; roles_json jsonb; permissions_json jsonb;
  staff_mfa_required boolean; mfa_factor_enrolled boolean; aal text; mfa_satisfied boolean; mfa_state text; mfa_transition_pending boolean;
begin
  if uid is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into profile from public.profiles where id=uid;
  if profile.id is null then raise exception 'profile_not_found' using errcode='P0002'; end if;
  select coalesce(jsonb_agg(role order by priority),'[]'::jsonb) into roles_json from(
    select distinct ur.role,case ur.role when 'super_admin' then 1 when 'admin' then 2 when 'operations' then 3 when 'moderator' then 4 when 'content_editor' then 5 when 'support' then 6 when 'producer' then 7 when 'customer' then 8 else 99 end priority
    from private.user_roles ur where ur.user_id=uid and (ur.expires_at is null or ur.expires_at>timezone('utc',now()))
  ) active_roles;
  staff_mfa_required:=private.user_requires_staff_mfa_v1(uid);
  mfa_factor_enrolled:=private.user_has_verified_totp_factor_v1(uid);
  aal:=private.current_authenticator_assurance_level_v1();
  mfa_state:=private.staff_mfa_state_v1(uid);
  mfa_transition_pending:=staff_mfa_required and coalesce(mfa_state,'enrollment_required')='enrollment_required';
  mfa_satisfied:=not staff_mfa_required or (mfa_state='enforced' and mfa_factor_enrolled and aal='aal2');

  if profile.status='active' and profile.deleted_at is null and not coalesce((private.platform_access_block_v1(uid)->>'blocked')::boolean,false) then
    select coalesce(jsonb_agg(permission_key order by permission_key),'[]'::jsonb) into permissions_json from(
      select distinct rp.permission_key
      from private.user_roles ur join private.role_permissions rp on rp.role=ur.role join private.permissions p on p.permission_key=rp.permission_key and p.is_active=true
      where ur.user_id=uid and (ur.expires_at is null or ur.expires_at>timezone('utc',now()))
        and (not staff_mfa_required or rp.permission_key='mfa.self_manage' or mfa_satisfied)
    ) effective_permissions;
  else permissions_json:='[]'::jsonb; end if;

  return jsonb_build_object(
    'userId',uid,'accountStatus',profile.status,'roles',roles_json,'permissions',permissions_json,
    'canAccessAdmin',private.has_permission('admin.access'),'isAdmin',private.has_role('admin') or private.has_role('super_admin'),'isSuperAdmin',private.has_role('super_admin'),
    'staffMfaRequired',staff_mfa_required,'mfaFactorEnrolled',mfa_factor_enrolled,'mfaSatisfied',mfa_satisfied,'mfaEnforcementActive',staff_mfa_required,
    'staffMfaState',mfa_state,'staffMfaTransitionPending',mfa_transition_pending,'authenticatorAssuranceLevel',aal
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.authorization_function_mentions_v1(p_signature text, p_needles text[])
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare fn_oid oid; definition text; needle text;
begin
  fn_oid:=to_regprocedure(p_signature);
  if fn_oid is null then return false; end if;
  definition:=pg_get_functiondef(fn_oid);
  foreach needle in array p_needles loop
    if position(needle in definition)=0 then return false; end if;
  end loop;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION private.auto_enable_rls_on_new_tables_v1()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  created record;
begin
  for created in
    select objid, schema_name, object_identity
    from pg_event_trigger_ddl_commands()
    where command_tag = 'CREATE TABLE'
      and schema_name = 'private'
  loop
    -- skip partitions; they follow the parent table's setting
    if exists (
      select 1 from pg_class c
      where c.oid = created.objid and c.relispartition
    ) then
      continue;
    end if;

    if exists (
      select 1 from pg_class c
      where c.oid = created.objid
        and c.relkind = 'r'
        and c.relrowsecurity = false
    ) then
      execute format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', created.object_identity);
      raise notice 'auto-enabled row level security on %', created.object_identity;
    end if;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION private.bootstrap_super_admin_v1(p_user_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  reason_value text:=btrim(coalesce(p_reason,''));
  target public.profiles%rowtype;
  active_count integer;
begin
  if auth.role()<>'service_role' then raise exception 'service_role_required' using errcode='42501'; end if;
  if p_user_id is null then raise exception 'bootstrap_target_required' using errcode='22023'; end if;
  if char_length(reason_value) not between 20 and 500 then raise exception 'bootstrap_reason_required' using errcode='22023'; end if;

  perform pg_advisory_xact_lock(hashtext('golden-oremar:super-admin-bootstrap'));
  select count(*) into active_count
  from private.user_roles ur
  join public.profiles p on p.id=ur.user_id
  where ur.role='super_admin'
    and (ur.expires_at is null or ur.expires_at>timezone('utc',now()))
    and p.status='active' and p.deleted_at is null
    and not coalesce((private.platform_access_block_v1(ur.user_id)->>'blocked')::boolean,false);
  if active_count<>0 then raise exception 'super_admin_already_configured' using errcode='42501'; end if;

  select * into target from public.profiles where id=p_user_id for update;
  if target.id is null or target.status<>'active' or target.deleted_at is not null then raise exception 'bootstrap_target_not_active' using errcode='42501'; end if;
  if coalesce((private.platform_access_block_v1(p_user_id)->>'blocked')::boolean,false) then raise exception 'bootstrap_target_blocked' using errcode='42501'; end if;

  insert into private.user_roles(user_id,role,granted_by)
  values(p_user_id,'customer',null)
  on conflict(user_id,role) do update set granted_at=timezone('utc',now()),expires_at=null;
  insert into private.user_roles(user_id,role,granted_by)
  values(p_user_id,'super_admin',null)
  on conflict(user_id,role) do update set granted_at=timezone('utc',now()),expires_at=null;

  insert into private.admin_audit_logs(actor_user_id,action,target_type,target_id,details,correlation_id,before_state,after_state)
  values(null,'authorization.break_glass_super_admin_bootstrap','user',p_user_id::text,
    jsonb_build_object('reason',reason_value,'executionRole','service_role','automaticAssignment',false),
    gen_random_uuid(),jsonb_build_object('activeSuperAdmins',0),jsonb_build_object('roles',jsonb_build_array('customer','super_admin')));

  return jsonb_build_object('ok',true,'userId',p_user_id,'role','super_admin','breakGlass',true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.brand_contrast_ratio_v1(p_foreground text, p_background text)
 RETURNS double precision
 LANGUAGE sql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
  with l as (
    select private.brand_hex_luminance_v1(p_foreground) as a,
           private.brand_hex_luminance_v1(p_background) as b
  )
  select (greatest(a,b)+0.05)/(least(a,b)+0.05) from l;
$function$;

CREATE OR REPLACE FUNCTION private.brand_hex_luminance_v1(p_hex text)
 RETURNS double precision
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
declare
  raw text := upper(btrim(p_hex));
  bytes bytea;
  r double precision;
  g double precision;
  b double precision;
  lr double precision;
  lg double precision;
  lb double precision;
begin
  if raw !~ '^#[0-9A-F]{6}$' then
    raise exception 'invalid_brand_hex_color' using errcode='22023';
  end if;
  bytes := decode(substr(raw,2,6),'hex');
  r := get_byte(bytes,0) / 255.0;
  g := get_byte(bytes,1) / 255.0;
  b := get_byte(bytes,2) / 255.0;
  lr := case when r <= 0.03928 then r / 12.92 else power((r + 0.055) / 1.055, 2.4) end;
  lg := case when g <= 0.03928 then g / 12.92 else power((g + 0.055) / 1.055, 2.4) end;
  lb := case when b <= 0.03928 then b / 12.92 else power((b + 0.055) / 1.055, 2.4) end;
  return 0.2126 * lr + 0.7152 * lg + 0.0722 * lb;
end;
$function$;

CREATE OR REPLACE FUNCTION private.build_event_payment_receipt_payload_v1(p_reservation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  f private.event_reservation_finance%rowtype;
  r public.event_reservations%rowtype;
  event_title text;
  recipient_email text;
  recipient_name text;
  recipient_locale text;
begin
  select * into f from private.event_reservation_finance where reservation_id=p_reservation_id;
  if f.reservation_id is null then raise exception 'event_finance_not_found' using errcode='P0002'; end if;
  if f.payment_status<>'paid' then raise exception 'event_payment_not_paid' using errcode='55000'; end if;
  select * into r from public.event_reservations where id=p_reservation_id;
  if r.id is null then raise exception 'event_reservation_not_found' using errcode='P0002'; end if;
  select e.title into event_title from public.events e where e.id=r.event_id;
  select lower(btrim(coalesce(u.email,''))),coalesce(nullif(btrim(coalesce(p.display_name,'')),''),nullif(btrim(coalesce(r.guest_name,'')),'')),coalesce(nullif(btrim(p.locale),''),'tr')
  into recipient_email,recipient_name,recipient_locale
  from auth.users u left join public.profiles p on p.id=u.id
  where u.id=f.user_id;

  return jsonb_build_object(
    'schemaVersion',1,
    'documentKind','event_payment_receipt',
    'legalInvoice',false,
    'recipientEmail',recipient_email,
    'recipientName',recipient_name,
    'locale',recipient_locale,
    'reservationId',r.id,
    'reservationCode',r.reservation_code,
    'eventId',r.event_id,
    'eventTitle',event_title,
    'guestCount',f.guest_count,
    'ticketPriceMinor',f.ticket_price_minor,
    'totalMinor',f.total_minor,
    'currency',f.currency,
    'paidAt',f.paid_at,
    'paymentProvider',f.provider
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.build_order_payment_receipt_payload_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  o public.orders%rowtype;
  recipient_email text;
  recipient_name text;
  recipient_locale text;
  payment_provider text;
  payment_method text;
  paid_at timestamptz;
  items jsonb;
begin
  select * into o from public.orders where id=p_order_id;
  if o.id is null then raise exception 'order_not_found' using errcode='P0002'; end if;
  if o.payment_status<>'paid' then raise exception 'order_not_paid' using errcode='55000'; end if;

  select lower(btrim(coalesce(u.email,''))),nullif(btrim(coalesce(p.display_name,'')),''),coalesce(nullif(btrim(p.locale),''),'tr')
  into recipient_email,recipient_name,recipient_locale
  from auth.users u left join public.profiles p on p.id=u.id
  where u.id=o.user_id;

  select pr.provider,pr.payment_method_type,coalesce(pr.captured_at,pr.updated_at)
  into payment_provider,payment_method,paid_at
  from public.payment_records pr
  where pr.order_id=o.id and pr.status='captured'
  order by pr.captured_at desc nulls last,pr.updated_at desc
  limit 1;

  select coalesce(jsonb_agg(jsonb_build_object(
    'name',oi.product_name,
    'variant',nullif(btrim(coalesce(oi.variant_name,'')),''),
    'quantity',oi.quantity,
    'lineTotalMinor',oi.line_total_minor
  ) order by oi.created_at,oi.id),'[]'::jsonb)
  into items
  from public.order_items oi where oi.order_id=o.id;

  return jsonb_build_object(
    'schemaVersion',1,
    'documentKind','payment_receipt',
    'legalInvoice',false,
    'recipientEmail',recipient_email,
    'recipientName',recipient_name,
    'locale',recipient_locale,
    'orderId',o.id,
    'orderNumber',o.order_number,
    'currency',o.currency,
    'subtotalMinor',o.subtotal_minor,
    'discountMinor',o.discount_minor,
    'taxMinor',o.tax_minor,
    'shippingMinor',o.shipping_minor,
    'totalMinor',o.total_minor,
    'placedAt',o.placed_at,
    'paidAt',paid_at,
    'paymentProvider',payment_provider,
    'paymentMethod',payment_method,
    'items',items
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.can_delete_catalog_brand_asset_v1(p_path text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  normalized text := private.verified_public_storage_path_v1('catalog-public', p_path);
  producer_id uuid;
begin
  if caller_id is null or normalized is null then
    return false;
  end if;

  if normalized !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}/profile/(logo|cover)-[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|jpeg|png|webp)$' then
    return false;
  end if;

  begin
    producer_id := split_part(normalized, '/', 1)::uuid;
  exception when invalid_text_representation then
    return false;
  end;

  if not exists (
    select 1
    from public.producers p
    where p.id = producer_id
      and p.deleted_at is null
      and (
        p.owner_user_id = caller_id
        or (
          p.store_kind = 'official'
          and coalesce(private.has_permission('product.publish'), false)
        )
      )
  ) then
    return false;
  end if;

  return not private.catalog_public_asset_is_referenced_v1(normalized);
end;
$function$;

CREATE OR REPLACE FUNCTION private.can_delete_unsubmitted_producer_document_v1(p_name text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select
    auth.uid() is not null
    and split_part(coalesce(p_name,''), '/', 1) = auth.uid()::text
    and not exists (
      select 1
      from private.producer_documents d
      where d.storage_path = p_name
    );
$function$;

CREATE OR REPLACE FUNCTION private.can_upload_message_attachment_v1(p_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  owner_segment text:=split_part(coalesce(p_name,''),'/',1);
  conversation_segment text:=split_part(coalesce(p_name,''),'/',2);
  conversation_id_value uuid;
  settings private.message_moderation_settings%rowtype;
begin
  if caller_id is null or owner_segment<>caller_id::text then return false; end if;
  if conversation_segment !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then return false; end if;
  conversation_id_value:=conversation_segment::uuid;
  select * into settings from private.message_moderation_settings where singleton=true;
  if not found or not settings.allow_attachments or settings.max_attachments<=0 then return false; end if;
  return exists(
    select 1
    from public.conversation_participants participant
    join public.conversations conversation on conversation.id=participant.conversation_id
    where participant.user_id=caller_id
      and participant.conversation_id=conversation_id_value
      and conversation.status<>'closed'
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.cancel_account_closure_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); request_row private.account_closure_requests%rowtype;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into request_row from private.account_closure_requests where user_id=caller_id and status='requested' order by requested_at desc limit 1 for update;
  if request_row.id is null then raise exception 'cancellable_account_closure_not_found' using errcode='P0002'; end if;
  update private.account_closure_requests set status='cancelled',updated_at=timezone('utc',now()),processed_at=timezone('utc',now()) where id=request_row.id returning * into request_row;
  return jsonb_build_object('id',request_row.id,'status',request_row.status,'cancelledAt',request_row.processed_at);
end;
$function$;

CREATE OR REPLACE FUNCTION private.cancel_customer_order(p_order_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_user_id uuid := (select auth.uid());
  target_order public.orders%rowtype;
begin
  if current_user_id is null then
    raise exception 'authentication_required' using errcode = '42501';
  end if;

  select customer_order.*
  into target_order
  from public.orders customer_order
  where customer_order.id = p_order_id
    and customer_order.user_id = current_user_id
  for update;

  if not found then
    raise exception 'order_not_found' using errcode = '22023';
  end if;

  if target_order.status = 'cancelled' then
    return true;
  end if;

  if target_order.status <> 'pending_payment' or target_order.payment_status <> 'unpaid' then
    raise exception 'order_cannot_be_cancelled' using errcode = '22023';
  end if;

  perform private.release_order_inventory(target_order.id);

  update public.orders
  set status = 'cancelled',
      cancelled_at = timezone('utc', now()),
      reservation_expires_at = null,
      updated_at = timezone('utc', now())
  where id = target_order.id;

  insert into public.order_status_history(
    order_id,
    from_status,
    to_status,
    note,
    visible_to_customer,
    actor_user_id
  ) values (
    target_order.id,
    target_order.status,
    'cancelled',
    'Müşteri ödeme öncesinde sipariş talebini iptal etti.',
    true,
    current_user_id
  );

  insert into private.outbox_events(
    aggregate_type,
    aggregate_id,
    event_type,
    payload
  ) values (
    'order',
    target_order.id,
    'order.cancelled_by_customer',
    jsonb_build_object('order_id', target_order.id, 'user_id', current_user_id)
  );

  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION private.cancel_my_producer_payout_v2(p_payout_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); p_id uuid; row private.producer_payouts%rowtype;
begin
  if uid is null then raise exception 'authentication_required' using errcode='42501'; end if; if not private.has_permission('payout.request') then raise exception 'permission_required:payout.request' using errcode='42501'; end if;
  select id into p_id from public.producers where owner_user_id=uid and deleted_at is null order by created_at desc limit 1;
  if p_id is null then raise exception 'producer_profile_required' using errcode='42501'; end if;
  select * into row from private.producer_payouts where id=p_payout_id and producer_id=p_id for update;
  if row.id is null then raise exception 'payout_not_found' using errcode='P0002'; end if;
  if row.channel<>'manual_bank_transfer' or row.request_source<>'producer' or row.status<>'requested' then raise exception 'payout_cannot_be_cancelled' using errcode='55000'; end if;
  update private.producer_payouts set status='cancelled',processed_by=uid,processed_at=timezone('utc',now()),updated_at=timezone('utc',now()) where id=row.id returning * into row;
  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload) values('producer_payout',row.id,'producer_payout.cancelled',jsonb_build_object('payout_id',row.id,'producer_id',p_id,'actor_user_id',uid,'source','producer'));
  return jsonb_build_object('id',row.id,'status',row.status);
end;
$function$;

CREATE OR REPLACE FUNCTION private.cancel_my_product_health_change_v1(p_request_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare uid uuid:=auth.uid(); changed integer; begin if uid is null then raise exception 'authentication_required' using errcode='42501'; end if; update private.product_health_change_requests set status='withdrawn',updated_at=timezone('utc',now()) where id=p_request_id and proposed_by=uid and status='pending'; get diagnostics changed=row_count; if changed=0 then raise exception 'product_health_request_not_found' using errcode='P0002'; end if; return true; end;$function$;

CREATE OR REPLACE FUNCTION private.cancel_my_stock_alert_v1(p_variant_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); affected integer;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  update private.stock_alert_subscriptions set status='cancelled' where user_id=caller_id and variant_id=p_variant_id and status='active';
  get diagnostics affected=row_count;
  return affected>0;
end;
$function$;

CREATE OR REPLACE FUNCTION private.cancel_stock_alert_by_token_v1(p_token text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare token_hash text:=private.hash_marketing_token_v1(p_token); affected integer;
begin
  update private.stock_alert_subscriptions set status='cancelled' where unsubscribe_token_hash=token_hash and status='active';
  get diagnostics affected=row_count;
  return affected>0;
end;
$function$;

CREATE OR REPLACE FUNCTION private.catalog_media_binary_verified_path_v2(p_path text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare normalized text := private.verified_public_storage_path_v1('catalog-public', p_path);
begin
  if normalized is null then return null; end if;
  -- R2: verified by media-upload (or adopted from a verified Supabase object).
  if exists (
    select 1 from private.media_cdn_objects m
    where m.bucket_id = 'catalog-public' and m.object_name = normalized and m.origin = 'direct' and m.confirmed and m.binary_verified
      and m.byte_size between 1 and 10485760 and m.sha256 ~ '^[0-9a-f]{64}$'
      and ((m.content_type = 'image/jpeg' and lower(normalized) ~ '\.(jpg|jpeg)$') or (m.content_type = 'image/png' and lower(normalized) ~ '\.png$')
        or (m.content_type = 'image/webp' and lower(normalized) ~ '\.webp$') or (m.content_type = 'image/avif' and lower(normalized) ~ '\.avif$'))) then
    return normalized;
  end if;
  -- Supabase Storage (not yet adopted): the original rule, unchanged.
  if exists (select 1 from storage.objects o join private.catalog_media_binary_verifications_v2 v on v.object_id = o.id
             where o.bucket_id = 'catalog-public' and o.name = normalized and coalesce(o.is_delete_marker,false) = false and o.archived_at is null
               and v.bucket_id = 'catalog-public' and v.object_path = normalized and v.object_version is not distinct from o.version
               and v.object_updated_at is not distinct from o.updated_at and lower(coalesce(o.metadata->>'mimetype','')) = v.detected_mime
               and coalesce(o.metadata->>'size','') ~ '^[0-9]{1,12}$' and (o.metadata->>'size')::bigint = v.byte_size
               and v.byte_size between 1 and 10485760 and v.sha256 ~ '^[0-9a-f]{64}$'
               and ((v.detected_mime = 'image/jpeg' and lower(normalized) ~ '\.(jpg|jpeg)$') or (v.detected_mime = 'image/png' and lower(normalized) ~ '\.png$')
                 or (v.detected_mime = 'image/webp' and lower(normalized) ~ '\.webp$') or (v.detected_mime = 'image/avif' and lower(normalized) ~ '\.avif$'))) then
    return normalized;
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION private.catalog_producer_card_identity_v1(p_producer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  producer_row public.producers%rowtype;
  badge_active boolean;
  follower_count bigint;
begin
  select * into producer_row
  from public.producers p
  where p.id=p_producer_id and p.status='active' and p.is_verified=true and p.deleted_at is null;
  if producer_row.id is null then return null; end if;

  badge_active:=coalesce(private.is_producer_trust_badge_active_v1(producer_row.id),false);
  select count(*) into follower_count from private.producer_follows f where f.producer_id=producer_row.id;

  return jsonb_build_object(
    'verified',badge_active,
    'originVerified',coalesce(producer_row.origin_verified,false) and badge_active,
    'storeKind',producer_row.store_kind,
    'storefrontTier',producer_row.storefront_tier,
    'badgeTone',case when producer_row.store_kind='official' then 'ruby' else 'blue' end,
    'storeBadgeLabel',case when producer_row.store_kind='official' then 'Golden Oremar Resmi Mağazası' else 'Golden Oremar Doğrulanmış Üretici' end,
    'followerCount',follower_count
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.catalog_public_asset_is_referenced_v1(p_path text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with target as (
    select private.verified_public_storage_path_v1('catalog-public',p_path) path
  )
  select coalesce((select path is not null and (
    exists(select 1 from public.product_images i where private.verified_public_storage_path_v1('catalog-public',i.storage_path)=target.path)
    or exists(select 1 from public.producers p where p.deleted_at is null and (
      private.verified_public_storage_path_v1('catalog-public',p.logo_path)=target.path
      or private.verified_public_storage_path_v1('catalog-public',p.cover_path)=target.path
    ))
    or exists(select 1 from public.categories c where private.verified_public_storage_path_v1('catalog-public',c.image_path)=target.path)
    or exists(select 1 from public.content_entries ce where ce.deleted_at is null and private.verified_public_storage_path_v1('catalog-public',ce.hero_image_path)=target.path)
    or exists(select 1 from public.events e where private.verified_public_storage_path_v1('catalog-public',e.image_path)=target.path)
    or exists(select 1 from public.order_items oi where private.verified_public_storage_path_v1('catalog-public',oi.image_path)=target.path)
  ) from target),false);
$function$;

CREATE OR REPLACE FUNCTION private.catalog_public_card_image_path_v1(p_product_image_path text, p_producer_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  verified_product_path text;
  producer_row public.producers%rowtype;
begin
  verified_product_path:=private.verified_public_storage_path_v1('catalog-public',p_product_image_path);
  if verified_product_path is not null then return verified_product_path; end if;
  if p_producer_id is null then return null; end if;
  select * into producer_row from public.producers where id=p_producer_id and deleted_at is null and status='active' and is_verified=true;
  if producer_row.id is null or producer_row.store_kind<>'official' then return null; end if;
  return coalesce(
    private.verified_public_storage_path_v1('catalog-public',producer_row.logo_path),
    private.verified_public_storage_path_v1('catalog-public',producer_row.cover_path)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.catalog_public_card_rows_v1()
 RETURNS TABLE(product_id uuid, category_id uuid, category_slug text, category_name text, producer_id uuid, producer_name text, province text, district text, village text, product_name text, product_search_text text, price_minor bigint, compare_at_price_minor bigint, stock_mode text, available_quantity integer, is_featured boolean, published_at timestamp with time zone, home_section text, average_rating numeric, review_count bigint, card jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select
    product.id,
    category.id,
    category.slug,
    category.name,
    producer.id,
    producer.display_name,
    producer.production_province,
    producer.production_district,
    producer.production_village,
    product.name,
    lower(coalesce(product.search_text,'')),
    variant.price_minor,
    variant.compare_at_price_minor,
    product.stock_mode,
    case
      when product.stock_mode in ('tracked','seasonal')
        then greatest(0,coalesce(inventory.available_quantity,0)-coalesce(inventory.reserved_quantity,0))
      else null
    end,
    product.is_featured,
    product.published_at,
    case
      when nullif(product.specifications->>'homeSection','') in ('natural','seasonal','best_sellers','new_arrivals','offers','concierge','regular')
        then product.specifications->>'homeSection'
      when product.stock_mode='preorder' then 'pre_order'
      when product.is_featured then 'featured'
      else 'regular'
    end,
    coalesce(review_stats.average_rating,0),
    coalesce(review_stats.review_count,0),
    jsonb_build_object(
      'id',product.id,
      'legacyId',product.legacy_id,
      'slug',product.slug,
      'name',product.name,
      'shortDescription',product.short_description,
      'origin',product.origin,
      'unitLabel',product.unit_label,
      'currency',product.currency,
      'stockMode',product.stock_mode,
      'featured',product.is_featured,
      'homeSection',case
        when nullif(product.specifications->>'homeSection','') in ('natural','seasonal','best_sellers','new_arrivals','offers','concierge','regular')
          then product.specifications->>'homeSection'
        when product.stock_mode='preorder' then 'pre_order'
        when product.is_featured then 'featured'
        else 'regular'
      end,
      'category',jsonb_build_object('id',category.id,'slug',category.slug,'name',category.name),
      'producer',jsonb_build_object(
        'id',producer.id,
        'name',producer.display_name,
        'province',producer.production_province,
        'district',producer.production_district,
        'village',producer.production_village
      ) || private.catalog_producer_card_identity_v1(producer.id),
      'variant',jsonb_build_object(
        'id',variant.id,
        'name',variant.name,
        'sku',variant.sku,
        'priceMinor',variant.price_minor,
        'compareAtPriceMinor',variant.compare_at_price_minor,
        'weightGrams',variant.weight_grams
      ),
      'availableQuantity',case
        when product.stock_mode in ('tracked','seasonal')
          then greatest(0,coalesce(inventory.available_quantity,0)-coalesce(inventory.reserved_quantity,0))
        else null
      end,
      'imagePath',private.catalog_public_card_image_path_v1(image.storage_path,producer.id),
      'averageRating',coalesce(review_stats.average_rating,0),
      'reviewCount',coalesce(review_stats.review_count,0),
      'handlingProfile',private.product_handling_profile_v1(product.id)
    )
  from public.products product
  join public.producers producer
    on producer.id=product.producer_id
   and producer.status='active'
   and producer.is_verified=true
   and producer.deleted_at is null
  join public.categories category
    on category.id=product.category_id
   and category.is_active=true
  join lateral(
    select variant_row.*
    from public.product_variants variant_row
    where variant_row.product_id=product.id
      and variant_row.is_active=true
    order by variant_row.is_default desc,variant_row.created_at asc
    limit 1
  ) variant on true
  left join public.product_inventory inventory on inventory.variant_id=variant.id
  left join lateral(
    select image_row.storage_path
    from public.product_images image_row
    where image_row.product_id=product.id
    order by image_row.is_primary desc,image_row.sort_order asc,image_row.created_at asc
    limit 1
  ) image on true
  left join lateral(
    select round(avg(review.rating)::numeric,2) average_rating,count(*)::bigint review_count
    from public.reviews review
    where review.product_id=product.id
      and review.status='published'
  ) review_stats on true
  where product.status='published'
    and product.is_active=true
    and product.deleted_at is null;
$function$;

CREATE OR REPLACE FUNCTION private.catalog_search_facets_v1(p_query text DEFAULT NULL::text, p_category_slug text DEFAULT NULL::text, p_producer_id uuid DEFAULT NULL::uuid, p_province text DEFAULT NULL::text, p_district text DEFAULT NULL::text, p_village text DEFAULT NULL::text, p_min_price_minor bigint DEFAULT NULL::bigint, p_max_price_minor bigint DEFAULT NULL::bigint, p_in_stock boolean DEFAULT false, p_featured boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  q text:=lower(btrim(coalesce(p_query,'')));
  requested_category_slug text:=nullif(lower(btrim(coalesce(p_category_slug,''))),'');
  province_value text:=nullif(lower(btrim(coalesce(p_province,''))),'');
  district_value text:=nullif(lower(btrim(coalesce(p_district,''))),'');
  village_value text:=nullif(lower(btrim(coalesce(p_village,''))),'');
  result jsonb;
begin
  if char_length(q)>100 then raise exception 'search_query_too_long' using errcode='22023'; end if;
  if p_min_price_minor is not null and p_min_price_minor<0 then raise exception 'invalid_min_price' using errcode='22023'; end if;
  if p_max_price_minor is not null and p_max_price_minor<0 then raise exception 'invalid_max_price' using errcode='22023'; end if;
  if p_min_price_minor is not null and p_max_price_minor is not null and p_max_price_minor<p_min_price_minor then raise exception 'invalid_price_range' using errcode='22023'; end if;

  with base as (
    select product.id,
           category.slug category_slug,category.name category_name,
           producer.id producer_id,producer.display_name producer_name,
           nullif(btrim(producer.production_province),'') production_province,
           nullif(btrim(producer.production_district),'') production_district,
           nullif(btrim(producer.production_village),'') production_village,
           variant.price_minor,
           product.stock_mode,
           case when product.stock_mode in ('tracked','seasonal')
                then greatest(0,coalesce(inventory.available_quantity,0)-coalesce(inventory.reserved_quantity,0))>0
                else true end is_in_stock
    from public.products product
    join public.producers producer on producer.id=product.producer_id and producer.status='active' and producer.is_verified=true and producer.deleted_at is null
    join public.categories category on category.id=product.category_id and category.is_active=true
    join lateral(
      select v.* from public.product_variants v
      where v.product_id=product.id and v.is_active=true
      order by v.is_default desc,v.created_at asc limit 1
    ) variant on true
    left join public.product_inventory inventory on inventory.variant_id=variant.id
    where product.status='published' and product.is_active=true and product.deleted_at is null
      and (requested_category_slug is null or category.slug=requested_category_slug)
      and (p_producer_id is null or producer.id=p_producer_id)
      and (province_value is null or lower(coalesce(producer.production_province,''))=province_value)
      and (district_value is null or lower(coalesce(producer.production_district,''))=district_value)
      and (village_value is null or lower(coalesce(producer.production_village,''))=village_value)
      and (p_min_price_minor is null or variant.price_minor>=p_min_price_minor)
      and (p_max_price_minor is null or variant.price_minor<=p_max_price_minor)
      and (not coalesce(p_in_stock,false) or product.stock_mode not in ('tracked','seasonal') or greatest(0,coalesce(inventory.available_quantity,0)-coalesce(inventory.reserved_quantity,0))>0)
      and (p_featured is null or product.is_featured=p_featured)
      and (
        q='' or product.search_text ilike '%'||q||'%' or lower(product.name) ilike '%'||q||'%'
        or lower(producer.display_name) ilike '%'||q||'%' or lower(coalesce(producer.production_village,'')) ilike '%'||q||'%'
        or lower(category.name) ilike '%'||q||'%'
        or extensions.similarity(product.search_text,q)>=0.12 or extensions.similarity(lower(product.name),q)>=0.18
      )
  )
  select jsonb_build_object(
    'total',(select count(*) from base),
    'categories',coalesce((select jsonb_agg(jsonb_build_object('slug',x.slug,'name',x.name,'count',x.count) order by x.count desc,x.name) from (select category_slug slug,min(category_name) name,count(*)::integer count from base group by category_slug) x),'[]'::jsonb),
    'producers',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'name',x.name,'count',x.count) order by x.count desc,x.name) from (select producer_id id,min(producer_name) name,count(*)::integer count from base group by producer_id) x),'[]'::jsonb),
    'provinces',coalesce((select jsonb_agg(jsonb_build_object('value',x.value,'count',x.count) order by x.count desc,x.value) from (select production_province value,count(*)::integer count from base where production_province is not null group by production_province) x),'[]'::jsonb),
    'districts',coalesce((select jsonb_agg(jsonb_build_object('value',x.value,'count',x.count) order by x.count desc,x.value) from (select production_district value,count(*)::integer count from base where production_district is not null group by production_district) x),'[]'::jsonb),
    'villages',coalesce((select jsonb_agg(jsonb_build_object('value',x.value,'count',x.count) order by x.count desc,x.value) from (select production_village value,count(*)::integer count from base where production_village is not null group by production_village) x),'[]'::jsonb),
    'price',jsonb_build_object('minMinor',(select min(price_minor) from base),'maxMinor',(select max(price_minor) from base)),
    'inStockCount',(select count(*) from base where is_in_stock)
  ) into result;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.catalog_search_suggestions_v1(p_query text, p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare q text:=lower(btrim(coalesce(p_query,''))); result jsonb;
begin
  if char_length(q) not between 1 and 100 then return '[]'::jsonb; end if;
  if p_limit not between 1 and 20 then raise exception 'invalid_suggestion_limit' using errcode='22023'; end if;
  with suggestions as (
    select 'product'::text kind,product.id::text id,product.name label,product.slug value,
           greatest(extensions.similarity(lower(product.name),q),case when lower(product.name) like q||'%' then 1 else 0 end)::numeric score
    from public.products product join public.producers producer on producer.id=product.producer_id
    where product.status='published' and product.is_active=true and product.deleted_at is null and producer.status='active' and producer.is_verified=true and producer.deleted_at is null
      and (lower(product.name) ilike '%'||q||'%' or extensions.similarity(lower(product.name),q)>=0.18)
    union all
    select 'producer',producer.id::text,producer.display_name,producer.slug,
           greatest(extensions.similarity(lower(producer.display_name),q),case when lower(producer.display_name) like q||'%' then 1 else 0 end)::numeric
    from public.producers producer
    where producer.status='active' and producer.is_verified=true and producer.deleted_at is null
      and (lower(producer.display_name) ilike '%'||q||'%' or lower(coalesce(producer.production_village,'')) ilike '%'||q||'%' or extensions.similarity(lower(producer.display_name),q)>=0.18)
    union all
    select 'category',category.id::text,category.name,category.slug,
           greatest(extensions.similarity(lower(category.name),q),case when lower(category.name) like q||'%' then 1 else 0 end)::numeric
    from public.categories category where category.is_active=true and (lower(category.name) ilike '%'||q||'%' or extensions.similarity(lower(category.name),q)>=0.18)
  )
  select coalesce(jsonb_agg(jsonb_build_object('kind',kind,'id',id,'label',label,'value',value) order by score desc,label),'[]'::jsonb)
  into result from (select * from suggestions order by score desc,label limit p_limit) ranked;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.check_product_export_eligibility_v1(p_product_id uuid, p_country_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  country_code text:=upper(btrim(coalesce(p_country_code,'')));
  product_row public.products%rowtype;
  zone_row public.shipping_zones%rowtype;
  rule jsonb;
  missing_weight_count integer;
begin
  if country_code !~ '^[A-Z]{2}$' then raise exception 'invalid_country_code' using errcode='22023'; end if;
  select product.* into product_row
  from public.products product
  join public.producers producer on producer.id=product.producer_id
  where product.id=p_product_id and product.status='published' and product.is_active=true and product.deleted_at is null
    and producer.status='active' and producer.is_verified=true and producer.deleted_at is null;
  if product_row.id is null then return jsonb_build_object('available',false,'reason','product_not_available'); end if;
  if country_code='TR' then return jsonb_build_object('available',true,'countryCode',country_code,'mode','domestic'); end if;
  zone_row:=private.resolve_shipping_zone_v1(country_code);
  if zone_row.id is null then return jsonb_build_object('available',false,'reason','shipping_zone_unavailable'); end if;
  if zone_row.requires_manual_quote then return jsonb_build_object('available',false,'reason','manual_shipping_quote_required','manualQuoteRequired',true,'publicNote',zone_row.public_note); end if;
  if product_row.export_status<>'eligible' then return jsonb_build_object('available',false,'reason','product_export_not_enabled','manualReviewRequired',true); end if;
  if product_row.country_of_origin_code is null or product_row.customs_hs_code is null or nullif(btrim(coalesce(product_row.customs_description,'')),'') is null then
    return jsonb_build_object('available',false,'reason','product_customs_profile_incomplete');
  end if;
  select count(*)::integer into missing_weight_count from public.product_variants variant where variant.product_id=product_row.id and variant.is_active=true and (variant.weight_grams is null or variant.weight_grams<=0);
  if missing_weight_count>0 then return jsonb_build_object('available',false,'reason','product_weight_incomplete'); end if;
  if product_row.requires_cold_chain and not zone_row.supports_cold_chain then return jsonb_build_object('available',false,'reason','cold_chain_unavailable'); end if;
  rule:=private.resolve_product_export_rule_v1(product_row.id,country_code);
  if coalesce(rule->>'decision','manual_review')<>'allowed' then
    return jsonb_build_object('available',false,'reason','country_product_rule_'||coalesce(rule->>'decision','manual_review'),'manualReviewRequired',(coalesce(rule->>'decision','manual_review') in ('manual_review','restricted')),'publicNote',rule->>'publicNote');
  end if;
  return jsonb_build_object('available',true,'countryCode',country_code,'zoneCode',zone_row.code,'publicNote',rule->>'publicNote');
end;
$function$;

CREATE OR REPLACE FUNCTION private.ci_orphan_catalog_media_cleanup_candidates_for_service_v1()
 RETURNS text[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(array_agg(o.name order by o.name),'{}'::text[])
  from storage.objects o
  where o.bucket_id='catalog-public'
    and coalesce(o.is_delete_marker,false)=false
    and o.archived_at is null
    and o.name ~ '^admin/[0-9a-f-]{36}/official-products/[0-9a-f-]{36}\\.(png|jpe?g|webp|avif)$'
    and o.owner_id is not null
    and not exists(select 1 from auth.users u where u.id::text=o.owner_id)
    and not exists(select 1 from public.product_images pi where private.verified_public_storage_path_v1('catalog-public',pi.storage_path)=o.name);
$function$;

CREATE OR REPLACE FUNCTION private.claim_push_deliveries_v1(p_limit integer, p_worker_id text)
 RETURNS TABLE(delivery_id bigint, provider text, platform text, environment text, push_token text, title text, body text, action_url text, metadata jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_limit not between 1 and 500 or char_length(btrim(coalesce(p_worker_id,''))) not between 2 and 120 then raise exception 'invalid_push_worker_request' using errcode='22023'; end if;
  return query
  with claimed as (
    select delivery.id from private.push_deliveries delivery
    join private.device_push_tokens token on token.id=delivery.device_token_id and token.disabled_at is null
    where delivery.status='pending' and delivery.available_at<=timezone('utc',now()) and delivery.attempts<5
    order by delivery.id for update of delivery skip locked limit p_limit
  ), updated as (
    update private.push_deliveries delivery
    set status='processing',attempts=attempts+1,locked_at=timezone('utc',now()),locked_by=btrim(p_worker_id),updated_at=timezone('utc',now())
    from claimed where delivery.id=claimed.id returning delivery.*
  )
  select updated.id,token.provider,token.platform,token.environment,
         extensions.pgp_sym_decrypt(token.token_ciphertext,private.get_push_token_key_v1())::text,
         notification.title,notification.message,notification.action_url,notification.metadata
  from updated
  join private.device_push_tokens token on token.id=updated.device_token_id
  join public.notifications notification on notification.id=updated.notification_id;
end;
$function$;

CREATE OR REPLACE FUNCTION private.claim_push_deliveries_v2(p_limit integer, p_worker_id text, p_providers text[])
 RETURNS TABLE(delivery_id bigint, provider text, platform text, environment text, push_token text, title text, body text, action_url text, metadata jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  normalized_providers text[];
begin
  if p_limit not between 1 and 500
     or char_length(btrim(coalesce(p_worker_id,''))) not between 2 and 120 then
    raise exception 'invalid_push_worker_request' using errcode='22023';
  end if;

  select coalesce(array_agg(distinct lower(btrim(value))), array[]::text[])
    into normalized_providers
  from unnest(coalesce(p_providers, array[]::text[])) value
  where lower(btrim(value)) in ('fcm','apns');

  if coalesce(cardinality(normalized_providers),0)=0 then
    raise exception 'push_provider_required' using errcode='22023';
  end if;

  return query
  with claimed as (
    select delivery.id
    from private.push_deliveries delivery
    join private.device_push_tokens token
      on token.id=delivery.device_token_id
     and token.disabled_at is null
     and lower(token.provider)=any(normalized_providers)
    where delivery.status='pending'
      and delivery.available_at<=timezone('utc',now())
      and delivery.attempts<5
    order by delivery.id
    for update of delivery skip locked
    limit p_limit
  ), updated as (
    update private.push_deliveries delivery
       set status='processing',
           attempts=attempts+1,
           locked_at=timezone('utc',now()),
           locked_by=btrim(p_worker_id),
           updated_at=timezone('utc',now())
      from claimed
     where delivery.id=claimed.id
    returning delivery.*
  )
  select updated.id,
         token.provider,
         token.platform,
         token.environment,
         extensions.pgp_sym_decrypt(token.token_ciphertext,private.get_push_token_key_v1())::text,
         notification.title,
         notification.message,
         notification.action_url,
         notification.metadata
    from updated
    join private.device_push_tokens token on token.id=updated.device_token_id
    join public.notifications notification on notification.id=updated.notification_id;
end;
$function$;

CREATE OR REPLACE FUNCTION private.claim_push_deliveries_v3(p_limit integer, p_worker_id text, p_providers text[])
 RETURNS TABLE(delivery_id bigint, provider text, platform text, environment text, push_token text, title text, body text, action_url text, metadata jsonb, unread_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  normalized_providers text[];
begin
  if p_limit not between 1 and 500
     or char_length(btrim(coalesce(p_worker_id,''))) not between 2 and 120 then
    raise exception 'invalid_push_worker_request' using errcode='22023';
  end if;

  select coalesce(array_agg(distinct lower(btrim(value))), array[]::text[])
    into normalized_providers
  from unnest(coalesce(p_providers, array[]::text[])) value
  where lower(btrim(value)) in ('fcm','apns');

  if coalesce(cardinality(normalized_providers),0)=0 then
    raise exception 'push_provider_required' using errcode='22023';
  end if;

  return query
  with claimed as (
    select delivery.id
    from private.push_deliveries delivery
    join private.device_push_tokens token
      on token.id=delivery.device_token_id
     and token.disabled_at is null
     and lower(token.provider)=any(normalized_providers)
    where delivery.status='pending'
      and delivery.available_at<=timezone('utc',now())
      and delivery.attempts<5
    order by delivery.id
    for update of delivery skip locked
    limit p_limit
  ), updated as (
    update private.push_deliveries delivery
       set status='processing',
           attempts=attempts+1,
           locked_at=timezone('utc',now()),
           locked_by=btrim(p_worker_id),
           updated_at=timezone('utc',now())
      from claimed
     where delivery.id=claimed.id
    returning delivery.*
  )
  select updated.id,
         token.provider,
         token.platform,
         token.environment,
         extensions.pgp_sym_decrypt(token.token_ciphertext,private.get_push_token_key_v1())::text,
         notification.title,
         notification.message,
         notification.action_url,
         notification.metadata,
         least(2147483647, coalesce(unread.total,0))::integer
    from updated
    join private.device_push_tokens token on token.id=updated.device_token_id
    join public.notifications notification on notification.id=updated.notification_id
    left join lateral (
      select count(*)::bigint as total
      from public.notifications pending_notification
      where pending_notification.user_id=updated.user_id
        and pending_notification.read_at is null
        and (pending_notification.expires_at is null or pending_notification.expires_at>timezone('utc',now()))
    ) unread on true;
end;
$function$;

CREATE OR REPLACE FUNCTION private.cleanup_stale_ci_e2e_users_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target record;
  candidate_count integer:=0;
  deleted_count integer:=0;
  skipped_count integer:=0;
  deleted_one integer:=0;
begin
  for target in
    select u.id
    from auth.users u
    where u.created_at < timezone('utc',now()) - interval '30 minutes'
      and coalesce(u.raw_user_meta_data->>'source','')='github-actions-e2e'
      and coalesce(u.raw_user_meta_data->>'e2e_run_id','') ~ '^[0-9]{1,24}$'
      and lower(coalesce(u.email,'')) ~ '^goldenoremar\+ci-e2e-[0-9]{1,24}(-[a-z0-9-]{1,24})?@gmail\.com$'
      and lower(coalesce(u.email,'')) = lower(
        'goldenoremar+ci-e2e-'||(u.raw_user_meta_data->>'e2e_run_id')||
        case
          when coalesce(u.raw_user_meta_data->>'e2e_slot','')<>'' then '-'||(u.raw_user_meta_data->>'e2e_slot')
          else ''
        end||'@gmail.com'
      )
    order by u.created_at
    limit 100
  loop
    candidate_count:=candidate_count+1;
    begin
      delete from private.user_roles
       where user_id=target.id
         and role in('support','content_editor','operations','moderator','admin','super_admin');

      delete from auth.users where id=target.id;
      get diagnostics deleted_one = row_count;
      deleted_count:=deleted_count+deleted_one;
    exception when foreign_key_violation then
      skipped_count:=skipped_count+1;
    end;
  end loop;

  if candidate_count>0 then
    insert into private.admin_audit_logs(
      actor_user_id,action,target_type,target_id,details,correlation_id,before_state,after_state
    ) values (
      null,'ci.e2e_stale_user_gc','automation',null,
      jsonb_build_object(
        'candidateCount',candidate_count,
        'deletedCount',deleted_count,
        'skippedForeignKeyCount',skipped_count,
        'minimumAgeMinutes',30,
        'batchLimit',100
      ),
      gen_random_uuid(),null,
      jsonb_build_object(
        'candidateCount',candidate_count,
        'deletedCount',deleted_count,
        'skippedForeignKeyCount',skipped_count
      )
    );
  end if;

  return jsonb_build_object(
    'ok',true,
    'candidateCount',candidate_count,
    'deletedCount',deleted_count,
    'skippedForeignKeyCount',skipped_count
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.clear_my_cart_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); cart_row public.carts%rowtype;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  cart_row:=private.get_or_create_customer_cart_v1(caller_id);
  delete from public.cart_items where cart_id=cart_row.id;
  update public.carts set expires_at=timezone('utc',now())+interval '30 days',updated_at=timezone('utc',now()) where id=cart_row.id;
  return private.get_customer_cart_snapshot_v1(caller_id);
end;
$function$;

CREATE OR REPLACE FUNCTION private.commercial_checkout_legal_readiness_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  settings public.brand_settings%rowtype;
  identity jsonb;
  missing jsonb:='[]'::jsonb;
  registered_name text;
  registered_address text;
  country_code text;
  verification_status text;
  finalized boolean:=false;
  legal_count integer:=0;
begin
  select * into settings from public.brand_settings where slug='golden-oremar';
  if settings.slug is null then return jsonb_build_object('ready',false,'missing',jsonb_build_array('brand_settings')); end if;
  identity:=coalesce(settings.public_config->'businessIdentity','{}'::jsonb);
  registered_name:=nullif(btrim(coalesce(identity->>'registeredLegalName','')),'');
  registered_address:=nullif(btrim(coalesce(identity->>'registeredAddress','')),'');
  country_code:=upper(btrim(coalesce(identity->>'countryCode','')));
  verification_status:=lower(btrim(coalesce(identity->>'verificationStatus','provisional')));
  finalized:=coalesce((identity->>'legalDocumentsFinalized')::boolean,false);
  if registered_name is null then missing:=missing||jsonb_build_array('registered_legal_name'); end if;
  if registered_address is null or char_length(registered_address)<10 then missing:=missing||jsonb_build_array('registered_address'); end if;
  if country_code !~ '^[A-Z]{2}$' then missing:=missing||jsonb_build_array('registered_country_code'); end if;
  if verification_status<>'verified' then missing:=missing||jsonb_build_array('registered_identity_verification'); end if;
  if settings.support_email is null or btrim(settings.support_email)='' then missing:=missing||jsonb_build_array('support_email'); end if;
  if settings.support_phone is null or btrim(settings.support_phone)='' then missing:=missing||jsonb_build_array('support_phone'); end if;
  select count(*) into legal_count from public.content_entries ce where ce.content_type='legal' and ce.slug in('about','returns','privacy','terms') and ce.locale='tr' and ce.status='published' and ce.deleted_at is null and char_length(btrim(coalesce(ce.body_markdown,'')))>=100;
  if legal_count<>4 then missing:=missing||jsonb_build_array('published_legal_documents'); end if;
  if not finalized then missing:=missing||jsonb_build_array('legal_documents_finalized'); end if;
  return jsonb_build_object(
    'ready',jsonb_array_length(missing)=0,
    'missing',missing,
    'registeredLegalName',registered_name,
    'registeredAddress',registered_address,
    'countryCode',case when country_code~'^[A-Z]{2}$' then country_code else null end,
    'identityVerificationStatus',case when verification_status='verified' then 'verified' else 'provisional' end,
    'registeredIdentityVerified',verification_status='verified',
    'legalDocumentsFinalized',finalized,
    'publishedLegalDocumentCount',legal_count
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.complete_commerce_payment_for_service_v3(p_intent_id uuid, p_provider_reference text, p_payment_method_type text, p_status text, p_provider_payload jsonb DEFAULT '{}'::jsonb, p_failure_code text DEFAULT NULL::text, p_failure_message text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare intent private.payment_intents%rowtype;
begin select * into intent from private.payment_intents where id=p_intent_id; if intent.id is null then raise exception 'payment_intent_not_found' using errcode='P0002'; end if; if intent.subject_type='order' then return private.complete_order_payment_for_service_v2(p_intent_id,p_provider_reference,p_payment_method_type,p_status,p_provider_payload,p_failure_code,p_failure_message); elsif intent.subject_type='event_reservation' then if lower(btrim(coalesce(p_status,''))) in ('failed','cancelled') then return private.fail_event_reservation_payment_for_service_v1(p_intent_id,coalesce(p_failure_code,'provider_rejected'),p_failure_message,p_provider_payload); end if; return private.complete_event_reservation_payment_for_service_v1(p_intent_id,p_provider_reference,p_payment_method_type,p_status,p_provider_payload); end if; raise exception 'unsupported_payment_subject_type' using errcode='55000'; end;$function$;

CREATE OR REPLACE FUNCTION private.complete_event_reservation_payment_for_service_v1(p_intent_id uuid, p_provider_reference text, p_payment_method_type text, p_status text, p_provider_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  intent private.payment_intents%rowtype;
  r public.event_reservations%rowtype;
  f private.event_reservation_finance%rowtype;
  e public.events%rowtype;
  payment public.payment_records%rowtype;
  method text:=lower(btrim(coalesce(p_payment_method_type,'')));
  st text:=lower(btrim(coalesce(p_status,'')));
  ref text:=btrim(coalesce(p_provider_reference,''));
  payload jsonb:=coalesce(p_provider_payload,'{}'::jsonb);
  other_guests bigint:=0;
  can_honor boolean:=true;
  event_key text;
  validated_item_count integer:=0;
begin
  if method not in ('card','bank_transfer','wallet','other') or st not in ('authorized','captured') then raise exception 'invalid_payment_completion' using errcode='22023'; end if;
  if char_length(ref) not between 4 and 220 or jsonb_typeof(payload)<>'object' then raise exception 'invalid_provider_payment' using errcode='22023'; end if;

  select * into intent from private.payment_intents where id=p_intent_id for update;
  if intent.id is null or intent.subject_type<>'event_reservation' then raise exception 'payment_intent_not_found' using errcode='P0002'; end if;
  if intent.status='captured' then return jsonb_build_object('ok',true,'intentId',intent.id,'status','captured','subjectType','event_reservation','reservationId',intent.subject_id,'unchanged',true); end if;
  if intent.status not in ('processing','authorized') then raise exception 'invalid_intent_transition' using errcode='22023'; end if;

  select * into r from public.event_reservations where id=intent.subject_id for update;
  select * into f from private.event_reservation_finance where reservation_id=intent.subject_id for update;
  select * into e from public.events where id=r.event_id for update;
  if r.id is null or f.reservation_id is null or e.id is null or f.user_id<>intent.user_id or f.total_minor<>intent.amount_minor or f.currency<>intent.currency then raise exception 'event_payment_context_mismatch' using errcode='55000'; end if;

  validated_item_count:=private.validate_event_provider_item_transaction_v1(r.id,payload);
  if validated_item_count<>1 then raise exception 'provider_event_item_transaction_required' using errcode='55000'; end if;

  select * into payment from public.payment_records where provider=intent.provider and provider_reference=ref for update;
  if payment.id is null then
    insert into public.payment_records(subject_type,subject_id,order_id,user_id,provider,provider_reference,payment_method_type,amount_minor,currency,status,authorized_at,captured_at)
    values('event_reservation',r.id,null,intent.user_id,intent.provider,ref,method,intent.amount_minor,intent.currency,st,case when st in ('authorized','captured') then timezone('utc',now()) else null end,case when st='captured' then timezone('utc',now()) else null end)
    returning * into payment;
  elsif payment.subject_type<>'event_reservation' or payment.subject_id<>r.id or payment.amount_minor<>intent.amount_minor or payment.currency<>intent.currency then
    raise exception 'payment_provider_reference_conflict' using errcode='23505';
  else
    update public.payment_records
    set status=st,payment_method_type=method,authorized_at=coalesce(authorized_at,timezone('utc',now())),captured_at=case when st='captured' then coalesce(captured_at,timezone('utc',now())) else captured_at end,updated_at=timezone('utc',now())
    where id=payment.id returning * into payment;
  end if;

  insert into private.payment_events(provider,provider_event_id,payment_id,event_type,payload,signature_verified,processing_status,processed_at)
  values(intent.provider,ref||':'||st||':event-reservation',payment.id,'payment.'||st,payload,true,'processed',timezone('utc',now()))
  on conflict(provider,provider_event_id) do nothing;

  if st='authorized' then
    update private.event_reservation_finance set payment_status='authorized',provider=intent.provider,provider_reference=ref,updated_at=timezone('utc',now()) where reservation_id=r.id;
    update private.payment_intents set status='authorized',provider_reference=ref,provider_result=provider_result||payload,updated_at=timezone('utc',now()) where id=intent.id;
    return jsonb_build_object('ok',true,'intentId',intent.id,'status','authorized','subjectType','event_reservation','reservationId',r.id,'refundRequired',false);
  end if;

  if f.payment_expires_at is not null and f.payment_expires_at<=timezone('utc',now()) then
    select coalesce(sum(orx.guest_count),0) into other_guests
    from public.event_reservations orx
    left join private.event_reservation_finance ofx on ofx.reservation_id=orx.id
    where orx.event_id=e.id and orx.id<>r.id
      and (orx.status in ('pending','confirmed','attended') or (orx.status='pending_payment' and (ofx.payment_status='authorized' or (ofx.payment_status='pending' and ofx.payment_expires_at>timezone('utc',now())))));
    if e.capacity is not null and other_guests+r.guest_count>e.capacity then can_honor:=false; end if;
  end if;

  update private.payment_intents set status='captured',provider_reference=ref,provider_result=provider_result||payload,completed_at=timezone('utc',now()),updated_at=timezone('utc',now()) where id=intent.id;

  if not can_honor then
    update private.event_reservation_finance set payment_status='refund_required',provider=intent.provider,provider_reference=ref,paid_at=timezone('utc',now()),updated_at=timezone('utc',now()) where reservation_id=r.id;
    update public.event_reservations set status='cancelled',updated_at=timezone('utc',now()) where id=r.id;
    insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
    values('event_reservation',r.id,'event.payment_refund_required',jsonb_build_object('reservation_id',r.id,'event_id',e.id,'payment_id',payment.id,'provider_reference',ref,'amount_minor',f.total_minor,'currency',f.currency));
    return jsonb_build_object('ok',true,'intentId',intent.id,'status','captured','subjectType','event_reservation','reservationId',r.id,'refundRequired',true);
  end if;

  update private.event_reservation_finance set payment_status='paid',provider=intent.provider,provider_reference=ref,paid_at=timezone('utc',now()),updated_at=timezone('utc',now()) where reservation_id=r.id;
  update public.event_reservations set status='confirmed',updated_at=timezone('utc',now()) where id=r.id;

  if f.producer_id is not null then
    event_key:='event_reservation:'||r.id::text||':sale';
    insert into private.producer_ledger_entries(producer_id,event_reservation_id,entry_type,currency,merchandise_minor,tax_minor,producer_gross_minor,platform_fee_minor,producer_net_minor,commission_basis_points,availability_status,available_at,source_key,metadata)
    values(f.producer_id,r.id,'sale',f.currency,f.total_minor,0,f.total_minor,f.platform_fee_minor,f.producer_net_minor,f.commission_basis_points_snapshot,'pending',e.ends_at,event_key,jsonb_build_object('event_id',e.id,'event_title',e.title,'reservation_code',r.reservation_code,'payment_id',payment.id))
    on conflict(source_key) do nothing;

    insert into private.payment_item_splits(payment_id,order_id,order_item_id,event_reservation_id,producer_id,provider_payment_transaction_id,item_price_minor,provider_paid_price_minor,submerchant_price_minor,transaction_status,approval_status,provider_snapshot)
    select payment.id,null,null,r.id,f.producer_id,nullif(x->>'paymentTransactionId',''),f.total_minor,
      case when (x->>'paidPrice')~'^[0-9]+([.][0-9]+)?$' then round((x->>'paidPrice')::numeric*100)::bigint else null end,
      f.producer_net_minor,
      case when (x->>'transactionStatus')~'^-?[0-9]+$' then (x->>'transactionStatus')::integer else null end,
      'pending',x
    from jsonb_array_elements(payload->'itemTransactions') x
    limit 1
    on conflict(payment_id,event_reservation_id) where event_reservation_id is not null
    do update set
      provider_payment_transaction_id=excluded.provider_payment_transaction_id,
      provider_paid_price_minor=excluded.provider_paid_price_minor,
      transaction_status=excluded.transaction_status,
      provider_snapshot=excluded.provider_snapshot,
      updated_at=timezone('utc',now());
  end if;

  if e.capacity is not null and (
    select coalesce(sum(rr.guest_count),0)
    from public.event_reservations rr
    left join private.event_reservation_finance ff on ff.reservation_id=rr.id
    where rr.event_id=e.id
      and (rr.status in ('pending','confirmed','attended') or (rr.status='pending_payment' and (ff.payment_status='authorized' or (ff.payment_status='pending' and ff.payment_expires_at>timezone('utc',now())))))
  )>=e.capacity then
    update public.events set status='sold_out',updated_at=timezone('utc',now()) where id=e.id and status='published';
  end if;

  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
  values('event_reservation',r.id,'event.payment_captured',jsonb_build_object('reservation_id',r.id,'event_id',e.id,'payment_id',payment.id,'user_id',r.user_id));

  return jsonb_build_object('ok',true,'intentId',intent.id,'status','captured','subjectType','event_reservation','reservationId',r.id,'paymentId',payment.id,'refundRequired',false);
end;
$function$;

CREATE OR REPLACE FUNCTION private.complete_order_payment_for_service_v1(p_intent_id uuid, p_provider_reference text, p_status text, p_provider_payload jsonb DEFAULT '{}'::jsonb, p_failure_code text DEFAULT NULL::text, p_failure_message text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  intent private.payment_intents%rowtype;
  normalized_status text:=lower(btrim(coalesce(p_status,'')));
  normalized_reference text:=btrim(coalesce(p_provider_reference,''));
  safe_payload jsonb:=coalesce(p_provider_payload,'{}'::jsonb);
  applied jsonb;
  split_count integer:=0;
  payment_id_value uuid;
begin
  if p_intent_id is null then raise exception 'payment_intent_required' using errcode='22023'; end if;
  if normalized_status not in ('authorized','captured','failed','cancelled') then raise exception 'invalid_payment_status' using errcode='22023'; end if;
  if char_length(normalized_reference) not between 4 and 220 then raise exception 'invalid_payment_reference' using errcode='22023'; end if;
  if jsonb_typeof(safe_payload)<>'object' then raise exception 'invalid_provider_payload' using errcode='22023'; end if;
  if p_failure_code is not null and char_length(p_failure_code)>120 then raise exception 'invalid_failure_code' using errcode='22023'; end if;
  if p_failure_message is not null and char_length(p_failure_message)>500 then raise exception 'invalid_failure_message' using errcode='22023'; end if;

  select i.* into intent from private.payment_intents i where i.id=p_intent_id for update;
  if intent.id is null then raise exception 'payment_intent_not_found' using errcode='P0002'; end if;
  if intent.status='captured' then return jsonb_build_object('ok',true,'intentId',intent.id,'status','captured','unchanged',true,'orderId',intent.order_id); end if;
  if intent.status in ('failed','cancelled') and normalized_status=intent.status then return jsonb_build_object('ok',true,'intentId',intent.id,'status',intent.status,'unchanged',true,'orderId',intent.order_id); end if;
  if intent.status='authorized' and normalized_status not in ('captured','failed','cancelled','authorized') then raise exception 'invalid_intent_transition' using errcode='22023'; end if;
  if intent.status not in ('processing','authorized') then raise exception 'invalid_intent_transition' using errcode='22023'; end if;

  applied:=private.apply_verified_payment_v1(intent.order_id,intent.provider,normalized_reference,'card',intent.amount_minor,intent.currency,normalized_status,null);
  payment_id_value:=nullif(applied->>'paymentId','')::uuid;
  if normalized_status in ('authorized','captured') and payment_id_value is not null then
    split_count:=private.persist_payment_item_splits_for_service_v1(payment_id_value,safe_payload);
  end if;

  update private.payment_intents
  set status=normalized_status,
      provider_reference=normalized_reference,
      failure_code=case when normalized_status='failed' then nullif(btrim(coalesce(p_failure_code,'')),'') else null end,
      failure_message=case when normalized_status='failed' then nullif(btrim(coalesce(p_failure_message,'')),'') else null end,
      provider_result=safe_payload,
      completed_at=case when normalized_status in ('captured','failed','cancelled') then timezone('utc',now()) else null end,
      updated_at=timezone('utc',now())
  where id=intent.id;

  return jsonb_build_object('ok',true,'intentId',intent.id,'status',normalized_status,'orderId',intent.order_id,'payment',applied,'splitCount',split_count);
end;
$function$;

CREATE OR REPLACE FUNCTION private.complete_order_payment_for_service_v2(p_intent_id uuid, p_provider_reference text, p_payment_method_type text, p_status text, p_provider_payload jsonb DEFAULT '{}'::jsonb, p_failure_code text DEFAULT NULL::text, p_failure_message text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  intent private.payment_intents%rowtype;
  normalized_method text:=lower(btrim(coalesce(p_payment_method_type,'')));
  normalized_status text:=lower(btrim(coalesce(p_status,'')));
  normalized_reference text:=btrim(coalesce(p_provider_reference,''));
  safe_payload jsonb:=coalesce(p_provider_payload,'{}'::jsonb);
  applied jsonb;
  expected_split_count integer:=0;
  persisted_split_count integer:=0;
  payment_id_value uuid;
begin
  if p_intent_id is null then raise exception 'payment_intent_required' using errcode='22023'; end if;
  if normalized_method not in ('card','bank_transfer','wallet','other') then raise exception 'invalid_payment_method' using errcode='22023'; end if;
  if normalized_status not in ('authorized','captured','failed','cancelled') then raise exception 'invalid_payment_status' using errcode='22023'; end if;
  if char_length(normalized_reference) not between 4 and 220 then raise exception 'invalid_payment_reference' using errcode='22023'; end if;
  if jsonb_typeof(safe_payload)<>'object' then raise exception 'invalid_provider_payload' using errcode='22023'; end if;

  select * into intent from private.payment_intents where id=p_intent_id for update;
  if intent.id is null or intent.subject_type<>'order' or intent.order_id is null then raise exception 'payment_intent_not_found' using errcode='P0002'; end if;
  if intent.status='captured' then return jsonb_build_object('ok',true,'intentId',intent.id,'status','captured','unchanged',true,'orderId',intent.order_id); end if;
  if intent.status in ('failed','cancelled') and normalized_status=intent.status then return jsonb_build_object('ok',true,'intentId',intent.id,'status',intent.status,'unchanged',true,'orderId',intent.order_id); end if;
  if intent.status not in ('processing','authorized') then raise exception 'invalid_intent_transition' using errcode='22023'; end if;

  if normalized_status in ('authorized','captured') then
    expected_split_count:=private.validate_order_provider_item_transactions_v1(intent.order_id,safe_payload);
  end if;

  applied:=private.apply_verified_payment_v1(intent.order_id,intent.provider,normalized_reference,normalized_method,intent.amount_minor,intent.currency,normalized_status,null);
  payment_id_value:=nullif(applied->>'paymentId','')::uuid;

  if normalized_status in ('authorized','captured') then
    if payment_id_value is null then raise exception 'payment_record_required' using errcode='55000'; end if;
    persisted_split_count:=private.persist_payment_item_splits_for_service_v1(payment_id_value,safe_payload);
    if persisted_split_count<>expected_split_count then
      raise exception 'provider_item_split_persistence_mismatch' using errcode='55000';
    end if;
  end if;

  update private.payment_intents
  set status=normalized_status,
      provider_reference=normalized_reference,
      failure_code=case when normalized_status='failed' then nullif(btrim(coalesce(p_failure_code,'')),'') else null end,
      failure_message=case when normalized_status='failed' then nullif(btrim(coalesce(p_failure_message,'')),'') else null end,
      provider_result=provider_result||safe_payload,
      completed_at=case when normalized_status in ('captured','failed','cancelled') then timezone('utc',now()) else null end,
      updated_at=timezone('utc',now())
  where id=intent.id;

  return jsonb_build_object('ok',true,'intentId',intent.id,'status',normalized_status,'orderId',intent.order_id,'payment',applied,'splitCount',persisted_split_count);
end;
$function$;

CREATE OR REPLACE FUNCTION private.complete_order_settlement_item_for_service_v1(p_actor_user_id uuid, p_order_id uuid, p_payment_transaction_id text, p_provider_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare split_row private.payment_item_splits%rowtype; o public.orders%rowtype; remaining bigint:=0; safe_payload jsonb:=coalesce(p_provider_payload,'{}'::jsonb); producer_owner uuid; begin if p_actor_user_id is null or p_order_id is null or nullif(btrim(coalesce(p_payment_transaction_id,'')),'') is null then raise exception 'settlement_context_required' using errcode='22023'; end if; if not private.user_has_permission_v1(p_actor_user_id,'payout.release') then raise exception 'permission_required:payout.release' using errcode='42501'; end if; if jsonb_typeof(safe_payload)<>'object' then raise exception 'invalid_provider_payload' using errcode='22023'; end if; if safe_payload->>'status'<>'success' or coalesce(safe_payload->>'paymentTransactionId','')<>btrim(p_payment_transaction_id) then raise exception 'provider_approval_not_verified' using errcode='55000'; end if; select ps.* into split_row from private.payment_item_splits ps where ps.order_id=p_order_id and ps.provider_payment_transaction_id=btrim(p_payment_transaction_id) and ps.order_item_id is not null for update; if split_row.id is null then raise exception 'payment_split_not_found' using errcode='P0002'; end if; if split_row.approval_status='disapproved' then raise exception 'payment_split_disapproved' using errcode='55000'; end if; if split_row.approval_status<>'approved' then update private.payment_item_splits set approval_status='approved',approved_at=timezone('utc',now()),approved_by=p_actor_user_id,approval_provider_snapshot=safe_payload,approval_error=null,updated_at=timezone('utc',now()) where id=split_row.id; end if; select count(*) into remaining from private.payment_item_splits where order_id=p_order_id and order_item_id is not null and approval_status<>'approved'; if remaining=0 then perform private.release_completed_order_settlements_v1(p_order_id); select * into o from public.orders where id=p_order_id; update private.order_settlement_releases set status='released',released_by=p_actor_user_id,released_at=timezone('utc',now()),last_error=null,provider_snapshot=safe_payload,updated_at=timezone('utc',now()) where order_id=p_order_id; for producer_owner in select distinct p.owner_user_id from public.order_items oi join public.producers p on p.id=oi.producer_id where oi.order_id=p_order_id and p.owner_user_id is not null loop insert into public.notifications(user_id,type,title,message,action_url,metadata) values(producer_owner,'producer','Hakedişiniz serbest bırakıldı',coalesce(o.order_number,'Sipariş')||' siparişindeki hakedişiniz kullanılabilir bakiyeye geçti.','/account',jsonb_build_object('orderId',p_order_id,'settlementStatus','released')); end loop; insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload) values('order',p_order_id,'order.settlement_released',jsonb_build_object('order_id',p_order_id,'actor_user_id',p_actor_user_id)); end if; return jsonb_build_object('ok',true,'orderId',p_order_id,'paymentTransactionId',btrim(p_payment_transaction_id),'remaining',remaining,'released',remaining=0,'state',private.order_settlement_state_v1(p_order_id)); end;$function$;

CREATE OR REPLACE FUNCTION private.complete_producer_submerchant_for_service_v1(p_producer_id uuid, p_submerchant_key text, p_provider_snapshot jsonb DEFAULT '{}'::jsonb, p_error text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  account private.producer_payment_accounts%rowtype;
  normalized_key text:=nullif(btrim(coalesce(p_submerchant_key,'')),'');
  safe_snapshot jsonb:=coalesce(p_provider_snapshot,'{}'::jsonb);
begin
  if p_producer_id is null then raise exception 'producer_required' using errcode='22023'; end if;
  if jsonb_typeof(safe_snapshot)<>'object' then raise exception 'invalid_provider_snapshot' using errcode='22023'; end if;
  if p_error is not null and char_length(p_error)>500 then raise exception 'invalid_provider_error' using errcode='22023'; end if;
  select * into account from private.producer_payment_accounts where producer_id=p_producer_id for update;
  if account.producer_id is null then raise exception 'producer_payment_account_not_found' using errcode='P0002'; end if;
  if normalized_key is not null and char_length(normalized_key) not between 8 and 500 then raise exception 'invalid_submerchant_key' using errcode='22023'; end if;
  update private.producer_payment_accounts
  set submerchant_key=coalesce(normalized_key,submerchant_key),
      status=case when normalized_key is not null then 'ready' else 'error' end,
      last_error=case when normalized_key is not null then null else nullif(btrim(coalesce(p_error,'provider_onboarding_failed')),'') end,
      provider_snapshot=safe_snapshot,
      onboarded_at=case when normalized_key is not null then coalesce(onboarded_at,timezone('utc',now())) else onboarded_at end,
      updated_at=timezone('utc',now())
  where producer_id=p_producer_id
  returning * into account;
  return jsonb_build_object('ok',normalized_key is not null,'producerId',account.producer_id,'provider',account.provider,'status',account.status,'ready',account.status='ready');
end;
$function$;

CREATE OR REPLACE FUNCTION private.complete_push_delivery_v1(p_delivery_id bigint, p_success boolean, p_error text DEFAULT NULL::text, p_disable_token boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare delivery_row private.push_deliveries%rowtype;
begin
  select * into delivery_row from private.push_deliveries where id=p_delivery_id for update;
  if delivery_row.id is null then raise exception 'push_delivery_not_found' using errcode='P0002'; end if;
  if delivery_row.status not in ('processing','pending') then return true; end if;
  if coalesce(p_success,false) then
    update private.push_deliveries set status='sent',sent_at=timezone('utc',now()),locked_at=null,locked_by=null,last_error=null,updated_at=timezone('utc',now()) where id=delivery_row.id;
  else
    if coalesce(p_disable_token,false) then update private.device_push_tokens set disabled_at=timezone('utc',now()),updated_at=timezone('utc',now()) where id=delivery_row.device_token_id; end if;
    update private.push_deliveries set status=case when attempts>=5 or coalesce(p_disable_token,false) then 'failed' else 'pending' end,
      available_at=case when attempts>=5 or coalesce(p_disable_token,false) then available_at else timezone('utc',now())+(interval '1 minute'*least(60,power(2,greatest(0,attempts-1))::integer)) end,
      locked_at=null,locked_by=null,last_error=left(coalesce(p_error,'push_delivery_failed'),2000),updated_at=timezone('utc',now()) where id=delivery_row.id;
  end if;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION private.confirm_newsletter_v1(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare token_hash text:=private.hash_marketing_token_v1(p_token); sub private.newsletter_subscriptions%rowtype;
begin
  select * into sub from private.newsletter_subscriptions where confirmation_token_hash=token_hash and status='pending' for update;
  if sub.id is null then raise exception 'newsletter_confirmation_invalid_or_expired' using errcode='P0002'; end if;
  update private.newsletter_subscriptions set status='active',confirmed_at=timezone('utc',now()),confirmation_token_hash=null,updated_at=timezone('utc',now()) where id=sub.id returning * into sub;
  if sub.user_id is not null then
    update public.profiles set marketing_consent=true,marketing_consent_at=coalesce(marketing_consent_at,timezone('utc',now())),updated_at=timezone('utc',now()) where id=sub.user_id and status='active' and deleted_at is null;
  end if;
  return jsonb_build_object('id',sub.id,'status',sub.status,'confirmedAt',sub.confirmed_at);
end;
$function$;

CREATE OR REPLACE FUNCTION private.consume_order_inventory_v1(p_order_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  reservation record;
  movement_id bigint;
  current_inventory public.product_inventory%rowtype;
begin
  for reservation in
    select item.variant_id, sum(item.quantity)::integer as quantity
    from public.order_items item
    join public.products product on product.id = item.product_id
    where item.order_id = p_order_id
      and item.variant_id is not null
      and product.stock_mode in ('tracked','seasonal')
    group by item.variant_id
    order by item.variant_id
  loop
    select inventory.* into current_inventory from public.product_inventory inventory where inventory.variant_id = reservation.variant_id for update;
    if current_inventory.variant_id is null then raise exception 'inventory_missing_for_sale:%', reservation.variant_id using errcode = 'P0001'; end if;
    if current_inventory.available_quantity < reservation.quantity or current_inventory.reserved_quantity < reservation.quantity then
      raise exception 'inventory_reservation_inconsistent:%', reservation.variant_id using errcode = 'P0001';
    end if;
    movement_id := null;
    insert into private.inventory_movements(variant_id, movement_type, quantity_delta, reference_type, reference_id, reason, idempotency_key, actor_user_id)
    values (reservation.variant_id, 'sale', -reservation.quantity, 'order', p_order_id,
      'Confirmed order converted reserved stock to sale', 'order:' || p_order_id::text || ':sale:' || reservation.variant_id::text, p_actor_user_id)
    on conflict (idempotency_key) do nothing returning id into movement_id;
    if movement_id is not null then
      update public.product_inventory inventory
      set available_quantity = inventory.available_quantity - reservation.quantity,
          reserved_quantity = inventory.reserved_quantity - reservation.quantity,
          version = inventory.version + 1, updated_at = timezone('utc', now())
      where inventory.variant_id = reservation.variant_id;
    end if;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION private.consume_order_promotion_v1(p_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  update private.promotion_redemptions redemption
  set status='consumed',
      consumed_at=coalesce(consumed_at,timezone('utc',now())),
      expires_at=null,
      updated_at=timezone('utc',now())
  where redemption.order_id=p_order_id
    and redemption.status='reserved';
end;
$function$;

CREATE OR REPLACE FUNCTION private.create_customer_order_guarded_v1(p_items jsonb, p_shipping_address jsonb, p_customer_note text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  country_code text;
  item jsonb;
  product_reference text;
  target_product public.products%rowtype;
  target_variant public.product_variants%rowtype;
  quantity_value integer;
  active_variant_count integer;
  subtotal_value bigint := 0;
  weight_value integer := 0;
  quote jsonb;
  result jsonb;
  brand_shipping bigint := 0;
begin
  if auth.uid() is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if p_shipping_address is null or jsonb_typeof(p_shipping_address)<>'object' then raise exception 'invalid_shipping_address' using errcode='22023'; end if;

  country_code := upper(coalesce(nullif(btrim(coalesce(p_shipping_address->>'country_code',p_shipping_address->>'countryCode','')),''),'TR'));
  if country_code !~ '^[A-Z]{2}$' then raise exception 'invalid_shipping_country' using errcode='22023'; end if;
  if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items) not between 1 and 50 then raise exception 'invalid_cart_items' using errcode='22023'; end if;

  for item in select value from jsonb_array_elements(p_items)
  loop
    product_reference := btrim(coalesce(item->>'productReference',item->>'productId',item->>'id',''));
    if coalesce(item->>'quantity','') !~ '^[0-9]{1,2}$' then raise exception 'invalid_cart_item' using errcode='22023'; end if;
    quantity_value := (item->>'quantity')::integer;
    if quantity_value not between 1 and 99 then raise exception 'invalid_cart_quantity' using errcode='22023'; end if;

    select product.* into target_product
    from public.products product
    join public.producers producer on producer.id=product.producer_id
    where (product.id::text=product_reference or product.legacy_id=product_reference or product.slug=product_reference)
      and product.status='published' and product.is_active=true and product.deleted_at is null
      and producer.status='active' and producer.is_verified=true and producer.deleted_at is null
    limit 1;
    if target_product.id is null then raise exception 'product_not_available' using errcode='22023'; end if;

    select count(*)::integer into active_variant_count
    from public.product_variants variant where variant.product_id=target_product.id and variant.is_active=true;
    if active_variant_count <> 1 then
      raise exception 'explicit_variant_checkout_required:%',target_product.id using errcode='55000';
    end if;

    select variant.* into target_variant
    from public.product_variants variant
    where variant.product_id=target_product.id and variant.is_active=true
    order by variant.is_default desc,variant.created_at asc limit 1;

    subtotal_value := subtotal_value + (target_variant.price_minor * quantity_value);
    weight_value := weight_value + (coalesce(target_variant.weight_grams,1000) * quantity_value);
  end loop;

  quote := public.get_shipping_quote_v1(country_code,greatest(weight_value,1),subtotal_value,'TRY');
  if not coalesce((quote->>'available')::boolean,false) then
    if coalesce((quote->>'manualQuoteRequired')::boolean,false) then
      raise exception 'manual_shipping_quote_required:%',country_code using errcode='55000';
    end if;
    raise exception 'shipping_not_available:%',coalesce(quote->>'reason','unknown') using errcode='55000';
  end if;

  select coalesce((settings.public_config#>>'{checkout,shippingMinor}')::bigint,0)
  into brand_shipping
  from public.brand_settings settings
  where settings.slug='golden-oremar';

  if (quote->>'shippingMinor')::bigint <> brand_shipping then
    raise exception 'shipping_rate_sync_required' using errcode='55000';
  end if;

  result := private.create_customer_order(p_items,p_shipping_address,p_customer_note,p_idempotency_key);
  return result || jsonb_build_object(
    'shippingZoneCode',quote->>'zoneCode',
    'shippingCountryCode',country_code,
    'shippingWeightGrams',weight_value
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.create_customer_order_v2(p_items jsonb, p_shipping_address jsonb, p_customer_note text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  customer_profile public.profiles%rowtype;
  brand_config public.brand_settings%rowtype;
  existing_key private.idempotency_keys%rowtype;
  normalized_address jsonb;
  country_code text;
  request_hash text;
  scoped_key text;
  inserted_key_count integer:=0;
  item jsonb;
  product_reference text;
  variant_reference text;
  quantity_value integer;
  product_row public.products%rowtype;
  variant_row public.product_variants%rowtype;
  variant_count integer;
  cart_id_value uuid;
  order_id_value uuid:=gen_random_uuid();
  order_number_value text;
  currency_value text;
  subtotal_value bigint:=0;
  shipping_value bigint:=0;
  total_value bigint;
  max_order_value bigint:=100000000;
  reservation_hours integer:=24;
  total_weight integer:=0;
  missing_weight_count integer:=0;
  quote jsonb;
  shortage_product text;
  response_payload jsonb;
  reservation record;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into customer_profile from public.profiles where id=caller_id and status='active' and deleted_at is null;
  if customer_profile.id is null then raise exception 'active_profile_required' using errcode='42501'; end if;
  if p_idempotency_key is null or char_length(p_idempotency_key) not between 8 and 160 or p_idempotency_key !~ '^[A-Za-z0-9_-]+$' then raise exception 'invalid_idempotency_key' using errcode='22023'; end if;
  if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items) not between 1 and 50 then raise exception 'invalid_cart_items' using errcode='22023'; end if;
  if p_shipping_address is null or jsonb_typeof(p_shipping_address)<>'object' then raise exception 'invalid_shipping_address' using errcode='22023'; end if;
  if p_customer_note is not null and char_length(p_customer_note)>1000 then raise exception 'invalid_customer_note' using errcode='22023'; end if;
  country_code:=upper(coalesce(nullif(btrim(coalesce(p_shipping_address->>'country_code',p_shipping_address->>'countryCode','')),''),'TR'));
  normalized_address:=jsonb_strip_nulls(jsonb_build_object(
    'label',coalesce(nullif(btrim(coalesce(p_shipping_address->>'label','')),''),'Teslimat'),
    'recipient_name',nullif(btrim(coalesce(p_shipping_address->>'recipient_name',p_shipping_address->>'recipientName','')),''),
    'phone',nullif(btrim(coalesce(p_shipping_address->>'phone','')),''),
    'country_code',country_code,
    'administrative_area',nullif(btrim(coalesce(p_shipping_address->>'administrative_area',p_shipping_address->>'administrativeArea',p_shipping_address->>'province','')),''),
    'city',nullif(btrim(coalesce(p_shipping_address->>'city',p_shipping_address->>'district',p_shipping_address->>'province','')),''),
    'locality',nullif(btrim(coalesce(p_shipping_address->>'locality',p_shipping_address->>'neighborhood','')),''),
    'address_line1',nullif(btrim(coalesce(p_shipping_address->>'address_line1',p_shipping_address->>'addressLine1',p_shipping_address->>'address_line',p_shipping_address->>'addressLine','')),''),
    'address_line2',nullif(btrim(coalesce(p_shipping_address->>'address_line2',p_shipping_address->>'addressLine2','')),''),
    'postal_code',nullif(btrim(coalesce(p_shipping_address->>'postal_code',p_shipping_address->>'postalCode','')),''),
    'delivery_notes',nullif(btrim(coalesce(p_shipping_address->>'delivery_notes',p_shipping_address->>'deliveryNotes','')),'')
  ));
  if char_length(coalesce(normalized_address->>'recipient_name','')) not between 2 and 120
    or char_length(coalesce(normalized_address->>'phone','')) not between 7 and 40
    or country_code !~ '^[A-Z]{2}$'
    or char_length(coalesce(normalized_address->>'city','')) not between 1 and 160
    or char_length(coalesce(normalized_address->>'address_line1','')) not between 5 and 1000
    or char_length(coalesce(normalized_address->>'administrative_area',''))>160
    or char_length(coalesce(normalized_address->>'locality',''))>160
    or char_length(coalesce(normalized_address->>'address_line2',''))>500
    or char_length(coalesce(normalized_address->>'postal_code',''))>30
    or char_length(coalesce(normalized_address->>'delivery_notes',''))>500
  then raise exception 'invalid_shipping_address' using errcode='22023'; end if;
  select * into brand_config from public.brand_settings where slug='golden-oremar';
  if brand_config.slug is null then raise exception 'brand_configuration_missing' using errcode='P0001'; end if;
  currency_value:=brand_config.default_currency;
  if coalesce(brand_config.public_config#>>'{checkout,maxOrderMinor}','') ~ '^[0-9]+$' then max_order_value:=(brand_config.public_config#>>'{checkout,maxOrderMinor}')::bigint; end if;
  if coalesce(brand_config.public_config#>>'{checkout,stockReservationHours}','') ~ '^[0-9]+$' then reservation_hours:=least(168,greatest(1,(brand_config.public_config#>>'{checkout,stockReservationHours}')::integer)); end if;
  scoped_key:='checkout-v2:'||caller_id::text||':'||p_idempotency_key;
  request_hash:=encode(extensions.digest(convert_to(jsonb_build_object('user_id',caller_id,'items',p_items,'shipping_address',normalized_address,'customer_note',coalesce(p_customer_note,''))::text,'UTF8'),'sha256'),'hex');
  select * into existing_key from private.idempotency_keys where key=scoped_key;
  if existing_key.key is not null then
    if existing_key.scope<>'customer_checkout_v2' or existing_key.user_id is distinct from caller_id or existing_key.request_hash<>request_hash then raise exception 'idempotency_key_reused' using errcode='22023'; end if;
    if existing_key.completed_at is not null then return existing_key.response_body; end if;
    raise exception 'request_in_progress' using errcode='40001';
  end if;
  insert into private.idempotency_keys(key,scope,user_id,request_hash,locked_at,expires_at)
  values(scoped_key,'customer_checkout_v2',caller_id,request_hash,timezone('utc',now()),timezone('utc',now())+interval '7 days')
  on conflict(key) do nothing;
  get diagnostics inserted_key_count=row_count;
  if inserted_key_count=0 then raise exception 'request_in_progress' using errcode='40001'; end if;
  if (select count(*) from public.orders o where o.user_id=caller_id and o.created_at>timezone('utc',now())-interval '10 minutes')>=10 then raise exception 'order_rate_limit_exceeded' using errcode='P0001'; end if;
  select cart.id into cart_id_value from public.carts cart where cart.user_id=caller_id and cart.status='active' for update;
  if cart_id_value is null then
    insert into public.carts(user_id,status,currency,expires_at) values(caller_id,'active',currency_value,timezone('utc',now())+make_interval(hours=>reservation_hours)) returning id into cart_id_value;
  else
    delete from public.cart_items where cart_id=cart_id_value;
    update public.carts set currency=currency_value,expires_at=timezone('utc',now())+make_interval(hours=>reservation_hours),updated_at=timezone('utc',now()) where id=cart_id_value;
  end if;
  for item in select value from jsonb_array_elements(p_items) loop
    if jsonb_typeof(item)<>'object' then raise exception 'invalid_cart_item' using errcode='22023'; end if;
    product_reference:=btrim(coalesce(item->>'productReference',item->>'productId',item->>'id',''));
    variant_reference:=btrim(coalesce(item->>'variantReference',item->>'variantId',item->>'variantSku',''));
    if char_length(product_reference) not between 1 and 200 or coalesce(item->>'quantity','') !~ '^[0-9]{1,2}$' then raise exception 'invalid_cart_item' using errcode='22023'; end if;
    quantity_value:=(item->>'quantity')::integer;
    if quantity_value not between 1 and 99 then raise exception 'invalid_cart_quantity' using errcode='22023'; end if;
    select product.* into product_row
    from public.products product join public.producers producer on producer.id=product.producer_id
    where (product.id::text=product_reference or product.legacy_id=product_reference or product.slug=product_reference)
      and product.status='published' and product.is_active=true and product.deleted_at is null
      and producer.status='active' and producer.is_verified=true and producer.deleted_at is null
    limit 1;
    if product_row.id is null then raise exception 'product_not_available' using errcode='22023'; end if;
    if product_row.currency<>currency_value then raise exception 'mixed_currency_cart' using errcode='22023'; end if;
    if variant_reference<>'' then
      select variant.* into variant_row from public.product_variants variant
      where variant.product_id=product_row.id and variant.is_active=true and (variant.id::text=variant_reference or variant.sku=variant_reference)
      limit 1;
      if variant_row.id is null then raise exception 'variant_not_available' using errcode='22023'; end if;
    else
      select count(*)::integer into variant_count from public.product_variants variant where variant.product_id=product_row.id and variant.is_active=true;
      if variant_count=0 then raise exception 'variant_not_available' using errcode='22023'; end if;
      if variant_count>1 then raise exception 'variant_selection_required:%',product_row.id using errcode='22023'; end if;
      select variant.* into variant_row from public.product_variants variant where variant.product_id=product_row.id and variant.is_active=true order by variant.is_default desc,variant.created_at asc limit 1;
    end if;
    if exists(select 1 from public.cart_items existing where existing.cart_id=cart_id_value and existing.variant_id=variant_row.id) then raise exception 'duplicate_cart_variant' using errcode='22023'; end if;
    insert into public.cart_items(cart_id,variant_id,quantity,selected_options) values(cart_id_value,variant_row.id,quantity_value,variant_row.option_values);
    subtotal_value:=subtotal_value+(variant_row.price_minor*quantity_value);
    if variant_row.weight_grams is null or variant_row.weight_grams<=0 then missing_weight_count:=missing_weight_count+1; else total_weight:=total_weight+(variant_row.weight_grams*quantity_value); end if;
  end loop;
  if country_code<>'TR' and missing_weight_count>0 then raise exception 'international_shipping_weight_missing' using errcode='55000'; end if;
  total_weight:=greatest(total_weight,case when missing_weight_count>0 then missing_weight_count else 1 end);
  quote:=public.get_shipping_quote_v1(country_code,total_weight,subtotal_value,currency_value);
  if not coalesce((quote->>'available')::boolean,false) then
    if coalesce((quote->>'manualQuoteRequired')::boolean,false) then raise exception 'manual_shipping_quote_required:%',country_code using errcode='55000'; end if;
    raise exception 'shipping_not_available:%',coalesce(quote->>'reason','unknown') using errcode='55000';
  end if;
  shipping_value:=(quote->>'shippingMinor')::bigint;
  total_value:=subtotal_value+shipping_value;
  if subtotal_value<=0 or total_value<=0 or total_value>max_order_value then raise exception 'invalid_order_total' using errcode='22023'; end if;
  perform inventory.variant_id
  from public.product_inventory inventory
  join public.cart_items cart_item on cart_item.variant_id=inventory.variant_id
  join public.product_variants variant on variant.id=cart_item.variant_id
  join public.products product on product.id=variant.product_id
  where cart_item.cart_id=cart_id_value and product.stock_mode in ('tracked','seasonal')
  order by inventory.variant_id for update of inventory;
  select product.name into shortage_product
  from public.cart_items cart_item
  join public.product_variants variant on variant.id=cart_item.variant_id
  join public.products product on product.id=variant.product_id
  left join public.product_inventory inventory on inventory.variant_id=variant.id
  where cart_item.cart_id=cart_id_value and product.stock_mode in ('tracked','seasonal')
    and (inventory.variant_id is null or inventory.available_quantity-inventory.reserved_quantity<cart_item.quantity)
  order by product.name limit 1;
  if shortage_product is not null then raise exception 'insufficient_stock:%',shortage_product using errcode='P0001'; end if;
  order_number_value:=brand_config.order_prefix||'-'||to_char(timezone('utc',now()),'YYYYMMDD')||'-'||lpad(nextval('public.order_number_seq')::text,8,'0');
  insert into public.orders(id,order_number,user_id,cart_id,status,payment_status,fulfillment_status,currency,subtotal_minor,discount_minor,tax_minor,shipping_minor,total_minor,shipping_address,customer_note,placed_at,checkout_idempotency_key,reservation_expires_at)
  values(order_id_value,order_number_value,caller_id,cart_id_value,'pending_payment','unpaid','unfulfilled',currency_value,subtotal_value,0,0,shipping_value,total_value,normalized_address,nullif(btrim(coalesce(p_customer_note,'')),''),timezone('utc',now()),p_idempotency_key,timezone('utc',now())+make_interval(hours=>reservation_hours));
  insert into public.order_items(order_id,product_id,variant_id,producer_id,product_name,variant_name,sku,image_path,quantity,unit_price_minor,discount_minor,tax_minor,line_total_minor,snapshot)
  select order_id_value,product.id,variant.id,product.producer_id,product.name,variant.name,variant.sku,primary_image.storage_path,cart_item.quantity,variant.price_minor,0,0,variant.price_minor*cart_item.quantity,
    jsonb_build_object('selected_options',variant.option_values,'product_slug',product.slug,'product_legacy_id',product.legacy_id,'unit_label',product.unit_label,'origin',product.origin,'stock_mode',product.stock_mode,'tax_rate_basis_points',product.tax_rate_basis_points,'weight_grams',variant.weight_grams)
  from public.cart_items cart_item
  join public.product_variants variant on variant.id=cart_item.variant_id
  join public.products product on product.id=variant.product_id
  left join lateral(select image.storage_path from public.product_images image where image.product_id=product.id order by image.is_primary desc,image.sort_order,image.created_at limit 1) primary_image on true
  where cart_item.cart_id=cart_id_value;
  for reservation in
    select item.variant_id,sum(item.quantity)::integer quantity from public.order_items item join public.products product on product.id=item.product_id
    where item.order_id=order_id_value and item.variant_id is not null and product.stock_mode in ('tracked','seasonal') group by item.variant_id order by item.variant_id
  loop
    update public.product_inventory set reserved_quantity=reserved_quantity+reservation.quantity,version=version+1,updated_at=timezone('utc',now()) where variant_id=reservation.variant_id;
    insert into private.inventory_movements(variant_id,movement_type,quantity_delta,reference_type,reference_id,reason,idempotency_key,actor_user_id)
    values(reservation.variant_id,'reservation',-reservation.quantity,'order',order_id_value,'Customer checkout v2 stock reservation','order:'||order_id_value::text||':reserve:'||reservation.variant_id::text,caller_id);
  end loop;
  insert into public.order_status_history(order_id,from_status,to_status,note,visible_to_customer,actor_user_id)
  values(order_id_value,null,'pending_payment','Sipariş talebi alındı. Ödeme doğrulaması bekleniyor.',true,caller_id);
  update public.carts set status='converted',expires_at=null,updated_at=timezone('utc',now()) where id=cart_id_value;
  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
  values('order',order_id_value,'order.pending_payment_created',jsonb_build_object('order_id',order_id_value,'order_number',order_number_value,'user_id',caller_id,'currency',currency_value,'subtotal_minor',subtotal_value,'shipping_minor',shipping_value,'total_minor',total_value,'shipping_country_code',country_code,'shipping_zone_code',quote->>'zoneCode','reservation_expires_at',timezone('utc',now())+make_interval(hours=>reservation_hours)));
  response_payload:=jsonb_build_object('ok',true,'orderId',order_id_value,'orderNumber',order_number_value,'status','pending_payment','paymentStatus','unpaid','paymentMode','provider_pending','currency',currency_value,'subtotalMinor',subtotal_value,'shippingMinor',shipping_value,'totalMinor',total_value,'shippingCountryCode',country_code,'shippingZoneCode',quote->>'zoneCode','shippingWeightGrams',total_weight,'reservationExpiresAt',timezone('utc',now())+make_interval(hours=>reservation_hours));
  update private.idempotency_keys set response_status=201,response_body=response_payload,completed_at=timezone('utc',now()) where key=scoped_key;
  return response_payload;
end;
$function$;

CREATE OR REPLACE FUNCTION private.create_customer_order_v3(p_items jsonb, p_shipping_address jsonb, p_customer_note text, p_coupon_code text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  derived_key text;
  base_result jsonb;
  promotion_result jsonb;
  order_id uuid;
  order_row public.orders%rowtype;
  country_code text;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if p_idempotency_key is null or char_length(p_idempotency_key) not between 8 and 160 or p_idempotency_key !~ '^[A-Za-z0-9_-]+$' then raise exception 'invalid_idempotency_key' using errcode='22023'; end if;
  country_code:=upper(coalesce(nullif(btrim(coalesce(p_shipping_address->>'country_code',p_shipping_address->>'countryCode','')),''),'TR'));
  derived_key:='v3_'||encode(extensions.digest(convert_to(caller_id::text||'|'||p_idempotency_key||'|'||coalesce(upper(btrim(p_coupon_code)),''),'UTF8'),'sha256'),'hex');
  base_result:=private.create_customer_order_v2(p_items,p_shipping_address,p_customer_note,derived_key);
  order_id:=(base_result->>'orderId')::uuid;
  perform private.validate_order_export_eligibility_v1(order_id,country_code);
  promotion_result:=private.reserve_order_promotion_v1(order_id,p_coupon_code);
  select * into order_row from public.orders where id=order_id;
  return base_result||jsonb_build_object('discountMinor',order_row.discount_minor,'totalMinor',order_row.total_minor,'promotion',promotion_result,'exportValidation','passed');
end;
$function$;

CREATE OR REPLACE FUNCTION private.create_customer_order_v4(p_items jsonb, p_shipping_address jsonb, p_customer_note text, p_coupon_code text, p_gift jsonb, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  base jsonb;
  order_id uuid;
  recipient_name text;
  recipient_phone text;
  recipient_email text;
  gift_message text;
  sender_name text;
  hide_price boolean:=true;
  country_code text;
  occasion_value text:='just_because';
  presentation_style_value text:='oremar_gold';
  card_title_value text;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if p_shipping_address is null or jsonb_typeof(p_shipping_address)<>'object' then raise exception 'invalid_shipping_address' using errcode='22023'; end if;
  country_code:=upper(btrim(coalesce(p_shipping_address->>'country_code',p_shipping_address->>'countryCode','')));
  if country_code !~ '^[A-Z]{2}$' then raise exception 'invalid_shipping_country' using errcode='22023'; end if;
  if p_gift is not null and jsonb_typeof(p_gift)<>'object' then raise exception 'invalid_gift_payload' using errcode='22023'; end if;
  if p_gift is not null then
    recipient_name:=btrim(coalesce(p_gift->>'recipientName',p_gift->>'recipient_name',''));
    recipient_phone:=nullif(btrim(coalesce(p_gift->>'recipientPhone',p_gift->>'recipient_phone','')),'');
    recipient_email:=nullif(lower(btrim(coalesce(p_gift->>'recipientEmail',p_gift->>'recipient_email',''))),'');
    gift_message:=nullif(btrim(coalesce(p_gift->>'message',p_gift->>'giftMessage','')),'');
    sender_name:=nullif(btrim(coalesce(p_gift->>'senderName','')),'');
    occasion_value:=lower(btrim(coalesce(p_gift->>'occasion','just_because')));
    presentation_style_value:=lower(btrim(coalesce(p_gift->>'presentationStyle','oremar_gold')));
    card_title_value:=nullif(btrim(coalesce(p_gift->>'cardTitle','')),'');
    if p_gift ? 'hidePrice' and jsonb_typeof(p_gift->'hidePrice')<>'boolean' then raise exception 'invalid_gift_hide_price' using errcode='22023'; end if;
    hide_price:=coalesce((p_gift->>'hidePrice')::boolean,true);
    if char_length(recipient_name) not between 2 and 120 or recipient_name ~ '[[:cntrl:]]' then raise exception 'gift_recipient_name_required' using errcode='22023'; end if;
    if recipient_phone is not null and (char_length(recipient_phone)>40 or recipient_phone ~ '[[:cntrl:]]' or char_length(regexp_replace(recipient_phone,'[^0-9]','','g')) not between 7 and 20) then raise exception 'invalid_gift_recipient_phone' using errcode='22023'; end if;
    if recipient_email is not null and (char_length(recipient_email)>254 or recipient_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') then raise exception 'invalid_gift_recipient_email' using errcode='22023'; end if;
    if gift_message is not null and (char_length(gift_message)>1000 or gift_message ~ '[\u0000]') then raise exception 'gift_message_too_long' using errcode='22023'; end if;
    if sender_name is not null and (char_length(sender_name)>120 or sender_name ~ '[[:cntrl:]]') then raise exception 'gift_sender_name_too_long' using errcode='22023'; end if;
    if occasion_value not in ('just_because','birthday','love','thank_you','celebration','get_well','new_home','new_baby') then raise exception 'invalid_gift_occasion' using errcode='22023'; end if;
    if presentation_style_value not in ('oremar_gold','mountain_warmth','minimal_elegance') then raise exception 'invalid_gift_presentation_style' using errcode='22023'; end if;
    if card_title_value is not null and (char_length(card_title_value) not between 2 and 100 or card_title_value ~ '[[:cntrl:]]') then raise exception 'invalid_gift_card_title' using errcode='22023'; end if;
  end if;
  base:=private.create_customer_order_v3(p_items,p_shipping_address,p_customer_note,p_coupon_code,p_idempotency_key);
  order_id:=(base->>'orderId')::uuid;
  if p_gift is not null then
    insert into private.order_gifts(order_id,user_id,recipient_name,recipient_phone,recipient_email,gift_message,sender_name,hide_price,occasion,presentation_style,card_title)
    values(order_id,caller_id,recipient_name,recipient_phone,recipient_email,gift_message,sender_name,hide_price,occasion_value,presentation_style_value,card_title_value)
    on conflict(order_id) do update set
      recipient_name=excluded.recipient_name,recipient_phone=excluded.recipient_phone,recipient_email=excluded.recipient_email,
      gift_message=excluded.gift_message,sender_name=excluded.sender_name,hide_price=excluded.hide_price,occasion=excluded.occasion,
      presentation_style=excluded.presentation_style,card_title=excluded.card_title,updated_at=timezone('utc',now());
  end if;
  return base||jsonb_build_object('gift',p_gift is not null,'giftOccasion',case when p_gift is null then null else occasion_value end,'giftPresentationStyle',case when p_gift is null then null else presentation_style_value end);
end;
$function$;

CREATE OR REPLACE FUNCTION private.create_customer_order_v5(p_items jsonb, p_shipping_address jsonb, p_customer_note text, p_coupon_code text, p_gift jsonb, p_payment_method_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  legal_readiness jsonb;
  payment_config jsonb;
  live_card_payments boolean:=false;
  hosted_checkout boolean:=false;
  configured_provider text;
  selected_method private.customer_payment_methods%rowtype;
  base jsonb;
  order_id_value uuid;
  items_with_customization jsonb:=p_items;
  source_item jsonb;
  variant_reference text;
  cart_variant_id uuid;
  cart_product_id uuid;
  cart_customization jsonb;
  normalized_customization jsonb;
  customization_by_variant jsonb:='{}'::jsonb;
  order_item record;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  legal_readiness:=private.commercial_checkout_legal_readiness_v1();
  if not coalesce((legal_readiness->>'ready')::boolean,false) then raise exception 'commercial_legal_readiness_required' using errcode='55000'; end if;
  select private.default_payment_control_v1()||coalesce(bs.public_config->'payments','{}'::jsonb) into payment_config from public.brand_settings bs where bs.slug='golden-oremar' limit 1;
  if payment_config is null then payment_config:=private.default_payment_control_v1(); end if;
  live_card_payments:=coalesce((payment_config->>'live_card_payments_enabled')::boolean,false);
  hosted_checkout:=coalesce((payment_config->>'checkout_form_enabled')::boolean,false);
  configured_provider:=nullif(lower(btrim(coalesce(payment_config->>'provider',''))),'');
  if configured_provider<>'iyzico' then raise exception 'payment_provider_not_configured' using errcode='55000'; end if;
  if p_payment_method_id is not null then
    if not live_card_payments then raise exception 'saved_card_payment_not_enabled' using errcode='55000'; end if;
    select * into selected_method from private.customer_payment_methods p where p.id=p_payment_method_id and p.user_id=caller_id and p.status='active' for update;
    if selected_method.id is null then raise exception 'payment_method_not_found' using errcode='P0002'; end if;
    if selected_method.provider<>configured_provider then raise exception 'payment_method_provider_mismatch' using errcode='22023'; end if;
    if selected_method.exp_year is not null and selected_method.exp_month is not null and make_date(selected_method.exp_year,selected_method.exp_month,1)<date_trunc('month',timezone('utc',now()))::date then raise exception 'payment_method_expired' using errcode='22023'; end if;
  elsif not hosted_checkout then raise exception 'payment_method_required' using errcode='22023'; end if;
  if p_items is not null and jsonb_typeof(p_items)='array' then
    items_with_customization:='[]'::jsonb;
    for source_item in select value from jsonb_array_elements(p_items) loop
      source_item:=source_item-'orderCustomization';
      variant_reference:=btrim(coalesce(source_item->>'variantReference',source_item->>'variantId',source_item->>'variantSku',''));
      cart_variant_id:=null; cart_product_id:=null; cart_customization:=null;
      if variant_reference<>'' then
        select ci.variant_id,v.product_id,ci.selected_options->'orderCustomization' into cart_variant_id,cart_product_id,cart_customization
        from public.carts c join public.cart_items ci on ci.cart_id=c.id join public.product_variants v on v.id=ci.variant_id
        where c.user_id=caller_id and c.status='active' and (c.expires_at is null or c.expires_at>timezone('utc',now())) and (v.id::text=variant_reference or v.sku=variant_reference)
        order by c.created_at desc limit 1;
      end if;
      if cart_variant_id is not null and cart_customization is not null and cart_customization<>'null'::jsonb then
        normalized_customization:=private.normalize_order_customization_v1(cart_product_id,cart_customization);
        customization_by_variant:=customization_by_variant||jsonb_build_object(cart_variant_id::text,normalized_customization);
        source_item:=source_item||jsonb_build_object('orderCustomization',normalized_customization);
      end if;
      items_with_customization:=items_with_customization||jsonb_build_array(source_item);
    end loop;
  end if;
  base:=private.create_customer_order_v4(items_with_customization,p_shipping_address,p_customer_note,p_coupon_code,p_gift,p_idempotency_key);
  order_id_value:=(base->>'orderId')::uuid;
  if customization_by_variant<>'{}'::jsonb then
    for order_item in select oi.id,oi.product_id,oi.variant_id,o.cart_id from public.order_items oi join public.orders o on o.id=oi.order_id where oi.order_id=order_id_value and oi.variant_id is not null loop
      normalized_customization:=customization_by_variant->order_item.variant_id::text;
      if normalized_customization is not null and normalized_customization<>'null'::jsonb then
        normalized_customization:=private.normalize_order_customization_v1(order_item.product_id,normalized_customization);
        update public.order_items set snapshot=jsonb_set(coalesce(snapshot,'{}'::jsonb),'{selected_options}',(coalesce(snapshot->'selected_options','{}'::jsonb)-'orderCustomization')||jsonb_build_object('orderCustomization',normalized_customization),true) where id=order_item.id;
        update public.cart_items set selected_options=(coalesce(selected_options,'{}'::jsonb)-'orderCustomization')||jsonb_build_object('orderCustomization',normalized_customization),updated_at=timezone('utc',now()) where cart_id=order_item.cart_id and variant_id=order_item.variant_id;
      end if;
    end loop;
  end if;
  if p_payment_method_id is not null then
    insert into private.order_payment_preferences(order_id,user_id,payment_method_id,provider) values(order_id_value,caller_id,selected_method.id,selected_method.provider) on conflict(order_id) do update set payment_method_id=excluded.payment_method_id,provider=excluded.provider,updated_at=timezone('utc',now()) where private.order_payment_preferences.user_id=caller_id;
    insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload) values('order',order_id_value,'order.payment_method_selected',jsonb_build_object('order_id',order_id_value,'user_id',caller_id,'payment_method_id',selected_method.id,'provider',selected_method.provider,'last4',selected_method.last4,'brand',selected_method.brand));
    base:=base||jsonb_build_object('paymentMethod',jsonb_build_object('id',selected_method.id,'provider',selected_method.provider,'brand',selected_method.brand,'last4',selected_method.last4,'nickname',selected_method.nickname),'paymentFlow','saved_card');
  else base:=base||jsonb_build_object('paymentMethod',null,'paymentFlow','checkout_form'); end if;
  return base;
end;
$function$;

CREATE OR REPLACE FUNCTION private.create_customer_order(p_items jsonb, p_shipping_address jsonb, p_customer_note text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_user_id uuid := (select auth.uid());
  customer_profile public.profiles%rowtype;
  brand_config public.brand_settings%rowtype;
  existing_key private.idempotency_keys%rowtype;
  normalized_address jsonb;
  normalized_options jsonb;
  request_hash text;
  scoped_key text;
  inserted_key_count integer := 0;
  item jsonb;
  product_reference text;
  quantity_value integer;
  target_product_id uuid;
  target_product_currency text;
  target_variant_id uuid;
  cart_id_value uuid;
  order_id_value uuid := gen_random_uuid();
  order_number_value text;
  currency_value text;
  subtotal_value bigint;
  shipping_value bigint := 0;
  max_order_value bigint := 100000000;
  reservation_hours integer := 24;
  total_value bigint;
  shortage_product text;
  response_payload jsonb;
  reservation record;
begin
  if current_user_id is null then raise exception 'authentication_required' using errcode = '42501'; end if;
  select profile.* into customer_profile from public.profiles profile where profile.id = current_user_id and profile.status = 'active' and profile.deleted_at is null;
  if not found then raise exception 'active_profile_required' using errcode = '42501'; end if;
  if p_idempotency_key is null or char_length(p_idempotency_key) not between 8 and 160 or p_idempotency_key !~ '^[A-Za-z0-9_-]+$' then
    raise exception 'invalid_idempotency_key' using errcode = '22023';
  end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) not between 1 and 50 then
    raise exception 'invalid_cart_items' using errcode = '22023';
  end if;
  if p_shipping_address is null or jsonb_typeof(p_shipping_address) <> 'object' then raise exception 'invalid_shipping_address' using errcode = '22023'; end if;
  if p_customer_note is not null and char_length(p_customer_note) > 1000 then raise exception 'invalid_customer_note' using errcode = '22023'; end if;
  normalized_address := jsonb_strip_nulls(jsonb_build_object(
    'label', nullif(btrim(coalesce(p_shipping_address ->> 'label', 'Teslimat')), ''),
    'recipient_name', nullif(btrim(coalesce(p_shipping_address ->> 'recipient_name', p_shipping_address ->> 'recipientName')), ''),
    'phone', nullif(btrim(coalesce(p_shipping_address ->> 'phone', '')), ''),
    'country_code', upper(coalesce(nullif(btrim(coalesce(p_shipping_address ->> 'country_code', p_shipping_address ->> 'countryCode')), ''), 'TR')),
    'province', nullif(btrim(coalesce(p_shipping_address ->> 'province', '')), ''),
    'district', nullif(btrim(coalesce(p_shipping_address ->> 'district', '')), ''),
    'neighborhood', nullif(btrim(coalesce(p_shipping_address ->> 'neighborhood', '')), ''),
    'address_line', nullif(btrim(coalesce(p_shipping_address ->> 'address_line', p_shipping_address ->> 'addressLine')), ''),
    'postal_code', nullif(btrim(coalesce(p_shipping_address ->> 'postal_code', p_shipping_address ->> 'postalCode')), ''),
    'delivery_notes', nullif(btrim(coalesce(p_shipping_address ->> 'delivery_notes', p_shipping_address ->> 'deliveryNotes')), '')
  ));
  if char_length(coalesce(normalized_address ->> 'label', '')) not between 1 and 60
    or char_length(coalesce(normalized_address ->> 'recipient_name', '')) not between 2 and 120
    or char_length(coalesce(normalized_address ->> 'phone', '')) not between 7 and 40
    or coalesce(normalized_address ->> 'country_code', '') !~ '^[A-Z]{2}$'
    or char_length(coalesce(normalized_address ->> 'province', '')) not between 2 and 120
    or char_length(coalesce(normalized_address ->> 'district', '')) not between 2 and 120
    or char_length(coalesce(normalized_address ->> 'neighborhood', '')) > 160
    or char_length(coalesce(normalized_address ->> 'address_line', '')) not between 10 and 1000
    or char_length(coalesce(normalized_address ->> 'postal_code', '')) > 20
    or char_length(coalesce(normalized_address ->> 'delivery_notes', '')) > 500 then
    raise exception 'invalid_shipping_address' using errcode = '22023';
  end if;
  scoped_key := 'checkout:' || current_user_id::text || ':' || p_idempotency_key;
  request_hash := encode(extensions.digest(convert_to(jsonb_build_object('user_id', current_user_id, 'items', p_items, 'shipping_address', normalized_address, 'customer_note', coalesce(p_customer_note, ''))::text, 'UTF8'), 'sha256'), 'hex');
  select key_row.* into existing_key from private.idempotency_keys key_row where key_row.key = scoped_key;
  if found then
    if existing_key.scope <> 'customer_checkout' or existing_key.user_id is distinct from current_user_id or existing_key.request_hash <> request_hash then
      raise exception 'idempotency_key_reused' using errcode = '22023';
    end if;
    if existing_key.completed_at is not null then return existing_key.response_body; end if;
    raise exception 'request_in_progress' using errcode = '40001';
  end if;
  insert into private.idempotency_keys(key, scope, user_id, request_hash, locked_at, expires_at)
  values (scoped_key, 'customer_checkout', current_user_id, request_hash, timezone('utc', now()), timezone('utc', now()) + interval '7 days')
  on conflict (key) do nothing;
  get diagnostics inserted_key_count = row_count;
  if inserted_key_count = 0 then
    select key_row.* into existing_key from private.idempotency_keys key_row where key_row.key = scoped_key;
    if existing_key.scope <> 'customer_checkout' or existing_key.user_id is distinct from current_user_id or existing_key.request_hash <> request_hash then
      raise exception 'idempotency_key_reused' using errcode = '22023';
    end if;
    if existing_key.completed_at is not null then return existing_key.response_body; end if;
    raise exception 'request_in_progress' using errcode = '40001';
  end if;
  if (select count(*) from public.orders customer_order where customer_order.user_id = current_user_id and customer_order.created_at > timezone('utc', now()) - interval '10 minutes') >= 10 then
    raise exception 'order_rate_limit_exceeded' using errcode = 'P0001';
  end if;
  select settings.* into brand_config from public.brand_settings settings where settings.slug = 'golden-oremar';
  if not found then raise exception 'brand_configuration_missing' using errcode = 'P0001'; end if;
  currency_value := brand_config.default_currency;
  if coalesce(brand_config.public_config #>> '{checkout,shippingMinor}', '') ~ '^[0-9]+$' then shipping_value := (brand_config.public_config #>> '{checkout,shippingMinor}')::bigint; end if;
  if coalesce(brand_config.public_config #>> '{checkout,maxOrderMinor}', '') ~ '^[0-9]+$' then max_order_value := (brand_config.public_config #>> '{checkout,maxOrderMinor}')::bigint; end if;
  if coalesce(brand_config.public_config #>> '{checkout,stockReservationHours}', '') ~ '^[0-9]+$' then
    reservation_hours := least(168, greatest(1, (brand_config.public_config #>> '{checkout,stockReservationHours}')::integer));
  end if;
  select cart.id into cart_id_value from public.carts cart where cart.user_id = current_user_id and cart.status = 'active' for update;
  if cart_id_value is null then
    insert into public.carts(user_id, status, currency, expires_at)
    values (current_user_id, 'active', currency_value, timezone('utc', now()) + make_interval(hours => reservation_hours))
    returning id into cart_id_value;
  else
    delete from public.cart_items where cart_id = cart_id_value;
    update public.carts set currency = currency_value, expires_at = timezone('utc', now()) + make_interval(hours => reservation_hours), updated_at = timezone('utc', now()) where id = cart_id_value;
  end if;
  for item in select value from jsonb_array_elements(p_items) loop
    if jsonb_typeof(item) <> 'object' then raise exception 'invalid_cart_item' using errcode = '22023'; end if;
    product_reference := btrim(coalesce(item ->> 'productReference', item ->> 'productId', item ->> 'id', ''));
    if char_length(product_reference) not between 1 and 200 or coalesce(item ->> 'quantity', '') !~ '^[0-9]{1,2}$' then
      raise exception 'invalid_cart_item' using errcode = '22023';
    end if;
    quantity_value := (item ->> 'quantity')::integer;
    if quantity_value not between 1 and 99 then raise exception 'invalid_cart_quantity' using errcode = '22023'; end if;
    normalized_options := coalesce(item -> 'selectedOptions', '{}'::jsonb);
    if jsonb_typeof(normalized_options) <> 'object' or octet_length(normalized_options::text) > 4000 then
      raise exception 'invalid_selected_options' using errcode = '22023';
    end if;
    select product.id, product.currency, variant.id into target_product_id, target_product_currency, target_variant_id
    from public.products product
    join public.producers producer on producer.id = product.producer_id
    join public.product_variants variant on variant.product_id = product.id
    where (product.id::text = product_reference or product.legacy_id = product_reference)
      and product.status = 'published' and product.is_active = true and product.deleted_at is null
      and producer.status = 'active' and producer.is_verified = true and producer.deleted_at is null
      and variant.is_active = true
    order by variant.is_default desc, variant.created_at asc limit 1;
    if not found then raise exception 'product_not_available' using errcode = '22023'; end if;
    if target_product_currency <> currency_value then raise exception 'mixed_currency_cart' using errcode = '22023'; end if;
    if exists (select 1 from public.cart_items existing_item where existing_item.cart_id = cart_id_value and existing_item.variant_id = target_variant_id and existing_item.selected_options = normalized_options) then
      raise exception 'duplicate_cart_item' using errcode = '22023';
    end if;
    insert into public.cart_items(cart_id, variant_id, quantity, selected_options) values (cart_id_value, target_variant_id, quantity_value, normalized_options);
  end loop;
  perform inventory.variant_id
  from public.product_inventory inventory
  join public.cart_items cart_item on cart_item.variant_id = inventory.variant_id
  join public.product_variants variant on variant.id = cart_item.variant_id
  join public.products product on product.id = variant.product_id
  where cart_item.cart_id = cart_id_value and product.stock_mode in ('tracked', 'seasonal')
  order by inventory.variant_id for update of inventory;
  select product.name into shortage_product
  from public.cart_items cart_item
  join public.product_variants variant on variant.id = cart_item.variant_id
  join public.products product on product.id = variant.product_id
  left join public.product_inventory inventory on inventory.variant_id = variant.id
  where cart_item.cart_id = cart_id_value and product.stock_mode in ('tracked', 'seasonal')
    and (inventory.variant_id is null or inventory.available_quantity - inventory.reserved_quantity < cart_item.quantity)
  order by product.name limit 1;
  if shortage_product is not null then raise exception 'insufficient_stock:%', shortage_product using errcode = 'P0001'; end if;
  select coalesce(sum(variant.price_minor * cart_item.quantity), 0) into subtotal_value
  from public.cart_items cart_item join public.product_variants variant on variant.id = cart_item.variant_id where cart_item.cart_id = cart_id_value;
  if coalesce(brand_config.public_config #>> '{checkout,freeShippingThresholdMinor}', '') ~ '^[0-9]+$'
    and subtotal_value >= (brand_config.public_config #>> '{checkout,freeShippingThresholdMinor}')::bigint then shipping_value := 0; end if;
  total_value := subtotal_value + shipping_value;
  if subtotal_value <= 0 or total_value <= 0 or total_value > max_order_value then raise exception 'invalid_order_total' using errcode = '22023'; end if;
  order_number_value := brand_config.order_prefix || '-' || to_char(timezone('utc', now()), 'YYYYMMDD') || '-' || lpad(nextval('public.order_number_seq')::text, 8, '0');
  insert into public.orders(id, order_number, user_id, cart_id, status, payment_status, fulfillment_status, currency, subtotal_minor, discount_minor, tax_minor, shipping_minor, total_minor, shipping_address, customer_note, placed_at, checkout_idempotency_key, reservation_expires_at)
  values (order_id_value, order_number_value, current_user_id, cart_id_value, 'pending_payment', 'unpaid', 'unfulfilled', currency_value, subtotal_value, 0, 0, shipping_value, total_value, normalized_address, nullif(btrim(coalesce(p_customer_note, '')), ''), timezone('utc', now()), p_idempotency_key, timezone('utc', now()) + make_interval(hours => reservation_hours));
  insert into public.order_items(order_id, product_id, variant_id, producer_id, product_name, variant_name, sku, image_path, quantity, unit_price_minor, discount_minor, tax_minor, line_total_minor, snapshot)
  select order_id_value, product.id, variant.id, product.producer_id, product.name, variant.name, variant.sku, primary_image.storage_path, cart_item.quantity, variant.price_minor, 0, 0, variant.price_minor * cart_item.quantity,
    jsonb_build_object('selected_options', cart_item.selected_options, 'product_slug', product.slug, 'product_legacy_id', product.legacy_id, 'unit_label', product.unit_label, 'origin', product.origin, 'stock_mode', product.stock_mode, 'tax_rate_basis_points', product.tax_rate_basis_points)
  from public.cart_items cart_item
  join public.product_variants variant on variant.id = cart_item.variant_id
  join public.products product on product.id = variant.product_id
  left join lateral (select image.storage_path from public.product_images image where image.product_id = product.id order by image.is_primary desc, image.sort_order asc, image.created_at asc limit 1) primary_image on true
  where cart_item.cart_id = cart_id_value;
  for reservation in
    select item.variant_id, sum(item.quantity)::integer as quantity from public.order_items item join public.products product on product.id = item.product_id
    where item.order_id = order_id_value and item.variant_id is not null and product.stock_mode in ('tracked', 'seasonal') group by item.variant_id order by item.variant_id
  loop
    update public.product_inventory inventory set reserved_quantity = inventory.reserved_quantity + reservation.quantity, version = inventory.version + 1, updated_at = timezone('utc', now()) where inventory.variant_id = reservation.variant_id;
    insert into private.inventory_movements(variant_id, movement_type, quantity_delta, reference_type, reference_id, reason, idempotency_key, actor_user_id)
    values (reservation.variant_id, 'reservation', -reservation.quantity, 'order', order_id_value, 'Customer checkout stock reservation', 'order:' || order_id_value::text || ':reserve:' || reservation.variant_id::text, current_user_id);
  end loop;
  insert into public.order_status_history(order_id, from_status, to_status, note, visible_to_customer, actor_user_id)
  values (order_id_value, null, 'pending_payment', 'Sipariş talebi alındı. Ödeme veya işletme onayı bekleniyor.', true, current_user_id);
  update public.carts set status = 'converted', expires_at = null, updated_at = timezone('utc', now()) where id = cart_id_value;
  insert into private.outbox_events(aggregate_type, aggregate_id, event_type, payload)
  values ('order', order_id_value, 'order.pending_payment_created', jsonb_build_object('order_id', order_id_value, 'order_number', order_number_value, 'user_id', current_user_id, 'currency', currency_value, 'total_minor', total_value, 'reservation_expires_at', timezone('utc', now()) + make_interval(hours => reservation_hours)));
  response_payload := jsonb_build_object('ok', true, 'orderId', order_id_value, 'orderNumber', order_number_value, 'status', 'pending_payment', 'paymentStatus', 'unpaid', 'paymentMode', 'manual_confirmation', 'currency', currency_value, 'subtotalMinor', subtotal_value, 'shippingMinor', shipping_value, 'totalMinor', total_value, 'reservationExpiresAt', timezone('utc', now()) + make_interval(hours => reservation_hours));
  update private.idempotency_keys set response_status = 201, response_body = response_payload, completed_at = timezone('utc', now()) where key = scoped_key;
  return response_payload;
end;
$function$;

CREATE OR REPLACE FUNCTION private.current_authenticator_assurance_level_v1()
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select case when coalesce((select auth.jwt()->>'aal'),'aal1')='aal2' then 'aal2' else 'aal1' end;
$function$;

CREATE OR REPLACE FUNCTION private.current_request_device_id_v1()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare headers jsonb; raw text;
begin
  begin headers:=nullif(current_setting('request.headers',true),'')::jsonb; exception when others then return null; end;
  raw:=nullif(btrim(coalesce(headers->>'x-golden-device-id','')),'');
  if raw is null or raw !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then return null; end if;
  return raw::uuid;
end;
$function$;

CREATE OR REPLACE FUNCTION private.current_request_ip_v1()
 RETURNS inet
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare headers jsonb; raw text;
begin
  begin headers:=nullif(current_setting('request.headers',true),'')::jsonb; exception when others then return null; end;
  if headers is null then return null; end if;
  raw:=coalesce(nullif(btrim(headers->>'cf-connecting-ip'),''),nullif(btrim(headers->>'x-real-ip'),''),nullif(btrim(split_part(coalesce(headers->>'x-forwarded-for',''),',',1)),''));
  if raw is null then return null; end if;
  begin return raw::inet; exception when others then return null; end;
end;
$function$;

CREATE OR REPLACE FUNCTION private.current_request_user_agent_hash_v1()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare headers jsonb; raw text;
begin
  begin headers:=nullif(current_setting('request.headers',true),'')::jsonb; exception when others then return null; end;
  raw:=left(coalesce(headers->>'user-agent',''),1000);
  if raw='' then return null; end if;
  return encode(extensions.digest(convert_to(raw,'UTF8'),'sha256'),'hex');
end;
$function$;

CREATE OR REPLACE FUNCTION private.customer_session_status_impl_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); profile public.profiles%rowtype; block jsonb; roles jsonb;
begin
  if caller_id is null then return null; end if;
  perform private.record_current_security_context_v1(caller_id);
  select * into profile from public.profiles where id=caller_id;
  if profile.id is null then return null; end if;
  block:=private.platform_access_block_v1(caller_id);
  select coalesce(jsonb_agg(r.role order by r.role),'[]'::jsonb) into roles from private.user_roles r where r.user_id=caller_id and (r.expires_at is null or r.expires_at>timezone('utc',now()));
  return jsonb_build_object('is_authenticated',true,'user_id',profile.id,'email',coalesce(auth.jwt()->>'email',''),'display_name',profile.display_name,'phone',profile.phone,'locale',profile.locale,'status',case when coalesce((block->>'blocked')::boolean,false) then 'blocked' else profile.status end,'roles',roles,'access_code',block->>'code','access_reason',block->>'reason','fraud_flag',coalesce((block->>'fraudFlag')::boolean,false));
end;
$function$;

CREATE OR REPLACE FUNCTION private.decorate_catalog_handling_v1(p_base jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare items jsonb;
begin
  select coalesce(jsonb_agg(
    jsonb_set(
      item || jsonb_build_object(
        'handlingProfile',coalesce(private.product_handling_profile_v1((item->>'id')::uuid),'null'::jsonb)
      ),
      '{producer}',
      coalesce(item->'producer','{}'::jsonb) || coalesce(private.catalog_producer_card_identity_v1((item#>>'{producer,id}')::uuid),'{}'::jsonb),
      true
    )
  ),'[]'::jsonb)
  into items
  from jsonb_array_elements(coalesce(p_base->'items','[]'::jsonb)) item;
  return jsonb_set(p_base,'{items}',items,true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.decrypt_producer_kyc(value text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select case
    when value is null then null
    else extensions.pgp_sym_decrypt(
      decode(value, 'base64'),
      private.producer_kyc_key()
    )
  end;
$function$;

CREATE OR REPLACE FUNCTION private.default_payment_control_v1()
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'mode','provider',
    'provider','iyzico',
    'checkout_form_enabled',false,
    'live_card_payments_enabled',false,
    'card_enrollment_enabled',false,
    'return_url',null,
    'requires_provider_configuration',true
  );
$function$;

CREATE OR REPLACE FUNCTION private.delete_customer_address_impl_v1(p_address_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); was_default boolean;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended(caller_id::text,85027));
  select is_default into was_default from public.addresses where id=p_address_id and user_id=caller_id and deleted_at is null for update;
  if not found then raise exception 'address_not_found' using errcode='P0002'; end if;
  update public.addresses set is_default=false,deleted_at=timezone('utc',now()),updated_at=timezone('utc',now()) where id=p_address_id and user_id=caller_id;
  if was_default then
    update public.addresses set is_default=true,updated_at=timezone('utc',now())
    where id=(select id from public.addresses where user_id=caller_id and deleted_at is null order by created_at desc limit 1);
  end if;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION private.dispatch_stock_alerts_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old_sellable integer:=greatest(0,old.available_quantity-old.reserved_quantity); new_sellable integer:=greatest(0,new.available_quantity-new.reserved_quantity); subscription record; product_row record; token_raw text;
begin
  if old_sellable>0 or new_sellable<=0 then return new; end if;
  select product.id product_id,product.name product_name,product.slug,variant.name variant_name into product_row
  from public.product_variants variant join public.products product on product.id=variant.product_id
  where variant.id=new.variant_id;
  if product_row.product_id is null then return new; end if;

  for subscription in select * from private.stock_alert_subscriptions where variant_id=new.variant_id and status='active' for update
  loop
    if subscription.user_id is not null and exists(select 1 from public.profiles where id=subscription.user_id and status='active' and deleted_at is null) then
      insert into public.notifications(user_id,type,title,message,action_url,metadata)
      values(subscription.user_id,'system','Stok geldi',product_row.product_name||' yeniden stokta.','/product/'||product_row.slug,jsonb_build_object('productId',product_row.product_id,'variantId',new.variant_id,'sellableQuantity',new_sellable));
    end if;
    if subscription.email_normalized is not null then
      token_raw:=encode(extensions.gen_random_bytes(24),'hex');
      update private.stock_alert_subscriptions set unsubscribe_token_hash=private.hash_marketing_token_v1(token_raw) where id=subscription.id;
      insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
      values('stock_alert',subscription.id,'stock_alert.available_email',jsonb_build_object('subscription_id',subscription.id,'email',subscription.email_normalized,'locale',subscription.locale,'unsubscribeToken',token_raw,'productId',product_row.product_id,'productName',product_row.product_name,'variantId',new.variant_id,'variantName',product_row.variant_name,'slug',product_row.slug));
    end if;
    update private.stock_alert_subscriptions set status='notified',notified_at=timezone('utc',now()) where id=subscription.id;
  end loop;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.editorial_text_array_v1(p_value jsonb, p_label text, p_max_items integer, p_max_len integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$declare
  result jsonb:='[]'::jsonb;
  item jsonb;
  item_text text;
  count_items integer:=0;
begin
  if p_value is null then return result; end if;
  if jsonb_typeof(p_value)<>'array' or jsonb_array_length(p_value)>p_max_items then raise exception 'invalid_%',p_label using errcode='22023'; end if;
  for item in select elem from jsonb_array_elements(p_value) as elements(elem) loop
    if jsonb_typeof(item)<>'string' then raise exception 'invalid_%',p_label using errcode='22023'; end if;
    item_text:=btrim(trim(both '"' from item::text));
    if item_text<>'' then
      if char_length(item_text)>p_max_len or item_text~E'[\\u0000-\\u001F\\u007F]' then raise exception 'invalid_%',p_label using errcode='22023'; end if;
      count_items:=count_items+1;
      result:=result||to_jsonb(item_text);
    end if;
  end loop;
  if count_items>p_max_items then raise exception 'invalid_%',p_label using errcode='22023'; end if;
  return result;
end;$function$;

CREATE OR REPLACE FUNCTION private.encrypt_producer_kyc(value text)
 RETURNS text
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select case
    when nullif(btrim(value), '') is null then null
    else encode(
      extensions.pgp_sym_encrypt(
        btrim(value),
        private.producer_kyc_key(),
        'cipher-algo=aes256, compress-algo=1'
      ),
      'base64'
    )
  end;
$function$;

CREATE OR REPLACE FUNCTION private.enforce_content_claim_policy()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  published_text text;
  claim_evidence jsonb;
  claim_reviewed boolean;
begin
  if new.status <> 'published' or new.content_type not in ('health_guide', 'product_health') then
    return new;
  end if;

  published_text := lower(concat_ws(' ', new.title, new.summary, new.body_markdown, new.body_html_sanitized));
  claim_evidence := coalesce(new.metadata -> 'claimEvidenceIds', '[]'::jsonb);
  claim_reviewed := coalesce(new.metadata ->> 'claimReviewStatus', '') = 'verified'
    and jsonb_typeof(claim_evidence) = 'array'
    and jsonb_array_length(claim_evidence) > 0;

  if published_text ~ '(şifa (deposu|kaynağı|iksiri|harikası)|doğal antibiyotik|bağışıklık.{0,40}(güçlendirir|destekler|artırır|korur)|(hastalık|kanser|diyabet|astım|bronşit|kolesterol|tansiyon|damar|romatizma|ağrı|yara|aft).{0,45}(önler|tedavi eder|iyileştirir|korur|hafifletir|giderir|düşürür|dengeler|açar|temizler))'
    and not claim_reviewed then
    raise exception using
      errcode = 'check_violation',
      message = 'İçerik sağlık beyanı, doğrulanmış inceleme ve kanıt kaydı olmadan yayımlanamaz.';
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.enforce_product_claim_policy()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  published_text text;
  claim_evidence jsonb;
  verification_evidence jsonb;
  claim_reviewed boolean;
  product_verified boolean;
begin
  if new.status <> 'published' then
    return new;
  end if;

  published_text := lower(concat_ws(
    ' ',
    new.name,
    new.short_description,
    new.description,
    new.story,
    array_to_string(new.tags, ' '),
    new.features::text
  ));

  claim_evidence := coalesce(new.specifications -> 'claimEvidenceIds', '[]'::jsonb);
  verification_evidence := coalesce(new.specifications -> 'verificationDocumentIds', '[]'::jsonb);
  claim_reviewed := coalesce(new.specifications ->> 'claimReviewStatus', '') = 'verified'
    and jsonb_typeof(claim_evidence) = 'array'
    and jsonb_array_length(claim_evidence) > 0;
  product_verified := coalesce(new.specifications ->> 'verificationStatus', '') = 'verified'
    and jsonb_typeof(verification_evidence) = 'array'
    and jsonb_array_length(verification_evidence) > 0;

  if published_text ~ '(şifa (deposu|kaynağı|iksiri|harikası)|doğal antibiyotik|bağışıklık.{0,40}(güçlendirir|destekler|artırır|korur)|(hastalık|kanser|diyabet|astım|bronşit|kolesterol|tansiyon|damar|romatizma|ağrı|yara|aft).{0,45}(önler|tedavi eder|iyileştirir|korur|hafifletir|giderir|düşürür|dengeler|açar|temizler))'
    and not claim_reviewed then
    raise exception using
      errcode = 'check_violation',
      message = 'Sağlık beyanı, doğrulanmış inceleme ve kanıt kaydı olmadan yayımlanamaz.';
  end if;

  if published_text ~ '(%100[[:space:]]+saf|laboratuvar onaylı|akredite laboratuvar.{0,30}mevcut|tamamen ilaçsız|sıfır müdahale)'
    and not product_verified then
    raise exception using
      errcode = 'check_violation',
      message = 'Kalite veya sertifika beyanı, doğrulanmış üretici belgesi olmadan yayımlanamaz.';
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.enforce_product_image_parent_media_integrity_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op<>'DELETE' then
    perform private.assert_published_product_media_integrity_v1(new.product_id);
  end if;
  if tg_op<>'INSERT' and (tg_op='DELETE' or old.product_id is distinct from new.product_id) then
    perform private.assert_published_product_media_integrity_v1(old.product_id);
  end if;
  return coalesce(new,old);
end;
$function$;

CREATE OR REPLACE FUNCTION private.enforce_product_image_storage_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  producer_row public.producers%rowtype;
  path_value text;
  caller_is_admin boolean:=false;
begin
  path_value:=private.verified_catalog_product_image_path_v1(new.storage_path);
  if path_value is null then
    raise exception 'verified_catalog_product_image_required' using errcode='22023';
  end if;
  new.storage_path:=path_value;

  select producer.* into producer_row
  from public.products product
  join public.producers producer on producer.id=product.producer_id
  where product.id=new.product_id and product.deleted_at is null;
  if producer_row.id is null then
    raise exception 'product_image_product_not_found' using errcode='P0002';
  end if;

  if caller_id is null then return new; end if;
  caller_is_admin:=coalesce(private.has_permission('admin.access'),false)
                   and coalesce(private.has_permission('product.update'),false);
  if caller_is_admin then return new; end if;

  if producer_row.owner_user_id is distinct from caller_id then
    raise exception 'product_image_access_denied' using errcode='42501';
  end if;
  if split_part(path_value,'/',1)<>producer_row.id::text
     or split_part(path_value,'/',2)<>'products'
     or split_part(path_value,'/',3)=''
     or split_part(path_value,'/',4)<>'' then
    raise exception 'product_image_must_use_owned_producer_catalog_path' using errcode='22023';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.enforce_product_publish_media_integrity_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform private.assert_published_product_media_integrity_v1(new.id);
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.enforce_super_admin_product_publication_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  publication_requested boolean:=false;
begin
  if new.status='published' then
    if tg_op='INSERT' then
      publication_requested:=true;
    else
      publication_requested:=old.status is distinct from 'published'
        or (new.is_active=true and old.is_active is distinct from true);
    end if;
  end if;
  if not publication_requested then return new; end if;
  if auth.uid() is null or not coalesce(private.has_permission('product.publish'),false) then
    raise exception 'permission_required:product.publish' using errcode='42501';
  end if;
  if not exists(
    select 1 from public.content_entries e
    where e.related_product_id=new.id
      and e.content_type='product_health'
      and e.locale='tr'
      and e.status='published'
      and e.deleted_at is null
  ) then
    raise exception 'published_product_health_required' using errcode='55000';
  end if;
  perform private.write_admin_audit_v2(
    'product.publication_authorized','product',new.id::text,
    case when tg_op='UPDATE' then jsonb_build_object('status',old.status,'isActive',old.is_active) else null end,
    jsonb_build_object('status',new.status,'isActive',new.is_active),
    jsonb_build_object('gate','product.publish','healthPackageVerified',true,'ownerApprovalRequired',true),null
  );
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.enforce_verified_producer_product_write_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  owner_id uuid;
  producer_status text;
  producer_verified boolean;
  producer_origin_verified boolean;
  producer_store_kind text;
  producer_location text;
  producer_categories text[];
  category_slug text;
begin
  -- Trusted server/service writes have no end-user uid. Administrative product
  -- writes are protected by their own capability gates and publication guard.
  if caller_id is null or coalesce(private.is_admin(), false) then
    return new;
  end if;

  if tg_op = 'UPDATE' and new.producer_id is distinct from old.producer_id then
    raise exception 'product_producer_transfer_not_allowed' using errcode = '42501';
  end if;

  select
    p.owner_user_id,
    p.status,
    p.is_verified,
    p.origin_verified,
    p.store_kind,
    p.production_location,
    p.approved_category_slugs
  into
    owner_id,
    producer_status,
    producer_verified,
    producer_origin_verified,
    producer_store_kind,
    producer_location,
    producer_categories
  from public.producers p
  where p.id = new.producer_id
    and p.deleted_at is null;

  if owner_id is distinct from caller_id
     or producer_status <> 'active'
     or not coalesce(producer_verified, false) then
    raise exception 'verified_active_producer_required' using errcode = '42501';
  end if;

  -- The canonical Golden Oremar official store is never managed through the
  -- producer write path. Its product management must remain admin-only.
  if coalesce(producer_store_kind, '') = 'official' then
    raise exception 'official_store_product_management_requires_admin' using errcode = '42501';
  end if;

  if not coalesce(producer_origin_verified, false) then
    raise exception 'producer_origin_verification_required' using errcode = '42501';
  end if;

  if not private.is_producer_trust_badge_active_v1(new.producer_id) then
    raise exception 'active_producer_trust_badge_required' using errcode = '42501';
  end if;

  if coalesce(cardinality(producer_categories), 0) = 0 then
    raise exception 'producer_category_scope_required' using errcode = '42501';
  end if;

  select c.slug
  into category_slug
  from public.categories c
  where c.id = new.category_id
    and c.is_active = true;

  if category_slug is null
     or not (category_slug = any(producer_categories)) then
    raise exception 'product_category_outside_producer_scope' using errcode = '42501';
  end if;

  if nullif(btrim(coalesce(producer_location, '')), '') is null then
    raise exception 'producer_production_location_required' using errcode = '42501';
  end if;

  -- Producer product origin is server-authoritative. This mirrors the
  -- producer RPC contract and prevents a lower-level caller from spoofing it.
  new.origin := producer_location;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.enqueue_admin_domain_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_table_name = 'campaigns' then
    insert into private.outbox_events(aggregate_type, aggregate_id, event_type, payload)
    values (
      'campaign',
      new.id,
      case when tg_op = 'INSERT' then 'campaign.created' else 'campaign.updated' end,
      jsonb_build_object('campaign_id', new.id, 'status', new.status, 'target_scope', new.target_scope)
    );
  elsif tg_table_name = 'reviews' then
    insert into private.outbox_events(aggregate_type, aggregate_id, event_type, payload)
    values (
      'review',
      new.id,
      'review.moderated',
      jsonb_build_object('review_id', new.id, 'status', new.status)
    );
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.enqueue_event_payment_receipt_email_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.payment_status='paid' and (tg_op='INSERT' or old.payment_status is distinct from new.payment_status) then
    insert into private.transactional_email_jobs(kind,aggregate_id,user_id,payload)
    values('event_payment_receipt',new.reservation_id,new.user_id,private.build_event_payment_receipt_payload_v1(new.reservation_id))
    on conflict(kind,aggregate_id) do nothing;
  end if;
  return new;
end;
$function$;

