CREATE OR REPLACE FUNCTION private.get_conversation_messages_v1(p_conversation_id uuid, p_limit integer DEFAULT 50, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); result jsonb;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if p_limit not between 1 and 100 then raise exception 'invalid_pagination' using errcode='22023'; end if;
  if not exists(select 1 from public.conversation_participants where conversation_id=p_conversation_id and user_id=caller_id) then raise exception 'conversation_access_denied' using errcode='42501'; end if;
  select coalesce(jsonb_agg(item order by created_at asc),'[]'::jsonb) into result
  from (
    select jsonb_build_object(
      'id',message.id,'senderUserId',message.sender_user_id,'senderName',profile.display_name,'isMine',message.sender_user_id=caller_id,
      'body',case when message.deleted_at is null then message.body else 'Mesaj kaldırıldı' end,
      'attachmentPaths',case when message.deleted_at is null then message.attachment_paths else '{}'::text[] end,
      'messageType',message.message_type,'createdAt',message.created_at,'editedAt',message.edited_at,'deletedAt',message.deleted_at
    ) item,message.created_at
    from public.messages message join public.profiles profile on profile.id=message.sender_user_id
    where message.conversation_id=p_conversation_id and (p_before is null or message.created_at<p_before)
    order by message.created_at desc limit p_limit
  ) rows;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_conversation_safety_context_v1(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); target_id uuid; target_name text; target_role text;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if not exists(select 1 from public.conversation_participants p where p.conversation_id=p_conversation_id and p.user_id=caller_id) then raise exception 'conversation_access_denied' using errcode='42501'; end if;
  select p.user_id, profile.display_name, p.participant_role into target_id,target_name,target_role
  from public.conversation_participants p join public.profiles profile on profile.id=p.user_id
  where p.conversation_id=p_conversation_id and p.user_id<>caller_id and p.participant_role in ('customer','producer')
  order by case p.participant_role when 'producer' then 0 else 1 end, p.joined_at asc limit 1;
  return jsonb_build_object(
    'conversationId',p_conversation_id,
    'canBlock',target_id is not null,
    'counterpartName',target_name,
    'counterpartRole',target_role,
    'blockedByMe',target_id is not null and exists(select 1 from private.user_blocks b where b.blocker_user_id=caller_id and b.blocked_user_id=target_id and b.removed_at is null),
    'blocksMe',target_id is not null and exists(select 1 from private.user_blocks b where b.blocker_user_id=target_id and b.blocked_user_id=caller_id and b.removed_at is null)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_customer_cart_snapshot_v1(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare cart_row public.carts%rowtype; result jsonb;
begin
  if p_user_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into cart_row from public.carts where user_id=p_user_id and status='active' and (expires_at is null or expires_at>timezone('utc',now())) order by created_at desc limit 1;
  if cart_row.id is null then return jsonb_build_object('cartId',null,'currency','TRY','itemCount',0,'subtotalMinor',0,'items','[]'::jsonb); end if;
  with rows as (
    select item.id cart_item_id,item.quantity,item.selected_options,
      variant.id variant_id,variant.name raw_variant_name,variant.sku,variant.price_minor,variant.compare_at_price_minor,variant.weight_grams,
      product.id product_id,product.legacy_id,product.slug,product.name product_name,product.unit_label,product.stock_mode,product.currency,
      producer.id producer_id,producer.display_name producer_name,image.storage_path image_path,
      case when product.stock_mode in ('tracked','seasonal') then greatest(0,coalesce(inventory.available_quantity,0)-coalesce(inventory.reserved_quantity,0)) else null end sellable_quantity,
      (item.quantity*variant.price_minor)::bigint line_total_minor,
      (product.status='published' and product.is_active=true and product.deleted_at is null and variant.is_active=true and producer.status='active' and producer.is_verified=true and producer.deleted_at is null) available
    from public.cart_items item
    join public.product_variants variant on variant.id=item.variant_id
    join public.products product on product.id=variant.product_id
    join public.producers producer on producer.id=product.producer_id
    left join public.product_inventory inventory on inventory.variant_id=variant.id
    left join lateral(select pi.storage_path from public.product_images pi where pi.product_id=product.id order by pi.is_primary desc,pi.sort_order asc limit 1) image on true
    where item.cart_id=cart_row.id
  )
  select jsonb_build_object(
    'cartId',cart_row.id,'currency',cart_row.currency,'expiresAt',cart_row.expires_at,
    'itemCount',coalesce(sum(quantity),0),'subtotalMinor',coalesce(sum(line_total_minor),0),
    'items',coalesce(jsonb_agg(jsonb_build_object(
      'cartItemId',cart_item_id,'quantity',quantity,'selectedOptions',selected_options,
      'productId',product_id,'legacyId',legacy_id,'slug',slug,'productName',product_name,'unitLabel',unit_label,
      'variantId',variant_id,'variantName',left(raw_variant_name||case when private.order_customization_summary_v1(selected_options)<>'' then ' · '||private.order_customization_summary_v1(selected_options) else '' end,240),'sku',sku,'priceMinor',price_minor,'compareAtPriceMinor',compare_at_price_minor,'weightGrams',weight_grams,
      'producer',jsonb_build_object('id',producer_id,'name',producer_name),'imagePath',image_path,
      'stockMode',stock_mode,'sellableQuantity',sellable_quantity,'available',available,'lineTotalMinor',line_total_minor,
      'handlingProfile',private.product_handling_profile_v1(product_id)
    ) order by product_name,raw_variant_name),'[]'::jsonb)
  ) into result from rows;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_hosted_payment_intent_for_service_v1(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare intent private.payment_intents%rowtype; normalized_token text:=btrim(coalesce(p_token,'')); context jsonb;
begin
  if char_length(normalized_token) not between 8 and 500 then raise exception 'invalid_provider_session_token' using errcode='22023'; end if;
  select * into intent from private.payment_intents where provider='iyzico' and provider_session_token=normalized_token;
  if intent.id is null or intent.payment_flow<>'checkout_form' then raise exception 'hosted_payment_session_not_found' using errcode='P0002'; end if;
  context:=private.get_payment_intent_for_service_v1(intent.id);
  return context||jsonb_build_object('paymentFlow',intent.payment_flow,'providerSessionToken',intent.provider_session_token);
end;$function$;

