CREATE OR REPLACE FUNCTION private.get_my_newsletter_status_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  email_value text:=lower(btrim(coalesce(auth.jwt()->>'email','')));
  sub private.newsletter_subscriptions%rowtype;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into sub
  from private.newsletter_subscriptions subscription
  where subscription.user_id=caller_id or (email_value<>'' and subscription.email_normalized=email_value)
  order by case when subscription.user_id=caller_id then 0 else 1 end,subscription.updated_at desc
  limit 1;

  if sub.id is null then
    return jsonb_build_object('status','none','email',nullif(email_value,''));
  end if;
  return jsonb_build_object(
    'status',sub.status,
    'email',sub.email_normalized,
    'locale',sub.locale,
    'consentVersion',sub.consent_version,
    'consentedAt',sub.consented_at,
    'confirmedAt',sub.confirmed_at,
    'unsubscribedAt',sub.unsubscribed_at
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_my_notification_preferences_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); pref private.user_notification_preferences%rowtype;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into pref from private.user_notification_preferences where user_id=caller_id;
  return jsonb_build_object(
    'pushEnabled',coalesce(pref.push_enabled,true),'orderPush',coalesce(pref.order_push,true),'paymentPush',coalesce(pref.payment_push,true),
    'shipmentPush',coalesce(pref.shipment_push,true),'returnPush',coalesce(pref.return_push,true),'messagePush',coalesce(pref.message_push,true),
    'reviewPush',coalesce(pref.review_push,true),'producerPush',coalesce(pref.producer_push,true),'systemPush',coalesce(pref.system_push,true),
    'campaignPush',coalesce(pref.campaign_push,false)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_my_order_detail_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); o public.orders%rowtype; result jsonb;
begin
 if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
 select * into o from public.orders where id=p_order_id and user_id=caller_id;
 if o.id is null then raise exception 'order_not_found' using errcode='P0002'; end if;
 select jsonb_build_object(
   'id',o.id,'orderNumber',o.order_number,'status',o.status,'paymentStatus',o.payment_status,'fulfillmentStatus',o.fulfillment_status,
   'currency',o.currency,'subtotalMinor',o.subtotal_minor,'discountMinor',o.discount_minor,'taxMinor',o.tax_minor,'shippingMinor',o.shipping_minor,'totalMinor',o.total_minor,
   'shippingAddress',o.shipping_address,'customerNote',o.customer_note,'placedAt',o.placed_at,'createdAt',o.created_at,'updatedAt',o.updated_at,
   'cancelledAt',o.cancelled_at,'completedAt',o.completed_at,'reservationExpiresAt',o.reservation_expires_at,
   'items',coalesce((select jsonb_agg(jsonb_build_object(
      'id',i.id,'productId',i.product_id,'variantId',i.variant_id,'producerId',i.producer_id,'productName',i.product_name,'variantName',i.variant_name,
      'sku',i.sku,'imagePath',i.image_path,'quantity',i.quantity,'unitPriceMinor',i.unit_price_minor,'discountMinor',i.discount_minor,'taxMinor',i.tax_minor,
      'lineTotalMinor',i.line_total_minor,'fulfillmentStatus',i.fulfillment_status,'snapshot',i.snapshot,
      'reviewed',exists(select 1 from public.reviews r where r.order_item_id=i.id)
    ) order by i.created_at) from public.order_items i where i.order_id=o.id),'[]'::jsonb),
   'statusHistory',coalesce((select jsonb_agg(jsonb_build_object('from',h.from_status,'to',h.to_status,'note',h.note,'at',h.created_at) order by h.created_at) from public.order_status_history h where h.order_id=o.id and h.visible_to_customer=true),'[]'::jsonb),
   'shipments',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'carrier',s.carrier,'trackingNumber',s.tracking_number,'trackingUrl',s.tracking_url,'status',s.status,'shippedAt',s.shipped_at,'deliveredAt',s.delivered_at,'estimatedDeliveryAt',s.estimated_delivery_at) order by s.created_at) from public.shipments s where s.order_id=o.id),'[]'::jsonb),
   'returns',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'returnNumber',r.return_number,'reasonCode',r.reason_code,'customerMessage',r.customer_message,'status',r.status,'resolution',r.resolution,'requestedAt',r.requested_at,'resolutionNote',r.resolution_note) order by r.created_at desc) from public.return_requests r where r.order_id=o.id and r.user_id=caller_id),'[]'::jsonb),
   'refunds',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'amountMinor',r.amount_minor,'currency',r.currency,'status',r.status,'reason',r.reason,'processedAt',r.processed_at) order by r.created_at desc) from public.refunds r where r.order_id=o.id),'[]'::jsonb),
   'payments',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'provider',p.provider,'paymentMethodType',p.payment_method_type,'amountMinor',p.amount_minor,'currency',p.currency,'status',p.status,'authorizedAt',p.authorized_at,'capturedAt',p.captured_at,'createdAt',p.created_at) order by p.created_at desc) from public.payment_records p where p.order_id=o.id and p.user_id=caller_id),'[]'::jsonb),
   'gift',(select jsonb_build_object('recipientName',g.recipient_name,'recipientPhone',g.recipient_phone,'recipientEmail',g.recipient_email,'message',g.gift_message,'senderName',g.sender_name,'hidePrice',g.hide_price) from private.order_gifts g where g.order_id=o.id and g.user_id=caller_id)
 ) into result;
 return result;
end; $function$;

CREATE OR REPLACE FUNCTION private.get_my_order_return_options_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  target_order public.orders%rowtype;
  active_return boolean;
  result jsonb;
begin
  if caller_id is null then
    raise exception 'authentication_required' using errcode='42501';
  end if;

  select * into target_order
  from public.orders customer_order
  where customer_order.id = p_order_id and customer_order.user_id = caller_id;

  if target_order.id is null then
    raise exception 'order_not_found' using errcode='P0002';
  end if;

  select exists(
    select 1
    from public.return_requests request
    where request.order_id = target_order.id
      and request.user_id = caller_id
      and request.status in ('requested','under_review','approved','in_transit','received')
  ) into active_return;

  select jsonb_build_object(
    'orderId',target_order.id,
    'orderNumber',target_order.order_number,
    'orderStatus',target_order.status,
    'eligibleStatus',target_order.status in ('delivered','completed'),
    'activeReturnExists',active_return,
    'canRequest',(target_order.status in ('delivered','completed')) and not active_return and exists(
      select 1
      from public.order_items item
      where item.order_id = target_order.id
        and item.quantity > coalesce((
          select sum(return_item.quantity)::integer
          from public.return_items return_item
          join public.return_requests request on request.id=return_item.return_id
          where return_item.order_item_id=item.id and request.status <> 'rejected'
        ),0)
    ),
    'reasonCodes',jsonb_build_array('damaged','wrong_item','quality_issue','missing_item','changed_mind','delivery_issue','other'),
    'items',coalesce((
      select jsonb_agg(jsonb_build_object(
        'orderItemId',item.id,
        'productId',item.product_id,
        'variantId',item.variant_id,
        'productName',item.product_name,
        'variantName',item.variant_name,
        'imagePath',item.image_path,
        'purchasedQuantity',item.quantity,
        'returnedQuantity',returned.returned_quantity,
        'remainingQuantity',greatest(0,item.quantity-returned.returned_quantity),
        'unitPriceMinor',item.unit_price_minor,
        'lineTotalMinor',item.line_total_minor,
        'currency',target_order.currency
      ) order by item.created_at)
      from public.order_items item
      cross join lateral (
        select coalesce(sum(return_item.quantity),0)::integer as returned_quantity
        from public.return_items return_item
        join public.return_requests request on request.id=return_item.return_id
        where return_item.order_item_id=item.id and request.status <> 'rejected'
      ) returned
      where item.order_id=target_order.id
    ),'[]'::jsonb)
  ) into result;

  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_my_producer_application_draft_v5(p_application_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  result jsonb;
begin
  if caller_id is null then
    raise exception 'authentication_required' using errcode='42501';
  end if;

  select jsonb_build_object(
    'application_id', a.id,
    'applicant_type', a.applicant_type,
    'status', a.status,
    'seller_classification', a.seller_classification,
    'activity_types', a.activity_types,
    'brand_name', a.brand_name,
    'public_name', a.public_name,
    'description', a.description,
    'production_location', jsonb_build_object(
      'country_code', a.production_country_code,
      'province', a.production_province,
      'district', a.production_district,
      'village', a.production_village,
      'village_is_custom', a.production_village_is_custom,
      'latitude', a.production_latitude,
      'longitude', a.production_longitude
    ),
    'production_country_code', a.production_country_code,
    'production_province', a.production_province,
    'production_district', a.production_district,
    'production_village', a.production_village,
    'production_village_is_custom', a.production_village_is_custom,
    'production_latitude', a.production_latitude,
    'production_longitude', a.production_longitude,
    'product_categories', a.product_categories,
    'food_compliance_status', a.food_compliance_status,
    'fulfillment_methods', a.fulfillment_methods,
    'average_dispatch_days', a.average_dispatch_days,
    'cold_chain_capable', a.cold_chain_capable,
    'planned_products', a.planned_products,
    'sourcing_models', a.sourcing_models,
    'organic_claim_status', a.organic_claim_status,
    'organic_certifier_name', coalesce(a.organic_certifier_name,''),
    'organic_certificate_number', coalesce(private.decrypt_producer_kyc(k.organic_certificate_number_ciphertext),''),
    'organic_certificate_expires_on', a.organic_certificate_expires_on,
    'village_product_commitment', a.village_product_commitment,
    'traceability_commitment', a.traceability_commitment,
    'product_truth_commitment', a.product_truth_commitment,
    'production_practice_notes', a.production_practice_notes,
    'submitted_at', a.submitted_at,
    'rejection_reason', a.rejection_reason,
    'created_at', a.created_at,
    'updated_at', a.updated_at,
    'legal_name', k.legal_name,
    'identifier', case when a.applicant_type='individual'
      then private.decrypt_producer_kyc(k.national_id_ciphertext)
      else private.decrypt_producer_kyc(k.tax_number_ciphertext) end,
    'tax_office', coalesce(k.tax_office,''),
    'mersis_number', coalesce(private.decrypt_producer_kyc(k.mersis_number_ciphertext),''),
    'tax_exemption_number', coalesce(private.decrypt_producer_kyc(k.tax_exemption_number_ciphertext),''),
    'food_registration_number', coalesce(private.decrypt_producer_kyc(k.food_registration_number_ciphertext),''),
    'iban', coalesce(private.decrypt_producer_kyc(k.iban_ciphertext),''),
    'phone', k.phone,
    'contact_email', k.contact_email,
    'contact_email_verified_at', k.contact_email_verified_at,
    'phone_verified_at', k.phone_verified_at,
    'address', k.address,
    'consent_version', k.consent_version,
    'existing_document_types', coalesce((
      select jsonb_agg(distinct d.document_type)
      from private.producer_documents d
      where d.application_id=a.id and d.verification_status<>'rejected'
    ), '[]'::jsonb)
  ) into result
  from public.producer_applications a
  join private.producer_application_kyc k on k.application_id=a.id
  where a.applicant_user_id=caller_id
    and (p_application_id is null or a.id=p_application_id)
  order by case when a.status in ('draft','needs_information') then 0 else 1 end,
           a.updated_at desc
  limit 1;

  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_my_producer_dashboard_v2()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  producer_row public.producers%rowtype;
  base jsonb;
  commerce jsonb;
begin
  if caller_id is null then
    raise exception 'authentication_required' using errcode='42501';
  end if;
  if not private.has_permission('product.read') or not private.has_permission('finance.read') then raise exception 'permission_required:producer.dashboard' using errcode='42501'; end if;
  if coalesce(private.has_permission('admin.access'), false) then
    raise exception 'producer_portal_separate_from_admin' using errcode='42501';
  end if;

  select p.* into producer_row
  from public.producers p
  where p.owner_user_id=caller_id and p.deleted_at is null
  order by p.created_at desc
  limit 1;

  if producer_row.id is null then
    raise exception 'producer_profile_required' using errcode='42501';
  end if;

  select jsonb_build_object(
    'profile', private.get_my_producer_profile_v1(),
    'inventory', case when producer_row.status='active' and producer_row.is_verified
      then private.list_my_producer_inventory_v1() else '[]'::jsonb end,
    'finance', private.get_my_producer_finance_summary_v1(),
    'summary', jsonb_build_object(
      'draftProducts', (select count(*) from public.products p where p.producer_id=producer_row.id and p.status='draft' and p.deleted_at is null),
      'reviewProducts', (select count(*) from public.products p where p.producer_id=producer_row.id and p.status='review' and p.deleted_at is null),
      'publishedProducts', (select count(*) from public.products p where p.producer_id=producer_row.id and p.status='published' and p.is_active=true and p.deleted_at is null),
      'rejectedProducts', (select count(*) from public.products p where p.producer_id=producer_row.id and p.status='rejected' and p.deleted_at is null),
      'pendingChanges', (select count(*) from public.product_change_requests r where r.producer_id=producer_row.id and r.status='pending'),
      'draftBatches', (select count(*) from public.product_batches b where b.producer_id=producer_row.id and b.status='draft'),
      'reviewBatches', (select count(*) from public.product_batches b where b.producer_id=producer_row.id and b.status='review'),
      'releasedBatches', (select count(*) from public.product_batches b where b.producer_id=producer_row.id and b.status='released'),
      'lowStockVariants', (
        select count(*)
        from public.product_inventory i
        join public.product_variants v on v.id=i.variant_id
        join public.products p on p.id=v.product_id
        where p.producer_id=producer_row.id
          and p.stock_mode in ('tracked','seasonal')
          and greatest(0,i.available_quantity-i.reserved_quantity)<=i.reorder_level
      )
    ),
    'changeRequests', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',r.id,'productId',r.product_id,'productName',p.name,'status',r.status,
        'proposedPayload',r.proposed_payload,'reviewReason',r.review_reason,
        'createdAt',r.created_at,'updatedAt',r.updated_at,'reviewedAt',r.reviewed_at
      ) order by r.created_at desc)
      from (
        select * from public.product_change_requests
        where producer_id=producer_row.id
        order by created_at desc limit 20
      ) r
      join public.products p on p.id=r.product_id
    ), '[]'::jsonb),
    'batches', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',b.id,'traceCode',b.trace_code,'batchCode',b.batch_code,
        'productId',b.product_id,'productName',p.name,'variantId',b.variant_id,
        'status',b.status,'harvestDate',b.harvest_date,'productionDate',b.production_date,
        'packagingDate',b.packaging_date,'bestBeforeDate',b.best_before_date,
        'reviewReason',b.review_reason,'submittedAt',b.submitted_at,
        'reviewedAt',b.reviewed_at,'releasedAt',b.released_at,'updatedAt',b.updated_at
      ) order by b.updated_at desc)
      from (
        select * from public.product_batches
        where producer_id=producer_row.id
        order by updated_at desc limit 20
      ) b
      join public.products p on p.id=b.product_id
    ), '[]'::jsonb),
    'recentPayouts', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',p.id,'currency',p.currency,'amountMinor',p.amount_minor,'status',p.status,
        'provider',p.provider,'providerReference',p.provider_reference,'note',p.note,
        'scheduledAt',p.scheduled_at,'processedAt',p.processed_at,'createdAt',p.created_at
      ) order by p.created_at desc)
      from (
        select * from private.producer_payouts
        where producer_id=producer_row.id
        order by created_at desc limit 10
      ) p
    ), '[]'::jsonb)
  ) into base;

  select jsonb_build_object(
    'followerCount', (select count(*) from private.producer_follows f where f.producer_id=producer_row.id),
    'orderCount', (select count(distinct oi.order_id) from public.order_items oi where oi.producer_id=producer_row.id),
    'openOrderCount', (
      select count(distinct oi.order_id)
      from public.order_items oi join public.orders o on o.id=oi.order_id
      where oi.producer_id=producer_row.id
        and o.status in ('confirmed','preparing','partially_shipped','shipped')
    ),
    'customerCount', (
      select count(distinct o.user_id)
      from public.order_items oi join public.orders o on o.id=oi.order_id
      where oi.producer_id=producer_row.id and o.status not in ('draft','cancelled')
    ),
    'recentOrders', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',x.id,'orderNumber',x.order_number,'status',x.status,
        'fulfillmentStatus',x.fulfillment_status,'currency',x.currency,
        'producerTotalMinor',x.producer_total_minor,'placedAt',x.placed_at,'createdAt',x.created_at
      ) order by x.created_at desc)
      from (
        select o.id,o.order_number,o.status,o.fulfillment_status,o.currency,
               sum(oi.line_total_minor)::bigint producer_total_minor,o.placed_at,o.created_at
        from public.order_items oi join public.orders o on o.id=oi.order_id
        where oi.producer_id=producer_row.id
        group by o.id,o.order_number,o.status,o.fulfillment_status,o.currency,o.placed_at,o.created_at
        order by o.created_at desc limit 10
      ) x
    ), '[]'::jsonb)
  ) into commerce;

  return base || jsonb_build_object('commerce', commerce);
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_my_producer_finance_summary_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  producer_row public.producers%rowtype;
  summaries jsonb;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if; if not private.has_permission('finance.read') then raise exception 'permission_required:finance.read' using errcode='42501'; end if;
  select * into producer_row from public.producers producer
  where producer.owner_user_id=caller_id and producer.deleted_at is null
  order by producer.created_at desc limit 1;
  if producer_row.id is null then raise exception 'producer_profile_required' using errcode='42501'; end if;

  select coalesce(jsonb_agg(private.get_producer_balance_v1(producer_row.id,currency_code) order by currency_code),'[]'::jsonb)
  into summaries
  from (
    select distinct currency as currency_code from private.producer_ledger_entries where producer_id=producer_row.id
    union
    select distinct currency as currency_code from private.producer_payouts where producer_id=producer_row.id
  ) currencies;

  return jsonb_build_object(
    'producerId',producer_row.id,
    'displayName',producer_row.display_name,
    'commissionBasisPoints',producer_row.commission_basis_points,
    'balances',summaries
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_my_producer_location_change_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  producer_id_value uuid;
  request public.producer_location_change_requests%rowtype;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select producer.id into producer_id_value from public.producers producer where producer.owner_user_id=caller_id and producer.deleted_at is null order by producer.created_at desc limit 1;
  if producer_id_value is null then raise exception 'producer_profile_not_found' using errcode='P0002'; end if;
  select r.* into request from public.producer_location_change_requests r where r.producer_id=producer_id_value order by r.created_at desc limit 1;
  if request.id is null then return null; end if;
  return jsonb_build_object(
    'id',request.id,'status',request.status,'countryCode',request.country_code,'province',request.province,
    'district',request.district,'village',request.village,'villageIsCustom',request.village_is_custom,
    'reason',request.reason,'reviewReason',request.review_reason,'createdAt',request.created_at,'reviewedAt',request.reviewed_at
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_my_producer_order_detail_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  producer_id_value uuid;
  target public.orders%rowtype;
  result jsonb;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if; if not private.has_permission('order.read') then raise exception 'permission_required:order.read' using errcode='42501'; end if;
  select p.id into producer_id_value from public.producers p
  where p.owner_user_id=caller_id and p.status='active' and p.is_verified=true and p.deleted_at is null
  order by p.created_at desc limit 1;
  if producer_id_value is null then raise exception 'verified_active_producer_required' using errcode='42501'; end if;

  select * into target from public.orders o
  where o.id=p_order_id
    and o.payment_status in ('paid','partially_refunded','refunded')
    and exists(select 1 from public.order_items oi where oi.order_id=o.id and oi.producer_id=producer_id_value);
  if target.id is null then raise exception 'producer_order_not_found' using errcode='P0002'; end if;

  select jsonb_build_object(
    'id',target.id,
    'orderNumber',target.order_number,
    'status',target.status,
    'paymentStatus',target.payment_status,
    'fulfillmentStatus',target.fulfillment_status,
    'currency',target.currency,
    'producerSubtotalMinor',(select coalesce(sum(oi.line_total_minor),0)::bigint from public.order_items oi where oi.order_id=target.id and oi.producer_id=producer_id_value),
    'placedAt',target.placed_at,
    'shipping',jsonb_build_object(
      'recipientName',coalesce(target.shipping_address->>'recipient_name',target.shipping_address->>'recipientName'),
      'phone',target.shipping_address->>'phone',
      'countryCode',coalesce(target.shipping_address->>'country_code',target.shipping_address->>'countryCode'),
      'province',target.shipping_address->>'province',
      'district',target.shipping_address->>'district',
      'neighborhood',target.shipping_address->>'neighborhood',
      'addressLine',coalesce(target.shipping_address->>'address_line',target.shipping_address->>'addressLine'),
      'postalCode',coalesce(target.shipping_address->>'postal_code',target.shipping_address->>'postalCode'),
      'deliveryNotes',coalesce(target.shipping_address->>'delivery_notes',target.shipping_address->>'deliveryNotes')
    ),
    'items',coalesce((select jsonb_agg(jsonb_build_object(
      'id',oi.id,'productId',oi.product_id,'variantId',oi.variant_id,'productName',oi.product_name,'variantName',oi.variant_name,'sku',oi.sku,
      'imagePath',oi.image_path,'quantity',oi.quantity,'unitPriceMinor',oi.unit_price_minor,'lineTotalMinor',oi.line_total_minor,
      'fulfillmentStatus',oi.fulfillment_status,
      'shippedQuantity',coalesce((select sum(si.quantity)::integer from public.shipment_items si where si.order_item_id=oi.id),0),
      'remainingToShip',greatest(0,oi.quantity-coalesce((select sum(si.quantity)::integer from public.shipment_items si where si.order_item_id=oi.id),0))
    ) order by oi.created_at) from public.order_items oi where oi.order_id=target.id and oi.producer_id=producer_id_value),'[]'::jsonb),
    'shipments',coalesce((select jsonb_agg(jsonb_build_object(
      'id',s.id,'carrier',s.carrier,'trackingNumber',s.tracking_number,'trackingUrl',s.tracking_url,'status',s.status,
      'shippedAt',s.shipped_at,'estimatedDeliveryAt',s.estimated_delivery_at,'deliveredAt',s.delivered_at,
      'items',coalesce((select jsonb_agg(jsonb_build_object('orderItemId',si.order_item_id,'quantity',si.quantity) order by si.order_item_id)
        from public.shipment_items si join public.order_items oi2 on oi2.id=si.order_item_id
        where si.shipment_id=s.id and oi2.producer_id=producer_id_value),'[]'::jsonb)
    ) order by s.created_at desc)
      from public.shipments s
      where s.order_id=target.id and exists(select 1 from public.shipment_items si join public.order_items oi on oi.id=si.order_item_id where si.shipment_id=s.id and oi.producer_id=producer_id_value)),'[]'::jsonb),
    'canFulfill',target.payment_status='paid' and target.status in ('confirmed','preparing','partially_shipped') and exists(
      select 1 from public.order_items oi where oi.order_id=target.id and oi.producer_id=producer_id_value and oi.fulfillment_status not in ('fulfilled','cancelled','returned')
      and oi.quantity>coalesce((select sum(si.quantity)::integer from public.shipment_items si where si.order_item_id=oi.id),0)
    )
  ) into result;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_my_producer_payment_identity_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); p public.producers%rowtype; app public.producer_applications%rowtype; kyc private.producer_application_kyc%rowtype; account private.producer_payment_accounts%rowtype; iban_value text; holder_value text; source text;
begin
 if uid is null then raise exception 'authentication_required' using errcode='42501'; end if; if not private.has_permission('finance.read') then raise exception 'permission_required:finance.read' using errcode='42501'; end if;
 select * into p from public.producers where owner_user_id=uid and deleted_at is null order by created_at desc limit 1;
 if p.id is null then raise exception 'producer_not_found' using errcode='P0002'; end if;
 if p.status not in('active','suspended') or not p.is_verified then raise exception 'verified_producer_required' using errcode='42501'; end if;
 if p.application_id is null then raise exception 'producer_application_required' using errcode='55000'; end if;
 select * into app from public.producer_applications where id=p.application_id and applicant_user_id=uid and status='approved';
 if app.id is null then raise exception 'producer_application_not_approved' using errcode='55000'; end if;
 select * into kyc from private.producer_application_kyc where application_id=app.id;
 if kyc.application_id is null then raise exception 'producer_kyc_missing' using errcode='55000'; end if;
 iban_value:=private.decrypt_producer_kyc(kyc.iban_ciphertext); holder_value:=nullif(btrim(coalesce(kyc.bank_account_holder,'')),''); source:='approved_application';
 if not private.is_valid_tr_iban_v1(iban_value) or holder_value is null then raise exception 'producer_bank_identity_incomplete' using errcode='55000'; end if;
 select * into account from private.producer_payment_accounts where producer_id=p.id;
 insert into private.sensitive_access_log(actor_user_id,resource_type,resource_id,purpose) values(uid,'producer_own_bank_identity',p.id,'Satıcı kendi ödeme hesabını finans ekranında görüntüledi.');
 return jsonb_build_object('producerId',p.id,'bankAccountHolder',holder_value,'iban',upper(regexp_replace(iban_value,'[^A-Za-z0-9]','','g')),'kycSource',source,'provider',coalesce(account.provider,'iyzico'),'paymentAccountStatus',coalesce(account.status,'pending_configuration'),'ready',account.status='ready' and account.submerchant_key is not null,'updatedAt',kyc.updated_at);
end;$function$;

CREATE OR REPLACE FUNCTION private.get_my_producer_payment_onboarding_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  uid uuid:=auth.uid();
  p public.producers%rowtype;
  account private.producer_payment_accounts%rowtype;
  app public.producer_applications%rowtype;
  app_kyc private.producer_application_kyc%rowtype;
  source text:='missing';
  legal_name_present boolean:=false;
  national_id_present boolean:=false;
  tax_number_present boolean:=false;
  tax_office_present boolean:=false;
  iban_present boolean:=false;
  holder_present boolean:=false;
  phone_present boolean:=false;
  email_present boolean:=false;
  address_present boolean:=false;
  consent_present boolean:=false;
  source_updated_at timestamptz;
  type_ready boolean:=false;
begin
  if uid is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into p from public.producers where owner_user_id=uid and deleted_at is null order by created_at desc limit 1;
  if p.id is null then raise exception 'producer_not_found' using errcode='P0002'; end if;
  if not p.is_verified or p.status not in('active','suspended') then raise exception 'verified_producer_required' using errcode='42501'; end if;
  select * into account from private.producer_payment_accounts where producer_id=p.id;

  if p.application_id is not null then
    select * into app from public.producer_applications where id=p.application_id and applicant_user_id=uid and status='approved';
    if app.id is not null then
      select * into app_kyc from private.producer_application_kyc where application_id=app.id;
      if app_kyc.application_id is not null then
        source:='approved_application';
        legal_name_present:=nullif(btrim(coalesce(app_kyc.legal_name,'')),'') is not null;
        national_id_present:=nullif(btrim(coalesce(app_kyc.national_id_ciphertext,'')),'') is not null;
        tax_number_present:=nullif(btrim(coalesce(app_kyc.tax_number_ciphertext,'')),'') is not null;
        tax_office_present:=nullif(btrim(coalesce(app_kyc.tax_office,'')),'') is not null;
        iban_present:=nullif(btrim(coalesce(app_kyc.iban_ciphertext,'')),'') is not null;
        holder_present:=nullif(btrim(coalesce(app_kyc.bank_account_holder,'')),'') is not null;
        phone_present:=private.normalize_tr_phone_v1(app_kyc.phone) is not null;
        email_present:=coalesce(app_kyc.contact_email,'') ~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$';
        address_present:=char_length(coalesce(private.producer_payment_address_text_v1(app_kyc.address),''))>=10;
        consent_present:=nullif(btrim(coalesce(app_kyc.consent_version,'')),'') is not null and app_kyc.consented_at is not null;
        source_updated_at:=app_kyc.updated_at;
      end if;
    end if;
  end if;

  type_ready:=case account.provider_submerchant_type
    when 'PERSONAL' then legal_name_present and national_id_present and iban_present and holder_present and phone_present and email_present and address_present and consent_present
    when 'PRIVATE_COMPANY' then legal_name_present and national_id_present and tax_office_present and iban_present and holder_present and phone_present and email_present and address_present and consent_present
    when 'LIMITED_OR_JOINT_STOCK_COMPANY' then legal_name_present and tax_number_present and tax_office_present and iban_present and holder_present and phone_present and email_present and address_present and consent_present
    else false
  end;

  return jsonb_build_object(
    'producerId',p.id,'producerName',p.display_name,'producerStatus',p.status,'producerVerified',p.is_verified,
    'applicationLinked',p.application_id is not null,'kycSource',source,'legacyKycEditable',false,
    'kyc',jsonb_build_object('legalNamePresent',legal_name_present,'nationalIdPresent',national_id_present,'taxNumberPresent',tax_number_present,'taxOfficePresent',tax_office_present,'ibanPresent',iban_present,'bankAccountHolderPresent',holder_present,'phonePresent',phone_present,'contactEmailPresent',email_present,'addressPresent',address_present,'consentPresent',consent_present,'updatedAt',source_updated_at),
    'paymentAccount',jsonb_build_object('provider','iyzico','providerSubmerchantType',account.provider_submerchant_type,'status',coalesce(account.status,'pending_configuration'),'typeConfigured',account.provider_submerchant_type is not null,'ready',account.status='ready' and account.submerchant_key is not null,'kycCompleteForConfiguredType',type_ready)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_my_producer_profile_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); producer public.producers%rowtype; badge_active boolean;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  perform private.assert_platform_access_v1(caller_id);
  select * into producer from public.producers where owner_user_id=caller_id and deleted_at is null order by created_at desc limit 1;
  if not found then raise exception 'producer_profile_not_found' using errcode='P0002'; end if;
  badge_active:=private.is_producer_trust_badge_active_v1(producer.id);
  return jsonb_build_object(
    'id',producer.id,'display_name',producer.display_name,'description',producer.description,'story',producer.story,
    'production_location',producer.production_location,'production_country_code',producer.production_country_code,
    'production_province',producer.production_province,'production_district',producer.production_district,
    'production_village',producer.production_village,'production_village_is_custom',producer.production_village_is_custom,
    'logo_path',producer.logo_path,'cover_path',producer.cover_path,'status',producer.status,'is_verified',producer.is_verified,
    'origin_verified',producer.origin_verified,'activity_types',producer.activity_types,
    'approved_category_slugs',producer.approved_category_slugs,
    'approved_categories',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'slug',c.slug,'name',c.name) order by c.sort_order,c.name) from public.categories c where c.is_active=true and c.slug=any(producer.approved_category_slugs)),'[]'::jsonb),
    'verified_at',producer.verified_at,'verification_due_at',producer.verification_due_at,
    'trust_badge_status',producer.trust_badge_status,'trust_badge_active',badge_active,
    'trust_badge_granted_at',producer.trust_badge_granted_at,'trust_badge_review_due_at',producer.trust_badge_review_due_at,
    'trust_badge_revoked_at',producer.trust_badge_revoked_at,'trust_badge_reason',producer.trust_badge_reason,
    'rating_average',producer.rating_average,'rating_count',producer.rating_count,
    'product_count',(select count(*) from public.products product where product.producer_id=producer.id and product.deleted_at is null),
    'published_product_count',(select count(*) from public.products product where product.producer_id=producer.id and product.status='published' and product.is_active=true and product.deleted_at is null),
    'order_count',(select count(distinct item.order_id) from public.order_items item where item.producer_id=producer.id),
    'customer_count',(select count(distinct customer_order.user_id) from public.order_items item join public.orders customer_order on customer_order.id=item.order_id where item.producer_id=producer.id and customer_order.status not in ('draft','cancelled'))
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_my_product_batch_editor_v1(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  batch_row public.product_batches%rowtype;
  product_row public.products%rowtype;
  result jsonb;
begin
  if caller_id is null then
    raise exception 'authentication_required' using errcode='42501';
  end if;

  select b.* into batch_row
  from public.product_batches b
  join public.producers producer on producer.id=b.producer_id
  where b.id=p_batch_id
    and producer.owner_user_id=caller_id
    and producer.deleted_at is null;

  if batch_row.id is null then
    raise exception 'batch_not_found_or_access_denied' using errcode='42501';
  end if;

  select * into product_row from public.products where id=batch_row.product_id;

  select jsonb_build_object(
    'id',batch_row.id,
    'traceCode',batch_row.trace_code,
    'batchCode',batch_row.batch_code,
    'status',batch_row.status,
    'productId',batch_row.product_id,
    'productSlug',product_row.slug,
    'productName',product_row.name,
    'variantId',batch_row.variant_id,
    'harvestDate',batch_row.harvest_date,
    'productionDate',batch_row.production_date,
    'packagingDate',batch_row.packaging_date,
    'bestBeforeDate',batch_row.best_before_date,
    'origin',jsonb_build_object(
      'countryCode',batch_row.origin_country_code,
      'province',batch_row.origin_province,
      'district',batch_row.origin_district,
      'village',batch_row.origin_village,
      'latitude',batch_row.origin_latitude,
      'longitude',batch_row.origin_longitude
    ),
    'productionMethod',batch_row.production_method,
    'initialQuantity',batch_row.initial_quantity,
    'quantityUnit',batch_row.quantity_unit,
    'publicNotes',batch_row.public_notes,
    'reviewReason',batch_row.review_reason,
    'submittedAt',batch_row.submitted_at,
    'reviewedAt',batch_row.reviewed_at,
    'releasedAt',batch_row.released_at,
    'createdAt',batch_row.created_at,
    'updatedAt',batch_row.updated_at,
    'events',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',e.id,
        'eventType',e.event_type,
        'eventAt',e.event_at,
        'locationLabel',e.location_label,
        'publicNote',e.public_note,
        'visibility',e.visibility,
        'createdAt',e.created_at
      ) order by e.event_at,e.id)
      from public.product_batch_events e
      where e.batch_id=batch_row.id
    ),'[]'::jsonb),
    'certifications',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',c.id,
        'type',c.certificate_type,
        'issuer',c.issuer,
        'certificateNumber',c.certificate_number,
        'issuedAt',c.issued_at,
        'expiresAt',c.expires_at,
        'status',c.status,
        'linked',exists(
          select 1 from public.product_batch_certifications bc
          where bc.batch_id=batch_row.id and bc.certification_id=c.id
        )
      ) order by c.certificate_type,c.issuer)
      from public.product_certifications c
      where c.product_id=batch_row.product_id
        and c.status='valid'
        and (c.expires_at is null or c.expires_at>=current_date)
    ),'[]'::jsonb)
  ) into result;

  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_my_product_health_editor_v1(p_product_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); product_row public.products%rowtype; producer_row public.producers%rowtype; entry public.content_entries%rowtype; pending private.product_health_change_requests%rowtype;
begin
 if uid is null then raise exception 'authentication_required' using errcode='42501'; end if;
 select * into product_row from public.products where id=p_product_id and deleted_at is null; if product_row.id is null then raise exception 'product_not_found' using errcode='P0002'; end if;
 select * into producer_row from public.producers where id=product_row.producer_id and deleted_at is null; if producer_row.owner_user_id is distinct from uid then raise exception 'producer_product_owner_required' using errcode='42501'; end if;
 select * into entry from public.content_entries where related_product_id=p_product_id and content_type='product_health' and locale='tr' and status='published' and deleted_at is null order by updated_at desc limit 1;
 select * into pending from private.product_health_change_requests where product_id=p_product_id and locale='tr' and proposed_by=uid and status='pending' order by updated_at desc limit 1;
 return jsonb_build_object('productId',product_row.id,'productName',product_row.name,'productStatus',product_row.status,'canEdit',producer_row.status='active' and producer_row.is_verified,
   'published',case when entry.id is null then null else jsonb_build_object('contentId',entry.id,'summary',entry.summary,'productInfo',coalesce(entry.metadata->'productInfoV1','{}'::jsonb),'safety',coalesce(entry.metadata->'safetyV2','{}'::jsonb),'recipe',coalesce(entry.metadata->'recipeV1','{}'::jsonb),'updatedAt',entry.updated_at) end,
   'pending',case when pending.id is null then null else jsonb_build_object('requestId',pending.id,'payload',pending.payload,'status',pending.status,'updatedAt',pending.updated_at) end);
end;$function$;

CREATE OR REPLACE FUNCTION private.get_my_return_detail_v1(p_return_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  request_row public.return_requests%rowtype;
  result jsonb;
begin
  if caller_id is null then
    raise exception 'authentication_required' using errcode='42501';
  end if;

  select * into request_row
  from public.return_requests request
  where request.id = p_return_id and request.user_id = caller_id;

  if request_row.id is null then
    raise exception 'return_not_found' using errcode='P0002';
  end if;

  select jsonb_build_object(
    'id',request_row.id,
    'returnNumber',request_row.return_number,
    'orderId',request_row.order_id,
    'reasonCode',request_row.reason_code,
    'customerMessage',request_row.customer_message,
    'status',request_row.status,
    'resolution',request_row.resolution,
    'resolutionNote',request_row.resolution_note,
    'reviewReason',request_row.review_reason,
    'requestedAt',request_row.requested_at,
    'reviewedAt',request_row.reviewed_at,
    'receivedAt',request_row.received_at,
    'closedAt',request_row.closed_at,
    'items',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',return_item.id,
        'orderItemId',return_item.order_item_id,
        'productName',order_item.product_name,
        'variantName',order_item.variant_name,
        'quantity',return_item.quantity,
        'purchasedQuantity',order_item.quantity,
        'condition',return_item.condition,
        'evidencePaths',to_jsonb(return_item.evidence_paths),
        'refundAmountMinor',return_item.refund_amount_minor,
        'currency',customer_order.currency
      ) order by return_item.created_at)
      from public.return_items return_item
      join public.order_items order_item on order_item.id=return_item.order_item_id
      join public.orders customer_order on customer_order.id=order_item.order_id
      where return_item.return_id=request_row.id
    ),'[]'::jsonb),
    'refunds',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',refund.id,
        'amountMinor',refund.amount_minor,
        'currency',refund.currency,
        'status',refund.status,
        'reason',refund.reason,
        'processedAt',refund.processed_at
      ) order by refund.created_at desc)
      from public.refunds refund
      where refund.return_id=request_row.id
    ),'[]'::jsonb)
  ) into result;

  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_my_terms_acceptance_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); accepted_row private.user_terms_acceptances%rowtype;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into accepted_row from private.user_terms_acceptances where user_id=caller_id;
  return jsonb_build_object(
    'accepted', accepted_row.user_id is not null and accepted_row.terms_version='2026-08-22-store-v1',
    'termsVersion','2026-08-22-store-v1',
    'acceptedAt',case when accepted_row.terms_version='2026-08-22-store-v1' then accepted_row.accepted_at else null end
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_or_create_customer_cart_v1(p_user_id uuid)
 RETURNS carts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare cart_row public.carts%rowtype;
begin
  if p_user_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended('cart:'||p_user_id::text,85031));

  update public.carts
  set status='abandoned',updated_at=timezone('utc',now())
  where user_id=p_user_id and status='active' and expires_at is not null and expires_at<=timezone('utc',now());

  select * into cart_row from public.carts where user_id=p_user_id and status='active' for update;
  if cart_row.id is null then
    insert into public.carts(user_id,status,currency,expires_at)
    values(p_user_id,'active','TRY',timezone('utc',now())+interval '30 days')
    returning * into cart_row;
  end if;
  return cart_row;
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_payment_intent_for_service_v1(p_intent_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare intent private.payment_intents%rowtype; o public.orders%rowtype; r public.event_reservations%rowtype; f private.event_reservation_finance%rowtype; e public.events%rowtype; price_minor bigint;
begin
 if p_intent_id is null then raise exception 'payment_intent_required' using errcode='22023'; end if;
 select * into intent from private.payment_intents where id=p_intent_id;
 if intent.id is null then raise exception 'payment_intent_not_found' using errcode='P0002'; end if;
 if intent.subject_type='order' then select * into o from public.orders where id=intent.order_id; if o.id is null then raise exception 'order_not_found' using errcode='P0002'; end if; select coalesce(sum(oi.line_total_minor),0)::bigint into price_minor from public.order_items oi where oi.order_id=o.id; return jsonb_build_object('intentId',intent.id,'subjectType','order','subjectId',o.id,'userId',intent.user_id,'provider',intent.provider,'intentStatus',intent.status,'providerReference',intent.provider_reference,'amountMinor',intent.amount_minor,'priceMinor',price_minor,'currency',intent.currency,'orderId',o.id,'orderNumber',o.order_number,'orderStatus',o.status,'paymentStatus',o.payment_status); end if;
 if intent.subject_type='event_reservation' then select * into r from public.event_reservations where id=intent.subject_id; select * into f from private.event_reservation_finance where reservation_id=intent.subject_id; select * into e from public.events where id=r.event_id; if r.id is null or f.reservation_id is null or e.id is null then raise exception 'event_payment_context_not_found' using errcode='P0002'; end if; return jsonb_build_object('intentId',intent.id,'subjectType','event_reservation','subjectId',r.id,'userId',intent.user_id,'provider',intent.provider,'intentStatus',intent.status,'providerReference',intent.provider_reference,'amountMinor',intent.amount_minor,'priceMinor',f.total_minor,'currency',intent.currency,'reservationId',r.id,'reservationCode',r.reservation_code,'eventId',e.id,'eventTitle',e.title,'paymentStatus',f.payment_status,'paymentExpiresAt',f.payment_expires_at); end if;
 raise exception 'unsupported_payment_subject_type' using errcode='55000';
end;$function$;

CREATE OR REPLACE FUNCTION private.get_producer_balance_v1(p_producer_id uuid, p_currency text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare currency_code text:=upper(btrim(coalesce(p_currency,''))); pending_net bigint:=0; available_ledger bigint:=0; reserved_payout bigint:=0; paid_payout bigint:=0; provider_processing bigint:=0; manual_requested bigint:=0; available_to_payout bigint:=0;
begin
  if currency_code !~ '^[A-Z]{3}$' then raise exception 'invalid_currency' using errcode='22023'; end if;
  select coalesce(sum(case when availability_status='pending' then producer_net_minor else 0 end),0)::bigint,coalesce(sum(case when availability_status='available' then producer_net_minor else 0 end),0)::bigint
  into pending_net,available_ledger from private.producer_ledger_entries where producer_id=p_producer_id and currency=currency_code;
  select coalesce(sum(amount_minor) filter(where status in('requested','scheduled','processing')),0)::bigint,
         coalesce(sum(amount_minor) filter(where status='paid'),0)::bigint,
         coalesce(sum(amount_minor) filter(where channel='provider_marketplace' and status='processing'),0)::bigint,
         coalesce(sum(amount_minor) filter(where channel='manual_bank_transfer' and status in('requested','scheduled','processing')),0)::bigint
  into reserved_payout,paid_payout,provider_processing,manual_requested
  from private.producer_payouts where producer_id=p_producer_id and currency=currency_code;
  available_to_payout:=greatest(available_ledger-reserved_payout-paid_payout,0);
  return jsonb_build_object('producerId',p_producer_id,'currency',currency_code,'pendingMinor',pending_net,'availableLedgerMinor',available_ledger,'reservedPayoutMinor',reserved_payout,'paidPayoutMinor',paid_payout,'providerTransferProcessingMinor',provider_processing,'manualWithdrawalPendingMinor',manual_requested,'availableToPayoutMinor',available_to_payout,'lifetimeNetMinor',pending_net+available_ledger);
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_producer_bank_destination_v1(p_producer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.producers%rowtype; k private.producer_application_kyc%rowtype; iban_value text; holder_value text;
begin
  select * into p from public.producers where id=p_producer_id and deleted_at is null;
  if p.id is null then raise exception 'producer_not_found' using errcode='P0002'; end if;
  if p.application_id is null then raise exception 'producer_application_required' using errcode='55000'; end if;
  select * into k from private.producer_application_kyc where application_id=p.application_id;
  if k.application_id is null then raise exception 'producer_kyc_missing' using errcode='55000'; end if;
  iban_value:=private.decrypt_producer_kyc(k.iban_ciphertext);
  holder_value:=nullif(btrim(coalesce(k.bank_account_holder,'')),'');
  if not private.is_valid_tr_iban_v1(iban_value) or holder_value is null then raise exception 'producer_bank_identity_incomplete' using errcode='55000'; end if;
  return jsonb_build_object('applicationId',p.application_id,'iban',upper(regexp_replace(iban_value,'[^A-Za-z0-9]','','g')),'ibanMasked',private.mask_tr_iban_v1(iban_value),'accountHolder',holder_value,'ibanCiphertext',k.iban_ciphertext);
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_product_availability_subscription_v1(p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  product_id uuid:=private.resolve_product_id_v1(p_reference);
  active_value boolean:=false;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if product_id is null or not exists(select 1 from public.products p where p.id=product_id and p.status='published' and p.is_active=true and p.deleted_at is null) then
    raise exception 'product_not_available' using errcode='P0002';
  end if;
  select coalesce(s.active,false) into active_value
  from public.product_availability_subscriptions s
  where s.user_id=caller_id and s.product_id=product_id;
  return jsonb_build_object('active',coalesce(active_value,false),'authenticated',true,'productId',product_id);
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_product_editorial_editor_v1(p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid(); product_id uuid:=private.resolve_product_id_v1(p_reference); product_row public.products%rowtype; producer_row public.producers%rowtype; entry public.content_entries%rowtype; draft private.product_editorial_drafts%rowtype; published_payload jsonb; safety jsonb; warning_texts jsonb;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if product_id is null then raise exception 'product_not_found' using errcode='P0002'; end if;
  select * into product_row from public.products p where p.id=product_id and p.deleted_at is null;
  select * into producer_row from public.producers p where p.id=product_row.producer_id and p.deleted_at is null;
  if not coalesce(private.has_permission('product.read'),false) and producer_row.owner_user_id is distinct from caller_id then raise exception 'product_access_denied' using errcode='42501'; end if;
  select * into entry from public.content_entries ce where ce.related_product_id=product_id and ce.content_type='product_health' and ce.locale='tr' and ce.deleted_at is null order by ce.updated_at desc limit 1;
  if entry.id is not null and jsonb_typeof(entry.metadata->'editorialV1')='object' then published_payload:=entry.metadata->'editorialV1';
  elsif entry.id is not null then
    safety:=case when jsonb_typeof(entry.metadata->'safetyV2')='object' then entry.metadata->'safetyV2' else '{}'::jsonb end;
    select coalesce(jsonb_agg(to_jsonb(item->>'text')) filter(where nullif(btrim(item->>'text'),'') is not null),'[]'::jsonb) into warning_texts from jsonb_array_elements(case when jsonb_typeof(safety->'warnings')='array' then safety->'warnings' else '[]'::jsonb end) item;
    published_payload:=jsonb_build_object('title',entry.title,'summary',entry.summary,'productInfo',jsonb_build_object('ingredients',coalesce(entry.metadata->'productInfoV1'->'ingredients','[]'::jsonb),'nutrition',coalesce(entry.metadata->'productInfoV1'->'nutrition','{}'::jsonb),'usageNotes',coalesce(entry.metadata->'productInfoV1'->'usageNotes','[]'::jsonb)),'safety',jsonb_build_object('storage',coalesce(safety->'storage'->'items','[]'::jsonb),'preparation',coalesce(safety->'preparation'->'items','[]'::jsonb),'warnings',warning_texts,'allergens',coalesce(safety->'allergens'->'known','[]'::jsonb),'allergenNote',coalesce(safety->'allergens'->>'text','')),'recipe',coalesce(entry.metadata->'recipeV1',jsonb_build_object('enabled',false,'ingredients','[]'::jsonb,'steps','[]'::jsonb)));
  else
    published_payload:=jsonb_build_object('title',product_row.name||' | Saklama ve Kullanım','summary','','productInfo',jsonb_build_object('ingredients','[]'::jsonb,'nutrition','{}'::jsonb,'usageNotes','[]'::jsonb),'safety',jsonb_build_object('storage','[]'::jsonb,'preparation','[]'::jsonb,'warnings','[]'::jsonb,'allergens','[]'::jsonb,'allergenNote',''),'recipe',jsonb_build_object('enabled',false,'ingredients','[]'::jsonb,'steps','[]'::jsonb));
  end if;
  select * into draft from private.product_editorial_drafts d where d.product_id=product_id and d.locale='tr';
  return jsonb_build_object('productId',product_row.id,'productName',product_row.name,'producerId',product_row.producer_id,'storeKind',producer_row.store_kind,'canPublish',coalesce(private.has_permission('product.read'),false),'published',published_payload,'draft',case when draft.id is null then null else jsonb_build_object('id',draft.id,'status',draft.status,'payload',draft.payload,'reviewNote',draft.review_note,'updatedAt',draft.updated_at) end,'videoPath',private.verified_product_video_path_v1(product_row.specifications->>'video'));
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_product_reviews_v1(p_product_id uuid, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; summary jsonb; caller_id uuid:=auth.uid();
begin
  if p_limit not between 1 and 50 or p_offset<0 then raise exception 'invalid_pagination' using errcode='22023'; end if;
  select jsonb_build_object('count',count(*),'averageRating',coalesce(round(avg(rating)::numeric,2),0),'rating1',count(*) filter(where rating=1),'rating2',count(*) filter(where rating=2),'rating3',count(*) filter(where rating=3),'rating4',count(*) filter(where rating=4),'rating5',count(*) filter(where rating=5)) into summary
  from public.reviews review where review.product_id=p_product_id and review.status='published' and (caller_id is null or not exists(select 1 from private.user_blocks b where b.blocker_user_id=caller_id and b.blocked_user_id=review.user_id and b.removed_at is null));
  select coalesce(jsonb_agg(item order by created_at desc),'[]'::jsonb) into result from (
    select jsonb_build_object('id',review.id,'rating',review.rating,'title',review.title,'body',review.body,'mediaPaths',review.media_paths,'verifiedPurchase',review.is_verified_purchase,'createdAt',review.created_at,'editedAt',review.edited_at,'reviewerName',case when position(' ' in profile.display_name)>0 then split_part(profile.display_name,' ',1)||' '||left(split_part(profile.display_name,' ',2),1)||'.' else profile.display_name end,'merchantReply',review.merchant_reply,'merchantRepliedAt',review.merchant_replied_at,'helpfulCount',(select count(*) from private.review_helpful_votes vote where vote.review_id=review.id),'helpfulByMe',exists(select 1 from private.review_helpful_votes vote where vote.review_id=review.id and vote.user_id=auth.uid())) as item,review.created_at
    from public.reviews review join public.profiles profile on profile.id=review.user_id where review.product_id=p_product_id and review.status='published' and (caller_id is null or not exists(select 1 from private.user_blocks b where b.blocker_user_id=caller_id and b.blocked_user_id=review.user_id and b.removed_at is null)) order by review.created_at desc limit p_limit offset p_offset
  ) rows;
  return jsonb_build_object('summary',summary,'items',result);
end; $function$;

CREATE OR REPLACE FUNCTION private.get_public_brand_appearance_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  raw jsonb;
  normalized jsonb;
begin
  select public_config->'appearance' into raw from public.brand_settings where slug='golden-oremar';
  if raw is null then
    raw := jsonb_build_object(
      'defaultTheme','custom',
      'colorScheme','light',
      'tokens',jsonb_build_object(
        'background','#F7F8F6','card','#FFFFFF','text','#14261C','muted','#52675C','border','#D7E0DA',
        'brandGold','#8A6810','brandGreen','#145A32','brandEarth','#7A431F','onGold','#FFFFFF','onGreen','#FFFFFF'
      )
    );
  end if;
  normalized := private.normalize_brand_appearance_v1(raw);
  return normalized;
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_contact_config_v1()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'address',nullif(btrim(coalesce(settings.public_config#>>'{contactInfo,address}','')),''),
    'mapUrl',nullif(btrim(coalesce(settings.public_config#>>'{contactInfo,mapUrl}','')),''),
    'email',nullif(btrim(coalesce(settings.public_config#>>'{contactInfo,email}','')),''),
    'phone',nullif(btrim(coalesce(settings.public_config#>>'{contactInfo,phone}','')),''),
    'whatsapp',nullif(btrim(coalesce(settings.public_config#>>'{contactInfo,whatsapp}','')),''),
    'social',coalesce(settings.public_config#>'{contactInfo,social}','{}'::jsonb),
    'supportChannelsReady',
      nullif(btrim(coalesce(settings.public_config#>>'{contactInfo,email}','')),'') is not null
      or nullif(btrim(coalesce(settings.public_config#>>'{contactInfo,phone}','')),'') is not null
      or nullif(btrim(coalesce(settings.public_config#>>'{contactInfo,whatsapp}','')),'') is not null
  )
  from public.brand_settings settings
  where settings.slug='golden-oremar';
$function$;

CREATE OR REPLACE FUNCTION private.get_public_content_entry_v1(p_reference text, p_locale text DEFAULT 'tr'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  locale_value text:=lower(btrim(coalesce(p_locale,'tr')));
  entry public.content_entries%rowtype;
  result jsonb;
begin
  if char_length(btrim(coalesce(p_reference,''))) not between 1 and 240 then raise exception 'invalid_content_reference' using errcode='22023'; end if;
  if locale_value not in ('tr','en','de','fr','ku','ar') then raise exception 'invalid_locale' using errcode='22023'; end if;
  select item.* into entry
  from public.content_entries item
  where (item.id::text=btrim(p_reference) or item.legacy_id=btrim(p_reference) or item.slug=btrim(p_reference))
    and item.locale=locale_value and item.status='published' and item.deleted_at is null
    and (item.published_at is null or item.published_at<=timezone('utc',now()))
  order by case when item.id::text=btrim(p_reference) then 0 when item.slug=btrim(p_reference) then 1 else 2 end
  limit 1;
  if entry.id is null then raise exception 'content_not_found' using errcode='P0002'; end if;

  select jsonb_build_object(
    'id',entry.id,'legacyId',entry.legacy_id,'type',entry.content_type,'slug',entry.slug,
    'title',entry.title,'summary',entry.summary,'markdown',entry.body_markdown,
    'sanitizedHtml',entry.body_html_sanitized,'heroImagePath',entry.hero_image_path,
    'tags',entry.tags,'publishedAt',entry.published_at,
    'category',nullif(btrim(coalesce(entry.metadata->>'originalCategory','')),''),
    'relatedProduct',case when product.id is null then null else jsonb_build_object(
      'id',product.id,'slug',product.slug,'name',product.name,'origin',product.origin,
      'imagePath',(select image.storage_path from public.product_images image where image.product_id=product.id order by image.is_primary desc,image.sort_order,image.created_at limit 1)
    ) end
  ) into result
  from (select 1) anchor
  left join public.products product on product.id=entry.related_product_id
    and product.status='published' and product.is_active=true and product.deleted_at is null
    and exists(select 1 from public.producers producer where producer.id=product.producer_id and producer.status='active' and producer.is_verified=true and producer.deleted_at is null);
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_content_entry_v2(p_reference text, p_locale text DEFAULT 'tr'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  base jsonb;
  safety jsonb;
  entry_id uuid;
begin
  base:=private.get_public_content_entry_v1(p_reference,p_locale);
  entry_id:=(base->>'id')::uuid;
  select coalesce(metadata->'safetyV2','{}'::jsonb)
    into safety
  from public.content_entries
  where id=entry_id;
  return base || jsonb_build_object('safety',coalesce(safety,'{}'::jsonb));
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_content_entry_v3(p_reference text, p_locale text DEFAULT 'tr'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  base jsonb:=private.get_public_content_entry_v2(p_reference,p_locale);
  verified_path text;
begin
  verified_path:=private.verified_public_storage_path_v1('content-public',base->>'heroImagePath');
  return jsonb_set(base,'{heroImagePath}',coalesce(to_jsonb(verified_path),'null'::jsonb),true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_home_catalog_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
  select jsonb_build_object(
    'items',coalesce(jsonb_agg(jsonb_build_object(
      'id',product.id,
      'legacyId',product.legacy_id,
      'slug',product.slug,
      'name',product.name,
      'shortDescription',product.short_description,
      'origin',product.origin,
      'unitLabel',product.unit_label,
      'currency',product.currency,
      'stockMode',product.stock_mode,
      'featured',product.is_featured,
      'homeSection',case
        when nullif(product.specifications->>'homeSection','') in ('natural','seasonal','best_sellers','new_arrivals','offers','concierge','regular')
          then product.specifications->>'homeSection'
        when product.stock_mode='preorder' then 'pre_order'
        when product.is_featured then 'featured'
        else 'regular'
      end,
      'category',jsonb_build_object('id',category.id,'slug',category.slug,'name',category.name),
      'producer',jsonb_build_object('id',producer.id,'name',producer.display_name),
      'variant',jsonb_build_object(
        'id',variant.id,'name',variant.name,'sku',variant.sku,'priceMinor',variant.price_minor,
        'compareAtPriceMinor',variant.compare_at_price_minor,'weightGrams',variant.weight_grams
      ),
      'availableQuantity',case when product.stock_mode in ('tracked','seasonal') then greatest(0,coalesce(inventory.available_quantity,0)-coalesce(inventory.reserved_quantity,0)) else null end,
      'imagePath',image.storage_path,
      'averageRating',coalesce(review_stats.average_rating,0),
      'reviewCount',coalesce(review_stats.review_count,0)
    ) order by product.is_featured desc,product.published_at desc nulls last,product.name),'[]'::jsonb),
    'generatedAt',timezone('utc',now())
  ) into result
  from public.products product
  join public.producers producer on producer.id=product.producer_id
    and producer.status='active' and producer.is_verified=true and producer.deleted_at is null
  join public.categories category on category.id=product.category_id and category.is_active=true
  join lateral(
    select v.* from public.product_variants v
    where v.product_id=product.id and v.is_active=true
    order by v.is_default desc,v.created_at asc limit 1
  ) variant on true
  left join public.product_inventory inventory on inventory.variant_id=variant.id
  left join lateral(
    select pi.storage_path from public.product_images pi
    where pi.product_id=product.id
    order by pi.is_primary desc,pi.sort_order asc,pi.created_at asc limit 1
  ) image on true
  left join lateral(
    select round(avg(r.rating)::numeric,2) average_rating,count(*)::bigint review_count
    from public.reviews r where r.product_id=product.id and r.status='published'
  ) review_stats on true
  where product.status='published' and product.is_active=true and product.deleted_at is null;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_home_catalog_v2()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  base jsonb:=private.get_public_home_catalog_v1();
  items jsonb;
begin
  select coalesce(jsonb_agg(
    case when resolved.path is null
      then jsonb_set(item,'{imagePath}','null'::jsonb,true)
      else jsonb_set(item,'{imagePath}',to_jsonb(resolved.path),true)
    end
  ),'[]'::jsonb) into items
  from jsonb_array_elements(coalesce(base->'items','[]'::jsonb)) item
  cross join lateral (
    select private.catalog_public_card_image_path_v1(
      item->>'imagePath',
      nullif(item#>>'{producer,id}','')::uuid
    ) path
  ) resolved;
  return jsonb_set(base,'{items}',items,true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_home_catalog_v3()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ select private.decorate_catalog_handling_v1(private.get_public_home_catalog_v2()); $function$;

CREATE OR REPLACE FUNCTION private.get_public_home_experience_v1(p_locale text DEFAULT 'tr'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  requested_locale text:=lower(split_part(btrim(coalesce(p_locale,'tr')),'-',1));
  config jsonb;
  category_rows jsonb;
  section_config jsonb;
  projection jsonb;
  sections jsonb:='[]'::jsonb;
  primary_assigned boolean:=false;
  campaign jsonb;
  now_utc timestamptz:=timezone('utc',now());
begin
  if requested_locale not in ('tr','en','de','fr','ku','ar') then requested_locale:='tr'; end if;
  config:=private.get_public_storefront_config_v1(requested_locale);
  category_rows:=private.list_public_categories_v3();

  for section_config in select value from jsonb_array_elements(coalesce(config->'homeSections','[]'::jsonb)) loop
    projection:=private.home_section_projection_v1(section_config,requested_locale);
    if projection is null then continue; end if;
    if primary_assigned=false then
      sections:=sections||jsonb_build_array(projection||jsonb_build_object('deferred',false));
      primary_assigned:=true;
    else
      sections:=sections||jsonb_build_array((projection-'items')||jsonb_build_object('items','[]'::jsonb,'deferred',true));
    end if;
  end loop;

  select jsonb_build_object(
    'id',campaign_row.id,
    'slug',campaign_row.slug,
    'title',campaign_row.title,
    'description',campaign_row.description,
    'bannerPath',campaign_row.banner_path,
    'startsAt',campaign_row.starts_at,
    'endsAt',campaign_row.ends_at,
    'targetScope',campaign_row.target_scope,
    'targetIds',case campaign_row.target_scope
      when 'products' then coalesce((select jsonb_agg(link.product_id) from public.campaign_products link where link.campaign_id=campaign_row.id),'[]'::jsonb)
      when 'categories' then coalesce((select jsonb_agg(category.slug) from public.campaign_categories link join public.categories category on category.id=link.category_id where link.campaign_id=campaign_row.id and category.is_active=true),'[]'::jsonb)
      else '[]'::jsonb end
  ) into campaign
  from public.campaigns campaign_row
  where campaign_row.status='active'
    and now_utc>=campaign_row.starts_at
    and now_utc<campaign_row.ends_at
  order by campaign_row.starts_at desc,campaign_row.id
  limit 1;

  return jsonb_build_object(
    'version',2,
    'locale',requested_locale,
    'generatedAt',now_utc,
    'updatedAt',config->>'updatedAt',
    'cacheKey','home:'||requested_locale||':'||coalesce(config->>'updatedAt','0'),
    'cachePolicy',jsonb_build_object(
      'compositionMaxAgeSeconds',60,
      'categoriesMaxAgeSeconds',300,
      'productProjectionMaxAgeSeconds',30
    ),
    'brand',config->'brand',
    'interface',config->'interface',
    'search',jsonb_build_object('enabled',true,'voiceEnabled',true),
    'categories',category_rows,
    'categoryOrder',coalesce(config->'heroCategories','[]'::jsonb),
    'sections',sections,
    'campaign',campaign,
    'eventSpotlight',config->'eventSpotlight',
    'salesReadiness',config->'salesReadiness'
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_home_section_v1(p_key text, p_locale text DEFAULT 'tr'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  requested_key text:=btrim(coalesce(p_key,''));
  requested_locale text:=lower(split_part(btrim(coalesce(p_locale,'tr')),'-',1));
  settings public.brand_settings%rowtype;
  section jsonb;
begin
  if requested_key='' or char_length(requested_key)>80 then raise exception 'invalid_home_section_key' using errcode='22023'; end if;
  if requested_locale not in ('tr','en','de','fr','ku','ar') then requested_locale:='tr'; end if;
  select * into settings from public.brand_settings where slug='golden-oremar';
  if not found then raise exception 'storefront_configuration_missing' using errcode='P0002'; end if;
  select value into section
  from jsonb_array_elements(coalesce(settings.public_config->'homeSections','[]'::jsonb))
  where value->>'id'=requested_key
  limit 1;
  if section is null then return null; end if;
  return private.home_section_projection_v1(section,requested_locale);
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_producer_follow_metrics_v1(p_producer_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); requested_count integer:=coalesce(cardinality(p_producer_ids),0); ids uuid[]:=array[]::uuid[]; result jsonb;
begin
  if requested_count=0 then return '[]'::jsonb; end if;
  if requested_count>100 then raise exception 'too_many_producer_ids' using errcode='22023'; end if;
  select coalesce(array_agg(distinct value),array[]::uuid[]) into ids from unnest(p_producer_ids) value where value is not null;
  select coalesce(jsonb_agg(jsonb_build_object('producerId',p.id,'followerCount',coalesce(follow_stats.follower_count,0),'following',case when caller_id is null then false else exists(select 1 from private.producer_follows mine where mine.user_id=caller_id and mine.producer_id=p.id) end,'verified',case when p.store_kind='official' then true else private.is_producer_trust_badge_active_v1(p.id) end,'originVerified',p.origin_verified and (p.store_kind='official' or private.is_producer_trust_badge_active_v1(p.id)),'storeKind',p.store_kind,'badgeTone',case when p.store_kind='official' then 'ruby' else 'blue' end,'storefrontTier',p.storefront_tier) order by case when p.store_kind='official' then 0 else 1 end,p.display_name,p.id),'[]'::jsonb) into result
  from public.producers p left join lateral(select count(*)::bigint follower_count from private.producer_follows all_follows where all_follows.producer_id=p.id) follow_stats on true
  where p.id=any(ids) and p.status='active' and p.is_verified=true and p.deleted_at is null;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_producer_profile_v1(p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ref text:=btrim(coalesce(p_reference,'')); producer public.producers%rowtype; result jsonb; badge_active boolean;
begin
  if char_length(ref) not between 1 and 160 then raise exception 'invalid_producer_reference' using errcode='22023'; end if;
  select * into producer from public.producers p where p.status='active' and p.is_verified=true and p.deleted_at is null and (p.id::text=ref or p.slug=lower(ref)) limit 1;
  if producer.id is null then raise exception 'producer_not_found' using errcode='P0002'; end if;
  badge_active:=private.is_producer_trust_badge_active_v1(producer.id);
  select jsonb_build_object(
    'id',producer.id,'slug',producer.slug,'display_name',producer.display_name,'description',producer.description,'story',producer.story,
    'logo_path',producer.logo_path,'cover_path',producer.cover_path,'rating_average',producer.rating_average,'rating_count',producer.rating_count,
    'activity_types',producer.activity_types,'verified_badge_active',badge_active,'location_label',producer.production_location,
    'location',jsonb_build_object('country_code',producer.production_country_code,'province',producer.production_province,'district',producer.production_district,'village',producer.production_village),
    'badges',jsonb_build_array(
      jsonb_build_object('key','verified_producer','label','Golden Oremar Doğrulanmış Üretici','active',badge_active),
      jsonb_build_object('key','verified_origin','label','Menşe ve üretim yeri doğrulandı','active',producer.origin_verified and badge_active)
    ),
    'product_count',(select count(*) from public.products p where p.producer_id=producer.id and p.status='published' and p.is_active=true and p.deleted_at is null),
    'products',coalesce((select jsonb_agg(jsonb_build_object('id',q.id,'slug',q.slug,'name',q.name,'short_description',q.short_description,'origin',q.origin,'unit_label',q.unit_label,'currency',q.currency,'featured',q.is_featured,'variant_id',q.variant_id,'variant_name',q.variant_name,'price_minor',q.price_minor,'compare_at_price_minor',q.compare_at_price_minor,'weight_grams',q.weight_grams,'image_path',q.image_path,'stock_mode',q.stock_mode,'available_quantity',q.available_quantity,'available',q.available) order by q.is_featured desc,q.published_at desc nulls last,q.name)
      from (select p.id,p.slug,p.name,p.short_description,p.origin,p.unit_label,p.currency,p.is_featured,p.stock_mode,p.published_at,v.id variant_id,v.name variant_name,v.price_minor,v.compare_at_price_minor,v.weight_grams,
        case when p.stock_mode in ('tracked','seasonal') then greatest(0,coalesce(inv.available_quantity,0)-coalesce(inv.reserved_quantity,0)) else null end available_quantity,
        case when p.stock_mode in ('tracked','seasonal') then inv.variant_id is not null and greatest(0,inv.available_quantity-inv.reserved_quantity)>0 else true end available,
        (select i.storage_path from public.product_images i where i.product_id=p.id order by i.is_primary desc,i.sort_order,i.created_at limit 1) image_path
        from public.products p join lateral(select pv.* from public.product_variants pv where pv.product_id=p.id and pv.is_active=true order by pv.is_default desc,pv.created_at limit 1)v on true
        left join public.product_inventory inv on inv.variant_id=v.id where p.producer_id=producer.id and p.status='published' and p.is_active=true and p.deleted_at is null order by p.is_featured desc,p.published_at desc nulls last,p.name limit 12)q),'[]'::jsonb)
  ) into result;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_producer_profile_v2(p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  base jsonb;
  target_producer_id uuid;
  follower_count bigint := 0;
  is_following boolean := false;
  enriched_products jsonb := '[]'::jsonb;
begin
  base := private.get_public_producer_profile_v1(p_reference);
  target_producer_id := (base->>'id')::uuid;

  select count(*)::bigint
    into follower_count
  from private.producer_follows f
  where f.producer_id=target_producer_id;

  if caller_id is not null then
    select exists(
      select 1 from private.producer_follows f
      where f.user_id=caller_id and f.producer_id=target_producer_id
    ) into is_following;
  end if;

  select coalesce(jsonb_agg(
    product_item || jsonb_build_object(
      'average_rating', coalesce(review_stats.average_rating, 0),
      'review_count', coalesce(review_stats.review_count, 0)
    ) order by ordinality
  ), '[]'::jsonb)
  into enriched_products
  from jsonb_array_elements(coalesce(base->'products','[]'::jsonb)) with ordinality as products(product_item, ordinality)
  left join lateral (
    select
      coalesce(round(avg(r.rating)::numeric,2),0) as average_rating,
      count(*)::bigint as review_count
    from public.reviews r
    where r.product_id=(product_item->>'id')::uuid
      and r.status='published'
  ) review_stats on true;

  return (base - 'products') || jsonb_build_object(
    'follower_count', follower_count,
    'following', is_following,
    'products', enriched_products
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_producer_profile_v3(p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  base jsonb:=private.get_public_producer_profile_v2(p_reference);
  products jsonb;
  logo_path text;
  cover_path text;
begin
  select coalesce(jsonb_agg(
    jsonb_set(product_item,'{image_path}',coalesce(to_jsonb(private.verified_public_storage_path_v1('catalog-public',product_item->>'image_path')),'null'::jsonb),true)
    order by ordinality
  ),'[]'::jsonb) into products
  from jsonb_array_elements(coalesce(base->'products','[]'::jsonb)) with ordinality as rows(product_item,ordinality);
  base:=jsonb_set(base,'{products}',products,true);
  logo_path:=private.verified_public_storage_path_v1('catalog-public',base->>'logo_path');
  cover_path:=private.verified_public_storage_path_v1('catalog-public',base->>'cover_path');
  base:=jsonb_set(base,'{logo_path}',coalesce(to_jsonb(logo_path),'null'::jsonb),true);
  base:=jsonb_set(base,'{cover_path}',coalesce(to_jsonb(cover_path),'null'::jsonb),true);
  return base;
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_producer_profile_v4(p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  base jsonb:=private.get_public_producer_profile_v3(p_reference);
  v_producer_id uuid;
  producer_row public.producers%rowtype;
  badge_active boolean;
  badges jsonb;
  categories jsonb;
  real_followers bigint:=0;
begin
  begin v_producer_id:=(base->>'id')::uuid; exception when others then raise exception 'producer_profile_invalid' using errcode='55000'; end;
  select * into producer_row from public.producers p where p.id=v_producer_id and p.status='active' and p.is_verified=true and p.deleted_at is null;
  if producer_row.id is null then raise exception 'producer_not_found' using errcode='P0002'; end if;
  badge_active:=private.is_producer_trust_badge_active_v1(v_producer_id);
  select count(*)::bigint into real_followers from private.producer_follows f where f.producer_id=v_producer_id;

  if producer_row.store_kind='official' then
    badges:=jsonb_build_array(
      jsonb_build_object('key','official_store','label','Golden Oremar Resmi Mağazası','active',true,'tone','emerald'),
      jsonb_build_object('key','verified_origin','label','Menşe doğrulandı','active',producer_row.origin_verified,'tone','emerald')
    );
  else
    badges:=jsonb_build_array(
      jsonb_build_object('key','verified_producer','label','Golden Oremar Doğrulanmış Üretici','active',badge_active,'tone','blue'),
      jsonb_build_object('key','verified_origin','label','Menşe ve üretim yeri doğrulandı','active',producer_row.origin_verified and badge_active,'tone','blue')
    );
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('slug',x.slug,'name',x.name,'productCount',x.product_count) order by x.product_count desc,x.name),'[]'::jsonb)
  into categories
  from (
    select c.slug,c.name,count(*)::bigint product_count
    from public.products p join public.categories c on c.id=p.category_id
    where p.producer_id=v_producer_id and p.status='published' and p.is_active=true and p.deleted_at is null and c.is_active=true
    group by c.slug,c.name
    order by count(*) desc,c.name
    limit 16
  ) x;

  return (base-'badges') || jsonb_build_object(
    'store_kind',producer_row.store_kind,
    'storefront_tier',producer_row.storefront_tier,
    'storefront_theme',producer_row.storefront_theme,
    'storefront_headline',producer_row.storefront_headline,
    'storefront_subheadline',producer_row.storefront_subheadline,
    'badges',badges,
    'categories',categories,
    'follower_count',real_followers,
    'social_proof',jsonb_build_object(
      'realFollowerCount',real_followers,
      'launchAudience',jsonb_build_object('count',producer_row.launch_audience_count,'label',producer_row.launch_audience_label,'kind','promotional_audience')
    )
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_producer_profile_v5(p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare base jsonb:=private.get_public_producer_profile_v4(p_reference); badges jsonb;
begin
  if base->>'store_kind'='official' then
    select coalesce(jsonb_agg(case when item->>'key' in ('official_store','verified_origin') then jsonb_set(item,'{tone}',to_jsonb('ruby'::text),true) else item end order by ordinality),'[]'::jsonb) into badges from jsonb_array_elements(coalesce(base->'badges','[]'::jsonb)) with ordinality rows(item,ordinality);
    base:=jsonb_set(base,'{badges}',badges,true);
  end if;
  return base;
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_product_detail_v1(p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ref text:=btrim(coalesce(p_reference,'')); product public.products%rowtype; producer public.producers%rowtype; category public.categories%rowtype; result jsonb; badge_active boolean;
begin
  if char_length(ref) not between 1 and 200 then raise exception 'invalid_product_reference' using errcode='22023'; end if;
  select p.* into product from public.products p join public.producers pr on pr.id=p.producer_id
  where (p.id::text=ref or p.legacy_id=ref or p.slug=lower(ref)) and p.status='published' and p.is_active=true and p.deleted_at is null and pr.status='active' and pr.is_verified=true and pr.deleted_at is null limit 1;
  if product.id is null then raise exception 'product_not_found' using errcode='P0002'; end if;
  select * into producer from public.producers where id=product.producer_id;select * into category from public.categories where id=product.category_id and is_active=true;badge_active:=private.is_producer_trust_badge_active_v1(producer.id);
  select jsonb_build_object(
    'id',product.id,'legacyId',product.legacy_id,'slug',product.slug,'name',product.name,'shortDescription',product.short_description,'description',product.description,'story',product.story,
    'origin',product.origin,'unitLabel',product.unit_label,'currency',product.currency,'stockMode',product.stock_mode,'preorderLeadDays',product.preorder_lead_days,'tags',product.tags,'features',product.features,
    'specifications',jsonb_strip_nulls(jsonb_build_object('cutOptions',case when jsonb_typeof(product.specifications->'cutOptions')='array' then product.specifications->'cutOptions' else null end,'preOrderTime',nullif(product.specifications->>'preOrderTime',''),'pricePrefix',nullif(product.specifications->>'pricePrefix',''),'video',nullif(product.specifications->>'video',''))),
    'translations',product.translations,'featured',product.is_featured,'category',jsonb_build_object('id',category.id,'slug',category.slug,'name',category.name),
    'producer',jsonb_build_object('id',producer.id,'slug',producer.slug,'name',producer.display_name,'description',producer.description,'story',producer.story,'logoPath',producer.logo_path,'coverPath',producer.cover_path,'ratingAverage',producer.rating_average,'ratingCount',producer.rating_count,'locationLabel',producer.production_location,'location',jsonb_build_object('countryCode',producer.production_country_code,'province',producer.production_province,'district',producer.production_district,'village',producer.production_village),'verified',badge_active,'originVerified',producer.origin_verified and badge_active),
    'trustBadges',jsonb_build_array(jsonb_build_object('key','verified_producer','label','Golden Oremar Doğrulanmış Üretici','active',badge_active),jsonb_build_object('key','verified_origin','label','Menşe ve üretim yeri doğrulandı','active',producer.origin_verified and badge_active),jsonb_build_object('key','batch_traceable','label','Lot/QR ile izlenebilir','active',exists(select 1 from public.product_batches b where b.product_id=product.id and b.status='released')),jsonb_build_object('key','certified_organic','label','Sertifikalı organik','active',exists(select 1 from public.product_certifications c where c.product_id=product.id and c.status='valid' and lower(c.certificate_type) in ('organic','organic_certificate','certified_organic') and (c.expires_at is null or c.expires_at>=current_date)))),
    'images',coalesce((select jsonb_agg(jsonb_build_object('path',i.storage_path,'alt',i.alt_text,'width',i.width,'height',i.height,'primary',i.is_primary) order by i.is_primary desc,i.sort_order,i.created_at) from public.product_images i where i.product_id=product.id),'[]'::jsonb),
    'variants',coalesce((select jsonb_agg(jsonb_build_object('id',v.id,'sku',v.sku,'name',v.name,'options',coalesce(v.option_values,'{}'::jsonb)-'legacyWeightOptions','priceMinor',v.price_minor,'compareAtPriceMinor',v.compare_at_price_minor,'weightGrams',v.weight_grams,'default',v.is_default,'availableQuantity',case when product.stock_mode in ('tracked','seasonal') then greatest(0,coalesce(inv.available_quantity,0)-coalesce(inv.reserved_quantity,0)) else null end,'available',case when product.stock_mode in ('tracked','seasonal') then greatest(0,coalesce(inv.available_quantity,0)-coalesce(inv.reserved_quantity,0))>0 else true end) order by v.is_default desc,v.created_at) from public.product_variants v left join public.product_inventory inv on inv.variant_id=v.id where v.product_id=product.id and v.is_active=true),'[]'::jsonb),
    'reviewSummary',(select jsonb_build_object('count',count(*),'averageRating',coalesce(round(avg(r.rating)::numeric,2),0),'rating1',count(*) filter(where r.rating=1),'rating2',count(*) filter(where r.rating=2),'rating3',count(*) filter(where r.rating=3),'rating4',count(*) filter(where r.rating=4),'rating5',count(*) filter(where r.rating=5)) from public.reviews r where r.product_id=product.id and r.status='published'),
    'certifications',coalesce((select jsonb_agg(jsonb_build_object('type',c.certificate_type,'issuer',c.issuer,'certificateNumber',c.certificate_number,'issuedAt',c.issued_at,'expiresAt',c.expires_at,'verificationUrl',c.verification_url,'status',c.status) order by c.certificate_type,c.issuer) from public.product_certifications c where c.product_id=product.id and c.status='valid' and (c.expires_at is null or c.expires_at>=current_date)),'[]'::jsonb),
    'traceability',jsonb_build_object('hasReleasedBatches',exists(select 1 from public.product_batches b where b.product_id=product.id and b.status='released'),'batches',coalesce((select jsonb_agg(jsonb_build_object('traceCode',b.trace_code,'batchCode',b.batch_code,'variantId',b.variant_id,'harvestDate',b.harvest_date,'productionDate',b.production_date,'packagingDate',b.packaging_date,'bestBeforeDate',b.best_before_date,'productionMethod',b.production_method,'publicNotes',b.public_notes,'origin',jsonb_build_object('countryCode',b.origin_country_code,'province',b.origin_province,'district',b.origin_district,'village',b.origin_village),'releasedAt',b.released_at) order by b.released_at desc,b.created_at desc) from public.product_batches b where b.product_id=product.id and b.status='released'),'[]'::jsonb)),
    'export',jsonb_build_object('status',product.export_status,'countryOfOriginCode',product.country_of_origin_code,'perishable',product.is_perishable,'requiresColdChain',product.requires_cold_chain,'shelfLifeDays',product.shelf_life_days)
  ) into result;return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_product_detail_v10(p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  base jsonb := private.get_public_product_detail_v9(p_reference);
  product_id uuid;
  raw_video text;
  store_kind text;
begin
  if base = '{}'::jsonb then return base; end if;
  begin
    product_id := (base->>'id')::uuid;
  exception when others then
    product_id := private.resolve_product_id_v1(p_reference);
  end;
  if product_id is null then return base; end if;

  select nullif(btrim(coalesce(p.specifications->>'video','')),''), pr.store_kind
    into raw_video, store_kind
  from public.products p
  join public.producers pr on pr.id = p.producer_id
  where p.id = product_id;

  if raw_video is null or char_length(raw_video) > 2000 then return base; end if;

  if private.is_youtube_video_url_v1(raw_video) then
    if store_kind = 'official' then
      return base || jsonb_build_object('video', jsonb_build_object('kind','youtube','url',raw_video));
    end if;
    return base;
  end if;

  if raw_video !~ '^[a-z]+:' and private.verified_product_video_path_v1(raw_video) is not null then
    return base || jsonb_build_object('video', jsonb_build_object('kind','file','path',raw_video,
      'url', private.media_public_url_v1('catalog-public', raw_video)));
  end if;

  return base;
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_product_detail_v2(p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  base jsonb:=private.get_public_product_detail_v1(p_reference);
  images jsonb;
  producer jsonb;
  logo_path text;
  cover_path text;
  v_product_id uuid;
  v_producer_id uuid;
  v_store_kind text:='independent';
  v_storefront_tier text:='standard';
  v_origin_verified boolean:=false;
  v_producer_verified boolean:=false;
  provenance jsonb;
  trust_badges jsonb;
begin
  select coalesce(jsonb_agg(
    jsonb_set(image,'{path}',to_jsonb(private.verified_public_storage_path_v1('catalog-public',image->>'path')),true)
    order by ordinality
  ) filter(where private.verified_public_storage_path_v1('catalog-public',image->>'path') is not null),'[]'::jsonb)
  into images
  from jsonb_array_elements(coalesce(base->'images','[]'::jsonb)) with ordinality as rows(image,ordinality);
  base:=jsonb_set(base,'{images}',images,true);

  producer:=coalesce(base->'producer','{}'::jsonb);
  logo_path:=private.verified_public_storage_path_v1('catalog-public',producer->>'logoPath');
  cover_path:=private.verified_public_storage_path_v1('catalog-public',producer->>'coverPath');
  producer:=jsonb_set(producer,'{logoPath}',coalesce(to_jsonb(logo_path),'null'::jsonb),true);
  producer:=jsonb_set(producer,'{coverPath}',coalesce(to_jsonb(cover_path),'null'::jsonb),true);

  begin v_product_id:=(base->>'id')::uuid; exception when others then v_product_id:=null; end;
  begin v_producer_id:=(producer->>'id')::uuid; exception when others then v_producer_id:=null; end;

  if v_producer_id is not null then
    select p.store_kind,p.storefront_tier,
           case when p.store_kind='official' then p.origin_verified else p.origin_verified and private.is_producer_trust_badge_active_v1(p.id) end,
           case when p.store_kind='official' then true else private.is_producer_trust_badge_active_v1(p.id) end
    into v_store_kind,v_storefront_tier,v_origin_verified,v_producer_verified
    from public.producers p
    where p.id=v_producer_id and p.status='active' and p.is_verified=true and p.deleted_at is null;
  end if;

  producer:=jsonb_set(producer,'{storeKind}',to_jsonb(coalesce(v_store_kind,'independent')),true);
  producer:=jsonb_set(producer,'{storefrontTier}',to_jsonb(coalesce(v_storefront_tier,'standard')),true);
  producer:=jsonb_set(producer,'{badgeTone}',to_jsonb(case when v_store_kind='official' then 'emerald' else 'blue' end),true);
  producer:=jsonb_set(producer,'{verified}',to_jsonb(coalesce(v_producer_verified,false)),true);
  producer:=jsonb_set(producer,'{originVerified}',to_jsonb(coalesce(v_origin_verified,false)),true);

  if v_product_id is not null then
    select jsonb_build_object(
      'sellerModel',pp.seller_model,
      'sourceMode',pp.source_mode,
      'sourceDisplayName',pp.source_display_name,
      'origin',jsonb_build_object(
        'countryCode',pp.country_code,
        'province',pp.province,
        'district',pp.district,
        'village',pp.village,
        'localityDetail',pp.locality_detail,
        'label',pp.origin_label
      ),
      'originVerified',pp.origin_verified,
      'organicClaim',pp.organic_claim,
      'publicNote',pp.public_note
    ) into provenance
    from public.product_provenance pp
    where pp.product_id=v_product_id;
  end if;

  if v_store_kind='official' then
    trust_badges:=jsonb_build_array(
      jsonb_build_object('key','official_store','label','Golden Oremar Resmi Mağazası','active',true,'tone','emerald'),
      jsonb_build_object('key','verified_origin','label','Menşe doğrulandı','active',coalesce((provenance->>'originVerified')::boolean,v_origin_verified,false),'tone','emerald'),
      jsonb_build_object('key','batch_traceable','label','Lot/QR ile izlenebilir','active',exists(select 1 from public.product_batches b where b.product_id=v_product_id and b.status='released'),'tone','gold'),
      jsonb_build_object('key','certified_organic','label','Sertifikalı organik','active',exists(select 1 from public.product_certifications c where c.product_id=v_product_id and c.status='valid' and lower(c.certificate_type) in ('organic','organic_certificate','certified_organic') and (c.expires_at is null or c.expires_at>=current_date)),'tone','emerald')
    );
  else
    trust_badges:=jsonb_build_array(
      jsonb_build_object('key','verified_producer','label','Golden Oremar Doğrulanmış Üretici','active',coalesce(v_producer_verified,false),'tone','blue'),
      jsonb_build_object('key','verified_origin','label','Menşe ve üretim yeri doğrulandı','active',coalesce((provenance->>'originVerified')::boolean,v_origin_verified,false),'tone','blue'),
      jsonb_build_object('key','batch_traceable','label','Lot/QR ile izlenebilir','active',exists(select 1 from public.product_batches b where b.product_id=v_product_id and b.status='released'),'tone','gold'),
      jsonb_build_object('key','certified_organic','label','Sertifikalı organik','active',exists(select 1 from public.product_certifications c where c.product_id=v_product_id and c.status='valid' and lower(c.certificate_type) in ('organic','organic_certificate','certified_organic') and (c.expires_at is null or c.expires_at>=current_date)),'tone','emerald')
    );
  end if;

  base:=jsonb_set(base,'{producer}',producer,true);
  base:=jsonb_set(base,'{trustBadges}',trust_badges,true);
  return jsonb_set(base,'{provenance}',coalesce(provenance,'null'::jsonb),true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_product_detail_v3(p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare base jsonb:=private.get_public_product_detail_v2(p_reference); specs jsonb; video_path text;
begin
  specs:=coalesce(base->'specifications','{}'::jsonb);
  video_path:=private.verified_product_video_path_v1(specs->>'video');
  specs:=jsonb_set(specs,'{video}',coalesce(to_jsonb(video_path),'null'::jsonb),true);
  return jsonb_set(base,'{specifications}',specs,true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_product_detail_v4(p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  base jsonb:=private.get_public_product_detail_v3(p_reference);
  producer_payload jsonb;
  provenance_payload jsonb;
  badges jsonb;
  official boolean:=false;
  certified boolean:=false;
begin
  if base='{}'::jsonb then return base; end if;
  producer_payload:=coalesce(base->'producer','{}'::jsonb);
  provenance_payload:=coalesce(base->'provenance','{}'::jsonb);
  official:=coalesce(producer_payload->>'storeKind','')='official';
  certified:=coalesce((provenance_payload->>'organicCertified')::boolean,false);
  if official then
    producer_payload:=jsonb_set(producer_payload,'{badgeTone}',to_jsonb('ruby'::text),true);
    select coalesce(jsonb_agg(case when item->>'key' in ('official_store','verified_origin') then jsonb_set(item,'{tone}',to_jsonb('ruby'::text),true) else item end order by ordinality),'[]'::jsonb)
      into badges
    from jsonb_array_elements(coalesce(producer_payload->'trustBadges','[]'::jsonb)) with ordinality rows(item,ordinality);
    producer_payload:=jsonb_set(producer_payload,'{trustBadges}',badges,true);
  end if;
  if coalesce(provenance_payload->>'organicClaim','')='certified_organic' and not certified then
    provenance_payload:=jsonb_set(provenance_payload,'{organicClaim}',to_jsonb('not_claimed'::text),true);
  end if;
  base:=jsonb_set(base,'{producer}',producer_payload,true);
  base:=jsonb_set(base,'{provenance}',provenance_payload,true);
  return base;
exception when invalid_text_representation then
  return base;
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_product_detail_v5(p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  base jsonb:=private.get_public_product_detail_v4(p_reference);
  badges jsonb;
  official boolean:=coalesce(base->'producer'->>'storeKind','')='official';
begin
  if base='{}'::jsonb or not official then return base; end if;
  select coalesce(jsonb_agg(
    case when item->>'key' in ('official_store','verified_origin')
      then jsonb_set(item,'{tone}',to_jsonb('ruby'::text),true)
      else item end
    order by ordinality
  ),'[]'::jsonb)
  into badges
  from jsonb_array_elements(coalesce(base->'trustBadges','[]'::jsonb)) with ordinality rows(item,ordinality);
  return jsonb_set(base,'{trustBadges}',badges,true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_product_detail_v6(p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  base jsonb:=private.get_public_product_detail_v5(p_reference);
  certifications jsonb;
begin
  if base='{}'::jsonb then return base; end if;
  select coalesce(jsonb_agg(
    (item - 'verificationUrl') || jsonb_build_object('verificationUrl',null)
    order by ordinality
  ),'[]'::jsonb)
  into certifications
  from jsonb_array_elements(coalesce(base->'certifications','[]'::jsonb)) with ordinality rows(item,ordinality);
  return jsonb_set(base,'{certifications}',certifications,true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_product_detail_v7(p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare base jsonb:=private.get_public_product_detail_v6(p_reference); profile jsonb;
begin
  if base='{}'::jsonb then return base; end if;
  profile:=private.product_handling_profile_v1((base->>'id')::uuid);
  return jsonb_set(base,'{handlingProfile}',coalesce(profile,'null'::jsonb),true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_product_detail_v8(p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  base jsonb:=private.get_public_product_detail_v7(p_reference);
  images jsonb;
  producer_id uuid;
  fallback_path text;
  product_name text;
begin
  if base='{}'::jsonb then return base; end if;
  images:=coalesce(base->'images','[]'::jsonb);
  if jsonb_typeof(images)='array' and jsonb_array_length(images)>0 then return base; end if;
  begin producer_id:=nullif(base#>>'{producer,id}','')::uuid; exception when others then producer_id:=null; end;
  fallback_path:=private.catalog_public_card_image_path_v1(null,producer_id);
  if fallback_path is null then return base; end if;
  product_name:=nullif(btrim(coalesce(base->>'name','')),'');
  images:=jsonb_build_array(jsonb_build_object(
    'path',fallback_path,
    'alt',coalesce(product_name||' · Golden Oremar resmi mağaza görseli','Golden Oremar resmi mağaza görseli'),
    'width',null,
    'height',null,
    'primary',true,
    'source','official_brand_fallback'
  ));
  return jsonb_set(base,'{images}',images,true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_product_detail_v9(p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare base jsonb:=private.get_public_product_detail_v8(p_reference); product_id uuid; commerce jsonb; has_confirmed_window boolean:=false; sales_state text; variants jsonb;
begin if base='{}'::jsonb then return base; end if; begin product_id:=(base->>'id')::uuid; exception when others then product_id:=private.resolve_product_id_v1(p_reference); end; if product_id is null then return base; end if; commerce:=private.product_commerce_payload_v1(product_id); if commerce is null then return base; end if; sales_state:=commerce#>>'{sales,state}'; has_confirmed_window:=coalesce((commerce#>>'{sales,confirmed}')::boolean,false); if has_confirmed_window and coalesce((commerce#>>'{preorder,enabled}')::boolean,false) and sales_state<>'preorder_open' then select coalesce(jsonb_agg(item||jsonb_build_object('available',false) order by ordinality),'[]'::jsonb) into variants from jsonb_array_elements(coalesce(base->'variants','[]'::jsonb)) with ordinality rows(item,ordinality); base:=jsonb_set(base,'{variants}',variants,true); end if; return jsonb_set(base,'{commerce}',commerce,true); end;$function$;

CREATE OR REPLACE FUNCTION private.get_public_product_handling_profiles_v1(p_product_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare safe_ids uuid[]; result jsonb;
begin
  safe_ids:=coalesce((select array_agg(distinct id) from unnest(coalesce(p_product_ids,'{}'::uuid[])) id),'{}'::uuid[]);
  if cardinality(safe_ids)>100 then raise exception 'too_many_product_ids' using errcode='22023'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'productId',p.id,
    'profile',private.product_handling_profile_v1(p.id)
  ) order by p.id),'[]'::jsonb)
  into result
  from public.products p
  join public.producers producer on producer.id=p.producer_id and producer.status='active' and producer.is_verified=true and producer.deleted_at is null
  where p.id=any(safe_ids) and p.status='published' and p.is_active=true and p.deleted_at is null;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_product_safety_v1(p_reference text, p_locale text DEFAULT 'tr'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  ref text:=btrim(coalesce(p_reference,''));
  locale_value text:=lower(btrim(coalesce(p_locale,'tr')));
  target_product_id uuid;
  entry public.content_entries%rowtype;
  raw_safety jsonb;
  warning_items jsonb;
  source_items jsonb;
  known_allergens jsonb;
  verification_items jsonb;
begin
  if char_length(ref) not between 1 and 240 then
    raise exception 'invalid_product_reference' using errcode='22023';
  end if;
  if locale_value not in ('tr','en','de','fr','ku','ar') then
    raise exception 'invalid_locale' using errcode='22023';
  end if;

  select p.id into target_product_id
  from public.products p
  where (p.id::text=ref or p.slug=lower(ref) or p.legacy_id=ref)
    and p.status='published' and p.is_active=true and p.deleted_at is null
    and exists(
      select 1 from public.producers producer
      where producer.id=p.producer_id
        and producer.status='active'
        and producer.is_verified=true
        and producer.deleted_at is null
    )
  order by case when p.id::text=ref then 0 when p.slug=lower(ref) then 1 else 2 end
  limit 1;

  if target_product_id is null then
    raise exception 'product_not_found' using errcode='P0002';
  end if;

  select ce.* into entry
  from public.content_entries ce
  where ce.related_product_id=target_product_id
    and ce.content_type='product_health'
    and ce.locale in (locale_value,'tr')
    and ce.status='published'
    and ce.deleted_at is null
    and (ce.published_at is null or ce.published_at<=timezone('utc',now()))
  order by case when ce.locale=locale_value then 0 else 1 end,
           ce.updated_at desc,
           ce.id
  limit 1;

  if entry.id is null then
    return '{}'::jsonb;
  end if;

  raw_safety:=case when jsonb_typeof(entry.metadata->'safetyV2')='object'
    then entry.metadata->'safetyV2' else '{}'::jsonb end;

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'code',nullif(btrim(item->>'code'),''),
    'severity',nullif(btrim(item->>'severity'),''),
    'text',nullif(btrim(item->>'text'),'')
  ))),'[]'::jsonb)
  into warning_items
  from jsonb_array_elements(case when jsonb_typeof(raw_safety->'warnings')='array' then raw_safety->'warnings' else '[]'::jsonb end) item
  where jsonb_typeof(item)='object'
    and nullif(btrim(item->>'text'),'') is not null;

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'authority',nullif(btrim(item->>'authority'),''),
    'title',nullif(btrim(item->>'title'),''),
    'topic',nullif(btrim(item->>'topic'),''),
    'url',case when coalesce(item->>'url','') ~* '^https://' then item->>'url' else null end,
    'accessedAt',nullif(btrim(item->>'accessedAt'),'')
  ))),'[]'::jsonb)
  into source_items
  from jsonb_array_elements(case when jsonb_typeof(raw_safety->'sources')='array' then raw_safety->'sources' else '[]'::jsonb end) item
  where jsonb_typeof(item)='object'
    and (nullif(btrim(item->>'authority'),'') is not null
      or nullif(btrim(item->>'title'),'') is not null
      or nullif(btrim(item->>'topic'),'') is not null
      or coalesce(item->>'url','') ~* '^https://');

  select coalesce(jsonb_agg(to_jsonb(value)),'[]'::jsonb)
  into known_allergens
  from jsonb_array_elements_text(case when jsonb_typeof(raw_safety->'allergens'->'known')='array' then raw_safety->'allergens'->'known' else '[]'::jsonb end) value
  where nullif(btrim(value),'') is not null;

  select coalesce(jsonb_agg(to_jsonb(value)),'[]'::jsonb)
  into verification_items
  from jsonb_array_elements_text(case when jsonb_typeof(raw_safety->'verificationNeeded')='array' then raw_safety->'verificationNeeded' else '[]'::jsonb end) value
  where nullif(btrim(value),'') is not null;

  return jsonb_build_object(
    'contentId',entry.id,
    'contentSlug',entry.slug,
    'title',entry.title,
    'summary',entry.summary,
    'locale',entry.locale,
    'safety',jsonb_strip_nulls(jsonb_build_object(
      'schemaVersion',case when jsonb_typeof(raw_safety->'schemaVersion')='number' then raw_safety->'schemaVersion' else null end,
      'guidanceKind',nullif(btrim(raw_safety->>'guidanceKind'),''),
      'safetyClass',nullif(btrim(raw_safety->>'safetyClass'),''),
      'storage',jsonb_build_object(
        'title',nullif(btrim(raw_safety->'storage'->>'title'),''),
        'items',case when jsonb_typeof(raw_safety->'storage'->'items')='array' then raw_safety->'storage'->'items' else '[]'::jsonb end
      ),
      'preparation',jsonb_build_object(
        'title',nullif(btrim(raw_safety->'preparation'->>'title'),''),
        'items',case when jsonb_typeof(raw_safety->'preparation'->'items')='array' then raw_safety->'preparation'->'items' else '[]'::jsonb end
      ),
      'warnings',warning_items,
      'allergens',jsonb_strip_nulls(jsonb_build_object(
        'known',known_allergens,
        'verifyLabel',case when jsonb_typeof(raw_safety->'allergens'->'verifyLabel')='boolean' then raw_safety->'allergens'->'verifyLabel' else null end,
        'text',nullif(btrim(raw_safety->'allergens'->>'text'),'')
      )),
      'verificationNeeded',verification_items,
      'claimPolicy',nullif(btrim(raw_safety->>'claimPolicy'),''),
      'sources',source_items
    )),
    'updatedAt',entry.updated_at
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_product_safety_v2(p_reference text, p_locale text DEFAULT 'tr'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare base jsonb:=private.get_public_product_safety_v1(p_reference,p_locale); entry_id uuid; meta jsonb;
begin
  if base='{}'::jsonb then return base; end if;
  begin entry_id:=(base->>'contentId')::uuid; exception when others then return base; end;
  select ce.metadata into meta from public.content_entries ce where ce.id=entry_id and ce.status='published' and ce.deleted_at is null;
  return base||jsonb_build_object('productInfo',case when jsonb_typeof(meta->'productInfoV1')='object' then meta->'productInfoV1' else '{}'::jsonb end,'recipe',case when jsonb_typeof(meta->'recipeV1')='object' then meta->'recipeV1' else '{}'::jsonb end);
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_product_safety_v3(p_reference text, p_locale text DEFAULT 'tr'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  base jsonb:=private.get_public_product_safety_v2(p_reference,p_locale);
  content_id uuid;
  product_id uuid;
  video_path text;
begin
  if base='{}'::jsonb then return base; end if;
  begin content_id:=(base->>'contentId')::uuid; exception when others then return base; end;
  select ce.related_product_id into product_id from public.content_entries ce where ce.id=content_id and ce.status='published' and ce.deleted_at is null;
  if product_id is not null then
    select private.verified_product_video_path_v1(p.specifications->>'video') into video_path from public.products p where p.id=product_id and p.status='published' and p.is_active=true and p.deleted_at is null;
  end if;
  base := jsonb_set(base,'{safety,videoPath}',coalesce(to_jsonb(video_path),'null'::jsonb),true);
  return jsonb_set(base,'{safety,videoUrl}',coalesce(to_jsonb(private.media_public_url_v1('catalog-public',video_path)),'null'::jsonb),true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_storefront_config_v1(p_locale text DEFAULT 'tr'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  locale_value text:=lower(btrim(coalesce(p_locale,'tr')));
  settings public.brand_settings%rowtype;
  interface_entry public.content_entries%rowtype;
  interface_payload jsonb:='{}'::jsonb;
  readiness jsonb;
begin
  if locale_value not in ('tr','en','de','fr','ku','ar') then locale_value:='tr'; end if;
  select * into settings from public.brand_settings where slug='golden-oremar';
  if settings.slug is null then raise exception 'brand_configuration_missing' using errcode='P0002'; end if;
  select entry.* into interface_entry from public.content_entries entry
  where entry.deleted_at is null and entry.status='published' and entry.legacy_source='repository-static-content-v1' and entry.legacy_id='interface' and entry.locale in (locale_value,'tr')
  order by case when entry.locale=locale_value then 0 else 1 end,entry.published_at desc nulls last,entry.updated_at desc limit 1;
  if interface_entry.id is not null then
    begin interface_payload:=interface_entry.body_markdown::jsonb; if jsonb_typeof(interface_payload)<>'object' then interface_payload:='{}'::jsonb; end if; exception when others then interface_payload:='{}'::jsonb; end;
  end if;
  readiness:=private.home_sales_readiness_v1();
  return jsonb_build_object(
    'brand',jsonb_build_object('slug',settings.slug,'name',settings.brand_name,'defaultLocale',settings.default_locale,'defaultCurrency',settings.default_currency),
    'interface',interface_payload,
    'heroCategories',coalesce(settings.public_config->'heroCategories','[]'::jsonb),
    'homeSections',coalesce(settings.public_config->'homeSections','[]'::jsonb),
    'eventSpotlight',coalesce(settings.public_config->'eventSpotlight','{}'::jsonb),
    'salesReadiness',readiness,
    'updatedAt',settings.updated_at
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_public_storefront_config_v2(p_locale text DEFAULT 'tr'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  base jsonb:=private.get_public_storefront_config_v1(p_locale);
  hero jsonb;
begin
  select coalesce(jsonb_agg(
    jsonb_set(item,'{image}',coalesce(to_jsonb(private.verified_public_storage_path_v1('catalog-public',item->>'image')),'null'::jsonb),true)
    order by ordinality
  ),'[]'::jsonb) into hero
  from jsonb_array_elements(coalesce(base->'heroCategories','[]'::jsonb)) with ordinality as rows(item,ordinality);
  return jsonb_set(base,'{heroCategories}',hero,true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_push_token_key_v1()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare key_value text;
begin
  select operational_config->>'pushTokenKey' into key_value from private.brand_secrets where brand_slug='golden-oremar';
  if char_length(coalesce(key_value,''))<32 then raise exception 'push_token_key_missing' using errcode='55000'; end if;
  return key_value;
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_store_branding_editor_v1(p_producer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); p public.producers%rowtype; can_edit boolean:=false;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into p from public.producers where id=p_producer_id and deleted_at is null;
  if p.id is null then raise exception 'producer_not_found' using errcode='P0002'; end if;
  if not (
    (p.store_kind<>'official' and p.owner_user_id=caller_id and p.status in ('pending','active','suspended'))
    or (p.store_kind='official' and coalesce(private.has_permission('product.publish'),false))
  ) then raise exception 'store_branding_access_required' using errcode='42501'; end if;
  can_edit:=private.store_branding_can_edit_v1(p.id);
  return jsonb_build_object(
    'producerId',p.id,'displayName',p.display_name,'storeKind',p.store_kind,'status',p.status,'verified',p.is_verified,
    'logoPath',p.logo_path,'coverPath',p.cover_path,'canEdit',can_edit,
    'logoBinaryVerified',private.catalog_media_binary_verified_path_v2(p.logo_path) is not null,
    'coverBinaryVerified',private.catalog_media_binary_verified_path_v2(p.cover_path) is not null
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_store_follow_simulation_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  allocated integer := 0;
  stores jsonb := '[]'::jsonb;
begin
  if auth.uid() is null or not private.has_permission('system.read') then
    raise exception 'super_admin_required' using errcode='42501';
  end if;

  select coalesce(sum(a.simulated_followers),0)::integer
    into allocated
  from private.store_follow_simulation_allocations a;

  select coalesce(jsonb_agg(jsonb_build_object(
    'producerId',p.id,
    'name',p.display_name,
    'storeKind',p.store_kind,
    'verified',p.is_verified,
    'realFollowerCount',coalesce(real_stats.follower_count,0),
    'simulatedFollowers',coalesce(a.simulated_followers,0),
    'updatedAt',a.updated_at
  ) order by case when p.store_kind='official' then 0 else 1 end,p.display_name,p.id),'[]'::jsonb)
    into stores
  from public.producers p
  left join private.store_follow_simulation_allocations a on a.producer_id=p.id
  left join lateral (
    select count(*)::bigint as follower_count
    from private.producer_follows f
    where f.producer_id=p.id
  ) real_stats on true
  where p.status='active' and p.is_verified=true and p.deleted_at is null;

  return jsonb_build_object(
    'poolCapacity',10000,
    'allocated',allocated,
    'available',greatest(0,10000-allocated),
    'publicMetricsIsolation',true,
    'stores',stores
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_storefront_setup_editor_v1(p_producer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  p public.producers%rowtype;
  kyc private.producer_application_kyc%rowtype;
  settings public.brand_settings%rowtype;
  identity jsonb:='{}'::jsonb;
  options jsonb:='[]'::jsonb;
  fallback_email text;
  fallback_phone text;
  fallback_line1 text;
  fallback_line2 text;
  fallback_postal text;
  fallback_city text;
  fallback_region text;
  fallback_country text;
begin
  if auth.uid() is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into p from public.producers where id=p_producer_id and deleted_at is null;
  if p.id is null then raise exception 'producer_not_found' using errcode='P0002'; end if;
  if not private.storefront_editor_authorized_v1(p.id) then raise exception 'storefront_editor_access_required' using errcode='42501'; end if;

  if p.store_kind='official' then
    select * into settings from public.brand_settings where slug='golden-oremar';
    identity:=coalesce(settings.public_config->'businessIdentity','{}'::jsonb);
    fallback_email:=settings.support_email;
    fallback_phone:=settings.support_phone;
    fallback_line1:=identity->>'registeredAddress';
    fallback_city:=p.production_district;
    fallback_region:=p.production_province;
    fallback_country:=coalesce(nullif(upper(identity->>'countryCode'),''),p.production_country_code);
  elsif p.application_id is not null then
    select * into kyc from private.producer_application_kyc where application_id=p.application_id;
    fallback_email:=kyc.contact_email;
    fallback_phone:=kyc.phone;
    fallback_line1:=coalesce(nullif(kyc.address->>'line1',''),nullif(kyc.address->>'addressLine1',''),nullif(kyc.address->>'street',''),nullif(kyc.address->>'fullAddress',''));
    fallback_line2:=coalesce(nullif(kyc.address->>'line2',''),nullif(kyc.address->>'addressLine2',''));
    fallback_postal:=coalesce(nullif(kyc.address->>'postalCode',''),nullif(kyc.address->>'postal_code',''));
    fallback_city:=coalesce(nullif(kyc.address->>'city',''),nullif(kyc.address->>'district',''),p.production_district);
    fallback_region:=coalesce(nullif(kyc.address->>'region',''),nullif(kyc.address->>'province',''),p.production_province);
    fallback_country:=upper(coalesce(nullif(kyc.address->>'countryCode',''),nullif(kyc.address->>'country_code',''),p.production_country_code));
  end if;
  options:=private.storefront_business_options_v1(p.id);

  return jsonb_build_object(
    'producerId',p.id,'storeKind',p.store_kind,'storefrontStatus',p.storefront_status,'publishedAt',p.storefront_published_at,
    'displayName',p.display_name,'description',p.description,'story',p.story,'headline',p.storefront_headline,'subheadline',p.storefront_subheadline,
    'logoPath',p.logo_path,'coverPath',p.cover_path,
    'contact',jsonb_build_object('email',coalesce(nullif(p.storefront_contact_email,''),fallback_email),'phone',coalesce(nullif(p.storefront_contact_phone,''),fallback_phone),'websiteUrl',p.storefront_website_url),
    'address',jsonb_build_object('line1',coalesce(nullif(p.storefront_address_line1,''),fallback_line1),'line2',coalesce(nullif(p.storefront_address_line2,''),fallback_line2),'postalCode',coalesce(nullif(p.storefront_postal_code,''),fallback_postal),'city',coalesce(nullif(p.storefront_city,''),fallback_city),'region',coalesce(nullif(p.storefront_region,''),fallback_region),'countryCode',coalesce(nullif(p.storefront_country_code,''),fallback_country),'visibility',p.storefront_address_visibility),
    'businessIdentity',jsonb_build_object('type',p.storefront_business_identity_type,'name',p.storefront_business_name,'reference',p.storefront_business_reference,'verifiedAt',p.storefront_business_verified_at),
    'businessOptions',options,
    'readiness',private.storefront_readiness_v1(p.id),
    'operations',jsonb_build_object('productsEnabled',p.storefront_status='published','ordersEnabled',p.storefront_status='published','returnsEnabled',p.storefront_status='published','paymentsEnabled',p.storefront_status='published')
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.guard_brand_public_config_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if jsonb_typeof(coalesce(new.public_config->'heroCategories','[]'::jsonb))<>'array' then
    raise exception 'invalid_hero_categories' using errcode='22023';
  end if;
  if exists(
    select 1
    from jsonb_array_elements(coalesce(new.public_config->'heroCategories','[]'::jsonb)) item
    where btrim(coalesce(item->>'image',''))<>''
      and (
        btrim(item->>'image') ~ '^/'
        or btrim(item->>'image') ~* '^[a-z][a-z0-9+.-]*:'
        or btrim(item->>'image') ~ '(^|/)\.\.?(/|$)'
        or position(E'\\' in btrim(item->>'image'))>0
      )
  ) then
    raise exception 'invalid_hero_category_image' using errcode='22023';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.guard_last_staff_totp_factor_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare recovery_until timestamptz;
begin
  if old.factor_type::text='totp' and old.status::text='verified'
     and private.user_requires_staff_mfa_v1(old.user_id)
     and coalesce((select s.state from private.staff_mfa_security_state s where s.user_id=old.user_id),'enrollment_required')='enforced'
     and not exists(select 1 from auth.mfa_factors f where f.user_id=old.user_id and f.id<>old.id and f.factor_type::text='totp' and f.status::text='verified') then
    select s.recovery_authorized_until into recovery_until from private.staff_mfa_security_state s where s.user_id=old.user_id;
    if recovery_until is null or recovery_until<=timezone('utc',now()) then raise exception 'last_verified_staff_totp_required' using errcode='42501'; end if;
  end if;
  return old;
end;
$function$;

CREATE OR REPLACE FUNCTION private.handle_new_auth_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  raw_name text;
  raw_phone text;
  raw_locale text;
begin
  raw_name := btrim(coalesce(
    nullif(new.raw_user_meta_data ->> 'display_name', ''),
    nullif(new.raw_user_meta_data ->> 'full_name', ''),
    nullif(new.raw_user_meta_data ->> 'name', ''),
    nullif(new.raw_user_meta_data ->> 'preferred_username', ''),
    nullif(split_part(coalesce(new.email, ''), '@', 1), ''),
    'Yeni Üye'
  ));
  raw_name := regexp_replace(raw_name, '[[:cntrl:]]', ' ', 'g');
  raw_name := regexp_replace(raw_name, '[[:space:]]+', ' ', 'g');
  raw_name := left(btrim(raw_name), 120);
  if char_length(raw_name) < 2 then
    raw_name := 'Yeni Üye';
  end if;

  raw_phone := nullif(btrim(coalesce(new.raw_user_meta_data ->> 'phone', '')), '');
  if raw_phone is not null then
    if char_length(raw_phone) > 40
       or raw_phone ~ '[[:cntrl:]]'
       or char_length(regexp_replace(raw_phone, '[^0-9]', '', 'g')) not between 7 and 20 then
      raw_phone := null;
    end if;
  end if;

  raw_locale := lower(split_part(replace(coalesce(new.raw_user_meta_data ->> 'locale', 'tr'), '_', '-'), '-', 1));
  if raw_locale not in ('tr','en','de','fr','ku','ar') then
    raw_locale := 'tr';
  end if;

  insert into public.profiles(id, display_name, phone, locale)
  values (new.id, raw_name, raw_phone, raw_locale)
  on conflict (id) do nothing;

  insert into private.user_roles(user_id, role)
  values (new.id, 'customer')
  on conflict (user_id, role) do nothing;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.has_permission(p_permission_key text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select private.user_has_permission_v1((select auth.uid()),p_permission_key)
    and (
      not private.user_requires_staff_mfa_v1((select auth.uid()))
      or p_permission_key='mfa.self_manage'
      or (
        private.staff_mfa_state_v1((select auth.uid()))='enforced'
        and private.user_has_verified_totp_factor_v1((select auth.uid()))
        and private.current_authenticator_assurance_level_v1()='aal2'
      )
    );
$function$;

CREATE OR REPLACE FUNCTION private.has_role(required_role text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists(
    select 1 from private.user_roles ur join public.profiles p on p.id=ur.user_id
    where ur.user_id=(select auth.uid()) and ur.role=required_role
      and (ur.expires_at is null or ur.expires_at>timezone('utc',now()))
      and p.status='active' and p.deleted_at is null
      and not coalesce((private.platform_access_block_v1(ur.user_id)->>'blocked')::boolean,false)
  );
$function$;

CREATE OR REPLACE FUNCTION private.hash_coupon_code_v1(p_code text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  normalized text := private.normalize_coupon_code_v1(p_code);
  pepper text;
begin
  select secret.operational_config->>'couponPepper'
  into pepper
  from private.brand_secrets secret
  where secret.brand_slug='golden-oremar';

  if char_length(coalesce(pepper,'')) < 32 then
    raise exception 'coupon_secret_missing' using errcode='55000';
  end if;

  return encode(
    extensions.hmac(
      convert_to(normalized,'UTF8'),
      convert_to(pepper,'UTF8'),
      'sha256'
    ),
    'hex'
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.hash_marketing_token_v1(p_token text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare pepper text; token_value text:=btrim(coalesce(p_token,''));
begin
  if char_length(token_value) not between 20 and 200 then raise exception 'invalid_marketing_token' using errcode='22023'; end if;
  select operational_config->>'marketingTokenPepper' into pepper from private.brand_secrets where brand_slug='golden-oremar';
  if char_length(coalesce(pepper,''))<32 then raise exception 'marketing_token_secret_missing' using errcode='55000'; end if;
  return encode(extensions.hmac(convert_to(token_value,'UTF8'),convert_to(pepper,'UTF8'),'sha256'),'hex');
end;
$function$;

CREATE OR REPLACE FUNCTION private.hash_push_token_v1(p_token text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare token_value text:=btrim(coalesce(p_token,''));
begin
  if char_length(token_value) not between 20 and 4096 then raise exception 'invalid_push_token' using errcode='22023'; end if;
  return encode(extensions.hmac(convert_to(token_value,'UTF8'),convert_to(private.get_push_token_key_v1(),'UTF8'),'sha256'),'hex');
end;
$function$;

CREATE OR REPLACE FUNCTION private.home_sales_readiness_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  legal jsonb:=private.commercial_checkout_legal_readiness_v1();
  payment jsonb:=private.get_checkout_payment_readiness_v3();
  legal_ready boolean:=coalesce((legal->>'ready')::boolean,false);
  live_payments boolean:=coalesce((payment->>'liveCardPaymentsEnabled')::boolean,false);
  provider_configuration_required boolean:=coalesce((payment->>'requiresProviderConfiguration')::boolean,true);
begin
  if not legal_ready then
    return jsonb_build_object(
      'status','blocked_pending_business_identity',
      'message','Katalog görüntülenebilir; sipariş tamamlama hizmeti şu anda kullanıma kapalıdır.'
    );
  end if;

  if not live_payments then
    return jsonb_build_object(
      'status',case when provider_configuration_required then 'blocked_pending_payment_provider_configuration' else 'blocked_pending_live_payment_enablement' end,
      'message','Katalog görüntülenebilir; ödeme ile sipariş tamamlama şu anda kullanıma kapalıdır.'
    );
  end if;

  return jsonb_build_object(
    'status','ready',
    'message','Sipariş ve ödeme hizmetleri kullanıma hazır.'
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.home_section_projection_v1(p_section jsonb, p_locale text DEFAULT 'tr'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  requested_locale text:=lower(split_part(btrim(coalesce(p_locale,'tr')),'-',1));
  source_kind text;
  collection_key text;
  category_slug_value text;
  display_limit integer;
  section_title text;
  section_items jsonb;
  start_at timestamptz;
  end_at timestamptz;
  now_utc timestamptz:=timezone('utc',now());
begin
  if requested_locale not in ('tr','en','de','fr','ku','ar') then requested_locale:='tr'; end if;
  if p_section is null or jsonb_typeof(p_section)<>'object' or coalesce((p_section->>'active')::boolean,false)=false then return null; end if;
  begin start_at:=nullif(p_section->>'startAt','')::timestamptz; exception when others then return null; end;
  begin end_at:=nullif(p_section->>'endAt','')::timestamptz; exception when others then return null; end;
  if start_at is not null and now_utc<start_at then return null; end if;
  if end_at is not null and now_utc>=end_at then return null; end if;

  source_kind:=coalesce(nullif(p_section#>>'{source,kind}',''),case p_section->>'id'
    when 'featured' then 'featured'
    when 'pre_order' then 'preorder'
    when 'seasonal' then 'seasonal'
    when 'new_arrivals' then 'newest'
    when 'offers' then 'offers'
    else 'curated' end);
  collection_key:=nullif(p_section#>>'{source,collectionKey}','');
  category_slug_value:=nullif(p_section#>>'{source,categorySlug}','');
  display_limit:=least(12,greatest(1,coalesce(nullif(p_section->>'displayLimit','')::integer,6)));
  section_title:=coalesce(nullif(p_section#>>array['localizedTitles',requested_locale],''),nullif(p_section->>'title',''),'Ürünler');

  select coalesce(jsonb_agg(card),'[]'::jsonb) into section_items
  from (
    select row_data.card
    from private.catalog_public_card_rows_v1() row_data
    where case source_kind
      when 'featured' then row_data.is_featured
      when 'preorder' then row_data.stock_mode='preorder'
      when 'seasonal' then row_data.stock_mode='seasonal' or row_data.home_section='seasonal'
      when 'offers' then row_data.compare_at_price_minor is not null and row_data.compare_at_price_minor>row_data.price_minor
      when 'category' then category_slug_value is not null and row_data.category_slug=category_slug_value
      when 'curated' then collection_key is not null and row_data.home_section=collection_key
      when 'newest' then true
      else false
    end
    order by
      case when source_kind='offers' then row_data.compare_at_price_minor-row_data.price_minor end desc nulls last,
      case when source_kind='featured' then row_data.is_featured end desc,
      row_data.published_at desc nulls last,row_data.product_id
    limit display_limit
  ) bounded;

  if jsonb_array_length(section_items)=0 then return null; end if;
  return jsonb_build_object(
    'key',p_section->>'id',
    'type',coalesce(nullif(p_section->>'sectionType',''),'product_carousel'),
    'title',section_title,
    'subtitle',coalesce(p_section->>'subtitle',''),
    'displayLimit',display_limit,
    'source',p_section->'source',
    'items',section_items
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.insert_conversation_message_v1(p_conversation_id uuid, p_sender_user_id uuid, p_body text, p_attachment_paths text[], p_message_type text)
 RETURNS messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  body_value text:=btrim(coalesce(p_body,''));
  type_value text:=lower(btrim(coalesce(p_message_type,'text')));
  attachments text[];
  message_row public.messages%rowtype;
  conversation_type_value text;
  violation text;
  path_value text;
begin
  if char_length(body_value) not between 1 and 5000 then raise exception 'invalid_message_body' using errcode='22023'; end if;
  select c.conversation_type into conversation_type_value from public.conversations c where c.id=p_conversation_id;
  violation:=private.message_moderation_violation_v1(body_value,conversation_type_value);
  if violation is not null then raise exception 'message_moderation_blocked:%',violation using errcode='22023'; end if;
  if type_value not in ('text','image','file') then raise exception 'invalid_message_type' using errcode='22023'; end if;
  attachments:=private.validate_message_attachments_v1(p_attachment_paths);
  foreach path_value in array attachments loop
    if split_part(path_value,'/',2)<>p_conversation_id::text then raise exception 'message_attachment_conversation_mismatch' using errcode='22023'; end if;
  end loop;
  if type_value in ('image','file') and coalesce(array_length(attachments,1),0)=0 then raise exception 'message_attachment_required' using errcode='22023'; end if;

  insert into public.messages(conversation_id,sender_user_id,body,attachment_paths,message_type)
  values(p_conversation_id,p_sender_user_id,body_value,attachments,type_value)
  returning * into message_row;

  update public.conversations set last_message_at=message_row.created_at,updated_at=message_row.created_at where id=p_conversation_id;
  update public.conversation_participants set last_read_at=message_row.created_at where conversation_id=p_conversation_id and user_id=p_sender_user_id;

  insert into public.notifications(user_id,type,title,message,action_url,metadata)
  select participant.user_id,'message','Yeni mesaj',left(body_value,180),'/messages/'||p_conversation_id::text,
         jsonb_build_object('conversationId',p_conversation_id,'messageId',message_row.id,'senderUserId',p_sender_user_id)
  from public.conversation_participants participant
  join public.profiles profile on profile.id=participant.user_id and profile.status='active'
  where participant.conversation_id=p_conversation_id and participant.user_id<>p_sender_user_id;
  return message_row;
end;
$function$;

CREATE OR REPLACE FUNCTION private.integration_secret_allowed_v1(p_name text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select p_name = any(array[
    'golden_oremar_iyzico_api_key',
    'golden_oremar_iyzico_secret_key',
    'golden_oremar_resend_api_key',
    'golden_oremar_fcm_service_account_email',
    'golden_oremar_fcm_private_key',
    'golden_oremar_apns_team_id',
    'golden_oremar_apns_key_id',
    'golden_oremar_apns_private_key'
  ]::text[]);
$function$;

CREATE OR REPLACE FUNCTION private.integration_secret_configured_v1(p_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare value text;
begin
  if not private.integration_secret_allowed_v1(p_name) then return false; end if;
  select nullif(btrim(decrypted_secret),'') into value from vault.decrypted_secrets where name=p_name limit 1;
  return value is not null and value not like 'replace-before-release:%';
end;
$function$;

CREATE OR REPLACE FUNCTION private.invalidate_business_legal_finalization_on_document_change_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.content_type='legal' and new.locale='tr' and new.slug in('about','returns','privacy','terms') then
    update public.brand_settings
    set public_config=jsonb_set(coalesce(public_config,'{}'::jsonb),'{businessIdentity,legalDocumentsFinalized}','false'::jsonb,true),updated_at=timezone('utc',now())
    where slug='golden-oremar' and coalesce((public_config#>>'{businessIdentity,legalDocumentsFinalized}')::boolean,false)=true;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.invalidate_business_legal_finalization_on_identity_change_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old_identity jsonb:=coalesce(old.public_config->'businessIdentity','{}'::jsonb); new_identity jsonb:=coalesce(new.public_config->'businessIdentity','{}'::jsonb);
begin
  if new.slug='golden-oremar' and (
    old_identity->>'registeredLegalName' is distinct from new_identity->>'registeredLegalName' or
    old_identity->>'registeredAddress' is distinct from new_identity->>'registeredAddress' or
    old_identity->>'countryCode' is distinct from new_identity->>'countryCode' or
    old_identity->>'taxOffice' is distinct from new_identity->>'taxOffice' or
    old_identity->>'taxNumber' is distinct from new_identity->>'taxNumber' or
    old_identity->>'mersisNumber' is distinct from new_identity->>'mersisNumber' or
    old_identity->>'tradeRegistryNumber' is distinct from new_identity->>'tradeRegistryNumber'
  ) then
    new.public_config:=jsonb_set(coalesce(new.public_config,'{}'::jsonb),'{businessIdentity,legalDocumentsFinalized}','false'::jsonb,true);
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select
    private.has_role('admin')
    or private.has_role('super_admin');
$function$;

CREATE OR REPLACE FUNCTION private.is_producer_trust_badge_active_v1(p_producer_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce((
    select p.status='active'
      and p.is_verified=true
      and p.origin_verified=true
      and p.trust_badge_status='active'
      and (p.trust_badge_review_due_at is null or p.trust_badge_review_due_at > timezone('utc',now()))
      and p.deleted_at is null
    from public.producers p where p.id=p_producer_id
  ),false);
$function$;

