CREATE OR REPLACE FUNCTION private.is_valid_tckn(value text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  digits integer[];
begin
  if value is null or value !~ '^[1-9][0-9]{10}$' then
    return false;
  end if;

  digits := array[
    substring(value, 1, 1)::integer,
    substring(value, 2, 1)::integer,
    substring(value, 3, 1)::integer,
    substring(value, 4, 1)::integer,
    substring(value, 5, 1)::integer,
    substring(value, 6, 1)::integer,
    substring(value, 7, 1)::integer,
    substring(value, 8, 1)::integer,
    substring(value, 9, 1)::integer,
    substring(value, 10, 1)::integer,
    substring(value, 11, 1)::integer
  ];

  return digits[10] = mod(
      7 * (digits[1] + digits[3] + digits[5] + digits[7] + digits[9])
      - (digits[2] + digits[4] + digits[6] + digits[8]) + 100,
      10
    )
    and digits[11] = mod(
      digits[1] + digits[2] + digits[3] + digits[4] + digits[5]
      + digits[6] + digits[7] + digits[8] + digits[9] + digits[10],
      10
    );
end;
$function$;

CREATE OR REPLACE FUNCTION private.is_valid_tr_iban_v1(p_value text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v text:=upper(regexp_replace(coalesce(p_value,''),'[^A-Za-z0-9]','','g'));
  rearranged text;
  expanded text;
  i int;
  c text;
  remainder int:=0;
begin
  if v !~ '^TR[0-9]{24}$' then return false; end if;
  rearranged:=substr(v,5)||substr(v,1,4);
  expanded:='';
  for i in 1..char_length(rearranged) loop
    c:=substr(rearranged,i,1);
    if c ~ '^[A-Z]$' then expanded:=expanded||(ascii(c)-55)::text; else expanded:=expanded||c; end if;
  end loop;
  for i in 1..char_length(expanded) loop
    remainder:=(remainder*10+substr(expanded,i,1)::int)%97;
  end loop;
  return remainder=1;
end;
$function$;

CREATE OR REPLACE FUNCTION private.is_valid_turkish_identity_v1(p_value text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v text:=btrim(coalesce(p_value,''));
  d int[];
  odd_sum int;
  even_sum int;
begin
  if v !~ '^[1-9][0-9]{10}$' then return false; end if;
  d:=array(select substr(v,i,1)::int from generate_series(1,11) i);
  odd_sum:=d[1]+d[3]+d[5]+d[7]+d[9];
  even_sum:=d[2]+d[4]+d[6]+d[8];
  return ((odd_sum*7-even_sum)%10+10)%10=d[10]
    and (select sum(x) from unnest(d[1:10]) x)%10=d[11];
end;
$function$;

CREATE OR REPLACE FUNCTION private.is_youtube_video_url_v1(p_value text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select coalesce(
    char_length(p_value) <= 2000
    and p_value ~* '^https://((www|m)\.)?(youtube\.com/(watch\?v=|shorts/|embed/|live/)|youtu\.be/|youtube-nocookie\.com/embed/)[A-Za-z0-9_-]{11}([?&#/].*)?$',
    false
  );
$function$;

CREATE OR REPLACE FUNCTION private.list_customer_favorite_references_impl_v1()
 RETURNS TABLE(product_reference text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid();
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  return query
  select coalesce(product.legacy_id,product.id::text)
  from public.favorites favorite
  join public.products product on product.id=favorite.product_id
  join public.producers producer on producer.id=product.producer_id
  where favorite.user_id=caller_id and product.status='published' and product.is_active=true and product.deleted_at is null
    and producer.status='active' and producer.is_verified=true and producer.deleted_at is null
  order by favorite.created_at desc;
end;
$function$;

CREATE OR REPLACE FUNCTION private.list_customer_returns_v1()
 RETURNS jsonb
