CREATE OR REPLACE FUNCTION private.list_my_conversations_v1(p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); result jsonb;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if p_limit not between 1 and 100 or p_offset<0 then raise exception 'invalid_pagination' using errcode='22023'; end if;
  select coalesce(jsonb_agg(item order by sort_time desc),'[]'::jsonb) into result
  from (
    select jsonb_build_object(
      'id',conversation.id,'type',conversation.conversation_type,'orderId',conversation.order_id,'producerId',conversation.producer_id,'productId',conversation.product_id,
      'subject',conversation.subject,'status',conversation.status,'updatedAt',conversation.updated_at,'lastMessageAt',conversation.last_message_at,
      'title',case when conversation.conversation_type='support' then 'Golden Oremar Destek' else coalesce(producer.display_name,'Üretici') end,
      'lastMessage',coalesce((select case when m.deleted_at is null then left(m.body,180) else 'Mesaj kaldırıldı' end from public.messages m where m.conversation_id=conversation.id order by m.created_at desc limit 1),''),
      'unreadCount',(select count(*) from public.messages m where m.conversation_id=conversation.id and m.sender_user_id<>caller_id and m.created_at>coalesce(participant.last_read_at,'epoch'::timestamptz))
    ) item,coalesce(conversation.last_message_at,conversation.updated_at) sort_time
    from public.conversation_participants participant
    join public.conversations conversation on conversation.id=participant.conversation_id
    left join public.producers producer on producer.id=conversation.producer_id
    where participant.user_id=caller_id
    order by coalesce(conversation.last_message_at,conversation.updated_at) desc
    limit p_limit offset p_offset
  ) rows;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.list_my_event_reservations_v1(p_limit integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); result jsonb;
begin
 if uid is null then raise exception 'authentication_required' using errcode='42501'; end if;
 if p_limit not between 1 and 100 then raise exception 'invalid_limit' using errcode='22023'; end if;
 select coalesce(jsonb_agg(jsonb_build_object(
   'id',r.id,'event_id',r.event_id,'reservation_code',r.reservation_code,'guest_name',r.guest_name,'guest_count',r.guest_count,
   'status',case when r.status='pending_payment' and f.payment_status='pending' and f.payment_expires_at<=timezone('utc',now()) then 'cancelled' else r.status end,
   'created_at',r.created_at,'updated_at',r.updated_at,
   'payment',case when f.reservation_id is null then jsonb_build_object('status','not_required','requiresPayment',false,'amountMinor',0,'currency',e.currency,'expiresAt',null)
     else jsonb_build_object('status',case when f.payment_status='pending' and f.payment_expires_at<=timezone('utc',now()) then 'expired' else f.payment_status end,'requiresPayment',f.payment_status='pending' and f.payment_expires_at>timezone('utc',now()),'amountMinor',f.total_minor,'currency',f.currency,'expiresAt',f.payment_expires_at) end,
   'event',case when e.id is null then null else jsonb_build_object('id',e.id,'slug',e.slug,'title',e.title,'starts_at',e.starts_at,'ends_at',e.ends_at,'location_name',e.location_name,'status',e.status,'image_path',private.verified_public_storage_path_v1('content-public',e.image_path),'ticket_price_minor',e.ticket_price_minor,'currency',e.currency) end
 ) order by r.created_at desc),'[]'::jsonb) into result
 from (select * from public.event_reservations where user_id=uid order by created_at desc limit p_limit) r
 left join public.events e on e.id=r.event_id
 left join private.event_reservation_finance f on f.reservation_id=r.id;
 return result;
end;$function$;

CREATE OR REPLACE FUNCTION private.list_my_favorites_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); result jsonb;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'productId',p.id,
    'legacyId',p.legacy_id,
    'slug',p.slug,
    'name',p.name,
    'shortDescription',p.short_description,
    'origin',p.origin,
    'currency',p.currency,
    'stockMode',p.stock_mode,
    'availableQuantity',case when p.stock_mode in ('tracked','seasonal') then greatest(0,coalesce(inv.available_quantity,0)-coalesce(inv.reserved_quantity,0)) else null end,
    'handlingProfile',private.product_handling_profile_v1(p.id),
    'producer',jsonb_build_object(
      'id',pr.id,
      'name',pr.display_name,
      'verified',private.is_producer_trust_badge_active_v1(pr.id),
      'originVerified',pr.origin_verified and private.is_producer_trust_badge_active_v1(pr.id),
      'locationLabel',pr.production_location,
      'storeKind',pr.store_kind,
      'storefrontTier',pr.storefront_tier,
      'badgeTone',case when pr.store_kind='official' then 'ruby' else 'blue' end,
      'storeBadgeLabel',case when pr.store_kind='official' then 'Golden Oremar Resmi Mağazası' else 'Golden Oremar Doğrulanmış Üretici' end
    ),
    'variant',case when v.id is null then jsonb_build_object('id',null) else jsonb_build_object('id',v.id,'name',v.name,'priceMinor',v.price_minor,'compareAtPriceMinor',v.compare_at_price_minor) end,
    'imagePath',private.verified_public_storage_path_v1('catalog-public',(
      select i.storage_path from public.product_images i where i.product_id=p.id order by i.is_primary desc,i.sort_order,i.created_at limit 1
    )),
    'available',p.status='published' and p.is_active=true and p.deleted_at is null
      and pr.status='active' and pr.is_verified=true and pr.deleted_at is null
      and v.id is not null
      and (p.stock_mode not in ('tracked','seasonal') or greatest(0,coalesce(inv.available_quantity,0)-coalesce(inv.reserved_quantity,0))>0),
    'favoritedAt',f.created_at
  ) order by f.created_at desc),'[]'::jsonb)
  into result
  from public.favorites f
  join public.products p on p.id=f.product_id
  join public.producers pr on pr.id=p.producer_id
  left join lateral(
    select pv.* from public.product_variants pv where pv.product_id=p.id and pv.is_active=true order by pv.is_default desc,pv.created_at limit 1
  ) v on true
  left join public.product_inventory inv on inv.variant_id=v.id
  where f.user_id=caller_id;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.list_my_followed_producers_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); result jsonb;
begin
 if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
 select coalesce(jsonb_agg(jsonb_build_object(
   'id',p.id,'slug',p.slug,'displayName',p.display_name,'description',p.description,'logoPath',p.logo_path,'coverPath',p.cover_path,
   'ratingAverage',p.rating_average,'ratingCount',p.rating_count,
   'verified',private.is_producer_trust_badge_active_v1(p.id),
   'originVerified',p.origin_verified and private.is_producer_trust_badge_active_v1(p.id),
   'storeKind',p.store_kind,
   'storefrontTier',p.storefront_tier,
   'badgeTone',case when p.store_kind='official' then 'ruby' else 'blue' end,
   'storeBadgeLabel',case when p.store_kind='official' then 'Golden Oremar Resmi Mağazası' else 'Golden Oremar Doğrulanmış Üretici' end,
   'locationLabel',p.production_location,'location',jsonb_build_object('countryCode',p.production_country_code,'province',p.production_province,'district',p.production_district,'village',p.production_village),
   'productCount',(select count(*) from public.products product where product.producer_id=p.id and product.status='published' and product.is_active=true and product.deleted_at is null),
   'followedAt',f.created_at
 ) order by f.created_at desc),'[]'::jsonb) into result
