CREATE OR REPLACE FUNCTION private.list_my_producer_conversations_v1(p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  producer_id_value uuid;
  result jsonb;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if p_limit not between 1 and 100 or p_offset<0 then raise exception 'invalid_pagination' using errcode='22023'; end if;

  select p.id into producer_id_value
  from public.producers p
  where p.owner_user_id=caller_id and p.deleted_at is null
  order by p.created_at
  limit 1;

  if producer_id_value is null then raise exception 'producer_required' using errcode='42501'; end if;

  select coalesce(jsonb_agg(item order by sort_time desc),'[]'::jsonb) into result
  from (
    select jsonb_build_object(
      'id',conversation.id,
      'type',conversation.conversation_type,
      'orderId',conversation.order_id,
      'producerId',conversation.producer_id,
      'productId',conversation.product_id,
      'subject',conversation.subject,
      'status',conversation.status,
      'updatedAt',conversation.updated_at,
      'lastMessageAt',conversation.last_message_at,
      'title',coalesce((
        select profile.display_name
        from public.conversation_participants other_participant
        join public.profiles profile on profile.id=other_participant.user_id
        where other_participant.conversation_id=conversation.id and other_participant.user_id<>caller_id
        order by other_participant.created_at
        limit 1
      ),'Müşteri'),
      'lastMessage',coalesce((
        select case when m.deleted_at is null then left(m.body,180) else 'Mesaj kaldırıldı' end
        from public.messages m
        where m.conversation_id=conversation.id
        order by m.created_at desc
        limit 1
      ),''),
      'unreadCount',(
        select count(*)
        from public.messages m
        where m.conversation_id=conversation.id
          and m.sender_user_id<>caller_id
          and m.created_at>coalesce(participant.last_read_at,'epoch'::timestamptz)
      )
    ) item,
    coalesce(conversation.last_message_at,conversation.updated_at) sort_time
    from public.conversation_participants participant
    join public.conversations conversation on conversation.id=participant.conversation_id
    where participant.user_id=caller_id
      and conversation.conversation_type='producer'
      and conversation.producer_id=producer_id_value
    order by coalesce(conversation.last_message_at,conversation.updated_at) desc
    limit p_limit offset p_offset
  ) rows;

  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.list_my_producer_event_submissions_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); producer_id uuid;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if; if not private.has_permission('event.read') then raise exception 'permission_required:event.read' using errcode='42501'; end if;
  perform private.assert_platform_access_v1(caller_id);
  if coalesce(private.has_permission('admin.access'),false) then raise exception 'producer_portal_separate_from_admin' using errcode='42501'; end if;
  select id into producer_id from public.producers where owner_user_id=caller_id and deleted_at is null order by created_at desc limit 1;
  if producer_id is null then return '[]'::jsonb; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id',s.id,'title',s.title,'description',s.description,'imagePath',s.image_path,'locationName',s.location_name,'locationDetails',s.location_details,
    'startsAt',s.starts_at,'endsAt',s.ends_at,'capacity',s.capacity,'reservationDeadline',s.reservation_deadline,
    'ticketPriceMinor',s.ticket_price_minor,'currency',s.currency,'status',s.status,'reviewReason',s.review_reason,'eventId',s.event_id,
    'createdAt',s.created_at,'updatedAt',s.updated_at
  ) order by s.created_at desc) from private.producer_event_submissions s where s.producer_id=producer_id),'[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION private.list_my_producer_inventory_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); producer_id_value uuid; result jsonb;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select producer.id into producer_id_value from public.producers producer where producer.owner_user_id=caller_id and producer.status='active' and producer.is_verified=true and producer.deleted_at is null limit 1;
  if producer_id_value is null then raise exception 'verified_active_producer_required' using errcode='42501'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'productId',product.id,'productName',product.name,'productStatus',product.status,'stockMode',product.stock_mode,
    'variantId',variant.id,'variantName',variant.name,'sku',variant.sku,'priceMinor',variant.price_minor,'currency',product.currency,
    'availableQuantity',coalesce(inventory.available_quantity,0),'reservedQuantity',coalesce(inventory.reserved_quantity,0),
    'sellableQuantity',case when inventory.variant_id is null then 0 else greatest(0,inventory.available_quantity-inventory.reserved_quantity) end,
    'reorderLevel',coalesce(inventory.reorder_level,0),'version',coalesce(inventory.version,1),'weightGrams',variant.weight_grams
  ) order by product.name,variant.is_default desc,variant.name),'[]'::jsonb)
  into result
  from public.products product
  join public.product_variants variant on variant.product_id=product.id and variant.is_active=true
  left join public.product_inventory inventory on inventory.variant_id=variant.id
  where product.producer_id=producer_id_value and product.deleted_at is null and product.status<>'archived';
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.list_my_producer_orders_v1(p_scope text DEFAULT 'open'::text, p_limit integer DEFAULT 30, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  producer_id_value uuid;
  normalized_scope text:=lower(btrim(coalesce(p_scope,'open')));
  result jsonb;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if; if not private.has_permission('order.read') then raise exception 'permission_required:order.read' using errcode='42501'; end if;
  if normalized_scope not in ('open','shipped','all') then raise exception 'invalid_order_scope' using errcode='22023'; end if;
  if p_limit not between 1 and 100 or p_offset<0 then raise exception 'invalid_pagination' using errcode='22023'; end if;

  select p.id into producer_id_value
  from public.producers p
  where p.owner_user_id=caller_id and p.status='active' and p.is_verified=true and p.deleted_at is null
  order by p.created_at desc limit 1;
  if producer_id_value is null then raise exception 'verified_active_producer_required' using errcode='42501'; end if;

  with item_rows as (
    select oi.order_id,oi.id,oi.line_total_minor,oi.fulfillment_status,
      greatest(0,oi.quantity-coalesce((select sum(si.quantity)::integer from public.shipment_items si where si.order_item_id=oi.id),0)) as remaining_quantity
    from public.order_items oi
    join public.orders o on o.id=oi.order_id
    where oi.producer_id=producer_id_value
      and o.payment_status in ('paid','partially_refunded','refunded')
      and o.status not in ('draft','pending_payment','cancelled')
  ), grouped as (
    select ir.order_id,
      count(*)::integer as item_count,
      sum(ir.line_total_minor)::bigint as producer_subtotal_minor,
      count(*) filter (where ir.remaining_quantity>0 and ir.fulfillment_status not in ('cancelled','returned'))::integer as remaining_item_count,
      count(*) filter (where ir.fulfillment_status='processing')::integer as processing_item_count,
      count(*) filter (where ir.fulfillment_status='fulfilled')::integer as fulfilled_item_count
    from item_rows ir group by ir.order_id
  ), filtered as (
    select o.*,g.item_count,g.producer_subtotal_minor,g.remaining_item_count,g.processing_item_count,g.fulfilled_item_count
    from grouped g join public.orders o on o.id=g.order_id
    where normalized_scope='all'
      or (normalized_scope='open' and g.remaining_item_count>0 and o.status not in ('shipped','delivered','completed','refunded'))
      or (normalized_scope='shipped' and (g.remaining_item_count=0 or o.status in ('shipped','delivered','completed','refunded')))
  ), paged as (
    select * from filtered order by coalesce(placed_at,created_at) desc limit p_limit offset p_offset
  )
  select jsonb_build_object(
    'scope',normalized_scope,
    'limit',p_limit,
    'offset',p_offset,
    'total',(select count(*) from filtered),
    'items',coalesce((select jsonb_agg(jsonb_build_object(
      'id',p.id,
      'orderNumber',p.order_number,
      'status',p.status,
      'paymentStatus',p.payment_status,
      'fulfillmentStatus',p.fulfillment_status,
      'currency',p.currency,
      'producerSubtotalMinor',p.producer_subtotal_minor,
      'itemCount',p.item_count,
      'remainingItemCount',p.remaining_item_count,
      'processingItemCount',p.processing_item_count,
      'fulfilledItemCount',p.fulfilled_item_count,
      'recipientName',coalesce(p.shipping_address->>'recipient_name',p.shipping_address->>'recipientName'),
      'destination',jsonb_build_object(
        'countryCode',coalesce(p.shipping_address->>'country_code',p.shipping_address->>'countryCode'),
        'province',p.shipping_address->>'province',
        'district',p.shipping_address->>'district'
      ),
      'placedAt',p.placed_at,
      'createdAt',p.created_at
    ) order by coalesce(p.placed_at,p.created_at) desc) from paged p),'[]'::jsonb)
  ) into result;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.list_my_producer_payouts_v2(p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); p_id uuid; result jsonb;
begin
  if uid is null then raise exception 'authentication_required' using errcode='42501'; end if; if not private.has_permission('payout.read') then raise exception 'permission_required:payout.read' using errcode='42501'; end if;
  if p_limit not between 1 and 100 or p_offset<0 then raise exception 'invalid_pagination' using errcode='22023'; end if;
  select id into p_id from public.producers where owner_user_id=uid and deleted_at is null order by created_at desc limit 1;
  if p_id is null then raise exception 'producer_profile_required' using errcode='42501'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'currency',q.currency,'amountMinor',q.amount_minor,'status',q.status,'channel',q.channel,'requestSource',q.request_source,'sourceOrderId',q.source_order_id,'provider',q.provider,'providerReference',q.provider_reference,'note',q.note,'destinationAccountHolder',q.destination_account_holder,'destinationIbanMasked',coalesce(q.destination_iban_masked,case when q.destination_iban_ciphertext is not null then private.mask_tr_iban_v1(private.decrypt_producer_kyc(q.destination_iban_ciphertext)) else null end),'requestedAt',q.requested_at,'scheduledAt',q.scheduled_at,'providerSettlementReleasedAt',q.provider_settlement_released_at,'processedAt',q.processed_at,'createdAt',q.created_at) order by q.created_at desc),'[]'::jsonb) into result
  from (select * from private.producer_payouts where producer_id=p_id order by created_at desc limit p_limit offset p_offset) q;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.list_my_producer_products_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  producer_id_value uuid;
  result jsonb;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select producer.id into producer_id_value
  from public.producers producer
  where producer.owner_user_id=caller_id and producer.status='active' and producer.is_verified=true and producer.deleted_at is null
  order by producer.created_at desc limit 1;
  if producer_id_value is null then raise exception 'verified_active_producer_required' using errcode='42501'; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',product.id,'legacyId',product.legacy_id,'slug',product.slug,'name',product.name,
    'shortDescription',product.short_description,'description',product.description,'story',product.story,'origin',product.origin,
    'unitLabel',product.unit_label,'currency',product.currency,'status',product.status,'stockMode',product.stock_mode,
    'preorderLeadDays',product.preorder_lead_days,'tags',product.tags,'features',product.features,'active',product.is_active,
    'category',jsonb_build_object('id',category.id,'slug',category.slug,'name',category.name),
    'variants',coalesce((select jsonb_agg(jsonb_build_object(
      'id',variant.id,'name',variant.name,'sku',variant.sku,'priceMinor',variant.price_minor,
      'compareAtPriceMinor',variant.compare_at_price_minor,'weightGrams',variant.weight_grams,'default',variant.is_default,'active',variant.is_active,
      'availableQuantity',coalesce(inventory.available_quantity,0),'reservedQuantity',coalesce(inventory.reserved_quantity,0),
      'reorderLevel',coalesce(inventory.reorder_level,0),'version',coalesce(inventory.version,1)
    ) order by variant.is_default desc,variant.created_at) from public.product_variants variant left join public.product_inventory inventory on inventory.variant_id=variant.id where variant.product_id=product.id),'[]'::jsonb),
    'images',coalesce((select jsonb_agg(jsonb_build_object('path',image.storage_path,'alt',image.alt_text,'primary',image.is_primary,'sortOrder',image.sort_order) order by image.is_primary desc,image.sort_order,image.created_at) from public.product_images image where image.product_id=product.id),'[]'::jsonb),
    'pendingChange',(
      select jsonb_build_object('id',request.id,'status',request.status,'createdAt',request.created_at,'updatedAt',request.updated_at,'reviewReason',request.review_reason)
      from public.product_change_requests request
      where request.product_id=product.id and request.status='pending'
      order by request.created_at desc limit 1
    )
  ) order by product.updated_at desc,product.name),'[]'::jsonb)
  into result
  from public.products product
  join public.categories category on category.id=product.category_id
  where product.producer_id=producer_id_value and product.deleted_at is null and product.status<>'archived';
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.list_my_producer_products_v2()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  base jsonb:=private.list_my_producer_products_v1();
  result jsonb;
begin
  select coalesce(jsonb_agg(
    jsonb_set(product_item,'{images}',coalesce(asset_images.images,'[]'::jsonb),true)
    order by product_ordinality
  ),'[]'::jsonb)
  into result
  from jsonb_array_elements(coalesce(base,'[]'::jsonb)) with ordinality as products(product_item,product_ordinality)
  cross join lateral (
    select coalesce(jsonb_agg(
      jsonb_set(image_item,'{path}',to_jsonb(verified_path),true)
      order by image_ordinality
    ) filter(where verified_path is not null),'[]'::jsonb) as images
    from jsonb_array_elements(coalesce(product_item->'images','[]'::jsonb)) with ordinality as image_rows(image_item,image_ordinality)
    cross join lateral (
      select private.verified_public_storage_path_v1('catalog-public',image_item->>'path') as verified_path
    ) verified
  ) asset_images;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.list_my_producer_products_v3()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare base jsonb:=private.list_my_producer_products_v2(); result jsonb;
begin
  select coalesce(jsonb_agg(product_item||jsonb_build_object(
    'rejectionReason',case when product.status='rejected' then nullif(product.specifications->>'rejectionReason','') else null end,
    'moderation',jsonb_build_object(
      'lastDecision',(select event.decision from private.product_moderation_events event where event.product_id=product.id order by event.created_at desc limit 1),
      'lastReason',(select event.reason from private.product_moderation_events event where event.product_id=product.id order by event.created_at desc limit 1),
      'lastDecisionAt',(select event.created_at from private.product_moderation_events event where event.product_id=product.id order by event.created_at desc limit 1),
      'lastRejectedChangeReason',(select request.review_reason from public.product_change_requests request where request.product_id=product.id and request.status='rejected' order by request.reviewed_at desc nulls last,request.updated_at desc limit 1)
    )
  ) order by product_ordinality),'[]'::jsonb) into result
  from jsonb_array_elements(coalesce(base,'[]'::jsonb)) with ordinality rows(product_item,product_ordinality)
  join public.products product on product.id=(product_item->>'id')::uuid;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.list_my_reviewable_order_items_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  result jsonb;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'orderItemId', item.id,
    'orderId', customer_order.id,
    'orderNumber', customer_order.order_number,
    'deliveredAt', coalesce(customer_order.completed_at, customer_order.updated_at),
    'productId', item.product_id,
    'productName', item.product_name,
    'variantName', item.variant_name,
    'imagePath', item.image_path,
    'producerId', item.producer_id,
    'producerName', producer.display_name,
    'quantity', item.quantity
  ) order by customer_order.updated_at desc,item.product_name),'[]'::jsonb)
  into result
  from public.order_items item
  join public.orders customer_order on customer_order.id=item.order_id
  join public.producers producer on producer.id=item.producer_id
  where customer_order.user_id=caller_id
    and customer_order.status in ('delivered','completed')
    and not exists(select 1 from public.reviews review where review.order_item_id=item.id);
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.list_my_reviews_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  result jsonb;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', review.id,
    'productId', review.product_id,
    'productName', product.name,
    'productSlug', product.slug,
    'orderItemId', review.order_item_id,
    'rating', review.rating,
    'title', review.title,
    'body', review.body,
    'mediaPaths', review.media_paths,
    'status', review.status,
    'verifiedPurchase', review.is_verified_purchase,
    'merchantReply', review.merchant_reply,
    'merchantRepliedAt', review.merchant_replied_at,
    'createdAt', review.created_at,
    'updatedAt', review.updated_at,
    'editedAt', review.edited_at,
    'moderationReason', review.moderation_reason
  ) order by review.created_at desc),'[]'::jsonb)
  into result
  from public.reviews review
  join public.products product on product.id=review.product_id
  where review.user_id=caller_id;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.list_public_categories_v1()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',category.id,
    'parentId',category.parent_id,
    'slug',category.slug,
    'name',category.name,
    'description',category.description,
    'icon',category.icon,
    'imagePath',category.image_path,
    'sortOrder',category.sort_order,
    'productCount',(
      select count(*)
      from public.products product
      join public.producers producer on producer.id=product.producer_id
      where product.category_id=category.id
        and product.status='published' and product.is_active=true and product.deleted_at is null
        and producer.status='active' and producer.is_verified=true and producer.deleted_at is null
    )
  ) order by category.sort_order,category.name),'[]'::jsonb)
  from public.categories category
  where category.is_active=true;
$function$;

CREATE OR REPLACE FUNCTION private.list_public_categories_v2()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  base jsonb:=private.list_public_categories_v1();
  result jsonb;
begin
  select coalesce(jsonb_agg(
    jsonb_set(item,'{imagePath}',coalesce(to_jsonb(private.verified_public_storage_path_v1('catalog-public',item->>'imagePath')),'null'::jsonb),true)
    order by ordinality
  ),'[]'::jsonb) into result
  from jsonb_array_elements(coalesce(base,'[]'::jsonb)) with ordinality as rows(item,ordinality);
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.list_public_categories_v3()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with counts as (
    select card.category_id,count(*)::bigint product_count
    from private.catalog_public_card_rows_v1() card
    group by card.category_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',category.id,
    'slug',category.slug,
    'name',category.name,
    'description',category.description,
    'icon',category.icon,
    'imagePath',category.image_path,
    'productCount',counts.product_count,
    'sortOrder',category.sort_order,
    'parentId',category.parent_id,
    'seo',category.seo
  ) order by category.sort_order,category.name),'[]'::jsonb)
  from public.categories category
  join counts on counts.category_id=category.id and counts.product_count>0
  where category.is_active=true;
$function$;

CREATE OR REPLACE FUNCTION private.list_public_content_v1(p_content_type text, p_locale text DEFAULT 'tr'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  type_value text:=lower(btrim(coalesce(p_content_type,'')));
  locale_value text:=lower(btrim(coalesce(p_locale,'tr')));
  result jsonb;
begin
  if type_value not in ('recipe','health_guide','product_health','page','legal') then raise exception 'invalid_content_type' using errcode='22023'; end if;
  if locale_value not in ('tr','en','de','fr','ku','ar') then raise exception 'invalid_locale' using errcode='22023'; end if;
  if p_limit not between 1 and 50 or p_offset<0 then raise exception 'invalid_pagination' using errcode='22023'; end if;

  with eligible as (
    select entry.*
    from public.content_entries entry
    where entry.content_type=type_value and entry.locale=locale_value
      and entry.status='published' and entry.deleted_at is null
      and (entry.published_at is null or entry.published_at<=timezone('utc',now()))
  ), paged as (
    select entry.* from eligible entry
    order by entry.published_at desc nulls last,entry.created_at desc,entry.id
    limit p_limit offset p_offset
  )
  select jsonb_build_object(
    'total',(select count(*) from eligible),
    'limit',p_limit,'offset',p_offset,
    'items',coalesce(jsonb_agg(jsonb_build_object(
      'id',paged.id,'legacyId',paged.legacy_id,'type',paged.content_type,'slug',paged.slug,
      'title',paged.title,'summary',paged.summary,'heroImagePath',paged.hero_image_path,
      'tags',paged.tags,'publishedAt',paged.published_at,
      'category',nullif(btrim(coalesce(paged.metadata->>'originalCategory','')),''),
      'relatedProduct',case when product.id is null then null else jsonb_build_object(
        'id',product.id,'slug',product.slug,'name',product.name
      ) end
    ) order by paged.published_at desc nulls last,paged.created_at desc,paged.id),'[]'::jsonb)
  ) into result
  from paged
  left join public.products product on product.id=paged.related_product_id
    and product.status='published' and product.is_active=true and product.deleted_at is null
    and exists(select 1 from public.producers producer where producer.id=product.producer_id and producer.status='active' and producer.is_verified=true and producer.deleted_at is null);
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.list_public_content_v2(p_content_type text, p_locale text DEFAULT 'tr'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  base jsonb:=private.list_public_content_v1(p_content_type,p_locale,p_limit,p_offset);
  items jsonb;
begin
  select coalesce(jsonb_agg(
    jsonb_set(item,'{heroImagePath}',coalesce(to_jsonb(private.verified_public_storage_path_v1('content-public',item->>'heroImagePath')),'null'::jsonb),true)
    order by ordinality
  ),'[]'::jsonb) into items
  from jsonb_array_elements(coalesce(base->'items','[]'::jsonb)) with ordinality as rows(item,ordinality);
  return jsonb_set(base,'{items}',items,true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.list_public_events_v1(p_include_past boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
  with event_rows as (
    select e.id,e.legacy_id,e.slug,e.title,e.description,e.image_path,e.location_name,e.starts_at,e.ends_at,e.capacity,e.reservation_deadline,e.status,e.ticket_price_minor,e.currency,e.sale_mode,
      coalesce((select sum(r.guest_count)::integer from public.event_reservations r left join private.event_reservation_finance f on f.reservation_id=r.id
        where r.event_id=e.id and (r.status in ('pending','confirmed','attended') or (r.status='pending_payment' and f.payment_status='pending' and f.payment_expires_at>timezone('utc',now())))),0) as reserved_guests
    from public.events e
    where e.status in ('published','sold_out','completed') and (p_include_past or e.ends_at>=timezone('utc',now()))
  )
  select jsonb_build_object(
    'items',coalesce(jsonb_agg(jsonb_build_object(
      'id',row.id,'legacyId',row.legacy_id,'slug',row.slug,'title',row.title,'description',row.description,'imagePath',row.image_path,'locationName',row.location_name,
      'startsAt',row.starts_at,'endsAt',row.ends_at,
      'status',case when row.status='sold_out' and row.capacity is not null and row.reserved_guests<row.capacity then 'published' else row.status end,
      'capacity',row.capacity,'remainingCapacity',case when row.capacity is null then null else greatest(0,row.capacity-row.reserved_guests) end,
      'reservationDeadline',row.reservation_deadline,
      'reservable',row.status in ('published','sold_out') and row.starts_at>timezone('utc',now()) and (row.reservation_deadline is null or row.reservation_deadline>=timezone('utc',now())),
      'waitlistOnly',case when row.capacity is null then row.status='sold_out' else row.reserved_guests>=row.capacity end,
      'ticketPriceMinor',row.ticket_price_minor,'currency',row.currency,'isPaid',row.ticket_price_minor>0,'saleMode',row.sale_mode
    ) order by case when row.ends_at>=timezone('utc',now()) then 0 else 1 end,case when row.ends_at>=timezone('utc',now()) then row.starts_at end asc,case when row.ends_at<timezone('utc',now()) then row.starts_at end desc),'[]'::jsonb),
    'upcomingCount',count(*) filter(where row.ends_at>=timezone('utc',now())),'pastCount',count(*) filter(where row.ends_at<timezone('utc',now()))
  ) into result from event_rows row;
  return result;
end;$function$;

CREATE OR REPLACE FUNCTION private.list_public_events_v2(p_include_past boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  base jsonb:=private.list_public_events_v1(p_include_past);
  items jsonb;
begin
  select coalesce(jsonb_agg(
    jsonb_set(item,'{imagePath}',coalesce(to_jsonb(private.verified_public_storage_path_v1('content-public',item->>'imagePath')),'null'::jsonb),true)
    order by ordinality
  ),'[]'::jsonb) into items
  from jsonb_array_elements(coalesce(base->'items','[]'::jsonb)) with ordinality as rows(item,ordinality);
  return jsonb_set(base,'{items}',items,true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.list_public_faq_v1(p_locale text DEFAULT 'tr'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  requested_locale text:=lower(btrim(coalesce(p_locale,'tr')));
  resolved_locale text;
  result jsonb;
begin
  if requested_locale not in ('tr','en','de','fr','ku','ar') then
    raise exception 'invalid_locale' using errcode='22023';
  end if;

  if exists(
    select 1 from public.content_entries ce
    where ce.content_type='faq' and ce.locale=requested_locale and ce.status='published' and ce.deleted_at is null
      and (ce.published_at is null or ce.published_at<=timezone('utc',now()))
  ) then
    resolved_locale:=requested_locale;
  else
    resolved_locale:='tr';
  end if;

  select jsonb_build_object(
    'locale',resolved_locale,
    'fallbackUsed',resolved_locale<>requested_locale,
    'total',count(*)::int,
    'items',coalesce(jsonb_agg(jsonb_build_object(
      'id',ce.id,
      'slug',ce.slug,
      'question',ce.title,
      'answer',ce.body_markdown,
      'category',coalesce(nullif(ce.metadata->>'category',''),'Diğer'),
      'sortOrder',case when coalesce(ce.metadata->>'sortOrder','') ~ '^[0-9]+$' then (ce.metadata->>'sortOrder')::int else 999 end,
      'tags',ce.tags,
      'updatedAt',ce.updated_at
    ) order by case when coalesce(ce.metadata->>'sortOrder','') ~ '^[0-9]+$' then (ce.metadata->>'sortOrder')::int else 999 end,ce.title),'[]'::jsonb)
  ) into result
  from public.content_entries ce
  where ce.content_type='faq' and ce.locale=resolved_locale and ce.status='published' and ce.deleted_at is null
    and (ce.published_at is null or ce.published_at<=timezone('utc',now()));

  return coalesce(result,jsonb_build_object('locale',resolved_locale,'fallbackUsed',resolved_locale<>requested_locale,'total',0,'items','[]'::jsonb));
end;
$function$;

CREATE OR REPLACE FUNCTION private.list_public_producers_v1(p_query text DEFAULT NULL::text, p_province text DEFAULT NULL::text, p_district text DEFAULT NULL::text, p_village text DEFAULT NULL::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare q text:=lower(btrim(coalesce(p_query,''))); result jsonb;
begin
  if char_length(q)>100 or p_limit not between 1 and 50 or p_offset<0 then raise exception 'invalid_producer_directory_request' using errcode='22023'; end if;
  with base as (
    select p.id,p.slug,p.display_name,p.description,p.logo_path,p.cover_path,p.rating_average,p.rating_count,p.production_location,
      p.production_country_code,p.production_province,p.production_district,p.production_village,p.origin_verified,p.created_at,
      private.is_producer_trust_badge_active_v1(p.id) badge_active,
      (select count(*) from public.products product where product.producer_id=p.id and product.status='published' and product.is_active=true and product.deleted_at is null) product_count
    from public.producers p where p.status='active' and p.is_verified=true and p.deleted_at is null
      and (q='' or lower(p.display_name) like '%'||q||'%' or lower(coalesce(p.production_location,'')) like '%'||q||'%' or lower(coalesce(p.production_village,'')) like '%'||q||'%' or lower(coalesce(p.production_district,'')) like '%'||q||'%' or lower(coalesce(p.production_province,'')) like '%'||q||'%')
      and (nullif(btrim(coalesce(p_province,'')),'') is null or lower(coalesce(p.production_province,''))=lower(btrim(p_province)))
      and (nullif(btrim(coalesce(p_district,'')),'') is null or lower(coalesce(p.production_district,''))=lower(btrim(p_district)))
      and (nullif(btrim(coalesce(p_village,'')),'') is null or lower(coalesce(p.production_village,''))=lower(btrim(p_village)))
  ), page as (select * from base order by rating_average desc,rating_count desc,display_name limit p_limit offset p_offset)
  select jsonb_build_object('total',(select count(*) from base),'limit',p_limit,'offset',p_offset,
    'items',coalesce((select jsonb_agg(jsonb_build_object(
      'id',id,'slug',slug,'display_name',display_name,'description',description,'logo_path',logo_path,'cover_path',cover_path,
      'rating_average',rating_average,'rating_count',rating_count,'product_count',product_count,'location_label',production_location,
      'location',jsonb_build_object('country_code',production_country_code,'province',production_province,'district',production_district,'village',production_village),
      'verified',badge_active,'origin_verified',origin_verified and badge_active
    ) order by rating_average desc,rating_count desc,display_name) from page),'[]'::jsonb)) into result;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.list_public_production_locations_v1(p_country_code text DEFAULT 'TR'::text, p_province text DEFAULT NULL::text, p_district text DEFAULT NULL::text, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  country_value text:=upper(btrim(coalesce(p_country_code,'TR')));
  province_value text:=nullif(btrim(coalesce(p_province,'')),'');
  district_value text:=nullif(btrim(coalesce(p_district,'')),'');
  result jsonb;
begin
  if country_value !~ '^[A-Z]{2}$' then raise exception 'invalid_country_code' using errcode='22023'; end if;
  if p_limit not between 1 and 200 then raise exception 'invalid_limit' using errcode='22023'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'countryCode',row.country_code,'province',row.province,'district',row.district,'village',row.village
  ) order by row.province,row.district,row.village),'[]'::jsonb)
  into result
  from (
    select distinct producer.production_country_code country_code,producer.production_province province,
      producer.production_district district,producer.production_village village
    from public.producers producer
    where producer.status='active' and producer.is_verified=true and producer.origin_verified=true and producer.deleted_at is null
      and producer.production_country_code=country_value
      and producer.production_province is not null and producer.production_district is not null and producer.production_village is not null
      and (province_value is null or lower(producer.production_province)=lower(province_value))
      and (district_value is null or lower(producer.production_district)=lower(district_value))
    order by producer.production_province,producer.production_district,producer.production_village
    limit p_limit
  ) row;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.management_add_order_item_preparation_event_v1(p_order_item_id uuid, p_event_type text, p_note text, p_visible_to_customer boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); item public.order_items%rowtype; owner_id uuid; order_user_id uuid; order_id_value uuid; product_slug text; event_id uuid; label text;
begin if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if; select * into item from public.order_items where id=p_order_item_id; if item.id is null then raise exception 'order_item_not_found' using errcode='P0002'; end if; select owner_user_id into owner_id from public.producers where id=item.producer_id; if owner_id is distinct from caller_id and not coalesce(private.has_permission('order.update'),false) then raise exception 'order_owner_or_admin_required' using errcode='42501'; end if; if p_event_type not in ('accepted','harvest_planned','catch_planned','preparing','packed','ready','note') then raise exception 'invalid_preparation_event_type' using errcode='22023'; end if; if char_length(coalesce(p_note,''))>1000 then raise exception 'preparation_note_too_long' using errcode='22023'; end if; insert into public.order_item_preparation_events(order_item_id,event_type,note,visible_to_customer,actor_user_id) values(item.id,p_event_type,nullif(btrim(coalesce(p_note,'')),''),coalesce(p_visible_to_customer,true),caller_id) returning id into event_id; if coalesce(p_visible_to_customer,true) then select o.user_id,o.id,p.slug into order_user_id,order_id_value,product_slug from public.orders o join public.products p on p.id=item.product_id where o.id=item.order_id; label:=case p_event_type when 'accepted' then 'Sipariş hazırlığa alındı' when 'harvest_planned' then 'Hasat planlandı' when 'catch_planned' then 'Av planlandı' when 'preparing' then 'Ürün hazırlanıyor' when 'packed' then 'Paketleme tamamlandı' when 'ready' then 'Ürün gönderime hazır' else 'Siparişinizden haber var' end; insert into public.notifications(user_id,type,title,message,action_url,metadata) values(order_user_id,'order_preparation',label,item.product_name||case when nullif(btrim(coalesce(p_note,'')),'') is null then ' için hazırlık durumu güncellendi.' else ': '||btrim(p_note) end,'/?tab=account&view=orders:'||order_id_value::text,jsonb_build_object('orderId',order_id_value,'orderItemId',item.id,'productSlug',product_slug,'eventType',p_event_type)); end if; return jsonb_build_object('id',event_id,'orderItemId',item.id,'eventType',p_event_type,'visibleToCustomer',coalesce(p_visible_to_customer,true)); end;$function$;

CREATE OR REPLACE FUNCTION private.management_archive_category_v1(p_reference text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  v_category_id uuid := private.resolve_category_id_v1(p_reference);
begin
  if caller_id is null or not coalesce(private.has_permission('content.update'),false) then
    raise exception 'admin_required' using errcode = '42501';
  end if;
  if v_category_id is null then
    raise exception 'category_not_found' using errcode = 'P0002';
  end if;
  if exists (
    select 1
    from public.products product
    where product.category_id = v_category_id
      and product.status = 'published'
      and product.is_active = true
      and product.deleted_at is null
  ) then
    raise exception 'category_has_published_products' using errcode = '23503';
  end if;
  update public.categories set is_active = false where id = v_category_id;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION private.management_archive_content_v1(p_reference text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
begin
  if caller_id is null or not coalesce(private.has_permission('content.update'),false) then
    raise exception 'admin_required' using errcode = '42501';
  end if;
  update public.content_entries
  set status = 'archived', deleted_at = timezone('utc', now())
  where id::text = btrim(coalesce(p_reference, '')) or legacy_id = btrim(coalesce(p_reference, ''));
  if not found then raise exception 'content_not_found' using errcode = 'P0002'; end if;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION private.management_archive_event_v1(p_reference text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
begin
  if caller_id is null or not coalesce(private.has_permission('event.manage'),false) then
    raise exception 'admin_required' using errcode = '42501';
  end if;
  update public.events set status = 'cancelled'
  where id::text = btrim(coalesce(p_reference, '')) or legacy_id = btrim(coalesce(p_reference, ''));
  if not found then raise exception 'event_not_found' using errcode = 'P0002'; end if;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION private.management_archive_product_v1(p_reference text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  caller_is_admin boolean;
  caller_producer_id uuid;
  v_product_id uuid := private.resolve_product_id_v1(p_reference);
  target_product public.products%rowtype;
begin
  if caller_id is null or v_product_id is null then
    raise exception 'product_not_found' using errcode = 'P0002';
  end if;
  if not private.has_permission('product.archive') then raise exception 'permission_required:product.archive' using errcode='42501'; end if;
  caller_is_admin := coalesce(private.has_permission('admin.access'),false);
  select producer.id into caller_producer_id
  from public.producers producer
  where producer.owner_user_id = caller_id and producer.deleted_at is null
  order by producer.created_at desc limit 1;
  select * into target_product from public.products product where product.id = v_product_id for update;
  if not caller_is_admin and target_product.producer_id <> caller_producer_id then
    raise exception 'product_access_denied' using errcode = '42501';
  end if;
  update public.products
  set status = 'archived', is_active = false, deleted_at = timezone('utc', now())
  where id = v_product_id;
  update public.product_change_requests
  set status = 'withdrawn', reviewed_at = timezone('utc', now()), reviewed_by = caller_id
  where product_change_requests.product_id = v_product_id and status = 'pending';
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION private.management_cancel_event_reservation_v1(p_reservation_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
begin
  if caller_id is null or not coalesce(private.has_permission('event.manage'),false) then
    raise exception 'admin_required' using errcode = '42501';
  end if;
  update public.event_reservations
  set status = 'cancelled'
  where id = p_reservation_id and status <> 'cancelled';
  if not found then raise exception 'reservation_not_found_or_cancelled' using errcode = 'P0002'; end if;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION private.management_catalog_snapshot_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  caller_is_admin boolean;
  caller_producer_id uuid;
begin
  if caller_id is null then
    raise exception 'authentication_required' using errcode = '42501';
  end if;

  caller_is_admin := coalesce(private.has_permission('product.read'),false);
  select producer.id into caller_producer_id
  from public.producers producer
  where producer.owner_user_id = caller_id
    and producer.deleted_at is null
    and producer.status in ('active', 'suspended')
  order by producer.created_at desc
  limit 1;

  if not caller_is_admin and caller_producer_id is null then
    raise exception 'management_role_required' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'products', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', coalesce(product.legacy_id, product.id::text),
          'databaseId', product.id,
          'name', product.name,
          'description', product.description,
          'price', product.base_price_minor::numeric / 100,
          'originalPrice', coalesce(product.compare_at_price_minor, product.base_price_minor)::numeric / 100,
          'category', category.name,
          'categoryId', category.slug,
          'tags', product.tags,
          'reviews', coalesce(review_summary.review_count, 0),
          'rating', coalesce(review_summary.rating_average, 0),
          'stock', coalesce(inventory_summary.available_stock, 0),
          'image', image_summary.primary_image,
          'gallery', coalesce(image_summary.gallery, '[]'::jsonb),
          'story', product.story,
          'features', product.features,
          'producer', producer.display_name,
          'origin', product.origin,
          'unit', product.unit_label,
          'weight', product.specifications -> 'originalWeight',
          'weightOptions', coalesce(product.specifications -> 'weightOptions', '[]'::jsonb),
          'cutOptions', coalesce(product.specifications -> 'cutOptions', '[]'::jsonb),
          'preOrder', product.stock_mode = 'preorder',
          'preOrderTime', product.specifications ->> 'preOrderTime',
          'pricePrefix', product.specifications ->> 'pricePrefix',
          'video', product.specifications ->> 'video',
          'section', product.specifications ->> 'section',
          'homeSection', product.specifications ->> 'homeSection',
          'vendor_id', product.producer_id,
          'is_approved', product.status = 'published',
          'is_active', product.is_active,
          'is_rejected', product.status = 'rejected',
          'rejection_reason', product.specifications ->> 'rejectionReason',
          'verificationStatus', coalesce(product.specifications ->> 'verificationStatus', 'pending_documents'),
          'claimReviewStatus', coalesce(product.specifications ->> 'claimReviewStatus', 'not_verified'),
          'status', product.status,
          'hasPendingChanges', exists (
            select 1
            from public.product_change_requests change_request
            where change_request.product_id = product.id
              and change_request.status = 'pending'
          )
        )
        order by product.created_at desc
      )
      from public.products product
      join public.categories category on category.id = product.category_id
      join public.producers producer on producer.id = product.producer_id
      left join lateral (
        select
          max(image.storage_path) filter (where image.is_primary) as primary_image,
          jsonb_agg(image.storage_path order by image.is_primary desc, image.sort_order, image.created_at) as gallery
        from public.product_images image
        where image.product_id = product.id
      ) image_summary on true
      left join lateral (
        select coalesce(sum(greatest(inventory.available_quantity - inventory.reserved_quantity, 0)), 0)::integer as available_stock
        from public.product_variants variant
        join public.product_inventory inventory on inventory.variant_id = variant.id
        where variant.product_id = product.id
          and variant.is_active = true
      ) inventory_summary on true
      left join lateral (
        select count(*)::integer as review_count, round(avg(review.rating)::numeric, 2) as rating_average
        from public.reviews review
        where review.product_id = product.id
          and review.status = 'published'
      ) review_summary on true
      where product.deleted_at is null
        and (caller_is_admin or product.producer_id = caller_producer_id)
    ), '[]'::jsonb),
    'categories', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', category.slug,
          'databaseId', category.id,
          'name', category.name,
          'description', category.description,
          'icon', coalesce(category.icon, 'Leaf'),
          'image', coalesce(category.image_path, ''),
          'targetCategory', category.slug,
          'is_active', category.is_active,
          'sortOrder', category.sort_order
        )
        order by category.sort_order, category.name
      )
      from public.categories category
      where caller_is_admin or category.is_active = true
    ), '[]'::jsonb),
    'events', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', coalesce(event.legacy_id, event.id::text),
          'databaseId', event.id,
          'title', event.title,
          'date', event.starts_at,
          'location', event.location_name,
          'description', event.description,
          'image', coalesce(event.image_path, ''),
          'status', event.status
        )
        order by event.starts_at desc
      )
      from public.events event
      where caller_is_admin or event.status in ('published', 'sold_out')
    ), '[]'::jsonb),
    'eventReservations', case when caller_is_admin then coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', reservation.id,
          'eventId', coalesce(event.legacy_id, event.id::text),
          'name', reservation.guest_name,
          'email', reservation.guest_email,
          'phone', reservation.guest_phone,
          'guests', reservation.guest_count,
          'date', reservation.created_at,
          'status', reservation.status
        )
        order by reservation.created_at desc
      )
      from public.event_reservations reservation
      join public.events event on event.id = reservation.event_id
    ), '[]'::jsonb) else '[]'::jsonb end,
    'content', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', coalesce(entry.legacy_id, entry.id::text),
          'databaseId', entry.id,
          'contentType', entry.content_type,
          'title', entry.title,
          'summary', entry.summary,
          'content', entry.body_markdown,
          'image', coalesce(entry.hero_image_path, ''),
          'date', coalesce(entry.metadata ->> 'originalDate', entry.published_at::text, entry.created_at::text),
          'category', entry.metadata ->> 'originalCategory',
          'productId', coalesce(product.legacy_id, product.id::text),
          'status', entry.status
        )
        order by entry.created_at desc
      )
      from public.content_entries entry
      left join public.products product on product.id = entry.related_product_id
      where entry.deleted_at is null
        and (caller_is_admin or entry.status = 'published')
    ), '[]'::jsonb),
    'role', case when caller_is_admin then 'admin' else 'producer' end,
    'producerId', caller_producer_id,
    'loadedAt', timezone('utc', now())
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.management_catalog_snapshot_v2()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  base jsonb:=private.management_catalog_snapshot_v1();
  products_payload jsonb;
  stores_payload jsonb:='[]'::jsonb;
begin
  select coalesce(jsonb_agg(
    item || jsonb_build_object(
      'storeKind',coalesce(producer.store_kind,'independent'),
      'provenance',case when provenance.product_id is null then null else jsonb_build_object(
        'sellerModel',provenance.seller_model,
        'sourceMode',provenance.source_mode,
        'sourceDisplayName',provenance.source_display_name,
        'sourceCountryCode',provenance.country_code,
        'sourceProvince',provenance.province,
        'sourceDistrict',provenance.district,
        'sourceVillage',provenance.village,
        'sourceLocality',provenance.locality_detail,
        'originLabel',provenance.origin_label,
        'originVerified',provenance.origin_verified,
        'organicClaim',provenance.organic_claim
      ) end
    ) order by ordinality
  ),'[]'::jsonb)
  into products_payload
  from jsonb_array_elements(coalesce(base->'products','[]'::jsonb)) with ordinality rows(item,ordinality)
  left join public.products product on product.id=(item->>'databaseId')::uuid
  left join public.producers producer on producer.id=product.producer_id
  left join public.product_provenance provenance on provenance.product_id=product.id;

  if base->>'role'='admin' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id',producer.id,
      'name',producer.display_name,
      'slug',producer.slug,
      'storeKind',producer.store_kind,
      'verified',producer.is_verified,
      'originVerified',producer.origin_verified,
      'location',jsonb_build_object(
        'countryCode',producer.production_country_code,
        'province',producer.production_province,
        'district',producer.production_district,
        'village',producer.production_village,
        'label',producer.production_location
      )
    ) order by case when producer.store_kind='official' then 0 else 1 end,producer.display_name),'[]'::jsonb)
    into stores_payload
    from public.producers producer
    where producer.deleted_at is null and producer.status='active' and producer.is_verified=true
      and (producer.store_kind='official' or (producer.store_kind='independent' and producer.owner_user_id is not null));
  end if;

  base:=jsonb_set(base,'{products}',products_payload,true);
  return jsonb_set(base,'{stores}',stores_payload,true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.management_catalog_snapshot_v3()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  base jsonb:=private.management_catalog_snapshot_v2();
  products_payload jsonb;
begin
  select coalesce(jsonb_agg(item || jsonb_build_object('commerce',private.product_commerce_payload_v1((item->>'databaseId')::uuid)) order by ordinality),'[]'::jsonb)
  into products_payload from jsonb_array_elements(coalesce(base->'products','[]'::jsonb)) with ordinality rows(item,ordinality);
  return jsonb_set(base,'{products}',products_payload,true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.management_orders_snapshot_v2()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  caller_is_admin boolean;
  caller_producer_id uuid;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  caller_is_admin:=coalesce(private.has_permission('order.read'),false);
  select producer.id into caller_producer_id
  from public.producers producer
  where producer.owner_user_id=caller_id
    and producer.deleted_at is null
    and producer.status in ('active','suspended')
  order by producer.created_at desc
  limit 1;
  if not caller_is_admin and caller_producer_id is null then raise exception 'management_role_required' using errcode='42501'; end if;

  return jsonb_build_object(
    'orders',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',customer_order.id,
        'orderNumber',customer_order.order_number,
        'customer',case when caller_is_admin then coalesce(nullif(profile.display_name,''),auth_user.email,'Müşteri') else coalesce(nullif(profile.display_name,''),customer_order.shipping_address->>'recipientName',customer_order.shipping_address->>'recipient_name','Müşteri') end,
        'customerEmail',case when caller_is_admin then auth_user.email else null end,
        'date',coalesce(customer_order.placed_at,customer_order.created_at),
        'status',customer_order.status,
        'paymentStatus',customer_order.payment_status,
        'fulfillmentStatus',customer_order.fulfillment_status,
        'currency',customer_order.currency,
        'total',(case when caller_is_admin then customer_order.total_minor else coalesce(item_summary.producer_total_minor,0) end)::numeric/100,
        'totalMinor',case when caller_is_admin then customer_order.total_minor else coalesce(item_summary.producer_total_minor,0) end,
        'reservationExpiresAt',customer_order.reservation_expires_at,
        'shippingAddress',customer_order.shipping_address,
        'customerNote',customer_order.customer_note,
        'items',coalesce(item_summary.items,'[]'::jsonb),
        'gift',case when gift.order_id is null then null else jsonb_strip_nulls(jsonb_build_object(
          'recipientName',gift.recipient_name,
          'message',gift.gift_message,
          'senderName',gift.sender_name,
          'hidePrice',gift.hide_price,
          'occasion',gift.occasion,
          'presentationStyle',gift.presentation_style,
          'cardTitle',gift.card_title
        )) end,
        'paymentMethod',case when caller_is_admin and payment_pref.order_id is not null then jsonb_strip_nulls(jsonb_build_object(
          'provider',payment_pref.provider,
          'brand',payment_method.brand,
          'last4',payment_method.last4,
          'nickname',payment_method.nickname,
          'expMonth',payment_method.exp_month,
          'expYear',payment_method.exp_year,
          'status',payment_method.status
        )) else null end,
        'returnStatus',case when return_request.status in ('requested','under_review') then 'Requested' when return_request.status in ('approved','in_transit','received') then 'Approved' when return_request.status='rejected' then 'Rejected' when return_request.status in ('refunded','closed') then 'Completed' else null end,
        'returnReason',return_request.customer_message,
        'returnId',return_request.id,
        'vendorId',case when caller_is_admin then null else caller_producer_id end,
        'userId',customer_order.user_id,
        'trackingNumber',shipment.tracking_number,
        'trackingUrl',shipment.tracking_url
      ) order by customer_order.created_at desc)
      from public.orders customer_order
      join public.profiles profile on profile.id=customer_order.user_id
      join auth.users auth_user on auth_user.id=customer_order.user_id
      left join lateral (
        select sum(item.line_total_minor) as producer_total_minor,
          jsonb_agg(jsonb_build_object(
            'id',item.id,'productId',item.product_id,'name',item.product_name,'title',item.product_name,'variantName',item.variant_name,'image',item.image_path,
            'quantity',item.quantity,'price',item.unit_price_minor::numeric/100,'lineTotal',item.line_total_minor::numeric/100,'fulfillmentStatus',item.fulfillment_status,'producerId',item.producer_id
          ) order by item.created_at) as items
        from public.order_items item
        where item.order_id=customer_order.id and (caller_is_admin or item.producer_id=caller_producer_id)
      ) item_summary on true
      left join private.order_gifts gift on gift.order_id=customer_order.id
      left join private.order_payment_preferences payment_pref on payment_pref.order_id=customer_order.id
      left join private.customer_payment_methods payment_method on payment_method.id=payment_pref.payment_method_id and payment_method.user_id=customer_order.user_id
      left join lateral (
        select request.id,request.status,request.customer_message
        from public.return_requests request where request.order_id=customer_order.id order by request.created_at desc limit 1
      ) return_request on true
      left join lateral (
        select delivery.tracking_number,delivery.tracking_url
        from public.shipments delivery where delivery.order_id=customer_order.id order by delivery.created_at desc limit 1
      ) shipment on true
      where caller_is_admin or (
        customer_order.status not in ('draft','pending_payment') and exists(
          select 1 from public.order_items own_item where own_item.order_id=customer_order.id and own_item.producer_id=caller_producer_id
        )
      )
    ),'[]'::jsonb),
    'role',case when caller_is_admin then 'admin' else 'producer' end,
    'producerId',caller_producer_id,
    'loadedAt',timezone('utc',now())
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.management_orders_snapshot_v3()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  base jsonb:=private.management_orders_snapshot_v2();
  orders_payload jsonb;
begin
  select coalesce(jsonb_agg(order_item||jsonb_build_object('items',coalesce(enriched.items,'[]'::jsonb)) order by order_ordinality),'[]'::jsonb)
  into orders_payload
  from jsonb_array_elements(coalesce(base->'orders','[]'::jsonb)) with ordinality order_rows(order_item,order_ordinality)
  left join lateral (
    select jsonb_agg(
      item || jsonb_build_object(
        'variantName',left(coalesce(item->>'variantName','Standart varyant')||case when private.order_customization_summary_v1(coalesce(db_item.snapshot->'selected_options','{}'::jsonb))<>'' then ' · '||private.order_customization_summary_v1(coalesce(db_item.snapshot->'selected_options','{}'::jsonb)) else '' end,240),
        'selectedOptions',coalesce(db_item.snapshot->'selected_options','{}'::jsonb),
        'preparationEvents',coalesce(events.items,'[]'::jsonb),
        'fulfillmentStatus',left(coalesce(item->>'fulfillmentStatus','unfulfilled')||case when events.latest_label is not null then ' · '||events.latest_label else '' end,60)
      ) order by item_ordinality
    ) as items
    from jsonb_array_elements(coalesce(order_item->'items','[]'::jsonb)) with ordinality item_rows(item,item_ordinality)
    left join public.order_items db_item on db_item.id=(item->>'id')::uuid
    left join lateral (
      select jsonb_agg(jsonb_build_object('id',e.id,'eventType',e.event_type,'note',e.note,'visibleToCustomer',e.visible_to_customer,'createdAt',e.created_at) order by e.created_at,e.id) items,
        (array_agg(case e.event_type when 'accepted' then 'sipariş kabul edildi' when 'harvest_planned' then 'hasat planlandı' when 'catch_planned' then 'av planlandı' when 'preparing' then 'hazırlanıyor' when 'packed' then 'paketlendi' when 'ready' then 'gönderime hazır' else 'hazırlık notu' end order by e.created_at desc,e.id desc))[1] latest_label
      from public.order_item_preparation_events e where e.order_item_id=db_item.id
    ) events on true
  ) enriched on true;
  return jsonb_set(base,'{orders}',orders_payload,true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.management_orders_snapshot_v4()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare base jsonb; enriched jsonb; caller_is_admin boolean:=coalesce(private.has_permission('order.read'),false); caller_can_release boolean:=coalesce(private.has_permission('payout.release'),false); begin base:=private.management_orders_snapshot_v3(); if not caller_is_admin then return base; end if; select coalesce(jsonb_agg(jsonb_set(row_item,'{settlement}',private.order_settlement_state_v1((row_item->>'id')::uuid)||jsonb_build_object('canRelease',caller_can_release),true) order by ordinality),'[]'::jsonb) into enriched from jsonb_array_elements(coalesce(base->'orders','[]'::jsonb)) with ordinality rows(row_item,ordinality); return jsonb_set(base,'{orders}',enriched,true); end;$function$;

CREATE OR REPLACE FUNCTION private.management_product_commerce_editor_v1(p_product_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  product_row public.products%rowtype;
  owner_id uuid;
  profile public.product_commerce_profiles%rowtype;
  can_approve boolean:=false;
begin
  if caller_id is null or not coalesce(private.has_permission('product.update'),false) then raise exception 'permission_required:product.update' using errcode='42501'; end if;
  select * into product_row from public.products where id=p_product_id and deleted_at is null;
  if product_row.id is null then raise exception 'product_not_found' using errcode='P0002'; end if;
  select owner_user_id into owner_id from public.producers where id=product_row.producer_id;
  can_approve:=coalesce(private.has_permission('product.approve'),false);
  if owner_id is distinct from caller_id and not can_approve then raise exception 'product_owner_or_admin_required' using errcode='42501'; end if;
  select * into profile from public.product_commerce_profiles where product_id=product_row.id;
  return jsonb_build_object(
    'product',jsonb_build_object('id',product_row.id,'name',product_row.name,'slug',product_row.slug,'stockMode',product_row.stock_mode,'status',product_row.status,'preorderLeadDays',product_row.preorder_lead_days),
    'profile',case when profile.product_id is null then jsonb_build_object('optionSchema','[]'::jsonb,'seasonalityMode','year_round','seasonStartMonth',null,'seasonEndMonth',null,'preorderEnabled',product_row.stock_mode='preorder','preparationDaysMin',null,'preparationDaysMax',product_row.preorder_lead_days,'customerSeasonNote',null,'researchBasis',null,'researchSourceLabel',null) else jsonb_build_object('optionSchema',profile.option_schema,'seasonalityMode',profile.seasonality_mode,'seasonStartMonth',profile.season_start_month,'seasonEndMonth',profile.season_end_month,'preorderEnabled',profile.preorder_enabled,'preparationDaysMin',profile.preparation_days_min,'preparationDaysMax',profile.preparation_days_max,'customerSeasonNote',profile.customer_season_note,'researchBasis',profile.research_basis,'researchSourceLabel',profile.research_source_label,'updatedAt',profile.updated_at) end,
    'variants',private.product_price_variants_payload_v1(product_row.id),
    'canManageLivePricing',(product_row.status<>'published' or can_approve),
    'windows',coalesce((select jsonb_agg(jsonb_build_object('id',w.id,'seasonYear',w.season_year,'opensAt',w.preorder_opens_at,'closesAt',w.preorder_closes_at,'fulfillmentStartsAt',w.fulfillment_starts_at,'fulfillmentEndsAt',w.fulfillment_ends_at,'status',w.status,'confirmed',w.is_confirmed,'publicNote',w.public_note,'internalNote',w.internal_note) order by w.season_year desc,w.created_at desc) from public.product_sales_windows w where w.product_id=product_row.id),'[]'::jsonb),
    'canConfirmWindow',can_approve
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.management_save_product_commerce_profile_v1(p_product_id uuid, p_profile jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); product_row public.products%rowtype; producer_owner uuid; normalized_schema jsonb; mode_value text; start_month integer; end_month integer; prep_min integer; prep_max integer; result public.product_commerce_profiles%rowtype;
begin if caller_id is null or not coalesce(private.has_permission('product.update'),false) then raise exception 'permission_required:product.update' using errcode='42501'; end if; if p_profile is null or jsonb_typeof(p_profile)<>'object' or pg_column_size(p_profile)>32768 then raise exception 'invalid_product_commerce_profile' using errcode='22023'; end if; select * into product_row from public.products where id=p_product_id and deleted_at is null; if product_row.id is null then raise exception 'product_not_found' using errcode='P0002'; end if; select owner_user_id into producer_owner from public.producers where id=product_row.producer_id; if producer_owner is distinct from caller_id and not coalesce(private.has_permission('product.approve'),false) then raise exception 'product_owner_or_admin_required' using errcode='42501'; end if; normalized_schema:=private.normalize_product_option_schema_v1(coalesce(p_profile->'optionSchema','[]'::jsonb)); mode_value:=coalesce(nullif(btrim(p_profile->>'seasonalityMode'),''),'year_round'); if mode_value not in ('year_round','seasonal','made_to_order') then raise exception 'invalid_seasonality_mode' using errcode='22023'; end if; start_month:=nullif(p_profile->>'seasonStartMonth','')::integer; end_month:=nullif(p_profile->>'seasonEndMonth','')::integer; prep_min:=nullif(p_profile->>'preparationDaysMin','')::integer; prep_max:=nullif(p_profile->>'preparationDaysMax','')::integer; if start_month is not null and start_month not between 1 and 12 then raise exception 'invalid_season_start_month' using errcode='22023'; end if; if end_month is not null and end_month not between 1 and 12 then raise exception 'invalid_season_end_month' using errcode='22023'; end if; if prep_min is not null and prep_min not between 0 and 365 then raise exception 'invalid_preparation_days' using errcode='22023'; end if; if prep_max is not null and prep_max not between coalesce(prep_min,0) and 365 then raise exception 'invalid_preparation_days' using errcode='22023'; end if; insert into public.product_commerce_profiles(product_id,option_schema,seasonality_mode,season_start_month,season_end_month,preorder_enabled,preparation_days_min,preparation_days_max,customer_season_note,research_basis,research_source_label,updated_by,updated_at) values(product_row.id,normalized_schema,mode_value,start_month,end_month,coalesce((p_profile->>'preorderEnabled')::boolean,false),prep_min,prep_max,nullif(btrim(coalesce(p_profile->>'customerSeasonNote','')),''),nullif(btrim(coalesce(p_profile->>'researchBasis','')),''),nullif(btrim(coalesce(p_profile->>'researchSourceLabel','')),''),caller_id,timezone('utc',now())) on conflict(product_id) do update set option_schema=excluded.option_schema,seasonality_mode=excluded.seasonality_mode,season_start_month=excluded.season_start_month,season_end_month=excluded.season_end_month,preorder_enabled=excluded.preorder_enabled,preparation_days_min=excluded.preparation_days_min,preparation_days_max=excluded.preparation_days_max,customer_season_note=excluded.customer_season_note,research_basis=excluded.research_basis,research_source_label=excluded.research_source_label,updated_by=caller_id,updated_at=timezone('utc',now()) returning * into result; update public.products set preorder_lead_days=case when result.preorder_enabled then coalesce(result.preparation_days_max,result.preparation_days_min,preorder_lead_days) else preorder_lead_days end,updated_at=timezone('utc',now()) where id=product_row.id; return private.product_commerce_payload_v1(product_row.id); end;$function$;

CREATE OR REPLACE FUNCTION private.management_save_product_price_variants_v1(p_product_id uuid, p_variants jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  product_row public.products%rowtype;
  owner_id uuid;
  item jsonb;
  item_id uuid;
  existing public.product_variants%rowtype;
  sku_value text;
  name_value text;
  price_value bigint;
  compare_value bigint;
  weight_value integer;
  active_value boolean;
  default_value boolean;
  expected_updated_at timestamptz;
  active_default_count integer:=0;
  item_count integer:=0;
  seen_skus text[]:='{}';
  saved_ids uuid[]:='{}';
  saved_id uuid;
  default_price bigint;
begin
  if caller_id is null or not coalesce(private.has_permission('product.update'),false) then
    raise exception 'permission_required:product.update' using errcode='42501';
  end if;
  if p_variants is null or jsonb_typeof(p_variants)<>'array' or jsonb_array_length(p_variants) not between 1 and 12 or pg_column_size(p_variants)>65536 then
    raise exception 'invalid_product_price_variants' using errcode='22023';
  end if;

  select * into product_row from public.products where id=p_product_id and deleted_at is null for update;
  if product_row.id is null then raise exception 'product_not_found' using errcode='P0002'; end if;
  select owner_user_id into owner_id from public.producers where id=product_row.producer_id;
  if owner_id is distinct from caller_id and not coalesce(private.has_permission('product.approve'),false) then
    raise exception 'product_owner_or_admin_required' using errcode='42501';
  end if;
  if product_row.status='published' and not coalesce(private.has_permission('product.approve'),false) then
    raise exception 'permission_required:product.approve' using errcode='42501';
  end if;

  for item in select value from jsonb_array_elements(p_variants)
  loop
    item_count:=item_count+1;
    if jsonb_typeof(item)<>'object' or exists(
      select 1 from jsonb_object_keys(item) key
      where key<>all(array['id','sku','name','priceMinor','compareAtPriceMinor','weightGrams','default','active','updatedAt']::text[])
    ) then raise exception 'invalid_product_price_variant:%',item_count using errcode='22023'; end if;

    begin item_id:=nullif(btrim(coalesce(item->>'id','')),'')::uuid; exception when others then raise exception 'invalid_product_price_variant_id:%',item_count using errcode='22023'; end;
    sku_value:=upper(btrim(coalesce(item->>'sku','')));
    name_value:=btrim(coalesce(item->>'name',''));
    begin price_value:=(item->>'priceMinor')::bigint; exception when others then raise exception 'invalid_product_price_variant_price:%',item_count using errcode='22023'; end;
    begin compare_value:=nullif(item->>'compareAtPriceMinor','')::bigint; exception when others then raise exception 'invalid_product_price_variant_compare_price:%',item_count using errcode='22023'; end;
    begin weight_value:=(item->>'weightGrams')::integer; exception when others then raise exception 'invalid_product_price_variant_weight:%',item_count using errcode='22023'; end;
    if item ? 'active' and jsonb_typeof(item->'active')<>'boolean' then raise exception 'invalid_product_price_variant_active:%',item_count using errcode='22023'; end if;
    if item ? 'default' and jsonb_typeof(item->'default')<>'boolean' then raise exception 'invalid_product_price_variant_default:%',item_count using errcode='22023'; end if;
    active_value:=coalesce((item->>'active')::boolean,true);
    default_value:=coalesce((item->>'default')::boolean,false);

    if sku_value !~ '^[A-Z0-9][A-Z0-9._-]{2,79}$' then raise exception 'invalid_product_price_variant_sku:%',item_count using errcode='22023'; end if;
    if char_length(name_value) not between 1 and 120 then raise exception 'invalid_product_price_variant_name:%',item_count using errcode='22023'; end if;
    if price_value not between 0 and 1000000000 then raise exception 'invalid_product_price_variant_price:%',item_count using errcode='22023'; end if;
    if compare_value is not null and (compare_value<price_value or compare_value>1000000000) then raise exception 'invalid_product_price_variant_compare_price:%',item_count using errcode='22023'; end if;
    if weight_value not between 1 and 1000000 then raise exception 'invalid_product_price_variant_weight:%',item_count using errcode='22023'; end if;
    if default_value and not active_value then raise exception 'inactive_product_price_variant_cannot_be_default:%',item_count using errcode='22023'; end if;
    if sku_value=any(seen_skus) then raise exception 'duplicate_product_price_variant_sku:%',sku_value using errcode='22023'; end if;
    seen_skus:=array_append(seen_skus,sku_value);
    if active_value and default_value then active_default_count:=active_default_count+1; end if;

    if item_id is not null then
      select * into existing from public.product_variants where id=item_id;
      if existing.id is null or existing.product_id<>product_row.id then raise exception 'product_price_variant_not_owned:%',item_id using errcode='42501'; end if;
      begin expected_updated_at:=nullif(item->>'updatedAt','')::timestamptz; exception when others then raise exception 'invalid_product_price_variant_revision:%',item_count using errcode='22023'; end;
      if expected_updated_at is null or existing.updated_at is distinct from expected_updated_at then
        raise exception 'stale_product_price_variant:%',item_id using errcode='40001';
      end if;
    end if;
  end loop;

  if active_default_count<>1 then raise exception 'exactly_one_active_default_product_price_variant_required' using errcode='22023'; end if;

  update public.product_variants set is_default=false,updated_at=timezone('utc',now())
  where product_id=product_row.id and is_default=true;

  for item in select value from jsonb_array_elements(p_variants)
  loop
    item_id:=nullif(btrim(coalesce(item->>'id','')),'')::uuid;
    sku_value:=upper(btrim(item->>'sku'));
    name_value:=btrim(item->>'name');
    price_value:=(item->>'priceMinor')::bigint;
    compare_value:=nullif(item->>'compareAtPriceMinor','')::bigint;
    weight_value:=(item->>'weightGrams')::integer;
    active_value:=coalesce((item->>'active')::boolean,true);
    default_value:=coalesce((item->>'default')::boolean,false);

    if item_id is null then
      insert into public.product_variants(product_id,sku,name,option_values,price_minor,compare_at_price_minor,weight_grams,is_default,is_active,shipping_weight_source,shipping_weight_note)
      values(product_row.id,sku_value,name_value,jsonb_build_object('packageVariant',true),price_value,compare_value,weight_value,default_value,active_value,'estimated','Admin fiyat/paket varyantı. Sevkiyat ağırlığı gerektiğinde ölçümle doğrulanır.')
      returning id into saved_id;
      insert into public.product_inventory(variant_id,available_quantity,reserved_quantity,reorder_level,version)
      values(saved_id,0,0,0,1) on conflict(variant_id) do nothing;
    else
      update public.product_variants
      set sku=sku_value,name=name_value,price_minor=price_value,compare_at_price_minor=compare_value,weight_grams=weight_value,is_default=default_value,is_active=active_value,updated_at=timezone('utc',now())
      where id=item_id and product_id=product_row.id
      returning id into saved_id;
    end if;
    saved_ids:=array_append(saved_ids,saved_id);
  end loop;

  update public.product_variants
  set is_active=false,is_default=false,updated_at=timezone('utc',now())
  where product_id=product_row.id and not(id=any(saved_ids));

  select price_minor into default_price from public.product_variants
  where product_id=product_row.id and is_active=true and is_default=true limit 1;
  if default_price is null then raise exception 'active_default_product_price_variant_missing' using errcode='23514'; end if;

  update public.products
  set base_price_minor=default_price,updated_at=timezone('utc',now())
  where id=product_row.id;

  return private.product_price_variants_payload_v1(product_row.id);
end;
$function$;

CREATE OR REPLACE FUNCTION private.management_save_product_sales_window_v1(p_product_id uuid, p_window jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); product_row public.products%rowtype; owner_id uuid; season_year_value integer; confirmed_value boolean; result public.product_sales_windows%rowtype;
begin if caller_id is null or not coalesce(private.has_permission('product.update'),false) then raise exception 'permission_required:product.update' using errcode='42501'; end if; select * into product_row from public.products where id=p_product_id and deleted_at is null; if product_row.id is null then raise exception 'product_not_found' using errcode='P0002'; end if; select owner_user_id into owner_id from public.producers where id=product_row.producer_id; if owner_id is distinct from caller_id and not coalesce(private.has_permission('product.approve'),false) then raise exception 'product_owner_or_admin_required' using errcode='42501'; end if; if p_window is null or jsonb_typeof(p_window)<>'object' or pg_column_size(p_window)>16384 then raise exception 'invalid_product_sales_window' using errcode='22023'; end if; season_year_value:=coalesce(nullif(p_window->>'seasonYear','')::integer,extract(year from timezone('utc',now()))::integer); confirmed_value:=coalesce((p_window->>'confirmed')::boolean,false); if confirmed_value and not coalesce(private.has_permission('product.approve'),false) then raise exception 'permission_required:product.approve' using errcode='42501'; end if; insert into public.product_sales_windows(product_id,season_year,preorder_opens_at,preorder_closes_at,fulfillment_starts_at,fulfillment_ends_at,status,is_confirmed,public_note,internal_note,updated_by,updated_at) values(product_row.id,season_year_value,nullif(p_window->>'opensAt','')::timestamptz,nullif(p_window->>'closesAt','')::timestamptz,nullif(p_window->>'fulfillmentStartsAt','')::timestamptz,nullif(p_window->>'fulfillmentEndsAt','')::timestamptz,case when coalesce(p_window->>'status','scheduled') in ('scheduled','open','closed','paused') then coalesce(p_window->>'status','scheduled') else 'scheduled' end,confirmed_value,nullif(btrim(coalesce(p_window->>'publicNote','')),''),nullif(btrim(coalesce(p_window->>'internalNote','')),''),caller_id,timezone('utc',now())) on conflict(product_id,season_year) do update set preorder_opens_at=excluded.preorder_opens_at,preorder_closes_at=excluded.preorder_closes_at,fulfillment_starts_at=excluded.fulfillment_starts_at,fulfillment_ends_at=excluded.fulfillment_ends_at,status=excluded.status,is_confirmed=excluded.is_confirmed,public_note=excluded.public_note,internal_note=excluded.internal_note,updated_by=caller_id,updated_at=timezone('utc',now()) returning * into result; return jsonb_build_object('id',result.id,'productId',result.product_id,'seasonYear',result.season_year,'status',result.status,'confirmed',result.is_confirmed,'opensAt',result.preorder_opens_at,'closesAt',result.preorder_closes_at,'fulfillmentStartsAt',result.fulfillment_starts_at,'fulfillmentEndsAt',result.fulfillment_ends_at,'publicNote',result.public_note); end;$function$;

CREATE OR REPLACE FUNCTION private.management_update_order_status_v1(p_order_id uuid, p_status text, p_tracking_number text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  caller_is_admin boolean;
  caller_producer_id uuid;
  normalized_status text := lower(btrim(coalesce(p_status, '')));
  normalized_tracking text := nullif(btrim(coalesce(p_tracking_number, '')), '');
  normalized_note text := nullif(btrim(coalesce(p_note, '')), '');
  target_order public.orders%rowtype;
  next_order_status text;
  next_fulfillment_status text;
  v_shipment_id uuid;
  unfulfilled_count integer;
begin
  if caller_id is null or p_order_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if normalized_status='payment_pending_escrow' then normalized_status:='pending_payment'; end if;
  if normalized_status not in ('draft','pending_payment','confirmed','preparing','partially_shipped','shipped','delivered','completed','cancelled','refunded') then raise exception 'invalid_order_status' using errcode='22023'; end if;
  if char_length(coalesce(normalized_note,''))>1000 or char_length(coalesce(normalized_tracking,''))>120 then raise exception 'invalid_order_update_field' using errcode='22023'; end if;

  select * into target_order from public.orders where id=p_order_id for update;
  if not found then raise exception 'order_not_found' using errcode='P0002'; end if;

  caller_is_admin := coalesce(private.has_permission('order.manage'),false);
  select producer.id into caller_producer_id
  from public.producers producer
  where producer.owner_user_id=caller_id and producer.deleted_at is null and producer.status='active'
  order by producer.created_at desc limit 1;

  if not caller_is_admin then
    if caller_producer_id is null or not exists(select 1 from public.order_items item where item.order_id=target_order.id and item.producer_id=caller_producer_id) then raise exception 'order_access_denied' using errcode='42501'; end if;
    if normalized_status not in ('preparing','shipped') then raise exception 'producer_fulfillment_status_only' using errcode='42501'; end if;
    if target_order.status in ('cancelled','refunded','completed') then raise exception 'order_is_terminal' using errcode='22023'; end if;
    if target_order.status not in ('confirmed','preparing','partially_shipped','shipped') then raise exception 'order_not_ready_for_fulfillment' using errcode='22023'; end if;

    if normalized_status='preparing' then
      update public.order_items set fulfillment_status='processing'
      where order_id=target_order.id and producer_id=caller_producer_id and fulfillment_status='unfulfilled';
      next_order_status := case when target_order.status='confirmed' then 'preparing' else target_order.status end;
      next_fulfillment_status := 'processing';
    else
      if normalized_tracking is null or char_length(normalized_tracking)<4 then raise exception 'tracking_number_required' using errcode='22023'; end if;
      insert into public.shipments(order_id,carrier,tracking_number,status,shipped_at)
      values(target_order.id,'other',normalized_tracking,'in_transit',timezone('utc',now()))
      on conflict(carrier,tracking_number) do update set status='in_transit',shipped_at=coalesce(public.shipments.shipped_at,timezone('utc',now()))
      returning id into v_shipment_id;
      insert into public.shipment_items(shipment_id,order_item_id,quantity)
      select v_shipment_id,item.id,item.quantity from public.order_items item
      where item.order_id=target_order.id and item.producer_id=caller_producer_id and item.fulfillment_status<>'cancelled'
      on conflict(shipment_id,order_item_id) do update set quantity=excluded.quantity;
      update public.order_items set fulfillment_status='fulfilled'
      where order_id=target_order.id and producer_id=caller_producer_id and fulfillment_status<>'cancelled';
      select count(*) into unfulfilled_count from public.order_items item
      where item.order_id=target_order.id and item.fulfillment_status not in ('fulfilled','returned','cancelled');
      next_order_status := case when unfulfilled_count=0 then 'shipped' else 'partially_shipped' end;
      next_fulfillment_status := case when unfulfilled_count=0 then 'fulfilled' else 'partially_fulfilled' end;
    end if;
    update public.orders set status=next_order_status,fulfillment_status=next_fulfillment_status,updated_at=timezone('utc',now()) where id=target_order.id;
  else
    if target_order.status=normalized_status then return jsonb_build_object('id',target_order.id,'status',target_order.status,'unchanged',true); end if;
    if not (
      (target_order.status='draft' and normalized_status in ('pending_payment','cancelled')) or
      (target_order.status='pending_payment' and normalized_status in ('confirmed','cancelled')) or
      (target_order.status='confirmed' and normalized_status in ('preparing','cancelled')) or
      (target_order.status='preparing' and normalized_status in ('partially_shipped','shipped','cancelled')) or
      (target_order.status='partially_shipped' and normalized_status='shipped') or
      (target_order.status='shipped' and normalized_status='delivered') or
      (target_order.status='delivered' and normalized_status='completed')
    ) then raise exception 'invalid_order_status_transition:%:%',target_order.status,normalized_status using errcode='22023'; end if;

    if target_order.status='pending_payment' and normalized_status='confirmed' then
      if target_order.payment_status not in ('authorized','paid') then raise exception 'verified_payment_required_before_confirmation' using errcode='55000'; end if;
      perform private.consume_order_inventory_v1(target_order.id,caller_id);
    end if;
    if normalized_status='cancelled' then
      if target_order.payment_status<>'unpaid' then raise exception 'paid_order_requires_refund_workflow' using errcode='22023'; end if;
      perform private.release_order_inventory(target_order.id);
    end if;
    if normalized_status in ('partially_shipped','shipped') and (normalized_tracking is null or char_length(normalized_tracking)<4) then raise exception 'tracking_number_required' using errcode='22023'; end if;

    next_fulfillment_status := case normalized_status when 'preparing' then 'processing' when 'partially_shipped' then 'partially_fulfilled' when 'shipped' then 'fulfilled' when 'delivered' then 'fulfilled' when 'completed' then 'fulfilled' else target_order.fulfillment_status end;
    if normalized_status in ('partially_shipped','shipped') then
      insert into public.shipments(order_id,carrier,tracking_number,status,shipped_at)
      values(target_order.id,'other',normalized_tracking,'in_transit',timezone('utc',now()))
      on conflict(carrier,tracking_number) do update set status='in_transit',shipped_at=coalesce(public.shipments.shipped_at,timezone('utc',now()))
      returning id into v_shipment_id;
      insert into public.shipment_items(shipment_id,order_item_id,quantity)
      select v_shipment_id,item.id,item.quantity from public.order_items item where item.order_id=target_order.id and item.fulfillment_status<>'cancelled'
      on conflict(shipment_id,order_item_id) do update set quantity=excluded.quantity;
    end if;
    update public.order_items set fulfillment_status=case normalized_status when 'preparing' then 'processing' when 'shipped' then 'fulfilled' when 'cancelled' then 'cancelled' else fulfillment_status end where order_id=target_order.id;
    update public.orders set status=normalized_status,fulfillment_status=next_fulfillment_status,
      cancelled_at=case when normalized_status='cancelled' then timezone('utc',now()) else cancelled_at end,
      completed_at=case when normalized_status='completed' then timezone('utc',now()) else completed_at end,
      reservation_expires_at=case when normalized_status in ('confirmed','cancelled') then null else reservation_expires_at end,
      updated_at=timezone('utc',now()) where id=target_order.id;
    next_order_status:=normalized_status;
  end if;

  insert into public.order_status_history(order_id,from_status,to_status,note,visible_to_customer,actor_user_id)
  values(target_order.id,target_order.status,next_order_status,coalesce(normalized_note,case when caller_is_admin then 'Yönetim paneli durum güncellemesi.' else 'Satıcı gönderim durumu güncellemesi.' end),true,caller_id);
  insert into public.notifications(user_id,type,title,message,action_url,metadata)
  values(target_order.user_id,case when next_order_status in ('partially_shipped','shipped','delivered') then 'shipment' else 'order' end,'Sipariş durumunuz güncellendi',target_order.order_number||' numaralı siparişinizin yeni durumu: '||next_order_status||'.','/account/orders',jsonb_build_object('orderId',target_order.id,'status',next_order_status,'trackingNumber',normalized_tracking));
  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
  values('order',target_order.id,'order.status_changed',jsonb_build_object('order_id',target_order.id,'from_status',target_order.status,'to_status',next_order_status,'actor_user_id',caller_id,'producer_id',caller_producer_id));
  return jsonb_build_object('id',target_order.id,'status',next_order_status,'fulfillmentStatus',next_fulfillment_status,'trackingNumber',normalized_tracking);
end;
$function$;

CREATE OR REPLACE FUNCTION private.management_upsert_category_v1(p_reference text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  v_category_id uuid := private.resolve_category_id_v1(p_reference);
  normalized_name text;
  normalized_slug text;
  category_row public.categories%rowtype;
begin
  if caller_id is null or not coalesce(private.has_permission('content.update'),false) then
    raise exception 'admin_required' using errcode = '42501';
  end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'invalid_category_payload' using errcode = '22023';
  end if;

  normalized_name := btrim(coalesce(p_payload ->> 'name', ''));
  if v_category_id is null and char_length(normalized_name) not between 2 and 120 then
    raise exception 'category_name_required' using errcode = '22023';
  end if;
  if p_payload ? 'name' and char_length(normalized_name) not between 2 and 120 then
    raise exception 'invalid_category_name' using errcode = '22023';
  end if;
  if char_length(coalesce(p_payload ->> 'description', '')) > 3000
    or char_length(coalesce(p_payload ->> 'icon', '')) > 80
    or char_length(coalesce(p_payload ->> 'image', '')) > 2048 then
    raise exception 'invalid_category_field_length' using errcode = '22023';
  end if;
  if coalesce(p_payload ->> 'image', '') ~* '^(blob:|data:)' then
    raise exception 'persistent_category_image_required' using errcode = '22023';
  end if;

  if v_category_id is null then
    normalized_slug := private.slugify_tr_v1(coalesce(nullif(p_payload ->> 'targetCategory', ''), normalized_name));
    if normalized_slug = '' then
      raise exception 'invalid_category_slug' using errcode = '22023';
    end if;
    if exists (select 1 from public.categories category where category.slug = normalized_slug) then
      normalized_slug := normalized_slug || '-' || substr(gen_random_uuid()::text, 1, 8);
    end if;
    insert into public.categories(slug, name, description, icon, image_path, sort_order, is_active)
    values (
      normalized_slug,
      normalized_name,
      btrim(coalesce(p_payload ->> 'description', '')),
      nullif(btrim(coalesce(p_payload ->> 'icon', '')), ''),
      nullif(btrim(coalesce(p_payload ->> 'image', '')), ''),
      coalesce((p_payload ->> 'sortOrder')::integer, 0),
      coalesce((p_payload ->> 'is_active')::boolean, true)
    )
    returning * into category_row;
  else
    update public.categories
    set name = case when p_payload ? 'name' then normalized_name else name end,
        description = case when p_payload ? 'description' then btrim(coalesce(p_payload ->> 'description', '')) else description end,
        icon = case when p_payload ? 'icon' then nullif(btrim(coalesce(p_payload ->> 'icon', '')), '') else icon end,
        image_path = case when p_payload ? 'image' then nullif(btrim(coalesce(p_payload ->> 'image', '')), '') else image_path end,
        sort_order = case when p_payload ? 'sortOrder' then (p_payload ->> 'sortOrder')::integer else sort_order end,
        is_active = case when p_payload ? 'is_active' then (p_payload ->> 'is_active')::boolean else is_active end
    where id = v_category_id
    returning * into category_row;
  end if;

  return jsonb_build_object(
    'id', category_row.slug,
    'databaseId', category_row.id,
    'name', category_row.name,
    'is_active', category_row.is_active
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.management_upsert_content_v1(p_reference text, p_content_type text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  normalized_type text := lower(btrim(coalesce(p_content_type, '')));
  entry_id uuid;
  normalized_title text;
  normalized_slug text;
  normalized_body text;
  v_related_product_id uuid;
  metadata_value jsonb;
  entry_row public.content_entries%rowtype;
begin
  if caller_id is null or not coalesce(private.has_permission('content.update'),false) then
    raise exception 'admin_required' using errcode = '42501';
  end if;
  if normalized_type not in ('blog', 'recipe', 'health_guide', 'product_health')
    or p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'invalid_content_payload' using errcode = '22023';
  end if;
  select entry.id into entry_id
  from public.content_entries entry
  where entry.deleted_at is null
    and (entry.id::text = btrim(coalesce(p_reference, '')) or entry.legacy_id = btrim(coalesce(p_reference, '')))
  order by entry.created_at
  limit 1;

  normalized_title := btrim(coalesce(p_payload ->> 'title', ''));
  normalized_body := btrim(coalesce(p_payload ->> 'content', ''));
  if entry_id is null and char_length(normalized_title) not between 2 and 240 then
    raise exception 'content_title_required' using errcode = '22023';
  end if;
  if p_payload ? 'title' and char_length(normalized_title) not between 2 and 240 then
    raise exception 'invalid_content_title' using errcode = '22023';
  end if;
  if char_length(coalesce(p_payload ->> 'summary', '')) > 2000
    or char_length(normalized_body) > 200000
    or char_length(coalesce(p_payload ->> 'image', '')) > 2048 then
    raise exception 'invalid_content_field_length' using errcode = '22023';
  end if;
  if coalesce(p_payload ->> 'image', '') ~* '^(blob:|data:)' then
    raise exception 'persistent_content_image_required' using errcode = '22023';
  end if;
  if (normalized_title || ' ' || normalized_body || ' ' || coalesce(p_payload ->> 'summary', ''))
    ~* '(tedavi eder|doğal antibiyotik|mucize|kanseri? (önler|iyileştirir)|kolesterolü düşürür|kan şekerini dengeler|hastalıklara karşı zırh)' then
    raise exception 'unsupported_health_claim' using errcode = '22023';
  end if;

  if normalized_type = 'product_health' then
    v_related_product_id := private.resolve_product_id_v1(p_payload ->> 'productId');
    if v_related_product_id is null and entry_id is null then
      raise exception 'related_product_required' using errcode = '22023';
    end if;
  end if;
  metadata_value := jsonb_strip_nulls(jsonb_build_object(
    'originalDate', nullif(btrim(coalesce(p_payload ->> 'date', '')), ''),
    'originalCategory', nullif(btrim(coalesce(p_payload ->> 'category', '')), '')
  ));

  if entry_id is null then
    normalized_slug := private.slugify_tr_v1(normalized_title);
    if normalized_slug = '' then raise exception 'invalid_content_slug' using errcode = '22023'; end if;
    if exists (
      select 1 from public.content_entries entry
      where entry.content_type = normalized_type and entry.slug = normalized_slug and entry.locale = 'tr'
    ) then
      normalized_slug := normalized_slug || '-' || substr(gen_random_uuid()::text, 1, 8);
    end if;
    insert into public.content_entries(
      content_type, slug, title, summary, body_markdown, body_html_sanitized,
      hero_image_path, author_user_id, related_product_id, status, locale, metadata, published_at
    ) values (
      normalized_type,
      normalized_slug,
      normalized_title,
      btrim(coalesce(p_payload ->> 'summary', '')),
      normalized_body,
      '',
      nullif(btrim(coalesce(p_payload ->> 'image', '')), ''),
      caller_id,
      v_related_product_id,
      'published',
      'tr',
      metadata_value,
      timezone('utc', now())
    ) returning * into entry_row;
  else
    update public.content_entries
    set title = case when p_payload ? 'title' then normalized_title else title end,
        summary = case when p_payload ? 'summary' then btrim(coalesce(p_payload ->> 'summary', '')) else summary end,
        body_markdown = case when p_payload ? 'content' then normalized_body else body_markdown end,
        body_html_sanitized = case when p_payload ? 'content' then '' else body_html_sanitized end,
        hero_image_path = case when p_payload ? 'image' then nullif(btrim(coalesce(p_payload ->> 'image', '')), '') else hero_image_path end,
        related_product_id = coalesce(v_related_product_id, public.content_entries.related_product_id),
        metadata = metadata || metadata_value,
        status = 'published',
        published_at = coalesce(published_at, timezone('utc', now())),
        deleted_at = null
    where id = entry_id
    returning * into entry_row;
  end if;

  return jsonb_build_object(
    'id', coalesce(entry_row.legacy_id, entry_row.id::text),
    'databaseId', entry_row.id,
    'contentType', entry_row.content_type,
    'status', entry_row.status
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.management_upsert_event_v2(p_reference text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  v_event_id uuid;
  current_row public.events%rowtype;
  event_row public.events%rowtype;
  normalized_title text;
  normalized_description text;
  normalized_location text;
  normalized_image text;
  normalized_status text;
  next_starts_at timestamptz;
  next_ends_at timestamptz;
  next_deadline timestamptz;
  next_capacity integer;
  has_capacity boolean := false;
  has_deadline boolean := false;
  normalized_slug text;
begin
  if caller_id is null or not coalesce(private.has_permission('event.manage'),false) then
    raise exception 'admin_required' using errcode='42501';
  end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'invalid_event_payload' using errcode='22023';
  end if;
  if exists (
    select 1 from jsonb_object_keys(p_payload) key
    where key not in ('title','description','image','location','startsAt','endsAt','capacity','reservationDeadline','status')
  ) then
    raise exception 'unsupported_event_field' using errcode='22023';
  end if;

  select e.* into current_row
  from public.events e
  where e.id::text=btrim(coalesce(p_reference,''))
     or e.legacy_id=btrim(coalesce(p_reference,''))
     or e.slug=btrim(coalesce(p_reference,''))
  order by e.created_at
  limit 1;
  if found then v_event_id:=current_row.id; end if;

  normalized_title := case when p_payload ? 'title' then btrim(coalesce(p_payload->>'title','')) else current_row.title end;
  normalized_description := case when p_payload ? 'description' then btrim(coalesce(p_payload->>'description','')) else current_row.description end;
  normalized_location := case when p_payload ? 'location' then btrim(coalesce(p_payload->>'location','')) else current_row.location_name end;
  normalized_image := case when p_payload ? 'image' then btrim(coalesce(p_payload->>'image','')) else current_row.image_path end;
  normalized_status := lower(btrim(coalesce(case when p_payload ? 'status' then p_payload->>'status' else current_row.status end, case when v_event_id is null then 'draft' else '' end)));

  if char_length(coalesce(normalized_title,'')) not between 2 and 180 then raise exception 'invalid_event_title' using errcode='22023'; end if;
  if char_length(coalesce(normalized_description,'')) > 20000 then raise exception 'invalid_event_description' using errcode='22023'; end if;
  if char_length(coalesce(normalized_location,'')) not between 2 and 500 then raise exception 'invalid_event_location' using errcode='22023'; end if;
  if char_length(coalesce(normalized_image,'')) > 2048 then raise exception 'invalid_event_image' using errcode='22023'; end if;
  if coalesce(normalized_image,'') ~* '^(blob:|data:|javascript:)' then raise exception 'persistent_event_image_required' using errcode='22023'; end if;
  if normalized_status not in ('draft','published','sold_out','cancelled','completed') then raise exception 'invalid_event_status' using errcode='22023'; end if;

  if p_payload ? 'startsAt' then
    begin next_starts_at := (p_payload->>'startsAt')::timestamptz; exception when others then raise exception 'invalid_event_start' using errcode='22007'; end;
  else next_starts_at := current_row.starts_at; end if;
  if p_payload ? 'endsAt' then
    begin next_ends_at := (p_payload->>'endsAt')::timestamptz; exception when others then raise exception 'invalid_event_end' using errcode='22007'; end;
  else next_ends_at := current_row.ends_at; end if;
  if v_event_id is null and (next_starts_at is null or next_ends_at is null) then raise exception 'event_dates_required' using errcode='22023'; end if;
  if next_starts_at is null or next_ends_at is null or next_ends_at <= next_starts_at then raise exception 'invalid_event_date_range' using errcode='22023'; end if;

  if p_payload ? 'capacity' then
    has_capacity := true;
    if jsonb_typeof(p_payload->'capacity')='null' then next_capacity:=null;
    elsif jsonb_typeof(p_payload->'capacity')='number' then
      begin next_capacity := (p_payload->>'capacity')::integer; exception when others then raise exception 'invalid_event_capacity' using errcode='22023'; end;
      if next_capacity < 1 or next_capacity > 1000000 then raise exception 'invalid_event_capacity' using errcode='22023'; end if;
    else raise exception 'invalid_event_capacity' using errcode='22023'; end if;
  else next_capacity := current_row.capacity; end if;

  if p_payload ? 'reservationDeadline' then
    has_deadline := true;
    if jsonb_typeof(p_payload->'reservationDeadline')='null' or btrim(coalesce(p_payload->>'reservationDeadline',''))='' then next_deadline:=null;
    else begin next_deadline := (p_payload->>'reservationDeadline')::timestamptz; exception when others then raise exception 'invalid_event_reservation_deadline' using errcode='22007'; end; end if;
  else next_deadline := current_row.reservation_deadline; end if;
  if next_deadline is not null and next_deadline > next_starts_at then raise exception 'invalid_event_reservation_deadline' using errcode='22023'; end if;

  if v_event_id is null then
    normalized_slug:=private.slugify_tr_v1(normalized_title);
    if exists(select 1 from public.events e where e.slug=normalized_slug) then normalized_slug:=normalized_slug||'-'||substr(gen_random_uuid()::text,1,8); end if;
    insert into public.events(slug,title,description,image_path,location_name,location_details,starts_at,ends_at,capacity,reservation_deadline,status)
    values(normalized_slug,normalized_title,normalized_description,nullif(normalized_image,''),normalized_location,'{}'::jsonb,next_starts_at,next_ends_at,next_capacity,next_deadline,normalized_status)
    returning * into event_row;
  else
    update public.events set
      title=normalized_title,
      description=normalized_description,
      image_path=nullif(normalized_image,''),
      location_name=normalized_location,
      starts_at=next_starts_at,
      ends_at=next_ends_at,
      capacity=case when has_capacity then next_capacity else capacity end,
      reservation_deadline=case when has_deadline then next_deadline else reservation_deadline end,
      status=normalized_status,
      updated_at=timezone('utc',now())
    where id=v_event_id
    returning * into event_row;
  end if;

  return jsonb_build_object('id',coalesce(event_row.legacy_id,event_row.slug),'databaseId',event_row.id,'status',event_row.status);
end;
$function$;

CREATE OR REPLACE FUNCTION private.management_upsert_product_core_v1(p_reference text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  caller_is_admin boolean;
  caller_producer_id uuid;
  v_product_id uuid := private.resolve_product_id_v1(p_reference);
  product_row public.products%rowtype;
  v_category_id uuid;
  v_producer_id uuid;
  normalized_name text;
  normalized_slug text;
  next_base_price bigint;
  next_compare_price bigint;
  next_status text;
  next_is_active boolean;
  next_specifications jsonb;
  next_features jsonb;
  next_tags text[];
  default_variant_id uuid;
  next_stock integer;
  media_values jsonb := '[]'::jsonb;
  media_path text;
  media_index integer := 0;
  change_request_id uuid;
begin
  if caller_id is null then
    raise exception 'authentication_required' using errcode = '42501';
  end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' or pg_column_size(p_payload) > 262144 then
    raise exception 'invalid_product_payload' using errcode = '22023';
  end if;

  caller_is_admin := true;
  select producer.id into caller_producer_id
  from public.producers producer
  where producer.owner_user_id = caller_id
    and producer.deleted_at is null
    and producer.status = 'active'
  order by producer.created_at desc
  limit 1;
  if not caller_is_admin and caller_producer_id is null then
    raise exception 'active_producer_required' using errcode = '42501';
  end if;

  if v_product_id is not null then
    select * into product_row
    from public.products product
    where product.id = v_product_id
    for update;
    if not caller_is_admin and product_row.producer_id <> caller_producer_id then
      raise exception 'product_access_denied' using errcode = '42501';
    end if;
    if not caller_is_admin and product_row.status = 'published' then
      insert into public.product_change_requests(product_id, producer_id, requested_by, proposed_payload)
      values (product_row.id, product_row.producer_id, caller_id, p_payload)
      on conflict (product_id) where status = 'pending'
      do update set
        proposed_payload = excluded.proposed_payload,
        requested_by = excluded.requested_by,
        updated_at = timezone('utc', now())
      returning id into change_request_id;

      insert into public.notifications(user_id, type, title, message, action_url, metadata)
      select role.user_id, 'producer', 'Ürün değişikliği inceleme bekliyor',
        product_row.name || ' ürünü için satıcı değişiklik talebi gönderildi.',
        '/admin/products',
        jsonb_build_object('productId', product_row.id, 'changeRequestId', change_request_id)
      from private.user_roles role
      join public.profiles profile on profile.id = role.user_id and profile.status = 'active'
      where role.role in ('admin', 'super_admin')
        and (role.expires_at is null or role.expires_at > timezone('utc', now()))
      on conflict do nothing;

      return jsonb_build_object(
        'id', coalesce(product_row.legacy_id, product_row.id::text),
        'databaseId', product_row.id,
        'status', 'pending_change_review',
        'changeRequestId', change_request_id
      );
    end if;
  end if;

  normalized_name := btrim(coalesce(p_payload ->> 'name', ''));
  if v_product_id is null and char_length(normalized_name) not between 2 and 180 then
    raise exception 'product_name_required' using errcode = '22023';
  end if;
  if p_payload ? 'name' and char_length(normalized_name) not between 2 and 180 then
    raise exception 'invalid_product_name' using errcode = '22023';
  end if;
  if char_length(coalesce(p_payload ->> 'description', '')) > 20000
    or char_length(coalesce(p_payload ->> 'story', '')) > 20000
    or char_length(coalesce(p_payload ->> 'origin', '')) > 500
    or char_length(coalesce(p_payload ->> 'unit', '')) > 80
    or char_length(coalesce(p_payload ->> 'video', '')) > 2048 then
    raise exception 'invalid_product_field_length' using errcode = '22023';
  end if;
  if coalesce(p_payload ->> 'video', '') ~* '^(blob:|data:)' then
    raise exception 'persistent_product_media_required' using errcode = '22023';
  end if;
  if p_payload ? 'price' and jsonb_typeof(p_payload -> 'price') <> 'number' then
    raise exception 'invalid_product_price' using errcode = '22023';
  end if;
  if p_payload ? 'originalPrice' and jsonb_typeof(p_payload -> 'originalPrice') <> 'number' then
    raise exception 'invalid_compare_price' using errcode = '22023';
  end if;
  if p_payload ? 'stock' and jsonb_typeof(p_payload -> 'stock') <> 'number' then
    raise exception 'invalid_product_stock' using errcode = '22023';
  end if;
  if p_payload ? 'tags' and jsonb_typeof(p_payload -> 'tags') <> 'array' then
    raise exception 'invalid_product_tags' using errcode = '22023';
  end if;
  if p_payload ? 'features' and jsonb_typeof(p_payload -> 'features') <> 'array' then
    raise exception 'invalid_product_features' using errcode = '22023';
  end if;

  if v_product_id is null or p_payload ? 'category' or p_payload ? 'categoryId' then
    v_category_id := private.resolve_category_id_v1(coalesce(nullif(p_payload ->> 'categoryId', ''), p_payload ->> 'category'));
    if v_category_id is null then
      raise exception 'category_not_found' using errcode = 'P0002';
    end if;
  else
    v_category_id := product_row.category_id;
  end if;

  if v_product_id is null then
    if caller_is_admin then
      v_producer_id := nullif(p_payload ->> 'vendor_id', '')::uuid;
      if v_producer_id is null or not exists (
        select 1 from public.producers producer
        where producer.id = v_producer_id and producer.deleted_at is null
      ) then
        select producer.id into v_producer_id
        from public.producers producer
        where producer.status = 'active' and producer.deleted_at is null
        order by producer.is_verified desc, producer.created_at
        limit 1;
      end if;
    else
      v_producer_id := caller_producer_id;
    end if;
    if v_producer_id is null then
      raise exception 'producer_not_found' using errcode = 'P0002';
    end if;
  else
    v_producer_id := product_row.producer_id;
  end if;

  next_base_price := case
    when p_payload ? 'price' then round((p_payload ->> 'price')::numeric * 100)::bigint
    when v_product_id is not null then product_row.base_price_minor
    else 0
  end;
  if next_base_price < 0 or next_base_price > 100000000 then
    raise exception 'product_price_out_of_range' using errcode = '22023';
  end if;
  next_compare_price := case
    when p_payload ? 'originalPrice' then round((p_payload ->> 'originalPrice')::numeric * 100)::bigint
    when v_product_id is not null then product_row.compare_at_price_minor
    else next_base_price
  end;
  if next_compare_price is not null and next_compare_price < next_base_price then
    next_compare_price := next_base_price;
  end if;

  next_features := case
    when p_payload ? 'features' then p_payload -> 'features'
    when v_product_id is not null then product_row.features
    else '[]'::jsonb
  end;
  next_tags := case
    when p_payload ? 'tags' then array(select jsonb_array_elements_text(p_payload -> 'tags'))
    when v_product_id is not null then product_row.tags
    else '{}'::text[]
  end;
  if coalesce(array_length(next_tags, 1), 0) > 30
    or exists (select 1 from unnest(next_tags) tag where char_length(tag) > 80) then
    raise exception 'invalid_product_tags' using errcode = '22023';
  end if;
  if jsonb_array_length(next_features) > 40 then
    raise exception 'too_many_product_features' using errcode = '22023';
  end if;

  next_specifications := case when v_product_id is null then '{}'::jsonb else product_row.specifications end;
  if p_payload ? 'weight' then next_specifications := jsonb_set(next_specifications, '{originalWeight}', p_payload -> 'weight', true); end if;
  if p_payload ? 'weightOptions' then next_specifications := jsonb_set(next_specifications, '{weightOptions}', p_payload -> 'weightOptions', true); end if;
  if p_payload ? 'cutOptions' then next_specifications := jsonb_set(next_specifications, '{cutOptions}', p_payload -> 'cutOptions', true); end if;
  if p_payload ? 'preOrderTime' then next_specifications := jsonb_set(next_specifications, '{preOrderTime}', to_jsonb(coalesce(p_payload ->> 'preOrderTime', '')), true); end if;
  if p_payload ? 'pricePrefix' then next_specifications := jsonb_set(next_specifications, '{pricePrefix}', to_jsonb(coalesce(p_payload ->> 'pricePrefix', '')), true); end if;
  if p_payload ? 'video' then next_specifications := jsonb_set(next_specifications, '{video}', to_jsonb(coalesce(p_payload ->> 'video', '')), true); end if;
  if p_payload ? 'section' then next_specifications := jsonb_set(next_specifications, '{section}', to_jsonb(coalesce(p_payload ->> 'section', '')), true); end if;
  if p_payload ? 'homeSection' then next_specifications := jsonb_set(next_specifications, '{homeSection}', to_jsonb(coalesce(p_payload ->> 'homeSection', '')), true); end if;
  if p_payload ? 'verificationStatus' then next_specifications := jsonb_set(next_specifications, '{verificationStatus}', p_payload -> 'verificationStatus', true); end if;
  if p_payload ? 'claimReviewStatus' then next_specifications := jsonb_set(next_specifications, '{claimReviewStatus}', p_payload -> 'claimReviewStatus', true); end if;
  if p_payload ? 'rejection_reason' then next_specifications := jsonb_set(next_specifications, '{rejectionReason}', to_jsonb(coalesce(p_payload ->> 'rejection_reason', '')), true); end if;

  next_is_active := case
    when p_payload ? 'is_active' then (p_payload ->> 'is_active')::boolean
    when v_product_id is not null then product_row.is_active
    else true
  end;
  if caller_is_admin then
    next_status := case
      when coalesce((p_payload ->> 'is_rejected')::boolean, false) then 'rejected'
      when coalesce((p_payload ->> 'is_approved')::boolean, false) then 'published'
      when v_product_id is not null then product_row.status
      else 'draft'
    end;
  else
    next_status := 'review';
  end if;

  if v_product_id is null then
    normalized_slug := private.slugify_tr_v1(normalized_name);
    if normalized_slug = '' then raise exception 'invalid_product_slug' using errcode = '22023'; end if;
    if exists (select 1 from public.products product where product.slug = normalized_slug) then
      normalized_slug := normalized_slug || '-' || substr(gen_random_uuid()::text, 1, 8);
    end if;
    insert into public.products(
      producer_id, category_id, slug, name, short_description, description, story, origin,
      unit_label, base_price_minor, compare_at_price_minor, currency, status, stock_mode,
      preorder_lead_days, tags, features, specifications, is_active, published_at
    ) values (
      v_producer_id,
      v_category_id,
      normalized_slug,
      normalized_name,
      left(btrim(coalesce(p_payload ->> 'description', '')), 320),
      btrim(coalesce(p_payload ->> 'description', '')),
      btrim(coalesce(p_payload ->> 'story', '')),
      nullif(btrim(coalesce(p_payload ->> 'origin', '')), ''),
      coalesce(nullif(btrim(p_payload ->> 'unit'), ''), 'adet'),
      next_base_price,
      next_compare_price,
      'TRY',
      next_status,
      case when coalesce((p_payload ->> 'preOrder')::boolean, false) then 'preorder' else 'tracked' end,
      case when coalesce((p_payload ->> 'preOrder')::boolean, false) then 3 else null end,
      next_tags,
      next_features,
      next_specifications,
      next_is_active,
      case when next_status = 'published' then timezone('utc', now()) else null end
    ) returning * into product_row;
    v_product_id := product_row.id;
  else
    update public.products
    set category_id = v_category_id,
        name = case when p_payload ? 'name' then normalized_name else name end,
        short_description = case when p_payload ? 'description' then left(btrim(coalesce(p_payload ->> 'description', '')), 320) else short_description end,
        description = case when p_payload ? 'description' then btrim(coalesce(p_payload ->> 'description', '')) else description end,
        story = case when p_payload ? 'story' then btrim(coalesce(p_payload ->> 'story', '')) else story end,
        origin = case when p_payload ? 'origin' then nullif(btrim(coalesce(p_payload ->> 'origin', '')), '') else origin end,
        unit_label = case when p_payload ? 'unit' then coalesce(nullif(btrim(p_payload ->> 'unit'), ''), unit_label) else unit_label end,
        base_price_minor = next_base_price,
        compare_at_price_minor = next_compare_price,
        tags = next_tags,
        features = next_features,
        specifications = next_specifications,
        stock_mode = case when p_payload ? 'preOrder' then case when (p_payload ->> 'preOrder')::boolean then 'preorder' else 'tracked' end else stock_mode end,
        preorder_lead_days = case when p_payload ? 'preOrder' then case when (p_payload ->> 'preOrder')::boolean then coalesce(preorder_lead_days, 3) else null end else preorder_lead_days end,
        status = next_status,
        is_active = next_is_active,
        published_at = case when next_status = 'published' then coalesce(published_at, timezone('utc', now())) else null end
    where id = v_product_id
    returning * into product_row;
  end if;

  select variant.id into default_variant_id
  from public.product_variants variant
  where variant.product_id = v_product_id
  order by variant.is_default desc, variant.created_at
  limit 1
  for update;

  if default_variant_id is null then
    insert into public.product_variants(product_id, sku, name, price_minor, compare_at_price_minor, weight_grams, is_default, is_active)
    values (
      v_product_id,
      'GO-' || upper(substr(replace(v_product_id::text, '-', ''), 1, 12)),
      'Standart',
      next_base_price,
      next_compare_price,
      case when p_payload ? 'weight' then greatest(1, round((p_payload ->> 'weight')::numeric * 1000)::integer) else null end,
      true,
      true
    )
    returning id into default_variant_id;
  else
    update public.product_variants
    set price_minor = next_base_price,
        compare_at_price_minor = next_compare_price,
        weight_grams = case when p_payload ? 'weight' then greatest(1, round((p_payload ->> 'weight')::numeric * 1000)::integer) else weight_grams end,
        is_active = true
    where id = default_variant_id;
  end if;

  if p_payload ? 'stock' then
    next_stock := floor((p_payload ->> 'stock')::numeric)::integer;
    if next_stock < 0 or next_stock > 100000000 then
      raise exception 'product_stock_out_of_range' using errcode = '22023';
    end if;
    insert into public.product_inventory(variant_id, available_quantity, reserved_quantity, reorder_level)
    values (default_variant_id, next_stock, 0, least(10, next_stock))
    on conflict (variant_id) do update
    set available_quantity = greatest(excluded.available_quantity, public.product_inventory.reserved_quantity),
        reorder_level = least(10, greatest(excluded.available_quantity, public.product_inventory.reserved_quantity)),
        version = public.product_inventory.version + 1;
  elsif not exists (select 1 from public.product_inventory inventory where inventory.variant_id = default_variant_id) then
    insert into public.product_inventory(variant_id, available_quantity, reserved_quantity, reorder_level)
    values (default_variant_id, 0, 0, 0);
  end if;

  if p_payload ? 'gallery' or p_payload ? 'image' then
    if p_payload ? 'gallery' and jsonb_typeof(p_payload -> 'gallery') <> 'array' then
      raise exception 'invalid_product_gallery' using errcode = '22023';
    end if;
    if nullif(btrim(coalesce(p_payload ->> 'image', '')), '') is not null then
      media_values := jsonb_build_array(btrim(p_payload ->> 'image'));
    end if;
    if p_payload ? 'gallery' then media_values := media_values || (p_payload -> 'gallery'); end if;
    if jsonb_array_length(media_values) > 11 then
      raise exception 'too_many_product_images' using errcode = '22023';
    end if;
    if exists (
      select 1
      from jsonb_array_elements_text(media_values) value
      where char_length(value) > 2048 or value ~* '^(blob:|data:)'
    ) then
      raise exception 'persistent_product_image_required' using errcode = '22023';
    end if;

    delete from public.product_images image where image.product_id = v_product_id;
    media_index := 0;
    for media_path in
      select value
      from (
        select value, min(ordinality) as first_position
        from jsonb_array_elements_text(media_values) with ordinality media(value, ordinality)
        where btrim(value) <> ''
        group by value
      ) unique_media
      order by first_position
      limit 10
    loop
      insert into public.product_images(product_id, storage_path, alt_text, sort_order, is_primary)
      values (v_product_id, media_path, product_row.name, media_index, media_index = 0);
      media_index := media_index + 1;
    end loop;
  end if;

  if not caller_is_admin then
    insert into public.notifications(user_id, type, title, message, action_url, metadata)
    select role.user_id, 'producer', 'Yeni ürün inceleme bekliyor',
      product_row.name || ' ürünü satıcı tarafından incelemeye gönderildi.',
      '/admin/products',
      jsonb_build_object('productId', product_row.id, 'producerId', product_row.producer_id)
    from private.user_roles role
    join public.profiles profile on profile.id = role.user_id and profile.status = 'active'
    where role.role in ('admin', 'super_admin')
      and (role.expires_at is null or role.expires_at > timezone('utc', now()))
    on conflict do nothing;
  end if;

  return jsonb_build_object(
    'id', coalesce(product_row.legacy_id, product_row.id::text),
    'databaseId', product_row.id,
    'status', product_row.status,
    'is_approved', product_row.status = 'published',
    'is_rejected', product_row.status = 'rejected'
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.management_upsert_product_v1(p_reference text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  caller_is_admin boolean;
  caller_producer_id uuid;
  v_product_id uuid := private.resolve_product_id_v1(p_reference);
  product_row public.products%rowtype;
  v_category_id uuid;
  v_producer_id uuid;
  normalized_name text;
  normalized_slug text;
  next_base_price bigint;
  next_compare_price bigint;
  next_status text;
  next_is_active boolean;
  next_specifications jsonb;
  next_features jsonb;
  next_tags text[];
  default_variant_id uuid;
  next_stock integer;
  media_values jsonb := '[]'::jsonb;
  media_path text;
  media_index integer := 0;
  change_request_id uuid;
begin
  if caller_id is null then
    raise exception 'authentication_required' using errcode = '42501';
  end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' or pg_column_size(p_payload) > 262144 then
    raise exception 'invalid_product_payload' using errcode = '22023';
  end if;

  caller_is_admin := coalesce(private.has_permission('admin.access'),false) and coalesce(private.has_permission('product.update'),false);
  select producer.id into caller_producer_id
  from public.producers producer
  where producer.owner_user_id = caller_id
    and producer.deleted_at is null
    and producer.status = 'active'
  order by producer.created_at desc
  limit 1;
  if not caller_is_admin and (caller_producer_id is null or not coalesce(private.has_permission('product.update'),false)) then
    raise exception 'active_producer_required' using errcode = '42501';
  end if;

  if v_product_id is not null then
    select * into product_row
    from public.products product
    where product.id = v_product_id
    for update;
    if not caller_is_admin and product_row.producer_id <> caller_producer_id then
      raise exception 'product_access_denied' using errcode = '42501';
    end if;
    if not caller_is_admin and product_row.status = 'published' then
      insert into public.product_change_requests(product_id, producer_id, requested_by, proposed_payload)
      values (product_row.id, product_row.producer_id, caller_id, p_payload)
      on conflict (product_id) where status = 'pending'
      do update set
        proposed_payload = excluded.proposed_payload,
        requested_by = excluded.requested_by,
        updated_at = timezone('utc', now())
      returning id into change_request_id;

      insert into public.notifications(user_id, type, title, message, action_url, metadata)
      select role.user_id, 'producer', 'Ürün değişikliği inceleme bekliyor',
        product_row.name || ' ürünü için satıcı değişiklik talebi gönderildi.',
        '/admin/products',
        jsonb_build_object('productId', product_row.id, 'changeRequestId', change_request_id)
      from private.user_roles role
      join public.profiles profile on profile.id = role.user_id and profile.status = 'active'
      where role.role in ('admin', 'super_admin')
        and (role.expires_at is null or role.expires_at > timezone('utc', now()))
      on conflict do nothing;

      return jsonb_build_object(
        'id', coalesce(product_row.legacy_id, product_row.id::text),
        'databaseId', product_row.id,
        'status', 'pending_change_review',
        'changeRequestId', change_request_id
      );
    end if;
  end if;

  normalized_name := btrim(coalesce(p_payload ->> 'name', ''));
  if v_product_id is null and char_length(normalized_name) not between 2 and 180 then
    raise exception 'product_name_required' using errcode = '22023';
  end if;
  if p_payload ? 'name' and char_length(normalized_name) not between 2 and 180 then
    raise exception 'invalid_product_name' using errcode = '22023';
  end if;
  if char_length(coalesce(p_payload ->> 'description', '')) > 20000
    or char_length(coalesce(p_payload ->> 'story', '')) > 20000
    or char_length(coalesce(p_payload ->> 'origin', '')) > 500
    or char_length(coalesce(p_payload ->> 'unit', '')) > 80
    or char_length(coalesce(p_payload ->> 'video', '')) > 2048 then
    raise exception 'invalid_product_field_length' using errcode = '22023';
  end if;
  if coalesce(p_payload ->> 'video', '') ~* '^(blob:|data:)' then
    raise exception 'persistent_product_media_required' using errcode = '22023';
  end if;
  if p_payload ? 'price' and jsonb_typeof(p_payload -> 'price') <> 'number' then
    raise exception 'invalid_product_price' using errcode = '22023';
  end if;
  if p_payload ? 'originalPrice' and jsonb_typeof(p_payload -> 'originalPrice') <> 'number' then
    raise exception 'invalid_compare_price' using errcode = '22023';
  end if;
  if p_payload ? 'stock' and jsonb_typeof(p_payload -> 'stock') <> 'number' then
    raise exception 'invalid_product_stock' using errcode = '22023';
  end if;
  if p_payload ? 'tags' and jsonb_typeof(p_payload -> 'tags') <> 'array' then
    raise exception 'invalid_product_tags' using errcode = '22023';
  end if;
  if p_payload ? 'features' and jsonb_typeof(p_payload -> 'features') <> 'array' then
    raise exception 'invalid_product_features' using errcode = '22023';
  end if;

  if v_product_id is null or p_payload ? 'category' or p_payload ? 'categoryId' then
    v_category_id := private.resolve_category_id_v1(coalesce(nullif(p_payload ->> 'categoryId', ''), p_payload ->> 'category'));
    if v_category_id is null then
      raise exception 'category_not_found' using errcode = 'P0002';
    end if;
  else
    v_category_id := product_row.category_id;
  end if;

  if v_product_id is null then
    if caller_is_admin then
      v_producer_id := nullif(p_payload ->> 'vendor_id', '')::uuid;
      if v_producer_id is null or not exists (
        select 1 from public.producers producer
        where producer.id = v_producer_id and producer.deleted_at is null
      ) then
        select producer.id into v_producer_id
        from public.producers producer
        where producer.status = 'active' and producer.deleted_at is null
        order by producer.is_verified desc, producer.created_at
        limit 1;
      end if;
    else
      v_producer_id := caller_producer_id;
    end if;
    if v_producer_id is null then
      raise exception 'producer_not_found' using errcode = 'P0002';
    end if;
  else
    v_producer_id := product_row.producer_id;
  end if;

  next_base_price := case
    when p_payload ? 'price' then round((p_payload ->> 'price')::numeric * 100)::bigint
    when v_product_id is not null then product_row.base_price_minor
    else 0
  end;
  if next_base_price < 0 or next_base_price > 100000000 then
    raise exception 'product_price_out_of_range' using errcode = '22023';
  end if;
  next_compare_price := case
    when p_payload ? 'originalPrice' then round((p_payload ->> 'originalPrice')::numeric * 100)::bigint
    when v_product_id is not null then product_row.compare_at_price_minor
    else next_base_price
  end;
  if next_compare_price is not null and next_compare_price < next_base_price then
    next_compare_price := next_base_price;
  end if;

  next_features := case
    when p_payload ? 'features' then p_payload -> 'features'
    when v_product_id is not null then product_row.features
    else '[]'::jsonb
  end;
  next_tags := case
    when p_payload ? 'tags' then array(select jsonb_array_elements_text(p_payload -> 'tags'))
    when v_product_id is not null then product_row.tags
    else '{}'::text[]
  end;
  if coalesce(array_length(next_tags, 1), 0) > 30
    or exists (select 1 from unnest(next_tags) tag where char_length(tag) > 80) then
    raise exception 'invalid_product_tags' using errcode = '22023';
  end if;
  if jsonb_array_length(next_features) > 40 then
    raise exception 'too_many_product_features' using errcode = '22023';
  end if;

  next_specifications := case when v_product_id is null then '{}'::jsonb else product_row.specifications end;
  if p_payload ? 'weight' then next_specifications := jsonb_set(next_specifications, '{originalWeight}', p_payload -> 'weight', true); end if;
  if p_payload ? 'weightOptions' then next_specifications := jsonb_set(next_specifications, '{weightOptions}', p_payload -> 'weightOptions', true); end if;
  if p_payload ? 'cutOptions' then next_specifications := jsonb_set(next_specifications, '{cutOptions}', p_payload -> 'cutOptions', true); end if;
  if p_payload ? 'preOrderTime' then next_specifications := jsonb_set(next_specifications, '{preOrderTime}', to_jsonb(coalesce(p_payload ->> 'preOrderTime', '')), true); end if;
  if p_payload ? 'pricePrefix' then next_specifications := jsonb_set(next_specifications, '{pricePrefix}', to_jsonb(coalesce(p_payload ->> 'pricePrefix', '')), true); end if;
  if p_payload ? 'video' then next_specifications := jsonb_set(next_specifications, '{video}', to_jsonb(coalesce(p_payload ->> 'video', '')), true); end if;
  if p_payload ? 'section' then next_specifications := jsonb_set(next_specifications, '{section}', to_jsonb(coalesce(p_payload ->> 'section', '')), true); end if;
  if p_payload ? 'homeSection' then next_specifications := jsonb_set(next_specifications, '{homeSection}', to_jsonb(coalesce(p_payload ->> 'homeSection', '')), true); end if;
  if p_payload ? 'verificationStatus' then next_specifications := jsonb_set(next_specifications, '{verificationStatus}', p_payload -> 'verificationStatus', true); end if;
  if p_payload ? 'claimReviewStatus' then next_specifications := jsonb_set(next_specifications, '{claimReviewStatus}', p_payload -> 'claimReviewStatus', true); end if;
  if p_payload ? 'rejection_reason' then next_specifications := jsonb_set(next_specifications, '{rejectionReason}', to_jsonb(coalesce(p_payload ->> 'rejection_reason', '')), true); end if;

  next_is_active := case
    when p_payload ? 'is_active' then (p_payload ->> 'is_active')::boolean
    when v_product_id is not null then product_row.is_active
    else true
  end;
  if caller_is_admin then
    next_status := case
      when coalesce((p_payload ->> 'is_rejected')::boolean, false) then 'rejected'
      when coalesce((p_payload ->> 'is_approved')::boolean, false) then 'published'
      when v_product_id is not null then product_row.status
      else 'draft'
    end;
  else
    next_status := 'review';
  end if;

  if v_product_id is null then
    normalized_slug := private.slugify_tr_v1(normalized_name);
    if normalized_slug = '' then raise exception 'invalid_product_slug' using errcode = '22023'; end if;
    if exists (select 1 from public.products product where product.slug = normalized_slug) then
      normalized_slug := normalized_slug || '-' || substr(gen_random_uuid()::text, 1, 8);
    end if;
    insert into public.products(
      producer_id, category_id, slug, name, short_description, description, story, origin,
      unit_label, base_price_minor, compare_at_price_minor, currency, status, stock_mode,
      preorder_lead_days, tags, features, specifications, is_active, published_at
    ) values (
      v_producer_id,
      v_category_id,
      normalized_slug,
      normalized_name,
      left(btrim(coalesce(p_payload ->> 'description', '')), 320),
      btrim(coalesce(p_payload ->> 'description', '')),
      btrim(coalesce(p_payload ->> 'story', '')),
      nullif(btrim(coalesce(p_payload ->> 'origin', '')), ''),
      coalesce(nullif(btrim(p_payload ->> 'unit'), ''), 'adet'),
      next_base_price,
      next_compare_price,
      'TRY',
      next_status,
      case when coalesce((p_payload ->> 'preOrder')::boolean, false) then 'preorder' else 'tracked' end,
      case when coalesce((p_payload ->> 'preOrder')::boolean, false) then 3 else null end,
      next_tags,
      next_features,
      next_specifications,
      next_is_active,
      case when next_status = 'published' then timezone('utc', now()) else null end
    ) returning * into product_row;
    v_product_id := product_row.id;
  else
    update public.products
    set category_id = v_category_id,
        name = case when p_payload ? 'name' then normalized_name else name end,
        short_description = case when p_payload ? 'description' then left(btrim(coalesce(p_payload ->> 'description', '')), 320) else short_description end,
        description = case when p_payload ? 'description' then btrim(coalesce(p_payload ->> 'description', '')) else description end,
        story = case when p_payload ? 'story' then btrim(coalesce(p_payload ->> 'story', '')) else story end,
        origin = case when p_payload ? 'origin' then nullif(btrim(coalesce(p_payload ->> 'origin', '')), '') else origin end,
        unit_label = case when p_payload ? 'unit' then coalesce(nullif(btrim(p_payload ->> 'unit'), ''), unit_label) else unit_label end,
        base_price_minor = next_base_price,
        compare_at_price_minor = next_compare_price,
        tags = next_tags,
        features = next_features,
        specifications = next_specifications,
        stock_mode = case when p_payload ? 'preOrder' then case when (p_payload ->> 'preOrder')::boolean then 'preorder' else 'tracked' end else stock_mode end,
        preorder_lead_days = case when p_payload ? 'preOrder' then case when (p_payload ->> 'preOrder')::boolean then coalesce(preorder_lead_days, 3) else null end else preorder_lead_days end,
        status = next_status,
        is_active = next_is_active,
        published_at = case when next_status = 'published' then coalesce(published_at, timezone('utc', now())) else null end
    where id = v_product_id
    returning * into product_row;
  end if;

  select variant.id into default_variant_id
  from public.product_variants variant
  where variant.product_id = v_product_id
  order by variant.is_default desc, variant.created_at
  limit 1
  for update;

  if default_variant_id is null then
    insert into public.product_variants(product_id, sku, name, price_minor, compare_at_price_minor, weight_grams, is_default, is_active)
    values (
      v_product_id,
      'GO-' || upper(substr(replace(v_product_id::text, '-', ''), 1, 12)),
      'Standart',
      next_base_price,
      next_compare_price,
      case when p_payload ? 'weight' then greatest(1, round((p_payload ->> 'weight')::numeric * 1000)::integer) else null end,
      true,
      true
    )
    returning id into default_variant_id;
  else
    update public.product_variants
    set price_minor = next_base_price,
        compare_at_price_minor = next_compare_price,
        weight_grams = case when p_payload ? 'weight' then greatest(1, round((p_payload ->> 'weight')::numeric * 1000)::integer) else weight_grams end,
        is_active = true
    where id = default_variant_id;
  end if;

  if p_payload ? 'stock' then
    next_stock := floor((p_payload ->> 'stock')::numeric)::integer;
    if next_stock < 0 or next_stock > 100000000 then
      raise exception 'product_stock_out_of_range' using errcode = '22023';
    end if;
    insert into public.product_inventory(variant_id, available_quantity, reserved_quantity, reorder_level)
    values (default_variant_id, next_stock, 0, least(10, next_stock))
    on conflict (variant_id) do update
    set available_quantity = greatest(excluded.available_quantity, public.product_inventory.reserved_quantity),
        reorder_level = least(10, greatest(excluded.available_quantity, public.product_inventory.reserved_quantity)),
        version = public.product_inventory.version + 1;
  elsif not exists (select 1 from public.product_inventory inventory where inventory.variant_id = default_variant_id) then
    insert into public.product_inventory(variant_id, available_quantity, reserved_quantity, reorder_level)
    values (default_variant_id, 0, 0, 0);
  end if;

  if p_payload ? 'gallery' or p_payload ? 'image' then
    if p_payload ? 'gallery' and jsonb_typeof(p_payload -> 'gallery') <> 'array' then
      raise exception 'invalid_product_gallery' using errcode = '22023';
    end if;
    if nullif(btrim(coalesce(p_payload ->> 'image', '')), '') is not null then
      media_values := jsonb_build_array(btrim(p_payload ->> 'image'));
    end if;
    if p_payload ? 'gallery' then media_values := media_values || (p_payload -> 'gallery'); end if;
    if jsonb_array_length(media_values) > 11 then
      raise exception 'too_many_product_images' using errcode = '22023';
    end if;
    if exists (
      select 1
      from jsonb_array_elements_text(media_values) value
      where char_length(value) > 2048 or value ~* '^(blob:|data:)'
    ) then
      raise exception 'persistent_product_image_required' using errcode = '22023';
    end if;

    delete from public.product_images image where image.product_id = v_product_id;
    media_index := 0;
    for media_path in
      select value
      from (
        select value, min(ordinality) as first_position
        from jsonb_array_elements_text(media_values) with ordinality media(value, ordinality)
        where btrim(value) <> ''
        group by value
      ) unique_media
      order by first_position
      limit 10
    loop
      insert into public.product_images(product_id, storage_path, alt_text, sort_order, is_primary)
      values (v_product_id, media_path, product_row.name, media_index, media_index = 0);
      media_index := media_index + 1;
    end loop;
  end if;

  if not caller_is_admin then
    insert into public.notifications(user_id, type, title, message, action_url, metadata)
    select role.user_id, 'producer', 'Yeni ürün inceleme bekliyor',
      product_row.name || ' ürünü satıcı tarafından incelemeye gönderildi.',
      '/admin/products',
      jsonb_build_object('productId', product_row.id, 'producerId', product_row.producer_id)
    from private.user_roles role
    join public.profiles profile on profile.id = role.user_id and profile.status = 'active'
    where role.role in ('admin', 'super_admin')
      and (role.expires_at is null or role.expires_at > timezone('utc', now()))
    on conflict do nothing;
  end if;

  return jsonb_build_object(
    'id', coalesce(product_row.legacy_id, product_row.id::text),
    'databaseId', product_row.id,
    'status', product_row.status,
    'is_approved', product_row.status = 'published',
    'is_rejected', product_row.status = 'rejected'
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.management_upsert_product_v2(p_reference text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  v_product_id uuid:=private.resolve_product_id_v1(p_reference);
  product_row public.products%rowtype;
  producer_row public.producers%rowtype;
  existing_provenance public.product_provenance%rowtype;
  safe_payload jsonb:=coalesce(p_payload,'{}'::jsonb);
  result jsonb;
  requested_vendor_raw text;
  selected_producer_id uuid;
  requested_publish boolean:=false;
  source_mode_value text;
  source_name_value text;
  source_country text;
  source_province text;
  source_district text;
  source_village text;
  source_locality text;
  origin_label_value text;
  origin_verified_value boolean;
  organic_claim_value text;
  app_organic_claim text;
begin
  if caller_id is null or not private.has_permission('product.update') then raise exception 'permission_required:product.update' using errcode='42501'; end if;
  if p_payload is null or jsonb_typeof(p_payload)<>'object' or pg_column_size(p_payload)>262144 then raise exception 'invalid_product_payload' using errcode='22023'; end if;
  if p_payload ? 'originVerified' and jsonb_typeof(p_payload->'originVerified')<>'boolean' then raise exception 'invalid_origin_verification' using errcode='22023'; end if;
  if char_length(coalesce(p_payload->>'sourceDisplayName',''))>180 or char_length(coalesce(p_payload->>'sourceLocality',''))>160 or char_length(coalesce(p_payload->>'originLabel',''))>500 then raise exception 'invalid_provenance_field_length' using errcode='22023'; end if;
  if char_length(coalesce(p_payload->>'sourceProvince',''))>120 or char_length(coalesce(p_payload->>'sourceDistrict',''))>120 or char_length(coalesce(p_payload->>'sourceVillage',''))>120 then raise exception 'invalid_provenance_location_length' using errcode='22023'; end if;
  requested_publish:=coalesce((p_payload->>'is_approved')::boolean,false); if requested_publish and not private.has_permission('product.approve') then raise exception 'permission_required:product.approve' using errcode='42501'; end if;
  safe_payload:=safe_payload-'is_approved';

  if v_product_id is null then
    requested_vendor_raw:=nullif(btrim(coalesce(p_payload->>'vendor_id','')),'');
    if requested_vendor_raw is null then
      select p.id into selected_producer_id from public.producers p where p.store_kind='official' and p.slug='golden-oremar' and p.status='active' and p.is_verified=true and p.deleted_at is null limit 1;
      if selected_producer_id is null then raise exception 'official_store_not_ready' using errcode='55000'; end if;
    else
      begin selected_producer_id:=requested_vendor_raw::uuid; exception when others then raise exception 'invalid_producer_id' using errcode='22023'; end;
      if not exists(select 1 from public.producers p where p.id=selected_producer_id and p.status='active' and p.is_verified=true and p.deleted_at is null) then raise exception 'producer_not_found' using errcode='P0002'; end if;
    end if;
  else
    select p.producer_id into selected_producer_id from public.products p where p.id=v_product_id and p.deleted_at is null;
    if selected_producer_id is null then raise exception 'product_not_found' using errcode='P0002'; end if;
    if p_payload ? 'vendor_id' and nullif(btrim(coalesce(p_payload->>'vendor_id','')),'') is not null and (p_payload->>'vendor_id')::uuid is distinct from selected_producer_id then
      raise exception 'existing_product_seller_cannot_be_changed' using errcode='55000';
    end if;
  end if;

  select * into producer_row from public.producers p where p.id=selected_producer_id and p.status='active' and p.is_verified=true and p.deleted_at is null;
  if producer_row.id is null then raise exception 'verified_active_producer_required' using errcode='55000'; end if;
  safe_payload:=jsonb_set(safe_payload,'{vendor_id}',to_jsonb(selected_producer_id::text),true);
  select * into existing_provenance from public.product_provenance pp where pp.product_id=v_product_id;

  if producer_row.store_kind='official' then
    source_mode_value:=coalesce(nullif(btrim(p_payload->>'sourceMode'),''),nullif(existing_provenance.source_mode,''),'platform_village_catalog');
    if source_mode_value not in ('platform_village_catalog','platform_direct','village_partner') then raise exception 'invalid_official_store_source_mode' using errcode='22023'; end if;
    source_name_value:=coalesce(nullif(btrim(p_payload->>'sourceDisplayName'),''),nullif(existing_provenance.source_display_name,''),case when source_mode_value='village_partner' then null else 'Golden Oremar Resmi Mağazası' end);
    if source_mode_value='village_partner' and char_length(coalesce(source_name_value,''))<2 then raise exception 'village_partner_name_required' using errcode='22023'; end if;
    source_country:=upper(coalesce(nullif(btrim(p_payload->>'sourceCountryCode'),''),nullif(existing_provenance.country_code,''),producer_row.production_country_code));
    source_province:=coalesce(nullif(btrim(p_payload->>'sourceProvince'),''),nullif(existing_provenance.province,''),producer_row.production_province);
    source_district:=coalesce(nullif(btrim(p_payload->>'sourceDistrict'),''),nullif(existing_provenance.district,''),producer_row.production_district);
    source_village:=coalesce(nullif(btrim(p_payload->>'sourceVillage'),''),nullif(existing_provenance.village,''),producer_row.production_village);
    source_locality:=coalesce(nullif(btrim(p_payload->>'sourceLocality'),''),nullif(existing_provenance.locality_detail,''),case when source_village='Yeşiltaş' then 'Dağlıca' else null end);
    if source_country is null or source_country !~ '^[A-Z]{2}$' or char_length(coalesce(source_province,''))<2 or char_length(coalesce(source_district,''))<2 or char_length(coalesce(source_village,''))<2 then raise exception 'complete_product_source_location_required' using errcode='22023'; end if;
    origin_label_value:=coalesce(nullif(btrim(p_payload->>'originLabel'),''),case when p_payload ? 'sourceProvince' or p_payload ? 'sourceDistrict' or p_payload ? 'sourceVillage' or p_payload ? 'sourceLocality' then null else nullif(existing_provenance.origin_label,'') end,
      concat_ws(', ',concat_ws(' - ',source_locality,source_village||' Köyü'),source_district,source_province));
    origin_verified_value:=case when p_payload ? 'originVerified' then (p_payload->>'originVerified')::boolean when v_product_id is not null and existing_provenance.product_id is not null then existing_provenance.origin_verified when source_mode_value='village_partner' then false else coalesce(producer_row.origin_verified,false) end;
    organic_claim_value:=coalesce(nullif(btrim(p_payload->>'organicClaim'),''),nullif(existing_provenance.organic_claim,''),'producer_declared_organic');
    if organic_claim_value not in ('producer_declared_organic','certification_in_progress','certified_organic','not_claimed') then raise exception 'invalid_organic_claim' using errcode='22023'; end if;
  else
    source_mode_value:='independent_producer';
    source_name_value:=producer_row.display_name;
    source_country:=producer_row.production_country_code;
    source_province:=producer_row.production_province;
    source_district:=producer_row.production_district;
    source_village:=producer_row.production_village;
    source_locality:=null;
    origin_label_value:=producer_row.production_location;
    origin_verified_value:=coalesce(producer_row.origin_verified,false) and private.is_producer_trust_badge_active_v1(producer_row.id);
    select pa.organic_claim into app_organic_claim from public.producer_applications pa where pa.id=producer_row.application_id and pa.status='approved';
    organic_claim_value:=case when app_organic_claim='certification_in_progress' then 'certification_in_progress' when app_organic_claim='certified' then 'producer_declared_organic' else 'not_claimed' end;
    if source_country is null or source_country !~ '^[A-Z]{2}$' or char_length(coalesce(source_province,''))<2 or char_length(coalesce(source_district,''))<2 or char_length(coalesce(source_village,''))<2 or char_length(coalesce(origin_label_value,''))<2 then raise exception 'producer_origin_incomplete' using errcode='55000'; end if;
  end if;

  safe_payload:=jsonb_set(safe_payload,'{origin}',to_jsonb(origin_label_value),true);
  result:=private.management_upsert_product_v1(p_reference,safe_payload);
  begin v_product_id:=(result->>'databaseId')::uuid; exception when others then raise exception 'product_write_result_invalid' using errcode='55000'; end;
  select * into product_row from public.products p where p.id=v_product_id and p.deleted_at is null for update;
  if product_row.id is null then raise exception 'product_not_found_after_write' using errcode='55000'; end if;

  if organic_claim_value='certified_organic' and not exists(
    select 1 from public.product_certifications c where c.product_id=v_product_id and c.status='valid' and lower(c.certificate_type) in ('organic','organic_certificate','certified_organic') and (c.expires_at is null or c.expires_at>=current_date)
  ) then raise exception 'valid_product_organic_certificate_required' using errcode='55000'; end if;

  insert into public.product_provenance(product_id,seller_model,source_mode,source_producer_id,source_display_name,country_code,province,district,village,locality_detail,origin_label,origin_verified,organic_claim,public_note)
  values(v_product_id,case when producer_row.store_kind='official' then 'official_store' else 'independent_producer' end,source_mode_value,
    case when producer_row.store_kind='official' then producer_row.id else producer_row.id end,source_name_value,source_country,source_province,source_district,source_village,source_locality,origin_label_value,origin_verified_value,organic_claim_value,
    case when producer_row.store_kind='official' then 'Golden Oremar resmi mağazası tarafından yönetilen ürün. Ürünün gerçek kaynak ve menşe bilgisi bu kayıt üzerinden izlenir; sertifikalı organik ibaresi yalnız geçerli sertifika varsa kullanılır.' else 'Bağımsız doğrulanmış üretici ürünü.' end)
  on conflict(product_id) do update set seller_model=excluded.seller_model,source_mode=excluded.source_mode,source_producer_id=excluded.source_producer_id,source_display_name=excluded.source_display_name,country_code=excluded.country_code,province=excluded.province,district=excluded.district,village=excluded.village,locality_detail=excluded.locality_detail,origin_label=excluded.origin_label,origin_verified=excluded.origin_verified,organic_claim=excluded.organic_claim,public_note=excluded.public_note,updated_at=timezone('utc',now());

  if product_row.status='published' and origin_verified_value is not true then raise exception 'published_product_origin_must_remain_verified' using errcode='55000'; end if;

  if requested_publish then
    if char_length(btrim(product_row.name))<2 or char_length(btrim(product_row.description))<20 or char_length(btrim(product_row.story))<20 then raise exception 'product_content_incomplete' using errcode='55000'; end if;
    if origin_verified_value is not true then raise exception 'verified_product_origin_required' using errcode='55000'; end if;
    if not exists(select 1 from public.product_variants v where v.product_id=v_product_id and v.is_active=true and v.price_minor>0) then raise exception 'active_priced_variant_required' using errcode='55000'; end if;
    if not private.product_media_integrity_ok_v1(v_product_id) then raise exception 'product_media_integrity_failed' using errcode='55000'; end if;
    result:=private.management_upsert_product_v1(v_product_id::text,jsonb_build_object('is_approved',true));
  end if;
  return result||jsonb_build_object('storeKind',producer_row.store_kind,'producerId',producer_row.id,'provenance',jsonb_build_object('sellerModel',case when producer_row.store_kind='official' then 'official_store' else 'independent_producer' end,'sourceMode',source_mode_value,'sourceDisplayName',source_name_value,'originLabel',origin_label_value,'originVerified',origin_verified_value,'organicClaim',organic_claim_value));
end;
$function$;

CREATE OR REPLACE FUNCTION private.mark_all_notifications_read_v1()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); affected integer;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  update public.notifications set read_at=timezone('utc',now()) where user_id=caller_id and read_at is null;
  get diagnostics affected=row_count;
  return affected;
end;
$function$;

CREATE OR REPLACE FUNCTION private.mark_conversation_read_v1(p_conversation_id uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); read_time timestamptz:=timezone('utc',now()); affected integer;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  update public.conversation_participants set last_read_at=read_time where conversation_id=p_conversation_id and user_id=caller_id;
  get diagnostics affected=row_count;
  if affected=0 then raise exception 'conversation_access_denied' using errcode='42501'; end if;
  return read_time;
end;
$function$;

CREATE OR REPLACE FUNCTION private.mark_notification_read_v1(p_notification_id uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); read_time timestamptz:=timezone('utc',now()); affected integer;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  update public.notifications set read_at=coalesce(read_at,read_time) where id=p_notification_id and user_id=caller_id;
  get diagnostics affected=row_count;
  if affected=0 then raise exception 'notification_not_found' using errcode='P0002'; end if;
  return read_time;
end;
$function$;

CREATE OR REPLACE FUNCTION private.mark_shipping_weight_provenance_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op='INSERT' then
    if new.weight_grams is not null and new.weight_grams>0 and coalesce(new.shipping_weight_source,'unknown')='unknown' then
      new.shipping_weight_source:='measured';
      new.shipping_weight_verified_at:=coalesce(new.shipping_weight_verified_at,timezone('utc',now()));
      new.shipping_weight_note:=coalesce(nullif(btrim(new.shipping_weight_note),''),'Ürün yönetiminden girilen paketli gönderi ağırlığı.');
    end if;
  elsif new.weight_grams is distinct from old.weight_grams
    and new.shipping_weight_source is not distinct from old.shipping_weight_source then
    if new.weight_grams is null or new.weight_grams<=0 then
      new.shipping_weight_source:='unknown';
      new.shipping_weight_verified_at:=null;
      new.shipping_weight_note:=null;
    else
      new.shipping_weight_source:='measured';
      new.shipping_weight_verified_at:=timezone('utc',now());
      new.shipping_weight_note:='Ürün yönetiminden güncellenen paketli gönderi ağırlığı.';
    end if;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.mask_tr_iban_v1(p_value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v text:=upper(regexp_replace(coalesce(p_value,''),'[^A-Za-z0-9]','','g'));
begin
  if v !~ '^TR[0-9]{24}$' then return null; end if;
  return substr(v,1,6)||' **** **** **** **** '||right(v,4);
end;
$function$;

CREATE OR REPLACE FUNCTION private.media_adopt_confirm_v1(p_bucket text, p_name text, p_etag text, p_sha256 text, p_width integer, p_height integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare verified boolean := false; r private.media_cdn_objects;
begin
  if p_bucket = 'catalog-public' then
    verified := exists (
      select 1 from storage.objects o join private.catalog_media_binary_verifications_v2 v on v.object_id = o.id
      where o.bucket_id = 'catalog-public' and o.name = p_name and v.object_path = p_name and v.sha256 = lower(p_sha256)
        and v.object_updated_at is not distinct from o.updated_at);
  end if;
  update private.media_cdn_objects
  set confirmed = true, mirrored_at = now(), sha256 = lower(p_sha256), width = p_width, height = p_height, binary_verified = verified
  where bucket_id = p_bucket and object_name = p_name and origin = 'direct' and not confirmed and deleting_at is null
    and source_etag = coalesce(p_etag,'') and lower(coalesce(p_sha256,'')) ~ '^[0-9a-f]{64}$'
  returning * into r;
  if r.id is null then return false; end if;
  if r.owner_user_id is not null then
    insert into private.media_upload_usage (user_id, byte_size) values (r.owner_user_id, r.byte_size);
  end if;
  delete from private.media_cdn_failures where bucket_id = p_bucket and object_name = p_name;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION private.media_adopt_reserve_v1(p_bucket text, p_name text, p_etag text, p_size bigint, p_content_type text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s private.media_cdn_settings; total bigint; owner uuid;
begin
  select * into s from private.media_cdn_settings where id for update;
  if not found or not s.enabled then return false; end if;
  select o.owner into owner from storage.objects o where o.bucket_id = p_bucket and o.name = p_name limit 1;
  if not exists (
    select 1 from private.media_cdn_sources_v1(p_bucket, p_name) src
    where src.source_etag = coalesce(p_etag,'') and src.byte_size = p_size and src.content_type = p_content_type and src.byte_size <= s.max_object_bytes) then
    return false;
  end if;
  if exists (select 1 from private.media_cdn_objects where bucket_id = p_bucket and object_name = p_name and origin = 'direct' and (confirmed or deleting_at is not null)) then return false; end if;
  if owner is not null and private.media_user_recent_bytes_v1(owner) + p_size > s.user_daily_bytes then return false; end if;
  select coalesce(sum(byte_size),0) into total from private.media_cdn_objects where not (bucket_id = p_bucket and object_name = p_name);
  if total + p_size > s.budget_bytes then return false; end if;
  insert into private.media_cdn_objects (bucket_id, object_name, source_etag, byte_size, content_type, confirmed, reserved_at, origin, owner_user_id, media_kind)
  values (p_bucket, p_name, coalesce(p_etag,''), p_size, p_content_type, false, now(), 'direct', owner, coalesce(private.media_direct_kind_v1(p_bucket, p_name), 'adopted'))
  on conflict (bucket_id, object_name) do update
    set source_etag = excluded.source_etag, byte_size = excluded.byte_size, content_type = excluded.content_type, confirmed = false,
        reserved_at = now(), mirrored_at = null, origin = 'direct', owner_user_id = excluded.owner_user_id, media_kind = excluded.media_kind,
        sha256 = null, width = null, height = null, binary_verified = false, staging_key = null;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION private.media_cdn_fail_v1(p_bucket text, p_name text, p_etag text, p_reason text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  insert into private.media_cdn_failures (bucket_id, object_name, source_etag, reason)
  values (p_bucket, p_name, coalesce(p_etag,''), left(coalesce(nullif(btrim(p_reason),''),'unknown'), 200))
  on conflict (bucket_id, object_name) do update
    set reason = excluded.reason,
        attempts = case when private.media_cdn_failures.source_etag = excluded.source_etag then private.media_cdn_failures.attempts + 1 else 1 end,
        source_etag = excluded.source_etag,
        last_attempt_at = now();
$function$;

CREATE OR REPLACE FUNCTION private.media_cdn_finish_v1(p_status text, p_detail jsonb)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  update private.media_cdn_settings
  set last_run_at = now(), last_run_status = left(coalesce(p_status,'unknown'), 64), last_run_detail = p_detail, updated_at = now()
  where id;
$function$;

CREATE OR REPLACE FUNCTION private.media_cdn_forget_v1(p_bucket text, p_name text)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with gone as (
    delete from private.media_cdn_objects
    where bucket_id = p_bucket and object_name = p_name
      and ((deleting_at is not null and delete_after <= now()) or (not confirmed and deleting_at is null) or origin = 'mirror')
    returning 1)
  select exists (select 1 from gone);
$function$;

CREATE OR REPLACE FUNCTION private.media_cdn_has_work_v1()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare plan jsonb;
begin
  if not exists (select 1 from private.media_cdn_settings where id and enabled) then return false; end if;
  if private.media_staging_sweep_due_v1() then return true; end if;
  if exists (select 1 from private.media_cdn_objects where deleting_at is not null and delete_after <= now()) then return true; end if;
  if exists (select 1 from private.media_cdn_objects where origin = 'direct' and not confirmed and deleting_at is null and reserved_at < now() - interval '1 hour') then return true; end if;
  if exists (select 1 from private.media_cdn_objects where origin = 'direct' and confirmed and media_kind is distinct from 'adopted'
             and reserved_at < now() - interval '72 hours'
             and (last_reference_check_at is null or last_reference_check_at < now() - interval '6 hours')) then return true; end if;
  plan := private.media_cdn_plan_v1(1);
  return jsonb_array_length(plan->'uploads') > 0 or jsonb_array_length(plan->'offloads') > 0 or jsonb_array_length(plan->'deletes') > 0;
end;
$function$;

CREATE OR REPLACE FUNCTION private.media_cdn_plan_v1(p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  s private.media_cdn_settings;
  total bigint;
  uploads jsonb; offloads jsonb; deletes jsonb; blocked integer;
begin
  select * into s from private.media_cdn_settings where id;
  if not found then raise exception 'media_cdn_settings_missing' using errcode = 'P0002'; end if;
  select coalesce(sum(byte_size),0) into total from private.media_cdn_objects;
  select coalesce(jsonb_agg(jsonb_build_object('bucket', g.bucket_id, 'name', g.object_name)), '[]'::jsonb) into deletes
  from (
    with src as materialized (select * from private.media_cdn_sources_v1())
    select m.bucket_id, m.object_name from private.media_cdn_objects m
    where m.origin = 'mirror' and not exists (select 1 from src where src.bucket_id = m.bucket_id and src.object_name = m.object_name)
    limit 50) g;
  select coalesce(jsonb_agg(jsonb_build_object('bucket', g.bucket_id, 'name', g.object_name)), '[]'::jsonb) into offloads
  from (
    select src.bucket_id, src.object_name
    from private.media_cdn_sources_v1() src
    join private.media_cdn_objects m on m.bucket_id = src.bucket_id and m.object_name = src.object_name and m.origin = 'direct' and m.confirmed
    where s.offload_sources
    limit 50) g;
  with candidates as (
    select src.*, coalesce(m.byte_size, 0) as previous_bytes
    from private.media_cdn_sources_v1() src
    left join private.media_cdn_objects m on m.bucket_id = src.bucket_id and m.object_name = src.object_name
    where src.byte_size <= s.max_object_bytes
      and src.created_at < now() - interval '2 minutes'
      and (src.bucket_id <> 'catalog-public' or src.created_at < now() - interval '30 minutes'
           or exists (select 1 from private.catalog_media_binary_verifications_v2 v where v.bucket_id = 'catalog-public' and v.object_path = src.object_name))
      and (m.object_name is null
           or m.origin = 'mirror'
           or (m.origin = 'direct' and not m.confirmed and m.deleting_at is null and m.reserved_at < now() - interval '10 minutes'
               and m.staging_key is null))
      and not exists (
        select 1 from private.media_cdn_failures f
        where f.bucket_id = src.bucket_id and f.object_name = src.object_name and f.source_etag = src.source_etag
          and (f.attempts >= 3 or f.last_attempt_at > now() - (interval '10 minutes' * f.attempts)))
  ), ranked as (
    select c.*, total + sum(c.byte_size - c.previous_bytes) over (order by c.created_at, c.bucket_id, c.object_name) as projected
    from candidates c
  )
  select
    coalesce((select jsonb_agg(jsonb_build_object('bucket', r.bucket_id, 'name', r.object_name, 'etag', r.source_etag, 'size', r.byte_size, 'contentType', r.content_type) order by r.created_at)
              from (select * from ranked where projected <= s.budget_bytes order by created_at limit greatest(1, least(coalesce(p_limit, s.batch_size), s.batch_size))) r), '[]'::jsonb),
    (select count(*) from ranked where projected > s.budget_bytes)::integer
  into uploads, blocked;
  return jsonb_build_object(
    'enabled', s.enabled, 'accountId', s.r2_account_id, 'bucket', s.r2_bucket, 'stagingBucket', s.r2_staging_bucket,
    'mirroredBytes', total, 'budgetBytes', s.budget_bytes, 'warnBytes', s.warn_bytes, 'maxObjectBytes', s.max_object_bytes,
    'budgetBlocked', blocked, 'offloadSources', s.offload_sources,
    'stagingSweepDue', private.media_staging_sweep_due_v1(),
    'uploads', uploads, 'offloads', offloads, 'deletes', deletes);
end;
$function$;

CREATE OR REPLACE FUNCTION private.media_cdn_sources_v1(p_bucket text DEFAULT NULL::text, p_name text DEFAULT NULL::text)
 RETURNS TABLE(bucket_id text, object_name text, source_etag text, byte_size bigint, content_type text, created_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select o.bucket_id, o.name, coalesce(o.metadata->>'eTag',''), (o.metadata->>'size')::bigint, lower(o.metadata->>'mimetype'), o.created_at
  from storage.objects o
  where o.bucket_id in ('catalog-public','content-public','event-public')
    and (p_bucket is null or o.bucket_id = p_bucket)
    and (p_name is null or o.name = p_name)
    and coalesce(o.is_delete_marker,false) = false
    and o.archived_at is null
    and lower(coalesce(o.metadata->>'mimetype','')) in ('image/jpeg','image/png','image/webp','image/avif')
    and coalesce(o.metadata->>'size','') ~ '^[0-9]{1,12}$'
    and (o.metadata->>'size')::bigint > 0
    and char_length(o.name) between 1 and 1024
    and o.name !~ '(^/|//|/$|(^|/)[.]{1,2}(/|$)|[\\[:cntrl:]])';
$function$;

CREATE OR REPLACE FUNCTION private.media_cdn_target_v1()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'enabled', s.enabled,
    'accountId', s.r2_account_id,
    'bucket', s.r2_bucket,
    'stagingBucket', s.r2_staging_bucket,
    'signContentLength', s.sign_content_length,
    'publicBaseUrl', s.public_base_url,
    'maxVideoBytes', s.max_video_bytes)
  from private.media_cdn_settings s where s.id;
$function$;

CREATE OR REPLACE FUNCTION private.media_direct_begin_publish_v1(p_user uuid, p_bucket text, p_name text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  update private.media_cdn_objects
  set publishing_at = now()
  where bucket_id = p_bucket and object_name = p_name and origin = 'direct' and owner_user_id = p_user
    and not confirmed and deleting_at is null and staging_key is not null
    and (publishing_at is null or publishing_at < now() - interval '5 minutes')
  returning jsonb_build_object('size', byte_size, 'contentType', content_type, 'staging', staging_key);
$function$;

CREATE OR REPLACE FUNCTION private.media_direct_begin_release_v2(p_user uuid, p_bucket text, p_name text, p_allow_confirmed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r private.media_cdn_objects;
begin
  select * into r from private.media_cdn_objects
  where bucket_id = p_bucket and object_name = p_name and origin = 'direct' and owner_user_id = p_user
  for update;
  if r.id is null then return null; end if;
  if r.deleting_at is not null then
    return jsonb_build_object('bucket', r.bucket_id, 'name', r.object_name, 'staging', r.staging_key, 'deferred', true);
  end if;
  if r.confirmed then
    if not coalesce(p_allow_confirmed, false) or r.reserved_at < now() - interval '24 hours' then return null; end if;
    if coalesce(array_length(private.media_unreferenced_v1(array[p_name]), 1), 0) = 0 then return null; end if;
    update private.media_cdn_objects
    set deleting_at = now(), delete_after = now() + interval '10 minutes', restore_binary_verified = r.binary_verified,
        confirmed = false, binary_verified = false
    where id = r.id;
    return jsonb_build_object('bucket', r.bucket_id, 'name', r.object_name, 'staging', r.staging_key, 'deferred', true);
  end if;
  if r.publishing_at is not null and r.publishing_at > now() - interval '5 minutes' then return null; end if;
  update private.media_cdn_objects
  set deleting_at = now(), delete_after = now() + interval '10 minutes', restore_binary_verified = null
  where id = r.id;
  return jsonb_build_object('bucket', r.bucket_id, 'name', r.object_name, 'staging', r.staging_key, 'deferred', false);
end;
$function$;

CREATE OR REPLACE FUNCTION private.media_direct_confirm_v1(p_user uuid, p_bucket text, p_name text, p_size bigint, p_content_type text, p_sha256 text, p_width integer, p_height integer)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with done as (
    update private.media_cdn_objects
    set confirmed = true, mirrored_at = now(), sha256 = lower(p_sha256), width = p_width, height = p_height,
        binary_verified = (p_content_type like 'image/%'), staging_key = null, publishing_at = null
    where bucket_id = p_bucket and object_name = p_name and origin = 'direct' and owner_user_id = p_user
      and not confirmed and deleting_at is null and publishing_at is not null
      and byte_size = p_size and content_type = p_content_type
      and lower(coalesce(p_sha256,'')) ~ '^[0-9a-f]{64}$'
      and (p_content_type like 'video/%' or (p_width between 1 and 20000 and p_height between 1 and 20000))
    returning 1)
  select exists (select 1 from done);
$function$;

CREATE OR REPLACE FUNCTION private.media_direct_end_publish_v1(p_user uuid, p_bucket text, p_name text)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with done as (
    update private.media_cdn_objects set publishing_at = null
    where bucket_id = p_bucket and object_name = p_name and origin = 'direct' and owner_user_id = p_user and not confirmed
    returning 1)
  select exists (select 1 from done);
$function$;

CREATE OR REPLACE FUNCTION private.media_direct_finish_release_v1(p_user uuid, p_bucket text, p_name text)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with gone as (
    delete from private.media_cdn_objects
    where bucket_id = p_bucket and object_name = p_name and origin = 'direct' and owner_user_id = p_user
      and deleting_at is not null and restore_binary_verified is null
    returning 1)
  select exists (select 1 from gone);
$function$;

CREATE OR REPLACE FUNCTION private.media_direct_kind_v1(p_bucket text, p_name text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  with u as (select '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}'::text as id)
  select case
    when p_bucket = 'catalog-public' and p_name ~ ('^' || u.id || '/products/' || u.id || '[.](jpg|jpeg|png|webp|avif)$') then 'product-image'
    when p_bucket = 'catalog-public' and p_name ~ ('^' || u.id || '/products/' || u.id || '[.](mp4|webm|mov)$') then 'product-video'
    when p_bucket = 'catalog-public' and p_name ~ ('^admin/' || u.id || '/official-products/' || u.id || '[.](jpg|jpeg|png|webp|avif)$') then 'official-image'
    when p_bucket = 'catalog-public' and p_name ~ ('^admin/' || u.id || '/official-products/' || u.id || '[.](mp4|webm|mov)$') then 'official-video'
    when p_bucket = 'catalog-public' and p_name ~ ('^admin/' || u.id || '/categories/' || u.id || '[.](jpg|jpeg|png|webp|avif)$') then 'category-image'
    when p_bucket = 'catalog-public' and p_name ~ ('^' || u.id || '/profile/logo-' || u.id || '[.](jpg|jpeg|png|webp)$') then 'brand-logo'
    when p_bucket = 'catalog-public' and p_name ~ ('^' || u.id || '/profile/cover-' || u.id || '[.](jpg|jpeg|png|webp)$') then 'brand-cover'
    when p_bucket = 'event-public' and p_name ~ ('^' || u.id || '/events/' || u.id || '[.](jpg|jpeg|png|webp|avif)$') then 'event-image'
  end
  from u;
$function$;

CREATE OR REPLACE FUNCTION private.media_direct_max_bytes_v1(p_kind text)
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select case
    when p_kind in ('product-video','official-video') then s.max_video_bytes
    when p_kind in ('brand-logo','brand-cover') then 5242880
    when p_kind is not null then 10485760
  end
  from private.media_cdn_settings s where s.id;
$function$;

CREATE OR REPLACE FUNCTION private.media_direct_reservation_v1(p_user uuid, p_bucket text, p_name text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object('size', m.byte_size, 'contentType', m.content_type, 'staging', m.staging_key,
                            'confirmed', m.confirmed, 'deleting', m.deleting_at is not null,
                            'publishing', m.publishing_at is not null and m.publishing_at > now() - interval '5 minutes')
  from private.media_cdn_objects m
  where m.bucket_id = p_bucket and m.object_name = p_name and m.origin = 'direct' and m.owner_user_id = p_user;
$function$;

CREATE OR REPLACE FUNCTION private.media_direct_reserve_v2(p_user uuid, p_bucket text, p_name text, p_size bigint, p_content_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  s private.media_cdn_settings;
  kind text := private.media_direct_kind_v1(p_bucket, p_name);
  producer public.producers%rowtype;
  total bigint; videos bigint; pending integer; staging text;
begin
  select * into s from private.media_cdn_settings where id for update;
  if not found or not s.enabled or s.public_base_url is null then return jsonb_build_object('status', 'not_configured'); end if;
  if p_user is null or kind is null or not private.media_extension_matches_v1(p_name, p_content_type) then return jsonb_build_object('status', 'invalid_name'); end if;
  if (kind like '%-video') <> (p_content_type like 'video/%') then return jsonb_build_object('status', 'invalid_name'); end if;
  if p_size is null or p_size < 1 or p_size > private.media_direct_max_bytes_v1(kind) then return jsonb_build_object('status', 'size_invalid'); end if;
  if kind in ('official-image','official-video','category-image') then
    if split_part(p_name, '/', 2) <> p_user::text then return jsonb_build_object('status', 'owner_mismatch'); end if;
  else
    select * into producer from public.producers pr where pr.id = split_part(p_name, '/', 1)::uuid and pr.deleted_at is null;
    if producer.id is null then return jsonb_build_object('status', 'owner_mismatch'); end if;
    if kind in ('product-image','product-video') then
      if producer.owner_user_id is distinct from p_user or producer.status <> 'active' or not producer.is_verified or not producer.origin_verified then
        return jsonb_build_object('status', 'owner_mismatch');
      end if;
    elsif kind in ('brand-logo','brand-cover') then
      if not producer.is_verified then return jsonb_build_object('status', 'owner_mismatch'); end if;
      if producer.store_kind = 'official' then
        if producer.status <> 'active' then return jsonb_build_object('status', 'owner_mismatch'); end if;
      elsif producer.owner_user_id is distinct from p_user or producer.status not in ('pending','active') then
        return jsonb_build_object('status', 'owner_mismatch');
      end if;
    elsif kind = 'event-image' then
      if producer.owner_user_id is distinct from p_user or not private.is_producer_trust_badge_active_v1(producer.id) then
        return jsonb_build_object('status', 'owner_mismatch');
      end if;
    end if;
  end if;
  select count(*) into pending from private.media_cdn_objects
  where origin = 'direct' and owner_user_id = p_user and not confirmed and deleting_at is null and reserved_at > now() - interval '1 hour';
  if pending >= 20 then return jsonb_build_object('status', 'too_many_pending'); end if;
  if private.media_user_recent_bytes_v1(p_user) + p_size > s.user_daily_bytes then return jsonb_build_object('status', 'daily_limit'); end if;
  select coalesce(sum(byte_size),0), coalesce(sum(byte_size) filter (where content_type like 'video/%'),0) into total, videos from private.media_cdn_objects;
  if total + p_size > s.budget_bytes then return jsonb_build_object('status', 'budget_full'); end if;
  if p_content_type like 'video/%' and videos + p_size > s.video_budget_bytes then return jsonb_build_object('status', 'budget_full'); end if;
  staging := '_incoming/' || gen_random_uuid()::text;
  insert into private.media_cdn_objects (bucket_id, object_name, source_etag, byte_size, content_type, confirmed, reserved_at, origin, owner_user_id, media_kind, staging_key)
  values (p_bucket, p_name, '', p_size, p_content_type, false, now(), 'direct', p_user, kind, staging);
  -- Counted when reserved and never refunded: a refused or cancelled upload
  -- still used the allowance.
  insert into private.media_upload_usage (user_id, byte_size) values (p_user, p_size);
  return jsonb_build_object('status', 'reserved', 'staging', staging);
exception when unique_violation then
  return jsonb_build_object('status', 'invalid_name');
end;
$function$;

CREATE OR REPLACE FUNCTION private.media_extension_matches_v1(p_name text, p_content_type text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select coalesce(
       (p_content_type = 'image/jpeg' and lower(p_name) ~ '[.](jpg|jpeg)$')
    or (p_content_type = 'image/png' and lower(p_name) ~ '[.]png$')
    or (p_content_type = 'image/webp' and lower(p_name) ~ '[.]webp$')
    or (p_content_type = 'image/avif' and lower(p_name) ~ '[.]avif$')
    or (p_content_type = 'video/mp4' and lower(p_name) ~ '[.]mp4$')
    or (p_content_type = 'video/webm' and lower(p_name) ~ '[.]webm$')
    or (p_content_type = 'video/quicktime' and lower(p_name) ~ '[.]mov$'), false);
$function$;

CREATE OR REPLACE FUNCTION private.media_gc_candidates_v3(p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  lim integer := greatest(1, least(coalesce(p_limit, 50), 100));
  names text[]; free text[]; due text[]; still_free text[];
begin
  -- Unfinished uploads: never confirmed, so nothing can reference them.
  update private.media_cdn_objects
  set deleting_at = now(), delete_after = now(), restore_binary_verified = null
  where id in (select id from private.media_cdn_objects
               where origin = 'direct' and not confirmed and deleting_at is null and reserved_at < now() - interval '1 hour'
                 and (publishing_at is null or publishing_at < now() - interval '10 minutes')
               order by reserved_at limit lim);

  -- Files nothing refers to: first sighting, then a second one 72 h later.
  select array_agg(object_name) into names from (
    select object_name from private.media_cdn_objects
    where origin = 'direct' and confirmed and deleting_at is null and media_kind is distinct from 'adopted'
      and reserved_at < now() - interval '72 hours'
      and (last_reference_check_at is null or last_reference_check_at < now() - interval '6 hours')
    order by last_reference_check_at nulls first, reserved_at
    limit lim) d;
  if names is not null then
    free := private.media_unreferenced_v1(names);
    update private.media_cdn_objects
    set last_reference_check_at = now(),
        first_unreferenced_at = case when object_name = any(free) then coalesce(first_unreferenced_at, now()) else null end
    where origin = 'direct' and confirmed and deleting_at is null and media_kind is distinct from 'adopted' and object_name = any(names);
    -- Marked, not deleted: a save that checked the file just before this
    -- statement may still commit. The second check below catches it.
    update private.media_cdn_objects
    set deleting_at = now(), delete_after = now() + interval '10 minutes', restore_binary_verified = binary_verified,
        confirmed = false, binary_verified = false
    where origin = 'direct' and confirmed and deleting_at is null and media_kind is distinct from 'adopted'
      and object_name = any(free) and first_unreferenced_at < now() - interval '72 hours';
  end if;

  -- Second check for files that were usable when marked.
  select array_agg(object_name) into due from (
    select object_name from private.media_cdn_objects
    where deleting_at is not null and delete_after <= now() and restore_binary_verified is not null
    limit lim) d;
  if due is not null then
    still_free := coalesce(private.media_unreferenced_v1(due), '{}');
    update private.media_cdn_objects
    set deleting_at = null, delete_after = null, confirmed = true, binary_verified = restore_binary_verified,
        restore_binary_verified = null, first_unreferenced_at = null, last_reference_check_at = now()
    where deleting_at is not null and restore_binary_verified is not null and object_name = any(due) and not (object_name = any(still_free));
  end if;

  -- The allowance record only needs a day; keep three.
  delete from private.media_upload_usage where used_at < now() - interval '3 days';

  return jsonb_build_object('delete', coalesce((
    select jsonb_agg(jsonb_build_object('bucket', bucket_id, 'name', object_name, 'staging', staging_key))
    from (select bucket_id, object_name, staging_key from private.media_cdn_objects
          where deleting_at is not null and delete_after <= now()
            and (restore_binary_verified is null or object_name = any(coalesce(still_free, '{}')))
          order by delete_after limit lim) x), '[]'::jsonb));
end;
$function$;

CREATE OR REPLACE FUNCTION private.media_public_url_v1(p_bucket text, p_name text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select s.public_base_url || '/' || p_bucket || '/' || p_name
  from private.media_cdn_settings s
  where s.id and s.enabled and s.public_base_url is not null
    and p_name ~ '^[A-Za-z0-9._/-]+$'
    and exists (select 1 from private.media_cdn_objects m where m.bucket_id = p_bucket and m.object_name = p_name and m.origin = 'direct' and m.confirmed);
$function$;

CREATE OR REPLACE FUNCTION private.media_staging_sweep_due_v1()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select s.last_staging_sweep_at is null
      or s.last_staging_sweep_at < now() - interval '6 hours'
      or exists (select 1 from private.media_upload_usage u where u.used_at > s.last_staging_sweep_at - interval '30 minutes')
  from private.media_cdn_settings s where s.id;
$function$;

CREATE OR REPLACE FUNCTION private.media_staging_swept_v1()
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  update private.media_cdn_settings set last_staging_sweep_at = now() where id;
$function$;

CREATE OR REPLACE FUNCTION private.media_unreferenced_v1(p_names text[])
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record; remaining text[] := coalesce(p_names, '{}');
begin
  if coalesce(array_length(remaining, 1), 0) = 0 then return '{}'; end if;
  for r in
    select c.table_schema, c.table_name, c.column_name
    from information_schema.columns c
    join information_schema.tables t on t.table_schema = c.table_schema and t.table_name = c.table_name and t.table_type = 'BASE TABLE'
    where c.table_schema in ('public','private')
      and c.data_type in ('text','character varying','jsonb','json','ARRAY')
      and not (c.table_schema = 'private' and c.table_name in ('audit_log','catalog_media_binary_verifications_v2','media_cdn_objects','media_cdn_failures','media_cdn_settings'))
  loop
    execute format('select coalesce(array_agg(n), ''{}'') from unnest($1) n where not exists (select 1 from %I.%I x where strpos(x.%I::text, n) > 0)',
                   r.table_schema, r.table_name, r.column_name)
      into remaining using remaining;
    exit when coalesce(array_length(remaining, 1), 0) = 0;
  end loop;
  return remaining;
end;
$function$;

CREATE OR REPLACE FUNCTION private.media_user_recent_bytes_v1(p_user uuid)
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(sum(byte_size), 0) from private.media_upload_usage
  where user_id = p_user and used_at > now() - interval '24 hours';
$function$;

CREATE OR REPLACE FUNCTION private.message_contains_disallowed_contact_v1(p_body text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  value text:=lower(btrim(coalesce(p_body,'')));
begin
  if value='' then return false; end if;

  if value ~* '(^|[^[:alnum:]_.+-])[[:alnum:]_.+-]+@[[:alnum:]-]+(\.[[:alnum:]-]+)+([^[:alnum:]_.+-]|$)' then
    return true;
  end if;

  if value ~* '(^|[^[:alnum:]])(mailto:|tel:)' then
    return true;
  end if;

  if value ~* '(^|[^0-9])\+?[0-9]([ .()/-]*[0-9]){9,14}([^0-9]|$)' then
    return true;
  end if;

  if value ~* '(^|[^[:alnum:]])(whatsapp|wa\.me|telegram|t\.me)[[:space:]:=@/+_-]*[[:alnum:]@+_.-]{3,}' then
    return true;
  end if;

  return false;
end;
$function$;

CREATE OR REPLACE FUNCTION private.message_moderation_violation_v1(p_body text, p_conversation_type text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  settings private.message_moderation_settings%rowtype;
  value text:=lower(btrim(coalesce(p_body,'')));
  phrase text;
begin
  select * into settings from private.message_moderation_settings where singleton=true;
  if not found or not settings.enabled then return null; end if;
  if coalesce(p_conversation_type,'') <> 'producer' and not (coalesce(p_conversation_type,'')='support' and settings.apply_to_support) then return null; end if;
  if value='' then return null; end if;

  if settings.block_email and value ~* '(^|[^[:alnum:]_.+-])[[:alnum:]_.+-]+@[[:alnum:]-]+(\.[[:alnum:]-]+)+([^[:alnum:]_.+-]|$)' then return 'email'; end if;
  if settings.block_phone and (value ~* '(^|[^0-9])\+?[0-9]([ .()/-]*[0-9]){9,14}([^0-9]|$)' or value ~* '(^|[^[:alnum:]])tel:') then return 'phone'; end if;
  if settings.block_messaging_apps and value ~* '(^|[^[:alnum:]])(whatsapp|wa\.me|telegram|t\.me|signal|viber)[[:space:]:=@/+_-]*[[:alnum:]@+_.-]{2,}' then return 'messaging_app'; end if;
  if settings.block_external_links and value ~* '(^|[^[:alnum:]])(https?://|www\.)[^[:space:]]+' then return 'external_link'; end if;
  if settings.block_social_handles and value ~* '(^|[^[:alnum:]])(instagram|facebook|tiktok|twitter|snapchat|discord|x\.com)[[:space:]:=@/+_-]*@?[[:alnum:]_.-]{3,}' then return 'social_handle'; end if;
  if settings.block_bank_details and (value ~* '(^|[^[:alnum:]])[a-z]{2}[0-9]{2}[a-z0-9]{11,30}([^[:alnum:]]|$)' or value ~* '(^|[^[:alnum:]])(iban|swift|bic|bank account|banka hesabı|hesap no)[^[:alnum:]]') then return 'bank_details'; end if;
  if settings.block_external_payments and value ~* '(^|[^[:alnum:]])(paypal|wise|revolut|western union|moneygram|cash ?app|venmo|usdt|bitcoin|btc|crypto|kripto|havale|eft)([^[:alnum:]]|$)' then return 'external_payment'; end if;
  if settings.block_qr_codes and value ~* '(^|[^[:alnum:]])(qr[[:space:]_-]*(code|kod)|karekod)([^[:alnum:]]|$)' then return 'qr_code'; end if;

  foreach phrase in array coalesce(settings.custom_blocked_phrases,'{}'::text[])
  loop
    phrase:=lower(btrim(phrase));
    if char_length(phrase)>=2 and position(phrase in value)>0 then return 'custom_phrase'; end if;
  end loop;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION private.normalize_brand_appearance_v1(p_appearance jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  default_theme text;
  color_scheme text;
  tokens jsonb;
  normalized_tokens jsonb;
  required_keys constant text[] := array['background','card','text','muted','border','brandGold','brandGreen','brandEarth','onGold','onGreen'];
  key text;
  value text;
begin
  if p_appearance is null or jsonb_typeof(p_appearance)<>'object' then
    raise exception 'invalid_brand_appearance' using errcode='22023';
  end if;
  if exists(select 1 from jsonb_object_keys(p_appearance) k where k not in ('defaultTheme','colorScheme','tokens')) then
    raise exception 'unsupported_brand_appearance_setting' using errcode='22023';
  end if;
  default_theme := lower(btrim(coalesce(p_appearance->>'defaultTheme','')));
  if default_theme not in ('custom','light','dark','emerald','ruby','champagne') then
    raise exception 'invalid_brand_default_theme' using errcode='22023';
  end if;
  color_scheme := lower(btrim(coalesce(p_appearance->>'colorScheme','')));
  if color_scheme not in ('light','dark') then
    raise exception 'invalid_brand_color_scheme' using errcode='22023';
  end if;
  tokens := p_appearance->'tokens';
  if jsonb_typeof(tokens)<>'object' then
    raise exception 'invalid_brand_appearance_tokens' using errcode='22023';
  end if;
  if exists(select 1 from jsonb_object_keys(tokens) k where not (k=any(required_keys))) then
    raise exception 'unsupported_brand_appearance_token' using errcode='22023';
  end if;
  foreach key in array required_keys loop
    if not (tokens ? key) then raise exception 'missing_brand_appearance_token:%',key using errcode='22023'; end if;
    value := upper(btrim(coalesce(tokens->>key,'')));
    if value !~ '^#[0-9A-F]{6}$' then raise exception 'invalid_brand_appearance_token:%',key using errcode='22023'; end if;
    normalized_tokens := coalesce(normalized_tokens,'{}'::jsonb) || jsonb_build_object(key,value);
  end loop;
  if private.brand_contrast_ratio_v1(normalized_tokens->>'text',normalized_tokens->>'background') < 4.5 then
    raise exception 'insufficient_brand_text_contrast' using errcode='22023';
  end if;
  if private.brand_contrast_ratio_v1(normalized_tokens->>'muted',normalized_tokens->>'background') < 4.5 then
    raise exception 'insufficient_brand_muted_contrast' using errcode='22023';
  end if;
  if private.brand_contrast_ratio_v1(normalized_tokens->>'text',normalized_tokens->>'card') < 4.5 then
    raise exception 'insufficient_brand_card_text_contrast' using errcode='22023';
  end if;
  if private.brand_contrast_ratio_v1(normalized_tokens->>'onGreen',normalized_tokens->>'brandGreen') < 4.5 then
    raise exception 'insufficient_brand_green_contrast' using errcode='22023';
  end if;
  if private.brand_contrast_ratio_v1(normalized_tokens->>'onGold',normalized_tokens->>'brandGold') < 4.5 then
    raise exception 'insufficient_brand_gold_contrast' using errcode='22023';
  end if;
  return jsonb_build_object('defaultTheme',default_theme,'colorScheme',color_scheme,'tokens',normalized_tokens);
end;
$function$;

CREATE OR REPLACE FUNCTION private.normalize_coupon_code_v1(p_code text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  normalized text := upper(regexp_replace(btrim(coalesce(p_code,'')), '\s+', '', 'g'));
begin
  if char_length(normalized) not between 4 and 40
    or normalized !~ '^[A-Z0-9_-]+$' then
    raise exception 'invalid_coupon_code' using errcode='22023';
  end if;
  return normalized;
end;
$function$;

CREATE OR REPLACE FUNCTION private.normalize_order_customization_v1(p_product_id uuid, p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  schema_value jsonb;
  schema_updated_at timestamptz;
  choices_input jsonb;
  normalized_choices jsonb:='{}'::jsonb;
  normalized_labels jsonb:='{}'::jsonb;
  group_row jsonb;
  choice_row jsonb;
  visible_when jsonb;
  group_key text;
  selected_value text;
  selected_label text;
  visible boolean;
  unknown_key text;
begin
  if p_input is null or p_input='null'::jsonb then return null; end if;
  if jsonb_typeof(p_input)<>'object' or pg_column_size(p_input)>8192 or coalesce(p_input->>'schemaVersion','')<>'1' then raise exception 'invalid_order_customization' using errcode='22023'; end if;
  choices_input:=p_input->'choices';
  if choices_input is null or jsonb_typeof(choices_input)<>'object' or pg_column_size(choices_input)>4096 then raise exception 'invalid_order_customization_choices' using errcode='22023'; end if;
  select profile.option_schema,profile.updated_at into schema_value,schema_updated_at from public.product_commerce_profiles profile where profile.product_id=p_product_id;
  if schema_value is null or jsonb_array_length(schema_value)=0 then raise exception 'order_customization_not_supported' using errcode='22023'; end if;
  schema_value:=private.normalize_product_option_schema_v1(schema_value);
  select key into unknown_key from jsonb_object_keys(choices_input) key where not exists(select 1 from jsonb_array_elements(schema_value) g where g->>'key'=key) limit 1;
  if unknown_key is not null then raise exception 'unsupported_order_customization_choice:%',unknown_key using errcode='22023'; end if;
  for group_row in select value from jsonb_array_elements(schema_value) loop
    group_key:=group_row->>'key'; visible_when:=group_row->'visibleWhen';
    visible:=visible_when is null or coalesce(choices_input->>(visible_when->>'key'),'')=coalesce(visible_when->>'equals','');
    selected_value:=nullif(btrim(coalesce(choices_input->>group_key,'')),'');
    if not visible then if selected_value is not null then raise exception 'hidden_order_customization_choice:%',group_key using errcode='22023'; end if; continue; end if;
    if coalesce((group_row->>'required')::boolean,false) and selected_value is null then raise exception 'required_order_customization_choice:%',group_key using errcode='22023'; end if;
    if selected_value is null then continue; end if;
    selected_label:=null;
    for choice_row in select value from jsonb_array_elements(group_row->'choices') loop if choice_row->>'value'=selected_value then selected_label:=choice_row->>'label'; exit; end if; end loop;
    if selected_label is null then raise exception 'invalid_order_customization_choice:%',group_key using errcode='22023'; end if;
    normalized_choices:=normalized_choices||jsonb_build_object(group_key,selected_value);
    normalized_labels:=normalized_labels||jsonb_build_object(group_key,jsonb_build_object('group',group_row->>'label','choice',selected_label));
  end loop;
  return jsonb_build_object('schemaVersion',1,'choices',normalized_choices,'labels',normalized_labels,'profileRevision',schema_updated_at);
end;
$function$;

CREATE OR REPLACE FUNCTION private.normalize_payment_intent_subject_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.subject_type:=lower(btrim(coalesce(new.subject_type,'order')));
  if new.subject_type='order' then
    if new.order_id is null then raise exception 'payment_order_subject_required' using errcode='22023'; end if;
    if new.subject_id is null then new.subject_id:=new.order_id; end if;
    if new.subject_id<>new.order_id then raise exception 'payment_subject_mismatch' using errcode='22023'; end if;
  elsif new.subject_type='event_reservation' then
    if new.subject_id is null then raise exception 'payment_event_reservation_subject_required' using errcode='22023'; end if;
    if new.order_id is not null then raise exception 'payment_event_subject_cannot_have_order' using errcode='22023'; end if;
  else
    raise exception 'unsupported_payment_subject_type' using errcode='22023';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.normalize_product_editorial_payload_v1(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  title_value text; summary_value text; info jsonb; safety jsonb; recipe jsonb; nutrition jsonb;
  ingredients jsonb; usage_notes jsonb; storage_items jsonb; prep_items jsonb; warning_items jsonb; allergens jsonb; recipe_ingredients jsonb; recipe_steps jsonb;
  recipe_enabled boolean:=false; serving_size text; allergen_note text; recipe_title text; servings integer; prep_minutes integer; cook_minutes integer;
  nutrition_result jsonb:='{}'::jsonb; key text; numeric_value numeric;
  allowed_nutrition constant text[]:=array['energyKcal','proteinG','carbohydrateG','sugarsG','fatG','saturatedFatG','fiberG','saltG'];
begin
  if p_payload is null or jsonb_typeof(p_payload)<>'object' or pg_column_size(p_payload)>131072 then raise exception 'invalid_product_editorial_payload' using errcode='22023'; end if;
  title_value:=btrim(coalesce(p_payload->>'title',''));
  summary_value:=btrim(coalesce(p_payload->>'summary',''));
  if char_length(title_value) not between 2 and 180 or char_length(summary_value)>1000 then raise exception 'invalid_product_editorial_text' using errcode='22023'; end if;
  info:=coalesce(p_payload->'productInfo','{}'::jsonb); safety:=coalesce(p_payload->'safety','{}'::jsonb); recipe:=coalesce(p_payload->'recipe','{}'::jsonb);
  if jsonb_typeof(info)<>'object' or jsonb_typeof(safety)<>'object' or jsonb_typeof(recipe)<>'object' then raise exception 'invalid_product_editorial_sections' using errcode='22023'; end if;
  ingredients:=private.editorial_text_array_v1(info->'ingredients','ingredients',80,300);
  usage_notes:=private.editorial_text_array_v1(info->'usageNotes','usage_notes',30,500);
  storage_items:=private.editorial_text_array_v1(safety->'storage','storage',20,500);
  prep_items:=private.editorial_text_array_v1(safety->'preparation','preparation',30,500);
  warning_items:=private.editorial_text_array_v1(safety->'warnings','warnings',20,700);
  allergens:=private.editorial_text_array_v1(safety->'allergens','allergens',30,160);
  allergen_note:=btrim(coalesce(safety->>'allergenNote',''));
  if char_length(allergen_note)>1000 then raise exception 'invalid_allergen_note' using errcode='22023'; end if;
  nutrition:=coalesce(info->'nutrition','{}'::jsonb);
  if jsonb_typeof(nutrition)<>'object' or pg_column_size(nutrition)>8192 then raise exception 'invalid_nutrition_payload' using errcode='22023'; end if;
  serving_size:=btrim(coalesce(nutrition->>'servingSize',''));
  if char_length(serving_size)>80 then raise exception 'invalid_serving_size' using errcode='22023'; end if;
  if serving_size<>'' then nutrition_result:=jsonb_set(nutrition_result,'{servingSize}',to_jsonb(serving_size),true); end if;
  foreach key in array allowed_nutrition loop
    if nutrition ? key then
      if jsonb_typeof(nutrition->key)<>'number' then raise exception 'invalid_nutrition_value' using errcode='22023'; end if;
      numeric_value:=(nutrition->>key)::numeric;
      if numeric_value<0 or numeric_value>100000 then raise exception 'nutrition_value_out_of_range' using errcode='22023'; end if;
      nutrition_result:=jsonb_set(nutrition_result,array[key],to_jsonb(numeric_value),true);
    end if;
  end loop;
  if recipe ? 'enabled' then
    if jsonb_typeof(recipe->'enabled')<>'boolean' then raise exception 'invalid_recipe_enabled' using errcode='22023'; end if;
    recipe_enabled:=(recipe->>'enabled')::boolean;
  end if;
  recipe_title:=btrim(coalesce(recipe->>'title',''));
  if char_length(recipe_title)>180 then raise exception 'invalid_recipe_title' using errcode='22023'; end if;
  recipe_ingredients:=private.editorial_text_array_v1(recipe->'ingredients','recipe_ingredients',60,300);
  recipe_steps:=private.editorial_text_array_v1(recipe->'steps','recipe_steps',40,1000);
  if recipe ? 'servings' then servings=(recipe->>'servings')::integer; if servings<1 or servings>100 then raise exception 'invalid_recipe_servings' using errcode='22023'; end if; end if;
  if recipe ? 'prepMinutes' then prep_minutes=(recipe->>'prepMinutes')::integer; if prep_minutes<0 or prep_minutes>1440 then raise exception 'invalid_recipe_prep_minutes' using errcode='22023'; end if; end if;
  if recipe ? 'cookMinutes' then cook_minutes=(recipe->>'cookMinutes')::integer; if cook_minutes<0 or cook_minutes>1440 then raise exception 'invalid_recipe_cook_minutes' using errcode='22023'; end if; end if;
  if recipe_enabled and (char_length(recipe_title)<2 or jsonb_array_length(recipe_ingredients)=0 or jsonb_array_length(recipe_steps)=0) then raise exception 'recipe_content_incomplete' using errcode='22023'; end if;
  return jsonb_build_object(
    'title',title_value,'summary',summary_value,
    'productInfo',jsonb_build_object('ingredients',ingredients,'nutrition',nutrition_result,'usageNotes',usage_notes),
    'safety',jsonb_build_object('storage',storage_items,'preparation',prep_items,'warnings',warning_items,'allergens',allergens,'allergenNote',allergen_note),
    'recipe',jsonb_strip_nulls(jsonb_build_object('enabled',recipe_enabled,'title',nullif(recipe_title,''),'servings',servings,'prepMinutes',prep_minutes,'cookMinutes',cook_minutes,'ingredients',recipe_ingredients,'steps',recipe_steps))
  );
exception when invalid_text_representation then
  raise exception 'invalid_product_editorial_number' using errcode='22023';
end;
$function$;

CREATE OR REPLACE FUNCTION private.normalize_product_option_schema_v1(p_schema jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  result jsonb:='[]'::jsonb;
  item jsonb;
  choice jsonb;
  visible_when jsonb;
  key_value text;
  label_value text;
  help_value text;
  choice_value text;
  choice_label text;
  seen_keys text[]:='{}';
  seen_choices text[];
  group_count integer:=0;
begin
  if p_schema is null then return '[]'::jsonb; end if;
  if jsonb_typeof(p_schema)<>'array' or jsonb_array_length(p_schema)>8 or pg_column_size(p_schema)>24576 then
    raise exception 'invalid_product_option_schema' using errcode='22023';
  end if;
  for item in select value from jsonb_array_elements(p_schema)
  loop
    group_count:=group_count+1;
    if jsonb_typeof(item)<>'object' then raise exception 'invalid_product_option_group' using errcode='22023'; end if;
    if exists(select 1 from jsonb_object_keys(item) k where k<>all(array['key','label','help','required','choices','visibleWhen']::text[])) then
      raise exception 'unsupported_product_option_group_field' using errcode='22023';
    end if;
    key_value:=btrim(coalesce(item->>'key',''));
    label_value:=btrim(coalesce(item->>'label',''));
    help_value:=nullif(btrim(coalesce(item->>'help','')),'');
    if key_value !~ '^[A-Za-z][A-Za-z0-9_]{0,39}$' or char_length(label_value) not between 1 and 100 or char_length(coalesce(help_value,''))>240 then
      raise exception 'invalid_product_option_group_identity' using errcode='22023';
    end if;
    if key_value=any(seen_keys) then raise exception 'duplicate_product_option_group:%',key_value using errcode='22023'; end if;
    seen_keys:=array_append(seen_keys,key_value);
    if item ? 'required' and jsonb_typeof(item->'required')<>'boolean' then raise exception 'invalid_product_option_required' using errcode='22023'; end if;
    if not(item ? 'choices') or jsonb_typeof(item->'choices')<>'array' or jsonb_array_length(item->'choices') not between 1 and 12 then
      raise exception 'invalid_product_option_choices' using errcode='22023';
    end if;
    seen_choices:='{}';
    for choice in select value from jsonb_array_elements(item->'choices')
    loop
      if jsonb_typeof(choice)<>'object' or exists(select 1 from jsonb_object_keys(choice) k where k<>all(array['value','label','description']::text[])) then
        raise exception 'invalid_product_option_choice' using errcode='22023';
      end if;
      choice_value:=btrim(coalesce(choice->>'value',''));
      choice_label:=btrim(coalesce(choice->>'label',''));
      if choice_value !~ '^[A-Za-z0-9][A-Za-z0-9_-]{0,59}$' or char_length(choice_label) not between 1 and 100 or char_length(coalesce(choice->>'description',''))>240 then
        raise exception 'invalid_product_option_choice_identity' using errcode='22023';
      end if;
      if choice_value=any(seen_choices) then raise exception 'duplicate_product_option_choice:%',choice_value using errcode='22023'; end if;
      seen_choices:=array_append(seen_choices,choice_value);
    end loop;
    visible_when:=item->'visibleWhen';
    if visible_when is not null then
      if jsonb_typeof(visible_when)<>'object' or btrim(coalesce(visible_when->>'key',''))='' or btrim(coalesce(visible_when->>'equals',''))='' or exists(select 1 from jsonb_object_keys(visible_when) k where k<>all(array['key','equals']::text[])) then
        raise exception 'invalid_product_option_visibility' using errcode='22023';
      end if;
    end if;
    result:=result||jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'key',key_value,'label',label_value,'help',help_value,'required',coalesce((item->>'required')::boolean,false),
      'choices',item->'choices','visibleWhen',visible_when
    )));
  end loop;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.normalize_tr_phone_v1(p_value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare digits text:=regexp_replace(coalesce(p_value,''),'[^0-9]','','g');
begin
  if digits ~ '^0[0-9]{10}$' then digits:=substr(digits,2); end if;
  if digits ~ '^90[0-9]{10}$' then return '+'||digits; end if;
  if digits ~ '^[0-9]{10}$' then return '+90'||digits; end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION private.order_customization_summary_v1(p_selected_options jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  labels jsonb;
  item record;
  parts text[]:='{}';
begin
  if p_selected_options is null or jsonb_typeof(p_selected_options)<>'object' then return ''; end if;
  labels:=p_selected_options#>'{orderCustomization,labels}';
  if labels is null or jsonb_typeof(labels)<>'object' then return ''; end if;
  for item in select key,value from jsonb_each(labels) order by key
  loop
    if jsonb_typeof(item.value)='object' and nullif(btrim(coalesce(item.value->>'group','')),'') is not null and nullif(btrim(coalesce(item.value->>'choice','')),'') is not null then
      parts:=array_append(parts,(item.value->>'group')||': '||(item.value->>'choice'));
    end if;
  end loop;
  return left(array_to_string(parts,' · '),200);
end;
$function$;

CREATE OR REPLACE FUNCTION private.order_settlement_state_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$declare o public.orders%rowtype; rr private.order_settlement_releases%rowtype; sale_count bigint:=0; pending_sale_count bigint:=0; available_sale_count bigint:=0; pending_minor bigint:=0; available_minor bigint:=0; split_count bigint:=0; pending_split_count bigint:=0; approved_split_count bigint:=0; disapproved_split_count bigint:=0; open_return boolean:=false; refund_block boolean:=false; s text; reason text; eligible boolean:=false; begin select * into o from public.orders where id=p_order_id; if o.id is null then raise exception 'order_not_found' using errcode='P0002'; end if; select * into rr from private.order_settlement_releases where order_id=o.id; select count(*)::bigint,count(*) filter(where availability_status='pending')::bigint,count(*) filter(where availability_status='available')::bigint,coalesce(sum(producer_net_minor) filter(where availability_status='pending'),0)::bigint,coalesce(sum(producer_net_minor) filter(where availability_status='available'),0)::bigint into sale_count,pending_sale_count,available_sale_count,pending_minor,available_minor from private.producer_ledger_entries where order_id=o.id and entry_type='sale'; select count(*)::bigint,count(*) filter(where approval_status='pending')::bigint,count(*) filter(where approval_status='approved')::bigint,count(*) filter(where approval_status='disapproved')::bigint into split_count,pending_split_count,approved_split_count,disapproved_split_count from private.payment_item_splits where order_id=o.id and order_item_id is not null; select exists(select 1 from public.return_requests r where r.order_id=o.id and r.status in('requested','under_review','approved','in_transit','received')) into open_return; select exists(select 1 from public.refunds rf where rf.order_id=o.id and rf.status not in('failed','cancelled')) into refund_block; if sale_count=0 and split_count=0 then s:='not_required';reason:='no_seller_settlement'; elsif rr.status='released' or (sale_count>0 and pending_sale_count=0 and split_count>0 and pending_split_count=0 and disapproved_split_count=0 and approved_split_count=split_count) then s:='released';reason:='released'; elsif o.status<>'completed' then s:='awaiting_completion';reason:='order_not_completed'; elsif o.payment_status<>'paid' then s:='blocked';reason:='payment_not_fully_paid'; elsif open_return then s:='blocked';reason:='open_return'; elsif refund_block then s:='blocked';reason:='refund_or_refund_review'; elsif sale_count=0 then s:='blocked';reason:='seller_ledger_missing'; elsif split_count=0 then s:='blocked';reason:='payment_split_missing'; elsif exists(select 1 from private.producer_ledger_entries le where le.order_id=o.id and le.entry_type='sale' and not exists(select 1 from private.payment_item_splits ps where ps.order_id=o.id and ps.order_item_id=le.order_item_id)) then s:='blocked';reason:='ledger_split_mismatch'; elsif disapproved_split_count>0 then s:='blocked';reason:='provider_split_disapproved'; elsif rr.status='processing' then s:='processing';reason:='provider_approval_processing'; elsif rr.status='failed' then s:='failed';reason:='provider_approval_failed';eligible:=true; else s:='pending_approval';reason:='super_admin_approval_required';eligible:=true; end if; return jsonb_build_object('status',s,'reason',reason,'eligible',eligible,'currency',o.currency,'pendingSellerMinor',pending_minor,'availableSellerMinor',available_minor,'saleCount',sale_count,'pendingSaleCount',pending_sale_count,'availableSaleCount',available_sale_count,'splitCount',split_count,'pendingSplitCount',pending_split_count,'approvedSplitCount',approved_split_count,'hasOpenReturn',open_return,'hasRefundBlock',refund_block,'requestedAt',rr.requested_at,'releasedAt',rr.released_at,'lastError',rr.last_error); end;$function$;

CREATE OR REPLACE FUNCTION private.persist_payment_item_splits_for_service_v1(p_payment_id uuid, p_provider_payload jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  payment public.payment_records%rowtype;
  item jsonb;
  order_item public.order_items%rowtype;
  inserted_count integer:=0;
  tx_id text;
  provider_item_id uuid;
  provider_price_minor bigint;
  provider_paid_minor bigint;
  provider_submerchant_minor bigint;
  expected_submerchant_minor bigint;
begin
  if p_payment_id is null or p_provider_payload is null or jsonb_typeof(p_provider_payload)<>'object' then return 0; end if;
  select * into payment from public.payment_records where id=p_payment_id;
  if payment.id is null then raise exception 'payment_not_found' using errcode='P0002'; end if;
  if jsonb_typeof(p_provider_payload->'itemTransactions')<>'array' then return 0; end if;
  for item in select value from jsonb_array_elements(p_provider_payload->'itemTransactions')
  loop
    if jsonb_typeof(item)<>'object' then continue; end if;
    begin provider_item_id:=(item->>'itemId')::uuid; exception when others then continue; end;
    tx_id:=nullif(btrim(coalesce(item->>'paymentTransactionId','')),'');
    if tx_id is null then continue; end if;
    select * into order_item from public.order_items where id=provider_item_id and order_id=payment.order_id;
    if order_item.id is null or order_item.producer_id is null then continue; end if;
    expected_submerchant_minor:=greatest(0,order_item.line_total_minor-round((((order_item.unit_price_minor*order_item.quantity)-order_item.discount_minor)::numeric*order_item.commission_basis_points_snapshot::numeric)/10000)::bigint);
    provider_price_minor:=case when coalesce(item->>'price','') ~ '^[0-9]+([.][0-9]+)?$' then round((item->>'price')::numeric*100)::bigint else order_item.line_total_minor end;
    provider_paid_minor:=case when coalesce(item->>'paidPrice','') ~ '^[0-9]+([.][0-9]+)?$' then round((item->>'paidPrice')::numeric*100)::bigint else null end;
    provider_submerchant_minor:=case when coalesce(item->>'subMerchantPrice','') ~ '^[0-9]+([.][0-9]+)?$' then round((item->>'subMerchantPrice')::numeric*100)::bigint else expected_submerchant_minor end;
    if provider_submerchant_minor<>expected_submerchant_minor then raise exception 'provider_submerchant_split_mismatch:%',order_item.id using errcode='55000'; end if;
    insert into private.payment_item_splits(payment_id,order_id,order_item_id,producer_id,provider_payment_transaction_id,item_price_minor,provider_paid_price_minor,submerchant_price_minor,transaction_status,provider_snapshot)
    values(payment.id,payment.order_id,order_item.id,order_item.producer_id,tx_id,provider_price_minor,provider_paid_minor,provider_submerchant_minor,
      case when coalesce(item->>'transactionStatus','') ~ '^-?[0-9]+$' then (item->>'transactionStatus')::integer else null end,item)
    on conflict(payment_id,order_item_id) do update set
      provider_payment_transaction_id=excluded.provider_payment_transaction_id,
      provider_paid_price_minor=excluded.provider_paid_price_minor,
      transaction_status=excluded.transaction_status,
      provider_snapshot=excluded.provider_snapshot,
      updated_at=timezone('utc',now());
    inserted_count:=inserted_count+1;
  end loop;
  return inserted_count;
end;
$function$;

CREATE OR REPLACE FUNCTION private.platform_access_block_v1(p_user_id uuid DEFAULT auth.uid())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ip inet:=private.current_request_ip_v1(); device uuid:=private.current_request_device_id_v1(); profile_status text; rule private.security_block_rules%rowtype;
begin
  if p_user_id is null then return jsonb_build_object('blocked',false); end if;
  select status into profile_status from public.profiles where id=p_user_id and deleted_at is null;
  if profile_status is null then return jsonb_build_object('blocked',true,'code','account_closed','reason','Hesap kapalı.'); end if;
  if profile_status<>'active' then return jsonb_build_object('blocked',true,'code','profile_'||profile_status,'reason','Hesap erişimi kısıtlı.'); end if;
  select * into rule from private.security_block_rules r where r.active=true and (r.expires_at is null or r.expires_at>timezone('utc',now())) and (
    (r.subject_type='user' and r.user_id=p_user_id)
    or (r.subject_type='ip' and ip is not null and ip <<= r.ip_network)
    or (r.subject_type='device' and device is not null and r.device_id=device)
  ) order by case r.subject_type when 'user' then 1 when 'device' then 2 else 3 end,r.created_at desc limit 1;
  if rule.id is not null then return jsonb_build_object('blocked',true,'code','security_'||rule.subject_type||'_blocked','reason',rule.reason,'fraudFlag',rule.fraud_flag,'ruleId',rule.id); end if;
  return jsonb_build_object('blocked',false);
end;
$function$;

CREATE OR REPLACE FUNCTION private.prepare_event_reservation_hosted_payment_for_service_v1(p_user_id uuid, p_reservation_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 r public.event_reservations%rowtype; f private.event_reservation_finance%rowtype; e public.events%rowtype; pa private.producer_payment_accounts%rowtype; a public.addresses%rowtype; p public.profiles%rowtype; u auth.users%rowtype; cfg jsonb; intent private.payment_intents%rowtype; intent_id uuid; action_value text; sub_key text:=null;
begin
 if auth.role()<>'service_role' then raise exception 'service_role_required' using errcode='42501'; end if;
 if p_user_id is null or p_reservation_id is null then raise exception 'payment_context_required' using errcode='22023'; end if;
 if p_idempotency_key is null or char_length(p_idempotency_key) not between 16 and 120 or p_idempotency_key !~ '^[A-Za-z0-9_-]+$' then raise exception 'invalid_payment_idempotency_key' using errcode='22023'; end if;
 select private.default_payment_control_v1()||coalesce(bs.public_config->'payments','{}'::jsonb) into cfg from public.brand_settings bs where bs.slug='golden-oremar' limit 1;
 if cfg is null or cfg->>'provider'<>'iyzico' or not coalesce((cfg->>'checkout_form_enabled')::boolean,false) then raise exception 'hosted_checkout_not_configured' using errcode='55000'; end if;
 select * into r from public.event_reservations where id=p_reservation_id and user_id=p_user_id for update;
 if r.id is null then raise exception 'event_reservation_not_found' using errcode='P0002'; end if;
 select * into f from private.event_reservation_finance where reservation_id=r.id for update;
 if f.reservation_id is null or f.user_id<>p_user_id or f.total_minor<=0 then raise exception 'event_reservation_payment_not_required' using errcode='55000'; end if;
 if f.payment_status='paid' then return jsonb_build_object('action','terminal','status','captured','intentId',(select i.id from private.payment_intents i where i.subject_type='event_reservation' and i.subject_id=r.id and i.status='captured' order by i.created_at desc limit 1),'reservationId',r.id,'reservationCode',r.reservation_code,'paymentStatus','paid'); end if;
 if r.status<>'pending_payment' or f.payment_status not in ('pending','authorized') then raise exception 'event_reservation_not_payable' using errcode='55000'; end if;
 if f.payment_status='pending' and (f.payment_expires_at is null or f.payment_expires_at<=timezone('utc',now())) then raise exception 'payment_reservation_expired' using errcode='55000'; end if;
 select * into e from public.events where id=r.event_id for update;
 if e.id is null or e.status not in ('published','sold_out') or e.starts_at<=timezone('utc',now()) then raise exception 'event_not_available' using errcode='55000'; end if;
 if f.producer_id is not null then select * into pa from private.producer_payment_accounts where producer_id=f.producer_id and provider='iyzico' and status='ready' and submerchant_key is not null; if pa.producer_id is null then raise exception 'producer_payment_account_not_ready' using errcode='55000'; end if; sub_key:=pa.submerchant_key; end if;
 select * into a from public.addresses where user_id=p_user_id and deleted_at is null order by is_default desc,updated_at desc limit 1;
 if a.id is null then raise exception 'payment_billing_address_required' using errcode='55000'; end if;
 if nullif(btrim(coalesce(a.postal_code,'')),'') is null then raise exception 'payment_postal_code_required' using errcode='55000'; end if;
 select * into p from public.profiles where id=p_user_id; select * into u from auth.users where id=p_user_id;
 if p.id is null or u.id is null or u.email is null then raise exception 'payment_buyer_profile_incomplete' using errcode='55000'; end if;
 select * into intent from private.payment_intents where user_id=p_user_id and idempotency_key=p_idempotency_key for update;
 if intent.id is not null then
   if intent.subject_type<>'event_reservation' or intent.subject_id<>r.id or intent.order_id is not null or intent.payment_method_id is not null or intent.payment_flow<>'checkout_form' or intent.amount_minor<>f.total_minor or intent.currency<>f.currency or intent.provider<>'iyzico' then raise exception 'payment_idempotency_key_reused' using errcode='23505'; end if;
   intent_id:=intent.id;
   if intent.status='created' then update private.payment_intents set status='processing',attempt_count=attempt_count+1,updated_at=timezone('utc',now()) where id=intent.id; action_value:='initialize';
   elsif intent.status in ('processing','authorized') then action_value:='reconcile'; else action_value:='terminal'; end if;
 else
   insert into private.payment_intents(user_id,subject_type,subject_id,order_id,payment_method_id,payment_flow,provider,idempotency_key,amount_minor,currency,status,attempt_count)
   values(p_user_id,'event_reservation',r.id,null,null,'checkout_form','iyzico',p_idempotency_key,f.total_minor,f.currency,'processing',1) returning id into intent_id;
   action_value:='initialize';
 end if;
 return jsonb_build_object('action',action_value,'intentId',intent_id,'intentStatus',coalesce(intent.status,'processing'),'subjectType','event_reservation','subjectId',r.id,'reservationId',r.id,'reservationCode',r.reservation_code,'eventId',e.id,'eventTitle',e.title,'amountMinor',f.total_minor,'priceMinor',f.total_minor,'currency',f.currency,'paymentExpiresAt',f.payment_expires_at,'buyer',jsonb_build_object('id',p_user_id,'displayName',coalesce(nullif(btrim(r.guest_name),''),p.display_name),'phone',r.guest_phone,'email',u.email,'createdAt',u.created_at),'billingAddress',jsonb_build_object('recipient_name',a.recipient_name,'phone',a.phone,'country_code',a.country_code,'province',a.province,'district',a.district,'neighborhood',a.neighborhood,'address_line',a.address_line,'postal_code',a.postal_code),'items',jsonb_build_array(jsonb_build_object('id',r.id,'name',e.title,'quantity',r.guest_count,'lineTotalMinor',f.total_minor,'producerId',f.producer_id,'subMerchantKey',sub_key,'subMerchantPriceMinor',f.producer_net_minor)),'splitTotalMinor',f.producer_net_minor,'providerReference',intent.provider_reference);
end;$function$;

CREATE OR REPLACE FUNCTION private.prepare_order_hosted_payment_for_service_v1(p_user_id uuid, p_order_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_order public.orders%rowtype;
  profile_row public.profiles%rowtype;
  auth_row auth.users%rowtype;
  payment_config jsonb;
  configured_provider text;
  existing_intent private.payment_intents%rowtype;
  intent_id uuid;
  action_value text;
  items_payload jsonb;
  basket_price_minor bigint;
  shipping_discount_minor bigint:=0;
  split_total_minor bigint:=0;
begin
  if p_user_id is null or p_order_id is null then raise exception 'payment_context_required' using errcode='22023'; end if;
  if p_idempotency_key is null or char_length(p_idempotency_key) not between 16 and 120 or p_idempotency_key !~ '^[A-Za-z0-9_-]+$' then raise exception 'invalid_payment_idempotency_key' using errcode='22023'; end if;

  select private.default_payment_control_v1() || coalesce(bs.public_config->'payments','{}'::jsonb) into payment_config from public.brand_settings bs where bs.slug='golden-oremar' limit 1;
  configured_provider:=nullif(lower(btrim(coalesce(payment_config->>'provider',''))),'');
  if configured_provider<>'iyzico' or not coalesce((payment_config->>'checkout_form_enabled')::boolean,false) then raise exception 'hosted_checkout_not_configured' using errcode='55000'; end if;

  select * into target_order from public.orders where id=p_order_id for update;
  if target_order.id is null or target_order.user_id<>p_user_id then raise exception 'order_not_found' using errcode='P0002'; end if;
  if target_order.payment_status='paid' then return jsonb_build_object('action','terminal','status','captured','orderId',target_order.id,'orderNumber',target_order.order_number,'paymentStatus','paid','orderStatus',target_order.status); end if;
  if target_order.status<>'pending_payment' or target_order.payment_status not in ('unpaid','failed') then raise exception 'order_not_payable' using errcode='55000'; end if;
  if target_order.reservation_expires_at is not null and target_order.reservation_expires_at<=timezone('utc',now()) then raise exception 'payment_reservation_expired' using errcode='55000'; end if;
  if exists(select 1 from private.payment_intents i where i.order_id=target_order.id and i.status in ('processing','authorized') and i.idempotency_key<>p_idempotency_key) then raise exception 'payment_reconciliation_required' using errcode='55000'; end if;

  if exists(
    select 1 from public.order_items oi
    left join private.producer_payment_accounts pa on pa.producer_id=oi.producer_id and pa.provider=configured_provider and pa.status='ready' and pa.submerchant_key is not null
    where oi.order_id=target_order.id and (oi.producer_id is null or pa.producer_id is null)
  ) then raise exception 'producer_payment_account_not_ready' using errcode='55000'; end if;

  select coalesce(sum(oi.line_total_minor),0)::bigint into basket_price_minor from public.order_items oi where oi.order_id=target_order.id;
  select coalesce(op.shipping_discount_minor,0)::bigint into shipping_discount_minor from public.order_promotions op where op.order_id=target_order.id;
  if basket_price_minor<=0 or target_order.total_minor<>basket_price_minor+target_order.shipping_minor-shipping_discount_minor then raise exception 'marketplace_payment_total_mismatch' using errcode='55000'; end if;

  select coalesce(sum(greatest(0,oi.line_total_minor-round((((oi.unit_price_minor*oi.quantity)-oi.discount_minor)::numeric*oi.commission_basis_points_snapshot::numeric)/10000)::bigint)),0)::bigint into split_total_minor
  from public.order_items oi where oi.order_id=target_order.id;
  if split_total_minor<=0 or split_total_minor>target_order.total_minor then raise exception 'submerchant_payout_exceeds_charge' using errcode='55000'; end if;

  select * into existing_intent from private.payment_intents i where i.user_id=p_user_id and i.idempotency_key=p_idempotency_key for update;
  if existing_intent.id is not null then
    if existing_intent.subject_type<>'order' or existing_intent.subject_id<>target_order.id or existing_intent.order_id<>target_order.id or existing_intent.payment_flow<>'checkout_form' or existing_intent.amount_minor<>target_order.total_minor or existing_intent.currency<>target_order.currency or existing_intent.provider<>configured_provider then raise exception 'payment_idempotency_key_reused' using errcode='23505'; end if;
    intent_id:=existing_intent.id;
    if existing_intent.status='created' then
      update private.payment_intents set status='processing',attempt_count=attempt_count+1,updated_at=timezone('utc',now()) where id=intent_id;
      action_value:='initialize';
    elsif existing_intent.status='processing' and existing_intent.provider_session_token is null then action_value:='initialize';
    elsif existing_intent.status in ('processing','authorized') then action_value:='reconcile';
    else action_value:='terminal';
    end if;
  else
    insert into private.payment_intents(user_id,subject_type,subject_id,order_id,payment_method_id,payment_flow,provider,idempotency_key,amount_minor,currency,status,attempt_count)
    values(p_user_id,'order',target_order.id,target_order.id,null,'checkout_form',configured_provider,p_idempotency_key,target_order.total_minor,target_order.currency,'processing',1)
    returning id into intent_id;
    action_value:='initialize';
  end if;

  select * into profile_row from public.profiles where id=p_user_id;
  select * into auth_row from auth.users where id=p_user_id;
  if profile_row.id is null or auth_row.id is null or auth_row.email is null then raise exception 'payment_buyer_profile_incomplete' using errcode='55000'; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
      'id',oi.id,'name',oi.product_name,'quantity',oi.quantity,'lineTotalMinor',oi.line_total_minor,'producerId',oi.producer_id,
      'subMerchantKey',pa.submerchant_key,
      'subMerchantPriceMinor',greatest(0,oi.line_total_minor-round((((oi.unit_price_minor*oi.quantity)-oi.discount_minor)::numeric*oi.commission_basis_points_snapshot::numeric)/10000)::bigint)
    ) order by oi.id),'[]'::jsonb) into items_payload
  from public.order_items oi join private.producer_payment_accounts pa on pa.producer_id=oi.producer_id and pa.provider=configured_provider and pa.status='ready'
  where oi.order_id=target_order.id;

  return jsonb_build_object(
    'action',action_value,'intentId',intent_id,'intentStatus',coalesce(existing_intent.status,'processing'),'providerSessionToken',existing_intent.provider_session_token,
    'orderId',target_order.id,'orderNumber',target_order.order_number,'amountMinor',target_order.total_minor,'priceMinor',basket_price_minor,
    'shippingMinor',target_order.shipping_minor,'shippingDiscountMinor',shipping_discount_minor,'discountMinor',target_order.discount_minor,'currency',target_order.currency,
    'shippingAddress',target_order.shipping_address,'items',items_payload,'provider',configured_provider,
    'buyer',jsonb_build_object('id',p_user_id,'displayName',profile_row.display_name,'phone',coalesce(profile_row.phone,target_order.shipping_address->>'phone'),'email',auth_row.email,'createdAt',auth_row.created_at),
    'splitTotalMinor',split_total_minor
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.prepare_order_payment_for_service_v1(p_user_id uuid, p_order_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_order public.orders%rowtype;
  pref private.order_payment_preferences%rowtype;
  method private.customer_payment_methods%rowtype;
  provider_customer private.payment_provider_customers%rowtype;
  profile_row public.profiles%rowtype;
  auth_row auth.users%rowtype;
  payment_config jsonb;
  configured_provider text;
  existing_intent private.payment_intents%rowtype;
  intent_id uuid;
  action_value text;
  items_payload jsonb;
  basket_price_minor bigint;
  shipping_charge_minor bigint;
begin
  if p_user_id is null or p_order_id is null then raise exception 'payment_context_required' using errcode='22023'; end if;
  if p_idempotency_key is null or char_length(p_idempotency_key) not between 16 and 120 or p_idempotency_key !~ '^[A-Za-z0-9_-]+$' then raise exception 'invalid_payment_idempotency_key' using errcode='22023'; end if;

  select coalesce(bs.public_config->'payments','{}'::jsonb) into payment_config from public.brand_settings bs where bs.slug='golden-oremar' limit 1;
  configured_provider:=nullif(lower(btrim(coalesce(payment_config->>'provider',''))),'');
  if configured_provider is null or not coalesce((payment_config->>'live_card_payments_enabled')::boolean,false) then raise exception 'payment_provider_not_configured' using errcode='55000'; end if;

  select o.* into target_order from public.orders o where o.id=p_order_id for update;
  if target_order.id is null or target_order.user_id<>p_user_id then raise exception 'order_not_found' using errcode='P0002'; end if;
  if target_order.status<>'pending_payment' then
    if target_order.payment_status='paid' then return jsonb_build_object('action','terminal','status','captured','orderId',target_order.id,'orderNumber',target_order.order_number,'paymentStatus','paid','orderStatus',target_order.status); end if;
    raise exception 'order_not_payable' using errcode='55000';
  end if;
  if target_order.payment_status='authorized' then raise exception 'payment_review_pending' using errcode='55000'; end if;
  if target_order.payment_status not in ('unpaid','failed') then raise exception 'order_not_payable' using errcode='55000'; end if;
  if target_order.reservation_expires_at is not null and target_order.reservation_expires_at<=timezone('utc',now()) then raise exception 'payment_reservation_expired' using errcode='55000'; end if;

  select p.* into pref from private.order_payment_preferences p where p.order_id=target_order.id and p.user_id=p_user_id;
  if pref.order_id is null then raise exception 'payment_method_required' using errcode='22023'; end if;
  select m.* into method from private.customer_payment_methods m where m.id=pref.payment_method_id and m.user_id=p_user_id and m.status='active';
  if method.id is null then raise exception 'payment_method_not_found' using errcode='P0002'; end if;
  if method.provider<>configured_provider or pref.provider<>configured_provider then raise exception 'payment_method_provider_mismatch' using errcode='22023'; end if;
  if method.exp_year is not null and method.exp_month is not null and make_date(method.exp_year,method.exp_month,1)<date_trunc('month',timezone('utc',now()))::date then raise exception 'payment_method_expired' using errcode='22023'; end if;
  select c.* into provider_customer from private.payment_provider_customers c where c.user_id=p_user_id and c.provider=configured_provider;
  if provider_customer.user_id is null then raise exception 'provider_customer_missing' using errcode='P0002'; end if;

  if exists(
    select 1 from public.order_items oi
    left join private.producer_payment_accounts pa on pa.producer_id=oi.producer_id and pa.provider=configured_provider and pa.status='ready' and pa.submerchant_key is not null
    where oi.order_id=target_order.id and (oi.producer_id is null or pa.producer_id is null)
  ) then raise exception 'producer_payment_account_not_ready' using errcode='55000'; end if;

  select coalesce(sum(oi.line_total_minor),0)::bigint into basket_price_minor from public.order_items oi where oi.order_id=target_order.id;
  shipping_charge_minor:=target_order.total_minor-basket_price_minor;
  if basket_price_minor<=0 or shipping_charge_minor<0 then raise exception 'invalid_marketplace_payment_totals' using errcode='55000'; end if;

  select * into existing_intent from private.payment_intents i where i.user_id=p_user_id and i.idempotency_key=p_idempotency_key for update;
  if existing_intent.id is not null then
    if existing_intent.order_id<>target_order.id or existing_intent.payment_method_id<>method.id or existing_intent.amount_minor<>target_order.total_minor or existing_intent.currency<>target_order.currency or existing_intent.provider<>configured_provider then raise exception 'payment_idempotency_key_reused' using errcode='23505'; end if;
    intent_id:=existing_intent.id;
    if existing_intent.status='created' then
      update private.payment_intents set status='processing',attempt_count=attempt_count+1,updated_at=timezone('utc',now()) where id=intent_id;
      action_value:='charge';
    elsif existing_intent.status='processing' then action_value:='reconcile';
    else action_value:='terminal';
    end if;
  else
    insert into private.payment_intents(user_id,order_id,payment_method_id,provider,idempotency_key,amount_minor,currency,status,attempt_count)
    values(p_user_id,target_order.id,method.id,configured_provider,p_idempotency_key,target_order.total_minor,target_order.currency,'processing',1)
    returning id into intent_id;
    action_value:='charge';
  end if;

  select p.* into profile_row from public.profiles p where p.id=p_user_id;
  select u.* into auth_row from auth.users u where u.id=p_user_id;
  select coalesce(jsonb_agg(jsonb_build_object(
      'id',oi.id,
      'name',oi.product_name,
      'quantity',oi.quantity,
      'lineTotalMinor',oi.line_total_minor,
      'producerId',oi.producer_id,
      'subMerchantKey',pa.submerchant_key,
      'subMerchantPriceMinor',greatest(0,oi.line_total_minor-round((((oi.unit_price_minor*oi.quantity)-oi.discount_minor)::numeric*oi.commission_basis_points_snapshot::numeric)/10000)::bigint)
    ) order by oi.id),'[]'::jsonb)
  into items_payload
  from public.order_items oi
  join private.producer_payment_accounts pa on pa.producer_id=oi.producer_id and pa.provider=configured_provider
  where oi.order_id=target_order.id;

  return jsonb_build_object(
    'action',action_value,
    'intentId',intent_id,
    'intentStatus',coalesce(existing_intent.status,'processing'),
    'orderId',target_order.id,
    'orderNumber',target_order.order_number,
    'amountMinor',target_order.total_minor,
    'priceMinor',basket_price_minor,
    'shippingChargeMinor',shipping_charge_minor,
    'subtotalMinor',target_order.subtotal_minor,
    'discountMinor',target_order.discount_minor,
    'shippingMinor',target_order.shipping_minor,
    'currency',target_order.currency,
    'shippingAddress',target_order.shipping_address,
    'items',items_payload,
    'provider',configured_provider,
    'providerCustomerRef',case when action_value='charge' then provider_customer.provider_customer_ref else null end,
    'providerPaymentMethodRef',case when action_value='charge' then method.provider_payment_method_ref else null end,
    'paymentMethod',jsonb_build_object('id',method.id,'brand',method.brand,'last4',method.last4),
    'buyer',jsonb_build_object('id',p_user_id,'displayName',profile_row.display_name,'phone',coalesce(profile_row.phone,target_order.shipping_address->>'phone'),'email',auth_row.email,'createdAt',auth_row.created_at),
    'providerReference',existing_intent.provider_reference
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.prepare_order_payment_for_service_v2(p_user_id uuid, p_order_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_order public.orders%rowtype;
  pref private.order_payment_preferences%rowtype;
  method private.customer_payment_methods%rowtype;
  provider_customer private.payment_provider_customers%rowtype;
  profile_row public.profiles%rowtype;
  auth_row auth.users%rowtype;
  payment_config jsonb;
  configured_provider text;
  existing_intent private.payment_intents%rowtype;
  intent_id uuid;
  action_value text;
  items_payload jsonb;
  basket_price_minor bigint;
  shipping_discount_minor bigint:=0;
  split_total_minor bigint:=0;
begin
  if p_user_id is null or p_order_id is null then raise exception 'payment_context_required' using errcode='22023'; end if;
  if p_idempotency_key is null or char_length(p_idempotency_key) not between 16 and 120 or p_idempotency_key !~ '^[A-Za-z0-9_-]+$' then raise exception 'invalid_payment_idempotency_key' using errcode='22023'; end if;

  select coalesce(bs.public_config->'payments','{}'::jsonb) into payment_config from public.brand_settings bs where bs.slug='golden-oremar' limit 1;
  configured_provider:=nullif(lower(btrim(coalesce(payment_config->>'provider',''))),'');
  if configured_provider is null or not coalesce((payment_config->>'live_card_payments_enabled')::boolean,false) then raise exception 'payment_provider_not_configured' using errcode='55000'; end if;

  select o.* into target_order from public.orders o where o.id=p_order_id for update;
  if target_order.id is null or target_order.user_id<>p_user_id then raise exception 'order_not_found' using errcode='P0002'; end if;
  if target_order.payment_status='paid' then
    return jsonb_build_object('action','terminal','status','captured','orderId',target_order.id,'orderNumber',target_order.order_number,'paymentStatus','paid','orderStatus',target_order.status);
  end if;
  if target_order.status<>'pending_payment' or target_order.payment_status not in ('unpaid','failed','authorized') then raise exception 'order_not_payable' using errcode='55000'; end if;
  if target_order.reservation_expires_at is not null and target_order.reservation_expires_at<=timezone('utc',now()) then raise exception 'payment_reservation_expired' using errcode='55000'; end if;

  select p.* into pref from private.order_payment_preferences p where p.order_id=target_order.id and p.user_id=p_user_id;
  if pref.order_id is null then raise exception 'payment_method_required' using errcode='22023'; end if;
  select m.* into method from private.customer_payment_methods m where m.id=pref.payment_method_id and m.user_id=p_user_id and m.status='active';
  if method.id is null then raise exception 'payment_method_not_found' using errcode='P0002'; end if;
  if method.provider<>configured_provider or pref.provider<>configured_provider then raise exception 'payment_method_provider_mismatch' using errcode='22023'; end if;
  if method.exp_year is not null and method.exp_month is not null and make_date(method.exp_year,method.exp_month,1)<date_trunc('month',timezone('utc',now()))::date then raise exception 'payment_method_expired' using errcode='22023'; end if;
  select c.* into provider_customer from private.payment_provider_customers c where c.user_id=p_user_id and c.provider=configured_provider;
  if provider_customer.user_id is null then raise exception 'provider_customer_missing' using errcode='P0002'; end if;

  if exists(
    select 1
    from public.order_items oi
    left join private.producer_payment_accounts pa on pa.producer_id=oi.producer_id and pa.provider=configured_provider and pa.status='ready' and pa.submerchant_key is not null
    where oi.order_id=target_order.id and (oi.producer_id is null or pa.producer_id is null)
  ) then raise exception 'producer_payment_account_not_ready' using errcode='55000'; end if;

  select coalesce(sum(oi.line_total_minor),0)::bigint into basket_price_minor from public.order_items oi where oi.order_id=target_order.id;
  select coalesce(op.shipping_discount_minor,0)::bigint into shipping_discount_minor from public.order_promotions op where op.order_id=target_order.id;
  if basket_price_minor<=0 then raise exception 'invalid_marketplace_basket_total' using errcode='55000'; end if;
  if target_order.total_minor<>basket_price_minor+target_order.shipping_minor-shipping_discount_minor then raise exception 'marketplace_payment_total_mismatch' using errcode='55000'; end if;

  if exists(
    select 1 from public.order_items oi
    where oi.order_id=target_order.id and greatest(0,oi.line_total_minor-round((((oi.unit_price_minor*oi.quantity)-oi.discount_minor)::numeric*oi.commission_basis_points_snapshot::numeric)/10000)::bigint)<=0
  ) then raise exception 'invalid_submerchant_payout_amount' using errcode='55000'; end if;

  select coalesce(sum(greatest(0,oi.line_total_minor-round((((oi.unit_price_minor*oi.quantity)-oi.discount_minor)::numeric*oi.commission_basis_points_snapshot::numeric)/10000)::bigint)),0)::bigint
  into split_total_minor
  from public.order_items oi where oi.order_id=target_order.id;
  if split_total_minor<=0 or split_total_minor>target_order.total_minor then raise exception 'submerchant_payout_exceeds_charge' using errcode='55000'; end if;

  select * into existing_intent from private.payment_intents i where i.user_id=p_user_id and i.idempotency_key=p_idempotency_key for update;
  if existing_intent.id is not null then
    if existing_intent.subject_type<>'order' or existing_intent.subject_id<>target_order.id or existing_intent.order_id<>target_order.id or existing_intent.payment_method_id<>method.id or existing_intent.amount_minor<>target_order.total_minor or existing_intent.currency<>target_order.currency or existing_intent.provider<>configured_provider then raise exception 'payment_idempotency_key_reused' using errcode='23505'; end if;
    intent_id:=existing_intent.id;
    if existing_intent.status='created' then
      update private.payment_intents set status='processing',attempt_count=attempt_count+1,updated_at=timezone('utc',now()) where id=intent_id;
      action_value:='charge';
    elsif existing_intent.status in ('processing','authorized') then action_value:='reconcile';
    else action_value:='terminal';
    end if;
  else
    insert into private.payment_intents(user_id,subject_type,subject_id,order_id,payment_method_id,provider,idempotency_key,amount_minor,currency,status,attempt_count)
    values(p_user_id,'order',target_order.id,target_order.id,method.id,configured_provider,p_idempotency_key,target_order.total_minor,target_order.currency,'processing',1)
    returning id into intent_id;
    action_value:='charge';
  end if;

  select p.* into profile_row from public.profiles p where p.id=p_user_id;
  select u.* into auth_row from auth.users u where u.id=p_user_id;
  if profile_row.id is null or auth_row.id is null or auth_row.email is null then raise exception 'payment_buyer_profile_incomplete' using errcode='55000'; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
      'id',oi.id,
      'name',oi.product_name,
      'quantity',oi.quantity,
      'lineTotalMinor',oi.line_total_minor,
      'producerId',oi.producer_id,
      'subMerchantKey',pa.submerchant_key,
      'subMerchantPriceMinor',greatest(0,oi.line_total_minor-round((((oi.unit_price_minor*oi.quantity)-oi.discount_minor)::numeric*oi.commission_basis_points_snapshot::numeric)/10000)::bigint)
    ) order by oi.id),'[]'::jsonb)
  into items_payload
  from public.order_items oi
  join private.producer_payment_accounts pa on pa.producer_id=oi.producer_id and pa.provider=configured_provider and pa.status='ready'
  where oi.order_id=target_order.id;

  return jsonb_build_object(
    'action',action_value,
    'intentId',intent_id,
    'intentStatus',coalesce(existing_intent.status,'processing'),
    'orderId',target_order.id,
    'orderNumber',target_order.order_number,
    'amountMinor',target_order.total_minor,
    'priceMinor',basket_price_minor,
    'shippingMinor',target_order.shipping_minor,
    'shippingDiscountMinor',shipping_discount_minor,
    'discountMinor',target_order.discount_minor,
    'currency',target_order.currency,
    'shippingAddress',target_order.shipping_address,
    'items',items_payload,
    'provider',configured_provider,
    'providerCustomerRef',case when action_value='charge' then provider_customer.provider_customer_ref else null end,
    'providerPaymentMethodRef',case when action_value='charge' then method.provider_payment_method_ref else null end,
    'paymentMethod',jsonb_build_object('id',method.id,'brand',method.brand,'last4',method.last4),
    'buyer',jsonb_build_object('id',p_user_id,'displayName',profile_row.display_name,'phone',coalesce(profile_row.phone,target_order.shipping_address->>'phone'),'email',auth_row.email,'createdAt',auth_row.created_at),
    'providerReference',existing_intent.provider_reference,
    'splitTotalMinor',split_total_minor
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.prepare_order_settlement_for_service_v1(p_actor_user_id uuid, p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare o public.orders%rowtype; state jsonb; items jsonb; pending_count bigint:=0; provider_count bigint:=0; begin if p_actor_user_id is null or p_order_id is null then raise exception 'settlement_context_required' using errcode='22023'; end if; if not private.user_has_permission_v1(p_actor_user_id,'payout.release') then raise exception 'permission_required:payout.release' using errcode='42501'; end if; select * into o from public.orders where id=p_order_id for update; if o.id is null then raise exception 'order_not_found' using errcode='P0002'; end if; state:=private.order_settlement_state_v1(o.id); if state->>'status'='released' then return jsonb_build_object('action','terminal','released',true,'orderId',o.id,'orderNumber',o.order_number,'state',state); end if; if state->>'status' not in('pending_approval','failed','processing') then raise exception 'settlement_not_releasable:%',coalesce(state->>'reason','unknown') using errcode='55000'; end if; select count(distinct pr.provider)::bigint,count(*) filter(where ps.approval_status='pending')::bigint,coalesce(jsonb_agg(jsonb_build_object('paymentTransactionId',ps.provider_payment_transaction_id,'orderItemId',ps.order_item_id,'producerId',ps.producer_id,'provider',pr.provider) order by ps.id) filter(where ps.approval_status='pending'),'[]'::jsonb) into provider_count,pending_count,items from private.payment_item_splits ps join public.payment_records pr on pr.id=ps.payment_id where ps.order_id=o.id and ps.order_item_id is not null; if provider_count<>1 or exists(select 1 from private.payment_item_splits ps join public.payment_records pr on pr.id=ps.payment_id where ps.order_id=o.id and ps.order_item_id is not null and pr.provider<>'iyzico') then raise exception 'unsupported_settlement_provider' using errcode='55000'; end if; if pending_count=0 then perform private.release_completed_order_settlements_v1(o.id); insert into private.order_settlement_releases(order_id,status,requested_by,requested_at,released_by,released_at,provider,last_error,updated_at) values(o.id,'released',p_actor_user_id,timezone('utc',now()),p_actor_user_id,timezone('utc',now()),'iyzico',null,timezone('utc',now())) on conflict(order_id) do update set status='released',requested_by=coalesce(private.order_settlement_releases.requested_by,excluded.requested_by),requested_at=coalesce(private.order_settlement_releases.requested_at,excluded.requested_at),released_by=excluded.released_by,released_at=excluded.released_at,provider='iyzico',last_error=null,updated_at=excluded.updated_at; return jsonb_build_object('action','terminal','released',true,'orderId',o.id,'orderNumber',o.order_number,'state',private.order_settlement_state_v1(o.id)); end if; insert into private.order_settlement_releases(order_id,status,requested_by,requested_at,provider,last_error,updated_at) values(o.id,'processing',p_actor_user_id,timezone('utc',now()),'iyzico',null,timezone('utc',now())) on conflict(order_id) do update set status='processing',requested_by=excluded.requested_by,requested_at=excluded.requested_at,provider='iyzico',last_error=null,updated_at=excluded.updated_at; return jsonb_build_object('action','approve','released',false,'orderId',o.id,'orderNumber',o.order_number,'currency',o.currency,'items',items,'state',private.order_settlement_state_v1(o.id)); end;$function$;

CREATE OR REPLACE FUNCTION private.prepare_producer_submerchant_for_service_v1(p_producer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  p public.producers%rowtype;
  a private.producer_payment_accounts%rowtype;
  app public.producer_applications%rowtype;
  kyc private.producer_application_kyc%rowtype;
  legal_name_value text;
  national_id_value text;
  tax_number_value text;
  tax_office_value text;
  iban_value text;
  holder_value text;
  phone_value text;
  email_value text;
  address_value jsonb;
  address_text text;
  name_parts text[];
  contact_name text;
  contact_surname text;
begin
  select * into p from public.producers where id=p_producer_id and deleted_at is null;
  if p.id is null then raise exception 'producer_not_found' using errcode='P0002'; end if;
  if p.status<>'active' or not p.is_verified then raise exception 'active_verified_producer_required' using errcode='55000'; end if;
  select * into a from private.producer_payment_accounts where producer_id=p.id;
  if a.producer_id is null then raise exception 'producer_payment_account_not_configured' using errcode='55000'; end if;
  if a.provider<>'iyzico' then raise exception 'unsupported_payment_provider' using errcode='55000'; end if;
  if a.status='ready' and a.submerchant_key is not null then return jsonb_build_object('ok',true,'action','ready','producerId',p.id,'provider','iyzico','providerSubmerchantType',a.provider_submerchant_type,'externalId',a.submerchant_external_id); end if;
  if a.status='suspended' then raise exception 'producer_payment_account_suspended' using errcode='55000'; end if;
  if a.provider_submerchant_type not in('PERSONAL','PRIVATE_COMPANY','LIMITED_OR_JOINT_STOCK_COMPANY') then raise exception 'provider_submerchant_type_required' using errcode='55000'; end if;
  if p.application_id is null then raise exception 'producer_application_required' using errcode='55000'; end if;

  select * into app from public.producer_applications where id=p.application_id and status='approved';
  if app.id is null then raise exception 'producer_application_not_approved' using errcode='55000'; end if;
  select * into kyc from private.producer_application_kyc where application_id=app.id;
  if kyc.application_id is null then raise exception 'producer_kyc_missing' using errcode='55000'; end if;

  legal_name_value:=btrim(coalesce(kyc.legal_name,''));
  national_id_value:=case when kyc.national_id_ciphertext is null then '' else private.decrypt_producer_kyc(kyc.national_id_ciphertext) end;
  tax_number_value:=case when kyc.tax_number_ciphertext is null then '' else private.decrypt_producer_kyc(kyc.tax_number_ciphertext) end;
  tax_office_value:=btrim(coalesce(kyc.tax_office,''));
  iban_value:=case when kyc.iban_ciphertext is null then '' else private.decrypt_producer_kyc(kyc.iban_ciphertext) end;
  holder_value:=btrim(coalesce(kyc.bank_account_holder,''));
  phone_value:=private.normalize_tr_phone_v1(kyc.phone);
  email_value:=lower(btrim(coalesce(kyc.contact_email,'')));
  address_value:=kyc.address;
  address_text:=private.producer_payment_address_text_v1(address_value);

  if char_length(legal_name_value)<2 or not private.is_valid_tr_iban_v1(iban_value) or phone_value is null or email_value !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' or char_length(coalesce(address_text,''))<10 then raise exception 'producer_payment_kyc_incomplete' using errcode='55000'; end if;
  if nullif(btrim(coalesce(kyc.consent_version,'')),'') is null or kyc.consented_at is null then raise exception 'payment_kyc_consent_required' using errcode='55000'; end if;
  if char_length(holder_value)<2 then holder_value:=legal_name_value; end if;
  name_parts:=regexp_split_to_array(holder_value,'[[:space:]]+');
  if cardinality(name_parts)>=2 then contact_name:=array_to_string(name_parts[1:cardinality(name_parts)-1],' '); contact_surname:=name_parts[cardinality(name_parts)]; else contact_name:=holder_value; contact_surname:=''; end if;

  if a.provider_submerchant_type='PERSONAL' then
    if not private.is_valid_turkish_identity_v1(national_id_value) or contact_surname='' then raise exception 'personal_submerchant_kyc_incomplete' using errcode='55000'; end if;
  elsif a.provider_submerchant_type='PRIVATE_COMPANY' then
    if not private.is_valid_turkish_identity_v1(national_id_value) or char_length(tax_office_value)<2 or char_length(legal_name_value)<2 or contact_surname='' then raise exception 'private_company_submerchant_kyc_incomplete' using errcode='55000'; end if;
  elsif a.provider_submerchant_type='LIMITED_OR_JOINT_STOCK_COMPANY' then
    if tax_number_value !~ '^[0-9]{10}$' or char_length(tax_office_value)<2 or char_length(legal_name_value)<2 then raise exception 'corporate_submerchant_kyc_incomplete' using errcode='55000'; end if;
  end if;

  update private.producer_payment_accounts set status='onboarding',last_error=null,updated_at=timezone('utc',now()) where producer_id=p.id;

  return jsonb_strip_nulls(jsonb_build_object('ok',true,'action','create','producerId',p.id,'producerName',p.display_name,'provider','iyzico','providerSubmerchantType',a.provider_submerchant_type,'externalId',a.submerchant_external_id,'kycSource','approved_application','name',p.display_name,'email',email_value,'gsmNumber',phone_value,'address',address_text,'iban',iban_value,'currency','TRY','contactName',case when a.provider_submerchant_type in('PERSONAL','PRIVATE_COMPANY') then contact_name else null end,'contactSurname',case when a.provider_submerchant_type in('PERSONAL','PRIVATE_COMPANY') then contact_surname else null end,'identityNumber',case when a.provider_submerchant_type in('PERSONAL','PRIVATE_COMPANY') then national_id_value else null end,'taxNumber',case when a.provider_submerchant_type='LIMITED_OR_JOINT_STOCK_COMPANY' then tax_number_value else null end,'taxOffice',case when a.provider_submerchant_type in('PRIVATE_COMPANY','LIMITED_OR_JOINT_STOCK_COMPANY') then tax_office_value else null end,'legalCompanyTitle',case when a.provider_submerchant_type in('PRIVATE_COMPANY','LIMITED_OR_JOINT_STOCK_COMPANY') then legal_name_value else null end));
end;
$function$;

CREATE OR REPLACE FUNCTION private.preview_gift_checkout_v1(p_product_reference text, p_variant_reference text, p_quantity integer, p_country_code text, p_coupon_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  uid uuid:=auth.uid();
  country text:=upper(btrim(coalesce(p_country_code,'')));
  product_row public.products%rowtype;
  variant_row public.product_variants%rowtype;
  producer_ok boolean:=false;
  available_quantity integer;
  subtotal bigint:=0;
  total_weight integer:=0;
  missing_weight integer:=0;
  shipping_weight integer:=0;
  quote jsonb:=jsonb_build_object('available',false,'reason','not_calculated');
  shipping bigint:=0;
  discount bigint:=0;
  product_discount bigint:=0;
  shipping_discount bigint:=0;
  promotion jsonb:=jsonb_build_object('eligible',false,'applied',false,'totalDiscountMinor',0);
  blocking text:=null;
  can_checkout boolean:=true;
  coupon_supplied boolean:=nullif(btrim(coalesce(p_coupon_code,'')),'') is not null;
  coupon_row public.coupons%rowtype;
  campaign_row public.campaigns%rowtype;
  candidate public.campaigns%rowtype;
  code_hash text;
  eligible boolean;
  candidate_discount bigint;
  best_discount bigint:=0;
  best_priority integer:=-1000000;
  campaign_usage bigint;
  campaign_user_usage bigint;
  coupon_usage bigint;
  coupon_user_usage bigint;
begin
  if uid is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if not exists(select 1 from public.profiles p where p.id=uid and p.status='active' and p.deleted_at is null) then raise exception 'active_profile_required' using errcode='42501'; end if;
  if p_product_reference is null or char_length(btrim(p_product_reference)) not between 1 and 220 then raise exception 'invalid_product_reference' using errcode='22023'; end if;
  if p_variant_reference is null or char_length(btrim(p_variant_reference)) not between 1 and 160 then raise exception 'invalid_variant_reference' using errcode='22023'; end if;
  if p_quantity is null or p_quantity not between 1 and 20 then raise exception 'invalid_gift_quantity' using errcode='22023'; end if;
  if country !~ '^[A-Z]{2}$' then raise exception 'invalid_shipping_country' using errcode='22023'; end if;

  select p.* into product_row
  from public.products p
  join public.producers pr on pr.id=p.producer_id
  where (p.id::text=btrim(p_product_reference) or p.slug=btrim(p_product_reference) or p.legacy_id=btrim(p_product_reference))
    and p.status='published' and p.is_active=true and p.deleted_at is null
    and pr.status='active' and pr.is_verified=true and pr.deleted_at is null
  limit 1;
  if product_row.id is null then raise exception 'product_not_available' using errcode='22023'; end if;

  select v.* into variant_row
  from public.product_variants v
  where v.product_id=product_row.id and v.is_active=true and (v.id::text=btrim(p_variant_reference) or v.sku=btrim(p_variant_reference))
  limit 1;
  if variant_row.id is null then raise exception 'variant_not_available' using errcode='22023'; end if;

  if product_row.stock_mode in ('tracked','seasonal') then
    select greatest(0,inv.available_quantity-inv.reserved_quantity) into available_quantity
    from public.product_inventory inv where inv.variant_id=variant_row.id;
    if available_quantity is null then can_checkout:=false; blocking:='stock_unverified';
    elsif available_quantity<p_quantity then can_checkout:=false; blocking:='insufficient_stock'; end if;
  end if;

  subtotal:=variant_row.price_minor*p_quantity;
  if subtotal<=0 then raise exception 'invalid_order_total' using errcode='22023'; end if;
  if variant_row.weight_grams is null or variant_row.weight_grams<=0 then
    missing_weight:=p_quantity;
  else
    total_weight:=variant_row.weight_grams*p_quantity;
  end if;

  if country<>'TR' and missing_weight>0 then
    can_checkout:=false;
    if blocking is null then blocking:='international_shipping_weight_missing'; end if;
    quote:=jsonb_build_object('available',false,'manualQuoteRequired',false,'countryCode',country,'reason','international_shipping_weight_missing','missingWeightQuantity',missing_weight);
  else
    shipping_weight:=greatest(total_weight,case when missing_weight>0 then missing_weight else 1 end);
    quote:=public.get_shipping_quote_v1(country,shipping_weight,subtotal,product_row.currency);
    if not coalesce((quote->>'available')::boolean,false) then
      can_checkout:=false;
      if blocking is null then blocking:=coalesce(quote->>'reason','shipping_not_available'); end if;
    else shipping:=coalesce((quote->>'shippingMinor')::bigint,0); end if;
  end if;

  if coupon_supplied then
    code_hash:=private.hash_coupon_code_v1(p_coupon_code);
    select c.* into coupon_row from public.coupons c
    where c.code_hash=code_hash and c.status='active'
      and (c.starts_at is null or timezone('utc',now())>=c.starts_at)
      and (c.ends_at is null or timezone('utc',now())<=c.ends_at)
    limit 1;
    if coupon_row.id is null then
      can_checkout:=false; if blocking is null then blocking:='coupon_invalid_or_unavailable'; end if;
      promotion:=jsonb_build_object('eligible',false,'applied',false,'reason','coupon_invalid_or_unavailable','totalDiscountMinor',0);
    else
      select * into campaign_row from public.campaigns c where c.id=coupon_row.campaign_id;
      eligible:=campaign_row.id is not null and campaign_row.activation_mode='coupon' and campaign_row.status='active'
        and timezone('utc',now()) between campaign_row.starts_at and campaign_row.ends_at
        and subtotal>=campaign_row.minimum_order_minor
        and (campaign_row.discount_type<>'fixed' or campaign_row.currency=product_row.currency)
        and (campaign_row.target_scope='all'
          or (campaign_row.target_scope='products' and exists(select 1 from public.campaign_products l where l.campaign_id=campaign_row.id and l.product_id=product_row.id))
          or (campaign_row.target_scope='categories' and exists(select 1 from public.campaign_categories l where l.campaign_id=campaign_row.id and l.category_id=product_row.category_id)));
      if eligible then
        select count(*) into campaign_usage from private.promotion_redemptions r where r.campaign_id=campaign_row.id and (r.status='consumed' or (r.status='reserved' and (r.expires_at is null or r.expires_at>timezone('utc',now()))));
        select count(*) into campaign_user_usage from private.promotion_redemptions r where r.campaign_id=campaign_row.id and r.user_id=uid and (r.status='consumed' or (r.status='reserved' and (r.expires_at is null or r.expires_at>timezone('utc',now()))));
        select count(*) into coupon_usage from private.promotion_redemptions r where r.coupon_id=coupon_row.id and (r.status='consumed' or (r.status='reserved' and (r.expires_at is null or r.expires_at>timezone('utc',now()))));
        select count(*) into coupon_user_usage from private.promotion_redemptions r where r.coupon_id=coupon_row.id and r.user_id=uid and (r.status='consumed' or (r.status='reserved' and (r.expires_at is null or r.expires_at>timezone('utc',now()))));
        if (campaign_row.usage_limit is not null and campaign_usage>=campaign_row.usage_limit) or campaign_user_usage>=campaign_row.per_user_limit or (coupon_row.usage_limit is not null and coupon_usage>=coupon_row.usage_limit) or coupon_user_usage>=coupon_row.per_user_limit then eligible:=false; end if;
      end if;
      if not eligible then
        can_checkout:=false; if blocking is null then blocking:='coupon_not_applicable'; end if;
        promotion:=jsonb_build_object('eligible',false,'applied',false,'reason','coupon_not_applicable','displayHint',coupon_row.display_hint,'totalDiscountMinor',0);
      else
        if campaign_row.discount_type='percentage' then
          product_discount:=floor((subtotal::numeric*campaign_row.discount_value::numeric)/10000)::bigint;
          if campaign_row.max_discount_minor is not null then product_discount:=least(product_discount,campaign_row.max_discount_minor); end if;
          product_discount:=least(product_discount,subtotal);
        elsif campaign_row.discount_type='fixed' then product_discount:=least(campaign_row.discount_value::bigint,subtotal);
        else shipping_discount:=shipping;
        end if;
        discount:=product_discount+shipping_discount;
        if discount<=0 or subtotal+shipping-discount<=0 then
          can_checkout:=false; if blocking is null then blocking:='coupon_not_applicable'; end if;
          promotion:=jsonb_build_object('eligible',false,'applied',false,'reason','zero_discount','totalDiscountMinor',0);
        else
          promotion:=jsonb_build_object('eligible',true,'applied',true,'campaignId',campaign_row.id,'title',campaign_row.title,'couponId',coupon_row.id,'displayHint',coupon_row.display_hint,'discountType',campaign_row.discount_type,'productDiscountMinor',product_discount,'shippingDiscountMinor',shipping_discount,'totalDiscountMinor',discount);
        end if;
      end if;
    end if;
  else
    for candidate in select c.* from public.campaigns c where c.activation_mode='automatic' and c.status='active' and timezone('utc',now()) between c.starts_at and c.ends_at order by c.priority desc,c.created_at asc
    loop
      eligible:=subtotal>=candidate.minimum_order_minor
        and (candidate.discount_type<>'fixed' or candidate.currency=product_row.currency)
        and (candidate.target_scope='all'
          or (candidate.target_scope='products' and exists(select 1 from public.campaign_products l where l.campaign_id=candidate.id and l.product_id=product_row.id))
          or (candidate.target_scope='categories' and exists(select 1 from public.campaign_categories l where l.campaign_id=candidate.id and l.category_id=product_row.category_id)));
      if not eligible then continue; end if;
      select count(*) into campaign_usage from private.promotion_redemptions r where r.campaign_id=candidate.id and (r.status='consumed' or (r.status='reserved' and (r.expires_at is null or r.expires_at>timezone('utc',now()))));
      select count(*) into campaign_user_usage from private.promotion_redemptions r where r.campaign_id=candidate.id and r.user_id=uid and (r.status='consumed' or (r.status='reserved' and (r.expires_at is null or r.expires_at>timezone('utc',now()))));
      if (candidate.usage_limit is not null and campaign_usage>=candidate.usage_limit) or campaign_user_usage>=candidate.per_user_limit then continue; end if;
      product_discount:=0; shipping_discount:=0;
      if candidate.discount_type='percentage' then
        product_discount:=floor((subtotal::numeric*candidate.discount_value::numeric)/10000)::bigint;
        if candidate.max_discount_minor is not null then product_discount:=least(product_discount,candidate.max_discount_minor); end if;
        product_discount:=least(product_discount,subtotal);
      elsif candidate.discount_type='fixed' then product_discount:=least(candidate.discount_value::bigint,subtotal);
      else shipping_discount:=shipping;
      end if;
      candidate_discount:=product_discount+shipping_discount;
      if candidate_discount>0 and subtotal+shipping-candidate_discount>0 and (candidate_discount>best_discount or (candidate_discount=best_discount and candidate.priority>best_priority)) then
        best_discount:=candidate_discount; best_priority:=candidate.priority; discount:=candidate_discount;
        promotion:=jsonb_build_object('eligible',true,'applied',true,'campaignId',candidate.id,'title',candidate.title,'discountType',candidate.discount_type,'productDiscountMinor',product_discount,'shippingDiscountMinor',shipping_discount,'totalDiscountMinor',candidate_discount);
      end if;
    end loop;
  end if;

  return jsonb_build_object(
    'canCheckout',can_checkout,'blockingReason',blocking,'countryCode',country,'currency',product_row.currency,
    'productId',product_row.id,'productSlug',product_row.slug,'variantId',variant_row.id,'quantity',p_quantity,
    'subtotalMinor',subtotal,'shippingMinor',shipping,'discountMinor',discount,'totalMinor',greatest(0,subtotal+shipping-discount),
    'totalWeightGrams',total_weight,'shippingWeightGrams',shipping_weight,'missingWeightQuantity',missing_weight,
    'availableQuantity',available_quantity,'shipping',quote,'promotion',promotion,'previewOnly',true
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.preview_my_checkout_v1(p_country_code text DEFAULT 'TR'::text, p_coupon_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  normalized_country text := upper(btrim(coalesce(p_country_code,'TR')));
  cart_row public.carts%rowtype;
  currency_value text := 'TRY';
  item_count integer := 0;
  subtotal_value bigint := 0;
  total_weight integer := 0;
  shipping_weight integer := 0;
  missing_weight_count integer := 0;
  unavailable_count integer := 0;
  insufficient_count integer := 0;
  quote jsonb;
  shipping_value bigint := 0;
  promotion jsonb := jsonb_build_object('eligible',false,'applied',false,'totalDiscountMinor',0);
  promotion_discount bigint := 0;
  product_discount bigint := 0;
  shipping_discount bigint := 0;
  eligible_subtotal bigint := 0;
  campaign_row public.campaigns%rowtype;
  coupon_row public.coupons%rowtype;
  candidate public.campaigns%rowtype;
  best_discount bigint := 0;
  best_priority integer := -1000000;
  code_hash_value text;
  campaign_usage bigint;
  campaign_user_usage bigint;
  coupon_usage bigint;
  coupon_user_usage bigint;
  blocking_reason text := null;
  can_checkout boolean := true;
  coupon_supplied boolean := nullif(btrim(coalesce(p_coupon_code,'')),'') is not null;
  candidate_discount bigint;
  candidate_product_discount bigint;
  candidate_shipping_discount bigint;
  candidate_eligible_subtotal bigint;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if normalized_country !~ '^[A-Z]{2}$' then raise exception 'invalid_shipping_country' using errcode='22023'; end if;
  if not exists(select 1 from public.profiles where id=caller_id and status='active' and deleted_at is null) then
    raise exception 'active_profile_required' using errcode='42501';
  end if;

  select * into cart_row
  from public.carts
  where user_id=caller_id and status='active' and (expires_at is null or expires_at>timezone('utc',now()))
  order by created_at desc
  limit 1;

  if cart_row.id is null then
    return jsonb_build_object(
      'canCheckout',false,'blockingReason','cart_empty','countryCode',normalized_country,
      'currency','TRY','itemCount',0,'subtotalMinor',0,'shippingMinor',0,'discountMinor',0,'totalMinor',0,
      'shipping',jsonb_build_object('available',false,'reason','cart_empty'),
      'promotion',promotion
    );
  end if;
  currency_value:=cart_row.currency;

  select
    coalesce(sum(ci.quantity),0)::integer,
    coalesce(sum(ci.quantity*v.price_minor),0)::bigint,
    coalesce(sum(case when v.weight_grams is not null and v.weight_grams>0 then ci.quantity*v.weight_grams else 0 end),0)::integer,
    coalesce(sum(case when v.weight_grams is null or v.weight_grams<=0 then ci.quantity else 0 end),0)::integer,
    count(*) filter(where p.status<>'published' or not p.is_active or p.deleted_at is not null or not v.is_active or pr.status<>'active' or not pr.is_verified or pr.deleted_at is not null)::integer,
    count(*) filter(where p.stock_mode in ('tracked','seasonal') and (inv.variant_id is null or inv.available_quantity-inv.reserved_quantity<ci.quantity))::integer
  into item_count,subtotal_value,total_weight,missing_weight_count,unavailable_count,insufficient_count
  from public.cart_items ci
  join public.product_variants v on v.id=ci.variant_id
  join public.products p on p.id=v.product_id
  join public.producers pr on pr.id=p.producer_id
  left join public.product_inventory inv on inv.variant_id=v.id
  where ci.cart_id=cart_row.id;

  if item_count<=0 then
    return jsonb_build_object(
      'canCheckout',false,'blockingReason','cart_empty','countryCode',normalized_country,
      'currency',currency_value,'itemCount',0,'subtotalMinor',0,'shippingMinor',0,'discountMinor',0,'totalMinor',0,
      'shipping',jsonb_build_object('available',false,'reason','cart_empty'),
      'promotion',promotion
    );
  end if;

  if unavailable_count>0 then
    can_checkout:=false;
    blocking_reason:='product_not_available';
  elsif insufficient_count>0 then
    can_checkout:=false;
    blocking_reason:='insufficient_stock';
  elsif normalized_country<>'TR' and missing_weight_count>0 then
    can_checkout:=false;
    blocking_reason:='international_shipping_weight_missing';
  end if;

  if blocking_reason='international_shipping_weight_missing' then
    quote:=jsonb_build_object(
      'available',false,'manualQuoteRequired',false,'countryCode',normalized_country,
      'reason','international_shipping_weight_missing','missingWeightQuantity',missing_weight_count
    );
  else
    shipping_weight:=greatest(total_weight,case when missing_weight_count>0 then missing_weight_count else 1 end);
    quote:=public.get_shipping_quote_v1(normalized_country,shipping_weight,subtotal_value,currency_value);
    if not coalesce((quote->>'available')::boolean,false) then
      can_checkout:=false;
      if blocking_reason is null then blocking_reason:=coalesce(quote->>'reason','shipping_not_available'); end if;
    else
      shipping_value:=coalesce((quote->>'shippingMinor')::bigint,0);
    end if;
  end if;

  -- Coupon preview: validate without reserving or consuming anything.
  if coupon_supplied then
    code_hash_value:=private.hash_coupon_code_v1(p_coupon_code);
    select c.* into coupon_row
    from public.coupons c
    where c.code_hash=code_hash_value
      and c.status='active'
      and (c.starts_at is null or timezone('utc',now())>=c.starts_at)
      and (c.ends_at is null or timezone('utc',now())<=c.ends_at)
    limit 1;

    if coupon_row.id is null then
      promotion:=jsonb_build_object('eligible',false,'applied',false,'reason','coupon_invalid_or_unavailable','totalDiscountMinor',0);
      can_checkout:=false;
      if blocking_reason is null then blocking_reason:='coupon_invalid_or_unavailable'; end if;
    else
      select * into campaign_row from public.campaigns where id=coupon_row.campaign_id;
      if campaign_row.id is null or campaign_row.activation_mode<>'coupon' or campaign_row.status<>'active'
         or timezone('utc',now())<campaign_row.starts_at or timezone('utc',now())>campaign_row.ends_at then
        promotion:=jsonb_build_object('eligible',false,'applied',false,'reason','coupon_invalid_or_unavailable','totalDiscountMinor',0);
        can_checkout:=false;
        if blocking_reason is null then blocking_reason:='coupon_invalid_or_unavailable'; end if;
      else
        select count(*) into campaign_usage from private.promotion_redemptions r
        where r.campaign_id=campaign_row.id and (r.status='consumed' or (r.status='reserved' and (r.expires_at is null or r.expires_at>timezone('utc',now()))));
        select count(*) into campaign_user_usage from private.promotion_redemptions r
        where r.campaign_id=campaign_row.id and r.user_id=caller_id and (r.status='consumed' or (r.status='reserved' and (r.expires_at is null or r.expires_at>timezone('utc',now()))));
        select count(*) into coupon_usage from private.promotion_redemptions r
        where r.coupon_id=coupon_row.id and (r.status='consumed' or (r.status='reserved' and (r.expires_at is null or r.expires_at>timezone('utc',now()))));
        select count(*) into coupon_user_usage from private.promotion_redemptions r
        where r.coupon_id=coupon_row.id and r.user_id=caller_id and (r.status='consumed' or (r.status='reserved' and (r.expires_at is null or r.expires_at>timezone('utc',now()))));

        if (campaign_row.usage_limit is not null and campaign_usage>=campaign_row.usage_limit)
           or campaign_user_usage>=campaign_row.per_user_limit
           or (coupon_row.usage_limit is not null and coupon_usage>=coupon_row.usage_limit)
           or coupon_user_usage>=coupon_row.per_user_limit then
          promotion:=jsonb_build_object('eligible',false,'applied',false,'reason','coupon_usage_limit_reached','totalDiscountMinor',0,'displayHint',coupon_row.display_hint);
          can_checkout:=false;
          if blocking_reason is null then blocking_reason:='coupon_usage_limit_reached'; end if;
        elsif subtotal_value<campaign_row.minimum_order_minor then
          promotion:=jsonb_build_object('eligible',false,'applied',false,'reason','minimum_order_not_met','totalDiscountMinor',0,'displayHint',coupon_row.display_hint,'minimumOrderMinor',campaign_row.minimum_order_minor);
          can_checkout:=false;
          if blocking_reason is null then blocking_reason:='coupon_not_applicable'; end if;
        elsif campaign_row.discount_type='fixed' and campaign_row.currency is distinct from currency_value then
          promotion:=jsonb_build_object('eligible',false,'applied',false,'reason','campaign_currency_mismatch','totalDiscountMinor',0,'displayHint',coupon_row.display_hint);
          can_checkout:=false;
          if blocking_reason is null then blocking_reason:='coupon_not_applicable'; end if;
        else
          if campaign_row.target_scope='all' then
            eligible_subtotal:=subtotal_value;
          elsif campaign_row.target_scope='products' then
            select coalesce(sum(ci.quantity*v.price_minor),0)::bigint into eligible_subtotal
            from public.cart_items ci join public.product_variants v on v.id=ci.variant_id
            where ci.cart_id=cart_row.id and exists(select 1 from public.campaign_products link where link.campaign_id=campaign_row.id and link.product_id=v.product_id);
          else
            select coalesce(sum(ci.quantity*v.price_minor),0)::bigint into eligible_subtotal
            from public.cart_items ci join public.product_variants v on v.id=ci.variant_id join public.products p on p.id=v.product_id
            where ci.cart_id=cart_row.id and exists(select 1 from public.campaign_categories link where link.campaign_id=campaign_row.id and link.category_id=p.category_id);
          end if;

          if eligible_subtotal<=0 and campaign_row.discount_type<>'free_shipping' then
            promotion:=jsonb_build_object('eligible',false,'applied',false,'reason','no_eligible_items','totalDiscountMinor',0,'displayHint',coupon_row.display_hint);
            can_checkout:=false;
            if blocking_reason is null then blocking_reason:='coupon_not_applicable'; end if;
          else
            product_discount:=0; shipping_discount:=0;
            if campaign_row.discount_type='percentage' then
              product_discount:=floor((eligible_subtotal::numeric*campaign_row.discount_value::numeric)/10000)::bigint;
              if campaign_row.max_discount_minor is not null then product_discount:=least(product_discount,campaign_row.max_discount_minor); end if;
              product_discount:=least(product_discount,eligible_subtotal);
            elsif campaign_row.discount_type='fixed' then
              product_discount:=least(campaign_row.discount_value::bigint,eligible_subtotal);
            else
              shipping_discount:=shipping_value;
            end if;
            promotion_discount:=product_discount+shipping_discount;
            if promotion_discount<=0 or subtotal_value+shipping_value-promotion_discount<=0 then
              promotion:=jsonb_build_object('eligible',false,'applied',false,'reason','zero_discount','totalDiscountMinor',0,'displayHint',coupon_row.display_hint);
              can_checkout:=false;
              if blocking_reason is null then blocking_reason:='coupon_not_applicable'; end if;
            else
              promotion:=jsonb_build_object(
                'eligible',true,'applied',true,'campaignId',campaign_row.id,'title',campaign_row.title,
                'couponId',coupon_row.id,'displayHint',coupon_row.display_hint,'discountType',campaign_row.discount_type,
                'productDiscountMinor',product_discount,'shippingDiscountMinor',shipping_discount,
                'totalDiscountMinor',promotion_discount
              );
            end if;
          end if;
        end if;
      end if;
    end if;
  else
    -- Automatic campaigns: choose the largest currently usable discount, tie-break by priority.
    for candidate in
      select c.* from public.campaigns c
      where c.activation_mode='automatic' and c.status='active' and timezone('utc',now()) between c.starts_at and c.ends_at
      order by c.priority desc,c.created_at asc
    loop
      select count(*) into campaign_usage from private.promotion_redemptions r
      where r.campaign_id=candidate.id and (r.status='consumed' or (r.status='reserved' and (r.expires_at is null or r.expires_at>timezone('utc',now()))));
      select count(*) into campaign_user_usage from private.promotion_redemptions r
      where r.campaign_id=candidate.id and r.user_id=caller_id and (r.status='consumed' or (r.status='reserved' and (r.expires_at is null or r.expires_at>timezone('utc',now()))));
      if (candidate.usage_limit is not null and campaign_usage>=candidate.usage_limit) or campaign_user_usage>=candidate.per_user_limit then continue; end if;
      if subtotal_value<candidate.minimum_order_minor then continue; end if;
      if candidate.discount_type='fixed' and candidate.currency is distinct from currency_value then continue; end if;

      if candidate.target_scope='all' then
        candidate_eligible_subtotal:=subtotal_value;
      elsif candidate.target_scope='products' then
        select coalesce(sum(ci.quantity*v.price_minor),0)::bigint into candidate_eligible_subtotal
        from public.cart_items ci join public.product_variants v on v.id=ci.variant_id
        where ci.cart_id=cart_row.id and exists(select 1 from public.campaign_products link where link.campaign_id=candidate.id and link.product_id=v.product_id);
      else
        select coalesce(sum(ci.quantity*v.price_minor),0)::bigint into candidate_eligible_subtotal
        from public.cart_items ci join public.product_variants v on v.id=ci.variant_id join public.products p on p.id=v.product_id
        where ci.cart_id=cart_row.id and exists(select 1 from public.campaign_categories link where link.campaign_id=candidate.id and link.category_id=p.category_id);
      end if;
      if candidate_eligible_subtotal<=0 and candidate.discount_type<>'free_shipping' then continue; end if;

      candidate_product_discount:=0; candidate_shipping_discount:=0;
      if candidate.discount_type='percentage' then
        candidate_product_discount:=floor((candidate_eligible_subtotal::numeric*candidate.discount_value::numeric)/10000)::bigint;
        if candidate.max_discount_minor is not null then candidate_product_discount:=least(candidate_product_discount,candidate.max_discount_minor); end if;
        candidate_product_discount:=least(candidate_product_discount,candidate_eligible_subtotal);
      elsif candidate.discount_type='fixed' then
        candidate_product_discount:=least(candidate.discount_value::bigint,candidate_eligible_subtotal);
      else
        candidate_shipping_discount:=shipping_value;
      end if;
      candidate_discount:=candidate_product_discount+candidate_shipping_discount;
      if candidate_discount<=0 or subtotal_value+shipping_value-candidate_discount<=0 then continue; end if;

      if candidate_discount>best_discount or (candidate_discount=best_discount and candidate.priority>best_priority) then
        best_discount:=candidate_discount;
        best_priority:=candidate.priority;
        product_discount:=candidate_product_discount;
        shipping_discount:=candidate_shipping_discount;
        promotion:=jsonb_build_object(
          'eligible',true,'applied',true,'campaignId',candidate.id,'title',candidate.title,
          'discountType',candidate.discount_type,'productDiscountMinor',candidate_product_discount,
          'shippingDiscountMinor',candidate_shipping_discount,'totalDiscountMinor',candidate_discount
        );
      end if;
    end loop;
    promotion_discount:=best_discount;
  end if;

  return jsonb_build_object(
    'canCheckout',can_checkout,
    'blockingReason',blocking_reason,
    'countryCode',normalized_country,
    'currency',currency_value,
    'itemCount',item_count,
    'subtotalMinor',subtotal_value,
    'shippingMinor',shipping_value,
    'discountMinor',promotion_discount,
    'totalMinor',greatest(0,subtotal_value+shipping_value-promotion_discount),
    'totalWeightGrams',total_weight,
    'shippingWeightGrams',shipping_weight,
    'missingWeightQuantity',missing_weight_count,
    'shipping',quote,
    'promotion',promotion,
    'previewOnly',true
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.process_product_sales_windows_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare opened_count integer:=0; closed_count integer:=0; notification_count integer:=0;
begin with updated as (update public.product_sales_windows w set status='open',updated_at=timezone('utc',now()) where w.is_confirmed=true and w.status='scheduled' and w.preorder_opens_at is not null and w.preorder_opens_at<=timezone('utc',now()) and (w.preorder_closes_at is null or w.preorder_closes_at>timezone('utc',now())) returning id) select count(*) into opened_count from updated; with updated as (update public.product_sales_windows w set status='closed',updated_at=timezone('utc',now()) where w.is_confirmed=true and w.status='open' and w.preorder_closes_at is not null and w.preorder_closes_at<=timezone('utc',now()) returning id) select count(*) into closed_count from updated; with candidates as (select s.id subscription_id,s.user_id,w.id window_id,p.slug,p.name from public.product_sales_windows w join public.product_availability_subscriptions s on s.product_id=w.product_id and s.active=true and s.notify_on_preorder=true join public.products p on p.id=w.product_id where w.is_confirmed=true and w.status='open' and p.status='published' and p.is_active=true and p.deleted_at is null), claimed as (insert into private.product_availability_delivery_log(subscription_id,sales_window_id,event_type) select c.subscription_id,c.window_id,'preorder_open' from candidates c on conflict do nothing returning subscription_id,sales_window_id), messages as (select c.user_id,c.slug,c.name,c.window_id from candidates c join claimed x on x.subscription_id=c.subscription_id and x.sales_window_id=c.window_id), inserted as (insert into public.notifications(user_id,type,title,message,action_url,metadata) select m.user_id,'product_preorder_open','Sipariş dönemi açıldı',m.name||' için sipariş dönemi açıldı. Ürün sayfasından hazırlama seçeneklerini seçerek sipariş verebilirsiniz.','/?tab=product-detail&product='||m.slug,jsonb_build_object('productSlug',m.slug,'salesWindowId',m.window_id) from messages m returning id) select count(*) into notification_count from inserted; return jsonb_build_object('opened',opened_count,'closed',closed_count,'notifications',notification_count); end;$function$;

CREATE OR REPLACE FUNCTION private.producer_add_product_batch_event_v1(p_batch_id uuid, p_event_type text, p_event_at timestamp with time zone, p_location_label text, p_public_note text, p_visibility text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := (select auth.uid());
  batch_row public.product_batches%rowtype;
  new_id bigint;
  normalized_note text := btrim(coalesce(p_public_note, ''));
  normalized_location text := nullif(btrim(coalesce(p_location_label, '')), '');
  normalized_visibility text := coalesce(nullif(btrim(coalesce(p_visibility, '')), ''), 'public');
begin
  if caller_id is null then raise exception 'authentication_required' using errcode = '42501'; end if; if not private.has_permission('product.update') then raise exception 'permission_required:product.update' using errcode='42501'; end if;
  select batch.* into batch_row
  from public.product_batches batch
  join public.producers producer on producer.id = batch.producer_id
  where batch.id = p_batch_id and producer.owner_user_id = caller_id
  for update of batch;
  if batch_row.id is null then raise exception 'batch_not_found_or_access_denied' using errcode = '42501'; end if;
  if batch_row.status not in ('draft','rejected') then raise exception 'batch_events_frozen' using errcode = '55000'; end if;
  if p_event_type not in ('harvested','produced','packed','quality_checked','stored','correction') then raise exception 'invalid_batch_event_type' using errcode = '22023'; end if;
  if p_event_at is null or p_event_at > timezone('utc', now()) + interval '5 minutes' then raise exception 'invalid_batch_event_time' using errcode = '22023'; end if;
  if normalized_visibility not in ('public','private') then raise exception 'invalid_batch_event_visibility' using errcode = '22023'; end if;
  if char_length(normalized_note) > 1500 then raise exception 'batch_event_note_too_long' using errcode = '22023'; end if;
  if normalized_location is not null and char_length(normalized_location) > 200 then raise exception 'batch_event_location_too_long' using errcode = '22023'; end if;

  insert into public.product_batch_events(batch_id, event_type, event_at, location_label, public_note, visibility, actor_user_id)
  values (p_batch_id, p_event_type, p_event_at, normalized_location, normalized_note, normalized_visibility, caller_id)
  returning id into new_id;
  return new_id;
end;
$function$;

CREATE OR REPLACE FUNCTION private.producer_archive_product_v1(p_reference text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  caller_producer_id uuid;
  target_product_id uuid;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if not private.has_permission('product.archive') then raise exception 'permission_required:product.archive' using errcode='42501'; end if;
  if coalesce(private.has_permission('admin.access'),false) then raise exception 'producer_portal_separate_from_admin' using errcode='42501'; end if;

  select p.id into caller_producer_id
  from public.producers p
  where p.owner_user_id=caller_id
    and p.status='active'
    and p.is_verified=true
    and p.origin_verified=true
    and p.deleted_at is null
  order by p.created_at desc
  limit 1;
  if caller_producer_id is null then raise exception 'verified_active_producer_required' using errcode='42501'; end if;

  select product.id into target_product_id
  from public.products product
  where product.producer_id=caller_producer_id
    and product.deleted_at is null
    and (product.id::text=btrim(coalesce(p_reference,'')) or product.slug=btrim(coalesce(p_reference,'')))
  limit 1;
  if target_product_id is null then raise exception 'product_access_denied' using errcode='42501'; end if;

  return private.management_archive_product_v1(target_product_id::text);
end;
$function$;

CREATE OR REPLACE FUNCTION private.producer_create_shipment_v1(p_order_id uuid, p_items jsonb, p_carrier text, p_tracking_number text, p_tracking_url text, p_estimated_delivery_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  producer_id_value uuid;
  target public.orders%rowtype;
  normalized_carrier text:=btrim(coalesce(p_carrier,''));
  normalized_tracking text:=btrim(coalesce(p_tracking_number,''));
  normalized_url text:=nullif(btrim(coalesce(p_tracking_url,'')),'');
  new_shipment_id uuid;
  element jsonb;
  order_item_id_value uuid;
  quantity_value integer;
  item_row public.order_items%rowtype;
  shipped_before integer;
  requested_count integer;
  recomputed jsonb;
  previous_status text;
  next_status text;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if; if not private.has_permission('order.manage') then raise exception 'permission_required:order.manage' using errcode='42501'; end if;
  if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items) not between 1 and 50 then raise exception 'shipment_items_required' using errcode='22023'; end if;
  if char_length(normalized_carrier) not between 2 and 100 then raise exception 'invalid_carrier' using errcode='22023'; end if;
  if char_length(normalized_tracking) not between 2 and 160 then raise exception 'invalid_tracking_number' using errcode='22023'; end if;
  if normalized_url is not null and (char_length(normalized_url)>500 or normalized_url !~ '^https://') then raise exception 'invalid_tracking_url' using errcode='22023'; end if;
  if p_estimated_delivery_at is not null and (p_estimated_delivery_at<timezone('utc',now())-interval '5 minutes' or p_estimated_delivery_at>timezone('utc',now())+interval '120 days') then raise exception 'invalid_estimated_delivery' using errcode='22023'; end if;
  if exists(select 1 from public.shipments s where lower(s.carrier)=lower(normalized_carrier) and s.tracking_number=normalized_tracking) then raise exception 'tracking_number_already_used' using errcode='23505'; end if;
  if exists(select 1 from jsonb_array_elements(p_items) e group by e->>'orderItemId' having count(*)>1) then raise exception 'duplicate_shipment_items' using errcode='22023'; end if;

  select p.id into producer_id_value from public.producers p
  where p.owner_user_id=caller_id and p.status='active' and p.is_verified=true and p.deleted_at is null order by p.created_at desc limit 1;
  if producer_id_value is null then raise exception 'verified_active_producer_required' using errcode='42501'; end if;

  select * into target from public.orders o where o.id=p_order_id for update;
  if target.id is null or target.payment_status<>'paid' or target.status not in ('confirmed','preparing','partially_shipped') then raise exception 'order_not_fulfillable' using errcode='55000'; end if;

  requested_count:=jsonb_array_length(p_items);
  for element in select value from jsonb_array_elements(p_items)
  loop
    begin order_item_id_value:=(element->>'orderItemId')::uuid; exception when others then raise exception 'invalid_order_item_id' using errcode='22023'; end;
    begin quantity_value:=(element->>'quantity')::integer; exception when others then raise exception 'invalid_shipment_quantity' using errcode='22023'; end;
    if quantity_value<1 then raise exception 'invalid_shipment_quantity' using errcode='22023'; end if;

    select * into item_row from public.order_items oi
    where oi.id=order_item_id_value and oi.order_id=target.id and oi.producer_id=producer_id_value for update;
    if item_row.id is null or item_row.fulfillment_status in ('cancelled','returned','fulfilled') then raise exception 'invalid_producer_order_item' using errcode='42501'; end if;
    select coalesce(sum(si.quantity),0)::integer into shipped_before from public.shipment_items si where si.order_item_id=item_row.id;
    if quantity_value>item_row.quantity-shipped_before then raise exception 'shipment_quantity_exceeds_remaining' using errcode='22023'; end if;
  end loop;

  insert into public.shipments(order_id,carrier,tracking_number,tracking_url,status,shipped_at,estimated_delivery_at)
  values(target.id,normalized_carrier,normalized_tracking,normalized_url,'in_transit',timezone('utc',now()),p_estimated_delivery_at)
  returning id into new_shipment_id;

  for element in select value from jsonb_array_elements(p_items)
  loop
    order_item_id_value:=(element->>'orderItemId')::uuid;
    quantity_value:=(element->>'quantity')::integer;
    insert into public.shipment_items(shipment_id,order_item_id,quantity) values(new_shipment_id,order_item_id_value,quantity_value);
  end loop;

  update public.order_items oi
  set fulfillment_status=case
    when coalesce((select sum(si.quantity)::integer from public.shipment_items si where si.order_item_id=oi.id),0)>=oi.quantity then 'fulfilled'
    else 'processing'
  end
  where oi.order_id=target.id and oi.producer_id=producer_id_value and oi.id in(select (e->>'orderItemId')::uuid from jsonb_array_elements(p_items) e);

  recomputed:=private.recompute_order_fulfillment_v1(target.id);
  previous_status:=recomputed->>'previousStatus';
  next_status:=recomputed->>'status';
  if next_status is distinct from previous_status then
    insert into public.order_status_history(order_id,from_status,to_status,note,visible_to_customer,actor_user_id)
    values(target.id,previous_status,next_status,case when next_status='shipped' then 'Siparişiniz kargoya verildi.' else 'Siparişinizin bir bölümü kargoya verildi.' end,true,caller_id);
  end if;

  insert into public.notifications(user_id,type,title,message,action_url,metadata)
  values(target.user_id,'shipment',case when next_status='shipped' then 'Siparişiniz kargoya verildi' else 'Siparişinizin bir bölümü kargoda' end,
    format('%s ile gönderildi. Takip numarası: %s',normalized_carrier,normalized_tracking),'/?tab=account',
    jsonb_build_object('orderId',target.id,'shipmentId',new_shipment_id,'carrier',normalized_carrier,'trackingNumber',normalized_tracking));

  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
  values('shipment',new_shipment_id,'shipment.created',jsonb_build_object('shipment_id',new_shipment_id,'order_id',target.id,'producer_id',producer_id_value));

  return private.get_my_producer_order_detail_v1(target.id);
end;
$function$;

CREATE OR REPLACE FUNCTION private.producer_kyc_key()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  encryption_key text;
begin
  select secret.decrypted_secret
  into encryption_key
  from vault.decrypted_secrets secret
  where secret.name = 'golden_oremar_producer_kyc_key'
  limit 1;

  if encryption_key is null then
    raise exception 'producer_kyc_key_missing' using errcode = '55000';
  end if;

  return encryption_key;
end;
$function$;

CREATE OR REPLACE FUNCTION private.producer_mark_order_items_processing_v1(p_order_id uuid, p_order_item_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  producer_id_value uuid;
  target public.orders%rowtype;
  requested_count integer;
  matched_count integer;
  recomputed jsonb;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if; if not private.has_permission('order.manage') then raise exception 'permission_required:order.manage' using errcode='42501'; end if;
  if p_order_item_ids is null or coalesce(array_length(p_order_item_ids,1),0) not between 1 and 50 then raise exception 'order_items_required' using errcode='22023'; end if;
  select count(distinct id),count(*) into matched_count,requested_count from unnest(p_order_item_ids) id;
  if matched_count<>requested_count then raise exception 'duplicate_order_items' using errcode='22023'; end if;

  select p.id into producer_id_value from public.producers p
  where p.owner_user_id=caller_id and p.status='active' and p.is_verified=true and p.deleted_at is null order by p.created_at desc limit 1;
  if producer_id_value is null then raise exception 'verified_active_producer_required' using errcode='42501'; end if;

  select * into target from public.orders o where o.id=p_order_id for update;
  if target.id is null or target.payment_status<>'paid' or target.status not in ('confirmed','preparing','partially_shipped') then raise exception 'order_not_fulfillable' using errcode='55000'; end if;

  select count(*) into matched_count from public.order_items oi
  where oi.id=any(p_order_item_ids) and oi.order_id=target.id and oi.producer_id=producer_id_value and oi.fulfillment_status in ('unfulfilled','processing');
  if matched_count<>requested_count then raise exception 'invalid_producer_order_items' using errcode='42501'; end if;

  update public.order_items set fulfillment_status='processing'
  where id=any(p_order_item_ids) and fulfillment_status='unfulfilled';

  recomputed:=private.recompute_order_fulfillment_v1(target.id);
  if (recomputed->>'status') is distinct from (recomputed->>'previousStatus') then
    insert into public.order_status_history(order_id,from_status,to_status,note,visible_to_customer,actor_user_id)
    values(target.id,recomputed->>'previousStatus',recomputed->>'status','Siparişiniz hazırlanıyor.',true,caller_id);
    insert into public.notifications(user_id,type,title,message,action_url,metadata)
    values(target.user_id,'order','Siparişiniz hazırlanıyor',format('%s numaralı siparişinizin ürünleri hazırlanmaya başladı.',target.order_number),'/?tab=account',jsonb_build_object('orderId',target.id));
  end if;
  return private.get_my_producer_order_detail_v1(target.id);
end;
$function$;

CREATE OR REPLACE FUNCTION private.producer_payment_address_text_v1(p_address jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select nullif(btrim(concat_ws(' ',
    nullif(btrim(coalesce(p_address->>'address_line',p_address->>'addressLine',p_address->>'address_line1','')),''),
    nullif(btrim(coalesce(p_address->>'neighborhood','')),''),
    nullif(btrim(coalesce(p_address->>'district','')),''),
    nullif(btrim(coalesce(p_address->>'province','')),''),
    nullif(btrim(coalesce(p_address->>'postal_code',p_address->>'postalCode','')),''),
    nullif(btrim(coalesce(p_address->>'country_code',p_address->>'countryCode','TR')),'')
  )), '');
$function$;

CREATE OR REPLACE FUNCTION private.producer_reply_to_review_v1(p_review_id uuid, p_reply text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); reply_value text:=btrim(coalesce(p_reply,'')); review_row public.reviews%rowtype;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  perform private.require_current_terms_v1();
  if char_length(reply_value) not between 2 and 2000 then raise exception 'invalid_review_reply' using errcode='22023'; end if;
  select review.* into review_row from public.reviews review join public.products product on product.id=review.product_id join public.producers producer on producer.id=product.producer_id where review.id=p_review_id and producer.owner_user_id=caller_id and producer.status='active' and producer.deleted_at is null for update of review;
  if review_row.id is null then raise exception 'review_reply_access_denied' using errcode='42501'; end if;
  if review_row.status<>'published' then raise exception 'only_published_review_can_be_replied' using errcode='55000'; end if;
  update public.reviews set merchant_reply=reply_value,merchant_replied_at=timezone('utc',now()),merchant_reply_by=caller_id,updated_at=timezone('utc',now()) where id=review_row.id returning * into review_row;
  insert into public.notifications(user_id,type,title,message,action_url,metadata) values(review_row.user_id,'review','Üretici yorumunuza cevap verdi','Satın aldığınız ürünün üreticisi yorumunuza cevap verdi.','/account/reviews',jsonb_build_object('reviewId',review_row.id));
  return jsonb_build_object('id',review_row.id,'merchantReply',review_row.merchant_reply,'merchantRepliedAt',review_row.merchant_replied_at);
end; $function$;

CREATE OR REPLACE FUNCTION private.producer_save_product_batch_v1(p_batch_id uuid, p_product_reference text, p_variant_id uuid, p_batch_code text, p_harvest_date date, p_production_date date, p_packaging_date date, p_best_before_date date, p_origin_country_code text, p_origin_province text, p_origin_district text, p_origin_village text, p_origin_latitude numeric, p_origin_longitude numeric, p_production_method text, p_initial_quantity numeric, p_quantity_unit text, p_public_notes text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := (select auth.uid());
  product_row public.products%rowtype;
  producer_row public.producers%rowtype;
  existing public.product_batches%rowtype;
  normalized_batch_code text;
  normalized_country text := upper(btrim(coalesce(p_origin_country_code, 'TR')));
  normalized_province text;
  normalized_district text;
  normalized_village text;
  normalized_method text := btrim(coalesce(p_production_method, ''));
  normalized_unit text := nullif(btrim(coalesce(p_quantity_unit, '')), '');
  normalized_notes text := btrim(coalesce(p_public_notes, ''));
  saved public.product_batches%rowtype;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode = '42501'; end if; if not private.has_permission('product.update') then raise exception 'permission_required:product.update' using errcode='42501'; end if;

  select product.* into product_row
  from public.products product
  where product.id::text = btrim(coalesce(p_product_reference, ''))
     or product.slug = btrim(coalesce(p_product_reference, ''))
  limit 1;
  if product_row.id is null then raise exception 'product_not_found' using errcode = 'P0002'; end if;

  select producer.* into producer_row
  from public.producers producer
  where producer.id = product_row.producer_id
    and producer.owner_user_id = caller_id
    and producer.status = 'active'
    and producer.deleted_at is null;
  if producer_row.id is null then raise exception 'producer_product_access_denied' using errcode = '42501'; end if;

  if p_variant_id is not null and not exists (
    select 1 from public.product_variants variant
    where variant.id = p_variant_id and variant.product_id = product_row.id and variant.is_active = true
  ) then
    raise exception 'invalid_product_variant' using errcode = '22023';
  end if;

  normalized_province := coalesce(nullif(btrim(coalesce(p_origin_province, '')), ''), producer_row.production_province);
  normalized_district := coalesce(nullif(btrim(coalesce(p_origin_district, '')), ''), producer_row.production_district);
  normalized_village := coalesce(nullif(btrim(coalesce(p_origin_village, '')), ''), producer_row.production_village);

  if normalized_country !~ '^[A-Z]{2}$' then raise exception 'invalid_origin_country' using errcode = '22023'; end if;
  if char_length(coalesce(normalized_province, '')) not between 2 and 100 then raise exception 'invalid_origin_province' using errcode = '22023'; end if;
  if char_length(coalesce(normalized_district, '')) not between 2 and 100 then raise exception 'invalid_origin_district' using errcode = '22023'; end if;
  if char_length(coalesce(normalized_village, '')) not between 2 and 160 then raise exception 'invalid_origin_village' using errcode = '22023'; end if;
  if (p_origin_latitude is null) <> (p_origin_longitude is null) then raise exception 'origin_coordinates_must_be_paired' using errcode = '22023'; end if;
  if p_origin_latitude is not null and p_origin_latitude not between -90 and 90 then raise exception 'invalid_origin_latitude' using errcode = '22023'; end if;
  if p_origin_longitude is not null and p_origin_longitude not between -180 and 180 then raise exception 'invalid_origin_longitude' using errcode = '22023'; end if;
  if p_harvest_date is null and p_production_date is null then raise exception 'harvest_or_production_date_required' using errcode = '22023'; end if;
  if coalesce(p_harvest_date, p_production_date) > current_date then raise exception 'future_origin_date_not_allowed' using errcode = '22023'; end if;
  if p_packaging_date is not null and p_packaging_date > current_date then raise exception 'future_packaging_date_not_allowed' using errcode = '22023'; end if;
  if char_length(normalized_method) not between 2 and 500 then raise exception 'invalid_production_method' using errcode = '22023'; end if;
  if p_initial_quantity is not null and p_initial_quantity <= 0 then raise exception 'invalid_initial_quantity' using errcode = '22023'; end if;
  if p_initial_quantity is not null and normalized_unit is null then raise exception 'quantity_unit_required' using errcode = '22023'; end if;
  if normalized_unit is not null and char_length(normalized_unit) > 30 then raise exception 'invalid_quantity_unit' using errcode = '22023'; end if;
  if char_length(normalized_notes) > 1500 then raise exception 'public_notes_too_long' using errcode = '22023'; end if;

  normalized_batch_code := upper(btrim(coalesce(p_batch_code, '')));
  if normalized_batch_code = '' then normalized_batch_code := private.generate_batch_code_v1(); end if;
  if normalized_batch_code !~ '^[A-Z0-9._/-]{3,80}$' then raise exception 'invalid_batch_code' using errcode = '22023'; end if;

  if p_batch_id is null then
    insert into public.product_batches(
      trace_code, batch_code, product_id, variant_id, producer_id,
      harvest_date, production_date, packaging_date, best_before_date,
      origin_country_code, origin_province, origin_district, origin_village,
      origin_latitude, origin_longitude, production_method,
      initial_quantity, quantity_unit, public_notes, status, created_by
    ) values (
      private.generate_trace_code_v1(), normalized_batch_code, product_row.id, p_variant_id, producer_row.id,
      p_harvest_date, p_production_date, p_packaging_date, p_best_before_date,
      normalized_country, normalized_province, normalized_district, normalized_village,
      p_origin_latitude, p_origin_longitude, normalized_method,
      p_initial_quantity, normalized_unit, normalized_notes, 'draft', caller_id
    ) returning * into saved;
  else
    select batch.* into existing from public.product_batches batch where batch.id = p_batch_id for update;
    if existing.id is null then raise exception 'batch_not_found' using errcode = 'P0002'; end if;
    if existing.producer_id <> producer_row.id or existing.product_id <> product_row.id then raise exception 'batch_access_denied' using errcode = '42501'; end if;
    if existing.status not in ('draft','rejected') then raise exception 'batch_not_editable' using errcode = '55000'; end if;

    update public.product_batches batch
    set batch_code = normalized_batch_code,
        variant_id = p_variant_id,
        harvest_date = p_harvest_date,
        production_date = p_production_date,
        packaging_date = p_packaging_date,
        best_before_date = p_best_before_date,
        origin_country_code = normalized_country,
        origin_province = normalized_province,
        origin_district = normalized_district,
        origin_village = normalized_village,
        origin_latitude = p_origin_latitude,
        origin_longitude = p_origin_longitude,
        production_method = normalized_method,
        initial_quantity = p_initial_quantity,
        quantity_unit = normalized_unit,
        public_notes = normalized_notes,
        status = 'draft',
        review_reason = null,
        submitted_at = null,
        reviewed_at = null,
        reviewed_by = null
    where batch.id = existing.id
    returning * into saved;
  end if;

  return jsonb_build_object(
    'batch_id', saved.id,
    'trace_code', saved.trace_code,
    'batch_code', saved.batch_code,
    'status', saved.status
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.producer_set_product_batch_certification_v1(p_batch_id uuid, p_certification_id uuid, p_enabled boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := (select auth.uid());
  batch_row public.product_batches%rowtype;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode = '42501'; end if; if not private.has_permission('product.update') then raise exception 'permission_required:product.update' using errcode='42501'; end if;
  select batch.* into batch_row
  from public.product_batches batch
  join public.producers producer on producer.id = batch.producer_id
  where batch.id = p_batch_id and producer.owner_user_id = caller_id
  for update of batch;
  if batch_row.id is null then raise exception 'batch_not_found_or_access_denied' using errcode = '42501'; end if;
  if batch_row.status not in ('draft','rejected') then raise exception 'batch_certifications_frozen' using errcode = '55000'; end if;
  if not exists (
    select 1 from public.product_certifications certification
    where certification.id = p_certification_id
      and certification.product_id = batch_row.product_id
      and certification.status = 'valid'
      and (certification.expires_at is null or certification.expires_at >= current_date)
  ) then
    raise exception 'invalid_product_certification' using errcode = '22023';
  end if;

  if coalesce(p_enabled, true) then
    insert into public.product_batch_certifications(batch_id, certification_id, linked_by)
    values (p_batch_id, p_certification_id, caller_id)
    on conflict (batch_id, certification_id) do nothing;
  else
    delete from public.product_batch_certifications
    where batch_id = p_batch_id and certification_id = p_certification_id;
  end if;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION private.producer_submit_product_batch_v1(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := (select auth.uid());
  batch_row public.product_batches%rowtype;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode = '42501'; end if; if not private.has_permission('product.update') then raise exception 'permission_required:product.update' using errcode='42501'; end if;
  select batch.* into batch_row
  from public.product_batches batch
  join public.producers producer on producer.id = batch.producer_id
  where batch.id = p_batch_id and producer.owner_user_id = caller_id
  for update of batch;
  if batch_row.id is null then raise exception 'batch_not_found_or_access_denied' using errcode = '42501'; end if;
  if batch_row.status not in ('draft','rejected') then raise exception 'batch_not_submittable' using errcode = '55000'; end if;
  if char_length(batch_row.origin_province) < 2 or char_length(batch_row.origin_district) < 2 or char_length(batch_row.origin_village) < 2 then raise exception 'batch_origin_incomplete' using errcode = '22023'; end if;
  if batch_row.harvest_date is null and batch_row.production_date is null then raise exception 'batch_origin_date_incomplete' using errcode = '22023'; end if;
  if char_length(batch_row.production_method) < 2 then raise exception 'batch_production_method_incomplete' using errcode = '22023'; end if;

  update public.product_batches
  set status = 'review', submitted_at = timezone('utc', now()), review_reason = null
  where id = batch_row.id;

  insert into private.outbox_events(aggregate_type, aggregate_id, event_type, payload)
  values ('product_batch', batch_row.id, 'product_batch.submitted', jsonb_build_object('batch_id', batch_row.id, 'producer_id', batch_row.producer_id, 'product_id', batch_row.product_id));

  return jsonb_build_object('batch_id', batch_row.id, 'status', 'review');
end;
$function$;

CREATE OR REPLACE FUNCTION private.producer_update_inventory_v1(p_variant_id uuid, p_available_quantity integer, p_reorder_level integer, p_expected_version bigint, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  scoped_key text;
  request_hash text;
  existing_key private.idempotency_keys%rowtype;
  inserted_count integer:=0;
  producer_id_value uuid;
  product_id_value uuid;
  product_name_value text;
  variant_name_value text;
  stock_mode_value text;
  inventory_row public.product_inventory%rowtype;
  old_sellable integer;
  new_sellable integer;
  delta integer;
  response_payload jsonb;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if p_available_quantity is null or p_available_quantity not between 0 and 100000000 then raise exception 'invalid_available_quantity' using errcode='22023'; end if;
  if p_reorder_level is null or p_reorder_level not between 0 and 100000000 then raise exception 'invalid_reorder_level' using errcode='22023'; end if;
  if p_expected_version is null or p_expected_version<1 then raise exception 'invalid_inventory_version' using errcode='22023'; end if;
  if p_idempotency_key is null or char_length(p_idempotency_key) not between 8 and 160 or p_idempotency_key !~ '^[A-Za-z0-9_-]+$' then raise exception 'invalid_idempotency_key' using errcode='22023'; end if;

  scoped_key:='producer_stock:'||caller_id::text||':'||p_idempotency_key;
  request_hash:=encode(extensions.digest(convert_to(jsonb_build_object('user',caller_id,'variant',p_variant_id,'available',p_available_quantity,'reorder',p_reorder_level,'version',p_expected_version)::text,'UTF8'),'sha256'),'hex');
  select * into existing_key from private.idempotency_keys where key=scoped_key;
  if existing_key.key is not null then
    if existing_key.scope<>'producer_inventory_update' or existing_key.user_id is distinct from caller_id or existing_key.request_hash<>request_hash then raise exception 'idempotency_key_reused' using errcode='22023'; end if;
    if existing_key.completed_at is not null then return existing_key.response_body; end if;
    raise exception 'request_in_progress' using errcode='40001';
  end if;
  insert into private.idempotency_keys(key,scope,user_id,request_hash,locked_at,expires_at)
  values(scoped_key,'producer_inventory_update',caller_id,request_hash,timezone('utc',now()),timezone('utc',now())+interval '7 days')
  on conflict(key) do nothing;
  get diagnostics inserted_count=row_count;
  if inserted_count=0 then raise exception 'request_in_progress' using errcode='40001'; end if;

  select producer.id,product.id,product.name,variant.name,product.stock_mode
  into producer_id_value,product_id_value,product_name_value,variant_name_value,stock_mode_value
  from public.product_variants variant
  join public.products product on product.id=variant.product_id and product.deleted_at is null
  join public.producers producer on producer.id=product.producer_id and producer.owner_user_id=caller_id and producer.status='active' and producer.is_verified=true and producer.deleted_at is null
  where variant.id=p_variant_id and variant.is_active=true;
  if producer_id_value is null then raise exception 'variant_access_denied' using errcode='42501'; end if;
  if stock_mode_value not in ('tracked','seasonal') then raise exception 'inventory_not_used_for_stock_mode' using errcode='22023'; end if;

  select * into inventory_row from public.product_inventory where variant_id=p_variant_id for update;
  if inventory_row.variant_id is null then raise exception 'inventory_record_missing' using errcode='P0002'; end if;
  if inventory_row.version<>p_expected_version then raise exception 'inventory_version_conflict:%',inventory_row.version using errcode='40001'; end if;
  if p_available_quantity<inventory_row.reserved_quantity then raise exception 'available_quantity_below_reserved:%',inventory_row.reserved_quantity using errcode='22023'; end if;

  old_sellable:=inventory_row.available_quantity-inventory_row.reserved_quantity;
  delta:=p_available_quantity-inventory_row.available_quantity;
  update public.product_inventory
  set available_quantity=p_available_quantity,reorder_level=p_reorder_level,version=version+1,updated_at=timezone('utc',now())
  where variant_id=p_variant_id returning * into inventory_row;
  new_sellable:=inventory_row.available_quantity-inventory_row.reserved_quantity;

  if delta<>0 then
    insert into private.inventory_movements(variant_id,movement_type,quantity_delta,reference_type,reference_id,reason,idempotency_key,actor_user_id)
    values(p_variant_id,'adjustment',delta,'product',product_id_value,'Producer stock count update',scoped_key,caller_id);
  end if;
  if old_sellable>p_reorder_level and new_sellable<=p_reorder_level then
    insert into public.notifications(user_id,type,title,message,action_url,metadata)
    values(caller_id,'producer','Stok seviyesi düştü',product_name_value||' - '||variant_name_value||' için satılabilir stok '||new_sellable::text||' seviyesine düştü.','/producer/products',jsonb_build_object('productId',product_id_value,'variantId',p_variant_id,'sellableQuantity',new_sellable,'reorderLevel',p_reorder_level));
  end if;

  response_payload:=jsonb_build_object('variantId',p_variant_id,'productId',product_id_value,'availableQuantity',inventory_row.available_quantity,'reservedQuantity',inventory_row.reserved_quantity,'sellableQuantity',new_sellable,'reorderLevel',inventory_row.reorder_level,'version',inventory_row.version);
  update private.idempotency_keys set response_status=200,response_body=response_payload,completed_at=timezone('utc',now()) where key=scoped_key;
  return response_payload;
end;
$function$;

CREATE OR REPLACE FUNCTION private.producer_upsert_event_submission_v1(p_submission_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); producer public.producers%rowtype; current private.producer_event_submissions%rowtype; row private.producer_event_submissions%rowtype; title_value text; description_value text; image_value text; location_value text; details_value jsonb; starts_value timestamptz; ends_value timestamptz; capacity_value integer; deadline_value timestamptz; price_value bigint; currency_value text; commission_value integer;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if; if not private.has_permission('event.manage') then raise exception 'permission_required:event.manage' using errcode='42501'; end if;
  perform private.assert_platform_access_v1(caller_id);
  if coalesce(private.has_permission('admin.access'),false) then raise exception 'producer_portal_separate_from_admin' using errcode='42501'; end if;
  select * into producer from public.producers p where p.owner_user_id=caller_id and p.status='active' and p.is_verified=true and p.origin_verified=true and p.deleted_at is null order by p.created_at desc limit 1;
  if producer.id is null or not private.is_producer_trust_badge_active_v1(producer.id) then raise exception 'verified_active_producer_required' using errcode='42501'; end if;
  if p_payload is null or jsonb_typeof(p_payload)<>'object' then raise exception 'invalid_event_submission_payload' using errcode='22023'; end if;
  if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('title','description','imagePath','locationName','locationDetails','startsAt','endsAt','capacity','reservationDeadline','ticketPriceMinor','currency')) then raise exception 'unsupported_event_submission_field' using errcode='22023'; end if;
  if p_submission_id is not null then
    select * into current from private.producer_event_submissions s where s.id=p_submission_id and s.producer_id=producer.id for update;
    if current.id is null then raise exception 'event_submission_not_found' using errcode='P0002'; end if;
    if current.status not in ('pending','needs_changes','rejected') then raise exception 'event_submission_not_editable' using errcode='55000'; end if;
  end if;
  title_value:=btrim(coalesce(p_payload->>'title',current.title,'')); description_value:=btrim(coalesce(p_payload->>'description',current.description,'')); image_value:=nullif(btrim(coalesce(p_payload->>'imagePath',current.image_path,'')),''); location_value:=btrim(coalesce(p_payload->>'locationName',current.location_name,producer.production_location,''));
  details_value:=case when p_payload ? 'locationDetails' then p_payload->'locationDetails' else coalesce(current.location_details,'{}'::jsonb) end;
  if jsonb_typeof(details_value)<>'object' then raise exception 'invalid_event_location_details' using errcode='22023'; end if;
  if char_length(title_value) not between 2 and 180 or char_length(description_value) not between 20 and 20000 or char_length(location_value) not between 2 and 500 then raise exception 'invalid_event_submission_content' using errcode='22023'; end if;
  if image_value is not null and (image_value !~ ('^'||producer.id::text||'/events/[A-Za-z0-9._-]+$') or private.verified_public_storage_path_v1('event-public',image_value) is null) then raise exception 'stored_event_image_required' using errcode='22023'; end if;
  begin starts_value:=coalesce((p_payload->>'startsAt')::timestamptz,current.starts_at); exception when others then raise exception 'invalid_event_start' using errcode='22007'; end;
  begin ends_value:=coalesce((p_payload->>'endsAt')::timestamptz,current.ends_at); exception when others then raise exception 'invalid_event_end' using errcode='22007'; end;
  if starts_value is null or ends_value is null or ends_value<=starts_value or starts_value<=timezone('utc',now()) then raise exception 'invalid_event_date_range' using errcode='22023'; end if;
  if p_payload ? 'capacity' then if jsonb_typeof(p_payload->'capacity')='null' then capacity_value:=null; elsif jsonb_typeof(p_payload->'capacity')='number' then capacity_value:=(p_payload->>'capacity')::integer; else raise exception 'invalid_event_capacity' using errcode='22023'; end if; else capacity_value:=current.capacity; end if;
  if capacity_value is not null and capacity_value not between 1 and 1000000 then raise exception 'invalid_event_capacity' using errcode='22023'; end if;
  if p_payload ? 'reservationDeadline' then if jsonb_typeof(p_payload->'reservationDeadline')='null' or btrim(coalesce(p_payload->>'reservationDeadline',''))='' then deadline_value:=null; else begin deadline_value:=(p_payload->>'reservationDeadline')::timestamptz; exception when others then raise exception 'invalid_event_reservation_deadline' using errcode='22007'; end; end if; else deadline_value:=current.reservation_deadline; end if;
  if deadline_value is not null and deadline_value>starts_value then raise exception 'invalid_event_reservation_deadline' using errcode='22023'; end if;
  if p_payload ? 'ticketPriceMinor' then if jsonb_typeof(p_payload->'ticketPriceMinor')<>'number' then raise exception 'invalid_event_ticket_price' using errcode='22023'; end if; price_value:=(p_payload->>'ticketPriceMinor')::bigint; else price_value:=coalesce(current.ticket_price_minor,0); end if;
  if price_value<0 or price_value>100000000000 then raise exception 'invalid_event_ticket_price' using errcode='22023'; end if;
  currency_value:=upper(btrim(coalesce(p_payload->>'currency',current.currency,'TRY'))); if currency_value !~ '^[A-Z]{3}$' then raise exception 'invalid_event_currency' using errcode='22023'; end if;
  commission_value:=producer.commission_basis_points;
  if p_submission_id is null then
    insert into private.producer_event_submissions(producer_id,submitted_by,title,description,image_path,location_name,location_details,starts_at,ends_at,capacity,reservation_deadline,ticket_price_minor,currency,requested_commission_basis_points,status)
    values(producer.id,caller_id,title_value,description_value,image_value,location_value,details_value||jsonb_build_object('producerProductionLocation',producer.production_location,'producerVillage',producer.production_village,'producerDistrict',producer.production_district,'producerProvince',producer.production_province),starts_value,ends_value,capacity_value,deadline_value,price_value,currency_value,commission_value,'pending') returning * into row;
  else
    update private.producer_event_submissions set title=title_value,description=description_value,image_path=image_value,location_name=location_value,location_details=details_value||jsonb_build_object('producerProductionLocation',producer.production_location,'producerVillage',producer.production_village,'producerDistrict',producer.production_district,'producerProvince',producer.production_province),starts_at=starts_value,ends_at=ends_value,capacity=capacity_value,reservation_deadline=deadline_value,ticket_price_minor=price_value,currency=currency_value,requested_commission_basis_points=commission_value,status='pending',review_reason=null,reviewed_by=null,reviewed_at=null,updated_at=timezone('utc',now()) where id=current.id returning * into row;
  end if;
  insert into public.notifications(user_id,type,title,message,action_url,metadata) values(caller_id,'producer','Etkinlik başvurunuz incelemeye gönderildi',row.title||' etkinliği Super Admin inceleme kuyruğuna alındı. Karar verildiğinde bildirim alacaksınız.','/?tab=account',jsonb_build_object('eventSubmissionId',row.id,'status',row.status));
  return jsonb_build_object('id',row.id,'status',row.status,'ticketPriceMinor',row.ticket_price_minor,'currency',row.currency);
end;
$function$;

CREATE OR REPLACE FUNCTION private.producer_upsert_product_v1(p_reference text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  producer public.producers%rowtype;
  target public.products%rowtype;
  target_category_slug text;
  sanitized jsonb;
  result jsonb;
  was_rejected boolean:=false;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if; if not private.has_permission('product.update') then raise exception 'permission_required:product.update' using errcode='42501'; end if;
  if coalesce(private.has_permission('admin.access'),false) then raise exception 'producer_portal_separate_from_admin' using errcode='42501'; end if;
  select * into producer from public.producers p where p.owner_user_id=caller_id and p.status='active' and p.is_verified=true and p.origin_verified=true and p.deleted_at is null order by p.created_at desc limit 1;
  if producer.id is null then raise exception 'verified_active_producer_required' using errcode='42501'; end if;
  if not private.is_producer_trust_badge_active_v1(producer.id) then raise exception 'active_producer_trust_badge_required' using errcode='42501'; end if;
  if cardinality(producer.approved_category_slugs)=0 then raise exception 'producer_category_scope_required' using errcode='42501'; end if;
  if p_payload is null or jsonb_typeof(p_payload)<>'object' then raise exception 'invalid_product_payload' using errcode='22023'; end if;
  if p_payload ?| array['vendor_id','is_approved','is_rejected','verificationStatus','claimReviewStatus','section','homeSection'] then raise exception 'producer_admin_fields_not_allowed' using errcode='42501'; end if;

  if nullif(btrim(coalesce(p_reference,'')),'') is not null then
    select * into target from public.products product where (product.id::text=btrim(p_reference) or product.slug=btrim(p_reference)) and product.deleted_at is null limit 1;
    if target.id is null then raise exception 'product_not_found' using errcode='P0002'; end if;
    if target.producer_id<>producer.id then raise exception 'product_access_denied' using errcode='42501'; end if;
    was_rejected:=target.status='rejected';
  end if;

  if p_payload ? 'category' or p_payload ? 'categoryId' or target.id is null then
    select c.slug into target_category_slug from public.categories c where c.is_active=true and (c.slug=coalesce(nullif(p_payload->>'category',''),p_payload->>'categoryId') or c.id::text=coalesce(nullif(p_payload->>'categoryId',''),p_payload->>'category')) limit 1;
  else
    select c.slug into target_category_slug from public.categories c where c.id=target.category_id;
  end if;
  if target_category_slug is null or not (target_category_slug=any(producer.approved_category_slugs)) then raise exception 'product_category_outside_producer_scope' using errcode='42501'; end if;

  sanitized:=p_payload-'vendor_id'-'is_approved'-'is_rejected'-'verificationStatus'-'claimReviewStatus'-'section'-'homeSection';
  sanitized:=jsonb_set(sanitized,'{origin}',to_jsonb(producer.production_location),true);
  result:=private.management_upsert_product_v1(p_reference,sanitized);

  if was_rejected and coalesce(result->>'status','')='review' then
    update public.products set specifications=specifications-'rejectionReason',updated_at=timezone('utc',now()) where id=target.id;
    insert into private.product_moderation_events(product_id,producer_id,actor_user_id,decision,reason)
    values(target.id,producer.id,caller_id,'resubmitted','Satıcı ret gerekçesine göre ürünü düzenleyip yeniden incelemeye gönderdi.');
    insert into public.notifications(user_id,type,title,message,action_url,metadata)
    values(caller_id,'producer','Ürün yeniden incelemeye gönderildi',target.name||' için yaptığınız düzeltmeler alındı. Super Admin incelemesinden sonra size bildirim gönderilecek.','/producer/products',jsonb_build_object('productId',target.id,'status','review'));
  end if;

  return result||jsonb_build_object('producerScope','own_products_only','categoryScope',target_category_slug,'resubmitted',was_rejected and coalesce(result->>'status','')='review');
end;
$function$;

CREATE OR REPLACE FUNCTION private.producer_withdraw_product_change_v1(p_change_request_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); affected integer;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  update public.product_change_requests request
  set status='withdrawn',updated_at=timezone('utc',now())
  where request.id=p_change_request_id and request.status='pending'
    and exists(select 1 from public.producers producer where producer.id=request.producer_id and producer.owner_user_id=caller_id);
  get diagnostics affected=row_count;
  if affected=0 then raise exception 'pending_product_change_not_found' using errcode='P0002'; end if;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION private.product_certificate_document_path_in_use_v1(p_storage_path text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists(
    select 1
    from private.product_certification_documents d
    where d.storage_path=p_storage_path
  );
$function$;

CREATE OR REPLACE FUNCTION private.product_commerce_payload_v1(p_product_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare profile public.product_commerce_profiles%rowtype; window_row public.product_sales_windows%rowtype; subscriber boolean:=false; sales_state text:='year_round'; caller_id uuid:=auth.uid();
begin
  select * into profile from public.product_commerce_profiles where product_id=p_product_id; if profile.product_id is null then return null; end if;
  select * into window_row from public.product_sales_windows w where w.product_id=p_product_id and w.is_confirmed=true order by case when w.status='open' then 0 when w.preorder_opens_at>=timezone('utc',now()) then 1 else 2 end,w.preorder_opens_at nulls last,w.season_year desc limit 1;
  if caller_id is not null then select exists(select 1 from public.product_availability_subscriptions s where s.user_id=caller_id and s.product_id=p_product_id and s.active=true) into subscriber; end if;
  if window_row.id is not null and window_row.status='open' and (window_row.preorder_closes_at is null or window_row.preorder_closes_at>timezone('utc',now())) then sales_state:='preorder_open'; elsif window_row.id is not null and window_row.preorder_opens_at>timezone('utc',now()) then sales_state:='scheduled'; elsif profile.preorder_enabled then sales_state:='planning'; elsif profile.seasonality_mode='seasonal' then sales_state:='out_of_season'; elsif profile.seasonality_mode='made_to_order' then sales_state:='made_to_order'; end if;
  return jsonb_strip_nulls(jsonb_build_object('optionSchema',profile.option_schema,'seasonality',jsonb_build_object('mode',profile.seasonality_mode,'startMonth',profile.season_start_month,'endMonth',profile.season_end_month,'note',profile.customer_season_note),'preorder',jsonb_build_object('enabled',profile.preorder_enabled,'preparationDaysMin',profile.preparation_days_min,'preparationDaysMax',profile.preparation_days_max),'sales',case when window_row.id is null then jsonb_build_object('state',sales_state,'confirmed',false) else jsonb_build_object('state',sales_state,'confirmed',true,'windowId',window_row.id,'opensAt',window_row.preorder_opens_at,'closesAt',window_row.preorder_closes_at,'fulfillmentStartsAt',window_row.fulfillment_starts_at,'fulfillmentEndsAt',window_row.fulfillment_ends_at,'publicNote',window_row.public_note) end,'availabilitySubscribed',subscriber));
end;$function$;

CREATE OR REPLACE FUNCTION private.product_editorial_payload_from_published_v1(p_product_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$declare product_row public.products%rowtype; entry public.content_entries%rowtype; safety jsonb; warning_texts jsonb; payload jsonb; begin
  select * into product_row from public.products p where p.id=p_product_id and p.deleted_at is null;
  if product_row.id is null then raise exception 'product_not_found' using errcode='P0002'; end if;
  select * into entry from public.content_entries ce where ce.related_product_id=p_product_id and ce.content_type='product_health' and ce.locale='tr' and ce.status='published' and ce.deleted_at is null order by ce.updated_at desc limit 1;
  if entry.id is null then raise exception 'published_product_health_required' using errcode='55000'; end if;
  if jsonb_typeof(entry.metadata->'editorialV1')='object' then payload:=entry.metadata->'editorialV1'; else
    safety:=case when jsonb_typeof(entry.metadata->'safetyV2')='object' then entry.metadata->'safetyV2' else '{}'::jsonb end;
    select coalesce(jsonb_agg(to_jsonb(w.item->>'text')) filter(where nullif(btrim(w.item->>'text'),'') is not null),'[]'::jsonb) into warning_texts from jsonb_array_elements(case when jsonb_typeof(safety->'warnings')='array' then safety->'warnings' else '[]'::jsonb end) as w(item);
    payload:=jsonb_build_object('title',entry.title,'summary',entry.summary,'productInfo',jsonb_build_object('ingredients',coalesce(entry.metadata->'productInfoV1'->'ingredients','[]'::jsonb),'nutrition',coalesce(entry.metadata->'productInfoV1'->'nutrition','{}'::jsonb),'usageNotes',coalesce(entry.metadata->'productInfoV1'->'usageNotes','[]'::jsonb)),'safety',jsonb_build_object('storage',coalesce(safety->'storage'->'items','[]'::jsonb),'preparation',coalesce(safety->'preparation'->'items','[]'::jsonb),'warnings',warning_texts,'allergens',coalesce(safety->'allergens'->'known','[]'::jsonb),'allergenNote',coalesce(safety->'allergens'->>'text','')),'recipe',coalesce(entry.metadata->'recipeV1',jsonb_build_object('enabled',false,'ingredients','[]'::jsonb,'steps','[]'::jsonb)));
  end if;
  return private.normalize_product_editorial_payload_v1(payload);
end;$function$;

CREATE OR REPLACE FUNCTION private.product_handling_profile_v1(p_product_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  product_row public.products%rowtype;
  safety_class text;
  product_type text;
begin
  select * into product_row from public.products p where p.id=p_product_id and p.deleted_at is null;
  if product_row.id is null then return null; end if;

  select nullif(btrim(ce.metadata#>>'{safetyV2,safetyClass}'),'')
  into safety_class
  from public.content_entries ce
  where ce.related_product_id=product_row.id
    and ce.content_type='product_health'
    and ce.status='published'
    and ce.deleted_at is null
  order by ce.updated_at desc
  limit 1;

  product_type:=case
    when product_row.specifications->>'productType' in ('fish','red_meat','poultry','egg','animal_fat','dairy','produce','pantry','beverage','non_food') then product_row.specifications->>'productType'
    when safety_class in ('lamb','goat') then 'red_meat'
    when safety_class='fish' then 'fish'
    when safety_class='poultry' then 'poultry'
    when safety_class='egg' then 'egg'
    when safety_class='animal_fat' then 'animal_fat'
    when safety_class in ('raw_milk','dairy') then 'dairy'
    when safety_class in ('wild_mushroom','fresh_produce') then 'produce'
    when safety_class in ('honey','salt','dry_pantry') then 'pantry'
    when safety_class in ('water','distillate','processed_beverage') then 'beverage'
    when safety_class='non_food_safety' then 'non_food'
    else null
  end;

  return jsonb_build_object(
    'productType',product_type,
    'safetyClass',safety_class,
    'isPerishable',coalesce(product_row.is_perishable,false),
    'requiresColdChain',coalesce(product_row.requires_cold_chain,false),
    'shelfLifeDays',product_row.shelf_life_days
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.product_health_text_array_v1(p_value jsonb, p_label text, p_max_items integer, p_max_length integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare item jsonb; item_text text; result jsonb:='[]'::jsonb;
begin
 if p_value is null then return result; end if;
 if jsonb_typeof(p_value)<>'array' then raise exception 'invalid_product_health_array:%',p_label using errcode='22023'; end if;
 if jsonb_array_length(p_value)>p_max_items then raise exception 'product_health_array_too_large:%',p_label using errcode='22023'; end if;
 for item in select e from jsonb_array_elements(p_value) as t(e) loop
   if jsonb_typeof(item)<>'string' then raise exception 'invalid_product_health_array_item:%',p_label using errcode='22023'; end if;
   item_text:=btrim(item#>>'{}');
   if item_text='' or char_length(item_text)>p_max_length or item_text~'[\u0000-\u001F\u007F]' then raise exception 'invalid_product_health_array_item:%',p_label using errcode='22023'; end if;
   result:=result||jsonb_build_array(item_text);
 end loop;
 return result;
end;$function$;

CREATE OR REPLACE FUNCTION private.product_media_integrity_ok_v1(p_product_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  image_count integer:=0;
  primary_count integer:=0;
  all_valid boolean:=false;
  product_store_kind text;
begin
  if p_product_id is null then return false; end if;

  select producer.store_kind
    into product_store_kind
  from public.products product
  join public.producers producer on producer.id=product.producer_id
  where product.id=p_product_id
    and product.deleted_at is null
    and producer.deleted_at is null;

  if product_store_kind is null then return false; end if;

  select count(*)::integer,
         count(*) filter(where image.is_primary)::integer,
         coalesce(bool_and(private.verified_catalog_product_image_path_v1(image.storage_path) is not null),false)
    into image_count,primary_count,all_valid
  from public.product_images image
  where image.product_id=p_product_id;

  if image_count=0 then
    return product_store_kind='official';
  end if;

  return image_count between 1 and 10
    and primary_count=1
    and all_valid;
end;
$function$;

CREATE OR REPLACE FUNCTION private.product_price_variants_payload_v1(p_product_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',v.id,
    'sku',v.sku,
    'name',v.name,
    'priceMinor',v.price_minor,
    'compareAtPriceMinor',v.compare_at_price_minor,
    'weightGrams',v.weight_grams,
    'default',v.is_default,
    'active',v.is_active,
    'updatedAt',v.updated_at
  ) order by v.is_default desc,v.is_active desc,v.created_at,v.id),'[]'::jsonb)
  from public.product_variants v
  where v.product_id=p_product_id;
$function$;

CREATE OR REPLACE FUNCTION private.product_recommendations_core_v1(p_reference text, p_limit integer DEFAULT 12, p_include_nonpublic boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$declare ref text:=btrim(coalesce(p_reference,'')); target public.products%rowtype; target_category public.categories%rowtype; target_price bigint; target_home_section text; result jsonb; begin
  if char_length(ref) not between 1 and 200 then raise exception 'invalid_product_reference' using errcode='22023'; end if;
  if p_limit not between 1 and 24 then raise exception 'invalid_recommendation_limit' using errcode='22023'; end if;
  select p.* into target from public.products p join public.producers pr on pr.id=p.producer_id and pr.status='active' and pr.is_verified=true and pr.deleted_at is null
  where (p.id::text=ref or p.legacy_id=ref or p.slug=lower(ref)) and p.deleted_at is null and ((not p_include_nonpublic and p.status='published' and p.is_active=true) or (p_include_nonpublic and pr.store_kind='official' and p.status in ('draft','review','published'))) limit 1;
  if target.id is null then raise exception 'product_not_found' using errcode='P0002'; end if;
  select * into target_category from public.categories c where c.id=target.category_id and c.is_active=true;
  select v.price_minor into target_price from public.product_variants v where v.product_id=target.id and v.is_active=true and v.price_minor>0 order by v.is_default desc,v.created_at asc limit 1;
  target_home_section:=nullif(btrim(coalesce(target.specifications->>'homeSection','')),'');
  if target_category.id is null or target_price is null then raise exception 'product_recommendation_target_not_ready' using errcode='55000'; end if;

  with candidates as (
    select p.id,p.legacy_id,p.slug,p.name,p.short_description,p.origin,p.unit_label,p.currency,p.stock_mode,p.is_featured,p.published_at,p.status,p.is_active,
      c.id category_id,c.slug category_slug,c.name category_name,c.parent_id category_parent_id,
      pr.id producer_id,pr.display_name producer_name,pr.store_kind,pr.storefront_tier,
      v.id variant_id,v.name variant_name,v.sku,v.price_minor,v.compare_at_price_minor,
      case when p.stock_mode in ('tracked','seasonal') then greatest(0,coalesce(inv.available_quantity,0)-coalesce(inv.reserved_quantity,0)) else null end available_quantity,
      private.verified_public_storage_path_v1('catalog-public',img.storage_path) image_path,
      coalesce(rv.average_rating,0)::numeric average_rating,coalesce(rv.review_count,0)::bigint review_count,
      coalesce(fav.favorite_count,0)::bigint favorite_count,
      coalesce(sale.sales_30d,0)::bigint sales_30d,coalesce(sale.sales_all,0)::bigint sales_all,
      (p.category_id=target.category_id) same_category,
      (target_category.parent_id is not null and (c.parent_id=target_category.parent_id or c.id=target_category.parent_id or c.parent_id=target_category.id)) related_category,
      (target_home_section is not null and nullif(btrim(coalesce(p.specifications->>'homeSection','')),'')=target_home_section) same_section,
      (select count(*)::integer from unnest(coalesce(p.tags,'{}'::text[])) candidate_tag where lower(btrim(candidate_tag))=any(select lower(btrim(target_tag)) from unnest(coalesce(target.tags,'{}'::text[])) target_tag)) tag_overlap_count,
      (v.price_minor<target_price) cheaper,
      abs(v.price_minor-target_price) price_difference_minor
    from public.products p
    join public.producers pr on pr.id=p.producer_id and pr.status='active' and pr.is_verified=true and pr.deleted_at is null
    join public.categories c on c.id=p.category_id and c.is_active=true
    join lateral(select pv.* from public.product_variants pv where pv.product_id=p.id and pv.is_active=true and pv.price_minor>0 order by pv.is_default desc,pv.created_at asc limit 1) v on true
    left join public.product_inventory inv on inv.variant_id=v.id
    left join lateral(select pi.storage_path from public.product_images pi where pi.product_id=p.id order by pi.is_primary desc,pi.sort_order,pi.created_at limit 1) img on true
    left join lateral(select round(avg(r.rating)::numeric,2) average_rating,count(*)::bigint review_count from public.reviews r where r.product_id=p.id and r.status='published') rv on true
    left join lateral(select count(*)::bigint favorite_count from public.favorites f where f.product_id=p.id) fav on true
    left join lateral(select coalesce(sum(oi.quantity) filter(where coalesce(o.placed_at,o.created_at)>=timezone('utc',now())-interval '30 days'),0)::bigint sales_30d,coalesce(sum(oi.quantity),0)::bigint sales_all from public.order_items oi join public.orders o on o.id=oi.order_id where oi.product_id=p.id and o.payment_status='paid' and o.status not in ('draft','cancelled')) sale on true
    where p.id<>target.id and p.deleted_at is null and private.product_media_integrity_ok_v1(p.id)
      and ((not p_include_nonpublic and p.status='published' and p.is_active=true) or (p_include_nonpublic and pr.store_kind='official' and p.status in ('draft','review','published')))
  ), scored as (
    select *,(
      case when same_category then 64 when related_category then 34 when same_section then 22 when tag_overlap_count>0 then least(20,tag_overlap_count*8) else 0 end
      + case when target_price>0 then greatest(0,(case when same_category then 18 when related_category or same_section or tag_overlap_count>0 then 10 else 3 end)-(price_difference_minor::numeric/target_price::numeric*(case when same_category then 18 when related_category or same_section or tag_overlap_count>0 then 10 else 3 end))) else 0 end
      + case when cheaper and (same_category or related_category or same_section or tag_overlap_count>0) then 8 else 0 end
      + least(25,ln(1+sales_30d::numeric)*10)
      + least(12,ln(1+sales_all::numeric)*4)
      + least(9,ln(1+favorite_count::numeric)*3)
      + least(10,average_rating*1.5+least(review_count,10)*0.25)
      + case when is_featured then 2 else 0 end
      + case when stock_mode in ('tracked','seasonal') and coalesce(available_quantity,0)<=0 then -40 else 0 end
    )::numeric score,
    case
      when same_category and cheaper then 'same_category_better_value'
      when same_category then 'same_category'
      when sales_30d>0 and (related_category or same_section or tag_overlap_count>0) then 'popular_related'
      when same_section and cheaper then 'same_collection_better_value'
      when same_section then 'same_collection'
      when tag_overlap_count>0 then 'similar_attributes'
      when related_category then 'related_category'
      when sales_30d>0 then 'popular'
      else 'discovery'
    end reason
    from candidates
  ), page as (select * from scored order by score desc,(same_category::int) desc,(same_section::int) desc,tag_overlap_count desc,sales_30d desc,sales_all desc,favorite_count desc,average_rating desc,name,id limit p_limit)
  select jsonb_build_object('productId',target.id,'generatedAt',timezone('utc',now()),'items',coalesce(jsonb_agg(jsonb_build_object(
    'id',id,'legacyId',legacy_id,'slug',slug,'name',name,'shortDescription',short_description,'origin',origin,'unitLabel',unit_label,
    'category',jsonb_build_object('id',category_id,'slug',category_slug,'name',category_name),
    'producer',jsonb_build_object('id',producer_id,'name',producer_name,'storeKind',store_kind,'storefrontTier',storefront_tier),
    'variant',jsonb_build_object('id',variant_id,'name',variant_name,'sku',sku,'priceMinor',price_minor,'compareAtPriceMinor',compare_at_price_minor),
    'currency',currency,'stockMode',stock_mode,'availableQuantity',available_quantity,'featured',is_featured,'imagePath',image_path,
    'averageRating',average_rating,'reviewCount',review_count,'reason',reason,'score',round(score,4),
    'signals',jsonb_build_object('sameCategory',same_category,'relatedCategory',related_category,'sameCollection',same_section,'tagOverlapCount',tag_overlap_count,'cheaper',cheaper,'priceDifferenceMinor',price_difference_minor,'sales30d',sales_30d,'salesAll',sales_all,'favoriteCount',favorite_count,'reviewCount',review_count,'averageRating',average_rating)
  ) order by score desc,(same_category::int) desc,(same_section::int) desc,tag_overlap_count desc,sales_30d desc,sales_all desc,favorite_count desc,average_rating desc,name,id),'[]'::jsonb)) into result from page;
  return coalesce(result,jsonb_build_object('productId',target.id,'generatedAt',timezone('utc',now()),'items','[]'::jsonb));
end;$function$;

CREATE OR REPLACE FUNCTION private.protect_active_product_health_content_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  product_id uuid:=old.related_product_id;
  remains_valid boolean:=false;
begin
  if old.content_type<>'product_health' or old.locale<>'tr' or old.status<>'published' or old.deleted_at is not null or product_id is null then
    if tg_op='DELETE' then return old; else return new; end if;
  end if;
  if not exists(select 1 from public.products p where p.id=product_id and p.status='published' and p.deleted_at is null) then
    if tg_op='DELETE' then return old; else return new; end if;
  end if;
  if tg_op='UPDATE' then
    remains_valid:=new.related_product_id=product_id and new.content_type='product_health' and new.locale='tr' and new.status='published' and new.deleted_at is null;
  end if;
  if not remains_valid then raise exception 'published_product_health_content_cannot_be_removed' using errcode='55000'; end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.protect_last_super_admin_role_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare remaining_count integer;
declare removing boolean:=false;
begin
  if old.role<>'super_admin' then return coalesce(new,old); end if;
  if tg_op='DELETE' then removing:=true;
  elsif new.role<>'super_admin' then removing:=true;
  elsif new.expires_at is not null and new.expires_at<=timezone('utc',now()) then removing:=true;
  end if;
  if removing and auth.uid() is not null then
    select count(*) into remaining_count
    from private.user_roles ur
    join public.profiles profile on profile.id=ur.user_id
    where ur.role='super_admin'
      and ur.user_id<>old.user_id
      and (ur.expires_at is null or ur.expires_at>timezone('utc',now()))
      and profile.status='active' and profile.deleted_at is null
      and not coalesce((private.platform_access_block_v1(ur.user_id)->>'blocked')::boolean,false);
    if remaining_count=0 then raise exception 'last_super_admin_cannot_be_removed' using errcode='42501'; end if;
  end if;
  return coalesce(new,old);
end;
$function$;

CREATE OR REPLACE FUNCTION private.publish_product_editorial_v1(p_product_id uuid, p_payload jsonb, p_actor uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  normalized jsonb:=private.normalize_product_editorial_payload_v1(p_payload);
  product_row public.products%rowtype; existing public.content_entries%rowtype; entry_id uuid; existing_safety jsonb; warning_objects jsonb; metadata_value jsonb;
begin
  select * into product_row from public.products p where p.id=p_product_id and p.deleted_at is null;
  if product_row.id is null then raise exception 'product_not_found' using errcode='P0002'; end if;
  select * into existing from public.content_entries ce where ce.related_product_id=p_product_id and ce.content_type='product_health' and ce.locale='tr' and ce.deleted_at is null order by ce.updated_at desc limit 1;
  existing_safety:=case when jsonb_typeof(existing.metadata->'safetyV2')='object' then existing.metadata->'safetyV2' else '{}'::jsonb end;
  select coalesce(jsonb_agg(jsonb_build_object('code','editorial_note','severity','info','text',value)),'[]'::jsonb) into warning_objects
  from jsonb_array_elements_text(normalized->'safety'->'warnings') value;
  metadata_value:=coalesce(existing.metadata,'{}'::jsonb)||jsonb_build_object(
    'editorialV1',normalized,
    'productInfoV1',normalized->'productInfo',
    'recipeV1',normalized->'recipe',
    'safetyV2',jsonb_build_object(
      'schemaVersion',2,
      'guidanceKind',coalesce(nullif(existing_safety->>'guidanceKind',''),'food_safety'),
      'safetyClass',coalesce(nullif(existing_safety->>'safetyClass',''),'general_product'),
      'storage',jsonb_build_object('title','Saklama','items',normalized->'safety'->'storage'),
      'preparation',jsonb_build_object('title','Hazırlama / kullanım','items',normalized->'safety'->'preparation'),
      'warnings',warning_objects,
      'allergens',jsonb_build_object('known',normalized->'safety'->'allergens','verifyLabel',true,'text',normalized->'safety'->>'allergenNote'),
      'verificationNeeded',case when jsonb_typeof(existing_safety->'verificationNeeded')='array' then existing_safety->'verificationNeeded' else '[]'::jsonb end,
      'claimPolicy','Bu içerik ürün/gıda güvenliği ve kullanım bilgisidir; hastalık tanısı, tedavisi veya önlenmesi iddiası değildir.',
      'sources',case when jsonb_typeof(existing_safety->'sources')='array' then existing_safety->'sources' else '[]'::jsonb end
    )
  );
  if existing.id is null then
    insert into public.content_entries(content_type,slug,title,summary,body_markdown,body_html_sanitized,author_user_id,related_product_id,related_producer_id,status,locale,metadata,published_at)
    values('product_health','product-health-'||product_row.slug,normalized->>'title',normalized->>'summary','', '',p_actor,product_row.id,product_row.producer_id,'published','tr',metadata_value,timezone('utc',now()))
    returning id into entry_id;
  else
    update public.content_entries set title=normalized->>'title',summary=normalized->>'summary',author_user_id=p_actor,related_producer_id=product_row.producer_id,status='published',metadata=metadata_value,published_at=coalesce(existing.published_at,timezone('utc',now())),updated_at=timezone('utc',now()) where id=existing.id returning id into entry_id;
  end if;
  return entry_id;
end;
$function$;

CREATE OR REPLACE FUNCTION private.publish_storefront_v1(p_producer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.producers%rowtype; readiness jsonb; caller_id uuid:=auth.uid();
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into p from public.producers where id=p_producer_id and deleted_at is null for update;
  if p.id is null then raise exception 'producer_not_found' using errcode='P0002'; end if;
  if not private.storefront_editor_authorized_v1(p.id) then raise exception 'storefront_publish_access_required' using errcode='42501'; end if;
  if p.status not in ('pending','active') or p.is_verified<>true then raise exception 'verified_producer_required' using errcode='42501'; end if;
  readiness:=private.storefront_readiness_v1(p.id);
  if coalesce((readiness->>'ready')::boolean,false)=false then raise exception 'storefront_not_ready:%',coalesce((readiness->'missing')::text,'[]') using errcode='55000'; end if;
  update public.producers set status='active',storefront_status='published',storefront_published_at=timezone('utc',now()),storefront_published_by=caller_id,updated_at=timezone('utc',now()) where id=p.id;
  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
  values('storefront',p.id,'storefront.published',jsonb_build_object('producerId',p.id,'actorUserId',caller_id,'storeKind',p.store_kind));
  return private.get_storefront_setup_editor_v1(p.id);
end;
$function$;

CREATE OR REPLACE FUNCTION private.quarantine_invalid_published_product_media_v1()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare affected_count integer:=0; begin
  update public.products p set is_active=false where p.status='published' and p.is_active=true and p.deleted_at is null and not private.product_media_integrity_ok_v1(p.id);
  get diagnostics affected_count=row_count;
  insert into private.catalog_media_integrity_state_v2(singleton,last_scanned_at,last_quarantined_count) values(true,timezone('utc',now()),affected_count) on conflict(singleton) do update set last_scanned_at=excluded.last_scanned_at,last_quarantined_count=excluded.last_quarantined_count;
  return affected_count;
end;$function$;

CREATE OR REPLACE FUNCTION private.queue_notification_push_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if private.should_queue_push_v1(new.user_id,new.type) then
    insert into private.push_deliveries(notification_id,user_id,device_token_id)
    select new.id,new.user_id,token.id from private.device_push_tokens token
    where token.user_id=new.user_id and token.disabled_at is null
    on conflict(notification_id,device_token_id) do nothing;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.recompute_order_fulfillment_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target public.orders%rowtype;
  active_count integer:=0;
  unfulfilled_count integer:=0;
  processing_count integer:=0;
  fulfilled_count integer:=0;
  new_fulfillment text;
  new_status text;
begin
  select * into target from public.orders o where o.id=p_order_id for update;
  if target.id is null then raise exception 'order_not_found' using errcode='P0002'; end if;

  select
    count(*) filter (where oi.fulfillment_status not in ('cancelled','returned')),
    count(*) filter (where oi.fulfillment_status='unfulfilled'),
    count(*) filter (where oi.fulfillment_status='processing'),
    count(*) filter (where oi.fulfillment_status='fulfilled')
  into active_count,unfulfilled_count,processing_count,fulfilled_count
  from public.order_items oi
  where oi.order_id=target.id;

  if active_count=0 then
    new_fulfillment:=target.fulfillment_status;
  elsif unfulfilled_count=0 and processing_count=0 then
    new_fulfillment:='fulfilled';
  elsif fulfilled_count>0 then
    new_fulfillment:='partially_fulfilled';
  elsif processing_count>0 then
    new_fulfillment:='processing';
  else
    new_fulfillment:='unfulfilled';
  end if;

  new_status:=target.status;
  if target.status in ('confirmed','preparing','partially_shipped') then
    if new_fulfillment='fulfilled' then new_status:='shipped';
    elsif fulfilled_count>0 then new_status:='partially_shipped';
    elsif processing_count>0 then new_status:='preparing';
    elsif target.status='preparing' then new_status:='confirmed';
    end if;
  end if;

  update public.orders
  set fulfillment_status=new_fulfillment,status=new_status,updated_at=timezone('utc',now())
  where id=target.id;

  return jsonb_build_object(
    'orderId',target.id,
    'previousStatus',target.status,
    'status',new_status,
    'previousFulfillmentStatus',target.fulfillment_status,
    'fulfillmentStatus',new_fulfillment,
    'activeItemCount',active_count,
    'unfulfilledItemCount',unfulfilled_count,
    'processingItemCount',processing_count,
    'fulfilledItemCount',fulfilled_count
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.record_current_security_context_v1(p_user_id uuid DEFAULT auth.uid())
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ip inet:=private.current_request_ip_v1(); device uuid:=private.current_request_device_id_v1(); ua text:=private.current_request_user_agent_hash_v1(); context_id uuid;
begin
  if p_user_id is null or not exists(select 1 from public.profiles where id=p_user_id) then return; end if;
  if ip is null and device is null then return; end if;
  select id into context_id from private.user_security_contexts c
  where c.user_id=p_user_id and c.device_id is not distinct from device and c.ip_address is not distinct from ip
  order by c.last_seen_at desc limit 1;
  if context_id is null then
    insert into private.user_security_contexts(user_id,device_id,ip_address,user_agent_hash) values(p_user_id,device,ip,ua);
  else
    update private.user_security_contexts set last_seen_at=timezone('utc',now()),user_agent_hash=coalesce(ua,user_agent_hash) where id=context_id;
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION private.record_mfa_client_event_v1(p_event text, p_factor_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  uid uuid:=auth.uid();
  event_key text:=lower(btrim(coalesce(p_event,'')));
  aal text;
  recent_failures integer:=0;
  factor_status text;
begin
  if uid is null then
    raise exception 'authentication_required' using errcode='42501';
  end if;

  if not private.user_requires_staff_mfa_v1(uid) then
    raise exception 'staff_mfa_event_required' using errcode='42501';
  end if;

  if event_key not in('mfa.challenge_failed','mfa.privileged_session_established') then
    raise exception 'unsupported_mfa_event' using errcode='22023';
  end if;

  if p_factor_id is null then
    raise exception 'mfa_factor_required' using errcode='22023';
  end if;

  select f.status::text
    into factor_status
  from auth.mfa_factors f
  where f.id=p_factor_id
    and f.user_id=uid
    and f.factor_type::text='totp';

  if factor_status is null then
    raise exception 'mfa_factor_not_owned' using errcode='42501';
  end if;

  aal:=private.current_authenticator_assurance_level_v1();

  if event_key='mfa.privileged_session_established' then
    if factor_status<>'verified' or aal<>'aal2' then
      raise exception 'aal2_verified_factor_required' using errcode='42501';
    end if;
  else
    select count(*)::int
      into recent_failures
    from private.admin_audit_logs l
    where l.actor_user_id=uid
      and l.action='mfa.challenge_failed'
      and l.created_at>=timezone('utc',now())-interval '1 minute';

    if recent_failures>=30 then
      raise exception 'mfa_audit_rate_limited' using errcode='42900';
    end if;
  end if;

  insert into private.admin_audit_logs(actor_user_id,action,target_type,target_id,details)
  values(
    uid,
    event_key,
    'mfa_factor',
    p_factor_id::text,
    jsonb_build_object(
      'aal',aal,
      'factorType','totp',
      'evidenceSource',case when event_key='mfa.challenge_failed' then 'client_observed' else 'client_confirmed_after_auth_verify' end
    )
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.record_order_producer_sales_v1(p_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_order public.orders%rowtype;
  item record;
  fee_minor bigint;
  merchandise_minor bigint;
  gross_minor bigint;
  net_minor bigint;
begin
  select * into target_order from public.orders where id=p_order_id;
  if target_order.id is null or target_order.payment_status<>'paid' then return; end if;

  for item in
    select oi.id,oi.producer_id,oi.unit_price_minor,oi.quantity,oi.discount_minor,oi.tax_minor,
           oi.commission_basis_points_snapshot as commission_basis_points
    from public.order_items oi
    where oi.order_id=target_order.id and oi.producer_id is not null
    order by oi.id
  loop
    merchandise_minor:=(item.unit_price_minor*item.quantity)-item.discount_minor;
    gross_minor:=merchandise_minor+item.tax_minor;
    fee_minor:=round((merchandise_minor::numeric*item.commission_basis_points::numeric)/10000)::bigint;
    net_minor:=gross_minor-fee_minor;

    insert into private.producer_ledger_entries(
      producer_id,order_id,order_item_id,entry_type,currency,merchandise_minor,tax_minor,
      producer_gross_minor,platform_fee_minor,producer_net_minor,commission_basis_points,
      availability_status,source_key,metadata
    ) values (
      item.producer_id,target_order.id,item.id,'sale',target_order.currency,merchandise_minor,item.tax_minor,
      gross_minor,fee_minor,net_minor,item.commission_basis_points,
      case when target_order.status='completed' then 'available' else 'pending' end,
      'sale:'||item.id::text,
      jsonb_build_object('order_number',target_order.order_number,'commission_snapshot_basis_points',item.commission_basis_points)
    )
    on conflict (source_key) do nothing;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION private.record_provider_payouts_on_settlement_release_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.status='released' and (tg_op='INSERT' or old.status is distinct from 'released') then
    insert into private.producer_payouts(producer_id,currency,amount_minor,status,provider,created_by,processed_by,scheduled_at,requested_at,channel,request_source,source_order_id,destination_application_id,destination_account_holder,destination_iban_ciphertext,provider_settlement_released_at)
    select le.producer_id,o.currency,sum(le.producer_net_minor)::bigint,'processing','iyzico',new.released_by,new.released_by,coalesce(new.released_at,timezone('utc',now())),coalesce(new.requested_at,new.released_at,timezone('utc',now())),'provider_marketplace','super_admin_settlement',new.order_id,p.application_id,k.bank_account_holder,k.iban_ciphertext,coalesce(new.released_at,timezone('utc',now()))
    from private.producer_ledger_entries le join public.orders o on o.id=le.order_id join public.producers p on p.id=le.producer_id left join private.producer_application_kyc k on k.application_id=p.application_id
    where le.order_id=new.order_id and le.entry_type='sale' and le.availability_status='available'
    group by le.producer_id,o.currency,p.application_id,k.bank_account_holder,k.iban_ciphertext
    on conflict do nothing;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.record_refund_producer_reversal_v1(p_refund_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  refund_row public.refunds%rowtype;
  candidate record;
  candidate_total bigint:=0;
  target_total bigint:=0;
  allocated_total bigint:=0;
  gross_reversal bigint;
  fee_reversal bigint;
  merchandise_reversal bigint;
  tax_reversal bigint;
  net_reversal bigint;
  is_last boolean;
  candidate_count integer:=0;
  candidate_index integer:=0;
begin
  select * into refund_row from public.refunds where id=p_refund_id;
  if refund_row.id is null or refund_row.status<>'succeeded' or refund_row.return_id is null then return; end if;
  if exists(select 1 from private.producer_ledger_entries e where e.refund_id=refund_row.id and e.entry_type='refund') then return; end if;

  select coalesce(sum(round((sale.producer_gross_minor::numeric*ri.quantity::numeric)/oi.quantity::numeric)),0)::bigint,
         count(*)::integer
  into candidate_total,candidate_count
  from public.return_items ri
  join public.order_items oi on oi.id=ri.order_item_id
  join private.producer_ledger_entries sale on sale.order_item_id=oi.id and sale.entry_type='sale'
  where ri.return_id=refund_row.return_id;

  if candidate_total<=0 or candidate_count=0 then return; end if;
  target_total:=least(refund_row.amount_minor,candidate_total);

  for candidate in
    select ri.quantity as return_quantity,oi.quantity as purchased_quantity,
           sale.id as sale_entry_id,sale.producer_id,sale.order_id,sale.order_item_id,
           sale.currency,sale.merchandise_minor,sale.tax_minor,sale.producer_gross_minor,
           sale.platform_fee_minor,sale.producer_net_minor,sale.commission_basis_points
    from public.return_items ri
    join public.order_items oi on oi.id=ri.order_item_id
    join private.producer_ledger_entries sale on sale.order_item_id=oi.id and sale.entry_type='sale'
    where ri.return_id=refund_row.return_id
    order by sale.id
  loop
    candidate_index:=candidate_index+1;
    is_last:=candidate_index=candidate_count;
    if is_last then
      gross_reversal:=target_total-allocated_total;
    else
      gross_reversal:=floor(
        target_total::numeric*
        round((candidate.producer_gross_minor::numeric*candidate.return_quantity::numeric)/candidate.purchased_quantity::numeric)
        /candidate_total::numeric
      )::bigint;
      allocated_total:=allocated_total+gross_reversal;
    end if;

    if gross_reversal<=0 then continue; end if;

    merchandise_reversal:=least(
      gross_reversal,
      round((candidate.merchandise_minor::numeric*candidate.return_quantity::numeric)/candidate.purchased_quantity::numeric)::bigint
    );
    tax_reversal:=gross_reversal-merchandise_reversal;
    fee_reversal:=case when candidate.merchandise_minor=0 then 0 else
      round((merchandise_reversal::numeric*candidate.platform_fee_minor::numeric)/candidate.merchandise_minor::numeric)::bigint end;
    net_reversal:=gross_reversal-fee_reversal;

    insert into private.producer_ledger_entries(
      producer_id,order_id,order_item_id,return_id,refund_id,entry_type,currency,
      merchandise_minor,tax_minor,producer_gross_minor,platform_fee_minor,producer_net_minor,
      commission_basis_points,availability_status,available_at,source_key,metadata
    ) values (
      candidate.producer_id,candidate.order_id,candidate.order_item_id,refund_row.return_id,refund_row.id,'refund',candidate.currency,
      -merchandise_reversal,-tax_reversal,-gross_reversal,-fee_reversal,-net_reversal,
      candidate.commission_basis_points,'available',timezone('utc',now()),
      'refund:'||refund_row.id::text||':'||candidate.order_item_id::text,
      jsonb_build_object('refund_amount_minor',refund_row.amount_minor,'return_quantity',candidate.return_quantity,'purchased_quantity',candidate.purchased_quantity)
    ) on conflict (source_key) do nothing;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION private.refresh_product_search_text_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.search_text:=lower(concat_ws(' ',new.name,new.short_description,new.description,new.story,new.origin,array_to_string(new.tags,' '),new.translations::text));
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.register_push_token_v1(p_provider text, p_platform text, p_token text, p_environment text DEFAULT 'production'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid(); provider_value text:=lower(btrim(coalesce(p_provider,''))); platform_value text:=lower(btrim(coalesce(p_platform,'')));
  environment_value text:=lower(btrim(coalesce(p_environment,'production'))); token_value text:=btrim(coalesce(p_token,'')); hash_value text; token_row private.device_push_tokens%rowtype;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if provider_value not in ('fcm','apns') or platform_value not in ('android','ios') or environment_value not in ('development','production') then raise exception 'invalid_push_registration' using errcode='22023'; end if;
  if (platform_value='android' and provider_value<>'fcm') then raise exception 'android_push_requires_fcm' using errcode='22023'; end if;
  hash_value:=private.hash_push_token_v1(token_value);
  insert into private.device_push_tokens(user_id,token_hash,token_ciphertext,provider,platform,environment,last_seen_at,disabled_at,updated_at)
  values(caller_id,hash_value,extensions.pgp_sym_encrypt(token_value,private.get_push_token_key_v1(),'cipher-algo=aes256'),provider_value,platform_value,environment_value,timezone('utc',now()),null,timezone('utc',now()))
  on conflict(token_hash) do update
  set user_id=excluded.user_id,token_ciphertext=excluded.token_ciphertext,provider=excluded.provider,platform=excluded.platform,environment=excluded.environment,last_seen_at=excluded.last_seen_at,disabled_at=null,updated_at=excluded.updated_at
  returning * into token_row;
  return jsonb_build_object('id',token_row.id,'provider',token_row.provider,'platform',token_row.platform,'environment',token_row.environment,'registered',true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.register_verified_payment_method_v1(p_user_id uuid, p_provider text, p_provider_payment_method_ref text, p_brand text, p_last4 text, p_exp_month smallint DEFAULT NULL::smallint, p_exp_year smallint DEFAULT NULL::smallint, p_billing_name text DEFAULT NULL::text, p_make_default boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  method_id uuid;
  normalized_provider text := lower(btrim(coalesce(p_provider,'')));
  normalized_brand text := btrim(coalesce(p_brand,''));
begin
  if p_user_id is null or not exists(select 1 from auth.users u where u.id=p_user_id) then raise exception 'user_not_found'; end if;
  if normalized_provider !~ '^[a-z0-9_-]{2,40}$' then raise exception 'invalid_provider'; end if;
  if p_provider_payment_method_ref is null or char_length(p_provider_payment_method_ref) not between 3 and 255 or p_provider_payment_method_ref ~ '[[:cntrl:][:space:]]' then raise exception 'invalid_provider_payment_method_ref'; end if;
  if char_length(normalized_brand) not between 1 and 40 or normalized_brand ~ '[[:cntrl:]]' then raise exception 'invalid_brand'; end if;
  if p_last4 !~ '^[0-9]{4}$' then raise exception 'invalid_last4'; end if;
  if p_exp_month is not null and p_exp_month not between 1 and 12 then raise exception 'invalid_exp_month'; end if;
  if p_exp_year is not null and p_exp_year not between 2024 and 2200 then raise exception 'invalid_exp_year'; end if;
  if p_billing_name is not null and (char_length(btrim(p_billing_name)) not between 2 and 120 or p_billing_name ~ '[[:cntrl:]]') then raise exception 'invalid_billing_name'; end if;

  if coalesce(p_make_default,false) then
    update private.customer_payment_methods set is_default=false, updated_at=now() where user_id=p_user_id and is_default=true;
  end if;

  insert into private.customer_payment_methods(user_id,provider,provider_payment_method_ref,brand,last4,exp_month,exp_year,billing_name,is_default,status)
  values(p_user_id,normalized_provider,p_provider_payment_method_ref,normalized_brand,p_last4,p_exp_month,p_exp_year,nullif(btrim(coalesce(p_billing_name,'')),''),coalesce(p_make_default,false),'active')
  on conflict(user_id,provider,provider_payment_method_ref) do update set
    brand=excluded.brand,last4=excluded.last4,exp_month=excluded.exp_month,exp_year=excluded.exp_year,billing_name=excluded.billing_name,
    is_default=case when excluded.is_default then true else private.customer_payment_methods.is_default end,status='active',updated_at=now()
  returning id into method_id;
  return method_id;
end;
$function$;

CREATE OR REPLACE FUNCTION private.register_verified_payment_method_v2(p_user_id uuid, p_provider text, p_provider_payment_method_ref text, p_brand text, p_last4 text, p_exp_month smallint DEFAULT NULL::smallint, p_exp_year smallint DEFAULT NULL::smallint, p_billing_name text DEFAULT NULL::text, p_nickname text DEFAULT NULL::text, p_billing_country_code text DEFAULT NULL::text, p_billing_postal_code text DEFAULT NULL::text, p_make_default boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  method_id uuid;
  normalized_provider text:=lower(btrim(coalesce(p_provider,'')));
  normalized_brand text:=btrim(coalesce(p_brand,''));
  normalized_name text:=nullif(btrim(coalesce(p_billing_name,'')),'');
  normalized_nickname text:=nullif(btrim(coalesce(p_nickname,'')),'');
  normalized_country text:=nullif(upper(btrim(coalesce(p_billing_country_code,''))),'');
  normalized_postal text:=nullif(btrim(coalesce(p_billing_postal_code,'')),'');
begin
  if p_user_id is null or not exists(select 1 from auth.users u where u.id=p_user_id) then raise exception 'user_not_found'; end if;
  if normalized_provider !~ '^[a-z0-9_-]{2,40}$' then raise exception 'invalid_provider'; end if;
  if p_provider_payment_method_ref is null or char_length(p_provider_payment_method_ref) not between 3 and 255 or p_provider_payment_method_ref ~ '[[:cntrl:][:space:]]' then raise exception 'invalid_provider_payment_method_ref'; end if;
  if char_length(normalized_brand) not between 1 and 40 or normalized_brand ~ '[[:cntrl:]]' then raise exception 'invalid_brand'; end if;
  if p_last4 !~ '^[0-9]{4}$' then raise exception 'invalid_last4'; end if;
  if p_exp_month is not null and p_exp_month not between 1 and 12 then raise exception 'invalid_exp_month'; end if;
  if p_exp_year is not null and p_exp_year not between 2024 and 2200 then raise exception 'invalid_exp_year'; end if;
  if normalized_name is not null and (char_length(normalized_name)>120 or normalized_name ~ '[[:cntrl:]]') then raise exception 'invalid_billing_name'; end if;
  if normalized_nickname is not null and (char_length(normalized_nickname)>40 or normalized_nickname ~ '[[:cntrl:]]') then raise exception 'invalid_payment_method_nickname'; end if;
  if normalized_country is not null and normalized_country !~ '^[A-Z]{2}$' then raise exception 'invalid_billing_country'; end if;
  if normalized_postal is not null and (char_length(normalized_postal)>30 or normalized_postal ~ '[[:cntrl:]]') then raise exception 'invalid_billing_postal_code'; end if;

  if coalesce(p_make_default,false) then
    update private.customer_payment_methods set is_default=false,updated_at=timezone('utc',now()) where user_id=p_user_id and is_default=true;
  end if;

  insert into private.customer_payment_methods(
    user_id,provider,provider_payment_method_ref,brand,last4,exp_month,exp_year,billing_name,nickname,billing_country_code,billing_postal_code,is_default,status
  ) values (
    p_user_id,normalized_provider,p_provider_payment_method_ref,normalized_brand,p_last4,p_exp_month,p_exp_year,normalized_name,normalized_nickname,normalized_country,normalized_postal,coalesce(p_make_default,false),'active'
  )
  on conflict(user_id,provider,provider_payment_method_ref) do update set
    brand=excluded.brand,last4=excluded.last4,exp_month=excluded.exp_month,exp_year=excluded.exp_year,
    billing_name=excluded.billing_name,nickname=coalesce(excluded.nickname,private.customer_payment_methods.nickname),
    billing_country_code=excluded.billing_country_code,billing_postal_code=excluded.billing_postal_code,
    is_default=case when excluded.is_default then true else private.customer_payment_methods.is_default end,
    status='active',updated_at=timezone('utc',now())
  returning id into method_id;
  return method_id;
end;
$function$;

CREATE OR REPLACE FUNCTION private.release_completed_order_settlements_v1(p_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare o public.orders%rowtype; begin select * into o from public.orders where id=p_order_id for update; if o.id is null then raise exception 'order_not_found' using errcode='P0002'; end if; if o.status<>'completed' then raise exception 'settlement_order_not_completed' using errcode='55000'; end if; if o.payment_status<>'paid' then raise exception 'settlement_payment_not_paid' using errcode='55000'; end if; if exists(select 1 from public.return_requests r where r.order_id=o.id and r.status in('requested','under_review','approved','in_transit','received')) then raise exception 'settlement_open_return' using errcode='55000'; end if; if exists(select 1 from public.refunds rf where rf.order_id=o.id and rf.status not in('failed','cancelled')) then raise exception 'settlement_refund_block' using errcode='55000'; end if; if exists(select 1 from private.producer_ledger_entries le where le.order_id=o.id and le.entry_type='sale' and le.availability_status='pending' and not exists(select 1 from private.payment_item_splits ps where ps.order_id=o.id and ps.order_item_id=le.order_item_id and ps.approval_status='approved')) then raise exception 'settlement_split_not_approved' using errcode='55000'; end if; update private.producer_ledger_entries set availability_status='available',available_at=coalesce(available_at,timezone('utc',now())) where order_id=o.id and entry_type='sale' and availability_status='pending'; end;$function$;

CREATE OR REPLACE FUNCTION private.release_expired_order_reservations(p_limit integer DEFAULT 100)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_order record;
  released_count integer := 0;
begin
  if p_limit is null or p_limit not between 1 and 1000 then
    raise exception 'invalid_release_limit' using errcode = '22023';
  end if;

  for target_order in
    select customer_order.id, customer_order.status
    from public.orders customer_order
    where customer_order.status = 'pending_payment'
      and customer_order.payment_status = 'unpaid'
      and customer_order.reservation_expires_at <= timezone('utc', now())
    order by customer_order.reservation_expires_at, customer_order.id
    for update skip locked
    limit p_limit
  loop
    perform private.release_order_inventory(target_order.id);

    update public.orders
    set status = 'cancelled',
        cancelled_at = timezone('utc', now()),
        reservation_expires_at = null,
        updated_at = timezone('utc', now())
    where id = target_order.id;

    insert into public.order_status_history(
      order_id,
      from_status,
      to_status,
      note,
      visible_to_customer
    ) values (
      target_order.id,
      target_order.status,
      'cancelled',
      'Ödeme süresi dolduğu için stok rezervasyonu otomatik bırakıldı.',
      true
    );

    insert into private.outbox_events(
      aggregate_type,
      aggregate_id,
      event_type,
      payload
    ) values (
      'order',
      target_order.id,
      'order.reservation_expired',
      jsonb_build_object('order_id', target_order.id)
    );

    released_count := released_count + 1;
  end loop;

  return released_count;
end;
$function$;

CREATE OR REPLACE FUNCTION private.release_order_inventory(p_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  reservation record;
  movement_id bigint;
begin
  for reservation in
    select
      item.variant_id,
      sum(item.quantity)::integer as quantity
    from public.order_items item
    join public.products product on product.id = item.product_id
    where item.order_id = p_order_id
      and item.variant_id is not null
      and product.stock_mode in ('tracked', 'seasonal')
    group by item.variant_id
    order by item.variant_id
  loop
    movement_id := null;

    insert into private.inventory_movements(
      variant_id,
      movement_type,
      quantity_delta,
      reference_type,
      reference_id,
      reason,
      idempotency_key,
      actor_user_id
    ) values (
      reservation.variant_id,
      'release',
      reservation.quantity,
      'order',
      p_order_id,
      'Unpaid order stock reservation released',
      'order:' || p_order_id::text || ':release:' || reservation.variant_id::text,
      (select auth.uid())
    )
    on conflict (idempotency_key) do nothing
    returning id into movement_id;

    if movement_id is not null then
      update public.product_inventory inventory
      set reserved_quantity = greatest(0, inventory.reserved_quantity - reservation.quantity),
          version = inventory.version + 1,
          updated_at = timezone('utc', now())
      where inventory.variant_id = reservation.variant_id;
    end if;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION private.release_order_promotion_v1(p_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  update private.promotion_redemptions redemption
  set status='released',
      released_at=coalesce(released_at,timezone('utc',now())),
      updated_at=timezone('utc',now())
  where redemption.order_id=p_order_id
    and redemption.status='reserved';
end;
$function$;

CREATE OR REPLACE FUNCTION private.remove_my_cart_item_v1(p_cart_item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); cart_id_value uuid; affected integer;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select cart.id into cart_id_value from public.carts cart join public.cart_items item on item.cart_id=cart.id where item.id=p_cart_item_id and cart.user_id=caller_id and cart.status='active' for update of cart;
  if cart_id_value is null then raise exception 'cart_item_not_found' using errcode='P0002'; end if;
  delete from public.cart_items where id=p_cart_item_id and cart_id=cart_id_value;
  update public.carts set expires_at=timezone('utc',now())+interval '30 days',updated_at=timezone('utc',now()) where id=cart_id_value;
  return private.get_customer_cart_snapshot_v1(caller_id);
end;
$function$;

CREATE OR REPLACE FUNCTION private.remove_my_payment_method_impl_v2(p_payment_method_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  uid uuid:=auth.uid();
  target private.customer_payment_methods%rowtype;
  replacement_id uuid;
begin
  if uid is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if p_payment_method_id is null then raise exception 'payment_method_required' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended(uid::text,86112));
  select * into target
  from private.customer_payment_methods p
  where p.id=p_payment_method_id and p.user_id=uid and p.status in ('active','expired')
  for update;
  if target.id is null then raise exception 'payment_method_not_found' using errcode='P0002'; end if;
  update private.customer_payment_methods
  set status='removed',is_default=false,updated_at=timezone('utc',now())
  where id=target.id;
  if target.is_default then
    select p.id into replacement_id
    from private.customer_payment_methods p
    where p.user_id=uid and p.status='active' and p.id<>target.id
    order by p.created_at desc,p.id
    limit 1
    for update;
    if replacement_id is not null then
      update private.customer_payment_methods
      set is_default=true,updated_at=timezone('utc',now())
      where id=replacement_id;
    end if;
  end if;
  return jsonb_build_object('ok',true,'removedId',target.id,'newDefaultId',replacement_id);
end;
$function$;

CREATE OR REPLACE FUNCTION private.report_client_error_v1(p_source text, p_message text, p_stack text DEFAULT NULL::text, p_route text DEFAULT NULL::text, p_severity text DEFAULT 'error'::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare source_value text:=btrim(coalesce(p_source,'')); message_value text:=btrim(coalesce(p_message,'')); stack_value text:=left(nullif(btrim(coalesce(p_stack,'')),''),12000); route_value text:=left(nullif(btrim(coalesce(p_route,'')),''),500); severity_value text:=lower(btrim(coalesce(p_severity,'error'))); metadata_value jsonb:=coalesce(p_metadata,'{}'::jsonb); fingerprint_value text;
begin
 if char_length(source_value) not between 2 and 80 or char_length(message_value) not between 1 and 2000 then return false; end if;
 if severity_value not in('warning','error','fatal') then severity_value:='error'; end if;
 if jsonb_typeof(metadata_value)<>'object' or length(metadata_value::text)>16000 then metadata_value:='{}'::jsonb; end if;
 fingerprint_value:=md5(source_value||'|'||message_value||'|'||coalesce(left(stack_value,2000),''));
 insert into private.system_error_daily(event_day,fingerprint,severity,source,message,sample_stack,route,last_user_id,metadata)
 values(timezone('utc',now())::date,fingerprint_value,severity_value,source_value,message_value,stack_value,route_value,auth.uid(),metadata_value)
 on conflict(event_day,fingerprint) do update set occurrence_count=private.system_error_daily.occurrence_count+1,last_seen_at=timezone('utc',now()),last_user_id=auth.uid(),route=coalesce(excluded.route,private.system_error_daily.route),metadata=excluded.metadata;
 return true;
end;
$function$;

CREATE OR REPLACE FUNCTION private.report_conversation_v1(p_conversation_id uuid, p_reason text, p_details text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); target_user uuid; reason_value text:=lower(btrim(coalesce(p_reason,''))); details_value text:=nullif(btrim(coalesce(p_details,'')),''); report_row private.user_content_reports%rowtype;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if reason_value not in ('harassment','hate','sexual','violence','spam','fraud','privacy','illegal','other') then raise exception 'invalid_report_reason' using errcode='22023'; end if;
  if details_value is not null and char_length(details_value)>1000 then raise exception 'report_details_too_long' using errcode='22023'; end if;
  if not exists(select 1 from public.conversation_participants p where p.conversation_id=p_conversation_id and p.user_id=caller_id) then raise exception 'conversation_access_denied' using errcode='42501'; end if;
  select p.user_id into target_user from public.conversation_participants p where p.conversation_id=p_conversation_id and p.user_id<>caller_id and p.participant_role in ('customer','producer') order by case p.participant_role when 'producer' then 0 else 1 end,p.joined_at asc limit 1;
  if (select count(*) from private.user_content_reports where reporter_user_id=caller_id and created_at>timezone('utc',now())-interval '1 hour')>=20 then raise exception 'content_report_rate_limit' using errcode='P0001'; end if;
  insert into private.user_content_reports(reporter_user_id,reported_user_id,target_type,target_id,reason,details)
  values(caller_id,target_user,'conversation',p_conversation_id,reason_value,details_value)
  on conflict(reporter_user_id,target_type,target_id) where status in ('new','reviewing')
  do update set reason=excluded.reason,details=excluded.details,updated_at=timezone('utc',now())
  returning * into report_row;
  return jsonb_build_object('id',report_row.id,'status',report_row.status,'targetType',report_row.target_type,'targetId',report_row.target_id,'createdAt',report_row.created_at);
end;
$function$;

CREATE OR REPLACE FUNCTION private.report_published_review_v1(p_review_id uuid, p_reason text, p_details text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); target_user uuid; reason_value text:=lower(btrim(coalesce(p_reason,''))); details_value text:=nullif(btrim(coalesce(p_details,'')),''); report_row private.user_content_reports%rowtype;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if reason_value not in ('harassment','hate','sexual','violence','spam','fraud','privacy','illegal','other') then raise exception 'invalid_report_reason' using errcode='22023'; end if;
  if details_value is not null and char_length(details_value)>1000 then raise exception 'report_details_too_long' using errcode='22023'; end if;
  select user_id into target_user from public.reviews where id=p_review_id and status='published';
  if target_user is null then raise exception 'published_review_not_found' using errcode='P0002'; end if;
  if target_user=caller_id then raise exception 'cannot_report_self' using errcode='22023'; end if;
  if (select count(*) from private.user_content_reports where reporter_user_id=caller_id and created_at>timezone('utc',now())-interval '1 hour')>=20 then raise exception 'content_report_rate_limit' using errcode='P0001'; end if;
  insert into private.user_content_reports(reporter_user_id,reported_user_id,target_type,target_id,reason,details)
  values(caller_id,target_user,'review',p_review_id,reason_value,details_value)
  on conflict(reporter_user_id,target_type,target_id) where status in ('new','reviewing')
  do update set reason=excluded.reason,details=excluded.details,updated_at=timezone('utc',now())
  returning * into report_row;
  return jsonb_build_object('id',report_row.id,'status',report_row.status,'targetType',report_row.target_type,'targetId',report_row.target_id,'createdAt',report_row.created_at);
end;
$function$;

CREATE OR REPLACE FUNCTION private.request_account_closure_v1(p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  reason_value text:=nullif(btrim(coalesce(p_reason,'')),'');
  request_row private.account_closure_requests%rowtype;
  active_order_count bigint;
  active_return_count bigint;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if reason_value is not null and char_length(reason_value)>2000 then raise exception 'account_closure_reason_too_long' using errcode='22023'; end if;
  if not exists(select 1 from public.profiles where id=caller_id and status='active' and deleted_at is null) then raise exception 'active_profile_required' using errcode='42501'; end if;
  if exists(select 1 from public.producers where owner_user_id=caller_id and deleted_at is null and status='active') then
    raise exception 'producer_account_requires_transfer_or_suspension' using errcode='55000';
  end if;

  select count(*) into active_order_count from public.orders
  where user_id=caller_id and status not in ('completed','cancelled','refunded');
  select count(*) into active_return_count from public.return_requests
  where user_id=caller_id and status not in ('rejected','refunded','closed');
  if active_order_count>0 or active_return_count>0 then
    raise exception 'account_closure_has_active_transactions:%:%',active_order_count,active_return_count using errcode='55000';
  end if;

  select * into request_row from private.account_closure_requests
  where user_id=caller_id and status in ('requested','processing','ready_for_auth_deletion')
  order by requested_at desc limit 1;
  if request_row.id is not null then
    return jsonb_build_object('id',request_row.id,'status',request_row.status,'requestedAt',request_row.requested_at,'unchanged',true);
  end if;

  insert into private.account_closure_requests(user_id,status,reason)
  values(caller_id,'requested',reason_value)
  returning * into request_row;

  update private.device_push_tokens set disabled_at=timezone('utc',now()),updated_at=timezone('utc',now())
  where user_id=caller_id and disabled_at is null;
  update private.user_notification_preferences
  set push_enabled=false,campaign_push=false,updated_at=timezone('utc',now())
  where user_id=caller_id;

  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
  values('account_closure',request_row.id,'account_closure.requested',jsonb_build_object('request_id',request_row.id,'user_id',caller_id));

  return jsonb_build_object('id',request_row.id,'status',request_row.status,'requestedAt',request_row.requested_at,'activeOrders',active_order_count,'activeReturns',active_return_count);
end;
$function$;

CREATE OR REPLACE FUNCTION private.request_customer_return_v1(p_order_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  normalized_reason text := btrim(coalesce(p_reason, ''));
  target_order public.orders%rowtype;
  v_return_id uuid;
  v_return_number text;
begin
  if caller_id is null then
    raise exception 'authentication_required' using errcode = '42501';
  end if;
  if char_length(normalized_reason) not between 10 and 3000 then
    raise exception 'return_reason_required' using errcode = '22023';
  end if;

  select * into target_order
  from public.orders customer_order
  where customer_order.id = p_order_id
    and customer_order.user_id = caller_id
  for update;
  if not found then raise exception 'order_not_found' using errcode = 'P0002'; end if;
  if target_order.status not in ('delivered', 'completed') then
    raise exception 'order_not_returnable' using errcode = '22023';
  end if;
  if exists (
    select 1 from public.return_requests request
    where request.order_id = target_order.id
      and request.status in ('requested', 'under_review', 'approved', 'in_transit', 'received')
  ) then
    raise exception 'active_return_already_exists' using errcode = '23505';
  end if;

  v_return_id := gen_random_uuid();
  v_return_number := 'RET-' || to_char(timezone('utc', now()), 'YYYY') || '-' || upper(substr(replace(v_return_id::text, '-', ''), 1, 10));
  insert into public.return_requests(
    id, return_number, order_id, user_id, reason_code, customer_message, status
  ) values (
    v_return_id, v_return_number, target_order.id, caller_id, 'other', normalized_reason, 'requested'
  );

  insert into public.return_items(return_id, order_item_id, quantity)
  select v_return_id, item.id, item.quantity
  from public.order_items item
  where item.order_id = target_order.id;

  insert into public.notifications(user_id, type, title, message, action_url, metadata)
  select role.user_id,
    'return',
    'Yeni iade talebi',
    target_order.order_number || ' numaralı sipariş için iade talebi açıldı.',
    '/admin/returns',
    jsonb_build_object('orderId', target_order.id, 'returnId', v_return_id, 'returnNumber', v_return_number)
  from private.user_roles role
  join public.profiles profile on profile.id = role.user_id and profile.status = 'active'
  where role.role in ('admin', 'super_admin')
    and (role.expires_at is null or role.expires_at > timezone('utc', now()));

  insert into private.outbox_events(aggregate_type, aggregate_id, event_type, payload)
  values (
    'return_request', v_return_id, 'return.requested',
    jsonb_build_object('return_id', v_return_id, 'order_id', target_order.id, 'user_id', caller_id)
  );

  return jsonb_build_object(
    'id', v_return_id,
    'returnNumber', v_return_number,
    'orderId', target_order.id,
    'status', 'requested'
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.request_customer_return_v2(p_order_id uuid, p_items jsonb, p_reason_code text, p_message text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  target_order public.orders%rowtype;
  normalized_reason text:=lower(btrim(coalesce(p_reason_code,'')));
  normalized_message text:=btrim(coalesce(p_message,''));
  item jsonb;
  order_item_id uuid;
  requested_quantity integer;
  target_item public.order_items%rowtype;
  already_returned integer;
  return_id uuid:=gen_random_uuid();
  return_number text;
  seen_ids uuid[]:='{}'::uuid[];
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if normalized_reason not in ('damaged','wrong_item','quality_issue','missing_item','changed_mind','delivery_issue','other') then raise exception 'invalid_return_reason' using errcode='22023'; end if;
  if char_length(normalized_message) not between 10 and 3000 then raise exception 'return_message_required' using errcode='22023'; end if;
  if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items) not between 1 and 50 then raise exception 'return_items_required' using errcode='22023'; end if;

  select * into target_order from public.orders customer_order
  where customer_order.id=p_order_id and customer_order.user_id=caller_id
  for update;
  if target_order.id is null then raise exception 'order_not_found' using errcode='P0002'; end if;
  if target_order.status not in ('delivered','completed') then raise exception 'order_not_returnable' using errcode='22023'; end if;
  if exists(select 1 from public.return_requests request where request.order_id=target_order.id and request.status in ('requested','under_review','approved','in_transit','received')) then raise exception 'active_return_already_exists' using errcode='23505'; end if;

  return_number:='RET-'||to_char(timezone('utc',now()),'YYYY')||'-'||upper(substr(replace(return_id::text,'-',''),1,10));
  insert into public.return_requests(id,return_number,order_id,user_id,reason_code,customer_message,status)
  values(return_id,return_number,target_order.id,caller_id,normalized_reason,normalized_message,'requested');

  for item in select value from jsonb_array_elements(p_items)
  loop
    if jsonb_typeof(item)<>'object' or coalesce(item->>'orderItemId','') !~ '^[0-9a-fA-F-]{36}$' or coalesce(item->>'quantity','') !~ '^[0-9]{1,3}$' then raise exception 'invalid_return_item' using errcode='22023'; end if;
    order_item_id:=(item->>'orderItemId')::uuid;
    requested_quantity:=(item->>'quantity')::integer;
    if requested_quantity<=0 then raise exception 'invalid_return_quantity' using errcode='22023'; end if;
    if order_item_id=any(seen_ids) then raise exception 'duplicate_return_item' using errcode='22023'; end if;
    seen_ids:=array_append(seen_ids,order_item_id);

    select * into target_item from public.order_items order_item
    where order_item.id=order_item_id and order_item.order_id=target_order.id;
    if target_item.id is null then raise exception 'return_item_not_in_order' using errcode='22023'; end if;

    select coalesce(sum(returned_item.quantity),0)::integer into already_returned
    from public.return_items returned_item
    join public.return_requests request on request.id=returned_item.return_id
    where returned_item.order_item_id=target_item.id and request.status not in ('rejected');

    if requested_quantity+already_returned>target_item.quantity then raise exception 'return_quantity_exceeds_purchased' using errcode='22023'; end if;

    insert into public.return_items(return_id,order_item_id,quantity)
    values(return_id,target_item.id,requested_quantity);
  end loop;

  insert into public.notifications(user_id,type,title,message,action_url,metadata)
  select role.user_id,'return','Yeni iade talebi',target_order.order_number||' numaralı sipariş için ürün bazlı iade talebi açıldı.','/admin/returns',jsonb_build_object('orderId',target_order.id,'returnId',return_id,'returnNumber',return_number)
  from private.user_roles role
  join public.profiles profile on profile.id=role.user_id and profile.status='active'
  where role.role in ('admin','super_admin') and (role.expires_at is null or role.expires_at>timezone('utc',now()));

  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
  values('return_request',return_id,'return.requested',jsonb_build_object('return_id',return_id,'order_id',target_order.id,'user_id',caller_id,'reason_code',normalized_reason));

  return jsonb_build_object('id',return_id,'returnNumber',return_number,'orderId',target_order.id,'status','requested');
end;
$function$;

CREATE OR REPLACE FUNCTION private.request_customer_return_v3(p_order_id uuid, p_items jsonb, p_reason_code text, p_message text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  base_result jsonb;
  return_id uuid;
  item jsonb;
  order_item_id uuid;
  evidence jsonb;
  evidence_path text;
  evidence_paths text[];
  evidence_count integer := 0;
begin
  if caller_id is null then
    raise exception 'authentication_required' using errcode='42501';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) not between 1 and 50 then
    raise exception 'return_items_required' using errcode='22023';
  end if;

  for item in select value from jsonb_array_elements(p_items)
  loop
    if jsonb_typeof(item) <> 'object' then
      raise exception 'invalid_return_item' using errcode='22023';
    end if;

    if item ? 'evidencePaths' then
      if jsonb_typeof(item->'evidencePaths') <> 'array' or jsonb_array_length(item->'evidencePaths') > 5 then
        raise exception 'invalid_return_evidence' using errcode='22023';
      end if;
      evidence_count := evidence_count + jsonb_array_length(item->'evidencePaths');
    end if;
  end loop;

  if evidence_count > 15 then
    raise exception 'too_many_return_evidence_files' using errcode='22023';
  end if;

  base_result := private.request_customer_return_v2(p_order_id, p_items, p_reason_code, p_message);
  return_id := (base_result->>'id')::uuid;

  for item in select value from jsonb_array_elements(p_items)
  loop
    order_item_id := (item->>'orderItemId')::uuid;
    evidence_paths := array[]::text[];

    if item ? 'evidencePaths' then
      for evidence in select value from jsonb_array_elements(item->'evidencePaths')
      loop
        if jsonb_typeof(evidence) <> 'string' then
          raise exception 'invalid_return_evidence_path' using errcode='22023';
        end if;

        evidence_path := btrim(evidence #>> '{}');
        if evidence_path = '' or split_part(evidence_path, '/', 1) <> caller_id::text then
          raise exception 'invalid_return_evidence_path' using errcode='22023';
        end if;

        if not exists (
          select 1
          from storage.objects object
          where object.bucket_id = 'return-evidence'
            and object.name = evidence_path
            and object.owner_id = caller_id::text
        ) then
          raise exception 'return_evidence_not_found' using errcode='P0002';
        end if;

        if exists (
          select 1
          from public.return_items existing_item
          where evidence_path = any(existing_item.evidence_paths)
        ) then
          raise exception 'return_evidence_already_used' using errcode='23505';
        end if;

        if evidence_path = any(evidence_paths) then
          raise exception 'duplicate_return_evidence' using errcode='22023';
        end if;

        evidence_paths := array_append(evidence_paths, evidence_path);
      end loop;
    end if;

    update public.return_items return_item
    set evidence_paths = evidence_paths
    where return_item.return_id = return_id
      and return_item.order_item_id = order_item_id;
  end loop;

  return base_result || jsonb_build_object('evidenceCount', evidence_count);
end;
$function$;

CREATE OR REPLACE FUNCTION private.request_my_producer_payout_v2(p_currency text, p_amount_minor bigint, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); p public.producers%rowtype; currency_code text:=upper(btrim(coalesce(p_currency,''))); balance jsonb; available bigint; destination jsonb; row private.producer_payouts%rowtype; admin_user uuid;
begin
  if uid is null then raise exception 'authentication_required' using errcode='42501'; end if; if not private.has_permission('payout.request') then raise exception 'permission_required:payout.request' using errcode='42501'; end if;
  if currency_code !~ '^[A-Z]{3}$' or p_amount_minor is null or p_amount_minor<=0 then raise exception 'invalid_payout_request' using errcode='22023'; end if;
  if char_length(coalesce(p_note,''))>1000 then raise exception 'payout_note_too_long' using errcode='22023'; end if;
  select * into p from public.producers where owner_user_id=uid and deleted_at is null order by created_at desc limit 1 for update;
  if p.id is null then raise exception 'producer_profile_required' using errcode='42501'; end if;
  if p.status<>'active' or not p.is_verified then raise exception 'active_verified_producer_required' using errcode='55000'; end if;
  balance:=private.get_producer_balance_v1(p.id,currency_code); available:=(balance->>'availableToPayoutMinor')::bigint;
  if p_amount_minor>available then raise exception 'payout_exceeds_available_balance' using errcode='22023'; end if;
  destination:=private.get_producer_bank_destination_v1(p.id);
  insert into private.producer_payouts(producer_id,currency,amount_minor,status,provider,note,created_by,scheduled_at,requested_at,channel,request_source,destination_application_id,destination_account_holder,destination_iban_ciphertext,destination_iban_masked)
  values(p.id,currency_code,p_amount_minor,'requested','bank_transfer',nullif(btrim(coalesce(p_note,'')),''),uid,timezone('utc',now()),timezone('utc',now()),'manual_bank_transfer','producer',(destination->>'applicationId')::uuid,destination->>'accountHolder',destination->>'ibanCiphertext',destination->>'ibanMasked') returning * into row;
  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload) values('producer_payout',row.id,'producer_payout.requested',jsonb_build_object('payout_id',row.id,'producer_id',p.id,'currency',currency_code,'amount_minor',p_amount_minor,'actor_user_id',uid,'channel','manual_bank_transfer'));
  for admin_user in select distinct ur.user_id from private.user_roles ur join public.profiles pr on pr.id=ur.user_id where (ur.expires_at is null or ur.expires_at>timezone('utc',now())) and pr.status='active' and pr.deleted_at is null and private.user_has_permission_v1(ur.user_id,'payout.review') loop
    insert into public.notifications(user_id,type,title,message,action_url,metadata) values(admin_user,'producer','Yeni satıcı çekim talebi',p.display_name||' için banka transferi bekleyen çekim talebi var.','/?tab=admin&adminView=producer-payouts',jsonb_build_object('payoutId',row.id,'producerId',p.id,'amountMinor',p_amount_minor,'currency',currency_code));
  end loop;
  return jsonb_build_object('id',row.id,'producerId',p.id,'currency',currency_code,'amountMinor',p_amount_minor,'status','requested','channel','manual_bank_transfer','destinationIbanMasked',row.destination_iban_masked,'destinationAccountHolder',row.destination_account_holder,'requestedAt',row.requested_at);
end;
$function$;

CREATE OR REPLACE FUNCTION private.request_producer_location_change_v1(p_country_code text, p_province text, p_district text, p_village text, p_village_is_custom boolean, p_latitude numeric, p_longitude numeric, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid(); producer public.producers%rowtype; request_id uuid;
  cc text:=upper(btrim(coalesce(p_country_code,'TR')));
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into producer from public.producers where owner_user_id=caller_id and deleted_at is null order by created_at desc limit 1;
  if producer.id is null or producer.status not in ('active','suspended') then raise exception 'producer_profile_not_editable' using errcode='42501'; end if;
  if cc !~ '^[A-Z]{2}$' or char_length(btrim(coalesce(p_province,''))) not between 2 and 100 or char_length(btrim(coalesce(p_district,''))) not between 2 and 100 or char_length(btrim(coalesce(p_village,''))) not between 2 and 160 then raise exception 'invalid_location' using errcode='22023'; end if;
  if (p_latitude is null) <> (p_longitude is null) or (p_latitude is not null and p_latitude not between -90 and 90) or (p_longitude is not null and p_longitude not between -180 and 180) then raise exception 'invalid_coordinates' using errcode='22023'; end if;
  if char_length(btrim(coalesce(p_reason,''))) not between 20 and 2000 then raise exception 'location_change_reason_required' using errcode='22023'; end if;
  if exists(select 1 from public.producer_location_change_requests r where r.producer_id=producer.id and r.status='pending') then raise exception 'location_change_request_already_pending' using errcode='55000'; end if;

  insert into public.producer_location_change_requests(producer_id,requested_by,country_code,province,district,village,village_is_custom,latitude,longitude,reason)
  values(producer.id,caller_id,cc,btrim(p_province),btrim(p_district),btrim(p_village),coalesce(p_village_is_custom,false),p_latitude,p_longitude,btrim(p_reason))
  returning id into request_id;
  return jsonb_build_object('request_id',request_id,'status','pending');
end; $function$;

CREATE OR REPLACE FUNCTION private.require_current_terms_v1()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid();
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if not exists(select 1 from private.user_terms_acceptances a where a.user_id=caller_id and a.terms_version='2026-08-22-store-v1') then
    raise exception 'terms_acceptance_required' using errcode='42501';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION private.require_permission(p_permission_key text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_permission_key is null or p_permission_key !~ '^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$' then
    raise exception 'invalid_permission_key' using errcode='22023';
  end if;
  if auth.uid() is null then
    raise exception 'authentication_required' using errcode='42501';
  end if;
  if not private.has_permission(p_permission_key) then
    raise exception 'permission_required:%',p_permission_key using errcode='42501';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION private.reserve_order_promotion_v1(p_order_id uuid, p_coupon_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  target_order public.orders%rowtype;
  existing public.order_promotions%rowtype;
  promotion jsonb;
  campaign_row public.campaigns%rowtype;
  coupon_row public.coupons%rowtype;
  campaign_id uuid;
  coupon_id uuid;
  product_discount bigint;
  shipping_discount bigint;
  total_discount bigint;
  campaign_usage bigint;
  campaign_user_usage bigint;
  coupon_usage bigint;
  coupon_user_usage bigint;
  eligible_total bigint;
  allocated_total bigint;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into target_order from public.orders where id=p_order_id and user_id=caller_id for update;
  if target_order.id is null then raise exception 'order_not_found' using errcode='P0002'; end if;
  if target_order.status<>'pending_payment' or target_order.payment_status not in ('unpaid','authorized') then raise exception 'order_not_promotion_eligible' using errcode='55000'; end if;

  select * into existing from public.order_promotions where order_id=target_order.id;
  if existing.id is not null then
    return jsonb_build_object('applied',true,'campaignId',existing.campaign_id,'couponId',existing.coupon_id,'productDiscountMinor',existing.product_discount_minor,'shippingDiscountMinor',existing.shipping_discount_minor,'totalDiscountMinor',existing.total_discount_minor,'orderTotalMinor',target_order.total_minor,'unchanged',true);
  end if;

  update private.promotion_redemptions
  set status='released',released_at=coalesce(released_at,timezone('utc',now())),updated_at=timezone('utc',now())
  where status='reserved' and expires_at is not null and expires_at<=timezone('utc',now());

  promotion:=private.resolve_order_promotion_v1(target_order.id,p_coupon_code);
  if not coalesce((promotion->>'eligible')::boolean,false) then
    return jsonb_build_object('applied',false,'totalDiscountMinor',0,'orderTotalMinor',target_order.total_minor);
  end if;

  campaign_id:=(promotion->>'campaignId')::uuid;
  coupon_id:=nullif(promotion->>'couponId','')::uuid;
  product_discount:=(promotion->>'productDiscountMinor')::bigint;
  shipping_discount:=(promotion->>'shippingDiscountMinor')::bigint;
  total_discount:=product_discount+shipping_discount;

  select * into campaign_row from public.campaigns where id=campaign_id for update;
  promotion:=private.evaluate_campaign_for_order_v1(target_order.id,campaign_id)||case when coupon_id is null then '{}'::jsonb else jsonb_build_object('couponId',coupon_id) end;
  if not coalesce((promotion->>'eligible')::boolean,false) then raise exception 'promotion_became_unavailable' using errcode='40001'; end if;
  product_discount:=(promotion->>'productDiscountMinor')::bigint;
  shipping_discount:=(promotion->>'shippingDiscountMinor')::bigint;
  total_discount:=product_discount+shipping_discount;

  if coupon_id is not null then
    select * into coupon_row from public.coupons where id=coupon_id for update;
    if coupon_row.id is null or coupon_row.status<>'active'
      or (coupon_row.starts_at is not null and timezone('utc',now())<coupon_row.starts_at)
      or (coupon_row.ends_at is not null and timezone('utc',now())>coupon_row.ends_at) then
      raise exception 'coupon_invalid_or_unavailable' using errcode='22023';
    end if;
  end if;

  select count(*) into campaign_usage from private.promotion_redemptions r where r.campaign_id=campaign_id and r.status in ('reserved','consumed');
  select count(*) into campaign_user_usage from private.promotion_redemptions r where r.campaign_id=campaign_id and r.user_id=caller_id and r.status in ('reserved','consumed');
  if campaign_row.usage_limit is not null and campaign_usage>=campaign_row.usage_limit then raise exception 'campaign_usage_limit_reached' using errcode='55000'; end if;
  if campaign_user_usage>=campaign_row.per_user_limit then raise exception 'campaign_user_limit_reached' using errcode='55000'; end if;

  if coupon_id is not null then
    select count(*) into coupon_usage from private.promotion_redemptions r where r.coupon_id=coupon_id and r.status in ('reserved','consumed');
    select count(*) into coupon_user_usage from private.promotion_redemptions r where r.coupon_id=coupon_id and r.user_id=caller_id and r.status in ('reserved','consumed');
    if coupon_row.usage_limit is not null and coupon_usage>=coupon_row.usage_limit then raise exception 'coupon_usage_limit_reached' using errcode='55000'; end if;
    if coupon_user_usage>=coupon_row.per_user_limit then raise exception 'coupon_user_limit_reached' using errcode='55000'; end if;
  end if;

  if product_discount>0 then
    with eligible as (
      select item.id,(item.unit_price_minor*item.quantity)::bigint gross
      from public.order_items item
      left join public.products product on product.id=item.product_id
      where item.order_id=target_order.id and (
        campaign_row.target_scope='all'
        or (campaign_row.target_scope='products' and exists(select 1 from public.campaign_products link where link.campaign_id=campaign_id and link.product_id=item.product_id))
        or (campaign_row.target_scope='categories' and exists(select 1 from public.campaign_categories link where link.campaign_id=campaign_id and link.category_id=product.category_id))
      )
    ), basis as (
      select coalesce(sum(gross),0)::bigint total from eligible
    ), raw_alloc as (
      select e.id,e.gross,
             floor((product_discount::numeric*e.gross::numeric)/nullif(b.total,0))::bigint base_alloc,
             row_number() over(order by e.gross desc,e.id) rn
      from eligible e cross join basis b
    ), totals as (
      select coalesce(sum(base_alloc),0)::bigint allocated from raw_alloc
    ), final_alloc as (
      select r.id,r.base_alloc+case when r.rn=1 then product_discount-t.allocated else 0 end as discount
      from raw_alloc r cross join totals t
    )
    update public.order_items item
    set discount_minor=allocation.discount,
        line_total_minor=(item.unit_price_minor*item.quantity)-allocation.discount+item.tax_minor
    from final_alloc allocation
    where item.id=allocation.id;
  end if;

  select coalesce(sum(item.discount_minor),0)::bigint into allocated_total from public.order_items item where item.order_id=target_order.id;
  if allocated_total<>product_discount then raise exception 'promotion_allocation_mismatch' using errcode='55000'; end if;

  update public.orders
  set discount_minor=total_discount,
      total_minor=subtotal_minor-total_discount+tax_minor+shipping_minor,
      updated_at=timezone('utc',now())
  where id=target_order.id
  returning * into target_order;

  insert into public.order_promotions(order_id,campaign_id,coupon_id,product_discount_minor,shipping_discount_minor,total_discount_minor,snapshot)
  values(target_order.id,campaign_id,coupon_id,product_discount,shipping_discount,total_discount,jsonb_build_object(
    'campaignTitle',campaign_row.title,'activationMode',campaign_row.activation_mode,'discountType',campaign_row.discount_type,
    'discountValue',campaign_row.discount_value,'targetScope',campaign_row.target_scope,'couponDisplayHint',coupon_row.display_hint
  ));

  insert into private.promotion_redemptions(campaign_id,coupon_id,user_id,order_id,status,product_discount_minor,shipping_discount_minor,total_discount_minor,expires_at)
  values(campaign_id,coupon_id,caller_id,target_order.id,'reserved',product_discount,shipping_discount,total_discount,target_order.reservation_expires_at);

  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
  values('order',target_order.id,'order.promotion_reserved',jsonb_build_object('order_id',target_order.id,'campaign_id',campaign_id,'coupon_id',coupon_id,'discount_minor',total_discount));

  return jsonb_build_object('applied',true,'campaignId',campaign_id,'couponId',coupon_id,'productDiscountMinor',product_discount,'shippingDiscountMinor',shipping_discount,'totalDiscountMinor',total_discount,'orderTotalMinor',target_order.total_minor);
end;
$function$;

CREATE OR REPLACE FUNCTION private.resolve_category_id_v1(p_reference text)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select category.id
  from public.categories category
  where category.id::text = btrim(coalesce(p_reference, ''))
     or category.slug = private.slugify_tr_v1(p_reference)
     or lower(category.name) = lower(btrim(coalesce(p_reference, '')))
  order by category.created_at
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION private.resolve_order_promotion_v1(p_order_id uuid, p_coupon_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  coupon_row public.coupons%rowtype;
  candidate record;
  evaluation jsonb;
  best jsonb:=jsonb_build_object('eligible',false,'totalDiscountMinor',0);
  best_discount bigint:=0;
  best_priority integer:=-1001;
  code_hash_value text;
begin
  if nullif(btrim(coalesce(p_coupon_code,'')),'') is not null then
    code_hash_value:=private.hash_coupon_code_v1(p_coupon_code);
    select coupon.* into coupon_row
    from public.coupons coupon
    where coupon.code_hash=code_hash_value
      and coupon.status='active'
      and (coupon.starts_at is null or timezone('utc',now())>=coupon.starts_at)
      and (coupon.ends_at is null or timezone('utc',now())<=coupon.ends_at);
    if coupon_row.id is null then raise exception 'coupon_invalid_or_unavailable' using errcode='22023'; end if;

    if not exists(select 1 from public.campaigns campaign where campaign.id=coupon_row.campaign_id and campaign.activation_mode='coupon') then
      raise exception 'coupon_invalid_or_unavailable' using errcode='22023';
    end if;
    evaluation:=private.evaluate_campaign_for_order_v1(p_order_id,coupon_row.campaign_id);
    if not coalesce((evaluation->>'eligible')::boolean,false) then
      raise exception 'coupon_not_applicable:%',coalesce(evaluation->>'reason','unknown') using errcode='22023';
    end if;
    return evaluation||jsonb_build_object('couponId',coupon_row.id,'couponDisplayHint',coupon_row.display_hint);
  end if;

  for candidate in
    select campaign.id,campaign.priority
    from public.campaigns campaign
    where campaign.activation_mode='automatic'
      and campaign.status='active'
      and timezone('utc',now()) between campaign.starts_at and campaign.ends_at
    order by campaign.priority desc,campaign.created_at asc
  loop
    evaluation:=private.evaluate_campaign_for_order_v1(p_order_id,candidate.id);
    if coalesce((evaluation->>'eligible')::boolean,false) then
      if (evaluation->>'totalDiscountMinor')::bigint>best_discount
        or ((evaluation->>'totalDiscountMinor')::bigint=best_discount and candidate.priority>best_priority) then
        best:=evaluation;
        best_discount:=(evaluation->>'totalDiscountMinor')::bigint;
        best_priority:=candidate.priority;
      end if;
    end if;
  end loop;
  return best;
end;
$function$;

CREATE OR REPLACE FUNCTION private.resolve_product_export_rule_v1(p_product_id uuid, p_country_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  product_row public.products%rowtype;
  rule_row private.product_export_country_rules%rowtype;
  country_code text:=upper(btrim(coalesce(p_country_code,'')));
begin
  select * into product_row from public.products where id=p_product_id;
  if product_row.id is null then return jsonb_build_object('decision','prohibited','publicNote','Ürün bulunamadı.'); end if;

  select * into rule_row from private.product_export_country_rules rule
  where rule.product_id=product_row.id and rule.country_code=country_code
  limit 1;
  if rule_row.id is null then
    select * into rule_row from private.product_export_country_rules rule
    where rule.category_id=product_row.category_id and rule.country_code=country_code
    limit 1;
  end if;
  if rule_row.id is null then
    return jsonb_build_object('decision','manual_review','publicNote','Bu ülke için ürün uygunluğu henüz doğrulanmadı.');
  end if;
  return jsonb_build_object('decision',rule_row.decision,'publicNote',rule_row.public_note);
end;
$function$;

CREATE OR REPLACE FUNCTION private.resolve_product_id_v1(p_reference text)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select product.id
  from public.products product
  where product.deleted_at is null
    and (
      product.id::text = btrim(coalesce(p_reference, ''))
      or product.legacy_id = btrim(coalesce(p_reference, ''))
      or product.slug = btrim(coalesce(p_reference, ''))
    )
  order by product.created_at
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION private.resolve_shipping_zone_v1(p_country_code text)
 RETURNS shipping_zones
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  country_code text:=upper(btrim(coalesce(p_country_code,'')));
  zone_row public.shipping_zones%rowtype;
begin
  if country_code !~ '^[A-Z]{2}$' then raise exception 'invalid_country_code' using errcode='22023'; end if;
  select zone.* into zone_row
  from public.shipping_zones zone
  join public.shipping_zone_countries link on link.zone_id=zone.id and link.country_code=country_code
  where zone.is_active=true
  order by zone.created_at asc limit 1;
  if zone_row.id is null then
    select zone.* into zone_row from public.shipping_zones zone
    where zone.is_active=true and zone.is_rest_of_world=true
    order by zone.created_at asc limit 1;
  end if;
  return zone_row;
end;
$function$;

CREATE OR REPLACE FUNCTION private.restock_return_inventory_v1(p_return_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  returned record;
  movement_id bigint;
begin
  for returned in
    select item.variant_id,sum(returned_item.quantity)::integer as quantity
    from public.return_items returned_item
    join public.order_items item on item.id=returned_item.order_item_id
    join public.products product on product.id=item.product_id
    where returned_item.return_id=p_return_id
      and item.variant_id is not null
      and product.stock_mode in ('tracked','seasonal')
    group by item.variant_id
    order by item.variant_id
  loop
    movement_id:=null;
    insert into private.inventory_movements(
      variant_id,movement_type,quantity_delta,reference_type,reference_id,
      reason,idempotency_key,actor_user_id
    ) values (
      returned.variant_id,'return',returned.quantity,'return_request',p_return_id,
      'Approved returned goods restored to sellable inventory',
      'return:'||p_return_id::text||':restock:'||returned.variant_id::text,
      p_actor_user_id
    )
    on conflict(idempotency_key) do nothing
    returning id into movement_id;

    if movement_id is not null then
      update public.product_inventory inventory
      set available_quantity=inventory.available_quantity+returned.quantity,
          version=inventory.version+1,
          updated_at=timezone('utc',now())
      where inventory.variant_id=returned.variant_id;
    end if;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION private.review_product_editorial_with_product_v1(p_product_id uuid, p_approve boolean, p_reason text, p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  draft_row private.product_editorial_drafts%rowtype;
  reason_value text:=nullif(btrim(coalesce(p_reason,'')),'');
begin
  if p_actor is null or auth.uid() is distinct from p_actor or not coalesce(private.has_permission('product.moderate'),false) then raise exception 'admin_required' using errcode='42501'; end if;
  select * into draft_row from private.product_editorial_drafts d where d.product_id=p_product_id and d.locale='tr' for update;
  if coalesce(p_approve,false) then
    if draft_row.id is null or draft_row.status<>'review' then raise exception 'product_editorial_review_required' using errcode='55000'; end if;
    perform private.publish_product_editorial_v1(p_product_id,draft_row.payload,p_actor);
    update private.product_editorial_drafts
       set status='approved',reviewed_by=p_actor,reviewed_at=timezone('utc',now()),review_note=null,updated_at=timezone('utc',now())
     where id=draft_row.id;
    return jsonb_build_object('status','approved','draftId',draft_row.id,'productId',p_product_id);
  end if;
  if draft_row.id is not null and draft_row.status='review' then
    update private.product_editorial_drafts
       set status='rejected',reviewed_by=p_actor,reviewed_at=timezone('utc',now()),review_note=reason_value,updated_at=timezone('utc',now())
     where id=draft_row.id;
    return jsonb_build_object('status','rejected','draftId',draft_row.id,'productId',p_product_id);
  end if;
  return jsonb_build_object('status','not_pending','productId',p_product_id);
end;
$function$;

CREATE OR REPLACE FUNCTION private.runtime_dependency_integrity_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  missing_private_count integer:=0;
  missing_public_count integer:=0;
  super_admin_helper_present boolean:=false;
  admin_audit_ledger_present boolean:=false;
  readiness_wrapper_present boolean:=false;
begin
  super_admin_helper_present:=to_regprocedure('private.is_super_admin()') is not null;
  admin_audit_ledger_present:=to_regclass('private.admin_audit_logs') is not null;
  readiness_wrapper_present:=to_regprocedure('public.super_admin_get_production_readiness_snapshot_v1()') is not null;

  with src as (
    select n.nspname,p.proname,p.oid,p.prosrc
    from pg_proc p
    join pg_namespace n on n.oid=p.pronamespace
    where n.nspname in ('private','public')
  ), refs as (
    select src.oid as caller_oid,lower(m[1]) as referenced_name
    from src
    cross join lateral regexp_matches(src.prosrc,'private\.([a-zA-Z_][a-zA-Z0-9_]*)','g') m
  )
  select count(*)::integer into missing_private_count
  from (
    select distinct caller_oid,referenced_name
    from refs r
    where not exists (
      select 1 from pg_proc p2 join pg_namespace n2 on n2.oid=p2.pronamespace
      where n2.nspname='private' and lower(p2.proname)=r.referenced_name
    )
    and not exists (
      select 1 from pg_class c join pg_namespace n3 on n3.oid=c.relnamespace
      where n3.nspname='private' and lower(c.relname)=r.referenced_name
    )
    and not exists (
      select 1 from pg_type t join pg_namespace n4 on n4.oid=t.typnamespace
      where n4.nspname='private' and lower(t.typname)=r.referenced_name
    )
  ) missing;

  with src as (
    select n.nspname,p.proname,p.oid,p.prosrc
    from pg_proc p
    join pg_namespace n on n.oid=p.pronamespace
    where n.nspname in ('private','public')
  ), refs as (
    select src.oid as caller_oid,lower(m[1]) as referenced_name
    from src
    cross join lateral regexp_matches(src.prosrc,'public\.([a-zA-Z_][a-zA-Z0-9_]*)','g') m
  )
  select count(*)::integer into missing_public_count
  from (
    select distinct caller_oid,referenced_name
    from refs r
    where not exists (
      select 1 from pg_proc p2 join pg_namespace n2 on n2.oid=p2.pronamespace
      where n2.nspname='public' and lower(p2.proname)=r.referenced_name
    )
    and not exists (
      select 1 from pg_class c join pg_namespace n3 on n3.oid=c.relnamespace
      where n3.nspname='public' and lower(c.relname)=r.referenced_name
    )
    and not exists (
      select 1 from pg_type t join pg_namespace n4 on n4.oid=t.typnamespace
      where n4.nspname='public' and lower(t.typname)=r.referenced_name
    )
  ) missing;

  return jsonb_build_object(
    'superAdminHelperPresent',super_admin_helper_present,
    'adminAuditLedgerPresent',admin_audit_ledger_present,
    'readinessWrapperPresent',readiness_wrapper_present,
    'missingPrivateReferenceCount',missing_private_count,
    'missingPublicReferenceCount',missing_public_count,
    'ready',super_admin_helper_present
      and admin_audit_ledger_present
      and readiness_wrapper_present
      and missing_private_count=0
      and missing_public_count=0
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.save_my_product_health_change_v1(p_product_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); product_row public.products%rowtype; producer_row public.producers%rowtype; clean jsonb; request_row private.product_health_change_requests%rowtype;
begin
 if uid is null then raise exception 'authentication_required' using errcode='42501'; end if;
 select * into product_row from public.products where id=p_product_id and deleted_at is null; if product_row.id is null then raise exception 'product_not_found' using errcode='P0002'; end if;
 select * into producer_row from public.producers where id=product_row.producer_id and deleted_at is null; if producer_row.owner_user_id is distinct from uid then raise exception 'producer_product_owner_required' using errcode='42501'; end if;
 if producer_row.status<>'active' or not producer_row.is_verified then raise exception 'active_verified_producer_required' using errcode='42501'; end if;
 clean:=private.validate_product_health_payload_v1(p_payload);
 select * into request_row from private.product_health_change_requests where product_id=p_product_id and locale='tr' and proposed_by=uid and status='pending' for update;
 if request_row.id is null then insert into private.product_health_change_requests(product_id,locale,proposed_by,payload) values(p_product_id,'tr',uid,clean) returning * into request_row;
 else update private.product_health_change_requests set payload=clean,updated_at=timezone('utc',now()) where id=request_row.id returning * into request_row; end if;
 return jsonb_build_object('requestId',request_row.id,'productId',request_row.product_id,'status',request_row.status,'updatedAt',request_row.updated_at);
end;$function$;

CREATE OR REPLACE FUNCTION private.save_producer_application_draft_v5(p_application_id uuid, p_seller_classification text, p_activity_types text[], p_brand_name text, p_public_name text, p_description text, p_production_country_code text, p_production_province text, p_production_district text, p_production_village text, p_production_village_is_custom boolean, p_production_latitude numeric, p_production_longitude numeric, p_product_categories text[], p_legal_name text, p_identifier text, p_tax_office text, p_mersis_number text, p_tax_exemption_number text, p_iban text, p_phone text, p_contact_email text, p_address jsonb, p_food_compliance_status text, p_food_registration_number text, p_fulfillment_methods text[], p_average_dispatch_days integer, p_cold_chain_capable boolean, p_planned_products jsonb, p_sourcing_models text[], p_organic_claim_status text, p_organic_certifier_name text, p_organic_certificate_number text, p_organic_certificate_expires_on date, p_village_product_commitment boolean, p_traceability_commitment boolean, p_product_truth_commitment boolean, p_production_practice_notes text, p_consent_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  allowed_activities constant text[] := array['beekeeping','livestock','dairy','poultry','field_farming','fruit_growing','vegetable_growing','wild_harvest','fishing','food_processing','beverage_production','natural_materials'];
  allowed_sources constant text[] := array['own_production','family_production','cooperative_production'];
  allowed_seller_classes constant text[] := array['individual_non_merchant','tax_exempt_artisan','artisan','sole_proprietor','company','cooperative'];
  derived_applicant_type text;
  normalized_activities text[];
  normalized_categories text[];
  normalized_sources text[];
  normalized_fulfillment text[];
  normalized_identifier text := regexp_replace(coalesce(p_identifier,''),'[^0-9]','','g');
  normalized_iban text := upper(regexp_replace(coalesce(p_iban,''),'[^A-Za-z0-9]','','g'));
  normalized_phone text := regexp_replace(coalesce(p_phone,''),'[^0-9+]','','g');
  normalized_mersis text := regexp_replace(coalesce(p_mersis_number,''),'[^0-9]','','g');
  normalized_tax_exemption text := btrim(coalesce(p_tax_exemption_number,''));
  normalized_food_registration text := btrim(coalesce(p_food_registration_number,''));
  normalized_organic_number text := btrim(coalesce(p_organic_certificate_number,''));
  normalized_brand text := btrim(coalesce(p_brand_name,''));
  normalized_public_name text := btrim(coalesce(p_public_name,''));
  normalized_legal_name text := btrim(coalesce(p_legal_name,''));
  country_code text := upper(btrim(coalesce(p_production_country_code,'')));
  province text := btrim(coalesce(p_production_province,''));
  district text := btrim(coalesce(p_production_district,''));
  village text := btrim(coalesce(p_production_village,''));
  formatted_location text;
  account_email text;
  account_email_confirmed_at timestamptz;
  application_id uuid;
  previous_phone text;
  previous_phone_verified_at timestamptz;
  previous_phone_verified_by uuid;
  product_item jsonb;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if not exists(select 1 from public.profiles p where p.id=caller_id and p.status='active' and p.deleted_at is null) then
    raise exception 'active_profile_required' using errcode='42501';
  end if;
  if p_consent_version <> 'producer-onboarding-v2-2026-08-19' then
    raise exception 'producer_consent_required' using errcode='22023';
  end if;
  if not (p_seller_classification=any(allowed_seller_classes)) then
    raise exception 'invalid_seller_classification' using errcode='22023';
  end if;
  derived_applicant_type := case when p_seller_classification in ('individual_non_merchant','tax_exempt_artisan') then 'individual' else 'business' end;

  if char_length(normalized_public_name) not between 2 and 160
     or char_length(normalized_legal_name) not between 2 and 240 then
    raise exception 'invalid_producer_name' using errcode='22023';
  end if;
  if normalized_brand='' then normalized_brand:=normalized_public_name; end if;
  if char_length(normalized_brand) not between 2 and 160 then raise exception 'invalid_producer_brand' using errcode='22023'; end if;
  if char_length(btrim(coalesce(p_description,''))) not between 40 and 4000 then raise exception 'invalid_producer_description' using errcode='22023'; end if;

  if country_code !~ '^[A-Z]{2}$' then raise exception 'invalid_production_country_code' using errcode='22023'; end if;
  if char_length(province) not between 2 and 100 then raise exception 'invalid_production_province' using errcode='22023'; end if;
  if char_length(district) not between 2 and 100 then raise exception 'invalid_production_district' using errcode='22023'; end if;
  if char_length(village) not between 2 and 160 then raise exception 'invalid_production_village' using errcode='22023'; end if;
  if (p_production_latitude is null)<>(p_production_longitude is null) then raise exception 'production_coordinates_must_be_paired' using errcode='22023'; end if;
  if p_production_latitude is not null and p_production_latitude not between -90 and 90 then raise exception 'invalid_production_latitude' using errcode='22023'; end if;
  if p_production_longitude is not null and p_production_longitude not between -180 and 180 then raise exception 'invalid_production_longitude' using errcode='22023'; end if;
  formatted_location:=village||', '||district||', '||province||', '||country_code;

  select coalesce(array_agg(distinct value order by value),'{}'::text[])
  into normalized_activities
  from unnest(coalesce(p_activity_types,'{}'::text[])) value
  where value=any(allowed_activities);
  if cardinality(normalized_activities) not between 1 and 12
     or cardinality(normalized_activities)<>cardinality(coalesce(p_activity_types,'{}'::text[])) then
    raise exception 'invalid_producer_activity_types' using errcode='22023';
  end if;

  select coalesce(array_agg(distinct c.slug order by c.slug),'{}'::text[])
  into normalized_categories
  from public.categories c
  where c.is_active=true and c.slug=any(coalesce(p_product_categories,'{}'::text[]));
  if cardinality(normalized_categories) not between 1 and 30
     or cardinality(normalized_categories)<>cardinality(coalesce(p_product_categories,'{}'::text[])) then
    raise exception 'invalid_producer_category_scope' using errcode='22023';
  end if;

  select coalesce(array_agg(distinct value order by value),'{}'::text[])
  into normalized_sources
  from unnest(coalesce(p_sourcing_models,'{}'::text[])) value
  where value=any(allowed_sources);
  if cardinality(normalized_sources) not between 1 and 3
     or cardinality(normalized_sources)<>cardinality(coalesce(p_sourcing_models,'{}'::text[])) then
    raise exception 'producer_intermediary_source_not_allowed' using errcode='22023';
  end if;

  select coalesce(array_agg(distinct value order by value),'{}'::text[])
  into normalized_fulfillment
  from unnest(coalesce(p_fulfillment_methods,'{}'::text[])) value
  where value in ('cargo','local_delivery','pickup');
  if cardinality(normalized_fulfillment) not between 1 and 3
     or cardinality(normalized_fulfillment)<>cardinality(coalesce(p_fulfillment_methods,'{}'::text[])) then
    raise exception 'invalid_fulfillment_methods' using errcode='22023';
  end if;
  if p_average_dispatch_days is null or p_average_dispatch_days not between 1 and 30 then raise exception 'invalid_dispatch_days' using errcode='22023'; end if;
  if p_cold_chain_capable is null then raise exception 'cold_chain_declaration_required' using errcode='22023'; end if;

  if p_planned_products is null or jsonb_typeof(p_planned_products)<>'array' or jsonb_array_length(p_planned_products) not between 1 and 30 then
    raise exception 'invalid_planned_products' using errcode='22023';
  end if;
  for product_item in select value from jsonb_array_elements(p_planned_products)
  loop
    if jsonb_typeof(product_item)<>'object'
       or char_length(btrim(coalesce(product_item->>'name',''))) not between 2 and 120
       or not (coalesce(product_item->>'category','')=any(normalized_categories))
       or not (coalesce(product_item->>'source_model','')=any(allowed_sources))
       or char_length(btrim(coalesce(product_item->>'unit',''))) not between 1 and 30
       or coalesce(product_item->>'estimated_quantity','') !~ '^[0-9]+([.][0-9]{1,2})?$'
       or (product_item->>'estimated_quantity')::numeric<=0
       or (product_item->>'estimated_quantity')::numeric>1000000 then
      raise exception 'invalid_planned_product_item' using errcode='22023';
    end if;
  end loop;

  if derived_applicant_type='individual' and not private.is_valid_tckn(normalized_identifier) then raise exception 'invalid_national_id' using errcode='22023'; end if;
  if derived_applicant_type='business' and normalized_identifier !~ '^[0-9]{10}$' then raise exception 'invalid_tax_number' using errcode='22023'; end if;
  if derived_applicant_type='business' and char_length(btrim(coalesce(p_tax_office,''))) not between 2 and 160 then raise exception 'tax_office_required' using errcode='22023'; end if;
  if p_seller_classification in ('company','cooperative') and normalized_mersis !~ '^[0-9]{16}$' then raise exception 'invalid_mersis_number' using errcode='22023'; end if;
  if p_seller_classification='tax_exempt_artisan' and char_length(normalized_tax_exemption) not between 4 and 80 then raise exception 'tax_exemption_number_required' using errcode='22023'; end if;
  if normalized_iban<>'' and normalized_iban !~ '^TR[0-9]{24}$' then raise exception 'invalid_iban' using errcode='22023'; end if;
  if normalized_phone !~ '^\+?[0-9]{10,15}$' then raise exception 'invalid_phone' using errcode='22023'; end if;

  select u.email,u.email_confirmed_at into account_email,account_email_confirmed_at from auth.users u where u.id=caller_id;
  if account_email_confirmed_at is null or lower(btrim(coalesce(p_contact_email,'')))<>lower(coalesce(account_email,'')) then
    raise exception 'contact_email_must_match_verified_account' using errcode='22023';
  end if;

  if p_address is null or jsonb_typeof(p_address)<>'object'
     or coalesce(p_address->>'country_code','') !~ '^[A-Za-z]{2}$'
     or char_length(btrim(coalesce(p_address->>'province',''))) not between 2 and 100
     or char_length(btrim(coalesce(p_address->>'district',''))) not between 2 and 100
     or coalesce(p_address->>'settlement_type','') not in ('village','neighborhood','hamlet','other')
     or char_length(btrim(coalesce(p_address->>'settlement_name',''))) not between 2 and 160
     or char_length(btrim(coalesce(p_address->>'address_line',''))) not between 5 and 500
     or (coalesce(p_address->>'postal_code','')<>'' and (char_length(p_address->>'postal_code')>24 or (p_address->>'postal_code') !~ '^[A-Za-z0-9 -]+$')) then
    raise exception 'invalid_detailed_address' using errcode='22023';
  end if;

  if p_food_compliance_status not in ('registered','approved_facility','primary_production_review','pending') then raise exception 'invalid_food_compliance_status' using errcode='22023'; end if;
  if p_food_compliance_status in ('registered','approved_facility') and char_length(normalized_food_registration) not between 4 and 120 then raise exception 'food_registration_number_required' using errcode='22023'; end if;
  if p_organic_claim_status not in ('certified','certification_in_progress','not_certified_no_claim') then raise exception 'invalid_organic_claim_status' using errcode='22023'; end if;
  if p_organic_claim_status='certified' and (
     char_length(btrim(coalesce(p_organic_certifier_name,''))) not between 2 and 160
     or char_length(normalized_organic_number) not between 4 and 100
     or p_organic_certificate_expires_on is null
     or p_organic_certificate_expires_on<current_date) then
    raise exception 'invalid_organic_certificate_details' using errcode='22023';
  end if;
  if char_length(btrim(coalesce(p_production_practice_notes,''))) not between 30 and 2000 then raise exception 'invalid_production_practice_notes' using errcode='22023'; end if;

  if p_application_id is not null then
    select a.id into application_id
    from public.producer_applications a
    where a.id=p_application_id and a.applicant_user_id=caller_id and a.status in ('draft','needs_information')
    for update;
    if application_id is null then raise exception 'producer_application_not_editable' using errcode='55000'; end if;
  else
    select a.id into application_id
    from public.producer_applications a
    where a.applicant_user_id=caller_id and a.status in ('draft','needs_information')
    order by a.updated_at desc limit 1 for update;
  end if;

  if application_id is not null then
    select k.phone,k.phone_verified_at,k.phone_verified_by
    into previous_phone,previous_phone_verified_at,previous_phone_verified_by
    from private.producer_application_kyc k where k.application_id=application_id;
  end if;

  if application_id is null then
    insert into public.producer_applications(
      applicant_user_id,applicant_type,seller_classification,activity_types,brand_name,public_name,description,
      production_location,production_country_code,production_province,production_district,production_village,
      production_village_is_custom,production_latitude,production_longitude,product_categories,status,
      food_compliance_status,fulfillment_methods,average_dispatch_days,cold_chain_capable,planned_products,
      sourcing_models,organic_claim_status,organic_certifier_name,organic_certificate_expires_on,
      village_product_commitment,traceability_commitment,product_truth_commitment,production_practice_notes
    ) values (
      caller_id,derived_applicant_type,p_seller_classification,normalized_activities,normalized_brand,normalized_public_name,btrim(p_description),
      formatted_location,country_code,province,district,village,coalesce(p_production_village_is_custom,false),p_production_latitude,p_production_longitude,
      normalized_categories,'draft',p_food_compliance_status,normalized_fulfillment,p_average_dispatch_days,p_cold_chain_capable,p_planned_products,
      normalized_sources,p_organic_claim_status,nullif(btrim(coalesce(p_organic_certifier_name,'')),''),
      case when p_organic_claim_status='certified' then p_organic_certificate_expires_on else null end,
      coalesce(p_village_product_commitment,false),coalesce(p_traceability_commitment,false),coalesce(p_product_truth_commitment,false),btrim(p_production_practice_notes)
    ) returning id into application_id;
  else
    update public.producer_applications a set
      applicant_type=derived_applicant_type,seller_classification=p_seller_classification,activity_types=normalized_activities,
      brand_name=normalized_brand,public_name=normalized_public_name,description=btrim(p_description),production_location=formatted_location,
      production_country_code=country_code,production_province=province,production_district=district,production_village=village,
      production_village_is_custom=coalesce(p_production_village_is_custom,false),production_latitude=p_production_latitude,
      production_longitude=p_production_longitude,product_categories=normalized_categories,status='draft',submitted_at=null,
      reviewed_at=null,reviewed_by=null,rejection_reason=null,food_compliance_status=p_food_compliance_status,
      fulfillment_methods=normalized_fulfillment,average_dispatch_days=p_average_dispatch_days,cold_chain_capable=p_cold_chain_capable,
      planned_products=p_planned_products,sourcing_models=normalized_sources,organic_claim_status=p_organic_claim_status,
      organic_certifier_name=nullif(btrim(coalesce(p_organic_certifier_name,'')),''),
      organic_certificate_expires_on=case when p_organic_claim_status='certified' then p_organic_certificate_expires_on else null end,
      village_product_commitment=coalesce(p_village_product_commitment,false),traceability_commitment=coalesce(p_traceability_commitment,false),
      product_truth_commitment=coalesce(p_product_truth_commitment,false),production_practice_notes=btrim(p_production_practice_notes),
      updated_at=timezone('utc',now())
    where a.id=application_id;
  end if;

  insert into private.producer_application_kyc(
    application_id,legal_name,national_id_ciphertext,tax_office,tax_number_ciphertext,iban_ciphertext,bank_account_holder,
    phone,contact_email,address,consent_version,consented_at,mersis_number_ciphertext,tax_exemption_number_ciphertext,
    food_registration_number_ciphertext,organic_certificate_number_ciphertext,contact_email_verified_at,phone_verified_at,phone_verified_by,updated_at
  ) values (
    application_id,normalized_legal_name,
    case when derived_applicant_type='individual' then private.encrypt_producer_kyc(normalized_identifier) end,
    case when derived_applicant_type='business' then btrim(p_tax_office) end,
    case when derived_applicant_type='business' then private.encrypt_producer_kyc(normalized_identifier) end,
    private.encrypt_producer_kyc(nullif(normalized_iban,'')),normalized_legal_name,normalized_phone,lower(btrim(p_contact_email)),
    p_address||jsonb_build_object('country_code',upper(p_address->>'country_code')),
    p_consent_version,timezone('utc',now()),private.encrypt_producer_kyc(nullif(normalized_mersis,'')),
    private.encrypt_producer_kyc(nullif(normalized_tax_exemption,'')),private.encrypt_producer_kyc(nullif(normalized_food_registration,'')),
    private.encrypt_producer_kyc(case when p_organic_claim_status='certified' then nullif(normalized_organic_number,'') else null end),
    account_email_confirmed_at,
    case when previous_phone=normalized_phone then previous_phone_verified_at else null end,
    case when previous_phone=normalized_phone then previous_phone_verified_by else null end,
    timezone('utc',now())
  ) on conflict(application_id) do update set
    legal_name=excluded.legal_name,national_id_ciphertext=excluded.national_id_ciphertext,tax_office=excluded.tax_office,
    tax_number_ciphertext=excluded.tax_number_ciphertext,iban_ciphertext=excluded.iban_ciphertext,bank_account_holder=excluded.bank_account_holder,
    phone=excluded.phone,contact_email=excluded.contact_email,address=excluded.address,consent_version=excluded.consent_version,
    consented_at=excluded.consented_at,mersis_number_ciphertext=excluded.mersis_number_ciphertext,
    tax_exemption_number_ciphertext=excluded.tax_exemption_number_ciphertext,food_registration_number_ciphertext=excluded.food_registration_number_ciphertext,
    organic_certificate_number_ciphertext=excluded.organic_certificate_number_ciphertext,contact_email_verified_at=excluded.contact_email_verified_at,
    phone_verified_at=excluded.phone_verified_at,phone_verified_by=excluded.phone_verified_by,updated_at=excluded.updated_at;

  return jsonb_build_object(
    'application_id',application_id,'status','draft','seller_classification',p_seller_classification,
    'activity_types',normalized_activities,'product_categories',normalized_categories,'sourcing_models',normalized_sources,
    'organic_claim_status',p_organic_claim_status,
    'production_location',jsonb_build_object('country_code',country_code,'province',province,'district',district,'village',village,
      'village_is_custom',coalesce(p_production_village_is_custom,false),'latitude',p_production_latitude,'longitude',p_production_longitude)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.save_product_editorial_v1(p_reference text, p_payload jsonb, p_action text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid(); product_id uuid:=private.resolve_product_id_v1(p_reference); product_row public.products%rowtype; producer_row public.producers%rowtype; normalized jsonb; action_value text:=lower(btrim(coalesce(p_action,''))); note_value text:=btrim(coalesce(p_note,'')); row_id uuid; current_status text;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if product_id is null then raise exception 'product_not_found' using errcode='P0002'; end if;
  select * into product_row from public.products p where p.id=product_id and p.deleted_at is null;
  select * into producer_row from public.producers p where p.id=product_row.producer_id and p.deleted_at is null;
  if not coalesce(private.has_permission('content.update'),false) and producer_row.owner_user_id is distinct from caller_id then raise exception 'product_access_denied' using errcode='42501'; end if;
  if action_value not in ('save','submit','publish','reject') then raise exception 'invalid_editorial_action' using errcode='22023'; end if;
  if action_value in ('save','submit','publish') then normalized:=private.normalize_product_editorial_payload_v1(p_payload); end if;
  if action_value='publish' then
    if not coalesce(private.has_permission('content.update'),false) then raise exception 'admin_required' using errcode='42501'; end if;
    perform private.publish_product_editorial_v1(product_id,normalized,caller_id);
    insert into private.product_editorial_drafts(product_id,producer_id,locale,payload,status,submitted_by,submitted_at,reviewed_by,reviewed_at,review_note,updated_at)
    values(product_id,product_row.producer_id,'tr',normalized,'approved',caller_id,timezone('utc',now()),caller_id,timezone('utc',now()),null,timezone('utc',now()))
    on conflict(product_id,locale) do update set payload=excluded.payload,status='approved',submitted_by=excluded.submitted_by,submitted_at=excluded.submitted_at,reviewed_by=excluded.reviewed_by,reviewed_at=excluded.reviewed_at,review_note=null,updated_at=excluded.updated_at returning id into row_id;
    return jsonb_build_object('id',row_id,'status','published','productId',product_id);
  elsif action_value='reject' then
    if not coalesce(private.has_permission('content.update'),false) then raise exception 'admin_required' using errcode='42501'; end if;
    if char_length(note_value) not between 8 and 2000 then raise exception 'editorial_rejection_note_required' using errcode='22023'; end if;
    update private.product_editorial_drafts d set status='rejected',reviewed_by=caller_id,reviewed_at=timezone('utc',now()),review_note=note_value,updated_at=timezone('utc',now()) where d.product_id=product_id and d.locale='tr' and d.status='review' returning d.id into row_id;
    if row_id is null then raise exception 'editorial_review_not_found' using errcode='P0002'; end if;
    return jsonb_build_object('id',row_id,'status','rejected','productId',product_id);
  else
    current_status:=case when action_value='submit' then 'review' else 'draft' end;
    insert into private.product_editorial_drafts(product_id,producer_id,locale,payload,status,submitted_by,submitted_at,reviewed_by,reviewed_at,review_note,updated_at)
    values(product_id,product_row.producer_id,'tr',normalized,current_status,caller_id,case when action_value='submit' then timezone('utc',now()) else null end,null,null,null,timezone('utc',now()))
    on conflict(product_id,locale) do update set payload=excluded.payload,status=excluded.status,submitted_by=excluded.submitted_by,submitted_at=excluded.submitted_at,reviewed_by=null,reviewed_at=null,review_note=null,updated_at=excluded.updated_at returning id into row_id;
    return jsonb_build_object('id',row_id,'status',current_status,'productId',product_id);
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION private.save_storefront_setup_v1(p_producer_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  p public.producers%rowtype;
  old_status text;
  unexpected text;
  display_name text;
  description text;
  story text;
  headline text;
  subheadline text;
  email text;
  phone text;
  website text;
  line1 text;
  line2 text;
  postal text;
  city text;
  region text;
  country text;
  visibility text;
  business_type text;
  business jsonb;
  options jsonb;
  readiness jsonb;
begin
  if auth.uid() is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if p_payload is null or jsonb_typeof(p_payload)<>'object' then raise exception 'invalid_storefront_payload' using errcode='22023'; end if;
  select key into unexpected from jsonb_object_keys(p_payload) key where key not in ('displayName','description','story','headline','subheadline','contact','address','businessIdentityType') limit 1;
  if unexpected is not null then raise exception 'storefront_field_not_allowed:%',unexpected using errcode='22023'; end if;
  if p_payload ? 'contact' and jsonb_typeof(p_payload->'contact')<>'object' then raise exception 'invalid_storefront_contact' using errcode='22023'; end if;
  if p_payload ? 'address' and jsonb_typeof(p_payload->'address')<>'object' then raise exception 'invalid_storefront_address' using errcode='22023'; end if;

  select * into p from public.producers where id=p_producer_id and deleted_at is null for update;
  if p.id is null then raise exception 'producer_not_found' using errcode='P0002'; end if;
  if not private.storefront_editor_authorized_v1(p.id) then raise exception 'storefront_editor_access_required' using errcode='42501'; end if;
  old_status:=p.storefront_status;

  display_name:=btrim(coalesce(p_payload->>'displayName',''));
  description:=btrim(coalesce(p_payload->>'description',''));
  story:=btrim(coalesce(p_payload->>'story',''));
  headline:=nullif(btrim(coalesce(p_payload->>'headline','')),'');
  subheadline:=nullif(btrim(coalesce(p_payload->>'subheadline','')),'');
  email:=lower(nullif(btrim(coalesce(p_payload->'contact'->>'email','')),''));
  phone:=nullif(btrim(coalesce(p_payload->'contact'->>'phone','')),'');
  website:=nullif(btrim(coalesce(p_payload->'contact'->>'websiteUrl','')),'');
  line1:=nullif(btrim(coalesce(p_payload->'address'->>'line1','')),'');
  line2:=nullif(btrim(coalesce(p_payload->'address'->>'line2','')),'');
  postal:=nullif(btrim(coalesce(p_payload->'address'->>'postalCode','')),'');
  city:=nullif(btrim(coalesce(p_payload->'address'->>'city','')),'');
  region:=nullif(btrim(coalesce(p_payload->'address'->>'region','')),'');
  country:=upper(nullif(btrim(coalesce(p_payload->'address'->>'countryCode','')),''));
  visibility:=lower(coalesce(nullif(btrim(p_payload->'address'->>'visibility'),''),'city_region'));
  business_type:=lower(nullif(btrim(coalesce(p_payload->>'businessIdentityType','')),''));

  if char_length(display_name) not between 2 and 120 then raise exception 'invalid_storefront_display_name' using errcode='22023'; end if;
  if char_length(description)>1200 or char_length(story)>5000 then raise exception 'storefront_about_too_long' using errcode='22023'; end if;
  if headline is not null and char_length(headline)>140 then raise exception 'storefront_headline_too_long' using errcode='22023'; end if;
  if subheadline is not null and char_length(subheadline)>280 then raise exception 'storefront_subheadline_too_long' using errcode='22023'; end if;
  if email is not null and (char_length(email)>254 or email !~* '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$') then raise exception 'invalid_storefront_email' using errcode='22023'; end if;
  if phone is not null and (char_length(phone)>32 or char_length(regexp_replace(phone,'[^0-9]','','g')) not between 7 and 15) then raise exception 'invalid_storefront_phone' using errcode='22023'; end if;
  if website is not null and (char_length(website)>300 or website !~* '^https://[^[:space:]]+$') then raise exception 'invalid_storefront_website' using errcode='22023'; end if;
  if line1 is not null and char_length(line1)>240 or line2 is not null and char_length(line2)>240 or postal is not null and char_length(postal)>24 or city is not null and char_length(city)>120 or region is not null and char_length(region)>120 then raise exception 'storefront_address_too_long' using errcode='22023'; end if;
  if country is not null and country !~ '^[A-Z]{2}$' then raise exception 'invalid_storefront_country_code' using errcode='22023'; end if;
  if visibility not in ('hidden','city_region','full') then raise exception 'invalid_storefront_address_visibility' using errcode='22023'; end if;

  options:=private.storefront_business_options_v1(p.id);
  if business_type is null and jsonb_array_length(options)>0 then business_type:=options->0->>'type'; end if;
  business:=private.storefront_business_selection_v1(p.id,business_type);

  update public.producers set
    display_name=display_name,
    description=description,
    story=story,
    storefront_headline=headline,
    storefront_subheadline=subheadline,
    storefront_contact_email=email,
    storefront_contact_phone=phone,
    storefront_website_url=website,
    storefront_address_line1=line1,
    storefront_address_line2=line2,
    storefront_postal_code=postal,
    storefront_city=city,
    storefront_region=region,
    storefront_country_code=country,
    storefront_address_visibility=visibility,
    storefront_business_identity_type=case when business is null then null else business->>'type' end,
    storefront_business_name=case when business is null then null else business->>'publicName' end,
    storefront_business_reference=case when business is null then null else nullif(business->>'reference','') end,
    storefront_business_verified_at=case when business is null then null else coalesce(storefront_business_verified_at,timezone('utc',now())) end,
    storefront_setup_version=1,
    updated_at=timezone('utc',now())
  where id=p.id;

  readiness:=private.storefront_readiness_v1(p.id);
  if old_status='published' and coalesce((readiness->>'ready')::boolean,false)=false then raise exception 'published_storefront_must_remain_ready' using errcode='55000'; end if;
  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
  values('storefront',p.id,'storefront.updated',jsonb_build_object('producerId',p.id,'actorUserId',auth.uid(),'storefrontStatus',old_status,'ready',coalesce((readiness->>'ready')::boolean,false)));
  return private.get_storefront_setup_editor_v1(p.id);
end;
$function$;

CREATE OR REPLACE FUNCTION private.search_catalog_v1(p_query text DEFAULT NULL::text, p_category_slug text DEFAULT NULL::text, p_producer_id uuid DEFAULT NULL::uuid, p_province text DEFAULT NULL::text, p_district text DEFAULT NULL::text, p_village text DEFAULT NULL::text, p_min_price_minor bigint DEFAULT NULL::bigint, p_max_price_minor bigint DEFAULT NULL::bigint, p_in_stock boolean DEFAULT false, p_featured boolean DEFAULT NULL::boolean, p_sort text DEFAULT 'relevance'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  q text:=lower(btrim(coalesce(p_query,'')));
  requested_category_slug text:=nullif(lower(btrim(coalesce(p_category_slug,''))),'');
  province_value text:=nullif(lower(btrim(coalesce(p_province,''))),'');
  district_value text:=nullif(lower(btrim(coalesce(p_district,''))),'');
  village_value text:=nullif(lower(btrim(coalesce(p_village,''))),'');
  sort_value text:=lower(btrim(coalesce(p_sort,'relevance')));
  result jsonb;
begin
  if char_length(q)>100 then raise exception 'search_query_too_long' using errcode='22023'; end if;
  if p_limit not between 1 and 50 or p_offset<0 then raise exception 'invalid_pagination' using errcode='22023'; end if;
  if p_min_price_minor is not null and p_min_price_minor<0 then raise exception 'invalid_min_price' using errcode='22023'; end if;
  if p_max_price_minor is not null and p_max_price_minor<0 then raise exception 'invalid_max_price' using errcode='22023'; end if;
  if p_min_price_minor is not null and p_max_price_minor is not null and p_max_price_minor<p_min_price_minor then raise exception 'invalid_price_range' using errcode='22023'; end if;
  if sort_value not in ('relevance','newest','price_asc','price_desc','rating') then raise exception 'invalid_catalog_sort' using errcode='22023'; end if;

  with base as (
    select product.id,product.legacy_id,product.slug,product.name,product.short_description,product.origin,product.unit_label,
           product.stock_mode,product.is_featured,product.published_at,product.currency,
           category.id category_id,category.slug category_slug,category.name category_name,
           producer.id producer_id,producer.display_name producer_name,producer.production_province,producer.production_district,producer.production_village,
           variant.id variant_id,variant.name variant_name,variant.sku,variant.price_minor,variant.compare_at_price_minor,
           case when product.stock_mode in ('tracked','seasonal') then greatest(0,coalesce(inventory.available_quantity,0)-coalesce(inventory.reserved_quantity,0)) else null end available_quantity,
           image.storage_path image_path,
           coalesce(review_stats.average_rating,0)::numeric average_rating,coalesce(review_stats.review_count,0)::bigint review_count,
           case when q='' then 0::numeric else
             greatest(
               extensions.similarity(product.search_text,q)::numeric,
               (extensions.similarity(lower(product.name),q)*1.8)::numeric,
               (extensions.similarity(lower(producer.display_name),q)*1.25)::numeric,
               extensions.similarity(lower(coalesce(producer.production_village,'')),q)::numeric,
               extensions.similarity(lower(category.name),q)::numeric
             ) + case when lower(product.name) like q||'%' then 1 else 0 end
           end relevance
    from public.products product
    join public.producers producer on producer.id=product.producer_id and producer.status='active' and producer.is_verified=true and producer.deleted_at is null
    join public.categories category on category.id=product.category_id and category.is_active=true
    join lateral(
      select v.* from public.product_variants v where v.product_id=product.id and v.is_active=true order by v.is_default desc,v.created_at asc limit 1
    ) variant on true
    left join public.product_inventory inventory on inventory.variant_id=variant.id
    left join lateral(
      select pi.storage_path from public.product_images pi where pi.product_id=product.id order by pi.is_primary desc,pi.sort_order asc,pi.created_at asc limit 1
    ) image on true
    left join lateral(
      select round(avg(r.rating)::numeric,2) average_rating,count(*)::bigint review_count from public.reviews r where r.product_id=product.id and r.status='published'
    ) review_stats on true
    where product.status='published' and product.is_active=true and product.deleted_at is null
      and (requested_category_slug is null or category.slug=requested_category_slug)
      and (p_producer_id is null or producer.id=p_producer_id)
      and (province_value is null or lower(coalesce(producer.production_province,''))=province_value)
      and (district_value is null or lower(coalesce(producer.production_district,''))=district_value)
      and (village_value is null or lower(coalesce(producer.production_village,''))=village_value)
      and (p_min_price_minor is null or variant.price_minor>=p_min_price_minor)
      and (p_max_price_minor is null or variant.price_minor<=p_max_price_minor)
      and (not coalesce(p_in_stock,false) or product.stock_mode not in ('tracked','seasonal') or greatest(0,coalesce(inventory.available_quantity,0)-coalesce(inventory.reserved_quantity,0))>0)
      and (p_featured is null or product.is_featured=p_featured)
      and (
        q='' or product.search_text ilike '%'||q||'%' or lower(product.name) ilike '%'||q||'%'
        or lower(producer.display_name) ilike '%'||q||'%' or lower(coalesce(producer.production_village,'')) ilike '%'||q||'%'
        or lower(category.name) ilike '%'||q||'%'
        or extensions.similarity(product.search_text,q)>=0.12 or extensions.similarity(lower(product.name),q)>=0.18
      )
  ), page as (
    select * from base
    order by
      case when sort_value='price_asc' then price_minor end asc,
      case when sort_value='price_desc' then price_minor end desc,
      case when sort_value='rating' then average_rating end desc,
      case when sort_value='newest' then published_at end desc,
      case when sort_value='relevance' then relevance end desc,
      case when sort_value='relevance' then is_featured end desc,
      published_at desc nulls last,id
    limit p_limit offset p_offset
  )
  select jsonb_build_object(
    'total',(select count(*) from base),
    'query',q,
    'limit',p_limit,
    'offset',p_offset,
    'items',coalesce((select jsonb_agg(jsonb_build_object(
      'id',id,'legacyId',legacy_id,'slug',slug,'name',name,'shortDescription',short_description,'origin',origin,'unitLabel',unit_label,
      'category',jsonb_build_object('id',category_id,'slug',category_slug,'name',category_name),
      'producer',jsonb_build_object('id',producer_id,'name',producer_name,'province',production_province,'district',production_district,'village',production_village),
      'variant',jsonb_build_object('id',variant_id,'name',variant_name,'sku',sku,'priceMinor',price_minor,'compareAtPriceMinor',compare_at_price_minor),
      'currency',currency,'stockMode',stock_mode,'availableQuantity',available_quantity,'featured',is_featured,'imagePath',image_path,
      'averageRating',average_rating,'reviewCount',review_count,'relevance',round(relevance,4)
    ) order by
      case when sort_value='price_asc' then price_minor end asc,
      case when sort_value='price_desc' then price_minor end desc,
      case when sort_value='rating' then average_rating end desc,
      case when sort_value='newest' then published_at end desc,
      case when sort_value='relevance' then relevance end desc,
      published_at desc nulls last,id) from page),'[]'::jsonb)
  ) into result;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.search_catalog_v2(p_query text DEFAULT NULL::text, p_category_slug text DEFAULT NULL::text, p_producer_id uuid DEFAULT NULL::uuid, p_province text DEFAULT NULL::text, p_district text DEFAULT NULL::text, p_village text DEFAULT NULL::text, p_min_price_minor bigint DEFAULT NULL::bigint, p_max_price_minor bigint DEFAULT NULL::bigint, p_in_stock boolean DEFAULT false, p_featured boolean DEFAULT NULL::boolean, p_sort text DEFAULT 'relevance'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  base jsonb;
  items jsonb;
begin
  base:=private.search_catalog_v1(p_query,p_category_slug,p_producer_id,p_province,p_district,p_village,p_min_price_minor,p_max_price_minor,p_in_stock,p_featured,p_sort,p_limit,p_offset);
  select coalesce(jsonb_agg(
    case when resolved.path is null
      then jsonb_set(item,'{imagePath}','null'::jsonb,true)
      else jsonb_set(item,'{imagePath}',to_jsonb(resolved.path),true)
    end
  ),'[]'::jsonb) into items
  from jsonb_array_elements(coalesce(base->'items','[]'::jsonb)) item
  cross join lateral (
    select private.catalog_public_card_image_path_v1(
      item->>'imagePath',
      nullif(item#>>'{producer,id}','')::uuid
    ) path
  ) resolved;
  return jsonb_set(base,'{items}',items,true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.search_catalog_v3(p_query text DEFAULT NULL::text, p_category_slug text DEFAULT NULL::text, p_producer_id uuid DEFAULT NULL::uuid, p_province text DEFAULT NULL::text, p_district text DEFAULT NULL::text, p_village text DEFAULT NULL::text, p_min_price_minor bigint DEFAULT NULL::bigint, p_max_price_minor bigint DEFAULT NULL::bigint, p_in_stock boolean DEFAULT false, p_featured boolean DEFAULT NULL::boolean, p_sort text DEFAULT 'relevance'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select private.decorate_catalog_handling_v1(private.search_catalog_v2(
    p_query,p_category_slug,p_producer_id,p_province,p_district,p_village,
    p_min_price_minor,p_max_price_minor,p_in_stock,p_featured,p_sort,p_limit,p_offset
  ));
$function$;

CREATE OR REPLACE FUNCTION private.search_catalog_v4(p_query text DEFAULT NULL::text, p_category_slug text DEFAULT NULL::text, p_producer_id uuid DEFAULT NULL::uuid, p_province text DEFAULT NULL::text, p_district text DEFAULT NULL::text, p_village text DEFAULT NULL::text, p_min_price_minor bigint DEFAULT NULL::bigint, p_max_price_minor bigint DEFAULT NULL::bigint, p_in_stock boolean DEFAULT false, p_featured boolean DEFAULT NULL::boolean, p_sort text DEFAULT 'relevance'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  q text:=lower(btrim(coalesce(p_query,'')));
  requested_category_slug text:=nullif(lower(btrim(coalesce(p_category_slug,''))), '');
  province_value text:=nullif(lower(btrim(coalesce(p_province,''))), '');
  district_value text:=nullif(lower(btrim(coalesce(p_district,''))), '');
  village_value text:=nullif(lower(btrim(coalesce(p_village,''))), '');
  sort_value text:=lower(btrim(coalesce(p_sort,'relevance')));
  result jsonb;
begin
  if p_limit not between 1 and 50 or p_offset not between 0 and 100000 then
    raise exception 'invalid_pagination' using errcode='22023';
  end if;
  if sort_value not in ('relevance','newest','price_asc','price_desc','rating') then
    raise exception 'invalid_catalog_sort' using errcode='22023';
  end if;
  if p_min_price_minor is not null and p_min_price_minor<0 then raise exception 'invalid_min_price' using errcode='22023'; end if;
  if p_max_price_minor is not null and p_max_price_minor<0 then raise exception 'invalid_max_price' using errcode='22023'; end if;
  if p_min_price_minor is not null and p_max_price_minor is not null and p_min_price_minor>p_max_price_minor then
    raise exception 'invalid_price_range' using errcode='22023';
  end if;

  with base as (
    select row_data.*,
      case when q='' then 0::numeric else
        greatest(
          extensions.similarity(row_data.product_search_text,q)::numeric,
          (extensions.similarity(lower(row_data.product_name),q)*1.8)::numeric,
          (extensions.similarity(lower(row_data.producer_name),q)*1.25)::numeric,
          extensions.similarity(lower(coalesce(row_data.village,'')),q)::numeric,
          extensions.similarity(lower(row_data.category_name),q)::numeric
        ) + case when lower(row_data.product_name) like q||'%' then 1 else 0 end
      end relevance
    from private.catalog_public_card_rows_v1() row_data
    where (requested_category_slug is null or row_data.category_slug=requested_category_slug)
      and (p_producer_id is null or row_data.producer_id=p_producer_id)
      and (province_value is null or lower(coalesce(row_data.province,''))=province_value)
      and (district_value is null or lower(coalesce(row_data.district,''))=district_value)
      and (village_value is null or lower(coalesce(row_data.village,''))=village_value)
      and (p_min_price_minor is null or row_data.price_minor>=p_min_price_minor)
      and (p_max_price_minor is null or row_data.price_minor<=p_max_price_minor)
      and (not coalesce(p_in_stock,false) or row_data.stock_mode not in ('tracked','seasonal') or coalesce(row_data.available_quantity,0)>0)
      and (p_featured is null or row_data.is_featured=p_featured)
      and (
        q='' or row_data.product_search_text ilike '%'||q||'%'
        or lower(row_data.product_name) ilike '%'||q||'%'
        or lower(row_data.producer_name) ilike '%'||q||'%'
        or lower(coalesce(row_data.village,'')) ilike '%'||q||'%'
        or lower(row_data.category_name) ilike '%'||q||'%'
        or extensions.similarity(row_data.product_search_text,q)>=0.12
        or extensions.similarity(lower(row_data.product_name),q)>=0.18
      )
  ), page as (
    select * from base
    order by
      case when sort_value='price_asc' then price_minor end asc,
      case when sort_value='price_desc' then price_minor end desc,
      case when sort_value='rating' then average_rating end desc,
      case when sort_value='newest' then published_at end desc,
      case when sort_value='relevance' then relevance end desc,
      case when sort_value='relevance' then is_featured end desc,
      published_at desc nulls last,product_id
    limit p_limit offset p_offset
  )
  select jsonb_build_object(
    'total',(select count(*) from base),
    'query',q,
    'limit',p_limit,
    'offset',p_offset,
    'items',coalesce((select jsonb_agg(card order by
      case when sort_value='price_asc' then price_minor end asc,
      case when sort_value='price_desc' then price_minor end desc,
      case when sort_value='rating' then average_rating end desc,
      case when sort_value='newest' then published_at end desc,
      case when sort_value='relevance' then relevance end desc,
      case when sort_value='relevance' then is_featured end desc,
      published_at desc nulls last,product_id
    ) from page),'[]'::jsonb)
  ) into result;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.send_conversation_message_v1(p_conversation_id uuid, p_body text, p_attachment_paths text[] DEFAULT '{}'::text[], p_message_type text DEFAULT 'text'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); conversation_row public.conversations%rowtype; message_row public.messages%rowtype;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  perform private.require_current_terms_v1();
  select conversation.* into conversation_row from public.conversations conversation where conversation.id=p_conversation_id and exists(select 1 from public.conversation_participants participant where participant.conversation_id=conversation.id and participant.user_id=caller_id) for update;
  if conversation_row.id is null then raise exception 'conversation_access_denied' using errcode='42501'; end if;
  if conversation_row.status='closed' then raise exception 'conversation_closed' using errcode='55000'; end if;
  if exists(select 1 from public.conversation_participants other join private.user_blocks b on b.removed_at is null and ((b.blocker_user_id=caller_id and b.blocked_user_id=other.user_id) or (b.blocker_user_id=other.user_id and b.blocked_user_id=caller_id)) where other.conversation_id=conversation_row.id and other.user_id<>caller_id) then raise exception 'conversation_user_blocked' using errcode='42501'; end if;
  if (select count(*) from public.messages message where message.sender_user_id=caller_id and message.created_at>timezone('utc',now())-interval '1 minute')>=20 then raise exception 'message_rate_limit' using errcode='P0001'; end if;
  message_row:=private.insert_conversation_message_v1(conversation_row.id,caller_id,p_body,p_attachment_paths,p_message_type);
  return jsonb_build_object('id',message_row.id,'conversationId',conversation_row.id,'messageType',message_row.message_type,'createdAt',message_row.created_at);
end;
$function$;

CREATE OR REPLACE FUNCTION private.service_get_integration_runtime_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  cfg private.super_admin_company_configuration_v1%rowtype;
  result jsonb;
  value text;
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role_required' using errcode='42501'; end if;
  select * into cfg from private.super_admin_company_configuration_v1 where singleton=true;
  if cfg.singleton is null then raise exception 'integration_configuration_missing' using errcode='P0002'; end if;
  result:=jsonb_build_object(
    'iyzicoBaseUrl',case when cfg.iyzico_environment='production' then 'https://api.iyzipay.com' else 'https://sandbox-api.iyzipay.com' end,
    'transactionalEmailFrom',cfg.transactional_email_from,
    'fcmProjectId',cfg.fcm_project_id,
    'apnsBundleId',cfg.apns_bundle_id
  );
  select decrypted_secret into value from vault.decrypted_secrets where name='golden_oremar_iyzico_api_key' limit 1;
  result:=result||jsonb_build_object('iyzicoApiKey',case when value like 'replace-before-release:%' then null else value end);
  select decrypted_secret into value from vault.decrypted_secrets where name='golden_oremar_iyzico_secret_key' limit 1;
  result:=result||jsonb_build_object('iyzicoSecretKey',case when value like 'replace-before-release:%' then null else value end);
  select decrypted_secret into value from vault.decrypted_secrets where name='golden_oremar_resend_api_key' limit 1;
  result:=result||jsonb_build_object('resendApiKey',case when value like 'replace-before-release:%' then null else value end);
  select decrypted_secret into value from vault.decrypted_secrets where name='golden_oremar_fcm_service_account_email' limit 1;
  result:=result||jsonb_build_object('fcmServiceAccountEmail',case when value like 'replace-before-release:%' then null else value end);
  select decrypted_secret into value from vault.decrypted_secrets where name='golden_oremar_fcm_private_key' limit 1;
  result:=result||jsonb_build_object('fcmPrivateKey',case when value like 'replace-before-release:%' then null else value end);
  select decrypted_secret into value from vault.decrypted_secrets where name='golden_oremar_apns_team_id' limit 1;
  result:=result||jsonb_build_object('apnsTeamId',case when value like 'replace-before-release:%' then null else value end);
  select decrypted_secret into value from vault.decrypted_secrets where name='golden_oremar_apns_key_id' limit 1;
  result:=result||jsonb_build_object('apnsKeyId',case when value like 'replace-before-release:%' then null else value end);
  select decrypted_secret into value from vault.decrypted_secrets where name='golden_oremar_apns_private_key' limit 1;
  result:=result||jsonb_build_object('apnsPrivateKey',case when value like 'replace-before-release:%' then null else value end);
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.set_conversation_open_state_v1(p_conversation_id uuid, p_open boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); conversation_row public.conversations%rowtype;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into conversation_row from public.conversations conversation
  where conversation.id=p_conversation_id and exists(select 1 from public.conversation_participants participant where participant.conversation_id=conversation.id and participant.user_id=caller_id)
  for update;
  if conversation_row.id is null then raise exception 'conversation_access_denied' using errcode='42501'; end if;
  update public.conversations
  set status=case when coalesce(p_open,false) then 'open' else 'closed' end,
      closed_at=case when coalesce(p_open,false) then null else timezone('utc',now()) end,
      closed_by=case when coalesce(p_open,false) then null else caller_id end,
      updated_at=timezone('utc',now())
  where id=conversation_row.id returning * into conversation_row;
  return jsonb_build_object('conversationId',conversation_row.id,'status',conversation_row.status,'closedAt',conversation_row.closed_at);
end;
$function$;

CREATE OR REPLACE FUNCTION private.set_conversation_user_block_v1(p_conversation_id uuid, p_block boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); target_id uuid;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if p_block is null then raise exception 'invalid_block_state' using errcode='22023'; end if;
  if not exists(select 1 from public.conversation_participants p where p.conversation_id=p_conversation_id and p.user_id=caller_id) then raise exception 'conversation_access_denied' using errcode='42501'; end if;
  select p.user_id into target_id from public.conversation_participants p where p.conversation_id=p_conversation_id and p.user_id<>caller_id and p.participant_role in ('customer','producer') order by case p.participant_role when 'producer' then 0 else 1 end,p.joined_at asc limit 1;
  if target_id is null then raise exception 'conversation_user_not_blockable' using errcode='55000'; end if;
  if p_block then
    insert into private.user_blocks(blocker_user_id,blocked_user_id,created_at,removed_at)
    values(caller_id,target_id,timezone('utc',now()),null)
    on conflict(blocker_user_id,blocked_user_id) do update set created_at=excluded.created_at,removed_at=null;
  else
    update private.user_blocks set removed_at=timezone('utc',now()) where blocker_user_id=caller_id and blocked_user_id=target_id and removed_at is null;
  end if;
  return private.get_conversation_safety_context_v1(p_conversation_id);
end;
$function$;

CREATE OR REPLACE FUNCTION private.set_my_cart_item_v1(p_variant_id uuid, p_quantity integer, p_selected_options jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  cart_row public.carts%rowtype;
  variant_row public.product_variants%rowtype;
  product_row public.products%rowtype;
  producer_row public.producers%rowtype;
  inventory_row public.product_inventory%rowtype;
  sellable integer;
  options_value jsonb;
  customization_value jsonb;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if not exists(select 1 from public.profiles where id=caller_id and status='active' and deleted_at is null) then raise exception 'active_profile_required' using errcode='42501'; end if;
  if p_quantity is null or p_quantity not between 0 and 99 then raise exception 'invalid_cart_quantity' using errcode='22023'; end if;
  if p_selected_options is not null and (jsonb_typeof(p_selected_options)<>'object' or pg_column_size(p_selected_options)>8192) then raise exception 'invalid_selected_options' using errcode='22023'; end if;
  select variant.* into variant_row from public.product_variants variant where variant.id=p_variant_id and variant.is_active=true;
  if variant_row.id is null then raise exception 'variant_not_available' using errcode='P0002'; end if;
  select * into product_row from public.products where id=variant_row.product_id;
  select * into producer_row from public.producers where id=product_row.producer_id;
  if product_row.id is null or product_row.status<>'published' or not product_row.is_active or product_row.deleted_at is not null or producer_row.id is null or producer_row.status<>'active' or not producer_row.is_verified or producer_row.deleted_at is not null then raise exception 'product_not_available' using errcode='P0002'; end if;
  options_value:=coalesce(variant_row.option_values,'{}'::jsonb)-'orderCustomization';
  if p_selected_options is not null and p_selected_options ? 'orderCustomization' then
    customization_value:=private.normalize_order_customization_v1(product_row.id,p_selected_options->'orderCustomization');
    if customization_value is not null then options_value:=options_value||jsonb_build_object('orderCustomization',customization_value); end if;
  end if;
  cart_row:=private.get_or_create_customer_cart_v1(caller_id);
  if cart_row.currency<>product_row.currency then raise exception 'mixed_currency_cart_not_supported' using errcode='22023'; end if;
  if p_quantity=0 then delete from public.cart_items where cart_id=cart_row.id and variant_id=p_variant_id; update public.carts set expires_at=timezone('utc',now())+interval '30 days',updated_at=timezone('utc',now()) where id=cart_row.id; return private.get_customer_cart_snapshot_v1(caller_id); end if;
  if product_row.stock_mode in ('tracked','seasonal') then select * into inventory_row from public.product_inventory where variant_id=p_variant_id; sellable:=greatest(0,coalesce(inventory_row.available_quantity,0)-coalesce(inventory_row.reserved_quantity,0)); if p_quantity>sellable then raise exception 'insufficient_stock:%',sellable using errcode='22023'; end if; end if;
  delete from public.cart_items where cart_id=cart_row.id and variant_id=p_variant_id and selected_options is distinct from options_value;
  insert into public.cart_items(cart_id,variant_id,quantity,selected_options) values(cart_row.id,p_variant_id,p_quantity,options_value) on conflict(cart_id,variant_id,selected_options) do update set quantity=excluded.quantity,updated_at=timezone('utc',now());
  update public.carts set expires_at=timezone('utc',now())+interval '30 days',updated_at=timezone('utc',now()) where id=cart_row.id;
  return private.get_customer_cart_snapshot_v1(caller_id);
end;
$function$;

CREATE OR REPLACE FUNCTION private.set_my_default_payment_method_impl_v2(p_payment_method_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  uid uuid:=auth.uid();
  target private.customer_payment_methods%rowtype;
begin
  if uid is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if p_payment_method_id is null then raise exception 'payment_method_required' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended(uid::text,86111));
  select * into target
  from private.customer_payment_methods p
  where p.id=p_payment_method_id and p.user_id=uid and p.status='active'
  for update;
  if target.id is null then raise exception 'payment_method_not_found' using errcode='P0002'; end if;
  update private.customer_payment_methods
  set is_default=false,updated_at=timezone('utc',now())
  where user_id=uid and is_default=true and id<>target.id;
  update private.customer_payment_methods
  set is_default=true,updated_at=timezone('utc',now())
  where id=target.id;
  return jsonb_build_object('ok',true,'id',target.id,'isDefault',true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.set_my_pending_order_payment_method_v1(p_order_id uuid, p_payment_method_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  target_order public.orders%rowtype;
  method private.customer_payment_methods%rowtype;
  payment_config jsonb;
  configured_provider text;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if p_order_id is null or p_payment_method_id is null then raise exception 'payment_context_required' using errcode='22023'; end if;

  select * into target_order from public.orders where id=p_order_id and user_id=caller_id for update;
  if target_order.id is null then raise exception 'order_not_found' using errcode='P0002'; end if;
  if target_order.status<>'pending_payment' or target_order.payment_status not in ('unpaid','failed') then raise exception 'order_payment_method_change_not_allowed' using errcode='55000'; end if;
  if target_order.reservation_expires_at is not null and target_order.reservation_expires_at<=timezone('utc',now()) then raise exception 'payment_reservation_expired' using errcode='55000'; end if;
  if exists(select 1 from private.payment_intents i where i.order_id=target_order.id and i.status in ('processing','authorized')) then raise exception 'payment_reconciliation_required' using errcode='55000'; end if;

  select coalesce(bs.public_config->'payments','{}'::jsonb) into payment_config from public.brand_settings bs where bs.slug='golden-oremar' limit 1;
  configured_provider:=nullif(lower(btrim(coalesce(payment_config->>'provider',''))),'');
  if configured_provider is null or not coalesce((payment_config->>'live_card_payments_enabled')::boolean,false) then raise exception 'payment_provider_not_configured' using errcode='55000'; end if;

  select * into method from private.customer_payment_methods where id=p_payment_method_id and user_id=caller_id and status='active';
  if method.id is null then raise exception 'payment_method_not_found' using errcode='P0002'; end if;
  if method.provider<>configured_provider then raise exception 'payment_method_provider_mismatch' using errcode='22023'; end if;
  if method.exp_year is not null and method.exp_month is not null and make_date(method.exp_year,method.exp_month,1)<date_trunc('month',timezone('utc',now()))::date then raise exception 'payment_method_expired' using errcode='22023'; end if;

  insert into private.order_payment_preferences(order_id,user_id,payment_method_id,provider,updated_at)
  values(target_order.id,caller_id,method.id,method.provider,timezone('utc',now()))
  on conflict(order_id) do update set payment_method_id=excluded.payment_method_id,provider=excluded.provider,updated_at=excluded.updated_at;

  update public.orders set payment_status='unpaid',updated_at=timezone('utc',now()) where id=target_order.id and payment_status='failed';

  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
  values('order',target_order.id,'order.payment_method_changed',jsonb_build_object('order_id',target_order.id,'user_id',caller_id,'payment_method_id',method.id,'provider',method.provider));

  return jsonb_build_object('ok',true,'orderId',target_order.id,'paymentMethodId',method.id,'provider',method.provider,'paymentStatus','unpaid');
end;
$function$;

CREATE OR REPLACE FUNCTION private.set_product_availability_subscription_v1(p_reference text, p_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); product_id uuid:=private.resolve_product_id_v1(p_reference); row_value public.product_availability_subscriptions%rowtype;
begin if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if; if product_id is null or not exists(select 1 from public.products p where p.id=product_id and p.status='published' and p.is_active=true and p.deleted_at is null) then raise exception 'product_not_available' using errcode='P0002'; end if; insert into public.product_availability_subscriptions(user_id,product_id,active,updated_at) values(caller_id,product_id,coalesce(p_active,true),timezone('utc',now())) on conflict(user_id,product_id) do update set active=excluded.active,updated_at=excluded.updated_at returning * into row_value; return jsonb_build_object('productId',product_id,'active',row_value.active,'updatedAt',row_value.updated_at); end;$function$;

CREATE OR REPLACE FUNCTION private.set_review_helpful_vote_v1(p_review_id uuid, p_helpful boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); review_row public.reviews%rowtype; vote_count bigint;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into review_row from public.reviews where id=p_review_id and status='published';
  if review_row.id is null then raise exception 'published_review_not_found' using errcode='P0002'; end if;
  if review_row.user_id=caller_id then raise exception 'cannot_vote_own_review' using errcode='22023'; end if;
  if coalesce(p_helpful,false) then
    insert into private.review_helpful_votes(review_id,user_id) values(review_row.id,caller_id) on conflict do nothing;
  else
    delete from private.review_helpful_votes where review_id=review_row.id and user_id=caller_id;
  end if;
  select count(*) into vote_count from private.review_helpful_votes where review_id=review_row.id;
  return jsonb_build_object('reviewId',review_row.id,'helpful',coalesce(p_helpful,false),'helpfulCount',vote_count);
end;
$function$;

CREATE OR REPLACE FUNCTION private.set_store_branding_asset_v1(p_producer_id uuid, p_kind text, p_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  kind text:=lower(btrim(coalesce(p_kind,'')));
  normalized text;
  previous_path text;
  locked_id uuid;
begin
  if auth.uid() is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if kind not in ('logo','cover') then raise exception 'invalid_store_branding_kind' using errcode='22023'; end if;
  select p.id into locked_id from public.producers p where p.id=p_producer_id and p.deleted_at is null for update;
  if locked_id is null then raise exception 'producer_not_found' using errcode='P0002'; end if;
  if not private.store_branding_can_edit_v1(p_producer_id) then raise exception 'store_branding_edit_required' using errcode='42501'; end if;
  normalized:=private.store_branding_verified_path_v1(p_producer_id,kind,p_path);
  if normalized is null then raise exception 'store_branding_asset_not_verified' using errcode='22023'; end if;
  if kind='logo' then
    select logo_path into previous_path from public.producers where id=p_producer_id;
    update public.producers set logo_path=normalized,updated_at=timezone('utc',now()) where id=p_producer_id;
  else
    select cover_path into previous_path from public.producers where id=p_producer_id;
    update public.producers set cover_path=normalized,updated_at=timezone('utc',now()) where id=p_producer_id;
  end if;
  return jsonb_build_object('ok',true,'producerId',p_producer_id,'kind',kind,'path',normalized,'previousPath',previous_path);
end;
$function$;

CREATE OR REPLACE FUNCTION private.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at := timezone('utc', now());
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.should_queue_push_v1(p_user_id uuid, p_type text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare pref private.user_notification_preferences%rowtype; marketing_allowed boolean:=false;
begin
  select * into pref from private.user_notification_preferences where user_id=p_user_id;
  if pref.user_id is not null and not pref.push_enabled then return false; end if;
  if p_type='campaign' then
    select marketing_consent into marketing_allowed from public.profiles where id=p_user_id;
    return coalesce(marketing_allowed,false) and coalesce(pref.campaign_push,false);
  elsif p_type='order' then return coalesce(pref.order_push,true);
  elsif p_type='payment' then return coalesce(pref.payment_push,true);
  elsif p_type='shipment' then return coalesce(pref.shipment_push,true);
  elsif p_type='return' then return coalesce(pref.return_push,true);
  elsif p_type='message' then return coalesce(pref.message_push,true);
  elsif p_type='review' then return coalesce(pref.review_push,true);
  elsif p_type='producer' then return coalesce(pref.producer_push,true);
  else return coalesce(pref.system_push,true);
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION private.slugify_tr_v1(p_value text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select trim(both '-' from regexp_replace(
    translate(lower(coalesce(p_value, '')), 'çğıöşüâîû', 'cgiosuaiu'),
    '[^a-z0-9]+',
    '-',
    'g'
  ));
$function$;

CREATE OR REPLACE FUNCTION private.snapshot_order_item_commission_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  commission integer;
begin
  if new.producer_id is null then
    new.commission_basis_points_snapshot:=0;
    return new;
  end if;
  select producer.commission_basis_points into commission
  from public.producers producer
  where producer.id=new.producer_id;
  if commission is null then raise exception 'producer_not_found_for_order_item' using errcode='P0002'; end if;
  new.commission_basis_points_snapshot:=commission;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.staff_mfa_state_v1(p_user_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select case
    when p_user_id is null then null
    when not private.user_requires_staff_mfa_v1(p_user_id) then null
    else coalesce((select s.state from private.staff_mfa_security_state s where s.user_id=p_user_id),'enrollment_required')
  end;
$function$;

CREATE OR REPLACE FUNCTION private.start_producer_conversation_v1(p_producer_id uuid, p_product_id uuid, p_order_id uuid, p_subject text, p_initial_message text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); producer_row public.producers%rowtype; product_row public.products%rowtype; context_value text; conversation_row public.conversations%rowtype; initial_row public.messages%rowtype; subject_value text:=nullif(btrim(coalesce(p_subject,'')),'');
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  perform private.require_current_terms_v1();
  if ((p_product_id is not null)::integer+(p_order_id is not null)::integer)<>1 then raise exception 'product_or_order_context_required' using errcode='22023'; end if;
  if subject_value is not null and char_length(subject_value)>200 then raise exception 'conversation_subject_too_long' using errcode='22023'; end if;
  if char_length(btrim(coalesce(p_initial_message,''))) not between 1 and 5000 then raise exception 'initial_message_required' using errcode='22023'; end if;
  select * into producer_row from public.producers producer where producer.id=p_producer_id and producer.status='active' and producer.is_verified=true and producer.deleted_at is null;
  if producer_row.id is null or producer_row.owner_user_id is null then raise exception 'producer_not_available' using errcode='P0002'; end if;
  if producer_row.owner_user_id=caller_id then raise exception 'cannot_message_self' using errcode='22023'; end if;
  if exists(select 1 from private.user_blocks b where b.removed_at is null and ((b.blocker_user_id=caller_id and b.blocked_user_id=producer_row.owner_user_id) or (b.blocker_user_id=producer_row.owner_user_id and b.blocked_user_id=caller_id))) then raise exception 'conversation_user_blocked' using errcode='42501'; end if;
  if p_product_id is not null then
    select * into product_row from public.products product where product.id=p_product_id and product.producer_id=producer_row.id and product.status='published' and product.is_active=true and product.deleted_at is null;
    if product_row.id is null then raise exception 'product_not_available' using errcode='P0002'; end if;
    context_value:='producer:'||caller_id::text||':'||producer_row.id::text||':product:'||product_row.id::text;
  else
    if not exists(select 1 from public.orders customer_order join public.order_items item on item.order_id=customer_order.id where customer_order.id=p_order_id and customer_order.user_id=caller_id and item.producer_id=producer_row.id) then raise exception 'order_producer_context_not_found' using errcode='P0002'; end if;
    context_value:='producer:'||caller_id::text||':'||producer_row.id::text||':order:'||p_order_id::text;
  end if;
  if (select count(*) from public.conversations c where c.created_by=caller_id and c.created_at>timezone('utc',now())-interval '1 hour')>=10 then raise exception 'conversation_start_rate_limit' using errcode='P0001'; end if;
  insert into public.conversations(conversation_type,order_id,producer_id,product_id,subject,status,created_by,context_key) values('producer',p_order_id,producer_row.id,p_product_id,subject_value,'open',caller_id,context_value)
  on conflict (context_key) where context_key is not null do update set status='open',closed_at=null,closed_by=null,subject=coalesce(excluded.subject,public.conversations.subject),updated_at=timezone('utc',now()) returning * into conversation_row;
  insert into public.conversation_participants(conversation_id,user_id,participant_role,last_read_at) values(conversation_row.id,caller_id,'customer',timezone('utc',now())) on conflict(conversation_id,user_id) do update set participant_role='customer';
  insert into public.conversation_participants(conversation_id,user_id,participant_role) values(conversation_row.id,producer_row.owner_user_id,'producer') on conflict(conversation_id,user_id) do update set participant_role='producer';
  initial_row:=private.insert_conversation_message_v1(conversation_row.id,caller_id,p_initial_message,'{}'::text[],'text');
  return jsonb_build_object('conversationId',conversation_row.id,'messageId',initial_row.id,'status',conversation_row.status,'producerId',producer_row.id,'productId',p_product_id,'orderId',p_order_id);
end;
$function$;

CREATE OR REPLACE FUNCTION private.start_support_conversation_v1(p_order_id uuid, p_subject text, p_initial_message text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  context_value text;
  conversation_row public.conversations%rowtype;
  message_row public.messages%rowtype;
  admin_count integer:=0;
  subject_value text:=btrim(coalesce(p_subject,''));
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if char_length(subject_value) not between 2 and 200 then raise exception 'support_subject_required' using errcode='22023'; end if;
  if char_length(btrim(coalesce(p_initial_message,''))) not between 1 and 5000 then raise exception 'initial_message_required' using errcode='22023'; end if;
  if p_order_id is not null and not exists(select 1 from public.orders where id=p_order_id and user_id=caller_id) then raise exception 'order_not_found' using errcode='P0002'; end if;
  context_value:='support:'||caller_id::text||':'||coalesce(p_order_id::text,'general');

  insert into public.conversations(conversation_type,order_id,subject,status,created_by,context_key)
  values('support',p_order_id,subject_value,'open',caller_id,context_value)
  on conflict (context_key) where context_key is not null do update
  set status='open',closed_at=null,closed_by=null,subject=excluded.subject,updated_at=timezone('utc',now())
  returning * into conversation_row;

  insert into public.conversation_participants(conversation_id,user_id,participant_role,last_read_at)
  values(conversation_row.id,caller_id,'customer',timezone('utc',now()))
  on conflict(conversation_id,user_id) do update set participant_role='customer';

  insert into public.conversation_participants(conversation_id,user_id,participant_role)
  select conversation_row.id,role.user_id,'admin'
  from private.user_roles role
  join public.profiles profile on profile.id=role.user_id and profile.status='active' and profile.deleted_at is null
  where role.role in ('admin','super_admin') and (role.expires_at is null or role.expires_at>timezone('utc',now()))
  on conflict(conversation_id,user_id) do update set participant_role='admin';
  get diagnostics admin_count=row_count;

  message_row:=private.insert_conversation_message_v1(conversation_row.id,caller_id,p_initial_message,'{}'::text[],'text');
  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
  values('conversation',conversation_row.id,'support_conversation.opened',jsonb_build_object('conversation_id',conversation_row.id,'order_id',p_order_id,'customer_user_id',caller_id,'assigned_admin_participants',admin_count));
  return jsonb_build_object('conversationId',conversation_row.id,'messageId',message_row.id,'status',conversation_row.status,'orderId',p_order_id);
end;
$function$;

CREATE OR REPLACE FUNCTION private.store_branding_can_edit_v1(p_producer_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select auth.uid() is not null and exists(
    select 1
    from public.producers p
    where p.id=p_producer_id
      and p.deleted_at is null
      and p.is_verified=true
      and (
        (p.store_kind<>'official' and p.owner_user_id=(select auth.uid()) and p.status in ('pending','active'))
        or (p.store_kind='official' and p.status='active' and coalesce(private.has_permission('product.publish'),false))
      )
  );
$function$;

CREATE OR REPLACE FUNCTION private.store_branding_verified_path_v1(p_producer_id uuid, p_kind text, p_path text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  normalized text:=private.catalog_media_binary_verified_path_v2(p_path);
  kind text:=lower(btrim(coalesce(p_kind,'')));
begin
  if p_producer_id is null or kind not in ('logo','cover') or normalized is null then return null; end if;
  if normalized !~* ('^' || p_producer_id::text || '/profile/' || kind || '-[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|jpeg|png|webp)$') then return null; end if;
  return normalized;
end;
$function$;

CREATE OR REPLACE FUNCTION private.store_hosted_payment_session_for_service_v1(p_intent_id uuid, p_token text, p_provider_snapshot jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare intent private.payment_intents%rowtype; normalized_token text:=btrim(coalesce(p_token,'')); snapshot jsonb:=coalesce(p_provider_snapshot,'{}'::jsonb);
begin
  if p_intent_id is null then raise exception 'payment_intent_required' using errcode='22023'; end if;
  if char_length(normalized_token) not between 8 and 500 or normalized_token ~ '[[:cntrl:]]' then raise exception 'invalid_provider_session_token' using errcode='22023'; end if;
  if jsonb_typeof(snapshot)<>'object' then raise exception 'invalid_provider_snapshot' using errcode='22023'; end if;
  select * into intent from private.payment_intents where id=p_intent_id for update;
  if intent.id is null or intent.payment_flow<>'checkout_form' or intent.status<>'processing' then raise exception 'hosted_payment_intent_invalid' using errcode='55000'; end if;
  if intent.provider_session_token is not null and intent.provider_session_token<>normalized_token then raise exception 'hosted_payment_session_conflict' using errcode='23505'; end if;
  update private.payment_intents set provider_session_token=normalized_token,provider_result=provider_result||snapshot,updated_at=timezone('utc',now()) where id=intent.id;
  return jsonb_build_object('ok',true,'intentId',intent.id,'tokenStored',true,'orderId',intent.order_id);
end;$function$;

CREATE OR REPLACE FUNCTION private.storefront_brand_asset_ready_v1(p_producer_id uuid, p_kind text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.producers%rowtype; kind text:=lower(btrim(coalesce(p_kind,''))); path text;
begin
  if kind not in ('logo','cover') then return false; end if;
  select * into p from public.producers where id=p_producer_id and deleted_at is null;
  if p.id is null then return false; end if;
  path:=case when kind='logo' then p.logo_path else p.cover_path end;
  if private.store_branding_verified_path_v1(p.id,kind,path) is not null then return true; end if;
  if p.store_kind='official' and private.verified_public_storage_path_v1('catalog-public',path) is not null then return true; end if;
  return false;
end;
$function$;

CREATE OR REPLACE FUNCTION private.storefront_business_options_v1(p_producer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  p public.producers%rowtype;
  application public.producer_applications%rowtype;
  kyc private.producer_application_kyc%rowtype;
  settings public.brand_settings%rowtype;
  identity jsonb:='{}'::jsonb;
  options jsonb:='[]'::jsonb;
  value text;
  legal_name text;
begin
  select * into p from public.producers where id=p_producer_id and deleted_at is null;
  if p.id is null then return '[]'::jsonb; end if;

  if p.store_kind='official' then
    select * into settings from public.brand_settings where slug='golden-oremar';
    identity:=coalesce(settings.public_config->'businessIdentity','{}'::jsonb);
    if lower(btrim(coalesce(identity->>'verificationStatus',''))) <> 'verified' then return '[]'::jsonb; end if;
    legal_name:=nullif(btrim(coalesce(identity->>'registeredLegalName',settings.legal_name,'')),'');
    value:=nullif(btrim(coalesce(identity->>'mersisNumber','')),'');
    if value is not null then options:=options||jsonb_build_array(jsonb_build_object('type','mersis','label','MERSİS numarası','reference',value,'legalName',legal_name,'publicName',legal_name,'verified',true)); end if;
    value:=nullif(btrim(coalesce(identity->>'tradeRegistryNumber','')),'');
    if value is not null then options:=options||jsonb_build_array(jsonb_build_object('type','trade_registry','label','Ticaret sicil numarası','reference',value,'legalName',legal_name,'publicName',legal_name,'verified',true)); end if;
    if jsonb_array_length(options)=0 then options:=jsonb_build_array(jsonb_build_object('type','platform_registered','label','Doğrulanmış işletme','reference',null,'legalName',legal_name,'publicName',legal_name,'verified',true)); end if;
    return options;
  end if;

  if p.application_id is null then return '[]'::jsonb; end if;
  select * into application from public.producer_applications where id=p.application_id and status='approved';
  select * into kyc from private.producer_application_kyc where application_id=p.application_id;
  if application.id is null or kyc.application_id is null then return '[]'::jsonb; end if;
  legal_name:=nullif(btrim(coalesce(kyc.legal_name,'')),'');

  if kyc.mersis_number_ciphertext is not null then
    value:=nullif(btrim(private.decrypt_producer_kyc(kyc.mersis_number_ciphertext)),'');
    if value is not null then options:=options||jsonb_build_array(jsonb_build_object('type','mersis','label','MERSİS numarası','reference',value,'legalName',legal_name,'publicName',legal_name,'verified',true)); end if;
  end if;
  if kyc.food_registration_number_ciphertext is not null and exists(select 1 from private.producer_documents d where d.application_id=p.application_id and d.document_type in ('food_business_registration','food_business_approval') and d.verification_status='verified') then
    value:=nullif(btrim(private.decrypt_producer_kyc(kyc.food_registration_number_ciphertext)),'');
    if value is not null then options:=options||jsonb_build_array(jsonb_build_object('type','food_registration','label','Gıda işletmesi kayıt/onay numarası','reference',value,'legalName',legal_name,'publicName',coalesce(legal_name,p.display_name),'verified',true)); end if;
  end if;
  if kyc.tax_exemption_number_ciphertext is not null and exists(select 1 from private.producer_documents d where d.application_id=p.application_id and d.document_type='tax_exemption_certificate' and d.verification_status='verified') then
    value:=nullif(btrim(private.decrypt_producer_kyc(kyc.tax_exemption_number_ciphertext)),'');
    if value is not null then options:=options||jsonb_build_array(jsonb_build_object('type','tax_exemption','label','Esnaf vergi muafiyeti belgesi','reference',value,'legalName',legal_name,'publicName',p.display_name,'verified',true)); end if;
  end if;

  if jsonb_array_length(options)=0 then
    if application.applicant_type='individual' then
      options:=jsonb_build_array(jsonb_build_object('type','verified_individual','label','Kimliği doğrulanmış bireysel üretici','reference',null,'legalName',legal_name,'publicName',p.display_name,'verified',true));
    else
      options:=jsonb_build_array(jsonb_build_object('type','verified_business','label','Belgesi doğrulanmış işletme','reference',null,'legalName',legal_name,'publicName',coalesce(legal_name,p.display_name),'verified',true));
    end if;
  end if;
  return options;
end;
$function$;

CREATE OR REPLACE FUNCTION private.storefront_business_selection_v1(p_producer_id uuid, p_type text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select item
  from jsonb_array_elements(private.storefront_business_options_v1(p_producer_id)) item
  where item->>'type'=lower(btrim(coalesce(p_type,''))) and coalesce((item->>'verified')::boolean,false)=true
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION private.storefront_editor_authorized_v1(p_producer_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select auth.uid() is not null and exists(
    select 1 from public.producers p
    where p.id=p_producer_id and p.deleted_at is null
      and (
        (p.store_kind<>'official' and p.owner_user_id=(select auth.uid()))
        or (p.store_kind='official' and coalesce(private.has_permission('product.publish'),false))
      )
  );
$function$;

CREATE OR REPLACE FUNCTION private.storefront_readiness_v1(p_producer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  p public.producers%rowtype; business jsonb; identity_ready boolean:=false; name_ready boolean:=false; about_ready boolean:=false;
  logo_ready boolean:=false; cover_ready boolean:=false; email_ready boolean:=false; phone_ready boolean:=false;
  address_ready boolean:=false; business_ready boolean:=false; ready boolean:=false; digits text;
begin
  select * into p from public.producers where id=p_producer_id and deleted_at is null;
  if p.id is null then return jsonb_build_object('ready',false,'missing',jsonb_build_array('producer_not_found'),'steps','[]'::jsonb); end if;
  identity_ready:=p.status in ('pending','active') and p.is_verified=true;
  name_ready:=char_length(btrim(coalesce(p.display_name,''))) between 2 and 120;
  about_ready:=char_length(btrim(coalesce(p.description,''))) between 40 and 1200;
  logo_ready:=private.storefront_brand_asset_ready_v1(p.id,'logo');
  cover_ready:=private.storefront_brand_asset_ready_v1(p.id,'cover');
  email_ready:=char_length(btrim(coalesce(p.storefront_contact_email,''))) between 5 and 254 and btrim(p.storefront_contact_email) ~* '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$';
  digits:=regexp_replace(coalesce(p.storefront_contact_phone,''),'[^0-9]','','g');
  phone_ready:=char_length(digits) between 7 and 15;
  address_ready:=coalesce(p.storefront_country_code,'')~'^[A-Z]{2}$' and char_length(btrim(coalesce(p.storefront_city,''))) between 2 and 120 and char_length(btrim(coalesce(p.storefront_region,''))) between 2 and 120 and (p.storefront_address_visibility<>'full' or char_length(btrim(coalesce(p.storefront_address_line1,''))) between 5 and 240);
  business:=private.storefront_business_selection_v1(p.id,p.storefront_business_identity_type);
  business_ready:=business is not null and coalesce(p.storefront_business_name,'')=coalesce(business->>'publicName','') and coalesce(p.storefront_business_reference,'')=coalesce(business->>'reference','') and p.storefront_business_verified_at is not null;
  ready:=identity_ready and name_ready and about_ready and logo_ready and cover_ready and email_ready and phone_ready and address_ready and business_ready;
  return jsonb_build_object(
    'ready',ready,
    'steps',jsonb_build_array(
      jsonb_build_object('code','identity','label','Satıcı doğrulaması','ready',identity_ready),
      jsonb_build_object('code','store_identity','label','Mağaza adı ve hakkında','ready',name_ready and about_ready),
      jsonb_build_object('code','logo','label','Profil / logo','ready',logo_ready),
      jsonb_build_object('code','cover','label','Kapak görseli','ready',cover_ready),
      jsonb_build_object('code','contact','label','İletişim bilgileri','ready',email_ready and phone_ready),
      jsonb_build_object('code','address','label','Adres ve konum','ready',address_ready),
      jsonb_build_object('code','business','label','İşletme doğrulaması','ready',business_ready)
    ),
    'missing',coalesce((select jsonb_agg(code order by ord) from (values
      (10,'producer_verification',not identity_ready),(20,'store_name',not name_ready),(30,'about',not about_ready),(40,'logo',not logo_ready),(50,'cover',not cover_ready),(60,'contact_email',not email_ready),(70,'contact_phone',not phone_ready),(80,'address',not address_ready),(90,'business_identity',not business_ready)
    ) m(ord,code,missing) where missing),'[]'::jsonb)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.submit_contact_message(p_idempotency_key text, p_request_hash text, p_name text, p_email text, p_phone text, p_subject text, p_message text, p_locale text, p_source text, p_ip_hash text, p_user_agent text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  existing_key private.idempotency_keys%rowtype;
  message_id uuid;
  response_payload jsonb;
  normalized_email text := lower(trim(p_email));
begin
  if p_idempotency_key is null or char_length(p_idempotency_key) not between 8 and 200 then
    raise exception using errcode = '22023', message = 'invalid_idempotency_key';
  end if;

  if p_request_hash is null or p_request_hash !~ '^[a-f0-9]{64}$' then
    raise exception using errcode = '22023', message = 'invalid_request_hash';
  end if;

  select *
  into existing_key
  from private.idempotency_keys
  where key = p_idempotency_key
    and scope = 'contact_submission';

  if found then
    if existing_key.request_hash <> p_request_hash then
      raise exception using errcode = '22023', message = 'idempotency_key_reused';
    end if;
    if existing_key.completed_at is not null then
      return existing_key.response_body;
    end if;
  end if;

  if p_name is null or char_length(trim(p_name)) not between 2 and 120 then
    raise exception using errcode = '22023', message = 'invalid_name';
  end if;
  if normalized_email is null
     or char_length(normalized_email) > 254
     or normalized_email !~* '^[a-z0-9.!#$%&''*+/=?^_`{|}~-]+@[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+$' then
    raise exception using errcode = '22023', message = 'invalid_email';
  end if;
  if p_phone is not null and char_length(trim(p_phone)) > 40 then
    raise exception using errcode = '22023', message = 'invalid_phone';
  end if;
  if p_subject is null or char_length(trim(p_subject)) not between 2 and 160 then
    raise exception using errcode = '22023', message = 'invalid_subject';
  end if;
  if p_message is null or char_length(trim(p_message)) not between 10 and 5000 then
    raise exception using errcode = '22023', message = 'invalid_message';
  end if;
  if p_locale is null or p_locale !~ '^[a-z]{2}(-[A-Z]{2})?$' then
    raise exception using errcode = '22023', message = 'invalid_locale';
  end if;
  if p_source is null or char_length(p_source) not between 2 and 40 then
    raise exception using errcode = '22023', message = 'invalid_source';
  end if;
  if p_ip_hash is null or p_ip_hash !~ '^[a-f0-9]{64}$' then
    raise exception using errcode = '22023', message = 'invalid_ip_hash';
  end if;

  insert into private.idempotency_keys(
    key, scope, request_hash, locked_at, expires_at
  ) values (
    p_idempotency_key,
    'contact_submission',
    p_request_hash,
    timezone('utc', now()),
    timezone('utc', now()) + interval '24 hours'
  )
  on conflict (key) do nothing;

  if not found then
    select *
    into existing_key
    from private.idempotency_keys
    where key = p_idempotency_key;

    if existing_key.scope <> 'contact_submission' or existing_key.request_hash <> p_request_hash then
      raise exception using errcode = '22023', message = 'idempotency_key_reused';
    end if;
    if existing_key.completed_at is not null then
      return existing_key.response_body;
    end if;
    raise exception using errcode = '40001', message = 'request_in_progress';
  end if;

  if (
    select count(*)
    from private.submission_attempts
    where scope = 'contact'
      and ip_hash = p_ip_hash
      and created_at > timezone('utc', now()) - interval '1 hour'
  ) >= 5 then
    raise exception using errcode = 'P0001', message = 'rate_limit_exceeded';
  end if;

  insert into private.submission_attempts(scope, ip_hash, request_hash)
  values ('contact', p_ip_hash, p_request_hash);

  insert into private.contact_messages(
    name,
    email,
    phone,
    subject,
    message,
    locale,
    source,
    ip_hash,
    user_agent
  ) values (
    trim(p_name),
    normalized_email,
    nullif(trim(p_phone), ''),
    trim(p_subject),
    trim(p_message),
    p_locale,
    p_source,
    p_ip_hash,
    left(coalesce(p_user_agent, ''), 500)
  )
  returning id into message_id;

  insert into private.outbox_events(
    aggregate_type,
    aggregate_id,
    event_type,
    payload
  ) values (
    'contact_message',
    message_id,
    'contact.received',
    jsonb_build_object('contact_message_id', message_id)
  );

  response_payload := jsonb_build_object(
    'ok', true,
    'messageId', message_id,
    'status', 'received'
  );

  update private.idempotency_keys
  set response_status = 201,
      response_body = response_payload,
      completed_at = timezone('utc', now())
  where key = p_idempotency_key;

  return response_payload;
end;
$function$;

CREATE OR REPLACE FUNCTION private.submit_event_reservation(p_idempotency_key text, p_request_hash text, p_event_reference text, p_guest_name text, p_guest_email text, p_guest_phone text, p_guest_count integer, p_notes text, p_ip_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid(); linked_user_id uuid; existing_key private.idempotency_keys%rowtype; target_event public.events%rowtype;
  reservation_id uuid; reservation_code_value text; reservation_status text; reserved_guest_count bigint; response_payload jsonb;
  normalized_email text:=lower(btrim(coalesce(p_guest_email,''))); is_paid boolean:=false; total_minor bigint:=0; commission_bps integer:=0; platform_fee bigint:=0; producer_net bigint:=0; payment_status_value text:='not_required'; payment_expires timestamptz:=null;
begin
  if p_idempotency_key is null or char_length(p_idempotency_key) not between 8 and 200 then raise exception 'invalid_idempotency_key' using errcode='22023'; end if;
  if p_request_hash is null or p_request_hash !~ '^[a-f0-9]{64}$' then raise exception 'invalid_request_hash' using errcode='22023'; end if;
  if p_event_reference is null or char_length(btrim(p_event_reference)) not between 1 and 200 then raise exception 'invalid_event' using errcode='22023'; end if;
  if char_length(btrim(coalesce(p_guest_name,''))) not between 2 and 120 then raise exception 'invalid_name' using errcode='22023'; end if;
  if char_length(normalized_email)>254 or normalized_email !~* '^[a-z0-9.!#$%&''*+/=?^_`{|}~-]+@[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+$' then raise exception 'invalid_email' using errcode='22023'; end if;
  if char_length(btrim(coalesce(p_guest_phone,''))) not between 7 and 40 then raise exception 'invalid_phone' using errcode='22023'; end if;
  if p_guest_count is null or p_guest_count not between 1 and 20 then raise exception 'invalid_guest_count' using errcode='22023'; end if;
  if p_notes is not null and char_length(p_notes)>1000 then raise exception 'invalid_notes' using errcode='22023'; end if;
  if p_ip_hash is null or p_ip_hash !~ '^[a-f0-9]{64}$' then raise exception 'invalid_ip_hash' using errcode='22023'; end if;

  select * into existing_key from private.idempotency_keys where key=p_idempotency_key and scope='event_reservation';
  if existing_key.key is not null then if existing_key.request_hash<>p_request_hash then raise exception 'idempotency_key_reused' using errcode='22023'; end if; if existing_key.completed_at is not null then return existing_key.response_body; end if; end if;

  select e.* into target_event from public.events e where e.id::text=btrim(p_event_reference) or e.legacy_id=btrim(p_event_reference) or e.slug=btrim(p_event_reference)
  order by case when e.id::text=btrim(p_event_reference) then 0 when e.legacy_id=btrim(p_event_reference) then 1 else 2 end limit 1 for update;
  if target_event.id is null or target_event.status not in ('published','sold_out') then raise exception 'event_not_available' using errcode='22023'; end if;
  if target_event.starts_at<=timezone('utc',now()) then raise exception 'event_already_started' using errcode='22023'; end if;
  if target_event.reservation_deadline is not null and target_event.reservation_deadline<timezone('utc',now()) then raise exception 'reservation_deadline_passed' using errcode='22023'; end if;

  perform private.expire_event_payment_holds_v1(target_event.id);
  select coalesce(sum(r.guest_count),0) into reserved_guest_count from public.event_reservations r
   left join private.event_reservation_finance f on f.reservation_id=r.id
   where r.event_id=target_event.id and (r.status in ('pending','confirmed','attended') or (r.status='pending_payment' and f.payment_status='pending' and f.payment_expires_at>timezone('utc',now())));
  if target_event.status='sold_out' and (target_event.capacity is null or reserved_guest_count<target_event.capacity) then update public.events set status='published',updated_at=timezone('utc',now()) where id=target_event.id; target_event.status:='published'; end if;

  is_paid:=target_event.ticket_price_minor>0;
  if is_paid then
    if caller_id is null then raise exception 'authentication_required_for_paid_event' using errcode='42501'; end if;
    if not exists(select 1 from public.profiles p where p.id=caller_id and p.status='active' and p.deleted_at is null) then raise exception 'active_account_required' using errcode='42501'; end if;
    linked_user_id:=caller_id;
    total_minor:=target_event.ticket_price_minor*p_guest_count;
    if total_minor<=0 then raise exception 'invalid_event_payment_total' using errcode='55000'; end if;
    commission_bps:=case when target_event.producer_id is null then 10000 else target_event.platform_commission_basis_points end;
    if commission_bps not between 0 and 10000 then raise exception 'invalid_event_commission' using errcode='55000'; end if;
    platform_fee:=round((total_minor::numeric*commission_bps::numeric)/10000)::bigint;
    producer_net:=total_minor-platform_fee;
  elsif caller_id is not null and exists(select 1 from public.profiles p where p.id=caller_id and p.status='active' and p.deleted_at is null) then linked_user_id:=caller_id; end if;

  insert into private.idempotency_keys(key,scope,request_hash,locked_at,expires_at) values(p_idempotency_key,'event_reservation',p_request_hash,timezone('utc',now()),timezone('utc',now())+interval '24 hours') on conflict(key) do nothing;
  if not found then select * into existing_key from private.idempotency_keys where key=p_idempotency_key; if existing_key.scope<>'event_reservation' or existing_key.request_hash<>p_request_hash then raise exception 'idempotency_key_reused' using errcode='22023'; end if; if existing_key.completed_at is not null then return existing_key.response_body; end if; raise exception 'request_in_progress' using errcode='40001'; end if;
  if (select count(*) from private.submission_attempts where scope='event_reservation' and ip_hash=p_ip_hash and created_at>timezone('utc',now())-interval '1 hour')>=10 then raise exception 'rate_limit_exceeded' using errcode='P0001'; end if;
  if exists(select 1 from public.event_reservations r where r.event_id=target_event.id and lower(r.guest_email)=normalized_email and r.status in ('pending_payment','pending','confirmed','waitlisted','attended')) then raise exception 'duplicate_reservation' using errcode='23505'; end if;

  reservation_status:=case when target_event.status='sold_out' then 'waitlisted' when target_event.capacity is not null and reserved_guest_count+p_guest_count>target_event.capacity then 'waitlisted' when is_paid then 'pending_payment' else 'pending' end;
  if reservation_status='pending_payment' then payment_status_value:='pending'; payment_expires:=timezone('utc',now())+interval '20 minutes'; end if;
  reservation_code_value:='GOE-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10));
  insert into private.submission_attempts(scope,ip_hash,request_hash) values('event_reservation',p_ip_hash,p_request_hash);
  insert into public.event_reservations(event_id,user_id,reservation_code,guest_name,guest_email,guest_phone,guest_count,notes,status)
  values(target_event.id,linked_user_id,reservation_code_value,btrim(p_guest_name),normalized_email,btrim(p_guest_phone),p_guest_count,nullif(btrim(coalesce(p_notes,'')),''),reservation_status) returning id into reservation_id;

  if is_paid then
    insert into private.event_reservation_finance(reservation_id,event_id,user_id,producer_id,ticket_price_minor,guest_count,total_minor,currency,commission_basis_points_snapshot,platform_fee_minor,producer_net_minor,payment_status,payment_expires_at)
    values(reservation_id,target_event.id,linked_user_id,target_event.producer_id,target_event.ticket_price_minor,p_guest_count,total_minor,target_event.currency,commission_bps,platform_fee,producer_net,payment_status_value,payment_expires);
  end if;

  if target_event.capacity is not null and reservation_status<>'waitlisted' and reserved_guest_count+p_guest_count>=target_event.capacity then update public.events set status='sold_out',updated_at=timezone('utc',now()) where id=target_event.id and status='published'; end if;
  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload) values('event_reservation',reservation_id,'event.reservation_received',jsonb_build_object('reservation_id',reservation_id,'event_id',target_event.id,'status',reservation_status,'user_id',linked_user_id,'requires_payment',reservation_status='pending_payment'));
  response_payload:=jsonb_build_object('ok',true,'reservationId',reservation_id,'reservationCode',reservation_code_value,'status',reservation_status,'requiresPayment',reservation_status='pending_payment','amountMinor',case when is_paid then total_minor else 0 end,'currency',target_event.currency,'paymentExpiresAt',payment_expires);
  update private.idempotency_keys set response_status=201,response_body=response_payload,completed_at=timezone('utc',now()) where key=p_idempotency_key;
  return response_payload;
end;$function$;

CREATE OR REPLACE FUNCTION private.submit_producer_application_v4(p_application_id uuid, p_documents jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  application public.producer_applications%rowtype;
  document_item jsonb;
  document_type text;
  storage_path text;
  object_metadata jsonb;
  mime_type text;
  size_bytes bigint;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;

  select a.* into application
  from public.producer_applications a
  where a.id=p_application_id and a.applicant_user_id=caller_id
  for update;
  if application.id is null then raise exception 'producer_application_not_found' using errcode='P0002'; end if;
  if application.status in ('submitted','under_review','approved') then
    return jsonb_build_object('application_id',p_application_id,'status',application.status);
  end if;
  if application.status not in ('draft','needs_information') then raise exception 'producer_application_not_submittable' using errcode='55000'; end if;
  if not exists(select 1 from private.producer_application_kyc k where k.application_id=p_application_id) then raise exception 'producer_kyc_required' using errcode='22023'; end if;
  if cardinality(application.activity_types)=0 then raise exception 'producer_activity_required' using errcode='22023'; end if;
  if cardinality(application.product_categories)=0 then raise exception 'producer_category_scope_required' using errcode='22023'; end if;
  if cardinality(application.sourcing_models)=0 or not (application.sourcing_models <@ array['own_production','family_production','cooperative_production']::text[]) then
    raise exception 'producer_intermediary_source_not_allowed' using errcode='22023';
  end if;
  if not application.village_product_commitment then raise exception 'village_product_commitment_required' using errcode='22023'; end if;
  if not application.traceability_commitment then raise exception 'traceability_commitment_required' using errcode='22023'; end if;
  if not application.product_truth_commitment then raise exception 'product_truth_commitment_required' using errcode='22023'; end if;

  if p_documents is null or jsonb_typeof(p_documents)<>'array' or jsonb_array_length(p_documents)>6 then raise exception 'invalid_producer_documents' using errcode='22023'; end if;
  for document_item in select value from jsonb_array_elements(p_documents)
  loop
    document_type:=document_item->>'document_type';
    storage_path:=document_item->>'storage_path';
    if document_type not in ('identity','cks','organic_certificate','business_registration','tax_certificate','bank_proof','food_business_registration','food_business_approval','tax_exemption_certificate','mersis_record','cooperative_registration','residence_proof','other') then
      raise exception 'invalid_producer_document_type' using errcode='22023';
    end if;
    if storage_path is null or storage_path not like caller_id::text||'/'||p_application_id::text||'/%' then raise exception 'invalid_producer_document_path' using errcode='22023'; end if;
    select o.metadata into object_metadata from storage.objects o where o.bucket_id='producer-documents' and o.name=storage_path;
    if object_metadata is null then raise exception 'producer_document_not_uploaded' using errcode='P0002'; end if;
    mime_type:=coalesce(object_metadata->>'mimetype','application/octet-stream');
    size_bytes:=case when coalesce(object_metadata->>'size','')~'^[0-9]+$' then (object_metadata->>'size')::bigint else 0 end;
    if mime_type not in ('application/pdf','image/jpeg','image/png','image/webp') or size_bytes<=0 or size_bytes>20971520 then
      raise exception 'invalid_producer_document_metadata' using errcode='22023';
    end if;
    insert into private.producer_documents(application_id,document_type,storage_path,mime_type,size_bytes,checksum_sha256)
    values(p_application_id,document_type,storage_path,mime_type,size_bytes,null)
    on conflict(application_id,document_type,storage_path) do update set mime_type=excluded.mime_type,size_bytes=excluded.size_bytes;
  end loop;

  if application.applicant_type='individual' and not exists(
    select 1 from private.producer_documents d where d.application_id=p_application_id and d.document_type='identity' and d.verification_status<>'rejected') then
    raise exception 'identity_document_required' using errcode='22023';
  end if;
  if application.applicant_type='business' and not exists(
    select 1 from private.producer_documents d where d.application_id=p_application_id and d.document_type in ('tax_certificate','business_registration') and d.verification_status<>'rejected') then
    raise exception 'business_document_required' using errcode='22023';
  end if;
  if application.seller_classification='tax_exempt_artisan' and not exists(
    select 1 from private.producer_documents d where d.application_id=p_application_id and d.document_type='tax_exemption_certificate' and d.verification_status<>'rejected') then
    raise exception 'tax_exemption_document_required' using errcode='22023';
  end if;
  if application.food_compliance_status='registered' and not exists(
    select 1 from private.producer_documents d where d.application_id=p_application_id and d.document_type='food_business_registration' and d.verification_status<>'rejected') then
    raise exception 'food_registration_document_required' using errcode='22023';
  end if;
  if application.food_compliance_status='approved_facility' and not exists(
    select 1 from private.producer_documents d where d.application_id=p_application_id and d.document_type='food_business_approval' and d.verification_status<>'rejected') then
    raise exception 'food_approval_document_required' using errcode='22023';
  end if;
  if application.food_compliance_status='primary_production_review' and not exists(
    select 1 from private.producer_documents d where d.application_id=p_application_id and d.document_type='cks' and d.verification_status<>'rejected') then
    raise exception 'primary_producer_document_required' using errcode='22023';
  end if;
  if application.organic_claim_status='certified' and not exists(
    select 1 from private.producer_documents d where d.application_id=p_application_id and d.document_type='organic_certificate' and d.verification_status<>'rejected') then
    raise exception 'organic_certificate_document_required' using errcode='22023';
  end if;

  update public.producer_applications a set status='submitted',submitted_at=timezone('utc',now()),reviewed_at=null,reviewed_by=null,rejection_reason=null,updated_at=timezone('utc',now()) where a.id=p_application_id;

  insert into public.notifications(user_id,type,title,message,action_url,metadata)
  select r.user_id,'producer','Yeni üretici başvurusu','Yeni bir üretici başvurusu inceleme bekliyor.',
         '/?tab=admin&adminView=vendor-applications',jsonb_build_object('application_id',p_application_id)
  from private.user_roles r
  where r.role in ('admin','super_admin') and (r.expires_at is null or r.expires_at>timezone('utc',now()))
  on conflict do nothing;

  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
  values('producer_application',p_application_id,'producer_application.submitted',jsonb_build_object('application_id',p_application_id,'applicant_user_id',caller_id));

  return jsonb_build_object('application_id',p_application_id,'status','submitted');
end;
$function$;

CREATE OR REPLACE FUNCTION private.submit_verified_review_v1(p_order_item_id uuid, p_rating integer, p_title text, p_body text, p_media_paths text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); target record; review_row public.reviews%rowtype; normalized_title text:=nullif(btrim(coalesce(p_title,'')),''); normalized_body text:=btrim(coalesce(p_body,'')); normalized_media text[];
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  perform private.require_current_terms_v1();
  if p_rating not between 1 and 5 then raise exception 'invalid_review_rating' using errcode='22023'; end if;
  if normalized_title is not null and char_length(normalized_title)>120 then raise exception 'review_title_too_long' using errcode='22023'; end if;
  if char_length(normalized_body) not between 10 and 3000 then raise exception 'invalid_review_body' using errcode='22023'; end if;
  normalized_media:=private.validate_review_media_paths_v1(p_media_paths);
  select item.id as order_item_id,item.product_id,customer_order.id as order_id,customer_order.status as order_status,product.producer_id,producer.owner_user_id into target from public.order_items item join public.orders customer_order on customer_order.id=item.order_id join public.products product on product.id=item.product_id join public.producers producer on producer.id=product.producer_id where item.id=p_order_item_id and customer_order.user_id=caller_id;
  if target.order_item_id is null then raise exception 'purchased_item_not_found' using errcode='P0002'; end if;
  if target.order_status not in ('delivered','completed') then raise exception 'review_requires_delivered_order' using errcode='55000'; end if;
  if target.owner_user_id=caller_id then raise exception 'producer_cannot_review_own_product' using errcode='42501'; end if;
  if exists(select 1 from public.reviews r where r.order_item_id=target.order_item_id) then raise exception 'review_already_exists_for_order_item' using errcode='23505'; end if;
  insert into public.reviews(user_id,product_id,order_item_id,rating,title,body,media_paths,status,is_verified_purchase) values(caller_id,target.product_id,target.order_item_id,p_rating,normalized_title,normalized_body,normalized_media,'pending',true) returning * into review_row;
  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload) values('review',review_row.id,'review.submitted',jsonb_build_object('review_id',review_row.id,'product_id',review_row.product_id,'user_id',caller_id));
  return jsonb_build_object('id',review_row.id,'productId',review_row.product_id,'orderItemId',review_row.order_item_id,'rating',review_row.rating,'status',review_row.status,'verifiedPurchase',true);
end; $function$;

CREATE OR REPLACE FUNCTION private.subscribe_newsletter_v1(p_email text, p_locale text, p_consent_version text, p_source text DEFAULT 'app'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); linked_user_id uuid; email_value text:=lower(btrim(coalesce(p_email,''))); locale_value text:=lower(btrim(coalesce(p_locale,'tr'))); source_value text:=lower(btrim(coalesce(p_source,'app'))); confirm_raw text; unsubscribe_raw text; sub private.newsletter_subscriptions%rowtype;
begin
  if char_length(email_value)>254 or email_value !~* '^[a-z0-9.!#$%&''*+/=?^_`{|}~-]+@[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+$' then raise exception 'invalid_email' using errcode='22023'; end if;
  if locale_value not in ('tr','en','de','fr','ku','ar') then raise exception 'invalid_locale' using errcode='22023'; end if;
  if char_length(btrim(coalesce(p_consent_version,''))) not between 1 and 80 then raise exception 'consent_version_required' using errcode='22023'; end if;
  if char_length(source_value) not between 2 and 40 then raise exception 'invalid_source' using errcode='22023'; end if;
  if caller_id is not null and exists(select 1 from public.profiles where id=caller_id and status='active' and deleted_at is null) then linked_user_id:=caller_id; end if;

  select * into sub from private.newsletter_subscriptions where email_normalized=email_value for update;
  if sub.id is not null and sub.status='active' then return jsonb_build_object('id',sub.id,'status','active','unchanged',true); end if;

  confirm_raw:=encode(extensions.gen_random_bytes(24),'hex'); unsubscribe_raw:=encode(extensions.gen_random_bytes(24),'hex');
  if sub.id is null then
    insert into private.newsletter_subscriptions(email_normalized,user_id,locale,status,consent_version,consented_at,confirmation_token_hash,unsubscribe_token_hash,source)
    values(email_value,linked_user_id,locale_value,'pending',btrim(p_consent_version),timezone('utc',now()),private.hash_marketing_token_v1(confirm_raw),private.hash_marketing_token_v1(unsubscribe_raw),source_value)
    returning * into sub;
  else
    update private.newsletter_subscriptions
    set user_id=coalesce(linked_user_id,user_id),locale=locale_value,status='pending',consent_version=btrim(p_consent_version),consented_at=timezone('utc',now()),confirmed_at=null,unsubscribed_at=null,
        confirmation_token_hash=private.hash_marketing_token_v1(confirm_raw),unsubscribe_token_hash=private.hash_marketing_token_v1(unsubscribe_raw),source=source_value,updated_at=timezone('utc',now())
    where id=sub.id returning * into sub;
  end if;

  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
  values('newsletter_subscription',sub.id,'newsletter.confirmation_requested',jsonb_build_object('subscription_id',sub.id,'email',email_value,'locale',locale_value,'confirmationToken',confirm_raw,'unsubscribeToken',unsubscribe_raw,'consentVersion',sub.consent_version));
  return jsonb_build_object('id',sub.id,'status','pending','email',email_value);
end;
$function$;

CREATE OR REPLACE FUNCTION private.subscribe_stock_alert_v1(p_variant_id uuid, p_email text DEFAULT NULL::text, p_locale text DEFAULT 'tr'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid(); linked_user_id uuid; email_value text:=lower(btrim(coalesce(p_email,auth.jwt()->>'email',''))); locale_value text:=lower(btrim(coalesce(p_locale,'tr')));
  variant_row public.product_variants%rowtype; product_row public.products%rowtype; producer_row public.producers%rowtype; inventory_row public.product_inventory%rowtype;
  sellable integer; token_raw text; token_hash text; subscription_row private.stock_alert_subscriptions%rowtype;
begin
  if locale_value not in ('tr','en','de','fr','ku','ar') then raise exception 'invalid_locale' using errcode='22023'; end if;
  if caller_id is not null and exists(select 1 from public.profiles where id=caller_id and status='active' and deleted_at is null) then linked_user_id:=caller_id; end if;
  if linked_user_id is null and (char_length(email_value)>254 or email_value !~* '^[a-z0-9.!#$%&''*+/=?^_`{|}~-]+@[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+$') then raise exception 'valid_email_required' using errcode='22023'; end if;
  if linked_user_id is not null and email_value<>'' and (char_length(email_value)>254 or email_value !~* '^[a-z0-9.!#$%&''*+/=?^_`{|}~-]+@[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+$') then raise exception 'invalid_email' using errcode='22023'; end if;

  select * into variant_row from public.product_variants where id=p_variant_id and is_active=true;
  if variant_row.id is null then raise exception 'variant_not_available' using errcode='P0002'; end if;
  select * into product_row from public.products where id=variant_row.product_id;
  select * into producer_row from public.producers where id=product_row.producer_id;
  if product_row.status<>'published' or not product_row.is_active or product_row.deleted_at is not null or producer_row.status<>'active' or not producer_row.is_verified or producer_row.deleted_at is not null then raise exception 'product_not_available' using errcode='P0002'; end if;
  if product_row.stock_mode not in ('tracked','seasonal') then return jsonb_build_object('status','not_required','reason','product_not_stock_tracked'); end if;
  select * into inventory_row from public.product_inventory where variant_id=p_variant_id;
  sellable:=greatest(0,coalesce(inventory_row.available_quantity,0)-coalesce(inventory_row.reserved_quantity,0));
  if sellable>0 then return jsonb_build_object('status','available','sellableQuantity',sellable,'variantId',p_variant_id); end if;

  token_raw:=encode(extensions.gen_random_bytes(24),'hex'); token_hash:=private.hash_marketing_token_v1(token_raw);
  if linked_user_id is not null then
    select * into subscription_row from private.stock_alert_subscriptions where user_id=linked_user_id and variant_id=p_variant_id and status='active' limit 1;
  else
    select * into subscription_row from private.stock_alert_subscriptions where email_normalized=email_value and variant_id=p_variant_id and status='active' limit 1;
  end if;
  if subscription_row.id is not null then return jsonb_build_object('id',subscription_row.id,'status','active','variantId',p_variant_id,'unchanged',true); end if;

  insert into private.stock_alert_subscriptions(variant_id,user_id,email_normalized,status,locale,unsubscribe_token_hash)
  values(p_variant_id,linked_user_id,nullif(email_value,''),'active',locale_value,token_hash)
  returning * into subscription_row;

  if linked_user_id is null and email_value<>'' then
    insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
    values('stock_alert',subscription_row.id,'stock_alert.subscribed',jsonb_build_object('subscription_id',subscription_row.id,'email',email_value,'locale',locale_value,'unsubscribeToken',token_raw,'productName',product_row.name,'variantName',variant_row.name));
  end if;
  return jsonb_build_object('id',subscription_row.id,'status','active','variantId',p_variant_id,'productId',product_row.id);
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_activate_official_catalog_products_atomic_v1(p_product_ids uuid[], p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  clean_reason text:=nullif(btrim(coalesce(p_reason,'')),'');
  candidate_ids uuid[]:='{}'::uuid[];
  requested_count integer:=0;
  distinct_count integer:=0;
  safe_count integer:=0;
  activated_count integer:=0;
begin
  if caller_id is null
    or not coalesce(private.has_permission('product.moderate'),false)
    or not coalesce(private.has_permission('product.publish'),false)
    or not coalesce(private.has_permission('product.approve'),false) then
    raise exception 'permission_required:product.publish' using errcode='42501';
  end if;
  if p_product_ids is null or cardinality(p_product_ids)=0 then raise exception 'product_ids_required' using errcode='22023'; end if;
  requested_count:=cardinality(p_product_ids);
  if requested_count>500 then raise exception 'bulk_product_limit_exceeded' using errcode='22023'; end if;
  if array_position(p_product_ids,null) is not null then raise exception 'product_id_required' using errcode='22023'; end if;
  select count(distinct value)::integer into distinct_count from unnest(p_product_ids) u(value);
  if distinct_count<>requested_count then raise exception 'duplicate_product_ids' using errcode='22023'; end if;
  if clean_reason is not null and char_length(clean_reason)>2000 then raise exception 'product_review_reason_too_long' using errcode='22023'; end if;

  select coalesce(array_agg(locked.id order by locked.created_at,locked.id),'{}'::uuid[])
  into candidate_ids
  from (
    select p.id,p.created_at
    from public.products p
    join public.producers pr on pr.id=p.producer_id
    where p.id=any(p_product_ids)
      and p.deleted_at is null
      and pr.deleted_at is null
      and pr.store_kind='official'
      and p.status='published'
      and p.is_active=false
    order by p.created_at,p.id
    for update of p
  ) locked;
  if cardinality(candidate_ids)<>requested_count then raise exception 'official_catalog_activation_set_mismatch' using errcode='55000'; end if;

  select count(*)::integer into safe_count
  from public.products p
  join public.producers pr on pr.id=p.producer_id
  where p.id=any(candidate_ids)
    and p.deleted_at is null and pr.deleted_at is null
    and pr.store_kind='official' and p.status='published' and p.is_active=false
    and pr.status='active' and pr.is_verified=true
    and private.is_producer_trust_badge_active_v1(p.producer_id)
    and lower(btrim(coalesce(p.origin,'')))=lower(btrim(coalesce(pr.production_location,'')))
    and char_length(btrim(coalesce(p.name,'')))>=2
    and char_length(btrim(coalesce(p.description,'')))>=20
    and char_length(btrim(coalesce(p.story,'')))>=20
    and char_length(btrim(coalesce(p.origin,'')))>=2
    and exists(select 1 from public.categories c where c.id=p.category_id and c.is_active=true)
    and exists(select 1 from public.product_variants v where v.product_id=p.id and v.is_active=true and v.price_minor>0)
    and exists(select 1 from public.content_entries e where e.related_product_id=p.id and e.content_type='product_health' and e.locale='tr' and e.status='published' and e.deleted_at is null)
    and exists(select 1 from private.product_editorial_drafts d where d.product_id=p.id and d.locale='tr' and d.status='approved')
    and private.product_media_integrity_ok_v1(p.id);
  if safe_count<>requested_count then raise exception 'official_catalog_activation_readiness_failed' using errcode='55000'; end if;

  perform private.write_admin_audit_v2(
    'product.official_catalog_activation_requested','product_batch',caller_id::text,null,
    jsonb_build_object('requestedCount',requested_count,'atomic',true),
    jsonb_build_object('mode','super_admin_official_catalog_activation','reason',clean_reason),null
  );

  update public.products p
  set is_active=true,updated_at=timezone('utc',now())
  where p.id=any(candidate_ids) and p.status='published' and p.is_active=false;
  get diagnostics activated_count=row_count;
  if activated_count<>requested_count then raise exception 'official_catalog_activation_count_mismatch' using errcode='55000'; end if;

  perform private.write_admin_audit_v2(
    'product.official_catalog_activation_completed','product_batch',caller_id::text,
    jsonb_build_object('publishedInactive',requested_count),
    jsonb_build_object('publishedActive',activated_count),
    jsonb_build_object('mode','super_admin_official_catalog_activation','reason',clean_reason,'atomic',true),null
  );

  return jsonb_build_object('requestedCount',requested_count,'activatedCount',activated_count,'atomic',true,'active',true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_add_platform_expense_v1(p_spent_on date, p_category text, p_description text, p_amount_minor bigint, p_currency text, p_external_reference text DEFAULT NULL::text, p_receipt_path text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); category_value text:=lower(btrim(coalesce(p_category,''))); description_value text:=btrim(coalesce(p_description,'')); currency_value text:=upper(btrim(coalesce(p_currency,''))); ref_value text:=nullif(btrim(coalesce(p_external_reference,'')),''); receipt_value text:=nullif(btrim(coalesce(p_receipt_path,'')),''); row private.platform_expenses%rowtype;
begin
 if caller_id is null or not coalesce(private.has_permission('finance.manage'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
 if p_spent_on is null or p_spent_on>timezone('utc',now())::date then raise exception 'invalid_expense_date' using errcode='22023'; end if;
 if category_value not in('payment_fee','shipping_subsidy','marketing','software','staff','tax_accounting','refund_loss','bank_fee','legal','other') then raise exception 'invalid_expense_category' using errcode='22023'; end if;
 if char_length(description_value) not between 3 and 1000 then raise exception 'invalid_expense_description' using errcode='22023'; end if;
 if p_amount_minor is null or p_amount_minor<=0 or p_amount_minor>100000000000000 then raise exception 'invalid_expense_amount' using errcode='22023'; end if;
 if currency_value!~'^[A-Z]{3}$' then raise exception 'invalid_currency' using errcode='22023'; end if;
 if ref_value is not null and char_length(ref_value)>300 then raise exception 'invalid_expense_reference' using errcode='22023'; end if;
 if receipt_value is not null and (char_length(receipt_value)>1200 or receipt_value~'^[a-z][a-z0-9+.-]*:') then raise exception 'invalid_expense_receipt' using errcode='22023'; end if;
 if exists(select 1 from private.accounting_periods ap where ap.currency=currency_value and p_spent_on between ap.period_from and ap.period_to) then raise exception 'closed_period_cannot_accept_expense' using errcode='55000'; end if;
 insert into private.platform_expenses(spent_on,category,description,amount_minor,currency,external_reference,receipt_path,created_by) values(p_spent_on,category_value,description_value,p_amount_minor,currency_value,ref_value,receipt_value,caller_id) returning * into row;
 return jsonb_build_object('id',row.id,'spentOn',row.spent_on,'category',row.category,'description',row.description,'amountMinor',row.amount_minor,'currency',row.currency,'status',row.status,'externalReference',row.external_reference,'receiptPath',row.receipt_path,'createdAt',row.created_at);
end;$function$;

CREATE OR REPLACE FUNCTION private.super_admin_anonymize_closed_user_v1(p_user_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  reason_value text:=btrim(coalesce(p_reason,''));
  profile_row public.profiles%rowtype;
  open_orders integer;
  open_returns integer;
  avatar_path text;
  review_media jsonb;
  anon_email text;
begin
  if caller_id is null or not coalesce(private.has_permission('user.erase'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
  if p_user_id=caller_id then raise exception 'cannot_anonymize_current_user' using errcode='42501'; end if;
  if char_length(reason_value) not between 8 and 1000 then raise exception 'anonymization_reason_required' using errcode='22023'; end if;
  select * into profile_row from public.profiles where id=p_user_id for update;
  if profile_row.id is null then raise exception 'user_not_found' using errcode='P0002'; end if;
  if profile_row.status<>'deleted' then raise exception 'account_must_be_closed_before_anonymization' using errcode='55000'; end if;
  if exists(select 1 from private.user_roles where user_id=p_user_id and role in ('admin','super_admin')) then raise exception 'privileged_account_cannot_be_anonymized_here' using errcode='42501'; end if;

  select count(*)::integer into open_orders from public.orders where user_id=p_user_id and status not in ('completed','cancelled','refunded');
  select count(*)::integer into open_returns from public.return_requests where user_id=p_user_id and status not in ('rejected','refunded','closed');
  if open_orders>0 or open_returns>0 then raise exception 'open_commerce_records_prevent_anonymization' using errcode='55000'; end if;

  avatar_path:=profile_row.avatar_path;
  select coalesce(jsonb_agg(path),'[]'::jsonb) into review_media
  from (select unnest(media_paths) path from public.reviews where user_id=p_user_id) media;

  delete from public.addresses where user_id=p_user_id;
  delete from public.favorites where user_id=p_user_id;
  delete from public.carts where user_id=p_user_id;
  delete from public.notifications where user_id=p_user_id;
  delete from private.content_favorites where user_id=p_user_id;
  delete from private.producer_follows where user_id=p_user_id;
  delete from private.stock_alert_subscriptions where user_id=p_user_id;
  delete from private.user_app_preferences where user_id=p_user_id;
  delete from private.user_notification_preferences where user_id=p_user_id;
  delete from private.newsletter_subscriptions where user_id=p_user_id;
  delete from private.customer_payment_methods where user_id=p_user_id;
  delete from private.payment_provider_customers where user_id=p_user_id;
  delete from private.order_payment_preferences where user_id=p_user_id;
  delete from private.device_push_tokens where user_id=p_user_id;
  delete from private.push_deliveries where user_id=p_user_id;
  delete from private.contact_messages where user_id=p_user_id;
  delete from private.user_security_contexts where user_id=p_user_id;
  delete from private.user_roles where user_id=p_user_id;

  update public.event_reservations set guest_name='Silinmiş Kullanıcı',guest_email='deleted-'||substr(p_user_id::text,1,8)||'@invalid.local',guest_phone='0000000000',notes=null,updated_at=timezone('utc',now()) where user_id=p_user_id;
  update public.reviews set media_paths='{}'::text[],updated_at=timezone('utc',now()) where user_id=p_user_id;
  update public.profiles set display_name='Silinmiş Kullanıcı',avatar_path=null,phone=null,marketing_consent=false,marketing_consent_at=null,last_seen_at=null,updated_at=timezone('utc',now()) where id=p_user_id;

  delete from auth.refresh_tokens where user_id=p_user_id::text;
  delete from auth.sessions where user_id=p_user_id;
  delete from auth.identities where user_id=p_user_id;
  anon_email:='deleted+'||replace(p_user_id::text,'-','')||'@invalid.local';
  update auth.users set email=anon_email,phone=null,banned_until='infinity'::timestamptz,raw_user_meta_data='{}'::jsonb,updated_at=timezone('utc',now()) where id=p_user_id;

  insert into private.account_enforcement_events(user_id,actor_user_id,action,reason,metadata)
    values(p_user_id,caller_id,'anonymized',reason_value,jsonb_build_object('ordersPreserved',(select count(*) from public.orders where user_id=p_user_id),'paymentsPreserved',(select count(*) from public.payment_records where user_id=p_user_id),'reviewsPreserved',(select count(*) from public.reviews where user_id=p_user_id)));

  return jsonb_build_object('id',p_user_id,'status','anonymized','avatarPath',avatar_path,'reviewMediaPaths',review_media,'ordersPreserved',(select count(*) from public.orders where user_id=p_user_id),'paymentsPreserved',(select count(*) from public.payment_records where user_id=p_user_id));
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_bulk_publish_products_atomic_v1(p_product_ids uuid[], p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  clean_reason text:=nullif(btrim(coalesce(p_reason,'')),'');
  candidate_ids uuid[]:='{}'::uuid[];
  candidate_id uuid;
  product_name text;
  item_result jsonb;
  results jsonb:='[]'::jsonb;
  requested_count integer:=0;
  distinct_count integer:=0;
begin
  if caller_id is null
    or not coalesce(private.has_permission('product.moderate'),false)
    or not coalesce(private.has_permission('product.publish'),false) then
    raise exception 'permission_required:product.publish' using errcode='42501';
  end if;
  if not coalesce(private.has_permission('product.approve'),false) then
    raise exception 'permission_required:product.approve' using errcode='42501';
  end if;
  if p_product_ids is null or cardinality(p_product_ids)=0 then raise exception 'product_ids_required' using errcode='22023'; end if;
  requested_count:=cardinality(p_product_ids);
  if requested_count>500 then raise exception 'bulk_product_limit_exceeded' using errcode='22023'; end if;
  if array_position(p_product_ids,null) is not null then raise exception 'product_id_required' using errcode='22023'; end if;
  select count(distinct value)::integer into distinct_count from unnest(p_product_ids) as u(value);
  if distinct_count<>requested_count then raise exception 'duplicate_product_ids' using errcode='22023'; end if;
  if clean_reason is not null and char_length(clean_reason)>2000 then raise exception 'product_review_reason_too_long' using errcode='22023'; end if;

  select coalesce(array_agg(locked.id order by locked.created_at,locked.id),'{}'::uuid[])
    into candidate_ids
  from (
    select p.id,p.created_at
    from public.products p
    where p.id=any(p_product_ids) and p.deleted_at is null
    order by p.created_at,p.id
    for update
  ) locked;
  if cardinality(candidate_ids)<>requested_count then raise exception 'bulk_product_set_mismatch' using errcode='55000'; end if;
  if exists(select 1 from public.products p where p.id=any(candidate_ids) and p.status<>'review') then raise exception 'product_not_reviewable' using errcode='55000'; end if;

  perform private.write_admin_audit_v2(
    'product.bulk_atomic_approval_requested','product_batch',caller_id::text,null,
    jsonb_build_object('requestedCount',requested_count,'approve',true,'atomic',true),
    jsonb_build_object('mode','super_admin_bulk_atomic','reason',clean_reason),null
  );

  foreach candidate_id in array candidate_ids loop
    select p.name into product_name from public.products p where p.id=candidate_id;
    item_result:=private.admin_review_product_v4(candidate_id,true,clean_reason,true,true,true,true);
    results:=results||jsonb_build_array(jsonb_build_object(
      'productId',candidate_id,
      'name',coalesce(product_name,'Ürün'),
      'ok',true,
      'approved',true,
      'errorCode',null,
      'error',null,
      'result',item_result
    ));
  end loop;

  perform private.write_admin_audit_v2(
    'product.bulk_atomic_approval_completed','product_batch',caller_id::text,
    jsonb_build_object('requestedCount',requested_count,'approve',true,'atomic',true),
    jsonb_build_object('successCount',requested_count,'failureCount',0,'approve',true,'atomic',true),
    jsonb_build_object('mode','super_admin_bulk_atomic','reason',clean_reason),null
  );

  return jsonb_build_object(
    'requestedCount',requested_count,
    'successCount',requested_count,
    'failureCount',0,
    'approved',true,
    'atomic',true,
    'results',results
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_bulk_review_products_v1(p_product_ids uuid[] DEFAULT NULL::uuid[], p_approve boolean DEFAULT true, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  clean_reason text:=nullif(btrim(coalesce(p_reason,'')),'');
  candidate_ids uuid[];
  candidate_id uuid;
  item_result jsonb;
  results jsonb:='[]'::jsonb;
  success_count integer:=0;
  failure_count integer:=0;
  total_count integer:=0;
  product_name text;
begin
  if caller_id is null
    or not coalesce(private.has_permission('product.moderate'),false)
    or not coalesce(private.has_permission('product.publish'),false) then
    raise exception 'permission_required:product.publish' using errcode='42501';
  end if;

  if coalesce(p_approve,false) then
    if not coalesce(private.has_permission('product.approve'),false) then
      raise exception 'permission_required:product.approve' using errcode='42501';
    end if;
  elsif not coalesce(private.has_permission('product.reject'),false) then
    raise exception 'permission_required:product.reject' using errcode='42501';
  end if;

  if not coalesce(p_approve,false) then
    if char_length(coalesce(clean_reason,''))<8 then
      raise exception 'product_rejection_reason_required' using errcode='22023';
    end if;
    if char_length(clean_reason)>2000 then
      raise exception 'product_rejection_reason_too_long' using errcode='22023';
    end if;
  elsif clean_reason is not null and char_length(clean_reason)>2000 then
    raise exception 'product_review_reason_too_long' using errcode='22023';
  end if;

  if p_product_ids is not null and cardinality(p_product_ids)>500 then
    raise exception 'bulk_product_limit_exceeded' using errcode='22023';
  end if;

  select coalesce(array_agg(p.id order by p.created_at,p.id),'{}'::uuid[])
    into candidate_ids
  from public.products p
  where p.deleted_at is null
    and p.status='review'
    and (
      p_product_ids is null
      or cardinality(p_product_ids)=0
      or p.id=any(p_product_ids)
    );

  total_count:=cardinality(candidate_ids);
  if total_count>500 then
    raise exception 'bulk_product_limit_exceeded' using errcode='22023';
  end if;

  perform private.write_admin_audit_v2(
    case when coalesce(p_approve,false) then 'product.bulk_approval_requested' else 'product.bulk_rejection_requested' end,
    'product_batch',
    caller_id::text,
    null,
    jsonb_build_object('requestedCount',total_count,'approve',coalesce(p_approve,false)),
    jsonb_build_object('mode','super_admin_bulk','reason',clean_reason),
    null
  );

  foreach candidate_id in array candidate_ids loop
    select p.name into product_name from public.products p where p.id=candidate_id;
    begin
      item_result:=private.admin_review_product_v4(
        candidate_id,
        coalesce(p_approve,false),
        clean_reason,
        true,
        true,
        true,
        true
      );
      success_count:=success_count+1;
      results:=results||jsonb_build_array(jsonb_build_object(
        'productId',candidate_id,
        'name',coalesce(product_name,'Ürün'),
        'ok',true,
        'approved',coalesce(p_approve,false),
        'result',item_result
      ));
    exception when others then
      failure_count:=failure_count+1;
      results:=results||jsonb_build_array(jsonb_build_object(
        'productId',candidate_id,
        'name',coalesce(product_name,'Ürün'),
        'ok',false,
        'approved',coalesce(p_approve,false),
        'errorCode',sqlstate,
        'error',left(sqlerrm,500)
      ));
    end;
  end loop;

  perform private.write_admin_audit_v2(
    case when coalesce(p_approve,false) then 'product.bulk_approval_completed' else 'product.bulk_rejection_completed' end,
    'product_batch',
    caller_id::text,
    null,
    jsonb_build_object('requestedCount',total_count),
    jsonb_build_object('successCount',success_count,'failureCount',failure_count,'approve',coalesce(p_approve,false)),
    jsonb_build_object('mode','super_admin_bulk'),
    null
  );

  return jsonb_build_object(
    'requestedCount',total_count,
    'successCount',success_count,
    'failureCount',failure_count,
    'approved',coalesce(p_approve,false),
    'results',results
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_catalog_media_health_v3()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; begin
  if auth.uid() is null or not coalesce(private.has_permission('product.health_manage'),false) then raise exception 'permission_required:product.health_manage' using errcode='42501'; end if;
  with image_rows as (
    select i.id image_id,i.product_id,p.name product_name,i.storage_path,private.verified_public_storage_path_v1('catalog-public',i.storage_path) normalized_path,o.id object_id,o.metadata,
      case when private.verified_public_storage_path_v1('catalog-public',i.storage_path) is null then 'invalid_path' when o.id is null then 'missing_object' when lower(coalesce(o.metadata->>'mimetype','')) not in ('image/jpeg','image/png','image/webp','image/avif') then 'invalid_mime' when coalesce(o.metadata->>'size','') !~ '^[0-9]{1,12}$' or (o.metadata->>'size')::bigint not between 1 and 10485760 then 'invalid_size' when private.catalog_media_binary_verified_path_v2(i.storage_path) is null then 'unverified_binary' else 'healthy' end status
    from public.product_images i join public.products p on p.id=i.product_id left join private.media_objects_all o on o.bucket_id='catalog-public' and o.name=private.verified_public_storage_path_v1('catalog-public',i.storage_path) and coalesce(o.is_delete_marker,false)=false and o.archived_at is null
  ), orphan_rows as (
    select null::uuid image_id,null::uuid product_id,null::text product_name,o.name storage_path,o.name normalized_path,o.id object_id,o.metadata,'orphan_object'::text status
    from private.media_objects_all o
    where o.bucket_id='catalog-public'
      and coalesce(o.is_delete_marker,false)=false
      and o.archived_at is null
      and lower(coalesce(o.metadata->>'mimetype','')) in ('image/jpeg','image/png','image/webp','image/avif')
      and not private.catalog_public_asset_is_referenced_v1(o.name)
  ), all_rows as (select * from image_rows union all select * from orphan_rows), summary as (
    select count(*) filter(where status='healthy')::integer healthy,count(*) filter(where status='missing_object')::integer missing,count(*) filter(where status='orphan_object')::integer orphan,count(*) filter(where status in ('invalid_path','invalid_mime','invalid_size','unverified_binary'))::integer invalid,count(*)::integer total from all_rows
  )
  select jsonb_build_object('scannedAt',timezone('utc',now()),'lastScheduledScanAt',(select s.last_scanned_at from private.catalog_media_integrity_state_v2 s where s.singleton=true),'lastQuarantinedCount',coalesce((select s.last_quarantined_count from private.catalog_media_integrity_state_v2 s where s.singleton=true),0),'summary',jsonb_build_object('total',summary.total,'healthy',summary.healthy,'missing',summary.missing,'orphan',summary.orphan,'invalid',summary.invalid),'items',coalesce((select jsonb_agg(jsonb_build_object('status',r.status,'productId',r.product_id,'productName',r.product_name,'imageId',r.image_id,'path',r.storage_path) order by r.status,r.product_name nulls last,r.storage_path) from all_rows r where r.status<>'healthy'),'[]'::jsonb)) into result from summary;
  return result;
end;$function$;

CREATE OR REPLACE FUNCTION private.super_admin_cleanup_operational_history_v1(p_period_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); period_row private.accounting_periods%rowtype; cutoff timestamptz; notifications_deleted integer:=0; idempotency_deleted integer:=0; outbox_deleted integer:=0; errors_deleted integer:=0;
begin
 if caller_id is null or not coalesce(private.has_permission('finance.manage'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
 select * into period_row from private.accounting_periods where id=p_period_id for update;
 if period_row.id is null then raise exception 'accounting_period_not_found' using errcode='P0002'; end if;
 cutoff=(period_row.period_to+1)::timestamptz;
 delete from public.notifications where created_at<cutoff and read_at is not null; get diagnostics notifications_deleted=row_count;
 delete from private.idempotency_keys where created_at<cutoff; get diagnostics idempotency_deleted=row_count;
 delete from private.outbox_events where created_at<cutoff and processed_at is not null; get diagnostics outbox_deleted=row_count;
 delete from private.system_error_daily where event_day<period_row.period_from; get diagnostics errors_deleted=row_count;
 update private.accounting_periods set status='archived',archived_at=coalesce(archived_at,timezone('utc',now())),cleanup_completed_at=timezone('utc',now()) where id=p_period_id;
 return jsonb_build_object('id',p_period_id,'notificationsDeleted',notifications_deleted,'idempotencyDeleted',idempotency_deleted,'outboxDeleted',outbox_deleted,'errorDaysDeleted',errors_deleted,'financialRecordsPreserved',true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_close_accounting_period_v1(p_from date, p_to date, p_currency text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 caller_id uuid:=auth.uid();
 currency_value text:=upper(btrim(coalesce(p_currency,'')));
 snapshot_value jsonb;
 period_id uuid;
 archived_count integer;
 reconciliation_delta bigint;
begin
 if caller_id is null or not coalesce(private.has_permission('finance.manage'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
 if p_from is null or p_to is null or p_to<p_from or p_to-p_from>366 then raise exception 'invalid_finance_date_range' using errcode='22023'; end if;
 if currency_value!~'^[A-Z]{3}$' then raise exception 'invalid_currency' using errcode='22023'; end if;
 if exists(select 1 from private.accounting_periods ap where ap.currency=currency_value and daterange(ap.period_from,ap.period_to,'[]') && daterange(p_from,p_to,'[]')) then raise exception 'accounting_period_overlap' using errcode='23505'; end if;
 if exists(select 1 from public.orders o where o.currency=currency_value and coalesce(o.placed_at,o.created_at)>=(p_from::timestamp at time zone 'UTC') and coalesce(o.placed_at,o.created_at)<((p_to+1)::timestamp at time zone 'UTC') and o.status not in('completed','cancelled','refunded')) then raise exception 'open_orders_prevent_period_close' using errcode='55000'; end if;
 if exists(select 1 from public.return_requests rr join public.orders o on o.id=rr.order_id where o.currency=currency_value and coalesce(o.placed_at,o.created_at)>=(p_from::timestamp at time zone 'UTC') and coalesce(o.placed_at,o.created_at)<((p_to+1)::timestamp at time zone 'UTC') and rr.status not in('rejected','refunded','closed')) then raise exception 'open_returns_prevent_period_close' using errcode='55000'; end if;
 snapshot_value:=private.admin_finance_report_v2(p_from,p_to,currency_value);
 reconciliation_delta:=coalesce((snapshot_value#>>'{totals,reconciliation_delta_minor}')::bigint,0);
 if reconciliation_delta<>0 then raise exception 'accounting_reconciliation_required:%',reconciliation_delta using errcode='55000'; end if;
 insert into private.accounting_periods(period_from,period_to,currency,snapshot,closed_by) values(p_from,p_to,currency_value,snapshot_value,caller_id) returning id into period_id;
 update public.orders set accounting_archived_at=timezone('utc',now()),accounting_period_id=period_id where currency=currency_value and coalesce(placed_at,created_at)>=(p_from::timestamp at time zone 'UTC') and coalesce(placed_at,created_at)<((p_to+1)::timestamp at time zone 'UTC') and status in('completed','cancelled','refunded');
 get diagnostics archived_count=row_count;
 return jsonb_build_object('id',period_id,'from',p_from,'to',p_to,'currency',currency_value,'archivedOrderCount',archived_count,'snapshot',snapshot_value);
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_delete_release_origin_v1(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  target private.super_admin_release_origins_v1%rowtype;
  active_count integer;
begin
  if caller_id is null or not coalesce(private.has_permission('system.configure'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
  select * into target from private.super_admin_release_origins_v1 where id=p_id for update;
  if target.id is null then raise exception 'release_origin_not_found' using errcode='P0002'; end if;
  if target.is_primary then raise exception 'primary_release_origin_cannot_be_deleted' using errcode='22023'; end if;
  select count(*)::integer into active_count from private.super_admin_release_origins_v1 where is_active=true;
  if target.is_active and active_count<=1 then raise exception 'last_active_release_origin_cannot_be_deleted' using errcode='22023'; end if;
  delete from private.super_admin_release_origins_v1 where id=p_id;
  insert into private.admin_audit_logs(actor_user_id,action,target_type,target_id,details)
  values(caller_id,'brand.release_origin_deleted','release_origin',target.origin,'{}'::jsonb);
  return private.super_admin_list_release_origins_v1();
end;
$function$;

