CREATE OR REPLACE FUNCTION private.super_admin_get_product_health_editor_v1(p_product_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); p public.products%rowtype; producer public.producers%rowtype; entry public.content_entries%rowtype; requests jsonb;
begin
 if uid is null or not private.has_permission('product.health_manage') then raise exception 'super_admin_required' using errcode='42501'; end if;
 select * into p from public.products where id=p_product_id and deleted_at is null; if p.id is null then raise exception 'product_not_found' using errcode='P0002'; end if;
 select * into producer from public.producers where id=p.producer_id;
 select * into entry from public.content_entries where related_product_id=p_product_id and content_type='product_health' and locale='tr' and status='published' and deleted_at is null order by updated_at desc limit 1;
 select coalesce(jsonb_agg(jsonb_build_object('requestId',r.id,'proposedBy',r.proposed_by,'payload',r.payload,'status',r.status,'createdAt',r.created_at,'updatedAt',r.updated_at) order by r.created_at),'[]'::jsonb) into requests from private.product_health_change_requests r where r.product_id=p_product_id and r.locale='tr' and r.status='pending';
 return jsonb_build_object('productId',p.id,'productName',p.name,'productStatus',p.status,'producerId',producer.id,'producerName',producer.display_name,'canPublish',true,'published',case when entry.id is null then null else jsonb_build_object('contentId',entry.id,'summary',entry.summary,'productInfo',coalesce(entry.metadata->'productInfoV1','{}'::jsonb),'safety',coalesce(entry.metadata->'safetyV2','{}'::jsonb),'recipe',coalesce(entry.metadata->'recipeV1','{}'::jsonb),'updatedAt',entry.updated_at) end,'requests',requests);
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_get_production_readiness_snapshot_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  settings public.brand_settings%rowtype;
  catalog_objects integer:=0; content_objects integer:=0; event_objects integer:=0;
  published_products integer:=0; products_with_real_primary integer:=0;
  active_variants integer:=0; missing_weights integer:=0; estimated_weights integer:=0; verified_weights integer:=0;
  active_producers integer:=0; ready_producer_accounts integer:=0;
  published_legal_slugs text[]:='{}'::text[]; required_legal_slugs constant text[]:=array['about','returns','privacy','terms']; missing_legal_slugs text[];
  payment_cfg jsonb; legal_readiness jsonb; runtime_integrity jsonb;
begin
  if auth.uid() is null or not coalesce(private.has_permission('system.read'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
  select * into settings from public.brand_settings where slug='golden-oremar';
  if settings.slug is null then raise exception 'brand_settings_not_found' using errcode='P0002'; end if;
  legal_readiness:=private.commercial_checkout_legal_readiness_v1();
  runtime_integrity:=private.runtime_dependency_integrity_v1();
  select count(*) into catalog_objects from private.media_objects_all where bucket_id='catalog-public';
  select count(*) into content_objects from private.media_objects_all where bucket_id='content-public';
  select count(*) into event_objects from private.media_objects_all where bucket_id='event-public';
  select count(*) into published_products from public.products p where p.status='published' and p.is_active=true and p.deleted_at is null;
  select count(*) into products_with_real_primary from public.products p where p.status='published' and p.is_active=true and p.deleted_at is null and exists(select 1 from public.product_images pi join private.media_objects_all so on so.bucket_id='catalog-public' and so.name=pi.storage_path where pi.product_id=p.id and pi.is_primary=true);
  select count(*),count(*) filter(where pv.weight_grams is null or pv.weight_grams<=0),count(*) filter(where pv.weight_grams>0 and pv.shipping_weight_source='estimated'),count(*) filter(where pv.weight_grams>0 and pv.shipping_weight_source in ('measured','supplier'))
  into active_variants,missing_weights,estimated_weights,verified_weights
  from public.product_variants pv join public.products p on p.id=pv.product_id
  where pv.is_active=true and p.status='published' and p.is_active=true and p.deleted_at is null;
  select count(*) into active_producers from public.producers p where p.status='active' and p.is_verified=true and p.deleted_at is null;
  select count(*) into ready_producer_accounts from private.producer_payment_accounts pa join public.producers p on p.id=pa.producer_id where p.status='active' and p.is_verified=true and p.deleted_at is null and pa.provider='iyzico' and pa.status='ready' and nullif(btrim(pa.submerchant_key),'') is not null;
  select coalesce(array_agg(distinct ce.slug order by ce.slug),'{}'::text[]) into published_legal_slugs from public.content_entries ce where ce.deleted_at is null and ce.status='published' and ce.locale='tr' and ce.slug=any(required_legal_slugs) and (char_length(btrim(coalesce(ce.body_markdown,'')))>=100 or char_length(btrim(coalesce(ce.body_html_sanitized,'')))>=100);
  select coalesce(array_agg(slug order by slug),'{}'::text[]) into missing_legal_slugs from unnest(required_legal_slugs) slug where not (slug=any(published_legal_slugs));
  payment_cfg:=private.default_payment_control_v1() || coalesce(settings.public_config->'payments','{}'::jsonb);
  return jsonb_build_object(
    'ok',true,'generatedAt',timezone('utc',now()),'integrity',runtime_integrity,
    'businessIdentity',jsonb_build_object('legalNameConfigured',nullif(btrim(coalesce(settings.legal_name,'')),'') is not null,'supportEmailConfigured',nullif(btrim(coalesce(settings.support_email,'')),'') is not null,'supportPhoneConfigured',nullif(btrim(coalesce(settings.support_phone,'')),'') is not null,'registeredLegalNameConfigured',legal_readiness->>'registeredLegalName' is not null,'registeredAddressConfigured',legal_readiness->>'registeredAddress' is not null,'registeredCountryCodeConfigured',legal_readiness->>'countryCode' is not null,'legalDocumentsFinalized',coalesce((legal_readiness->>'legalDocumentsFinalized')::boolean,false),'missing',coalesce(legal_readiness->'missing','[]'::jsonb),'ready',coalesce((legal_readiness->>'ready')::boolean,false)),
    'assets',jsonb_build_object('catalogObjectCount',catalog_objects,'contentObjectCount',content_objects,'eventObjectCount',event_objects,'publishedProductCount',published_products,'publishedProductsWithRealPrimaryImage',products_with_real_primary,'publishedProductsMissingRealPrimaryImage',greatest(published_products-products_with_real_primary,0),'catalogReady',published_products>0 and products_with_real_primary=published_products),
    'legalContent',jsonb_build_object('requiredSlugs',to_jsonb(required_legal_slugs),'publishedSlugs',to_jsonb(published_legal_slugs),'missingSlugs',to_jsonb(missing_legal_slugs),'ready',cardinality(missing_legal_slugs)=0),
    'shipping',jsonb_build_object('activePublishedVariantCount',active_variants,'missingWeightVariantCount',missing_weights,'estimatedWeightVariantCount',estimated_weights,'verifiedWeightVariantCount',verified_weights,'ready',active_variants>0 and missing_weights=0,'verifiedReady',active_variants>0 and missing_weights=0 and estimated_weights=0),
    'producerPayments',jsonb_build_object('activeVerifiedProducerCount',active_producers,'readyProducerPaymentAccountCount',ready_producer_accounts,'missingProducerPaymentAccountCount',greatest(active_producers-ready_producer_accounts,0),'ready',active_producers>0 and ready_producer_accounts=active_producers),
    'paymentControl',jsonb_build_object('provider',payment_cfg->>'provider','checkoutFormEnabled',coalesce((payment_cfg->>'checkout_form_enabled')::boolean,false),'savedCardPaymentsEnabled',coalesce((payment_cfg->>'live_card_payments_enabled')::boolean,false),'cardEnrollmentEnabled',coalesce((payment_cfg->>'card_enrollment_enabled')::boolean,false),'atLeastOneCheckoutFlowEnabled',coalesce((payment_cfg->>'checkout_form_enabled')::boolean,false) or coalesce((payment_cfg->>'live_card_payments_enabled')::boolean,false))
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_get_release_setup_v2()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  settings public.brand_settings%rowtype;
  cfg private.super_admin_company_configuration_v1%rowtype;
  release_config jsonb;
  payment_config jsonb;
  live_origin text;
  live_return text;
begin
  if auth.uid() is null or not coalesce(private.has_permission('system.read'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
  select * into settings from public.brand_settings where slug='golden-oremar';
  select * into cfg from private.super_admin_company_configuration_v1 where singleton=true;
  if settings.slug is null or cfg.singleton is null then raise exception 'brand_settings_not_found' using errcode='P0002'; end if;
  release_config:=coalesce(settings.public_config->'releaseSetup','{}'::jsonb);
  payment_config:=coalesce(settings.public_config->'payments','{}'::jsonb);
  live_origin:=nullif(btrim(coalesce(release_config#>>'{publicShareOrigin,url}','')),'');
  live_return:=nullif(btrim(coalesce(payment_config->>'return_url',release_config#>>'{payment,returnUrl}','')),'');
  return jsonb_build_object(
    'appId',coalesce(nullif(release_config->>'appId',''),'com.goldenoremar.app'),
    'androidApplicationId',coalesce(nullif(release_config->>'androidApplicationId',''),'com.goldenoremar.app'),
    'iosBundleId',coalesce(nullif(release_config->>'iosBundleId',''),'com.goldenoremar.app'),
    'publicOrigin',coalesce(live_origin,cfg.public_origin),
    'publicOriginConfigured',live_origin is not null,
    'iyzicoReturnUrl',coalesce(live_return,cfg.iyzico_return_url),
    'iyzicoReturnUrlConfigured',live_return is not null,
    'iyzicoReturnPath','/payment/iyzico/return',
    'iyzicoEnvironment',cfg.iyzico_environment,
    'transactionalEmailFrom',coalesce(nullif(btrim(coalesce(release_config#>>'{transactionalEmail,from}','')),''),cfg.transactional_email_from),
    'fcmProjectId',coalesce(nullif(btrim(coalesce(release_config#>>'{notifications,fcmProjectId}','')),''),cfg.fcm_project_id),
    'apnsBundleId',coalesce(nullif(btrim(coalesce(release_config#>>'{notifications,apnsBundleId}','')),''),cfg.apns_bundle_id),
    'googleOAuthClientId',coalesce(nullif(btrim(coalesce(release_config#>>'{socialOAuth,googleClientId}','')),''),cfg.google_oauth_client_id),
    'facebookAppId',coalesce(nullif(btrim(coalesce(release_config#>>'{socialOAuth,facebookAppId}','')),''),cfg.facebook_app_id),
    'productionActivated',cfg.production_enabled,
    'secretsPolicy','server_only_never_store_in_public_config',
    'updatedAt',greatest(settings.updated_at,cfg.updated_at)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_list_legal_documents_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
  if auth.uid() is null or not coalesce(private.has_permission('system.read'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'slug',c.slug,'locale',c.locale,'title',c.title,'summary',c.summary,'markdown',c.body_markdown,'status',c.status,'publishedAt',c.published_at,'updatedAt',c.updated_at) order by c.slug,c.locale),'[]'::jsonb)
  into result from public.content_entries c
  where c.content_type='legal' and c.slug in ('about','returns','privacy','terms') and c.deleted_at is null;
  return jsonb_build_object('ok',true,'items',result);
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_list_producer_payouts_v2(p_status text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); status_filter text:=nullif(lower(btrim(coalesce(p_status,''))),''); result jsonb;
begin
  if uid is null or not coalesce(private.has_permission('payout.read'),false) then raise exception 'permission_required:payout.read' using errcode='42501'; end if;
  if status_filter is not null and status_filter not in('requested','scheduled','processing','paid','failed','cancelled') then raise exception 'invalid_payout_status' using errcode='22023'; end if;
  if p_limit not between 1 and 500 or p_offset<0 then raise exception 'invalid_pagination' using errcode='22023'; end if;
  insert into private.sensitive_access_log(actor_user_id,resource_type,resource_id,purpose) values(uid,'producer_payout_queue',uid,'Süper Admin satıcı ödeme kuyruğunu ve ödeme hedefi IBAN bilgilerini görüntüledi.');
  select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'producerId',q.producer_id,'producerName',q.display_name,'ownerUserId',q.owner_user_id,'ownerEmail',q.owner_email,'currency',q.currency,'amountMinor',q.amount_minor,'status',q.status,'channel',q.channel,'requestSource',q.request_source,'sourceOrderId',q.source_order_id,'orderNumber',q.order_number,'provider',q.provider,'providerReference',q.provider_reference,'note',q.note,'destinationAccountHolder',coalesce(q.destination_account_holder,q.current_holder),'destinationIban',coalesce(case when q.destination_iban_ciphertext is not null then private.decrypt_producer_kyc(q.destination_iban_ciphertext) else null end,case when q.current_iban_ciphertext is not null then private.decrypt_producer_kyc(q.current_iban_ciphertext) else null end),'destinationIbanMasked',coalesce(q.destination_iban_masked,private.mask_tr_iban_v1(coalesce(case when q.destination_iban_ciphertext is not null then private.decrypt_producer_kyc(q.destination_iban_ciphertext) else null end,case when q.current_iban_ciphertext is not null then private.decrypt_producer_kyc(q.current_iban_ciphertext) else null end))),'requestedAt',q.requested_at,'scheduledAt',q.scheduled_at,'providerSettlementReleasedAt',q.provider_settlement_released_at,'processedAt',q.processed_at,'createdAt',q.created_at,'balance',private.get_producer_balance_v1(q.producer_id,q.currency)) order by q.created_at desc),'[]'::jsonb) into result
  from (
    select po.*,p.display_name,p.owner_user_id,au.email owner_email,o.order_number,k.bank_account_holder current_holder,k.iban_ciphertext current_iban_ciphertext
    from private.producer_payouts po join public.producers p on p.id=po.producer_id left join auth.users au on au.id=p.owner_user_id left join public.orders o on o.id=po.source_order_id left join private.producer_application_kyc k on k.application_id=p.application_id
    where status_filter is null or po.status=status_filter
    order by po.created_at desc limit p_limit offset p_offset
  ) q;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_list_product_health_changes_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); result jsonb;
begin
 if uid is null or not private.has_permission('product.health_manage') then raise exception 'super_admin_required' using errcode='42501'; end if;
 select coalesce(jsonb_agg(jsonb_build_object('requestId',r.id,'productId',r.product_id,'productName',p.name,'productSlug',p.slug,'producerId',producer.id,'producerName',producer.display_name,'proposedBy',r.proposed_by,'payload',r.payload,'status',r.status,'createdAt',r.created_at,'updatedAt',r.updated_at) order by r.created_at),'[]'::jsonb) into result
 from private.product_health_change_requests r join public.products p on p.id=r.product_id join public.producers producer on producer.id=p.producer_id where r.status='pending';
 return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_list_release_origins_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null or not coalesce(private.has_permission('system.read'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
  return jsonb_build_object('items',coalesce((
    select jsonb_agg(jsonb_build_object(
      'id',id,'origin',origin,'isPrimary',is_primary,'isActive',is_active,'createdAt',created_at,'updatedAt',updated_at
    ) order by is_primary desc, origin)
    from private.super_admin_release_origins_v1
  ),'[]'::jsonb));
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_list_shipping_weight_readiness_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
  if auth.uid() is null or not coalesce(private.has_permission('shipping.read'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'variantId',pv.id,'productId',p.id,'productName',p.name,'variantName',pv.name,'sku',pv.sku,
    'producerId',pr.id,'producerName',pr.display_name,'weightGrams',pv.weight_grams,
    'weightSource',pv.shipping_weight_source,'weightNote',pv.shipping_weight_note,'verifiedAt',pv.shipping_weight_verified_at,
    'missingWeight',pv.weight_grams is null or pv.weight_grams<=0,
    'estimatedWeight',pv.weight_grams>0 and pv.shipping_weight_source='estimated',
    'verifiedWeight',pv.weight_grams>0 and pv.shipping_weight_source in ('measured','supplier'),
    'updatedAt',pv.updated_at
  ) order by (pv.weight_grams is null or pv.weight_grams<=0) desc,(pv.shipping_weight_source='estimated') desc,p.name,pv.name,pv.id),'[]'::jsonb)
  into result
  from public.product_variants pv
  join public.products p on p.id=pv.product_id
  join public.producers pr on pr.id=p.producer_id
  where pv.is_active=true and p.status='published' and p.is_active=true and p.deleted_at is null;
  return jsonb_build_object('ok',true,'items',result);
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_list_storefronts_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
  if auth.uid() is null or not coalesce(private.has_permission('storefront.read'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',p.id,'name',p.display_name,'slug',p.slug,'storeKind',p.store_kind,'status',p.status,'verified',p.is_verified,
    'tier',p.storefront_tier,'theme',p.storefront_theme,'headline',p.storefront_headline,'subheadline',p.storefront_subheadline,
    'realFollowerCount',(select count(*)::bigint from private.producer_follows f where f.producer_id=p.id),
    'launchAudienceCount',p.launch_audience_count,'launchAudienceLabel',p.launch_audience_label,
    'logoPath',private.verified_public_storage_path_v1('catalog-public',p.logo_path),
    'coverPath',private.verified_public_storage_path_v1('catalog-public',p.cover_path),
    'logoReady',private.verified_public_storage_path_v1('catalog-public',p.logo_path) is not null,
    'coverReady',private.verified_public_storage_path_v1('catalog-public',p.cover_path) is not null,
    'location',p.production_location
  ) order by case when p.store_kind='official' then 0 else 1 end,p.display_name),'[]'::jsonb) into result
  from public.producers p
  where p.deleted_at is null and p.status in ('active','suspended') and (p.store_kind='official' or p.owner_user_id is not null);
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_list_transactional_email_jobs_v1(p_status text DEFAULT NULL::text, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare normalized text:=nullif(lower(btrim(coalesce(p_status,''))),'' ); result jsonb;
begin
  if auth.uid() is null or not coalesce(private.has_permission('notification.read'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
  if normalized is not null and normalized not in ('pending','processing','failed','sent','dead_letter') then raise exception 'invalid_email_job_status' using errcode='22023'; end if;
  if p_limit not between 1 and 200 then raise exception 'invalid_limit' using errcode='22023'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',j.id,'kind',j.kind,'aggregateId',j.aggregate_id,'status',j.status,'attempts',j.attempts,'availableAt',j.available_at,'providerMessageId',j.provider_message_id,'lastError',j.last_error,'createdAt',j.created_at,'sentAt',j.sent_at) order by j.created_at desc,j.id desc),'[]'::jsonb)
  into result from (select * from private.transactional_email_jobs where normalized is null or status=normalized order by created_at desc,id desc limit p_limit) j;
  return jsonb_build_object('ok',true,'items',result);
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_media_cdn_status_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s private.media_cdn_settings; plan jsonb;
begin
  if auth.uid() is null or not coalesce(private.has_permission('product.health_manage'), false) then
    raise exception 'permission_required:product.health_manage' using errcode = '42501';
  end if;
  select * into s from private.media_cdn_settings where id;
  plan := private.media_cdn_plan_v1(50);
  return jsonb_build_object(
    'enabled', s.enabled, 'publicBaseUrl', s.public_base_url,
    'objectCount', (select count(*) from private.media_cdn_objects where confirmed),
    'imageCount', (select count(*) from private.media_cdn_objects where confirmed and content_type like 'image/%'),
    'videoCount', (select count(*) from private.media_cdn_objects where confirmed and content_type like 'video/%'),
    'storedBytes', plan->'mirroredBytes',
    'videoBytes', (select coalesce(sum(byte_size),0) from private.media_cdn_objects where content_type like 'video/%'),
    'budgetBytes', s.budget_bytes, 'videoBudgetBytes', s.video_budget_bytes, 'warnBytes', s.warn_bytes,
    'overWarning', (plan->>'mirroredBytes')::bigint >= s.warn_bytes,
    'budgetBlocked', plan->'budgetBlocked',
    'waitingInSupabase', jsonb_array_length(plan->'uploads') + jsonb_array_length(plan->'offloads'),
    'unfinishedUploads', (select count(*) from private.media_cdn_objects where origin = 'direct' and not confirmed),
    'failedObjects', (select count(*) from private.media_cdn_failures where attempts >= 3),
    'lastRunAt', s.last_run_at, 'lastRunStatus', s.last_run_status, 'lastRunDetail', s.last_run_detail);
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_product_publish_readiness_v1(p_query text DEFAULT NULL::text, p_state text DEFAULT 'all'::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  q text:=lower(btrim(coalesce(p_query,'')));
  state_value text:=lower(btrim(coalesce(p_state,'all')));
  q_is_uuid boolean:=q~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
  result jsonb;
begin
  if auth.uid() is null or not coalesce(private.has_permission('product.health_manage'),false) then
    raise exception 'permission_required:product.health_manage' using errcode='42501';
  end if;
  if char_length(q)>120 then raise exception 'search_query_too_long' using errcode='22023'; end if;
  if p_limit not between 1 and 200 or p_offset<0 then raise exception 'invalid_pagination' using errcode='22023'; end if;
  if state_value not in ('all','published','ready','missing_media','data_missing','media_blocked','owner_required') then raise exception 'invalid_readiness_state' using errcode='22023'; end if;

  with flags as (
    select p.id,p.name,p.slug,p.status,p.is_active,p.updated_at,pr.display_name producer_name,pr.store_kind,
      exists(select 1 from public.categories c where c.id=p.category_id and c.is_active=true) category_ok,
      exists(select 1 from public.product_variants v where v.product_id=p.id and v.is_active=true and v.price_minor>0) price_ok,
      char_length(btrim(coalesce(p.description,'')))>=20 description_ok,
      char_length(btrim(coalesce(p.story,'')))>=20 story_ok,
      exists(select 1 from public.content_entries e where e.related_product_id=p.id and e.content_type='product_health' and e.locale='tr' and e.status='published' and e.deleted_at is null) health_ok,
      coalesce(pp.origin_verified,false) origin_ok,
      (pr.id is not null and pr.status='active' and pr.is_verified=true and pr.deleted_at is null) producer_ok,
      (select count(*)::integer from public.product_images i where i.product_id=p.id) image_count,
      exists(select 1 from public.product_images i where i.product_id=p.id and i.is_primary=true) primary_image_row,
      exists(select 1 from public.product_images i where i.product_id=p.id and i.is_primary=true and private.verified_public_storage_path_v1('catalog-public',i.storage_path) is not null) primary_storage_ok,
      exists(select 1 from public.product_images i where i.product_id=p.id and i.is_primary=true and private.catalog_media_binary_verified_path_v2(i.storage_path) is not null) primary_binary_ok,
      private.product_media_integrity_ok_v1(p.id) media_ok
    from public.products p
    left join public.producers pr on pr.id=p.producer_id
    left join public.product_provenance pp on pp.product_id=p.id
    where p.deleted_at is null
  ), classified as (
    select f.*,
      (f.status='published' and f.is_active=true) published,
      (f.category_ok and f.price_ok and f.description_ok and f.story_ok and f.health_ok and f.origin_ok and f.producer_ok) mandatory_ok,
      (f.image_count=0 or not f.primary_storage_ok) missing_real_media,
      (not f.media_ok) media_blocked,
      (f.store_kind='official' and f.image_count=0 and f.media_ok) brand_fallback_allowed,
      f.media_ok media_ready,
      (f.status<>'published' or f.is_active=false) owner_required
    from flags f
  ), enriched as (
    select c.*,
      (not c.published and c.mandatory_ok and c.media_ready) ready,
      (not c.mandatory_ok) data_missing,
      coalesce((select jsonb_agg(jsonb_build_object('code',issue.code,'label',issue.label) order by issue.ord) from (
        select 10 ord,'primary_image_missing' code,'Primary image eksik' label where c.image_count=0 and not c.brand_fallback_allowed
        union all select 15,'primary_image_missing','Primary image eksik' where c.image_count>0 and not c.primary_image_row
        union all select 20,'storage_object_missing','Storage object bulunamadı' where c.primary_image_row and not c.primary_storage_ok
        union all select 30,'binary_verification_missing','Görsel binary doğrulaması eksik' where c.primary_storage_ok and not c.primary_binary_ok
        union all select 40,'media_integrity_failed','Media integrity kontrolü başarısız' where c.image_count>0 and c.primary_image_row and c.primary_storage_ok and c.primary_binary_ok and not c.media_ready
        union all select 50,'category_missing','Kategori eksik veya müşteriye kapalı' where not c.category_ok
        union all select 60,'price_missing','Aktif pozitif fiyatlı varyant eksik' where not c.price_ok
        union all select 70,'description_missing','Ürün açıklaması eksik veya yetersiz' where not c.description_ok
        union all select 80,'story_missing','Ürün hikayesi eksik veya yetersiz' where not c.story_ok
        union all select 90,'health_package_missing','Yayınlanmış Türkçe sağlık paketi eksik' where not c.health_ok
        union all select 100,'origin_not_verified','Ürün menşei doğrulanmamış' where not c.origin_ok
        union all select 110,'producer_not_ready','Üretici aktif ve doğrulanmış değil' where not c.producer_ok
      ) issue),'[]'::jsonb) reasons
    from classified c
  ), filtered as (
    select * from enriched e
    where (
      q=''
      or (q_is_uuid and e.id::text=q)
      or (not q_is_uuid and (
        lower(e.name) like '%'||q||'%'
        or lower(e.slug) like '%'||q||'%'
        or lower(coalesce(e.producer_name,'')) like '%'||q||'%'
      ))
    )
      and (state_value='all'
        or (state_value='published' and e.published)
        or (state_value='ready' and e.ready)
        or (state_value='missing_media' and e.missing_real_media)
        or (state_value='data_missing' and e.data_missing)
        or (state_value='media_blocked' and e.media_blocked)
        or (state_value='owner_required' and e.owner_required))
  ), page as (
    select * from filtered order by ready desc,missing_real_media desc,data_missing desc,name,id limit p_limit offset p_offset
  )
  select jsonb_build_object(
    'scannedAt',timezone('utc',now()),
    'summary',jsonb_build_object(
      'total',(select count(*) from enriched),
      'published',(select count(*) from enriched where published),
      'readyToPublish',(select count(*) from enriched where ready),
      'missingRealMedia',(select count(*) from enriched where missing_real_media),
      'mandatoryDataMissing',(select count(*) from enriched where data_missing),
      'mediaBlocked',(select count(*) from enriched where media_blocked),
      'mediaReady',(select count(*) from enriched where media_ready),
      'brandFallbackAllowed',(select count(*) from enriched where brand_fallback_allowed),
      'ownerApprovalRequired',(select count(*) from enriched where owner_required)
    ),
    'filteredTotal',(select count(*) from filtered),
    'limit',p_limit,'offset',p_offset,
    'items',coalesce((select jsonb_agg(jsonb_build_object(
      'productId',id,'name',name,'slug',slug,'producerName',producer_name,'status',status,'active',is_active,
      'published',published,'readyToPublish',ready,'missingRealMedia',missing_real_media,'mandatoryDataMissing',data_missing,
      'mediaReady',media_ready,'brandFallbackAllowed',brand_fallback_allowed,'mediaBlocked',media_blocked,
      'ownerApprovalRequired',owner_required,'reasons',reasons,'updatedAt',updated_at
    ) order by ready desc,missing_real_media desc,data_missing desc,name,id) from page),'[]'::jsonb)
  ) into result;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_product_recommendations_preview_v1(p_reference text, p_limit integer DEFAULT 12)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
  if auth.uid() is null or not coalesce(private.has_permission('product.read'),false) then raise exception 'permission_required:product.read' using errcode='42501'; end if;
  return private.product_recommendations_core_v1(p_reference,p_limit,true);
end;$function$;

CREATE OR REPLACE FUNCTION private.super_admin_publish_product_health_v1(p_product_id uuid, p_payload jsonb, p_review_note text DEFAULT NULL::text, p_request_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); p public.products%rowtype; clean jsonb; entry public.content_entries%rowtype; old_meta jsonb:='{}'::jsonb; slug_value text; request_row private.product_health_change_requests%rowtype;
begin
 if uid is null or not private.has_permission('product.health_manage') then raise exception 'super_admin_required' using errcode='42501'; end if;
 if p_review_note is not null and char_length(btrim(p_review_note))>2000 then raise exception 'invalid_review_note' using errcode='22023'; end if;
 select * into p from public.products where id=p_product_id and deleted_at is null; if p.id is null then raise exception 'product_not_found' using errcode='P0002'; end if; clean:=private.validate_product_health_payload_v1(p_payload);
 if p_request_id is not null then select * into request_row from private.product_health_change_requests where id=p_request_id and product_id=p_product_id and status='pending' for update; if request_row.id is null then raise exception 'product_health_request_not_found' using errcode='P0002'; end if; end if;
 select * into entry from public.content_entries where related_product_id=p_product_id and content_type='product_health' and locale='tr' and deleted_at is null order by case when status='published' then 0 else 1 end,updated_at desc limit 1 for update;
 if entry.id is null then
   slug_value:='product-health-'||p.slug; if exists(select 1 from public.content_entries where content_type='product_health' and locale='tr' and slug=slug_value) then slug_value:=slug_value||'-'||substr(gen_random_uuid()::text,1,8); end if;
   insert into public.content_entries(content_type,slug,title,summary,body_markdown,body_html_sanitized,author_user_id,related_product_id,status,locale,metadata,published_at)
   values('product_health',slug_value,p.name||' - ürün bilgileri',clean->>'summary','','',uid,p.id,'published','tr',jsonb_build_object('safetyV2',clean->'safety','productInfoV1',clean->'productInfo','recipeV1',clean->'recipe'),timezone('utc',now())) returning * into entry;
 else
   old_meta:=coalesce(entry.metadata,'{}'::jsonb);
   update public.content_entries set title=p.name||' - ürün bilgileri',summary=clean->>'summary',metadata=(old_meta-'safetyV2'-'productInfoV1'-'recipeV1')||jsonb_build_object('safetyV2',(coalesce(old_meta->'safetyV2','{}'::jsonb)||clean->'safety'),'productInfoV1',clean->'productInfo','recipeV1',clean->'recipe'),status='published',published_at=timezone('utc',now()),author_user_id=uid,deleted_at=null where id=entry.id returning * into entry;
 end if;
 if request_row.id is not null then update private.product_health_change_requests set status='approved',reviewed_by=uid,reviewed_at=timezone('utc',now()),review_note=nullif(btrim(coalesce(p_review_note,'')),''),updated_at=timezone('utc',now()) where id=request_row.id; end if;
 perform private.write_admin_audit_v2('product_health.publish','product',p.id::text,null,jsonb_build_object('contentId',entry.id,'status','published'),jsonb_build_object('requestId',request_row.id,'reviewNoteProvided',nullif(btrim(coalesce(p_review_note,'')),'') is not null),null);
 return jsonb_build_object('productId',p.id,'contentId',entry.id,'status','published','requestId',request_row.id,'updatedAt',entry.updated_at);
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_reject_product_health_change_v1(p_request_id uuid, p_review_note text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); changed integer; note text:=btrim(coalesce(p_review_note,'')); product_id_value uuid;
begin
 if uid is null or not private.has_permission('product.health_manage') then raise exception 'super_admin_required' using errcode='42501'; end if;
 if char_length(note) not between 10 and 2000 then raise exception 'product_health_review_note_required' using errcode='22023'; end if;
 update private.product_health_change_requests set status='rejected',reviewed_by=uid,reviewed_at=timezone('utc',now()),review_note=note,updated_at=timezone('utc',now()) where id=p_request_id and status='pending' returning product_id into product_id_value;
 get diagnostics changed=row_count; if changed=0 then raise exception 'product_health_request_not_found' using errcode='P0002'; end if;
 perform private.write_admin_audit_v2('product_health.reject','product',product_id_value::text,null,jsonb_build_object('requestId',p_request_id,'status','rejected'),jsonb_build_object('requestId',p_request_id,'reasonLength',char_length(note)),null);
 return true;
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_remove_product_v1(p_product_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  reason_value text:=btrim(coalesce(p_reason,''));
  product_row public.products%rowtype;
  order_refs integer;
  review_refs integer;
  batch_refs integer;
  change_refs integer;
  image_paths jsonb;
  preserve_history boolean;
begin
  if caller_id is null or not coalesce(private.has_permission('product.remove'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
  if char_length(reason_value) not between 8 and 1000 then raise exception 'product_removal_reason_required' using errcode='22023'; end if;
  select * into product_row from public.products where id=p_product_id for update;
  if product_row.id is null then raise exception 'product_not_found' using errcode='P0002'; end if;

  select count(*)::integer into order_refs from public.order_items where product_id=p_product_id;
  select count(*)::integer into review_refs from public.reviews where product_id=p_product_id;
  select count(*)::integer into batch_refs from public.product_batches where product_id=p_product_id;
  select count(*)::integer into change_refs from public.product_change_requests where product_id=p_product_id;
  select coalesce(jsonb_agg(storage_path order by sort_order,created_at),'[]'::jsonb) into image_paths from public.product_images where product_id=p_product_id;
  preserve_history:=order_refs>0 or review_refs>0 or batch_refs>0 or change_refs>0;

  if preserve_history then
    update public.products
      set status='archived',is_active=false,is_featured=false,deleted_at=coalesce(deleted_at,timezone('utc',now())),updated_at=timezone('utc',now())
      where id=p_product_id;
    update public.product_change_requests set status='withdrawn',review_reason=coalesce(review_reason,reason_value),updated_at=timezone('utc',now()) where product_id=p_product_id and status='pending';
    delete from public.favorites where product_id=p_product_id;
    delete from public.campaign_products where product_id=p_product_id;
    insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
      values('product',p_product_id,'product.removed_preserving_history',jsonb_build_object('actor_user_id',caller_id,'reason',reason_value,'order_refs',order_refs,'review_refs',review_refs,'batch_refs',batch_refs,'change_refs',change_refs));
    return jsonb_build_object('id',p_product_id,'mode','archived_preserving_history','imagePaths','[]'::jsonb,'orderRefs',order_refs,'reviewRefs',review_refs,'batchRefs',batch_refs,'changeRefs',change_refs);
  end if;

  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload)
    values('product',p_product_id,'product.permanently_removed',jsonb_build_object('actor_user_id',caller_id,'reason',reason_value,'producer_id',product_row.producer_id,'name',product_row.name));
  delete from public.products where id=p_product_id;
  return jsonb_build_object('id',p_product_id,'mode','permanently_deleted','imagePaths',image_paths,'orderRefs',0,'reviewRefs',0,'batchRefs',0,'changeRefs',0);
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_reopen_closed_user_v1(p_user_id uuid, p_reason text, p_restore_producer boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); reason_value text:=btrim(coalesce(p_reason,'')); profile_row public.profiles%rowtype; producer_row public.producers%rowtype;
begin
 if caller_id is null or not coalesce(private.has_permission('user.restore'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
 if p_user_id=caller_id then raise exception 'cannot_reopen_current_user' using errcode='42501'; end if;
 if char_length(reason_value) not between 8 and 1000 then raise exception 'reopen_reason_required' using errcode='22023'; end if;
 select * into profile_row from public.profiles where id=p_user_id for update;
 if profile_row.id is null then raise exception 'user_not_found' using errcode='P0002'; end if;
 if profile_row.status<>'deleted' then raise exception 'account_not_closed' using errcode='55000'; end if;
 if (select email from auth.users where id=p_user_id) like 'deleted+%@invalid.local' then raise exception 'anonymized_account_cannot_be_reopened' using errcode='55000'; end if;
 update public.profiles set status='active',deleted_at=null,updated_at=timezone('utc',now()) where id=p_user_id;
 insert into private.user_roles(user_id,role,granted_by) values(p_user_id,'customer',caller_id) on conflict(user_id,role) do update set expires_at=null,granted_by=excluded.granted_by,granted_at=timezone('utc',now());
 update private.security_block_rules set active=false,revoked_by=caller_id,revoked_at=timezone('utc',now()) where source_user_id=p_user_id and active=true;
 update private.device_push_tokens set disabled_at=null,updated_at=timezone('utc',now()) where user_id=p_user_id;
 select * into producer_row from public.producers where owner_user_id=p_user_id and deleted_at is null order by created_at desc limit 1;
 if producer_row.id is not null and p_restore_producer then
   update public.producers set status='active',updated_at=timezone('utc',now()) where id=producer_row.id;
   insert into private.user_roles(user_id,role,granted_by) values(p_user_id,'producer',caller_id) on conflict(user_id,role) do update set expires_at=null,granted_by=excluded.granted_by,granted_at=timezone('utc',now());
 end if;
 insert into private.account_enforcement_events(user_id,actor_user_id,action,reason,metadata) values(p_user_id,caller_id,'reopened',reason_value,jsonb_build_object('producerRestored',p_restore_producer and producer_row.id is not null,'producerRequiresTrustReview',producer_row.id is not null));
 return jsonb_build_object('id',p_user_id,'status','active','producerStatus',case when producer_row.id is null then null when p_restore_producer then 'active' else producer_row.status end,'producerRestored',p_restore_producer and producer_row.id is not null);
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_retry_transactional_email_job_v1(p_job_id bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null or not coalesce(private.has_permission('notification.manage'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
  update private.transactional_email_jobs
  set status='pending',attempts=0,available_at=timezone('utc',now()),locked_at=null,locked_by=null,last_error=null
  where id=p_job_id and status in ('failed','dead_letter');
  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_set_integration_secret_v1(p_name text, p_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  secret_name text:=btrim(coalesce(p_name,''));
  secret_value text:=coalesce(p_secret,'');
  existing_id uuid;
  configured boolean;
begin
  if caller_id is null or not coalesce(private.has_permission('system.configure'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
  if not private.integration_secret_allowed_v1(secret_name) then raise exception 'integration_secret_name_invalid' using errcode='22023'; end if;
  if char_length(secret_value)<6 or char_length(secret_value)>20000 then raise exception 'integration_secret_value_invalid' using errcode='22023'; end if;
  if secret_name='golden_oremar_fcm_service_account_email'
     and secret_value not like 'replace-before-release:%'
     and secret_value !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'
  then raise exception 'integration_secret_value_invalid' using errcode='22023'; end if;
  if secret_name in ('golden_oremar_fcm_private_key','golden_oremar_apns_private_key')
     and secret_value not like 'replace-before-release:%'
     and position('BEGIN PRIVATE KEY' in secret_value)=0
  then raise exception 'integration_secret_value_invalid' using errcode='22023'; end if;
  if secret_name in ('golden_oremar_apns_team_id','golden_oremar_apns_key_id')
     and secret_value not like 'replace-before-release:%'
     and secret_value !~ '^[A-Z0-9]{10}$'
  then raise exception 'integration_secret_value_invalid' using errcode='22023'; end if;
  select id into existing_id from vault.secrets where name=secret_name limit 1;
  if existing_id is null then
    perform vault.create_secret(secret_value,secret_name,'Golden Oremar integration secret',null);
  else
    perform vault.update_secret(existing_id,secret_value,secret_name,'Golden Oremar integration secret',null);
  end if;
  configured:=secret_value not like 'replace-before-release:%';
  insert into private.admin_audit_logs(actor_user_id,action,target_type,target_id,details)
  values(caller_id,'integration.secret_updated','vault_secret',secret_name,jsonb_build_object('configured',configured));
  return jsonb_build_object('ok',true,'name',secret_name,'configured',configured);
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_set_iyzico_environment_v1(p_environment text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); env_value text:=lower(btrim(coalesce(p_environment,'')));
begin
  if caller_id is null or not coalesce(private.has_permission('payment.manage'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
  if env_value not in ('sandbox','production') then raise exception 'invalid_iyzico_environment' using errcode='22023'; end if;
  update private.super_admin_company_configuration_v1 set iyzico_environment=env_value,updated_at=timezone('utc',now()),updated_by=caller_id where singleton=true;
  insert into private.admin_audit_logs(actor_user_id,action,target_type,target_id,details) values(caller_id,'integration.iyzico_environment_updated','brand_settings','golden-oremar',jsonb_build_object('environment',env_value));
  return private.super_admin_get_release_setup_v2();
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_set_producer_payment_provider_type_v1(p_producer_id uuid, p_provider_submerchant_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); normalized_type text:=upper(btrim(coalesce(p_provider_submerchant_type,''))); target public.producers%rowtype; result private.producer_payment_accounts%rowtype;
begin
  if caller_id is null or not coalesce(private.has_permission('payment.manage'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
  if p_producer_id is null then raise exception 'producer_required' using errcode='22023'; end if;
  if normalized_type not in ('PERSONAL','PRIVATE_COMPANY','LIMITED_OR_JOINT_STOCK_COMPANY') then raise exception 'invalid_provider_submerchant_type' using errcode='22023'; end if;
  select * into target from public.producers where id=p_producer_id and deleted_at is null;
  if target.id is null then raise exception 'producer_not_found' using errcode='P0002'; end if;
  insert into private.producer_payment_accounts(producer_id,provider,provider_submerchant_type,submerchant_external_id,status,last_error,updated_at)
  values(target.id,'iyzico',normalized_type,'GO-'||replace(target.id::text,'-',''),'pending_configuration',null,timezone('utc',now()))
  on conflict(producer_id) do update set provider_submerchant_type=excluded.provider_submerchant_type,status=case when private.producer_payment_accounts.submerchant_key is null then 'pending_configuration' else private.producer_payment_accounts.status end,last_error=null,updated_at=timezone('utc',now())
  returning * into result;
  insert into private.admin_audit_logs(actor_user_id,action,target_type,target_id,details)
  values(caller_id,'producer.payment_provider_type_set','producer',target.id,jsonb_build_object('provider','iyzico','submerchantType',normalized_type));
  return jsonb_build_object('ok',true,'producerId',result.producer_id,'provider',result.provider,'providerSubmerchantType',result.provider_submerchant_type,'status',result.status,'ready',result.status='ready');
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_set_store_state_v1(p_store_reference text, p_action text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  ref text:=btrim(coalesce(p_store_reference,''));
  action_value text:=lower(btrim(coalesce(p_action,'')));
  reason_value text:=btrim(coalesce(p_reason,''));
  p public.producers%rowtype;
  readiness jsonb;
  before_status text;
  before_deleted_at timestamptz;
begin
  if caller_id is null or not coalesce(private.has_permission('storefront.lifecycle_manage'),false) then
    raise exception 'permission_required:storefront.lifecycle_manage' using errcode='42501';
  end if;
  if char_length(ref) not between 1 and 220 then raise exception 'invalid_store_reference' using errcode='22023'; end if;
  if action_value not in ('open','block','close','archive','restore') then raise exception 'invalid_store_lifecycle_action' using errcode='22023'; end if;
  if action_value in ('block','close','archive') and char_length(reason_value) not between 10 and 1000 then raise exception 'store_lifecycle_reason_required' using errcode='22023'; end if;

  select * into p from public.producers x
  where lower(x.store_number)=lower(ref) or lower(x.slug)=lower(ref) or x.id::text=lower(ref)
  order by case when lower(x.store_number)=lower(ref) then 0 when x.id::text=lower(ref) then 1 else 2 end
  limit 1 for update;
  if p.id is null then raise exception 'store_not_found' using errcode='P0002'; end if;
  if p.store_kind='official' then raise exception 'official_store_state_protected' using errcode='42501'; end if;
  before_status:=p.status; before_deleted_at:=p.deleted_at;

  if action_value='open' then
    if p.deleted_at is not null then raise exception 'store_restore_required' using errcode='55000'; end if;
    if p.storefront_status<>'published' then raise exception 'storefront_publish_required' using errcode='55000'; end if;
    readiness:=private.storefront_readiness_v1(p.id);
    if not coalesce((readiness->>'ready')::boolean,false) then raise exception 'storefront_readiness_required' using errcode='55000'; end if;
    if not p.is_verified or not p.origin_verified then raise exception 'store_verification_required' using errcode='55000'; end if;
    if not coalesce(private.is_producer_trust_badge_active_v1(p.id),false) then raise exception 'active_producer_trust_badge_required' using errcode='55000'; end if;
    update public.producers set status='active',updated_at=timezone('utc',now()) where id=p.id;
  elsif action_value='block' then
    if p.deleted_at is not null then raise exception 'store_archived' using errcode='55000'; end if;
    update public.producers set status='suspended',
      trust_badge_status=case when trust_badge_status='active' then 'revoked' else trust_badge_status end,
      trust_badge_revoked_at=case when trust_badge_status='active' then timezone('utc',now()) else trust_badge_revoked_at end,
      trust_badge_reason=case when trust_badge_status='active' then 'Mağaza Super Admin tarafından engellendi: '||reason_value else trust_badge_reason end,
      updated_at=timezone('utc',now()) where id=p.id;
    if p.trust_badge_status='active' then
      insert into private.producer_trust_badge_events(producer_id,actor_user_id,action,reason,review_due_at)
      values(p.id,caller_id,'auto_revoked','Mağaza Super Admin tarafından engellendi: '||reason_value,p.trust_badge_review_due_at);
    end if;
  elsif action_value='close' then
    if p.deleted_at is not null then raise exception 'store_archived' using errcode='55000'; end if;
    update public.producers set status='closed',updated_at=timezone('utc',now()) where id=p.id;
  elsif action_value='archive' then
    if p.deleted_at is not null then raise exception 'store_already_archived' using errcode='55000'; end if;
    update public.producers set status='closed',deleted_at=timezone('utc',now()),
      trust_badge_status=case when trust_badge_status='active' then 'revoked' else trust_badge_status end,
      trust_badge_revoked_at=case when trust_badge_status='active' then timezone('utc',now()) else trust_badge_revoked_at end,
      trust_badge_reason=case when trust_badge_status='active' then 'Mağaza güvenli arşive alındı: '||reason_value else trust_badge_reason end,
      updated_at=timezone('utc',now()) where id=p.id;
    if p.trust_badge_status='active' then
      insert into private.producer_trust_badge_events(producer_id,actor_user_id,action,reason,review_due_at)
      values(p.id,caller_id,'auto_revoked','Mağaza güvenli arşive alındı: '||reason_value,p.trust_badge_review_due_at);
    end if;
  else
    if p.deleted_at is null then raise exception 'store_not_archived' using errcode='55000'; end if;
    update public.producers set deleted_at=null,status='pending',updated_at=timezone('utc',now()) where id=p.id;
  end if;

  if p.owner_user_id is not null then
    insert into public.notifications(user_id,type,title,message,action_url,metadata)
    values(p.owner_user_id,'producer',
      case action_value when 'open' then 'Mağazanız yeniden açıldı' when 'block' then 'Mağazanız engellendi' when 'close' then 'Mağazanız kapatıldı' when 'archive' then 'Mağazanız arşive alındı' else 'Mağazanız arşivden çıkarıldı' end,
      case when reason_value<>'' then reason_value else 'Mağaza durumunuz Golden Oremar yönetimi tarafından güncellendi.' end,
      '/?tab=account',jsonb_build_object('producer_id',p.id,'store_number',p.store_number,'action',action_value));
  end if;

  insert into private.admin_audit_logs(actor_user_id,action,target_type,target_id,details)
  values(caller_id,'storefront.lifecycle.'||action_value,'producer',p.id::text,jsonb_build_object(
    'storeNumber',p.store_number,'reason',nullif(reason_value,''),'beforeStatus',before_status,'beforeArchivedAt',before_deleted_at
  ));

  select * into p from public.producers where id=p.id;
  return jsonb_build_object('ok',true,'id',p.id,'storeNumber',p.store_number,'status',p.status,'storefrontStatus',p.storefront_status,'archivedAt',p.deleted_at,'action',action_value);
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_store_detail_v1(p_store_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  ref text:=btrim(coalesce(p_store_reference,''));
  p public.producers%rowtype;
  readiness jsonb;
  application jsonb:=null;
begin
  if auth.uid() is null or not coalesce(private.has_permission('storefront.lifecycle_manage'),false) then
    raise exception 'permission_required:storefront.lifecycle_manage' using errcode='42501';
  end if;
  if char_length(ref) not between 1 and 220 then raise exception 'invalid_store_reference' using errcode='22023'; end if;
  select * into p from public.producers x
  where lower(x.store_number)=lower(ref) or lower(x.slug)=lower(ref) or x.id::text=lower(ref)
  order by case when lower(x.store_number)=lower(ref) then 0 when x.id::text=lower(ref) then 1 else 2 end
  limit 1;
  if p.id is null then raise exception 'store_not_found' using errcode='P0002'; end if;
  readiness:=case when p.deleted_at is null then private.storefront_readiness_v1(p.id) else jsonb_build_object('ready',false,'missing',jsonb_build_array('store_archived'),'steps','[]'::jsonb) end;
  if p.application_id is not null then
    select jsonb_build_object('id',a.id,'status',a.status,'sellerClassification',a.seller_classification,'foodComplianceStatus',a.food_compliance_status,'submittedAt',a.submitted_at,'reviewedAt',a.reviewed_at)
      into application from public.producer_applications a where a.id=p.application_id;
  end if;
  return jsonb_build_object(
    'id',p.id,'storeNumber',p.store_number,'slug',p.slug,'name',p.display_name,'description',p.description,'story',p.story,
    'storeKind',p.store_kind,'producerStatus',p.status,'storefrontStatus',p.storefront_status,'publishedAt',p.storefront_published_at,
    'verified',p.is_verified,'originVerified',p.origin_verified,'trustBadgeActive',case when p.store_kind='official' then true else coalesce(private.is_producer_trust_badge_active_v1(p.id),false) end,
    'logoPath',private.verified_public_storage_path_v1('catalog-public',p.logo_path),'coverPath',private.verified_public_storage_path_v1('catalog-public',p.cover_path),
    'contact',jsonb_build_object('email',p.storefront_contact_email,'phone',p.storefront_contact_phone,'website',p.storefront_website_url),
    'address',jsonb_build_object('line1',p.storefront_address_line1,'line2',p.storefront_address_line2,'postalCode',p.storefront_postal_code,'city',p.storefront_city,'region',p.storefront_region,'countryCode',p.storefront_country_code,'visibility',p.storefront_address_visibility),
    'business',jsonb_build_object('type',p.storefront_business_identity_type,'name',p.storefront_business_name,'reference',p.storefront_business_reference,'verifiedAt',p.storefront_business_verified_at),
    'readiness',readiness,'application',application,
    'metrics',jsonb_build_object(
      'products',(select count(*)::bigint from public.products product where product.producer_id=p.id and product.deleted_at is null),
      'publishedProducts',(select count(*)::bigint from public.products product where product.producer_id=p.id and product.status='published' and product.is_active=true and product.deleted_at is null),
      'orders',(select count(distinct item.order_id)::bigint from public.order_items item where item.producer_id=p.id),
      'customers',(select count(distinct o.user_id)::bigint from public.order_items item join public.orders o on o.id=item.order_id where item.producer_id=p.id and o.status not in ('draft','cancelled')),
      'followers',(select count(*)::bigint from private.producer_follows f where f.producer_id=p.id)
    ),
    'createdAt',p.created_at,'updatedAt',p.updated_at,'archivedAt',p.deleted_at,
    'officialProtected',p.store_kind='official'
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_store_directory_v1(p_query text DEFAULT NULL::text, p_state text DEFAULT 'all'::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  q text:=lower(btrim(coalesce(p_query,'')));
  state_value text:=lower(btrim(coalesce(p_state,'all')));
  result jsonb;
begin
  if auth.uid() is null or not coalesce(private.has_permission('storefront.lifecycle_manage'),false) then
    raise exception 'permission_required:storefront.lifecycle_manage' using errcode='42501';
  end if;
  if char_length(q)>160 then raise exception 'store_search_query_too_long' using errcode='22023'; end if;
  if state_value not in ('all','open','setup','blocked','closed','archived') then raise exception 'invalid_store_state_filter' using errcode='22023'; end if;
  if p_limit not between 1 and 100 or p_offset<0 then raise exception 'invalid_pagination' using errcode='22023'; end if;

  with all_stores as (
    select p.*,
      case
        when p.deleted_at is not null then 'archived'
        when p.status='active' and p.storefront_status='published' then 'open'
        when p.status='suspended' then 'blocked'
        when p.status='closed' then 'closed'
        else 'setup'
      end lifecycle_state,
      (select count(*)::bigint from public.products product where product.producer_id=p.id and product.deleted_at is null) product_count,
      (select count(*)::bigint from public.products product where product.producer_id=p.id and product.status='published' and product.is_active=true and product.deleted_at is null) published_product_count,
      (select count(distinct item.order_id)::bigint from public.order_items item where item.producer_id=p.id) order_count
    from public.producers p
  ), filtered as (
    select * from all_stores s
    where (state_value='all' or s.lifecycle_state=state_value)
      and (
        q='' or lower(s.store_number)=q or lower(s.id::text)=q or lower(s.slug)=q
        or lower(s.display_name) like '%'||q||'%'
        or lower(coalesce(s.storefront_contact_email,'')) like '%'||q||'%'
        or lower(coalesce(s.storefront_contact_phone,'')) like '%'||q||'%'
      )
  ), page as (
    select * from filtered
    order by case when store_kind='official' then 0 else 1 end,
             case lifecycle_state when 'open' then 0 when 'setup' then 1 when 'blocked' then 2 when 'closed' then 3 else 4 end,
             updated_at desc,id
    limit p_limit offset p_offset
  )
  select jsonb_build_object(
    'summary',jsonb_build_object(
      'totalStores',(select count(*)::bigint from all_stores),
      'openStores',(select count(*)::bigint from all_stores where lifecycle_state='open'),
      'setupPending',(select count(*)::bigint from all_stores where lifecycle_state='setup'),
      'blockedStores',(select count(*)::bigint from all_stores where lifecycle_state='blocked'),
      'closedStores',(select count(*)::bigint from all_stores where lifecycle_state='closed'),
      'archivedStores',(select count(*)::bigint from all_stores where lifecycle_state='archived'),
      'officialStores',(select count(*)::bigint from all_stores where store_kind='official'),
      'independentStores',(select count(*)::bigint from all_stores where store_kind='independent'),
      'totalProducts',(select coalesce(sum(product_count),0)::bigint from all_stores),
      'publishedProducts',(select coalesce(sum(published_product_count),0)::bigint from all_stores),
      'totalOrders',(select coalesce(sum(order_count),0)::bigint from all_stores)
    ),
    'total',(select count(*)::bigint from filtered),
    'limit',p_limit,
    'offset',p_offset,
    'items',coalesce((select jsonb_agg(jsonb_build_object(
      'id',id,'storeNumber',store_number,'slug',slug,'name',display_name,'storeKind',store_kind,
      'producerStatus',status,'storefrontStatus',storefront_status,'state',lifecycle_state,
      'verified',is_verified,'originVerified',origin_verified,
      'contactEmail',storefront_contact_email,'contactPhone',storefront_contact_phone,
      'location',coalesce(nullif(concat_ws(', ',nullif(storefront_city,''),nullif(storefront_region,''),nullif(storefront_country_code,'')),''),production_location),
      'productCount',product_count,'publishedProductCount',published_product_count,'orderCount',order_count,
      'updatedAt',updated_at,'createdAt',created_at,'archivedAt',deleted_at
    ) order by case when store_kind='official' then 0 else 1 end,updated_at desc,id) from page),'[]'::jsonb)
  ) into result;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_update_brand_appearance_v1(p_appearance jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  normalized jsonb;
  updated_at timestamptz;
begin
  if auth.uid() is null or not coalesce(private.has_permission('system.configure'),false) then
    raise exception 'super_admin_required' using errcode='42501';
  end if;
  normalized := private.normalize_brand_appearance_v1(p_appearance);
  update public.brand_settings
  set public_config=jsonb_set(coalesce(public_config,'{}'::jsonb),'{appearance}',normalized,true)
  where slug='golden-oremar'
  returning brand_settings.updated_at into updated_at;
  if not found then raise exception 'brand_configuration_not_found' using errcode='P0002'; end if;
  return normalized || jsonb_build_object('updatedAt',updated_at);
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_update_business_identity_v2(p_registered_legal_name text, p_registered_address text, p_tax_office text, p_tax_number text, p_mersis_number text, p_trade_registry_number text, p_country_code text, p_support_email text, p_support_phone text, p_legal_documents_finalized boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  registered_name text:=nullif(btrim(coalesce(p_registered_legal_name,'')),'');
  registered_address text:=nullif(btrim(coalesce(p_registered_address,'')),'');
  tax_office text:=nullif(btrim(coalesce(p_tax_office,'')),'');
  tax_number text:=nullif(regexp_replace(coalesce(p_tax_number,''),'[^0-9]','','g'),'');
  mersis_number text:=nullif(regexp_replace(coalesce(p_mersis_number,''),'[^0-9]','','g'),'');
  trade_registry text:=nullif(btrim(coalesce(p_trade_registry_number,'')),'');
  country_code text:=nullif(upper(btrim(coalesce(p_country_code,''))),'');
  email_value text:=lower(btrim(coalesce(p_support_email,'')));
  phone_value text:=btrim(coalesce(p_support_phone,''));
  phone_digits text;
  next_config jsonb;
  current_identity jsonb;
begin
  if caller_id is null or not coalesce(private.has_permission('system.configure'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
  if registered_name is null or char_length(registered_name) not between 2 and 240 or registered_name ~ '[[:cntrl:]]' then raise exception 'invalid_registered_legal_name' using errcode='22023'; end if;
  if registered_address is null or char_length(registered_address) not between 10 and 1000 or registered_address ~ '[[:cntrl:]]' then raise exception 'invalid_registered_address' using errcode='22023'; end if;
  if tax_office is null or char_length(tax_office)>160 or tax_office ~ '[[:cntrl:]]' then raise exception 'invalid_tax_office' using errcode='22023'; end if;
  if tax_number is null or char_length(tax_number) not between 10 and 11 then raise exception 'invalid_tax_number' using errcode='22023'; end if;
  if mersis_number is null or char_length(mersis_number)<>16 then raise exception 'invalid_mersis_number' using errcode='22023'; end if;
  if trade_registry is null or char_length(trade_registry)>120 or trade_registry ~ '[[:cntrl:]]' then raise exception 'invalid_trade_registry_number' using errcode='22023'; end if;
  if country_code is null or country_code !~ '^[A-Z]{2}$' then raise exception 'invalid_registered_country_code' using errcode='22023'; end if;
  if char_length(email_value) not between 5 and 254 or email_value !~ '^[^[:space:]@]+@[^[:space:]@]+\\.[^[:space:]@]+$' then raise exception 'invalid_support_email' using errcode='22023'; end if;
  if char_length(phone_value) not between 7 and 40 or phone_value !~ '^[+()0-9 .-]+$' then raise exception 'invalid_support_phone' using errcode='22023'; end if;
  phone_digits:=regexp_replace(phone_value,'[^0-9]','','g');
  if char_length(phone_digits) not between 10 and 15 then raise exception 'invalid_support_phone' using errcode='22023'; end if;

  update private.super_admin_company_configuration_v1 set
    registered_legal_name=registered_name,
    registered_address=registered_address,
    tax_office=tax_office,
    tax_number=tax_number,
    mersis_number=mersis_number,
    trade_registry_number=trade_registry,
    country_code=country_code,
    support_email=email_value,
    support_phone=phone_value,
    updated_at=timezone('utc',now()),
    updated_by=caller_id
  where singleton=true;

  update public.brand_settings set
    support_email=email_value,
    support_phone=phone_value,
    public_config=jsonb_set(jsonb_set(coalesce(public_config,'{}'::jsonb),'{contactInfo,email}',to_jsonb(email_value),true),'{contactInfo,phone}',to_jsonb(phone_value),true),
    updated_at=timezone('utc',now())
  where slug='golden-oremar';

  if coalesce(p_legal_documents_finalized,false) then
    select coalesce(public_config,'{}'::jsonb),coalesce(public_config->'businessIdentity','{}'::jsonb)
      into next_config,current_identity from public.brand_settings where slug='golden-oremar' for update;
    current_identity:=current_identity||jsonb_build_object(
      'registeredLegalName',registered_name,
      'registeredAddress',registered_address,
      'taxOffice',tax_office,
      'taxNumber',tax_number,
      'mersisNumber',mersis_number,
      'tradeRegistryNumber',trade_registry,
      'countryCode',country_code,
      'verificationStatus','verified',
      'legalDocumentsFinalized',true,
      'updatedBy',caller_id,
      'updatedAt',timezone('utc',now())
    );
    next_config:=jsonb_set(next_config,'{businessIdentity}',current_identity,true);
    update public.brand_settings set public_config=next_config,updated_at=timezone('utc',now()) where slug='golden-oremar';
  end if;

  insert into private.admin_audit_logs(actor_user_id,action,target_type,target_id,details)
  values(caller_id,'brand.business_configuration_updated','brand_settings','golden-oremar',jsonb_build_object('publishedVerifiedIdentity',coalesce(p_legal_documents_finalized,false)));
  return private.super_admin_get_business_identity_v2();
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_update_payment_control_v1(p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); normalized jsonb; previous jsonb;
begin
  if caller_id is null or not coalesce(private.has_permission('payment.manage'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
  normalized:=private.validate_payment_control_v1(p_config);
  select private.default_payment_control_v1() || coalesce(bs.public_config->'payments','{}'::jsonb) into previous from public.brand_settings bs where bs.slug='golden-oremar' for update;
  if previous is null then raise exception 'brand_settings_not_found' using errcode='P0002'; end if;
  update public.brand_settings set public_config=jsonb_set(public_config,'{payments}',normalized,true),updated_at=timezone('utc',now()) where slug='golden-oremar';
  insert into private.admin_audit_logs(actor_user_id,action,target_type,target_id,details)
  values(caller_id,'payments.control_updated','brand_settings','golden-oremar',jsonb_build_object('previous',previous,'next',normalized));
  return normalized;
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_update_producer_payout_v2(p_payout_id uuid, p_status text, p_reference text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); row private.producer_payouts%rowtype; next_status text:=lower(btrim(coalesce(p_status,''))); owner_id uuid; provider_value text;
begin
  if uid is null or not coalesce(private.has_permission('payout.release'),false) then raise exception 'permission_required:payout.release' using errcode='42501'; end if;
  if next_status not in('processing','paid','failed','cancelled') then raise exception 'invalid_payout_status' using errcode='22023'; end if;
  if char_length(coalesce(p_reference,''))>180 or char_length(coalesce(p_note,''))>1000 then raise exception 'invalid_payout_field' using errcode='22023'; end if;
  select * into row from private.producer_payouts where id=p_payout_id for update;
  if row.id is null then raise exception 'payout_not_found' using errcode='P0002'; end if;
  if row.channel='provider_marketplace' then
    if not (row.status='processing' and next_status in('paid','failed')) then raise exception 'invalid_payout_transition' using errcode='22023'; end if;
    provider_value:='iyzico';
  else
    if not ((row.status in('requested','scheduled') and next_status in('processing','paid','failed','cancelled')) or (row.status='processing' and next_status in('paid','failed','cancelled'))) then raise exception 'invalid_payout_transition' using errcode='22023'; end if;
    provider_value:='bank_transfer';
  end if;
  if next_status='paid' and char_length(btrim(coalesce(p_reference,'')))<4 then raise exception 'payout_payment_reference_required' using errcode='22023'; end if;
  update private.producer_payouts set status=next_status,provider=provider_value,provider_reference=case when nullif(btrim(coalesce(p_reference,'')),'') is not null then btrim(p_reference) else provider_reference end,note=case when nullif(btrim(coalesce(p_note,'')),'') is not null then btrim(p_note) else note end,processed_by=uid,processed_at=case when next_status in('paid','failed','cancelled') then timezone('utc',now()) else processed_at end,updated_at=timezone('utc',now()) where id=row.id returning * into row;
  select owner_user_id into owner_id from public.producers where id=row.producer_id;
  if owner_id is not null and next_status in('paid','failed','cancelled') then
    insert into public.notifications(user_id,type,title,message,action_url,metadata) values(owner_id,'producer',case next_status when 'paid' then 'Satıcı ödemeniz tamamlandı' when 'failed' then 'Satıcı ödemeniz sonuçlanamadı' else 'Çekim talebiniz iptal edildi' end,case next_status when 'paid' then 'Ödeme hedef IBAN hesabınıza gönderildi ve transfer referansı kaydedildi.' when 'failed' then 'Ödeme işlemi tamamlanamadı. Finans ekranından durumu takip edebilirsiniz.' else 'Bekleyen çekim talebi iptal edildi.' end,'/?tab=account&view=seller%3Afinance',jsonb_build_object('payoutId',row.id,'status',next_status,'amountMinor',row.amount_minor,'currency',row.currency));
  end if;
  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload) values('producer_payout',row.id,'producer_payout.'||next_status,jsonb_build_object('payout_id',row.id,'producer_id',row.producer_id,'status',next_status,'channel',row.channel,'actor_user_id',uid));
  return jsonb_build_object('id',row.id,'producerId',row.producer_id,'currency',row.currency,'amountMinor',row.amount_minor,'status',row.status,'channel',row.channel,'provider',row.provider,'providerReference',row.provider_reference,'processedAt',row.processed_at);
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_update_release_setup_v2(p_public_origin text, p_iyzico_return_url text, p_transactional_email_from text, p_fcm_project_id text, p_apns_bundle_id text, p_google_oauth_client_id text, p_facebook_app_id text, p_activate_for_production boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  origin_value text:=regexp_replace(btrim(coalesce(p_public_origin,'')),'/+$','','g');
  return_url_value text:=btrim(coalesce(p_iyzico_return_url,''));
  email_from_value text:=lower(btrim(coalesce(p_transactional_email_from,'')));
  fcm_project_value text:=btrim(coalesce(p_fcm_project_id,''));
  apns_bundle_value text:=btrim(coalesce(p_apns_bundle_id,''));
  google_client_value text:=btrim(coalesce(p_google_oauth_client_id,''));
  facebook_app_value text:=btrim(coalesce(p_facebook_app_id,''));
  next_config jsonb;
  release_config jsonb;
  payment_config jsonb;
begin
  if caller_id is null or not coalesce(private.has_permission('system.configure'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
  if origin_value='' or char_length(origin_value)>2048 or origin_value !~ '^https://[^[:space:]/?#]+(?::[0-9]{1,5})?$' then raise exception 'invalid_public_origin' using errcode='22023'; end if;
  if return_url_value='' or char_length(return_url_value)>2048 or return_url_value !~ '^https://[^[:space:]]+$' then raise exception 'invalid_iyzico_return_url' using errcode='22023'; end if;
  if email_from_value='' or char_length(email_from_value)>254 or email_from_value !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'invalid_transactional_email_from' using errcode='22023'; end if;
  if fcm_project_value='' or char_length(fcm_project_value)>255 or fcm_project_value !~ '^[A-Za-z0-9._:-]+$' then raise exception 'invalid_fcm_project_id' using errcode='22023'; end if;
  if apns_bundle_value='' or char_length(apns_bundle_value)>255 or apns_bundle_value !~ '^[A-Za-z0-9.-]+$' then raise exception 'invalid_apns_bundle_id' using errcode='22023'; end if;
  if google_client_value='' or char_length(google_client_value)>512 or google_client_value !~ '^[A-Za-z0-9._:-]+\.apps\.googleusercontent\.com$' then raise exception 'invalid_google_oauth_client_id' using errcode='22023'; end if;
  if facebook_app_value='' or char_length(facebook_app_value)>64 or facebook_app_value !~ '^[0-9]+$' then raise exception 'invalid_facebook_app_id' using errcode='22023'; end if;

  update private.super_admin_company_configuration_v1 set
    public_origin=origin_value,iyzico_return_url=return_url_value,transactional_email_from=email_from_value,fcm_project_id=fcm_project_value,apns_bundle_id=apns_bundle_value,google_oauth_client_id=google_client_value,facebook_app_id=facebook_app_value,production_enabled=coalesce(p_activate_for_production,false),updated_at=timezone('utc',now()),updated_by=caller_id
  where singleton=true;

  update private.super_admin_release_origins_v1 set is_primary=false,updated_at=timezone('utc',now()),updated_by=caller_id where is_primary=true and origin<>origin_value;
  insert into private.super_admin_release_origins_v1(origin,is_primary,is_active,created_by,updated_by) values(origin_value,true,true,caller_id,caller_id)
  on conflict(origin) do update set is_primary=true,is_active=true,updated_at=timezone('utc',now()),updated_by=caller_id;

  select coalesce(public_config,'{}'::jsonb) into next_config from public.brand_settings where slug='golden-oremar' for update;
  release_config:=coalesce(next_config->'releaseSetup','{}'::jsonb);
  payment_config:=coalesce(next_config->'payments','{}'::jsonb);
  release_config:=jsonb_set(release_config,'{publicShareOrigin}',jsonb_build_object('url',origin_value,'status','configured'),true);
  release_config:=jsonb_set(release_config,'{payment}',coalesce(release_config->'payment','{}'::jsonb)||jsonb_build_object('provider','iyzico','callbackPath','/payment/iyzico/return','returnUrl',return_url_value,'status','return_url_configured_provider_credentials_required'),true);
  release_config:=jsonb_set(release_config,'{transactionalEmail}',coalesce(release_config->'transactionalEmail','{}'::jsonb)||jsonb_build_object('from',email_from_value,'status','sender_configured_api_key_required'),true);
  release_config:=jsonb_set(release_config,'{notifications}',coalesce(release_config->'notifications','{}'::jsonb)||jsonb_build_object('fcmProjectId',fcm_project_value,'apnsBundleId',apns_bundle_value,'fcm','credentials_required','apns','credentials_required'),true);
  release_config:=jsonb_set(release_config,'{socialOAuth}',coalesce(release_config->'socialOAuth','{}'::jsonb)||jsonb_build_object('googleClientId',google_client_value,'facebookAppId',facebook_app_value,'status','public_ids_configured_provider_secrets_required'),true);
  release_config:=jsonb_set(release_config,'{productionEnabled}',to_jsonb(coalesce(p_activate_for_production,false)),true);
  payment_config:=payment_config||jsonb_build_object('return_url',return_url_value,'provider','iyzico','mode','provider');
  next_config:=jsonb_set(jsonb_set(next_config,'{releaseSetup}',release_config,true),'{payments}',payment_config,true);
  update public.brand_settings set public_config=next_config,updated_at=timezone('utc',now()) where slug='golden-oremar';

  insert into private.admin_audit_logs(actor_user_id,action,target_type,target_id,details)
  values(caller_id,'brand.release_configuration_updated','brand_settings','golden-oremar',jsonb_build_object('productionActivated',coalesce(p_activate_for_production,false),'publicOrigin',origin_value));
  return private.super_admin_get_release_setup_v2();
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_update_storefront_media_v1(p_producer_id uuid, p_logo_path text, p_cover_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null or not coalesce(private.has_permission('product.publish'),false) then raise exception 'permission_required:product.publish' using errcode='42501'; end if;
  if not exists(select 1 from public.producers p where p.id=p_producer_id and p.store_kind='official' and p.deleted_at is null) then raise exception 'official_store_only' using errcode='42501'; end if;
  raise exception 'storefront_media_legacy_retired' using errcode='55000';
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_update_storefront_presentation_v1(p_producer_id uuid, p_launch_audience_count bigint, p_launch_audience_label text, p_storefront_tier text, p_storefront_theme text, p_headline text, p_subheadline text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid(); row public.producers%rowtype; label_value text:=btrim(coalesce(p_launch_audience_label,'')); headline_value text:=nullif(btrim(coalesce(p_headline,'')),''); subheadline_value text:=nullif(btrim(coalesce(p_subheadline,'')),'');
begin
  if caller_id is null or not coalesce(private.has_permission('product.publish'),false) then raise exception 'permission_required:product.publish' using errcode='42501'; end if;
  if p_launch_audience_count is null or p_launch_audience_count<0 or p_launch_audience_count>1000000000 then raise exception 'invalid_launch_audience_count' using errcode='22023'; end if;
  if char_length(label_value) not between 2 and 60 then raise exception 'invalid_launch_audience_label' using errcode='22023'; end if;
  if p_storefront_tier not in ('standard','verified','signature') then raise exception 'invalid_storefront_tier' using errcode='22023'; end if;
  if p_storefront_theme not in ('heritage','emerald','midnight','ivory') then raise exception 'invalid_storefront_theme' using errcode='22023'; end if;
  if headline_value is not null and char_length(headline_value) not between 2 and 140 then raise exception 'invalid_storefront_headline' using errcode='22023'; end if;
  if subheadline_value is not null and char_length(subheadline_value) not between 2 and 320 then raise exception 'invalid_storefront_subheadline' using errcode='22023'; end if;
  update public.producers set launch_audience_count=p_launch_audience_count,launch_audience_label=label_value,storefront_tier=p_storefront_tier,storefront_theme=p_storefront_theme,storefront_headline=headline_value,storefront_subheadline=subheadline_value,updated_at=timezone('utc',now())
  where id=p_producer_id and store_kind='official' and deleted_at is null returning * into row;
  if row.id is null then raise exception 'official_store_only' using errcode='42501'; end if;
  insert into private.admin_audit_logs(actor_user_id,action,target_type,target_id,details)
  values(caller_id,'storefront.presentation_updated','producer',row.id::text,jsonb_build_object('storeKind',row.store_kind,'tier',row.storefront_tier,'theme',row.storefront_theme,'launchAudienceCount',row.launch_audience_count,'launchAudienceLabel',row.launch_audience_label));
  return jsonb_build_object('id',row.id,'tier',row.storefront_tier,'theme',row.storefront_theme,'launchAudienceCount',row.launch_audience_count,'launchAudienceLabel',row.launch_audience_label,'headline',row.storefront_headline,'subheadline',row.storefront_subheadline,'updatedAt',row.updated_at);
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_update_variant_shipping_weight_v1(p_variant_id uuid, p_weight_grams integer, p_expected_updated_at timestamp with time zone, p_verification_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); current_row public.product_variants%rowtype; note_value text:=btrim(coalesce(p_verification_note,'')); updated public.product_variants%rowtype;
begin
  if caller_id is null or not coalesce(private.has_permission('shipping.manage'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
  if p_variant_id is null then raise exception 'variant_required' using errcode='22023'; end if;
  if p_weight_grams is null or p_weight_grams<1 or p_weight_grams>100000000 then raise exception 'invalid_shipping_weight' using errcode='22023'; end if;
  if char_length(note_value) not between 10 and 500 then raise exception 'shipping_weight_verification_note_required' using errcode='22023'; end if;
  select pv.* into current_row from public.product_variants pv join public.products p on p.id=pv.product_id where pv.id=p_variant_id and p.deleted_at is null for update of pv;
  if current_row.id is null then raise exception 'variant_not_found' using errcode='P0002'; end if;
  if p_expected_updated_at is null or current_row.updated_at is distinct from p_expected_updated_at then raise exception 'shipping_weight_conflict' using errcode='40001'; end if;
  update public.product_variants
  set weight_grams=p_weight_grams,
      shipping_weight_source='measured',
      shipping_weight_note=note_value,
      shipping_weight_verified_at=timezone('utc',now()),
      updated_at=timezone('utc',now())
  where id=p_variant_id returning * into updated;
  insert into private.admin_audit_logs(actor_user_id,action,target_type,target_id,details)
  values(caller_id,'inventory.shipping_weight_verified','product_variant',updated.id,jsonb_build_object('previousWeightGrams',current_row.weight_grams,'nextWeightGrams',updated.weight_grams,'previousSource',current_row.shipping_weight_source,'nextSource',updated.shipping_weight_source,'verificationNote',note_value));
  return jsonb_build_object('ok',true,'variantId',updated.id,'weightGrams',updated.weight_grams,'weightSource',updated.shipping_weight_source,'verifiedAt',updated.shipping_weight_verified_at,'updatedAt',updated.updated_at);
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_upsert_legal_document_v1(p_slug text, p_locale text, p_title text, p_summary text, p_markdown text, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); slug_value text:=lower(btrim(coalesce(p_slug,''))); locale_value text:=lower(btrim(coalesce(p_locale,''))); title_value text:=btrim(coalesce(p_title,'')); summary_value text:=btrim(coalesce(p_summary,'')); markdown_value text:=btrim(coalesce(p_markdown,'')); status_value text:=lower(btrim(coalesce(p_status,''))); row_value public.content_entries%rowtype;
begin
  if caller_id is null or not coalesce(private.has_permission('system.configure'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
  if slug_value not in ('about','returns','privacy','terms') then raise exception 'invalid_legal_slug' using errcode='22023'; end if;
  if locale_value not in ('tr','en','de','fr','ku','ar') then raise exception 'invalid_legal_locale' using errcode='22023'; end if;
  if char_length(title_value) not between 2 and 240 then raise exception 'invalid_legal_title' using errcode='22023'; end if;
  if char_length(summary_value)>2000 or char_length(markdown_value)>200000 then raise exception 'legal_document_too_large' using errcode='22023'; end if;
  if status_value not in ('draft','published') then raise exception 'invalid_legal_status' using errcode='22023'; end if;
  if status_value='published' and char_length(markdown_value)<100 then raise exception 'legal_document_too_short_to_publish' using errcode='22023'; end if;
  insert into public.content_entries(content_type,slug,title,summary,body_markdown,body_html_sanitized,author_user_id,status,locale,published_at,metadata,updated_at,deleted_at)
  values('legal',slug_value,title_value,summary_value,markdown_value,'',caller_id,status_value,locale_value,case when status_value='published' then timezone('utc',now()) else null end,jsonb_build_object('managedBy','super_admin_legal_v1'),timezone('utc',now()),null)
  on conflict(content_type,slug,locale) do update set title=excluded.title,summary=excluded.summary,body_markdown=excluded.body_markdown,body_html_sanitized='',author_user_id=caller_id,status=excluded.status,published_at=case when excluded.status='published' then coalesce(public.content_entries.published_at,timezone('utc',now())) else null end,metadata=public.content_entries.metadata||jsonb_build_object('managedBy','super_admin_legal_v1'),updated_at=timezone('utc',now()),deleted_at=null
  returning * into row_value;
  insert into private.admin_audit_logs(actor_user_id,action,target_type,target_id,details)
  values(caller_id,'content.legal_document_upserted','content_entry',row_value.id,jsonb_build_object('slug',slug_value,'locale',locale_value,'status',status_value));
  return jsonb_build_object('id',row_value.id,'slug',row_value.slug,'locale',row_value.locale,'title',row_value.title,'summary',row_value.summary,'markdown',row_value.body_markdown,'status',row_value.status,'publishedAt',row_value.published_at,'updatedAt',row_value.updated_at);
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_upsert_release_origin_v1(p_origin text, p_make_primary boolean DEFAULT false, p_is_active boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  origin_value text:=regexp_replace(btrim(coalesce(p_origin,'')),'/+$','','g');
  next_config jsonb;
  release_config jsonb;
begin
  if caller_id is null or not coalesce(private.has_permission('system.configure'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
  if origin_value='' or char_length(origin_value)>2048 or origin_value !~ '^https://[^[:space:]/?#]+(?::[0-9]{1,5})?$' then raise exception 'invalid_public_origin' using errcode='22023'; end if;

  if coalesce(p_make_primary,false) then
    update private.super_admin_release_origins_v1 set is_primary=false,updated_at=timezone('utc',now()),updated_by=caller_id where is_primary=true;
  end if;

  insert into private.super_admin_release_origins_v1(origin,is_primary,is_active,created_by,updated_by)
  values(origin_value,coalesce(p_make_primary,false),coalesce(p_is_active,true),caller_id,caller_id)
  on conflict(origin) do update set
    is_primary=case when coalesce(p_make_primary,false) then true else private.super_admin_release_origins_v1.is_primary end,
    is_active=excluded.is_active,
    updated_at=timezone('utc',now()),
    updated_by=caller_id;

  if coalesce(p_make_primary,false) then
    update private.super_admin_company_configuration_v1
      set public_origin=origin_value,updated_at=timezone('utc',now()),updated_by=caller_id
    where singleton=true;

    select coalesce(public_config,'{}'::jsonb) into next_config
    from public.brand_settings where slug='golden-oremar' for update;
    release_config:=coalesce(next_config->'releaseSetup','{}'::jsonb);
    release_config:=jsonb_set(release_config,'{publicShareOrigin}',jsonb_build_object('url',origin_value,'status','configured'),true);
    next_config:=jsonb_set(next_config,'{releaseSetup}',release_config,true);
    update public.brand_settings set public_config=next_config,updated_at=timezone('utc',now()) where slug='golden-oremar';
  end if;

  insert into private.admin_audit_logs(actor_user_id,action,target_type,target_id,details)
  values(caller_id,'brand.release_origin_upserted','release_origin',origin_value,jsonb_build_object('makePrimary',coalesce(p_make_primary,false),'active',coalesce(p_is_active,true)));
  return private.super_admin_list_release_origins_v1();
end;
$function$;

CREATE OR REPLACE FUNCTION private.super_admin_void_platform_expense_v1(p_expense_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); reason_value text:=btrim(coalesce(p_reason,'')); row private.platform_expenses%rowtype;
begin
 if caller_id is null or not coalesce(private.has_permission('finance.manage'),false) then raise exception 'super_admin_required' using errcode='42501'; end if;
 if char_length(reason_value) not between 8 and 1000 then raise exception 'expense_void_reason_required' using errcode='22023'; end if;
 select * into row from private.platform_expenses where id=p_expense_id for update;
 if row.id is null then raise exception 'expense_not_found' using errcode='P0002'; end if;
 if row.status='void' then raise exception 'expense_already_void' using errcode='55000'; end if;
 if exists(select 1 from private.accounting_periods ap where ap.currency=row.currency and row.spent_on between ap.period_from and ap.period_to) then raise exception 'closed_period_expense_cannot_be_voided' using errcode='55000'; end if;
 update private.platform_expenses set status='void',void_reason=reason_value,voided_by=caller_id,voided_at=timezone('utc',now()),updated_at=timezone('utc',now()) where id=row.id;
 return jsonb_build_object('id',row.id,'status','void');
end;$function$;

CREATE OR REPLACE FUNCTION private.sync_order_promotion_redemption_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.status='confirmed' and new.payment_status='paid'
    and (old.status is distinct from new.status or old.payment_status is distinct from new.payment_status) then
    perform private.consume_order_promotion_v1(new.id);
  elsif new.status='cancelled' and old.status is distinct from new.status then
    perform private.release_order_promotion_v1(new.id);
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.sync_producer_finance_from_order_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin if new.payment_status='paid' and old.payment_status is distinct from new.payment_status then perform private.record_order_producer_sales_v1(new.id); end if; return new; end;$function$;

CREATE OR REPLACE FUNCTION private.sync_producer_finance_from_refund_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.status='succeeded' and (tg_op='INSERT' or old.status is distinct from new.status) then
    perform private.record_refund_producer_reversal_v1(new.id);
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.toggle_customer_favorite_impl_v1(p_product_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); product_id_value uuid; reference_value text;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_product_reference,''))) not between 1 and 200 then raise exception 'invalid_product_reference' using errcode='22023'; end if;
  select product.id,coalesce(product.legacy_id,product.id::text) into product_id_value,reference_value
  from public.products product
  join public.producers producer on producer.id=product.producer_id
  where (product.id::text=btrim(p_product_reference) or product.legacy_id=btrim(p_product_reference) or product.slug=btrim(p_product_reference))
    and product.status='published' and product.is_active=true and product.deleted_at is null
    and producer.status='active' and producer.is_verified=true and producer.deleted_at is null
  order by case when product.legacy_id=btrim(p_product_reference) then 0 else 1 end limit 1;
  if product_id_value is null then raise exception 'product_not_available' using errcode='P0002'; end if;
  perform pg_advisory_xact_lock(hashtextextended(caller_id::text||':'||product_id_value::text,85028));
  if exists(select 1 from public.favorites where user_id=caller_id and product_id=product_id_value) then
    delete from public.favorites where user_id=caller_id and product_id=product_id_value;
    return jsonb_build_object('productReference',reference_value,'isFavorite',false);
  end if;
  if (select count(*) from public.favorites where user_id=caller_id)>=500 then raise exception 'favorite_limit_exceeded' using errcode='54000'; end if;
  insert into public.favorites(user_id,product_id) values(caller_id,product_id_value);
  return jsonb_build_object('productReference',reference_value,'isFavorite',true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.toggle_my_content_favorite_v1(p_content_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  entry public.content_entries%rowtype;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if not exists(select 1 from public.profiles where id=caller_id and status='active' and deleted_at is null) then raise exception 'active_profile_required' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_content_reference,''))) not between 1 and 240 then raise exception 'invalid_content_reference' using errcode='22023'; end if;

  select item.* into entry
  from public.content_entries item
  where (item.id::text=btrim(p_content_reference) or item.legacy_id=btrim(p_content_reference) or item.slug=btrim(p_content_reference))
    and item.status='published' and item.deleted_at is null
    and item.content_type in ('recipe','health_guide','product_health')
    and (item.published_at is null or item.published_at<=timezone('utc',now()))
  order by case when item.id::text=btrim(p_content_reference) then 0 when item.slug=btrim(p_content_reference) then 1 else 2 end
  limit 1;
  if entry.id is null then raise exception 'content_not_found' using errcode='P0002'; end if;

  perform pg_advisory_xact_lock(hashtextextended(caller_id::text||':'||entry.id::text,92418));
  if exists(select 1 from private.content_favorites where user_id=caller_id and content_id=entry.id) then
    delete from private.content_favorites where user_id=caller_id and content_id=entry.id;
    return jsonb_build_object('contentId',entry.id,'slug',entry.slug,'isFavorite',false);
  end if;
  if (select count(*) from private.content_favorites where user_id=caller_id)>=500 then raise exception 'content_favorite_limit_exceeded' using errcode='54000'; end if;
  insert into private.content_favorites(user_id,content_id) values(caller_id,entry.id);
  return jsonb_build_object('contentId',entry.id,'slug',entry.slug,'isFavorite',true);
end;
$function$;

CREATE OR REPLACE FUNCTION private.toggle_producer_follow_v1(p_producer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); removed integer;
begin
 if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
 if not exists(select 1 from public.producers p where p.id=p_producer_id and p.status='active' and p.is_verified=true and p.deleted_at is null) then raise exception 'producer_not_available' using errcode='P0002'; end if;
 delete from private.producer_follows where user_id=caller_id and producer_id=p_producer_id;
 get diagnostics removed=row_count;
 if removed>0 then return jsonb_build_object('producerId',p_producer_id,'following',false); end if;
 insert into private.producer_follows(user_id,producer_id) values(caller_id,p_producer_id) on conflict do nothing;
 return jsonb_build_object('producerId',p_producer_id,'following',true);
end; $function$;

CREATE OR REPLACE FUNCTION private.unregister_push_device_v1(p_device_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  affected integer := 0;
begin
  if caller_id is null then
    raise exception 'authentication_required' using errcode = '42501';
  end if;

  update private.device_push_tokens
  set disabled_at = timezone('utc', now()),
      updated_at = timezone('utc', now())
  where id = p_device_id
    and user_id = caller_id
    and disabled_at is null;

  get diagnostics affected = row_count;
  return affected > 0;
end;
$function$;

CREATE OR REPLACE FUNCTION private.unregister_push_token_v1(p_token text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); hash_value text; affected integer;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  hash_value:=private.hash_push_token_v1(p_token);
  update private.device_push_tokens set disabled_at=timezone('utc',now()),updated_at=timezone('utc',now()) where user_id=caller_id and token_hash=hash_value and disabled_at is null;
  get diagnostics affected=row_count;
  return affected>0;
end;
$function$;

CREATE OR REPLACE FUNCTION private.unsubscribe_my_newsletter_v1()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); email_value text:=lower(btrim(coalesce(auth.jwt()->>'email',''))); affected integer;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  update private.newsletter_subscriptions set status='unsubscribed',unsubscribed_at=timezone('utc',now()),updated_at=timezone('utc',now())
  where (user_id=caller_id or (email_value<>'' and email_normalized=email_value)) and status in ('pending','active');
  get diagnostics affected=row_count;
  update public.profiles set marketing_consent=false,marketing_consent_at=null,updated_at=timezone('utc',now()) where id=caller_id;
  update private.user_notification_preferences set campaign_push=false,updated_at=timezone('utc',now()) where user_id=caller_id;
  return affected>0;
end;
$function$;

CREATE OR REPLACE FUNCTION private.unsubscribe_newsletter_v1(p_token text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare token_hash text:=private.hash_marketing_token_v1(p_token); sub private.newsletter_subscriptions%rowtype;
begin
  select * into sub from private.newsletter_subscriptions where unsubscribe_token_hash=token_hash for update;
  if sub.id is null then return false; end if;
  update private.newsletter_subscriptions set status='unsubscribed',unsubscribed_at=timezone('utc',now()),updated_at=timezone('utc',now()) where id=sub.id;
  if sub.user_id is not null then
    update public.profiles set marketing_consent=false,marketing_consent_at=null,updated_at=timezone('utc',now()) where id=sub.user_id;
    update private.user_notification_preferences set campaign_push=false,updated_at=timezone('utc',now()) where user_id=sub.user_id;
  end if;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION private.update_customer_avatar_v1(p_avatar_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  normalized_path text := nullif(btrim(coalesce(p_avatar_path, '')), '');
begin
  if caller_id is null then
    raise exception 'authentication_required' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.profiles p
    where p.id = caller_id and p.status = 'active' and p.deleted_at is null
  ) then
    raise exception 'active_profile_required' using errcode = '42501';
  end if;

  if normalized_path is not null then
    if char_length(normalized_path) > 500
       or split_part(normalized_path, '/', 1) <> caller_id::text
       or not exists (
         select 1 from storage.objects o
         where o.bucket_id = 'user-private' and o.name = normalized_path
       ) then
      raise exception 'invalid_avatar_path' using errcode = '22023';
    end if;
  end if;

  update public.profiles
  set avatar_path = normalized_path,
      updated_at = timezone('utc', now())
  where id = caller_id;

  return jsonb_build_object('avatar_path', normalized_path);
end;
$function$;

CREATE OR REPLACE FUNCTION private.update_customer_profile_impl_v1(p_display_name text, p_phone text, p_locale text, p_marketing_consent boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  profile_row public.profiles%rowtype;
  phone_digits text:=regexp_replace(coalesce(p_phone,''),'[^0-9]','','g');
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_display_name,''))) not between 2 and 120
     or char_length(coalesce(p_phone,''))>40
     or (phone_digits<>'' and char_length(phone_digits) not between 10 and 15)
     or p_locale not in ('tr','en','de','fr','ku','ar') then
    raise exception 'invalid_profile' using errcode='22023';
  end if;

  update public.profiles
  set display_name=btrim(p_display_name),
      phone=nullif(btrim(coalesce(p_phone,'')),''),
      locale=p_locale,
      marketing_consent=coalesce(p_marketing_consent,false),
      marketing_consent_at=case when coalesce(p_marketing_consent,false) then coalesce(marketing_consent_at,timezone('utc',now())) else null end,
      updated_at=timezone('utc',now())
  where id=caller_id and status='active' and deleted_at is null
  returning * into profile_row;
  if profile_row.id is null then raise exception 'active_profile_required' using errcode='42501'; end if;

  if not coalesce(p_marketing_consent,false) then
    update private.user_notification_preferences set campaign_push=false,updated_at=timezone('utc',now()) where user_id=caller_id and campaign_push=true;
  end if;

  return jsonb_build_object('userId',profile_row.id,'displayName',profile_row.display_name,'phone',coalesce(profile_row.phone,''),'locale',profile_row.locale,'marketingConsent',profile_row.marketing_consent);
end;
$function$;

CREATE OR REPLACE FUNCTION private.update_my_app_preferences_impl_v1(p_theme text DEFAULT NULL::text, p_notification_sound text DEFAULT NULL::text, p_notification_sound_enabled boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  uid uuid:=auth.uid();
  normalized_theme text:=nullif(lower(btrim(coalesce(p_theme,''))),'');
  normalized_sound text:=nullif(lower(btrim(coalesce(p_notification_sound,''))),'');
  row_value private.user_app_preferences%rowtype;
begin
  if uid is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if not exists(select 1 from public.profiles p where p.id=uid and p.status='active' and p.deleted_at is null) then raise exception 'active_profile_required' using errcode='42501'; end if;
  if normalized_theme is not null and normalized_theme not in ('light','dark','emerald','ruby','champagne') then raise exception 'invalid_app_theme' using errcode='22023'; end if;
  if normalized_sound is not null and normalized_sound not in ('oremar-drop','mountain-birds','dawn-rooster','partridge-call','highland-bell') then raise exception 'invalid_notification_sound' using errcode='22023'; end if;
  if normalized_theme is null and normalized_sound is null and p_notification_sound_enabled is null then raise exception 'app_preference_update_required' using errcode='22023'; end if;

  insert into private.user_app_preferences(user_id,theme,notification_sound,notification_sound_enabled)
  values(uid,normalized_theme,coalesce(normalized_sound,'oremar-drop'),coalesce(p_notification_sound_enabled,true))
  on conflict(user_id) do update set
    theme=coalesce(normalized_theme,private.user_app_preferences.theme),
    notification_sound=coalesce(normalized_sound,private.user_app_preferences.notification_sound),
    notification_sound_enabled=coalesce(p_notification_sound_enabled,private.user_app_preferences.notification_sound_enabled),
    updated_at=timezone('utc',now())
  returning * into row_value;

  return jsonb_build_object(
    'theme',row_value.theme,
    'notificationSound',row_value.notification_sound,
    'notificationSoundEnabled',row_value.notification_sound_enabled,
    'updatedAt',row_value.updated_at
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.update_my_notification_preferences_v1(p_push_enabled boolean, p_order_push boolean, p_payment_push boolean, p_shipment_push boolean, p_return_push boolean, p_message_push boolean, p_review_push boolean, p_producer_push boolean, p_system_push boolean, p_campaign_push boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); marketing_allowed boolean;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select marketing_consent into marketing_allowed from public.profiles where id=caller_id and status='active' and deleted_at is null;
  if coalesce(p_campaign_push,false) and not coalesce(marketing_allowed,false) then raise exception 'campaign_push_requires_marketing_consent' using errcode='22023'; end if;
  insert into private.user_notification_preferences(user_id,push_enabled,order_push,payment_push,shipment_push,return_push,message_push,review_push,producer_push,system_push,campaign_push,updated_at)
  values(caller_id,coalesce(p_push_enabled,true),coalesce(p_order_push,true),coalesce(p_payment_push,true),coalesce(p_shipment_push,true),coalesce(p_return_push,true),coalesce(p_message_push,true),coalesce(p_review_push,true),coalesce(p_producer_push,true),coalesce(p_system_push,true),coalesce(p_campaign_push,false),timezone('utc',now()))
  on conflict(user_id) do update set push_enabled=excluded.push_enabled,order_push=excluded.order_push,payment_push=excluded.payment_push,shipment_push=excluded.shipment_push,return_push=excluded.return_push,message_push=excluded.message_push,review_push=excluded.review_push,producer_push=excluded.producer_push,system_push=excluded.system_push,campaign_push=excluded.campaign_push,updated_at=excluded.updated_at;
  return private.get_my_notification_preferences_v1();
end;
$function$;

CREATE OR REPLACE FUNCTION private.update_my_payment_method_metadata_impl_v2(p_payment_method_id uuid, p_nickname text DEFAULT NULL::text, p_billing_name text DEFAULT NULL::text, p_billing_country_code text DEFAULT NULL::text, p_billing_postal_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  uid uuid:=auth.uid();
  target private.customer_payment_methods%rowtype;
  normalized_nickname text:=nullif(btrim(coalesce(p_nickname,'')),'');
  normalized_name text:=nullif(btrim(coalesce(p_billing_name,'')),'');
  normalized_country text:=nullif(upper(btrim(coalesce(p_billing_country_code,''))),'');
  normalized_postal text:=nullif(btrim(coalesce(p_billing_postal_code,'')),'');
begin
  if uid is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if p_payment_method_id is null then raise exception 'payment_method_required' using errcode='22023'; end if;
  if normalized_nickname is not null and (char_length(normalized_nickname)>40 or normalized_nickname ~ '[[:cntrl:]]') then raise exception 'invalid_payment_method_nickname' using errcode='22023'; end if;
  if normalized_name is not null and (char_length(normalized_name) not between 2 and 120 or normalized_name ~ '[[:cntrl:]]') then raise exception 'invalid_billing_name' using errcode='22023'; end if;
  if normalized_country is not null and normalized_country !~ '^[A-Z]{2}$' then raise exception 'invalid_billing_country' using errcode='22023'; end if;
  if normalized_postal is not null and (char_length(normalized_postal)>30 or normalized_postal ~ '[[:cntrl:]]') then raise exception 'invalid_billing_postal_code' using errcode='22023'; end if;
  select * into target
  from private.customer_payment_methods p
  where p.id=p_payment_method_id and p.user_id=uid and p.status in ('active','expired')
  for update;
  if target.id is null then raise exception 'payment_method_not_found' using errcode='P0002'; end if;
  update private.customer_payment_methods
  set nickname=normalized_nickname,
      billing_name=normalized_name,
      billing_country_code=normalized_country,
      billing_postal_code=normalized_postal,
      updated_at=timezone('utc',now())
  where id=target.id;
  return jsonb_build_object(
    'ok',true,'id',target.id,'nickname',normalized_nickname,'billingName',normalized_name,
    'billingCountryCode',normalized_country,'billingPostalCode',normalized_postal
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.update_my_producer_profile_v2(p_display_name text, p_description text, p_story text, p_logo_path text, p_cover_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  producer public.producers%rowtype;
  clean_logo_path text:=nullif(btrim(coalesce(p_logo_path,'')),'');
  clean_cover_path text:=nullif(btrim(coalesce(p_cover_path,'')),'');
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into producer from public.producers where owner_user_id=caller_id and status in ('active','suspended') and deleted_at is null order by created_at desc limit 1;
  if producer.id is null then raise exception 'producer_profile_not_editable' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_display_name,''))) not between 2 and 120 then raise exception 'invalid_producer_display_name' using errcode='22023'; end if;
  if char_length(btrim(coalesce(p_description,'')))>1200 then raise exception 'producer_description_too_long' using errcode='22023'; end if;
  if char_length(btrim(coalesce(p_story,'')))>5000 then raise exception 'producer_story_too_long' using errcode='22023'; end if;
  if clean_logo_path is distinct from producer.logo_path and clean_logo_path is not null and private.store_branding_verified_path_v1(producer.id,'logo',clean_logo_path) is null then raise exception 'invalid_producer_logo_path' using errcode='22023'; end if;
  if clean_cover_path is distinct from producer.cover_path and clean_cover_path is not null and private.store_branding_verified_path_v1(producer.id,'cover',clean_cover_path) is null then raise exception 'invalid_producer_cover_path' using errcode='22023'; end if;
  update public.producers
  set display_name=btrim(p_display_name),description=btrim(coalesce(p_description,'')),story=btrim(coalesce(p_story,'')),logo_path=clean_logo_path,cover_path=clean_cover_path,updated_at=timezone('utc',now())
  where id=producer.id;
  return private.get_my_producer_profile_v1();
end;
$function$;

CREATE OR REPLACE FUNCTION private.update_my_review_v1(p_review_id uuid, p_rating integer, p_title text, p_body text, p_media_paths text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); review_row public.reviews%rowtype; normalized_title text:=nullif(btrim(coalesce(p_title,'')),''); normalized_body text:=btrim(coalesce(p_body,'')); normalized_media text[];
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  perform private.require_current_terms_v1();
  if p_rating not between 1 and 5 then raise exception 'invalid_review_rating' using errcode='22023'; end if;
  if normalized_title is not null and char_length(normalized_title)>120 then raise exception 'review_title_too_long' using errcode='22023'; end if;
  if char_length(normalized_body) not between 10 and 3000 then raise exception 'invalid_review_body' using errcode='22023'; end if;
  normalized_media:=private.validate_review_media_paths_v1(p_media_paths);
  select * into review_row from public.reviews where id=p_review_id and user_id=caller_id for update;
  if review_row.id is null then raise exception 'review_not_found' using errcode='P0002'; end if;
  if review_row.status='withdrawn' then raise exception 'withdrawn_review_cannot_be_edited' using errcode='55000'; end if;
  update public.reviews set rating=p_rating,title=normalized_title,body=normalized_body,media_paths=normalized_media,status='pending',moderated_by=null,moderated_at=null,moderation_reason=null,merchant_reply=null,merchant_replied_at=null,merchant_reply_by=null,edited_at=timezone('utc',now()),updated_at=timezone('utc',now()) where id=review_row.id returning * into review_row;
  insert into private.outbox_events(aggregate_type,aggregate_id,event_type,payload) values('review',review_row.id,'review.resubmitted',jsonb_build_object('review_id',review_row.id,'user_id',caller_id));
  return jsonb_build_object('id',review_row.id,'rating',review_row.rating,'status',review_row.status,'editedAt',review_row.edited_at);
end; $function$;

CREATE OR REPLACE FUNCTION private.upsert_customer_address_impl_v1(p_address_id uuid, p_label text, p_recipient_name text, p_phone text, p_country_code text, p_province text, p_district text, p_neighborhood text, p_address_line text, p_postal_code text, p_delivery_notes text, p_is_default boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  address_row public.addresses%rowtype;
  make_default boolean;
  phone_digits text:=regexp_replace(coalesce(p_phone,''),'[^0-9]','','g');
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if not exists(select 1 from public.profiles where id=caller_id and status='active' and deleted_at is null) then raise exception 'active_profile_required' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_label,''))) not between 1 and 60
     or char_length(btrim(coalesce(p_recipient_name,''))) not between 2 and 120
     or char_length(coalesce(p_phone,''))>40
     or char_length(phone_digits) not between 10 and 15
     or upper(btrim(coalesce(p_country_code,''))) !~ '^[A-Z]{2}$'
     or char_length(btrim(coalesce(p_province,''))) not between 2 and 120
     or char_length(btrim(coalesce(p_district,''))) not between 2 and 120
     or char_length(coalesce(p_neighborhood,''))>160
     or char_length(btrim(coalesce(p_address_line,''))) not between 10 and 1000
     or char_length(coalesce(p_postal_code,''))>20
     or char_length(coalesce(p_delivery_notes,''))>500 then
    raise exception 'invalid_address' using errcode='22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(caller_id::text,85027));
  if p_address_id is not null and not exists(select 1 from public.addresses where id=p_address_id and user_id=caller_id and deleted_at is null) then raise exception 'address_not_found' using errcode='P0002'; end if;
  if p_address_id is null and (select count(*) from public.addresses where user_id=caller_id and deleted_at is null)>=20 then raise exception 'address_limit_exceeded' using errcode='54000'; end if;

  make_default:=coalesce(p_is_default,false) or not exists(select 1 from public.addresses where user_id=caller_id and deleted_at is null and is_default=true);
  if make_default then
    update public.addresses set is_default=false,updated_at=timezone('utc',now()) where user_id=caller_id and deleted_at is null and is_default=true;
  end if;

  if p_address_id is null then
    insert into public.addresses(user_id,label,recipient_name,phone,country_code,province,district,neighborhood,address_line,postal_code,delivery_notes,is_default)
    values(caller_id,btrim(p_label),btrim(p_recipient_name),btrim(p_phone),upper(btrim(p_country_code)),btrim(p_province),btrim(p_district),nullif(btrim(coalesce(p_neighborhood,'')),''),btrim(p_address_line),nullif(btrim(coalesce(p_postal_code,'')),''),nullif(btrim(coalesce(p_delivery_notes,'')),''),make_default)
    returning * into address_row;
  else
    update public.addresses
    set label=btrim(p_label),recipient_name=btrim(p_recipient_name),phone=btrim(p_phone),country_code=upper(btrim(p_country_code)),province=btrim(p_province),district=btrim(p_district),
        neighborhood=nullif(btrim(coalesce(p_neighborhood,'')),''),address_line=btrim(p_address_line),postal_code=nullif(btrim(coalesce(p_postal_code,'')),''),delivery_notes=nullif(btrim(coalesce(p_delivery_notes,'')),''),
        is_default=make_default,updated_at=timezone('utc',now())
    where id=p_address_id and user_id=caller_id and deleted_at is null
    returning * into address_row;
  end if;
  return to_jsonb(address_row);
end;
$function$;

CREATE OR REPLACE FUNCTION private.upsert_customer_address_v2_impl(p_address_id uuid, p_label text, p_recipient_name text, p_phone text, p_country_code text, p_administrative_area text, p_city text, p_locality text, p_address_line1 text, p_address_line2 text, p_postal_code text, p_delivery_notes text, p_is_default boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  address_row public.addresses%rowtype;
  make_default boolean;
  phone_value text:=btrim(coalesce(p_phone,''));
  phone_digits text:=regexp_replace(coalesce(p_phone,''),'[^0-9]','','g');
  country_value text:=upper(btrim(coalesce(p_country_code,'')));
  admin_value text:=nullif(btrim(coalesce(p_administrative_area,'')),'');
  city_value text:=btrim(coalesce(p_city,''));
  locality_value text:=nullif(btrim(coalesce(p_locality,'')),'');
  line1_value text:=btrim(coalesce(p_address_line1,''));
  line2_value text:=nullif(btrim(coalesce(p_address_line2,'')),'');
  merged_line text;
  province_value text;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if not exists(select 1 from public.profiles where id=caller_id and status='active' and deleted_at is null) then raise exception 'active_profile_required' using errcode='42501'; end if;

  if char_length(btrim(coalesce(p_label,''))) not between 1 and 60
     or char_length(btrim(coalesce(p_recipient_name,''))) not between 2 and 120
     or char_length(phone_value)>40
     or char_length(phone_digits) not between 7 and 20
     or country_value !~ '^[A-Z]{2}$'
     or (admin_value is not null and char_length(admin_value)>120)
     or char_length(city_value) not between 1 and 120
     or (locality_value is not null and char_length(locality_value)>160)
     or char_length(line1_value) not between 5 and 1000
     or (line2_value is not null and char_length(line2_value)>500)
     or char_length(coalesce(p_postal_code,''))>30
     or char_length(coalesce(p_delivery_notes,''))>500
     or btrim(coalesce(p_label,'')) ~ '[[:cntrl:]]'
     or btrim(coalesce(p_recipient_name,'')) ~ '[[:cntrl:]]'
     or phone_value ~ '[[:cntrl:]]'
     or city_value ~ '[[:cntrl:]]'
     or line1_value ~ '[[:cntrl:]]'
  then raise exception 'invalid_address' using errcode='22023'; end if;

  if admin_value is not null and admin_value ~ '[[:cntrl:]]' then raise exception 'invalid_address' using errcode='22023'; end if;
  if locality_value is not null and locality_value ~ '[[:cntrl:]]' then raise exception 'invalid_address' using errcode='22023'; end if;
  if line2_value is not null and line2_value ~ '[[:cntrl:]]' then raise exception 'invalid_address' using errcode='22023'; end if;

  merged_line:=line1_value;
  if line2_value is not null then merged_line:=merged_line||E'\n'||line2_value; end if;
  if char_length(merged_line)>1000 then raise exception 'invalid_address' using errcode='22023'; end if;
  province_value:=coalesce(admin_value,city_value);

  perform pg_advisory_xact_lock(hashtextextended(caller_id::text,85027));
  if p_address_id is not null and not exists(select 1 from public.addresses where id=p_address_id and user_id=caller_id and deleted_at is null) then raise exception 'address_not_found' using errcode='P0002'; end if;
  if p_address_id is null and (select count(*) from public.addresses where user_id=caller_id and deleted_at is null)>=20 then raise exception 'address_limit_exceeded' using errcode='54000'; end if;

  make_default:=coalesce(p_is_default,false) or not exists(select 1 from public.addresses where user_id=caller_id and deleted_at is null and is_default=true);
  if make_default then update public.addresses set is_default=false,updated_at=timezone('utc',now()) where user_id=caller_id and deleted_at is null and is_default=true; end if;

  if p_address_id is null then
    insert into public.addresses(user_id,label,recipient_name,phone,country_code,province,district,neighborhood,address_line,postal_code,delivery_notes,is_default)
    values(caller_id,btrim(p_label),btrim(p_recipient_name),phone_value,country_value,province_value,city_value,locality_value,merged_line,nullif(btrim(coalesce(p_postal_code,'')),''),nullif(btrim(coalesce(p_delivery_notes,'')),''),make_default)
    returning * into address_row;
  else
    update public.addresses
    set label=btrim(p_label),recipient_name=btrim(p_recipient_name),phone=phone_value,country_code=country_value,province=province_value,district=city_value,
        neighborhood=locality_value,address_line=merged_line,postal_code=nullif(btrim(coalesce(p_postal_code,'')),''),delivery_notes=nullif(btrim(coalesce(p_delivery_notes,'')),''),
        is_default=make_default,updated_at=timezone('utc',now())
    where id=p_address_id and user_id=caller_id and deleted_at is null
    returning * into address_row;
  end if;
  return to_jsonb(address_row);
end;
$function$;

CREATE OR REPLACE FUNCTION private.user_has_permission_v1(p_user_id uuid, p_permission_key text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select p_user_id is not null
    and p_permission_key is not null
    and exists(
      select 1
      from private.user_roles ur
      join private.role_permissions rp on rp.role=ur.role
      join private.permissions permission on permission.permission_key=rp.permission_key and permission.is_active=true
      join public.profiles profile on profile.id=ur.user_id
      where ur.user_id=p_user_id
        and rp.permission_key=p_permission_key
        and (ur.expires_at is null or ur.expires_at>timezone('utc',now()))
        and profile.status='active'
        and profile.deleted_at is null
        and not coalesce((private.platform_access_block_v1(ur.user_id)->>'blocked')::boolean,false)
    );
$function$;

CREATE OR REPLACE FUNCTION private.user_has_verified_totp_factor_v1(p_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select p_user_id is not null and exists(
    select 1
    from auth.mfa_factors factor
    where factor.user_id=p_user_id
      and factor.status::text='verified'
      and factor.factor_type::text='totp'
  );
$function$;

CREATE OR REPLACE FUNCTION private.user_requires_staff_mfa_v1(p_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ select p_user_id is not null and exists( select 1 from private.user_roles ur join public.profiles profile on profile.id=ur.user_id where ur.user_id=p_user_id and ur.role in ('support','content_editor','operations','moderator','admin') and (ur.expires_at is null or ur.expires_at>timezone('utc',now())) and profile.status='active' and profile.deleted_at is null and not coalesce((private.platform_access_block_v1(ur.user_id)->>'blocked')::boolean,false) ); $function$;

CREATE OR REPLACE FUNCTION private.validate_event_provider_item_transaction_v1(p_reservation_id uuid, p_provider_payload jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  payload jsonb:=coalesce(p_provider_payload,'{}'::jsonb);
  finance private.event_reservation_finance%rowtype;
  tx jsonb;
  tx_id text;
begin
  if p_reservation_id is null then raise exception 'event_reservation_required' using errcode='22023'; end if;
  if jsonb_typeof(payload)<>'object' or payload->>'signatureVerified'<>'true' then
    raise exception 'verified_provider_payload_required' using errcode='55000';
  end if;
  if jsonb_typeof(payload->'itemTransactions')<>'array' or jsonb_array_length(payload->'itemTransactions')<>1 then
    raise exception 'provider_event_item_transaction_required' using errcode='55000';
  end if;

  select * into finance
  from private.event_reservation_finance f
  where f.reservation_id=p_reservation_id;
  if finance.reservation_id is null or finance.total_minor<=0 then
    raise exception 'event_payment_context_not_found' using errcode='P0002';
  end if;

  tx:=payload->'itemTransactions'->0;
  if jsonb_typeof(tx)<>'object' or tx->>'itemId'<>p_reservation_id::text then
    raise exception 'provider_event_item_reference_mismatch' using errcode='55000';
  end if;
  tx_id:=nullif(btrim(coalesce(tx->>'paymentTransactionId','')),'');
  if tx_id is null or char_length(tx_id)>220 then
    raise exception 'provider_event_payment_transaction_invalid' using errcode='55000';
  end if;
  if coalesce(tx->>'price','') !~ '^[0-9]+([.][0-9]+)?$'
    or round((tx->>'price')::numeric*100)::bigint<>finance.total_minor then
    raise exception 'provider_event_price_mismatch' using errcode='55000';
  end if;
  if finance.producer_id is not null and (
    coalesce(tx->>'subMerchantPrice','') !~ '^[0-9]+([.][0-9]+)?$'
    or round((tx->>'subMerchantPrice')::numeric*100)::bigint<>finance.producer_net_minor
  ) then
    raise exception 'provider_event_submerchant_split_mismatch' using errcode='55000';
  end if;

  return 1;
end;
$function$;

CREATE OR REPLACE FUNCTION private.validate_message_attachments_v1(p_attachment_paths text[])
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid();
  path_value text;
  normalized text[]:='{}'::text[];
  settings private.message_moderation_settings%rowtype;
  object_meta jsonb;
  object_type text;
  object_size bigint;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into settings from private.message_moderation_settings where singleton=true;
  if not found then raise exception 'message_moderation_configuration_missing' using errcode='55000'; end if;
  if not settings.allow_attachments and coalesce(array_length(p_attachment_paths,1),0)>0 then raise exception 'message_attachments_disabled' using errcode='22023'; end if;
  if coalesce(array_length(p_attachment_paths,1),0)>settings.max_attachments then raise exception 'message_attachment_limit_exceeded' using errcode='22023'; end if;

  foreach path_value in array coalesce(p_attachment_paths,'{}'::text[])
  loop
    path_value:=btrim(coalesce(path_value,''));
    if char_length(path_value) not between 1 and 500 or split_part(path_value,'/',1)<>caller_id::text then raise exception 'invalid_message_attachment_path' using errcode='22023'; end if;
    select object.metadata into object_meta from storage.objects object where object.bucket_id='message-attachments' and object.name=path_value;
    if object_meta is null then raise exception 'message_attachment_not_uploaded' using errcode='22023'; end if;
    object_type:=lower(coalesce(object_meta->>'mimetype',''));
    object_size:=coalesce((object_meta->>'size')::bigint,0);
    if object_size<=0 or object_size>settings.max_attachment_mb::bigint*1024*1024 then raise exception 'message_attachment_size_not_allowed' using errcode='22023'; end if;
    if object_type like 'image/%' then
      if not settings.allow_images or object_type not in ('image/jpeg','image/png','image/webp','image/avif') then raise exception 'message_attachment_type_not_allowed' using errcode='22023'; end if;
    elsif object_type='application/pdf' then
      if not settings.allow_pdf then raise exception 'message_attachment_type_not_allowed' using errcode='22023'; end if;
    else
      raise exception 'message_attachment_type_not_allowed' using errcode='22023';
    end if;
    normalized:=array_append(normalized,path_value);
  end loop;
  return normalized;
end;
$function$;

CREATE OR REPLACE FUNCTION private.validate_order_export_eligibility_v1(p_order_id uuid, p_country_code text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  country_code text:=upper(btrim(coalesce(p_country_code,'')));
  item record;
  result jsonb;
  zone_row public.shipping_zones%rowtype;
begin
  if country_code='TR' then return; end if;
  zone_row:=private.resolve_shipping_zone_v1(country_code);
  if zone_row.id is null then raise exception 'shipping_zone_unavailable:%',country_code using errcode='55000'; end if;
  if zone_row.requires_manual_quote then raise exception 'manual_shipping_quote_required:%',country_code using errcode='55000'; end if;

  for item in select distinct order_item.product_id from public.order_items order_item where order_item.order_id=p_order_id and order_item.product_id is not null
  loop
    result:=private.check_product_export_eligibility_v1(item.product_id,country_code);
    if not coalesce((result->>'available')::boolean,false) then
      raise exception 'international_product_not_eligible:%:%',item.product_id,coalesce(result->>'reason','unknown') using errcode='55000';
    end if;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION private.validate_order_provider_item_transactions_v1(p_order_id uuid, p_provider_payload jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  payload jsonb:=coalesce(p_provider_payload,'{}'::jsonb);
  expected_count integer:=0;
  provider_count integer:=0;
begin
  if p_order_id is null then raise exception 'order_required' using errcode='22023'; end if;
  if jsonb_typeof(payload)<>'object' or payload->>'signatureVerified'<>'true' then
    raise exception 'verified_provider_payload_required' using errcode='55000';
  end if;
  if jsonb_typeof(payload->'itemTransactions')<>'array' then
    raise exception 'provider_item_transactions_required' using errcode='55000';
  end if;

  select count(*)::integer into expected_count
  from public.order_items oi
  where oi.order_id=p_order_id;
  if expected_count<1 or expected_count>100 then
    raise exception 'invalid_order_item_count' using errcode='55000';
  end if;

  provider_count:=jsonb_array_length(payload->'itemTransactions');
  if provider_count<>expected_count then
    raise exception 'provider_item_transaction_count_mismatch' using errcode='55000';
  end if;

  if exists(
    select 1
    from jsonb_array_elements(payload->'itemTransactions') tx
    where jsonb_typeof(tx)<>'object'
      or nullif(btrim(coalesce(tx->>'itemId','')),'') is null
      or nullif(btrim(coalesce(tx->>'paymentTransactionId','')),'') is null
      or char_length(btrim(coalesce(tx->>'paymentTransactionId','')))>220
  ) then
    raise exception 'provider_item_transaction_invalid' using errcode='55000';
  end if;

  if (
    select count(distinct tx->>'itemId')
    from jsonb_array_elements(payload->'itemTransactions') tx
  )<>provider_count then
    raise exception 'provider_item_id_duplicate' using errcode='55000';
  end if;

  if (
    select count(distinct tx->>'paymentTransactionId')
    from jsonb_array_elements(payload->'itemTransactions') tx
  )<>provider_count then
    raise exception 'provider_payment_transaction_duplicate' using errcode='55000';
  end if;

  if exists(
    select 1
    from jsonb_array_elements(payload->'itemTransactions') tx
    where not exists(
      select 1 from public.order_items oi
      where oi.order_id=p_order_id and oi.id::text=tx->>'itemId'
    )
  ) then
    raise exception 'provider_item_reference_mismatch' using errcode='55000';
  end if;

  if exists(
    select 1
    from public.order_items oi
    left join lateral(
      select tx
      from jsonb_array_elements(payload->'itemTransactions') tx
      where tx->>'itemId'=oi.id::text
      limit 1
    ) matched on true
    where oi.order_id=p_order_id
      and (
        matched.tx is null
        or coalesce(matched.tx->>'price','') !~ '^[0-9]+([.][0-9]+)?$'
        or round((matched.tx->>'price')::numeric*100)::bigint<>oi.line_total_minor
        or coalesce(matched.tx->>'subMerchantPrice','') !~ '^[0-9]+([.][0-9]+)?$'
        or round((matched.tx->>'subMerchantPrice')::numeric*100)::bigint<>
          greatest(0,oi.line_total_minor-round((((oi.unit_price_minor*oi.quantity)-oi.discount_minor)::numeric*oi.commission_basis_points_snapshot::numeric)/10000)::bigint)
      )
  ) then
    raise exception 'provider_item_financial_mismatch' using errcode='55000';
  end if;

  return expected_count;
end;
$function$;

CREATE OR REPLACE FUNCTION private.validate_paid_event_reservation_buyer_name_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare paid boolean:=false;
begin
 select e.ticket_price_minor>0 into paid from public.events e where e.id=new.event_id;
 if paid and (new.user_id is null or btrim(new.guest_name) !~ '^[^[:space:]]+[[:space:]]+[^[:space:]].*$') then raise exception 'paid_event_full_name_required' using errcode='22023'; end if;
 return new;
end;$function$;

CREATE OR REPLACE FUNCTION private.validate_payment_control_v1(p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  cfg jsonb:=coalesce(p_config,'{}'::jsonb);
  hosted boolean:=coalesce((cfg->>'checkout_form_enabled')::boolean,false);
  saved_card boolean:=coalesce((cfg->>'live_card_payments_enabled')::boolean,false);
  enrollment boolean:=coalesce((cfg->>'card_enrollment_enabled')::boolean,false);
begin
  if jsonb_typeof(cfg)<>'object' then raise exception 'invalid_payment_config' using errcode='22023'; end if;
  if enrollment and not saved_card then raise exception 'card_enrollment_requires_saved_card_payments' using errcode='22023'; end if;
  return jsonb_build_object(
    'mode','provider',
    'provider','iyzico',
    'checkout_form_enabled',hosted,
    'live_card_payments_enabled',saved_card,
    'card_enrollment_enabled',enrollment,
    'return_url',null,
    'requires_provider_configuration',not (hosted or saved_card)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.validate_product_change_payload_v1(p_product_id uuid, p_producer_id uuid, p_requested_by uuid, p_payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  producer_row public.producers%rowtype;
  product_row public.products%rowtype;
  key_name text;
  media_path text;
  gallery jsonb;
begin
  if p_payload is null or jsonb_typeof(p_payload)<>'object' or p_payload='{}'::jsonb or pg_column_size(p_payload)>262144 then
    raise exception 'invalid_product_change_payload' using errcode='22023';
  end if;
  select * into product_row from public.products where id=p_product_id;
  select * into producer_row from public.producers where id=p_producer_id and deleted_at is null;
  if product_row.id is null or producer_row.id is null or product_row.producer_id<>producer_row.id or producer_row.owner_user_id<>p_requested_by then
    raise exception 'product_change_context_invalid' using errcode='42501';
  end if;
  if product_row.status<>'published' then raise exception 'only_published_product_uses_change_request' using errcode='55000'; end if;
  if producer_row.status<>'active' or not producer_row.is_verified then raise exception 'verified_active_producer_required' using errcode='42501'; end if;

  for key_name in select jsonb_object_keys(p_payload)
  loop
    if key_name not in (
      'name','description','story','origin','unit','video','price','originalPrice','tags','features',
      'category','categoryId','weight','weightOptions','cutOptions','preOrderTime','pricePrefix','preOrder',
      'gallery','image','is_active'
    ) then
      raise exception 'unsupported_product_change_field:%',key_name using errcode='22023';
    end if;
  end loop;

  if p_payload ? 'name' and char_length(btrim(coalesce(p_payload->>'name',''))) not between 2 and 180 then raise exception 'invalid_product_name' using errcode='22023'; end if;
  if p_payload ? 'description' and char_length(btrim(coalesce(p_payload->>'description',''))) not between 20 and 20000 then raise exception 'invalid_product_description' using errcode='22023'; end if;
  if p_payload ? 'story' and char_length(btrim(coalesce(p_payload->>'story',''))) not between 20 and 20000 then raise exception 'invalid_product_story' using errcode='22023'; end if;
  if p_payload ? 'origin' and char_length(btrim(coalesce(p_payload->>'origin',''))) not between 2 and 500 then raise exception 'invalid_product_origin' using errcode='22023'; end if;
  if p_payload ? 'unit' and char_length(btrim(coalesce(p_payload->>'unit',''))) not between 1 and 80 then raise exception 'invalid_product_unit' using errcode='22023'; end if;
  if p_payload ? 'price' and (jsonb_typeof(p_payload->'price')<>'number' or (p_payload->>'price')::numeric<=0 or (p_payload->>'price')::numeric>1000000) then raise exception 'invalid_product_price' using errcode='22023'; end if;
  if p_payload ? 'originalPrice' and (jsonb_typeof(p_payload->'originalPrice')<>'number' or (p_payload->>'originalPrice')::numeric<0 or (p_payload->>'originalPrice')::numeric>1000000) then raise exception 'invalid_compare_price' using errcode='22023'; end if;
  if p_payload ? 'weight' and (jsonb_typeof(p_payload->'weight')<>'number' or (p_payload->>'weight')::numeric<=0 or (p_payload->>'weight')::numeric>1000) then raise exception 'invalid_product_weight' using errcode='22023'; end if;
  if p_payload ? 'preOrder' and jsonb_typeof(p_payload->'preOrder')<>'boolean' then raise exception 'invalid_preorder_flag' using errcode='22023'; end if;
  if p_payload ? 'is_active' and jsonb_typeof(p_payload->'is_active')<>'boolean' then raise exception 'invalid_product_active_flag' using errcode='22023'; end if;
  if p_payload ? 'tags' and (jsonb_typeof(p_payload->'tags')<>'array' or jsonb_array_length(p_payload->'tags')>30) then raise exception 'invalid_product_tags' using errcode='22023'; end if;
  if p_payload ? 'features' and (jsonb_typeof(p_payload->'features')<>'array' or jsonb_array_length(p_payload->'features')>40) then raise exception 'invalid_product_features' using errcode='22023'; end if;
  if p_payload ? 'weightOptions' and jsonb_typeof(p_payload->'weightOptions') not in ('array','object') then raise exception 'invalid_weight_options' using errcode='22023'; end if;
  if p_payload ? 'cutOptions' and jsonb_typeof(p_payload->'cutOptions') not in ('array','object') then raise exception 'invalid_cut_options' using errcode='22023'; end if;
  if p_payload ? 'category' or p_payload ? 'categoryId' then
    if private.resolve_category_id_v1(coalesce(nullif(p_payload->>'categoryId',''),p_payload->>'category')) is null then raise exception 'category_not_found' using errcode='P0002'; end if;
  end if;
  if p_payload ? 'video' and nullif(btrim(coalesce(p_payload->>'video','')),'') is not null and coalesce(p_payload->>'video','') !~* '^https://' then raise exception 'https_product_video_required' using errcode='22023'; end if;

  if p_payload ? 'image' and nullif(btrim(coalesce(p_payload->>'image','')),'') is not null then
    media_path:=btrim(p_payload->>'image');
    if split_part(media_path,'/',1)<>producer_row.id::text or not exists(select 1 from private.media_objects_all object where object.bucket_id='catalog-public' and object.name=media_path) then raise exception 'product_image_not_uploaded' using errcode='22023'; end if;
  end if;
  if p_payload ? 'gallery' then
    gallery:=p_payload->'gallery';
    if jsonb_typeof(gallery)<>'array' or jsonb_array_length(gallery)>10 then raise exception 'invalid_product_gallery' using errcode='22023'; end if;
    for media_path in select btrim(value) from jsonb_array_elements_text(gallery)
    loop
      if split_part(media_path,'/',1)<>producer_row.id::text or not exists(select 1 from private.media_objects_all object where object.bucket_id='catalog-public' and object.name=media_path) then raise exception 'product_gallery_image_not_uploaded' using errcode='22023'; end if;
    end loop;
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION private.validate_product_change_request_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform private.validate_product_change_payload_v1(new.product_id,new.producer_id,new.requested_by,new.proposed_payload);
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.validate_product_health_payload_v1(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
 info jsonb; safety jsonb; recipe jsonb; nutrition jsonb; warnings jsonb:='[]'::jsonb; warning jsonb; warning_text text; warning_severity text;
 result_info jsonb; result_safety jsonb; result_recipe jsonb; nutrition_out jsonb:='{}'::jsonb; key text; numeric_value numeric;
 summary_value text; allergen_note text; claim_policy text; recipe_title text; enabled boolean; integer_value integer; serving_size text;
begin
 if p_payload is null or jsonb_typeof(p_payload)<>'object' then raise exception 'invalid_product_health_payload' using errcode='22023'; end if;
 if char_length(p_payload::text)>80000 then raise exception 'product_health_payload_too_large' using errcode='22023'; end if;
 if lower(p_payload::text) ~ '(tedavi eder|doğal antibiyotik|mucize|kanseri? (önler|iyileştirir)|kolesterolü düşürür|kan şekerini dengeler|hastalıklara karşı zırh|hastalığı önler|hastalığı iyileştirir)' then raise exception 'unsupported_product_health_claim' using errcode='23514'; end if;
 summary_value:=btrim(coalesce(p_payload->>'summary',''));
 if char_length(summary_value)>2000 or summary_value~'[\u0000-\u001F\u007F]' then raise exception 'invalid_product_health_summary' using errcode='22023'; end if;
 info:=coalesce(p_payload->'productInfo','{}'::jsonb); safety:=coalesce(p_payload->'safety','{}'::jsonb); recipe:=coalesce(p_payload->'recipe','{}'::jsonb);
 if jsonb_typeof(info)<>'object' or jsonb_typeof(safety)<>'object' or jsonb_typeof(recipe)<>'object' then raise exception 'invalid_product_health_sections' using errcode='22023'; end if;
 nutrition:=coalesce(info->'nutrition','{}'::jsonb); if jsonb_typeof(nutrition)<>'object' then raise exception 'invalid_product_nutrition' using errcode='22023'; end if;
 serving_size:=btrim(coalesce(nutrition->>'servingSize','')); if char_length(serving_size)>120 or serving_size~'[\u0000-\u001F\u007F]' then raise exception 'invalid_product_serving_size' using errcode='22023'; end if;
 if serving_size<>'' then nutrition_out:=nutrition_out||jsonb_build_object('servingSize',serving_size); end if;
 foreach key in array array['energyKcal','proteinG','carbohydrateG','sugarsG','fatG','saturatedFatG','fiberG','saltG'] loop
   if nutrition ? key then
     if jsonb_typeof(nutrition->key)<>'number' then raise exception 'invalid_product_nutrition_value:%',key using errcode='22023'; end if;
     numeric_value:=(nutrition->>key)::numeric; if numeric_value<0 or numeric_value>1000000 then raise exception 'invalid_product_nutrition_value:%',key using errcode='22023'; end if;
     nutrition_out:=nutrition_out||jsonb_build_object(key,numeric_value);
   end if;
 end loop;
 result_info:=jsonb_build_object(
   'ingredients',private.product_health_text_array_v1(info->'ingredients','ingredients',60,240),
   'usageNotes',private.product_health_text_array_v1(info->'usageNotes','usageNotes',30,500),
   'nutrition',nutrition_out
 );
 if safety ? 'warnings' then
   if jsonb_typeof(safety->'warnings')<>'array' or jsonb_array_length(safety->'warnings')>20 then raise exception 'invalid_product_health_warnings' using errcode='22023'; end if;
   for warning in select value from jsonb_array_elements(safety->'warnings') loop
     if jsonb_typeof(warning)<>'object' then raise exception 'invalid_product_health_warning' using errcode='22023'; end if;
     warning_text:=btrim(coalesce(warning->>'text','')); warning_severity:=lower(btrim(coalesce(warning->>'severity','info')));
     if warning_text='' or char_length(warning_text)>1000 or warning_text~'[\u0000-\u001F\u007F]' or warning_severity not in('info','low','medium','high') then raise exception 'invalid_product_health_warning' using errcode='22023'; end if;
     warnings:=warnings||jsonb_build_array(jsonb_build_object('severity',warning_severity,'text',warning_text));
   end loop;
 end if;
 allergen_note:=btrim(coalesce(safety->>'allergenNote','')); claim_policy:=btrim(coalesce(safety->>'claimPolicy',''));
 if char_length(allergen_note)>1000 or char_length(claim_policy)>1000 or allergen_note~'[\u0000-\u001F\u007F]' or claim_policy~'[\u0000-\u001F\u007F]' then raise exception 'invalid_product_health_text' using errcode='22023'; end if;
 result_safety:=jsonb_build_object(
   'schemaVersion',2,
   'storage',jsonb_build_object('title','Saklama','items',private.product_health_text_array_v1(safety->'storage','storage',30,500)),
   'preparation',jsonb_build_object('title','Hazırlama / kullanım','items',private.product_health_text_array_v1(safety->'preparation','preparation',30,500)),
   'warnings',warnings,
   'allergens',jsonb_build_object('known',private.product_health_text_array_v1(safety->'allergens','allergens',30,160),'verifyLabel',true,'text',nullif(allergen_note,'')),
   'verificationNeeded',private.product_health_text_array_v1(safety->'verificationNeeded','verificationNeeded',30,500),
   'claimPolicy',nullif(claim_policy,'')
 );
 enabled:=case when recipe ? 'enabled' then (recipe->>'enabled')::boolean else false end;
 recipe_title:=btrim(coalesce(recipe->>'title','')); if char_length(recipe_title)>240 or recipe_title~'[\u0000-\u001F\u007F]' then raise exception 'invalid_product_recipe_title' using errcode='22023'; end if;
 result_recipe:=jsonb_build_object('enabled',enabled,'title',recipe_title,
   'ingredients',private.product_health_text_array_v1(recipe->'ingredients','recipeIngredients',60,300),
   'steps',private.product_health_text_array_v1(recipe->'steps','recipeSteps',40,1000));
 foreach key in array array['servings','prepMinutes','cookMinutes'] loop
   if recipe ? key then
     if jsonb_typeof(recipe->key)<>'number' or (recipe->>key)!~'^\d+$' then raise exception 'invalid_product_recipe_number:%',key using errcode='22023'; end if;
     integer_value:=(recipe->>key)::integer;
     if integer_value<0 or integer_value>10000 or (key='servings' and integer_value>1000) then raise exception 'invalid_product_recipe_number:%',key using errcode='22023'; end if;
     result_recipe:=result_recipe||jsonb_build_object(key,integer_value);
   end if;
 end loop;
 return jsonb_build_object('summary',summary_value,'productInfo',result_info,'safety',result_safety,'recipe',result_recipe);
exception when invalid_text_representation then raise exception 'invalid_product_health_payload' using errcode='22023';
end;$function$;

CREATE OR REPLACE FUNCTION private.validate_review_media_paths_v1(p_media_paths text[])
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid:=auth.uid(); path_value text; normalized text[]:='{}'::text[];
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if coalesce(array_length(p_media_paths,1),0)>5 then raise exception 'review_media_limit_exceeded' using errcode='22023'; end if;
  foreach path_value in array coalesce(p_media_paths,'{}'::text[])
  loop
    path_value:=btrim(coalesce(path_value,''));
    if char_length(path_value) not between 1 and 500 or split_part(path_value,'/',1)<>caller_id::text then raise exception 'invalid_review_media_path' using errcode='22023'; end if;
    if not exists(select 1 from storage.objects object where object.bucket_id='review-media' and object.name=path_value) then raise exception 'review_media_not_uploaded' using errcode='22023'; end if;
    normalized:=array_append(normalized,path_value);
  end loop;
  return normalized;
end;
$function$;

CREATE OR REPLACE FUNCTION private.verified_catalog_product_image_path_v1(p_path text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ select private.catalog_media_binary_verified_path_v2(p_path); $function$;

CREATE OR REPLACE FUNCTION private.verified_product_certificate_path_v1(p_path text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare normalized text:=btrim(coalesce(p_path,'')); mime text; size_bytes bigint;
begin
  if normalized='' or char_length(normalized)>1200 or normalized~*'^[a-z][a-z0-9+.-]*:' or normalized like '/%' then return null; end if;
  if exists(select 1 from unnest(string_to_array(normalized,'/')) part where part in ('','.','..')) then return null; end if;
  select lower(coalesce(o.metadata->>'mimetype','')),nullif(o.metadata->>'size','')::bigint into mime,size_bytes
  from storage.objects o where o.bucket_id='product-certificates' and o.name=normalized limit 1;
  if mime not in ('application/pdf','image/jpeg','image/png','image/webp') then return null; end if;
  if size_bytes is null or size_bytes<=0 or size_bytes>20971520 then return null; end if;
  return normalized;
exception when others then return null;
end;
$function$;

CREATE OR REPLACE FUNCTION private.verified_product_video_path_v1(p_path text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare normalized text := btrim(coalesce(p_path,''));
begin
  if normalized = '' or char_length(normalized) > 1200 or normalized ~* '^[a-z][a-z0-9+.-]*:' or normalized like '/%' then return null; end if;
  if exists (select 1 from unnest(string_to_array(normalized,'/')) part where part in ('','.','..')) then return null; end if;
  if exists (
    select 1 from private.media_cdn_objects m
    where m.bucket_id = 'catalog-public' and m.object_name = normalized and m.origin = 'direct' and m.confirmed
      and m.content_type in ('video/mp4','video/webm','video/quicktime') and m.byte_size between 1 and 52428800) then
    return normalized;
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION private.verified_public_storage_path_v1(p_bucket text, p_path text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  bucket_name text := btrim(coalesce(p_bucket,''));
  raw_path text := btrim(coalesce(p_path,''));
  normalized text;
begin
  if bucket_name not in ('catalog-public','content-public','event-public') then return null; end if;
  if raw_path = '' or raw_path ~ '[[:cntrl:]]' or raw_path ~ '^[a-zA-Z][a-zA-Z0-9+.-]*:' then return null; end if;
  normalized := regexp_replace(raw_path,'^/+','','g');
  if normalized = '' or normalized like '%../%' or normalized like '../%' or normalized like '%/..' or normalized like '%/./%' then return null; end if;
  if exists (select 1 from private.media_objects_all o where o.bucket_id = bucket_name and o.name = normalized and not o.is_delete_marker and o.archived_at is null) then
    return normalized;
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION private.withdraw_my_review_v1(p_review_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid:=auth.uid(); affected integer;
begin
  if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  update public.reviews set status='withdrawn',updated_at=timezone('utc',now()) where id=p_review_id and user_id=caller_id and status<>'withdrawn';
  get diagnostics affected=row_count;
  if affected=0 and not exists(select 1 from public.reviews where id=p_review_id and user_id=caller_id) then raise exception 'review_not_found' using errcode='P0002'; end if;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION private.write_admin_audit_v2(p_action text, p_target_type text, p_target_id text DEFAULT NULL::text, p_before jsonb DEFAULT NULL::jsonb, p_after jsonb DEFAULT NULL::jsonb, p_details jsonb DEFAULT '{}'::jsonb, p_correlation_id uuid DEFAULT NULL::uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare new_id bigint;
begin
  if char_length(btrim(coalesce(p_action,''))) not between 3 and 160 then raise exception 'invalid_audit_action' using errcode='22023'; end if;
  if char_length(btrim(coalesce(p_target_type,''))) not between 2 and 120 then raise exception 'invalid_audit_target_type' using errcode='22023'; end if;
  if p_target_id is not null and char_length(p_target_id)>300 then raise exception 'invalid_audit_target_id' using errcode='22023'; end if;
  if p_details is null or jsonb_typeof(p_details)<>'object' then raise exception 'invalid_audit_details' using errcode='22023'; end if;
  insert into private.admin_audit_logs(actor_user_id,action,target_type,target_id,details,correlation_id,before_state,after_state)
  values(auth.uid(),btrim(p_action),btrim(p_target_type),p_target_id,p_details,coalesce(p_correlation_id,gen_random_uuid()),p_before,p_after)
  returning id into new_id;
  return new_id;
end;
$function$;

