CREATE OR REPLACE FUNCTION public.store_hosted_payment_session_for_service_v2(p_intent_id uuid, p_token text, p_client_ip inet, p_provider_snapshot jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare intent private.payment_intents%rowtype; token_value text:=btrim(coalesce(p_token,'')); snapshot jsonb:=coalesce(p_provider_snapshot,'{}'::jsonb);
begin
 if auth.role()<>'service_role' then raise exception 'service_role_required' using errcode='42501'; end if;
 if p_intent_id is null or char_length(token_value) not between 8 and 500 or p_client_ip is null or jsonb_typeof(snapshot)<>'object' then raise exception 'invalid_hosted_payment_session' using errcode='22023'; end if;
 select * into intent from private.payment_intents where id=p_intent_id for update;
 if intent.id is null or intent.payment_flow<>'checkout_form' or intent.status not in ('processing','authorized') then raise exception 'payment_intent_not_hosted' using errcode='55000'; end if;
 update private.payment_intents set provider_session_token=token_value,provider_result=provider_result||snapshot,client_ip=p_client_ip,updated_at=timezone('utc',now()) where id=intent.id;
 return jsonb_build_object('ok',true,'intentId',intent.id,'subjectType',intent.subject_type,'subjectId',intent.subject_id);
end;$function$;

CREATE OR REPLACE FUNCTION public.store_verified_provider_payment_method_v1(p_user_id uuid, p_provider text, p_provider_customer_ref text, p_provider_payment_method_ref text, p_brand text, p_last4 text, p_exp_month smallint DEFAULT NULL::smallint, p_exp_year smallint DEFAULT NULL::smallint, p_billing_name text DEFAULT NULL::text, p_nickname text DEFAULT NULL::text, p_billing_country_code text DEFAULT NULL::text, p_billing_postal_code text DEFAULT NULL::text, p_make_default boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  normalized_provider text:=lower(btrim(coalesce(p_provider,'')));
  customer_ref text:=btrim(coalesce(p_provider_customer_ref,''));
  method_id uuid;
begin
  if auth.role()<>'service_role' then raise exception 'service_role_required' using errcode='42501'; end if;
  if p_user_id is null or normalized_provider !~ '^[a-z0-9_-]{2,40}$' then raise exception 'invalid_provider_payment_method_request' using errcode='22023'; end if;
  if char_length(customer_ref) not between 3 and 255 or customer_ref ~ '[[:cntrl:][:space:]]' then raise exception 'invalid_provider_customer_ref' using errcode='22023'; end if;
  if not exists(select 1 from public.profiles p where p.id=p_user_id and p.status='active' and p.deleted_at is null) then raise exception 'active_profile_required' using errcode='42501'; end if;

  insert into private.payment_provider_customers(user_id,provider,provider_customer_ref)
  values(p_user_id,normalized_provider,customer_ref)
  on conflict(user_id,provider) do update set provider_customer_ref=excluded.provider_customer_ref,updated_at=timezone('utc',now());

  method_id:=private.register_verified_payment_method_v2(
    p_user_id,normalized_provider,p_provider_payment_method_ref,p_brand,p_last4,p_exp_month,p_exp_year,p_billing_name,p_nickname,p_billing_country_code,p_billing_postal_code,p_make_default
  );
  return method_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.store_verified_provider_payment_method_v2(p_user_id uuid, p_provider text, p_provider_customer_ref text, p_provider_payment_method_ref text, p_brand text, p_last4 text, p_exp_month smallint DEFAULT NULL::smallint, p_exp_year smallint DEFAULT NULL::smallint, p_billing_name text DEFAULT NULL::text, p_nickname text DEFAULT NULL::text, p_billing_country_code text DEFAULT NULL::text, p_billing_postal_code text DEFAULT NULL::text, p_make_default boolean DEFAULT false, p_consent_version text DEFAULT NULL::text, p_consent_source text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare method_id uuid; consent_version text:=btrim(coalesce(p_consent_version,'')); consent_source text:=btrim(coalesce(p_consent_source,''));
begin
  if auth.role()<>'service_role' then raise exception 'service_role_required' using errcode='42501'; end if;
  if char_length(consent_version) not between 3 and 80 or consent_version ~ '[[:cntrl:]]' then raise exception 'card_storage_consent_required' using errcode='22023'; end if;
  if char_length(consent_source) not between 3 and 80 or consent_source ~ '[[:cntrl:]]' then raise exception 'card_storage_consent_source_required' using errcode='22023'; end if;
  method_id:=public.store_verified_provider_payment_method_v1(p_user_id,p_provider,p_provider_customer_ref,p_provider_payment_method_ref,p_brand,p_last4,p_exp_month,p_exp_year,p_billing_name,p_nickname,p_billing_country_code,p_billing_postal_code,p_make_default);
  update private.customer_payment_methods set storage_consent_version=consent_version,storage_consented_at=timezone('utc',now()),storage_consent_source=consent_source,updated_at=timezone('utc',now()) where id=method_id and user_id=p_user_id;
  if not found then raise exception 'payment_method_store_failed' using errcode='55000'; end if;
  return method_id;
end;$function$;

