alter table public.campaigns add constraint campaigns_check CHECK ((ends_at > starts_at));
alter table public.campaigns add constraint campaigns_check1 CHECK ((((discount_type = 'percentage'::text) AND ((discount_value >= 1) AND (discount_value <= 10000))) OR ((discount_type = 'fixed'::text) AND (discount_value > 0) AND (currency IS NOT NULL)) OR ((discount_type = 'free_shipping'::text) AND (discount_value = 0))));
alter table public.campaigns add constraint campaigns_currency_check CHECK (((currency IS NULL) OR (currency ~ '^[A-Z]{3}$'::text)));
