alter table public.campaigns add constraint campaigns_discount_value_check CHECK ((discount_value >= 0));
alter table public.campaigns add constraint campaigns_max_discount_minor_check CHECK (((max_discount_minor IS NULL) OR (max_discount_minor > 0)));
alter table public.campaigns add constraint campaigns_minimum_order_minor_check CHECK ((minimum_order_minor >= 0));
alter table public.campaigns add constraint campaigns_per_user_limit_check CHECK ((per_user_limit > 0));
alter table public.campaigns add constraint campaigns_priority_check CHECK (((priority >= '-1000'::integer) AND (priority <= 1000)));
alter table public.campaigns add constraint campaigns_slug_check CHECK ((slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'::text));
alter table public.campaigns add constraint campaigns_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'scheduled'::text, 'active'::text, 'paused'::text, 'ended'::text])));
alter table public.campaigns add constraint campaigns_target_scope_check CHECK ((target_scope = ANY (ARRAY['all'::text, 'products'::text, 'categories'::text])));
alter table public.campaigns add constraint campaigns_translations_check CHECK ((jsonb_typeof(translations) = 'object'::text));
alter table public.campaigns add constraint campaigns_usage_limit_check CHECK (((usage_limit IS NULL) OR (usage_limit > 0)));
alter table public.cart_items add constraint cart_items_quantity_check CHECK (((quantity >= 1) AND (quantity <= 99)));
