-- Views
create view public.catalog_product_cards with (security_invoker=true) as
SELECT product.id,
    product.slug,
    product.name,
    product.short_description,
    product.unit_label,
    product.base_price_minor,
    product.compare_at_price_minor,
    product.currency,
    product.tags,
    product.is_featured,
    product.published_at,
    product.category_id,
    category.slug AS category_slug,
    category.name AS category_name,
    product.producer_id,
    producer.slug AS producer_slug,
    producer.display_name AS producer_name,
    producer.is_verified AS producer_is_verified,
    primary_image.storage_path AS primary_image_path,
    primary_image.alt_text AS primary_image_alt
   FROM (((products product
     JOIN categories category ON ((category.id = product.category_id)))
     JOIN producers producer ON ((producer.id = product.producer_id)))
     LEFT JOIN LATERAL ( SELECT image.storage_path,
            image.alt_text
           FROM product_images image
          WHERE (image.product_id = product.id)
          ORDER BY image.is_primary DESC, image.sort_order, image.created_at
         LIMIT 1) primary_image ON (true))
  WHERE ((product.status = 'published'::text) AND (product.is_active = true) AND (product.deleted_at IS NULL) AND (category.is_active = true) AND (producer.status = 'active'::text) AND (producer.is_verified = true) AND (producer.deleted_at IS NULL));
create view private.media_objects_all as
SELECT o.id,
    o.bucket_id,
    o.name,
    o.owner,
    o.owner_id,
    o.metadata,
    o.version,
    o.created_at,
    o.updated_at,
    o.last_accessed_at,
    COALESCE(o.is_delete_marker, false) AS is_delete_marker,
    o.archived_at,
    'supabase'::text AS store
   FROM storage.objects o
  WHERE (NOT (EXISTS ( SELECT 1
           FROM private.media_cdn_objects m
          WHERE ((m.origin = 'direct'::text) AND m.confirmed AND (m.bucket_id = o.bucket_id) AND (m.object_name = o.name)))))
UNION ALL
 SELECT m.id,
    m.bucket_id,
    m.object_name AS name,
    m.owner_user_id AS owner,
    (m.owner_user_id)::text AS owner_id,
    jsonb_build_object('mimetype', m.content_type, 'size', m.byte_size, 'eTag', COALESCE(m.sha256, m.source_etag), 'cacheControl', 'max-age=31536000') AS metadata,
    NULL::text AS version,
    m.reserved_at AS created_at,
    COALESCE(m.mirrored_at, m.reserved_at) AS updated_at,
    NULL::timestamp with time zone AS last_accessed_at,
    false AS is_delete_marker,
    NULL::timestamp with time zone AS archived_at,
    'r2'::text AS store
   FROM private.media_cdn_objects m
  WHERE ((m.origin = 'direct'::text) AND m.confirmed);

