create policy products_authenticated_read on public.products as permissive for select to authenticated using ((((status = 'published'::text) AND (is_active = true) AND (deleted_at IS NULL) AND (EXISTS ( SELECT 1
   FROM producers producer
  WHERE ((producer.id = products.producer_id) AND (producer.status = 'active'::text) AND (producer.is_verified = true) AND (producer.deleted_at IS NULL))))) OR (EXISTS ( SELECT 1
   FROM producers producer
  WHERE ((producer.id = products.producer_id) AND (producer.owner_user_id = ( SELECT auth.uid() AS uid))))) OR ( SELECT private.is_admin() AS is_admin)));
create policy products_public_read on public.products as permissive for select to anon using (((status = 'published'::text) AND (is_active = true) AND (deleted_at IS NULL) AND (EXISTS ( SELECT 1
   FROM producers producer
  WHERE ((producer.id = products.producer_id) AND (producer.status = 'active'::text) AND (producer.is_verified = true) AND (producer.deleted_at IS NULL))))));
alter table public.profiles enable row level security;
alter table public.profiles force row level security;
create policy profiles_authenticated_read on public.profiles as permissive for select to authenticated using (((id = ( SELECT auth.uid() AS uid)) OR ( SELECT private.is_admin() AS is_admin)));
create policy profiles_update_own on public.profiles as permissive for update to authenticated using (((id = ( SELECT auth.uid() AS uid)) AND (status = 'active'::text) AND (deleted_at IS NULL))) with check (((id = ( SELECT auth.uid() AS uid)) AND (status = 'active'::text) AND (deleted_at IS NULL)));
alter table public.refunds enable row level security;
alter table public.refunds force row level security;
create policy refunds_authenticated_read on public.refunds as permissive for select to authenticated using (((EXISTS ( SELECT 1
   FROM orders customer_order
  WHERE ((customer_order.id = refunds.order_id) AND (customer_order.user_id = ( SELECT auth.uid() AS uid))))) OR ( SELECT private.is_admin() AS is_admin)));
alter table public.return_items enable row level security;
alter table public.return_items force row level security;
create policy return_items_read_own on public.return_items as permissive for select to authenticated using ((EXISTS ( SELECT 1
   FROM return_requests customer_return
  WHERE ((customer_return.id = return_items.return_id) AND (customer_return.user_id = ( SELECT auth.uid() AS uid))))));
alter table public.return_requests enable row level security;
alter table public.return_requests force row level security;
create policy return_requests_read_own on public.return_requests as permissive for select to authenticated using ((user_id = ( SELECT auth.uid() AS uid)));
alter table public.reviews enable row level security;
alter table public.reviews force row level security;
create policy reviews_authenticated_read on public.reviews as permissive for select to authenticated using (((status = 'published'::text) OR (user_id = ( SELECT auth.uid() AS uid)) OR ( SELECT private.is_admin() AS is_admin)));
create policy reviews_authenticated_update on public.reviews as permissive for update to authenticated using ((((user_id = ( SELECT auth.uid() AS uid)) AND (status = 'pending'::text)) OR ( SELECT private.is_admin() AS is_admin))) with check ((((user_id = ( SELECT auth.uid() AS uid)) AND (status = 'pending'::text)) OR ( SELECT private.is_admin() AS is_admin)));
create policy reviews_insert_verified_purchase on public.reviews as permissive for insert to authenticated with check (((user_id = ( SELECT auth.uid() AS uid)) AND (status = 'pending'::text) AND (is_verified_purchase = true) AND (EXISTS ( SELECT 1
   FROM (order_items purchased_item
     JOIN orders customer_order ON ((customer_order.id = purchased_item.order_id)))
  WHERE ((purchased_item.id = reviews.order_item_id) AND (purchased_item.product_id = reviews.product_id) AND (customer_order.user_id = ( SELECT auth.uid() AS uid)) AND (customer_order.status = ANY (ARRAY['delivered'::text, 'completed'::text])))))));
create policy reviews_public_read on public.reviews as permissive for select to anon using ((status = 'published'::text));
alter table public.shipment_items enable row level security;
alter table public.shipment_items force row level security;
create policy shipment_items_read_own on public.shipment_items as permissive for select to authenticated using ((EXISTS ( SELECT 1
   FROM (shipments shipment
     JOIN orders customer_order ON ((customer_order.id = shipment.order_id)))
  WHERE ((shipment.id = shipment_items.shipment_id) AND (customer_order.user_id = ( SELECT auth.uid() AS uid))))));
alter table public.shipments enable row level security;
alter table public.shipments force row level security;
create policy shipments_read_own on public.shipments as permissive for select to authenticated using ((EXISTS ( SELECT 1
   FROM orders customer_order
  WHERE ((customer_order.id = shipments.order_id) AND (customer_order.user_id = ( SELECT auth.uid() AS uid))))));
alter table public.shipping_zone_countries enable row level security;
create policy shipping_zone_countries_public_read on public.shipping_zone_countries as permissive for select to anon, authenticated using ((EXISTS ( SELECT 1
   FROM shipping_zones zone
  WHERE ((zone.id = shipping_zone_countries.zone_id) AND (zone.is_active = true)))));
alter table public.shipping_zones enable row level security;
create policy shipping_zones_public_read on public.shipping_zones as permissive for select to anon, authenticated using ((is_active = true));
