-- Default privileges
alter default privileges for role postgres in schema public revoke all on tables from public, anon, authenticated, service_role;
alter default privileges for role postgres in schema public grant truncate, references, trigger on tables to anon;
alter default privileges for role postgres in schema public grant truncate, references, trigger on tables to authenticated;
alter default privileges for role postgres in schema public grant truncate, references, trigger on tables to service_role;
alter default privileges for role postgres in schema public revoke all on sequences from public, anon, authenticated, service_role;
alter default privileges for role postgres in schema public grant update on sequences to anon;
alter default privileges for role postgres in schema public grant update on sequences to authenticated;
alter default privileges for role postgres in schema public grant update on sequences to service_role;
alter default privileges for role postgres in schema public revoke all on functions from public, anon, authenticated, service_role;

-- Event triggers
create event trigger auto_enable_rls_on_new_private_tables on ddl_command_end when tag in ('CREATE TABLE') execute function private.auto_enable_rls_on_new_tables_v1();

-- Comments
comment on column public.product_variants.weight_grams is 'Packaged gross shipping weight in grams, not product net weight.';
comment on column public.product_variants.shipping_weight_source is 'Provenance of packaged gross shipping weight: unknown, estimated, measured, or supplier.';
comment on column public.product_variants.shipping_weight_note is 'Human-readable source or estimation note for the packaged shipping weight.';
comment on column public.product_variants.shipping_weight_verified_at is 'Timestamp of physical/supplier verification; null for estimates.';
comment on column private.payment_intents.payment_method_id is 'Optional for provider-hosted checkout. Required only for saved_card channel.';
comment on table private.store_follow_simulation_allocations is 'Internal QA/load-test follower simulation only. Never included in public producer follower counts or customer-facing social proof.';
comment on function admin_broadcast_notification_v1(text,uuid,text,text,text,text) is 'Admin-only in-app notification broadcast. Push delivery is queued automatically per recipient preferences and registered device tokens.';
comment on function admin_get_brand_configuration_v1() is 'Admin snapshot of Golden Oremar brand and public storefront configuration.';
comment on function admin_list_categories_v1() is 'Admin-only category directory including inactive categories and total/published product counts.';
comment on function admin_list_content_v1() is 'Admin editorial content directory backed by content_entries.';
comment on function admin_list_events_v1() is 'Admin-only event and reservation directory with capacity utilization metrics.';
comment on function admin_list_inventory_v1() is 'Admin-only inventory directory. Inventory mutation remains producer-owned to preserve stock accountability.';
comment on function admin_list_returns_v1() is 'Admin-only return directory with order, customer, requested amount and successful refund aggregates.';
comment on function get_my_producer_dashboard_v2() is 'Authenticated producer dashboard with real follower, customer and producer-specific order metrics.';
comment on function private.admin_list_producers_v1() is 'Admin producer directory with verified identity, verified origin, structured village location, commerce and follower metrics.';
comment on function private.enforce_content_claim_policy() is 'Blocks unreviewed medical and health promises from public guide and product information content.';
comment on function private.enforce_product_claim_policy() is 'Blocks unreviewed medical, health, laboratory and certification promises from the public product catalog.';
comment on function private.has_role(text) is 'RLS-safe role predicate. SECURITY DEFINER prevents recursive public.profiles RLS evaluation while still binding identity to auth.uid().';
comment on function private.product_certificate_document_path_in_use_v1(text) is 'RLS-safe private boundary for determining whether a product certificate Storage object is still referenced.';
comment on function private.product_media_integrity_ok_v1(uuid) is 'Official-store products may temporarily publish with no product image and use the truthful Golden Oremar brand fallback. If any media is attached, or for non-official producers, the canonical verified media integrity contract remains mandatory.';
comment on function private.validate_payment_control_v1(jsonb) is 'Validates iyzico controls for in-app checkout. Customer-facing return URLs are not part of the runtime contract; provider callback handling is server-side.';
comment on function remove_my_payment_method_v1(uuid) is 'Retired for direct customer execution. Payment method removal must go through payment-method-vault so provider deletion succeeds before local revocation.';
